/**
 * اختبارات End-to-End لأداة brain-storm-ai
 * يختبر التدفق الكامل من منظور المستخدم النهائي
 */

import { test, expect } from "@playwright/test";

test.describe("E2E: brain-storm-ai — تدفق تشغيلي كامل", () => {
  test.setTimeout(60000); // 60 ثانية للاختبارات الطويلة

  test.beforeEach(async ({ page }) => {
    // تنظيف localStorage قبل كل اختبار
    await page.addInitScript(() => {
      localStorage.clear();
    });

    // الذهاب إلى الصفحة
    await page.goto("/brain-storm-ai");
  });

  test("يجتاز تدفق عصف ذهني كامل من البداية إلى النهاية", async ({ page }) => {
    // انتظار تحميل الصفحة
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    // إدخال فكرة إبداعية
    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await expect(briefInput).toBeVisible();
    await briefInput.fill(
      "فكرة لتطبيق تعليمي تفاعلي باستخدام الذكاء الاصطناعي لمساعدة الطلاب في التعلم"
    );

    // بدء الجلسة
    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await expect(startButton).toBeVisible();
    await startButton.click();

    // انتظار بدء المعالجة
    await expect(page.locator("text=جاري المعالجة")).toBeVisible({
      timeout: 10000,
    });

    // انتظار ظهور شريط التقدم
    await expect(page.locator("text=التقدم الكلي")).toBeVisible({
      timeout: 15000,
    });

    // مراقبة تطور التقدم عبر المراحل
    let previousProgress = 0;
    for (let attempt = 0; attempt < 10; attempt++) {
      const progressText = await page
        .locator("text=/\\d+\\.\\d+%/")
        .textContent();
      if (progressText) {
        const currentProgress = parseFloat(progressText.replace("%", ""));
        console.log(`التقدم الحالي: ${currentProgress}%`);

        // التأكد من أن التقدم يتزايد أو يظل كما هو (ليس يتناقص)
        expect(currentProgress).toBeGreaterThanOrEqual(previousProgress);
        previousProgress = currentProgress;

        // إذا وصل إلى 100% أو اكتملت الجلسة، نخرج
        if (currentProgress >= 100) {
          break;
        }
      }

      // انتظار قليل قبل التحقق التالي
      await page.waitForTimeout(2000);
    }

    // انتظار ظهور النتيجة النهائية
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible({
      timeout: 30000,
    });

    // التحقق من وجود القرار النهائي
    await expect(page.locator("text=القرار النهائي:")).toBeVisible();

    // التحقق من وجود أزرار التصدير
    await expect(page.locator('button:has-text("JSON")')).toBeVisible();
    await expect(page.locator('button:has-text("Markdown")')).toBeVisible();
    await expect(page.locator('button:has-text("نسخ")')).toBeVisible();

    // التقاط screenshot للتوثيق
    await page.screenshot({
      path: `test-results/brainstorm-complete-${Date.now()}.png`,
      fullPage: true,
    });
  });

  test("يحفظ الجلسة ويسترجعها بعد إعادة التحميل", async ({ page }) => {
    // إنشاء جلسة وانتظار اكتمالها جزئياً
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار الحفظ والاسترجاع");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار بدء المعالجة
    await expect(page.locator("text=جاري المعالجة")).toBeVisible();

    // انتظار حفظ الجلسة (سيحدث تلقائياً)
    await page.waitForTimeout(3000);

    // إعادة تحميل الصفحة
    await page.reload();

    // انتظار إعادة التحميل
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    // التحقق من وجود الجلسة المحفوظة
    await expect(
      page.locator("text=فكرة لاختبار الحفظ والاسترجاع")
    ).toBeVisible();
  });

  test("يصدر الجلسة بتنسيقات مختلفة", async ({ page }) => {
    // انتظار تحميل وإنشاء جلسة مكتملة
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار التصدير");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار اكتمال الجلسة
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible({
      timeout: 45000,
    });

    // تجربة تصدير JSON
    const jsonButton = page.locator('button:has-text("JSON")');
    await expect(jsonButton).toBeVisible();

    // مراقبة التحميلات (سنحتاج إلى التعامل مع dialog التحميل)
    const downloadPromise = page.waitForEvent("download");
    await jsonButton.click();

    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/brainstorm_.*\.json/);

    // تجربة تصدير Markdown
    const mdButton = page.locator('button:has-text("Markdown")');
    const mdDownloadPromise = page.waitForEvent("download");
    await mdButton.click();

    const mdDownload = await mdDownloadPromise;
    expect(mdDownload.suggestedFilename()).toMatch(/brainstorm_.*\.md/);

    // تجربة النسخ للحافظة
    const copyButton = page.locator('button:has-text("نسخ")');
    await copyButton.click();

    // التحقق من ظهور تأكيد النسخ
    await expect(page.locator('button:has-text("تم النسخ!")')).toBeVisible();
  });

  test("يتعامل مع حالات الفشل بشكل صحيح", async ({ page }) => {
    // محاكاة فشل الشبكة أو API
    await page.route("**/api/brainstorm", (route) => route.abort());

    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة ستفشل بسبب مشكلة فنية");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار ظهور رسالة الخطأ
    await expect(page.locator("text=فشل في الاتصال")).toBeVisible({
      timeout: 10000,
    });

    // التأكد من عدم تجمد الواجهة
    await expect(startButton).toBeEnabled();

    // التقاط screenshot للخطأ
    await page.screenshot({
      path: `test-results/brainstorm-error-${Date.now()}.png`,
      fullPage: true,
    });
  });

  test("يعرض المراحل والتقدم بوضوح", async ({ page }) => {
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار عرض المراحل");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار ظهور لوحة المراحل
    await expect(page.locator("text=التحليل الأولي")).toBeVisible({
      timeout: 10000,
    });

    // التحقق من وجود جميع المراحل
    await expect(page.locator("text=التحليل الأولي")).toBeVisible();
    await expect(page.locator("text=التوسع الإبداعي")).toBeVisible();
    await expect(page.locator("text=التحقق والتدقيق")).toBeVisible();
    await expect(page.locator("text=النقاش والتوافق")).toBeVisible();
    await expect(page.locator("text=التقييم النهائي")).toBeVisible();

    // التحقق من وجود شريط التقدم الكلي
    await expect(page.locator("text=التقدم الكلي")).toBeVisible();

    // التقاط screenshot للمراحل
    await page.screenshot({
      path: `test-results/brainstorm-phases-${Date.now()}.png`,
      fullPage: true,
    });
  });

  test("يحافظ على الاتساق بعد إعادة التحميل في جلسة مكتملة", async ({
    page,
  }) => {
    // إنشاء جلسة كاملة
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار الاتساق بعد إعادة التحميل");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار اكتمال الجلسة
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible({
      timeout: 45000,
    });

    // التحقق من وجود النتيجة النهائية
    await expect(page.locator("text=القرار النهائي:")).toBeVisible();

    // إعادة تحميل الصفحة
    await page.reload();

    // التأكد من الاحتفاظ بالنتيجة
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible();
    await expect(page.locator("text=القرار النهائي:")).toBeVisible();

    // التقاط screenshot للتحقق من الاتساق
    await page.screenshot({
      path: `test-results/brainstorm-consistency-${Date.now()}.png`,
      fullPage: true,
    });
  });
});

/**
 * @fileoverview سيناريو E2E متكامل لصفحة الاستوديو السينماتوغرافي.
 *
 * يثبت المسار البشري الفعلي:
 *   1. فتح /cinematography-studio على خادم dev الحي.
 *   2. التحقق من ظهور قوالب العدسات.
 *   3. اختيار قالب عدسة + تأكيد التحديث البصري.
 *   4. تحريك منزلق واحد على الأقل + تأكيد القيمة الجديدة في DOM.
 *   5. كتابة سؤال للمساعد مع mock للـ endpoint عبر page.route() — التحقق من loading ثم answer.
 *   6. إعادة تحميل الصفحة + التحقق من استرجاع الحالة من localStorage.
 *   7. لقطة شاشة نهائية في e2e/__screenshots__/.
 */

import { expect, test } from "@playwright/test";

const PAGE_PATH = "/cinematography-studio";
const SESSION_STORAGE_KEY = "cinematography-studio.session.v1";
const ASSISTANT_ANSWER = "اقتراح المساعد: استخدم عدسة 50mm بفتحة f/1.8 لعزل الموضوع.";

test.describe("cinematography studio — live dev scenario", () => {
  test.describe.configure({ mode: "serial" });

  test("يفتح الصفحة، يختار عدسة، يحرّك منزلقًا، يسأل المساعد، ثم يستعيد الحالة بعد إعادة التحميل", async ({
    page,
  }, testInfo) => {
    // mock endpoint المساعد + endpoint رمز الحماية.
    // المساعد يستدعي /api/ai/chat مع requireCsrf:true الذي يحضر cookie من /api/health.
    await page.route("**/api/health", async (route) => {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        headers: {
          "set-cookie": "XSRF-TOKEN=playwright-token; Path=/",
        },
        body: JSON.stringify({ ok: true }),
      });
    });
    await page.route("**/api/ai/chat", async (route) => {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({
          success: true,
          data: { response: ASSISTANT_ANSWER },
        }),
      });
    });

    // ضع cookie الحماية يدويًا قبل أي تفاعل لتفادي الاعتماد على set-cookie المحاكى
    await page.context().addCookies([
      {
        name: "XSRF-TOKEN",
        value: "playwright-token",
        url: "http://localhost:5000",
      },
    ]);

    // 1) فتح الصفحة — نص الترويسة الفعلي على الصفحة هو "Vision CineAI"
    await page.goto(PAGE_PATH, { waitUntil: "domcontentloaded" });
    await expect(page.getByText("Vision CineAI").first()).toBeVisible({
      timeout: 45_000,
    });

    // الانتقال لأداة Lens Simulator لإظهار القوالب — نبحث عبر اسم القسم العربي
    const lensCard = page.getByText(/محاكي العدسة|Lens Simulator/).first();
    await lensCard.scrollIntoViewIfNeeded().catch(() => undefined);
    await lensCard.click({ timeout: 10_000 }).catch(() => undefined);

    // 2) قوالب العدسات تظهر
    await expect(page.getByText(/Cooke|كوك/).first()).toBeVisible({
      timeout: 20_000,
    });

    // 3) اختيار قالب عدسة (Cooke S4) + تأكيد التحديث
    const cookeCard = page
      .getByRole("button", { pressed: false })
      .filter({ hasText: /كوك|Cooke/ })
      .first();
    await cookeCard.click();
    await expect(
      page
        .getByRole("button", { pressed: true })
        .filter({ hasText: /كوك|Cooke/ })
    ).toBeVisible();

    // 4) تحريك منزلق — Manual Calibration: اضغط "تحرير يدوي" أولًا لرفع القفل
    const unlockButton = page.getByRole("button", { name: /تحرير يدوي/ });
    if ((await unlockButton.count()) > 0) {
      await unlockButton.click();
    }

    const focalSlider = page
      .getByRole("slider")
      .filter({ has: page.locator(":scope") })
      .first();
    await focalSlider.focus();
    const initialAriaValue = await focalSlider.getAttribute("aria-valuenow");
    // تحريك بسحب لوحة المفاتيح (arrow keys) — يتطابق مع المسار الداخلي للسحب
    await focalSlider.press("ArrowRight");
    await focalSlider.press("ArrowRight");
    await focalSlider.press("ArrowRight");
    const newAriaValue = await focalSlider.getAttribute("aria-valuenow");
    expect(newAriaValue).not.toBe(initialAriaValue);

    // 5) المساعد — افتح أداة "محلل اللقطة" (التي تحوي ProductionTools وحقل المساعد).
    // لإغلاق أداة محاكي العدسة المفتوحة حاليًا، نضغط زر العودة/الرئيسية إن وُجد،
    // ثم ننقر على بطاقة محلل اللقطة.
    const closeToolButton = page.getByRole("button", { name: /العودة|إغلاق|×/ });
    if ((await closeToolButton.count()) > 0) {
      await closeToolButton
        .first()
        .click({ timeout: 3_000 })
        .catch(() => undefined);
    }
    const shotAnalyzerCard = page
      .getByText(/محلل اللقطة/, { exact: false })
      .first();
    await shotAnalyzerCard.scrollIntoViewIfNeeded().catch(() => undefined);
    await shotAnalyzerCard.click({ timeout: 10_000 });

    // اكتب السؤال
    const assistantInput = page.getByLabel("سؤال المساعد الذكي للتصوير");
    await assistantInput.waitFor({ state: "visible", timeout: 15_000 });
    await assistantInput.fill("ما العدسة المثالية للوجه؟");

    const submitButton = page.getByTestId("cine-assistant-submit");
    await submitButton.click();

    // التحقق من ظهور الإجابة داخل اللوحة (mock يرد فورًا تقريبًا)
    await expect(page.getByTestId("cine-assistant-answer")).toBeVisible({
      timeout: 10_000,
    });
    await expect(page.getByTestId("cine-assistant-answer")).toContainText(
      ASSISTANT_ANSWER
    );

    // 6) إعادة التحميل + التحقق من الحالة المحفوظة
    const sessionBefore = await page.evaluate((key) => {
      return window.localStorage.getItem(key);
    }, SESSION_STORAGE_KEY);
    expect(sessionBefore).not.toBeNull();
    expect(sessionBefore!.length).toBeGreaterThan(0);

    await page.reload({ waitUntil: "domcontentloaded" });
    const sessionAfter = await page.evaluate((key) => {
      return window.localStorage.getItem(key);
    }, SESSION_STORAGE_KEY);
    expect(sessionAfter).not.toBeNull();
    // الحالة تبقى مخزنة بنفس المفتاح بعد إعادة التحميل.
    const beforeParsed = JSON.parse(sessionBefore!);
    const afterParsed = JSON.parse(sessionAfter!);
    // تأكيد بقاء الحقول الجوهرية (المرحلة، المزاج، آخر إجابة)
    if (beforeParsed.lastAssistant?.answer) {
      expect(afterParsed.lastAssistant?.answer).toBe(
        beforeParsed.lastAssistant.answer
      );
    }

    // 7) لقطة الشاشة النهائية المرجعية
    await page.screenshot({
      path: testInfo.outputPath("cinematography-studio-final.png"),
      fullPage: true,
    });
  });
});

import "@testing-library/jest-dom/vitest";

import { vi } from "vitest";

// Mock Next.js router
vi.mock("next/navigation", () => ({
  useRouter: () => ({
    push: vi.fn(),
    replace: vi.fn(),
    prefetch: vi.fn(),
    back: vi.fn(),
    forward: vi.fn(),
    refresh: vi.fn(),
  }),
  useSearchParams: () => new URLSearchParams(),
  usePathname: () => "/",
}));

// Mock environment variables
if (process.env["NODE_ENV"] !== "test") {
  Object.defineProperty(process.env, "NODE_ENV", {
    value: "test",
    configurable: true,
    writable: true,
  });
}

import path from "path";
import bundleAnalyzer from "@next/bundle-analyzer";
import { withSentryConfig } from "@sentry/nextjs";

const isWindowsHost = process.platform === "win32";
const enableStandaloneOutput =
  process.env["NEXT_OUTPUT_MODE"] === "standalone" || !isWindowsHost;

const parsePositiveInt = (value: string | undefined): number | undefined => {
  if (!value) return undefined;
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : undefined;
