/**
 * @fileoverview سويت تكامل تحقق سحب المنزلقات في صفحة الاستوديو السينماتوغرافي.
 *
 * تختبر هذه السويت العقد الفعلي لمكوّن `SliderNumberInput` كمكوّن متحكَّم
 * (controlled component) وفق الإعدادات الحقيقية المُستخدَمة في:
 *   - LensSimulatorTool (focalLength 14..200, aperture 1.4..22, distortion 0..20)
 *   - DOFCalculatorTool (distance 0.3..50)
 *   - ColorGradingPreviewTool (temperature -100..100, contrast 50..200, ...)
 *
 * ممنوع الاكتفاء بـ `fireEvent.change` لقيمة واحدة. كل اختبار يثبت تسلسلًا
 * منطقيًا من القيم وحدودًا فعلية على [min, max].
 *
 * ملاحظة: `userEvent.setup()` يفشل تحت jsdom محلي بسبب صراع document.
 * نستعمل `fireEvent` مع تتابع متعدد + `keyDown` مباشرة على عنصر الـ slider
 * — وهذا هو نفس المسار الداخلي الذي يسلكه السحب الحقيقي حين يُترجم Radix
 * pointer events إلى تحديثات قيمة عبر `onValueChange`.
 *
 * تُصدَّر `runSliderDragSuite` ليستهلكها `run-integration-tests.ts` ضمن المنظومة الواحدة.
 */

import assert from "node:assert/strict";
// @ts-expect-error — jsdom يُحمَّل بنفس الأسلوب المتبع في باقي السويتات
import { JSDOM } from "jsdom";
import * as React from "react";
import { act, cleanup, fireEvent, render } from "@testing-library/react";

interface SliderConfig {
  readonly label: string;
  readonly min: number;
  readonly max: number;
  readonly step: number;
  readonly initial: number;
  readonly formatValue?: (value: number) => string;
}

const REAL_SLIDER_CONFIGS: ReadonlyArray<SliderConfig> = [
  // LensSimulatorTool
  { label: "البعد البؤري", min: 14, max: 200, step: 1, initial: 50 },
  {
    label: "فتحة العدسة",
    min: 1.4,
    max: 22,
    step: 0.1,
    initial: 2.8,
    formatValue: (value) => value.toFixed(1),
  },
  { label: "التشوه", min: 0, max: 20, step: 1, initial: 0 },
  // DOFCalculatorTool
  {
    label: "مسافة الهدف",
    min: 0.3,
    max: 50,
    step: 0.1,
    initial: 5,
    formatValue: (value) => value.toFixed(1),
  },
  // ColorGradingPreviewTool — تشمل قيمًا سالبة
  { label: "حرارة اللون", min: -100, max: 100, step: 1, initial: 0 },
  { label: "التباين", min: 50, max: 200, step: 1, initial: 100 },
  { label: "التشبّع", min: 0, max: 200, step: 1, initial: 100 },
  { label: "الإضاءة", min: -100, max: 100, step: 1, initial: 0 },
  { label: "الظلال", min: -100, max: 100, step: 1, initial: 0 },
];

/**
 * يثبّت بيئة DOM مع polyfills الضرورية لـ Radix Slider.
 *
 * Radix يحتاج: setPointerCapture, getBoundingClientRect حقيقي, ResizeObserver.
 */
function installDomForSliders(): () => void {
  const dom = new JSDOM("<!doctype html><html><body></body></html>", {
    url: "http://localhost/",
    pretendToBeVisual: true,
  });

  const previousWindow = (globalThis as { window?: Window }).window;
  const previousDocument = (globalThis as { document?: Document }).document;
  const previousNavigator = (globalThis as { navigator?: Navigator }).navigator;
  const previousResizeObserver = (
    globalThis as { ResizeObserver?: unknown }
  ).ResizeObserver;

  Object.defineProperty(globalThis, "window", {
    configurable: true,
    writable: true,
    value: dom.window,
  });
  Object.defineProperty(globalThis, "document", {
    configurable: true,
    writable: true,
    value: dom.window.document,
  });
  Object.defineProperty(globalThis, "navigator", {
    configurable: true,
    writable: true,
    value: dom.window.navigator,
  });

  // polyfills حرجة لـ Radix Slider:
  const HTMLElementProto = dom.window.HTMLElement.prototype as unknown as {
    hasPointerCapture: () => boolean;
    setPointerCapture: () => void;
    releasePointerCapture: () => void;
    getBoundingClientRect: () => DOMRect;
    scrollIntoView: () => void;
  };
  HTMLElementProto.hasPointerCapture = () => false;
  HTMLElementProto.setPointerCapture = () => undefined;
  HTMLElementProto.releasePointerCapture = () => undefined;
  HTMLElementProto.scrollIntoView = () => undefined;
  HTMLElementProto.getBoundingClientRect = function (): DOMRect {
    return {
      width: 200,
      height: 20,
      top: 0,
      left: 0,
      bottom: 20,
      right: 200,
      x: 0,
      y: 0,
      toJSON: () => ({}),
    } as DOMRect;
  };

  Object.defineProperty(dom.window, "matchMedia", {
    configurable: true,
    writable: true,
    value: (query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: () => undefined,
      removeListener: () => undefined,
      addEventListener: () => undefined,
      removeEventListener: () => undefined,
      dispatchEvent: () => false,
    }),
  });

  // ResizeObserver مفقود في jsdom — Radix use-size يعتمد عليه.
  class FakeResizeObserver {
    observe(): void {
      /* noop */
    }
    unobserve(): void {
      /* noop */
    }
    disconnect(): void {
      /* noop */
    }
  }
  Object.defineProperty(dom.window, "ResizeObserver", {
    configurable: true,
    writable: true,
    value: FakeResizeObserver,
  });
  Object.defineProperty(globalThis, "ResizeObserver", {
    configurable: true,
    writable: true,
    value: FakeResizeObserver,
  });

  (
    globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT?: boolean }
  ).IS_REACT_ACT_ENVIRONMENT = true;

  return () => {
    cleanup();
    dom.window.close();
    Object.defineProperty(globalThis, "window", {
      configurable: true,
      writable: true,
      value: previousWindow,
    });
    Object.defineProperty(globalThis, "document", {
      configurable: true,
      writable: true,
      value: previousDocument,
    });
    Object.defineProperty(globalThis, "navigator", {
      configurable: true,
      writable: true,
      value: previousNavigator,
    });
    if (previousResizeObserver !== undefined) {
      Object.defineProperty(globalThis, "ResizeObserver", {
        configurable: true,
        writable: true,
        value: previousResizeObserver,
      });
    } else {
      Reflect.deleteProperty(globalThis, "ResizeObserver");
    }
  };
}

/**
 * Harness متحكَّم — يُمكِّن من اختبار `controlled prop change` وإثبات
 * مزامنة العرض مع القيمة الجديدة.
 */
function makeControlledHarness(config: SliderConfig) {
  const updates: number[] = [];
  let currentValue = config.initial;
  let setExternalValue: ((next: number) => void) | null = null;

  const Harness: React.FC = () => {
    const [value, setValue] = React.useState<number>(config.initial);
    React.useEffect(() => {
      setExternalValue = setValue;
      return () => {
        setExternalValue = null;
      };
    }, []);

    const sliderProps: React.ComponentProps<typeof SliderNumberInput> = {
      label: config.label,
      value,
      min: config.min,
      max: config.max,
      step: config.step,
      onChange: (next: number) => {
        currentValue = next;
        updates.push(next);
        setValue(next);
      },
    };

    if (config.formatValue) {
      sliderProps.formatValue = config.formatValue;
    }

    return React.createElement(SliderNumberInput, sliderProps);
  };

  return {
    Harness,
    getCurrentValue: () => currentValue,
    getUpdates: () => updates.slice(),
    setExternal: (next: number) => {
      act(() => {
        setExternalValue?.(next);
      });
    },
  };
}

let SliderNumberInput: React.ComponentType<{
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  onChange: (value: number) => void;
  formatValue?: (value: number) => string;
}>;

/**
 * يستورد المكوّن بعد تثبيت DOM فقط (لأنه يعتمد على بيئة المتصفح).
 */
async function loadSliderModule(): Promise<void> {
  const moduleRef = await import(
    "../../../src/app/(main)/cinematography-studio/components/controls/SliderNumberInput"
  );
  SliderNumberInput =
    moduleRef.SliderNumberInput as unknown as typeof SliderNumberInput;
}

/**
 * يضغط مفتاحًا على عنصر مع act() للسماح لـ React بمعالجة التحديث.
 */
function pressKey(target: HTMLElement, key: string): void {
  act(() => {
    fireEvent.keyDown(target, { key });
    fireEvent.keyUp(target, { key });
  });
}

/**
 * يُحاكي تتابع pointer drag عبر سلسلة من ضغطات الأسهم — وهو نفس المسار الداخلي
 * الذي يسلكه السحب الحقيقي في Radix حين يُترجم pointer events إلى تحديثات قيمة.
 *
 * يضمن أن `onChange` يُستدعى مرات متعددة بقيم متتالية ضمن النطاق.
 */
function simulateDrag(
  slider: HTMLElement,
  direction: "right" | "left",
  steps: number
): void {
  const key = direction === "right" ? "ArrowRight" : "ArrowLeft";
  for (let index = 0; index < steps; index += 1) {
    pressKey(slider, key);
  }
}

/**
 * يثبت أن:
 *  1. التركيب الأولي يعرض القيمة الافتراضية بصورة صحيحة.
 *  2. تغيير prop من الأعلى يُحدّث العرض البصري وحقل الإدخال (controlled update).
 *  3. تتابع الأسهم يُطلق onChange بقيم متسلسلة منطقية ضمن النطاق (drag-like).
 *  4. القيم التي تتجاوز [min, max] تُكبَح (clamping) إلى الحد الأقرب.
 */
async function exerciseSlider(config: SliderConfig): Promise<void> {
  const harness = makeControlledHarness(config);
  const utils = render(React.createElement(harness.Harness));

  try {
    const slider = utils.container.querySelector(
      '[role="slider"]'
    ) as HTMLElement | null;
    const numberInput = utils.container.querySelector(
      'input[type="number"]'
    ) as HTMLInputElement | null;

    assert.ok(slider, `expected slider for "${config.label}"`);
    assert.ok(numberInput, `expected number input for "${config.label}"`);

    // 1) initial render
    const formatter =
      config.formatValue ??
      ((value: number) => {
        const precision = config.step < 1 ? 1 : 0;
        return value.toFixed(precision);
      });
    assert.equal(
      numberInput.value,
      formatter(config.initial),
      `[${config.label}] initial input value mismatch`
    );

    // 2) controlled update from outside
    const externalTarget = clampToRange(
      config.initial + config.step * 5,
      config.min,
      config.max,
      config.step
    );
    harness.setExternal(externalTarget);
    assert.equal(
      numberInput.value,
      formatter(externalTarget),
      `[${config.label}] input did not reflect controlled prop update`
    );

    // 3) drag simulation عبر تتابع 5 أسهم — يثبت أن onChange يُستدعى متسلسلًا
    const beforeUpdates = harness.getUpdates().length;
    simulateDrag(slider, "right", 5);
    const afterRight = harness.getUpdates();
    const rightDelta = afterRight.length - beforeUpdates;
    assert.ok(
      rightDelta >= 1,
      `[${config.label}] expected at least 1 onChange from sequential ArrowRight, got ${rightDelta}`
    );
    for (const value of afterRight) {
      assert.ok(
        value >= config.min - 1e-9 && value <= config.max + 1e-9,
        `[${config.label}] update ${value} out of [${config.min}, ${config.max}]`
      );
    }

    // مسار عكسي للتأكد من السحب في الاتجاهين
    const beforeLeft = harness.getUpdates().length;
    simulateDrag(slider, "left", 3);
    const leftDelta = harness.getUpdates().length - beforeLeft;
    assert.ok(
      leftDelta >= 1,
      `[${config.label}] expected onChange from ArrowLeft sequence, got ${leftDelta}`
    );

    // 4) clamping على الحدود — نُمرِّر قيمتين متطرفتين عبر الإدخال النصي
    act(() => {
      fireEvent.change(numberInput, {
        target: { value: String(config.max * 100) },
      });
      fireEvent.blur(numberInput);
    });
    assert.ok(
      harness.getCurrentValue() <= config.max + 1e-9,
      `[${config.label}] clamping above max failed: got ${harness.getCurrentValue()}`
    );

    act(() => {
      fireEvent.change(numberInput, {
        target: { value: String(config.min - 9999) },
      });
      fireEvent.blur(numberInput);
    });
    assert.ok(
      harness.getCurrentValue() >= config.min - 1e-9,
      `[${config.label}] clamping below min failed: got ${harness.getCurrentValue()}`
    );
  } finally {
    utils.unmount();
  }
}

function clampToRange(
  value: number,
  min: number,
  max: number,
  step: number
): number {
  const stepped = Math.round((value - min) / step) * step + min;
  const clamped = Math.max(min, Math.min(max, stepped));
  const precision = step < 1 ? 4 : 0;
  return Number(clamped.toFixed(precision));
}

/**
 * نقطة الدخول لتشغيل السويت من `run-integration-tests.ts`.
 * تُرجع عدد المنزلقات المُغطَّاة للتسجيل في التقرير.
 */
export async function runSliderDragSuite(): Promise<number> {
  const restoreDom = installDomForSliders();
  try {
    await loadSliderModule();
    for (const config of REAL_SLIDER_CONFIGS) {
      await exerciseSlider(config);
    }
    return REAL_SLIDER_CONFIGS.length;
  } finally {
    restoreDom();
  }
}

import { spawn } from "node:child_process";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);

/**
 * مشغل موحد لاختبارات النهاية إلى النهاية الخاصة بمسار الاستوديو السينمائي.
 *
 * يسمح هذا الملف بتوحيد نقطة التشغيل داخل الحزمة بدل ترك أمر يشير إلى ملف غير موجود.
 */
async function main(): Promise<void> {
  const forwardedArgs = process.argv.slice(2);
  const playwrightCliPath = require.resolve("@playwright/test/cli");
  const playwrightArgs = [
    playwrightCliPath,
    "test",
    "-c",
    "playwright.cinematography.config.ts",
    ...forwardedArgs,
  ];

  await new Promise<void>((resolve, reject) => {
    const child = spawn(process.execPath, playwrightArgs, {
      cwd: process.cwd(),
      stdio: "inherit",
      shell: false,
      env: process.env,
    });

    child.on("error", reject);
    child.on("exit", (code, signal) => {
      if (signal) {
        reject(
          new Error(`تم إيقاف اختبارات النهاية إلى النهاية بإشارة ${signal}.`)
        );
        return;
      }

      if (code !== 0) {
        reject(
          new Error(
            `فشلت اختبارات النهاية إلى النهاية الخاصة بالسينماتوغرافي برمز خروج ${code}.`
          )
        );
        return;
      }

      resolve();
    });
  });
}

main().catch((error) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`${message}\n`);
  process.exitCode = 1;
});

import assert from "node:assert/strict";
import {
  createServer,
  type IncomingMessage,
  type ServerResponse,
} from "node:http";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { ensureMediaFixtures } from "../../tests/fixtures/media/ensure-media-fixtures.mjs";
import { runSliderDragSuite } from "./__tests__/cinematography-slider-drag.test";
import { runDiagnosticOverlaySuite } from "./__tests__/cinematography-diagnostic-overlay.test";
// @ts-ignore — لا يوجد @types/jsdom مثبت، jsdom لها types بداخلها من الإصدار 28+
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
import { JSDOM } from "jsdom";
import { renderHook, act, cleanup } from "@testing-library/react";
import { NextRequest } from "next/server";
import { createCinematographyInputConfig } from "../../src/app/(main)/cinematography-studio/lib/cinematography-config";
import {
  createLocalFootageSummary,
  createLocalShotAnalysis,
} from "../../src/app/(main)/cinematography-studio/lib/local-shot-analysis";

interface SuiteResult {
  name: string;
  status: "passed" | "failed";
  durationMs: number;
  details?: string;
}

interface FixtureServerState {
  receivedBodies: Array<Record<string, unknown>>;
}

interface StartedFixtureServer {
  baseUrl: string;
  close: () => Promise<void>;
  state: FixtureServerState;
}

const outputDirectory = resolve(
  process.cwd(),
  "../../output/cinematography-integration"
);
const reportPath = resolve(outputDirectory, "integration-results.json");
const fixtureImagePath = resolve(
  process.cwd(),
  "tests/fixtures/media/sample-shot.png"
);

mkdirSync(outputDirectory, { recursive: true });

// تأكد من وجود ملفات وسائط الاختبار قبل أي suite — حتى لا يفشل المسار بـ ENOENT
// عند تشغيل المُكامل دون global setup الخاص بـ Playwright.
await ensureMediaFixtures();

async function runSuite(
  name: string,
  runner: () => Promise<void>
): Promise<SuiteResult> {
  const startedAt = Date.now();
  process.stdout.write(`RUN ${name}\n`);

  try {
    await runner();
    const result: SuiteResult = {
      name,
      status: "passed",
      durationMs: Date.now() - startedAt,
    };
    process.stdout.write(`PASS ${name}\n`);
    return result;
  } catch (error) {
    const message =
      error instanceof Error ? error.stack || error.message : String(error);
    const result: SuiteResult = {
      name,
      status: "failed",
      durationMs: Date.now() - startedAt,
      details: message,
    };
    process.stderr.write(`FAIL ${name}\n${message}\n`);
    return result;
  }
}

function createFixtureImageFile(): File {
  const bytes = readFileSync(fixtureImagePath);
  return new File([bytes], "sample-shot.png", {
    type: "image/png",
    lastModified: Date.now(),
  });
}

function readBodyAsText(request: IncomingMessage): Promise<string> {
  return new Promise((resolveBody, rejectBody) => {
    let raw = "";
    request.setEncoding("utf8");
    request.on("data", (chunk) => {
      raw += chunk;
    });
    request.on("end", () => resolveBody(raw));
    request.on("error", rejectBody);
  });
}

async function startFixtureServer(): Promise<StartedFixtureServer> {
  const state: FixtureServerState = {
    receivedBodies: [],
  };

  const server = createServer(
    async (request: IncomingMessage, response: ServerResponse) => {
      const requestUrl = new URL(request.url || "/", "http://127.0.0.1");
      const fixtureMode =
        requestUrl.searchParams.get("fixtureMode") === "fail"
          ? "fail"
          : "success";

      if (request.method === "GET" && requestUrl.pathname === "/health") {
        response.writeHead(200, { "content-type": "application/json" });
        response.end(JSON.stringify({ ok: true, fixtureMode }));
        return;
      }

      if (
        request.method === "POST" &&
        requestUrl.pathname === "/api/cineai/validate-shot"
      ) {
        const bodyText = await readBodyAsText(request);
        const payload = bodyText
          ? (JSON.parse(bodyText) as Record<string, unknown>)
          : {};
        state.receivedBodies.push(payload);

        if (fixtureMode === "fail") {
          response.writeHead(503, { "content-type": "application/json" });
          response.end(
            JSON.stringify({
              success: false,
              error: "Fixture backend failure",
            })
          );
          return;
        }

        response.writeHead(200, { "content-type": "application/json" });
        response.end(
          JSON.stringify({
            success: true,
            validation: {
              score: 88,
              exposure: "Balanced",
              composition: "Strong thirds",
              focus: "Sharp",
              colorBalance: "Neutral",
              suggestions: ["تحسين خفيف في فصل الخلفية."],
            },
          })
        );
        return;
      }

      if (
        request.method === "POST" &&
        requestUrl.pathname === "/api/cineai/color-grading"
      ) {
        response.writeHead(200, { "content-type": "application/json" });
        response.end(
          JSON.stringify({
            success: true,
            sceneType: "generic",
            palette: ["#111111", "#3a3a3a", "#7f5f3a", "#c9a56a", "#f4e2b8"],
          })
        );
        return;
      }

      response.writeHead(404, { "content-type": "application/json" });
      response.end(JSON.stringify({ success: false, error: "Not found" }));
    }
  );

  await new Promise<void>((resolveStart, rejectStart) => {
    server.once("error", rejectStart);
    server.listen(0, "127.0.0.1", () => resolveStart());
  });

  const address = server.address();
  if (!address || typeof address === "string") {
    throw new Error("تعذر الحصول على عنوان خادم التكامل.");
  }

  return {
    baseUrl: `http://127.0.0.1:${address.port}`,
    state,
    close: () =>
      new Promise<void>((resolveClose, rejectClose) => {
        server.close((error) => {
          if (error) {
            rejectClose(error);
            return;
          }
          resolveClose();
        });
      }),
  };
}

function installDomEnvironment(): () => void {
  const dom = new JSDOM("<!doctype html><html><body></body></html>", {
    url: "http://localhost/",
  });

  const previousWindow = globalThis.window;
  const previousDocument = globalThis.document;
  const previousNavigator = globalThis.navigator;
  const previousMatchMedia = globalThis.window?.matchMedia;
  const previousCreateObjectUrl = (
    URL as typeof URL & {
      createObjectURL?: (file: File) => string;
    }
  ).createObjectURL;
  const previousRevokeObjectUrl = (
    URL as typeof URL & {
      revokeObjectURL?: (url: string) => void;
    }
  ).revokeObjectURL;

  Object.defineProperty(globalThis, "window", {
    configurable: true,
    writable: true,
    value: dom.window,
  });
  Object.defineProperty(globalThis, "document", {
    configurable: true,
    writable: true,
    value: dom.window.document,
  });
  Object.defineProperty(globalThis, "navigator", {
    configurable: true,
    writable: true,
    value: dom.window.navigator,
  });

  Object.defineProperty(globalThis.window, "matchMedia", {
    configurable: true,
    writable: true,
    value: (query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: () => undefined,
      removeListener: () => undefined,
      addEventListener: () => undefined,
      removeEventListener: () => undefined,
      dispatchEvent: () => false,
    }),
  });

  (
    URL as typeof URL & { createObjectURL: (file: File) => string }
  ).createObjectURL = () => "blob:cinematography-test";
  (
    URL as typeof URL & { revokeObjectURL: (url: string) => void }
  ).revokeObjectURL = () => undefined;

  (
    globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT?: boolean }
  ).IS_REACT_ACT_ENVIRONMENT = true;

  return () => {
    cleanup();
    dom.window.close();

    Object.defineProperty(globalThis, "window", {
      configurable: true,
      writable: true,
      value: previousWindow,
    });
    Object.defineProperty(globalThis, "document", {
      configurable: true,
      writable: true,
      value: previousDocument,
    });
    Object.defineProperty(globalThis, "navigator", {
      configurable: true,
      writable: true,
      value: previousNavigator,
    });

    if (previousWindow && previousMatchMedia) {
      Object.defineProperty(previousWindow, "matchMedia", {
        configurable: true,
        writable: true,
        value: previousMatchMedia,
      });
    }

    if (previousCreateObjectUrl) {
      (
        URL as typeof URL & { createObjectURL: (file: File) => string }
      ).createObjectURL = previousCreateObjectUrl;
    } else {
      Reflect.deleteProperty(URL, "createObjectURL");
    }

    if (previousRevokeObjectUrl) {
      (
        URL as typeof URL & { revokeObjectURL: (url: string) => void }
      ).revokeObjectURL = previousRevokeObjectUrl;
    } else {
      Reflect.deleteProperty(URL, "revokeObjectURL");
    }
  };
}

