import { Dirent, existsSync } from "node:fs";
import { readdir, rm } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";

type RemovePath = (targetPath: string) => Promise<void>;
type ReadDirectory = (targetPath: string) => Promise<Dirent[]>;
type PathExists = (targetPath: string) => boolean;

interface CleanerDependencies {
  pathExists: PathExists;
  readDirectory: ReadDirectory;
  removePath: RemovePath;
}

const defaultDependencies: CleanerDependencies = {
  pathExists: existsSync,
  readDirectory: async (targetPath) =>
    readdir(targetPath, { withFileTypes: true }) as Promise<Dirent[]>,
  removePath: async (targetPath) => {
    await rm(targetPath, { recursive: true, force: true });
  },
};

function isBusyDirectoryError(error: unknown): error is NodeJS.ErrnoException {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    (error.code === "EBUSY" ||
      error.code === "EPERM" ||
      error.code === "ENOTEMPTY")
  );
}

function isMissingDirectoryError(
  error: unknown
): error is NodeJS.ErrnoException {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    error.code === "ENOENT"
  );
}

export async function clearNextDirectory(
  nextDirectory: string,
  dependencies: CleanerDependencies = defaultDependencies
): Promise<string[]> {
  const { pathExists, readDirectory, removePath } = dependencies;

  if (!pathExists(nextDirectory)) {
    return [];
  }

  try {
    await removePath(nextDirectory);
    return [nextDirectory];
  } catch (error) {
    if (!isBusyDirectoryError(error)) {
      throw error;
    }

    if (!pathExists(nextDirectory)) {
      return [nextDirectory];
    }

    let directoryEntries: Dirent[];
    try {
      directoryEntries = await readDirectory(nextDirectory);
    } catch (readError) {
      if (
        isBusyDirectoryError(readError) ||
        isMissingDirectoryError(readError)
      ) {
        return [`${nextDirectory} (preserved: busy)`];
      }

      throw readError;
    }

    const removedPaths: string[] = [];
    for (const entry of directoryEntries) {
      const entryPath = path.join(nextDirectory, entry.name);
      try {
        await removePath(entryPath);
        removedPaths.push(entryPath);
      } catch (entryError) {
        if (isBusyDirectoryError(entryError)) {
          removedPaths.push(`${entryPath} (preserved: busy)`);
        } else if (isMissingDirectoryError(entryError)) {
          continue;
        } else {
          throw entryError;
        }
      }
    }

    if (removedPaths.length === 0) {
      removedPaths.push(`${nextDirectory} (preserved: busy)`);
    }

    return removedPaths.sort((left, right) => left.localeCompare(right));
  }
}

export async function removeNestedNextDirs(
  rootDirectory: string,
  dependencies: CleanerDependencies = defaultDependencies
): Promise<string[]> {
  const removedPaths: string[] = [];
  const pendingDirectories = [rootDirectory];
  const { readDirectory } = dependencies;

  while (pendingDirectories.length > 0) {
    const currentDirectory = pendingDirectories.pop();
    if (!currentDirectory) {
      continue;
    }

    let entries: Dirent[];
    try {
      entries = await readDirectory(currentDirectory);
    } catch (error) {
      if (isBusyDirectoryError(error) || isMissingDirectoryError(error)) {
        continue;
      }

      throw error;
    }

    for (const entry of entries) {
      if (!entry.isDirectory()) {
        continue;
      }

      const entryPath = path.join(currentDirectory, entry.name);
      if (entry.name === ".next") {
        const cleanedPaths = await clearNextDirectory(entryPath, dependencies);
        removedPaths.push(...cleanedPaths);
        continue;
      }

      pendingDirectories.push(entryPath);
    }
  }

  return removedPaths.sort((left, right) => left.localeCompare(right));
}

export async function main(
  currentWorkingDirectory: string = process.cwd(),
  dependencies: CleanerDependencies = defaultDependencies
): Promise<void> {
  const removedPaths: string[] = [];

  const appBuildDirectory = path.resolve(currentWorkingDirectory, ".next");
  if (dependencies.pathExists(appBuildDirectory)) {
    const cleanedBuildDirectory = await clearNextDirectory(
      appBuildDirectory,
      dependencies
    );
    removedPaths.push(...cleanedBuildDirectory);
  }

  const resolvedSourceRoot = path.resolve(currentWorkingDirectory, "src");
  if (dependencies.pathExists(resolvedSourceRoot)) {
    const nestedBuildArtifacts = await removeNestedNextDirs(
      resolvedSourceRoot,
      dependencies
    );
    removedPaths.push(...nestedBuildArtifacts);
  }

  if (removedPaths.length === 0) {
    console.log("No .next build artifacts found.");
    return;
  }

  console.log("Removed build artifacts:");
  for (const removedPath of removedPaths) {
    console.log(`- ${removedPath}`);
  }
}

const isDirectExecution =
  typeof process.argv[1] === "string" &&
  pathToFileURL(process.argv[1]).href === import.meta.url;

if (isDirectExecution) {
  main().catch((error) => {
    if (isBusyDirectoryError(error) || isMissingDirectoryError(error)) {
      console.warn(
        "[warn] Failed to clean nested build artifacts (non-fatal):",
        error.message || error
      );
      process.exitCode = 0;
      return;
    }

    console.error("[error] Failed to clean build artifacts:", error);
    process.exitCode = 1;
  });
}

const { spawn } = require("child_process");
const net = require("net");
const path = require("path");

const START_PORT = Number(process.env.PORT) || 5000;
const HOST = "0.0.0.0";

function checkPort(port) {
  return new Promise((resolve) => {
    const tester = net
      .createServer()
      .once("error", (err) => {
        if (err.code === "EADDRINUSE") {
          resolve(false);
        } else {
          resolve(false);
        }
      })
      .once("listening", () => {
        tester.close(() => resolve(true));
      })
      .listen(port, HOST);
  });
}

async function findOpenPort(start) {
  let port = start;
  // Try up to 50 ports ahead
  for (let i = 0; i < 50; i++) {
    /* eslint-disable no-await-in-loop */
    const free = await checkPort(port);
    if (free) return port;
    port += 1;
  }
  throw new Error("No open port found");
}

async function run() {
  const port = await findOpenPort(START_PORT);
  // Resolve Next.js CLI JS entry to avoid .cmd spawning issues on Windows
  const nextCli = require.resolve("next/dist/bin/next");
  console.log(`[dev] Starting Next.js on port ${port}...`);
  const child = spawn(
    process.execPath,
    [nextCli, "dev", "-p", String(port), "-H", HOST],
    {
      stdio: "inherit",
      env: { ...process.env, PORT: String(port), HOST },
    }
  );
  child.on("exit", (code) => process.exit(code ?? 0));
}

run().catch((err) => {
  console.error("[dev] Failed to start:", err);
  process.exit(1);
});

#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
// SECURITY FIX: Import safe path utilities to prevent path traversal
const { safeResolve } = require("./safe-path");

function decodeRecord(text) {
  const lines = text.split("\n").filter((line) => line.trim());
  const result = {};
  for (const line of lines) {
    const idx = line.indexOf("=");
    if (idx === -1) continue;
    const key = line.slice(0, idx);
    const value = line
      .slice(idx + 1)
      .replace(/\\=/g, "=")
      .replace(/\\n/g, "\n")
      .replace(/\\r/g, "\r")
      .replace(/\\\\/g, "\\");
    result[key] = value;
  }
  return result;
}

function unflatten(flat) {
  // SECURITY FIX: Use Object.create(null) to prevent prototype pollution
  const result = Object.create(null);
  for (const [key, value] of Object.entries(flat)) {
    // SECURITY FIX: Validate key to prevent prototype pollution
    if (key === "__proto__" || key === "constructor" || key === "prototype") {
      console.warn(`SECURITY: Skipping dangerous key: ${key}`);
      continue;
    }

    const parts = key.split(".");
    let current = result;
    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      // SECURITY FIX: Check for dangerous property names
      if (
        part === "__proto__" ||
        part === "constructor" ||
        part === "prototype"
      ) {
        console.warn(`SECURITY: Skipping dangerous property: ${part}`);
        break;
      }
      if (!current[part]) current[part] = Object.create(null);
      current = current[part];
    }
    const lastKey = parts[parts.length - 1];
    // SECURITY FIX: Final check for dangerous keys
    if (
      lastKey === "__proto__" ||
      lastKey === "constructor" ||
      lastKey === "prototype"
    ) {
      console.warn(`SECURITY: Skipping dangerous final key: ${lastKey}`);
      continue;
    }
    const numValue = parseFloat(value);
    current[lastKey] = isNaN(numValue) ? value : numValue;
  }
  return result;
}

const ABSOLUTE_MINIMUMS = {
  global: { lines: 85, functions: 90, branches: 85, statements: 85 },
  ai: { lines: 95, functions: 100, branches: 95, statements: 95 },
  lib: { lines: 95, functions: 95, branches: 95, statements: 95 },
  components: { lines: 85, functions: 90, branches: 85, statements: 85 },
};

// SECURITY FIX: Use safe path resolution to prevent traversal attacks
const summaryPath = safeResolve(
  process.cwd(),
  "reports/unit/coverage-summary.txt"
);

if (!fs.existsSync(summaryPath)) {
  console.error("❌ FATAL: Coverage summary file not found");
  console.error("📁 Expected at:", summaryPath);
  console.error("💡 Run: npm run test:coverage");
  process.exit(1);
}

const summaryText = fs.readFileSync(summaryPath, "utf-8");
const flat = decodeRecord(summaryText);
const summary = unflatten(flat);
const failures = [];
const warnings = [];

console.log("\n🔍 Enforcing MANDATORY coverage thresholds...\n");

const total = summary.total;
console.log("📊 Global Coverage:");
console.log(
  `   Lines:      ${total.lines.pct.toFixed(2)}% (required: ${ABSOLUTE_MINIMUMS.global.lines}%)`
);
console.log(
  `   Functions:  ${total.functions.pct.toFixed(2)}% (required: ${ABSOLUTE_MINIMUMS.global.functions}%)`
);
console.log(
  `   Branches:   ${total.branches.pct.toFixed(2)}% (required: ${ABSOLUTE_MINIMUMS.global.branches}%)`
);
console.log(
  `   Statements: ${total.statements.pct.toFixed(2)}% (required: ${ABSOLUTE_MINIMUMS.global.statements}%)`
);

// فحص الحدود الإجمالية
["lines", "functions", "branches", "statements"].forEach((metric) => {
  const actual = total[metric].pct;
  const required = ABSOLUTE_MINIMUMS.global[metric];

  if (actual < required) {
    failures.push(
      `❌ Global ${metric}: ${actual.toFixed(2)}% < ${required}% (DEFICIT: ${(required - actual).toFixed(2)}%)`
    );
  }
});

// فحص ملفات محددة حسب المجلد
const fileCategories = {
  ai: /\/ai\//,
  lib: /\/lib\//,
  components: /\/components\//,
};

Object.entries(summary).forEach(([filePath, metrics]) => {
  if (filePath === "total") return;

  let category = "global";
  for (const [cat, regex] of Object.entries(fileCategories)) {
    if (regex.test(filePath)) {
      category = cat;
      break;
    }
  }

  const thresholds = ABSOLUTE_MINIMUMS[category];

  ["lines", "functions", "branches", "statements"].forEach((metric) => {
    const actual = metrics[metric].pct;
    const required = thresholds[metric];

    if (actual < required) {
      failures.push(
        `❌ ${filePath}\n   ${metric}: ${actual.toFixed(2)}% < ${required}% (category: ${category})`
      );
    } else if (actual < required + 5) {
      warnings.push(
        `⚠️  ${filePath}\n   ${metric}: ${actual.toFixed(2)}% (close to threshold: ${required}%)`
      );
    }
  });
});

console.log("\n" + "=".repeat(80));

if (failures.length > 0) {
  console.error("\n🚨 COVERAGE ENFORCEMENT FAILED\n");
  console.error(
    "The following files/metrics DO NOT meet mandatory thresholds:\n"
  );
  failures.forEach((failure) => console.error(failure));

  console.error("\n" + "=".repeat(80));
  console.error("\n📋 REQUIRED ACTIONS:");
  console.error("1. Add comprehensive tests for the failing files");
  console.error("2. Cover all branches, edge cases, and error paths");
  console.error("3. Re-run: npm run test:coverage");
  console.error("4. Verify: npm run enforce:coverage");
  console.error(
    "\n⛔ Merge/Commit BLOCKED until coverage requirements are met.\n"
  );

  process.exit(1);
}

if (warnings.length > 0) {
  console.warn("\n⚠️  WARNING: Some files are close to thresholds:\n");
  warnings.forEach((warning) => console.warn(warning));
  console.warn("\n💡 Consider adding more tests to these files.\n");
}

console.log("\n✅ ALL MANDATORY COVERAGE THRESHOLDS MET");
console.log("🎉 Proceeding with merge/commit\n");

process.exit(0);

#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
const { safeResolve } = require("./safe-path");

const srcDir = safeResolve(process.cwd(), "src");
const untestedFiles = [];

const ALLOWED_EXCEPTIONS = [
  /\.d\.ts$/,
  /^index\.ts$/,
  /types\.ts$/,
  /__tests__\//,
  /__mocks__\//,
  /\.test\./,
  /\.spec\./,
];

function isSimpleIndexFile(filePath) {
  const content = fs.readFileSync(filePath, "utf-8");
  const lines = content.split("\n").filter((line) => line.trim());

  return lines.every(isSimpleLine);
}

function isSimpleLine(line) {
  return (
    line.startsWith("export") ||
    line.startsWith("//") ||
    line.startsWith("/*") ||
    line === ""
  );
}

function isSimpleTypeFile(filePath) {
  const content = fs.readFileSync(filePath, "utf-8");
  const hasLogic = /function |class |const .*=.*=>|if \(|switch \(/.test(
    content
  );
  return !hasLogic;
}

function matchesAllowedException(filePath) {
  return ALLOWED_EXCEPTIONS.some((pattern) => pattern.test(filePath));
}

function isComplexIndexFile(filePath, fileName) {
  return fileName === "index.ts" && !isSimpleIndexFile(filePath);
}

function isComplexTypeFile(filePath, fileName) {
  return fileName.endsWith("types.ts") && !isSimpleTypeFile(filePath);
}

function shouldHaveTests(filePath) {
  const fileName = path.basename(filePath);

  if (!matchesAllowedException(filePath)) {
    return true;
  }

  if (isComplexIndexFile(filePath, fileName)) {
    return true;
  }

  if (isComplexTypeFile(filePath, fileName)) {
    return true;
  }

  return false;
}

function hasTestFile(sourceFile) {
  const dir = path.dirname(sourceFile);
  const baseName = path.basename(sourceFile, path.extname(sourceFile));

  const testPatterns = [
    `${baseName}.test.ts`,
    `${baseName}.test.tsx`,
    `${baseName}.spec.ts`,
    `${baseName}.spec.tsx`,
  ];

  const possibleTestPatterns = [];

  const dirRelative = path.relative(srcDir, dir);

  for (const pattern of testPatterns) {
    try {
      const testPath = safeResolve(srcDir, dirRelative, pattern);
      possibleTestPatterns.push(testPath);
    } catch (error) {
      continue;
    }
  }

  for (const pattern of testPatterns) {
    try {
      const testPath = safeResolve(srcDir, dirRelative, "__tests__", pattern);
      possibleTestPatterns.push(testPath);
    } catch (error) {
      continue;
    }
  }

  return possibleTestPatterns.some((pattern) => fs.existsSync(pattern));
}

function scanDirectory(dir) {
  const items = fs.readdirSync(dir);

  for (const item of items) {
    let fullPath;
    try {
      if (item.includes("..") || item.includes("/") || item.includes("\\")) {
        console.warn(`Skipping potentially dangerous path: ${item}`);
        continue;
      }
      const relativePath = path.relative(srcDir, dir);
      fullPath = safeResolve(srcDir, relativePath, item);
    } catch (error) {
      console.warn(`Skipping invalid path: ${item}`);
      continue;
    }

    const stat = fs.statSync(fullPath);

    if (stat.isDirectory()) {
      scanDirectory(fullPath);
    } else if (item.endsWith(".ts") || item.endsWith(".tsx")) {
      if (shouldHaveTests(fullPath) && !hasTestFile(fullPath)) {
        const relativePath = path.relative(srcDir, fullPath);
        untestedFiles.push({
          path: relativePath,
          size: stat.size,
          reason: "No corresponding test file found",
        });
      }
    }
  }
}

console.log("\n🔎 Scanning for untested TypeScript files...\n");
console.log(`📂 Source directory: ${srcDir}\n`);

scanDirectory(srcDir);

if (untestedFiles.length > 0) {
  console.error("❌ ENFORCEMENT FAILED: Found files without tests\n");
  console.error(`🚨 ${untestedFiles.length} file(s) require tests:\n`);

  untestedFiles
    .sort((a, b) => b.size - a.size)
    .forEach(({ path, size, reason }) => {
      console.error(`   ❌ ${path}`);
      console.error(`      Size: ${(size / 1024).toFixed(2)} KB`);
      console.error(`      Reason: ${reason}\n`);
    });

  console.error("=".repeat(80));
  console.error("\n📋 REQUIRED ACTIONS:");
  console.error("1. Create test files for ALL listed files above");
  console.error(
    "2. Follow naming convention: <filename>.test.ts or <filename>.spec.ts"
  );
  console.error("3. Or place in __tests__/ directory");
  console.error(
    "4. Ensure each test file covers all functions/classes/exports"
  );
  console.error("\n⛔ This is MANDATORY - no exceptions allowed.\n");

  process.exit(1);
}

console.log("✅ SUCCESS: All TypeScript files have corresponding tests");
console.log("🎉 No untested files found\n");

process.exit(0);

