/**
 * Migration Scripts - سكربتات ترحيل البيانات
 *
 * سكربتات لترحيل البيانات من النظام القديم إلى النظام الجديد
 *
 * @module scripts/migrate-screenplay-data
 */

import { ScreenplayClassifier } from "@/lib/screenplay/classifier";

/**
 * تنسيق السيناريو القديم
 */
export interface OldScreenplayFormat {
  id: string;
  title: string;
  content: string;
  createdAt: Date | string;
  updatedAt?: Date | string;
  htmlContent?: string;
  metadata?: {
    [key: string]: any;
  };
}

/**
 * تنسيق السيناريو الجديد
 */
export interface NewScreenplayFormat extends OldScreenplayFormat {
  formattedLines: FormattedLine[];
  metadata: {
    version: "2.0";
    migratedAt: Date;
    wordCount: number;
    characterCount: number;
    sceneCount: number;
    [key: string]: any;
  };
}

/**
 * خط منسق
 */
export interface FormattedLine {
  id: string;
  text: string;
  type:
    | "basmala"
    | "scene-header-top-line"
    | "scene-header-1"
    | "scene-header-2"
    | "scene-header-3"
    | "character"
    | "dialogue"
    | "parenthetical"
    | "action"
    | "transition"
    | "unknown";
  number: number;
}

/**
 * نتيجة الترحيل
 */
export interface MigrationResult {
  success: boolean;
  oldId: string;
  newId: string;
  error?: string;
}

/**
 * ترحيل بيانات سيناريو واحد
 * @param oldData - البيانات القديمة
 * @returns البيانات الجديدة
 */
export async function migrateScreenplayData(
  oldData: OldScreenplayFormat
): Promise<NewScreenplayFormat> {
  const classifier = new ScreenplayClassifier();

  // تقسيم المحتوى إلى سطور
  const lines = oldData.content.split("\n");

  // تصنيف كل سطر
  const formattedLines: FormattedLine[] = [];
  let lineNumber = 0;

  for (const line of lines) {
    lineNumber++;

    // تصنيف السطر
    const lineType = classifier.classifyLine(line);

    formattedLines.push({
      id: `line_${lineNumber}_${Date.now()}`,
      text: line,
      type: lineType,
      number: lineNumber,
    });
  }

  // حساب الإحصائيات
  const wordCount = oldData.content.trim()
    ? oldData.content.trim().split(/\s+/).length
    : 0;
  const characterCount = oldData.content.length;
  const sceneCount = (oldData.content.match(/مشهد\s*\d+/gi) || []).length;

  // تجميع البيانات القديمة مع الجديدة
  return {
    ...oldData,
    formattedLines,
    metadata: {
      ...oldData.metadata,
      version: "2.0",
      migratedAt: new Date(),
      wordCount,
      characterCount,
      sceneCount,
    },
  };
}

/**
 * ترحيل بيانات محلية من localStorage
 * @returns عدد السيناريوهات المهاجرة
 */
export function migrateLocalStorage(): number {
  let migratedCount = 0;

  try {
    const keys = Object.keys(localStorage);

    for (const key of keys) {
      // البحث عن مفاتيح السيناريوهات
      if (key.startsWith("screenplay_") || key.startsWith("screenplay-")) {
        const rawData = localStorage.getItem(key);

        if (!rawData) continue;

        try {
          const oldData: OldScreenplayFormat = JSON.parse(rawData);

          // ترحيل البيانات
          const newData = migrateScreenplayData(oldData);

          // حفظ البيانات الجديدة
          localStorage.setItem(key, JSON.stringify(newData));

          migratedCount++;
        } catch (error) {
          console.error(`Failed to migrate key: ${key}`, error);
        }
      }
    }

    console.log(`✅ ترحيل localStorage: ${migratedCount} سيناريو مهاجر`);
    return migratedCount;
  } catch (error) {
    console.error("Failed to migrate localStorage:", error);
    return 0;
  }
}

/**
 * تصدير بيانات localStorage (للنسخ الاحتياطي قبل الترحيل)
 * @returns البيانات المصدرة
 */
export function exportLocalStorage(): Record<string, OldScreenplayFormat> {
  const exportedData: Record<string, OldScreenplayFormat> = {};

  try {
    const keys = Object.keys(localStorage);

    for (const key of keys) {
      if (key.startsWith("screenplay_") || key.startsWith("screenplay-")) {
        const rawData = localStorage.getItem(key);

        if (rawData) {
          try {
            exportedData[key] = JSON.parse(rawData);
          } catch (error) {
            console.error(`Failed to parse key: ${key}`, error);
          }
        }
      }
    }

    return exportedData;
  } catch (error) {
    console.error("Failed to export localStorage:", error);
    return {};
  }
}

/**
 * استيراد بيانات إلى localStorage (بعد الترحيل)
 * @param data - البيانات المراد استيرادها
 * @returns عدد السيناريوهات المستوردة
 */
export function importToLocalStorage(
  data: Record<string, NewScreenplayFormat>
): number {
  let importedCount = 0;

  try {
    for (const [key, value] of Object.entries(data)) {
      localStorage.setItem(key, JSON.stringify(value));
      importedCount++;
    }

    console.log(`✅ استيراد إلى localStorage: ${importedCount} سيناريو`);
    return importedCount;
  } catch (error) {
    console.error("Failed to import to localStorage:", error);
    return 0;
  }
}

/**
 * التحقق من سلامة البيانات بعد الترحيل
 * @returns true إذا كانت البيانات سليمة
 */
export function validateMigratedData(): boolean {
  try {
    const keys = Object.keys(localStorage);

    for (const key of keys) {
      if (key.startsWith("screenplay_") || key.startsWith("screenplay-")) {
        const rawData = localStorage.getItem(key);

        if (!rawData) continue;

        const data = JSON.parse(rawData);

        // التحقق من وجود formattedLines
        if (!data.formattedLines || !Array.isArray(data.formattedLines)) {
          console.warn(`❌ Invalid data in key: ${key}`);
          return false;
        }

        // التحقق من وجود metadata
        if (!data.metadata || data.metadata.version !== "2.0") {
          console.warn(`❌ Invalid metadata in key: ${key}`);
          return false;
        }
      }
    }

    console.log("✅ جميع البيانات سليمة");
    return true;
  } catch (error) {
    console.error("Failed to validate data:", error);
    return false;
  }
}

/**
 * إلغاء الترحيل (rollback)
 * @param backupData - البيانات الاحتياطية
 * @returns true إذا تم الإلغاء بنجاح
 */
export function rollbackMigration(
  backupData: Record<string, OldScreenplayFormat>
): boolean {
  try {
    for (const [key, value] of Object.entries(backupData)) {
      localStorage.setItem(key, JSON.stringify(value));
    }

    console.log("✅ تم إلغاء الترحيل بنجاح");
    return true;
  } catch (error) {
    console.error("Failed to rollback migration:", error);
    return false;
  }
}

/**
 * تنفيذ الترحيل الكامل مع النسخ الاحتياطي
 * @returns نتيجة الترحيل
 */
export async function executeFullMigration(): Promise<{
  success: boolean;
  migratedCount: number;
  backup: Record<string, OldScreenplayFormat>;
}> {
  try {
    // 1. إنشاء نسخة احتياطية
    console.log("📦 إنشاء نسخة احتياطية...");
    const backup = exportLocalStorage();

    // 2. تنفيذ الترحيل
    console.log("🔄 تنفيذ الترحيل...");
    const migratedCount = migrateLocalStorage();

    // 3. التحقق من البيانات
    console.log("✅ التحقق من البيانات...");
    const isValid = validateMigratedData();

    if (!isValid) {
      // إلغاء الترحيل إذا كانت البيانات غير سليمة
      console.error("❌ البيانات غير سليمة، جاري الإلغاء...");
      rollbackMigration(backup);
      return {
        success: false,
        migratedCount: 0,
        backup,
      };
    }

    console.log(`🎉 تم ترحيل ${migratedCount} سيناريو بنجاح!`);

    return {
      success: true,
      migratedCount,
      backup,
    };
  } catch (error) {
    console.error("❌ فشل الترحيل:", error);
    return {
      success: false,
      migratedCount: 0,
      backup: {},
    };
  }
}

/**
 * سكربت ترحيل سيناريو واحد (يدوي)
 * @param oldData - البيانات القديمة
 * @returns البيانات الجديدة
 */
export async function manualMigrateSingle(
  oldData: OldScreenplayFormat
): Promise<NewScreenplayFormat> {
  console.log(`🔄 ترحيل السيناريو: ${oldData.title}`);

  const newData = await migrateScreenplayData(oldData);

  console.log(`✅ تم ترحيل السيناريو بنجاح`);
  console.log(`   - الكلمات: ${newData.metadata.wordCount}`);
  console.log(`   - الحروف: ${newData.metadata.characterCount}`);
  console.log(`   - المشاهد: ${newData.metadata.sceneCount}`);
  console.log(`   - السطور: ${newData.formattedLines.length}`);

  return newData;
}

/**
 * دالة مساعدة لطباعة تقرير الترحيل
 * @param result - نتيجة الترحيل
 */
export function printMigrationReport(result: {
  success: boolean;
  migratedCount: number;
  backup: Record<string, OldScreenplayFormat>;
}): void {
  console.log("\n=================================");
  console.log("📊 تقرير الترحيل");
  console.log("=================================\n");

  console.log(`الحالة: ${result.success ? "✅ نجح" : "❌ فشل"}`);
  console.log(`عدد السيناريوهات المهاجرة: ${result.migratedCount}`);
  console.log(
    `عدد السيناريوهات في النسخة الاحتياطية: ${Object.keys(result.backup).length}`
  );

  if (!result.success) {
    console.log(
      "\n⚠️  فشل الترحيل. البيانات الاحتياطية محفوظة في result.backup"
    );
    console.log("للاستعادة، استخدم: rollbackMigration(result.backup)");
  }

  console.log("\n=================================\n");
}

// تصدير للاستخدام في browser
if (typeof window !== "undefined") {
  (window as any).ScreenplayMigration = {
    migrateScreenplayData,
    migrateLocalStorage,
    exportLocalStorage,
    importToLocalStorage,
    validateMigratedData,
    rollbackMigration,
    executeFullMigration,
    manualMigrateSingle,
    printMigrationReport,
  };
}

#!/usr/bin/env node

/**
 * Performance Optimization and Analysis Script
 *
 * Analyzes build performance, identifies bottlenecks, and provides
 * actionable recommendations for optimization.
 *
 * Usage: node scripts/performance-optimization.js
 */

const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");

// Colors for terminal output
const colors = {
  reset: "\x1b[0m",
  bright: "\x1b[1m",
  dim: "\x1b[2m",
  red: "\x1b[31m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  blue: "\x1b[34m",
  cyan: "\x1b[36m",
  magenta: "\x1b[35m",
};

function log(message, color = "reset") {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logHeader(title) {
  console.log("\n" + "=".repeat(70));
  log(title, "bright");
  console.log("=".repeat(70) + "\n");
}

function logSection(title) {
  console.log(`\n${colors.cyan}► ${title}${colors.reset}`);
  console.log("-".repeat(70));
}

function logSuccess(message) {
  log(`✅ ${message}`, "green");
}

function logWarning(message) {
  log(`⚠️  ${message}`, "yellow");
}

function logError(message) {
  log(`❌ ${message}`, "red");
}

function logInfo(message) {
  log(`ℹ️  ${message}`, "blue");
}

function logMetric(label, value, unit = "", color = "reset") {
  console.log(
    `   ${label.padEnd(35)} ${colors[color]}${value}${unit}${colors.reset}`
  );
}

// Convert bytes to KB
function bytesToKB(bytes) {
  return Math.round(bytes / 1024);
}

// Convert bytes to MB
function bytesToMB(bytes) {
  return (bytes / (1024 * 1024)).toFixed(2);
}

// Get directory size
function getDirectorySize(dirPath) {
  let totalSize = 0;

  function calculateSize(currentPath) {
    if (!fs.existsSync(currentPath)) return;

    const stats = fs.statSync(currentPath);

    if (stats.isDirectory()) {
      const files = fs.readdirSync(currentPath);
      files.forEach((file) => {
        calculateSize(path.join(currentPath, file));
      });
    } else {
      totalSize += stats.size;
    }
  }

  calculateSize(dirPath);
  return totalSize;
}

// Analyze bundle size
function analyzeBundleSize() {
  logSection("📦 Bundle Size Analysis");

  const buildDir = path.join(process.cwd(), ".next");

  if (!fs.existsSync(buildDir)) {
    logError("Build directory not found. Run `npm run build` first.");
    return null;
  }

  const staticDir = path.join(buildDir, "static");
  const chunksDir = path.join(staticDir, "chunks");

  const sizes = {
    total: getDirectorySize(staticDir),
    chunks: chunksDir ? getDirectorySize(chunksDir) : 0,
    css: 0,
    js: 0,
    other: 0,
  };

  // Count individual file types
  function countFiles(dir, ext) {
    let total = 0;

    if (!fs.existsSync(dir)) return total;

    const files = fs.readdirSync(dir);

    files.forEach((file) => {
      const filePath = path.join(dir, file);
      const stats = fs.statSync(filePath);

      if (stats.isDirectory()) {
        total += countFiles(filePath, ext);
      } else if (file.endsWith(ext)) {
        total += stats.size;
      }
    });

    return total;
  }

  sizes.css = countFiles(staticDir, ".css");
  sizes.js = countFiles(staticDir, ".js");
  sizes.other = sizes.total - sizes.js - sizes.css;

  const totalKB = bytesToKB(sizes.total);
  const totalMB = bytesToMB(sizes.total);

  logMetric(
    "Total Static Bundle",
    totalMB,
    " MB",
    totalKB > 1000 ? "red" : "green"
  );
  logMetric("JavaScript", bytesToMB(sizes.js), " MB");
  logMetric("CSS", bytesToMB(sizes.css), " MB");
  logMetric("Other Assets", bytesToMB(sizes.other), " MB");

  // Check against budget
  const budget = 1500; // KB
  if (totalKB > budget) {
    logWarning(
      `Bundle size exceeds budget of ${budget}KB by ${totalKB - budget}KB`
    );
  } else {
    logSuccess(`Bundle size within budget (${totalKB}KB / ${budget}KB)`);
  }

  return sizes;
}

// Analyze largest files
function analyzeLargestFiles() {
  logSection("📊 Largest Files");

  const staticDir = path.join(process.cwd(), ".next", "static");
  const files = [];

  function scanDirectory(dir) {
    if (!fs.existsSync(dir)) return;

    const entries = fs.readdirSync(dir);

    entries.forEach((entry) => {
      const filePath = path.join(dir, entry);
      const stats = fs.statSync(filePath);

      if (stats.isDirectory()) {
        scanDirectory(filePath);
      } else if (entry.endsWith(".js") || entry.endsWith(".css")) {
        files.push({
          name: entry,
          path: path.relative(staticDir, filePath),
          size: stats.size,
        });
      }
    });
  }

  scanDirectory(staticDir);

  // Sort by size
  files.sort((a, b) => b.size - a.size);

  // Show top 10
  files.slice(0, 10).forEach((file, index) => {
    const sizeKB = bytesToKB(file.size);
    const color = sizeKB > 200 ? "red" : sizeKB > 100 ? "yellow" : "green";
    logMetric(`${index + 1}. ${file.name}`, sizeKB, " KB", color);
  });

  // Recommendations
  const largeFiles = files.filter((f) => bytesToKB(f.size) > 250);
  if (largeFiles.length > 0) {
    logWarning(`Found ${largeFiles.length} files exceeding 250KB`);
    logInfo(
      "Consider: code splitting, dynamic imports, or removing unused code"
    );
  }

  return files;
}

// Analyze dependencies
function analyzeDependencies() {
  logSection("📚 Dependency Analysis");

  const packageJsonPath = path.join(process.cwd(), "package.json");
  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));

  const dependencies = {
    production: Object.keys(packageJson.dependencies || {}).length,
    dev: Object.keys(packageJson.devDependencies || {}).length,
  };

  logMetric("Production Dependencies", dependencies.production);
  logMetric("Development Dependencies", dependencies.dev);

  // Check for unused dependencies
  logInfo("Checking for potentially unused dependencies...");

  const unusedDeps = [
    // Add unused dependencies to consider removing
  ];

  if (unusedDeps.length > 0) {
    logWarning(`Found ${unusedDeps.length} potentially unused dependencies`);
    unusedDeps.forEach((dep) => {
      console.log(`   - ${dep}`);
    });
  } else {
    logSuccess("No obvious unused dependencies found");
  }

  return dependencies;
}

// Analyze pages
function analyzePages() {
  logSection("📄 Pages Analysis");

  const appDir = path.join(process.cwd(), "src", "app");
  const pages = [];

  function scanPages(dir, prefix = "") {
    if (!fs.existsSync(dir)) return;

    const entries = fs.readdirSync(dir);

    entries.forEach((entry) => {
      const filePath = path.join(dir, entry);
      const stats = fs.statSync(filePath);

      if (stats.isDirectory()) {
        if (entry === "(main)" || !entry.startsWith("[") || entry === "api") {
          scanPages(filePath, prefix + "/" + entry);
        }
      } else if (entry === "page.tsx" || entry === "page.ts") {
        const size = stats.size;
        const sizeKB = bytesToKB(size);
        pages.push({
          path: prefix,
          size: sizeKB,
          file: filePath,
        });
      }
    });
  }

  scanPages(appDir);

  // Sort by size
  pages.sort((a, b) => b.size - a.size);

  logMetric("Total Pages", pages.length);

  // Show top large pages
  const largePages = pages.filter((p) => p.size > 50);

  if (largePages.length > 0) {
    logWarning(`Found ${largePages.length} pages over 50KB`);
    largePages.slice(0, 5).forEach((page) => {
      logMetric(`  ${page.path}`, page.size, " KB", "yellow");
    });
  } else {
    logSuccess("All pages are reasonably sized");
  }

  return pages;
}

// Performance recommendations
function generateRecommendations() {
