      const axiosError = error as AxiosError;
      toast({
        title: "فشل توليد الرمز",
        description: axiosError.message || "حدث خطأ غير متوقع",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [projectId, role, expiresInMinutes]);

  const handleCopy = useCallback(async (): Promise<void> => {
    if (!invite) {
      return;
    }
    try {
      await navigator.clipboard.writeText(invite.qr_token);
      toast({
        title: "تم النسخ",
        description: "رمز QR في الحافظة",
      });
    } catch {
      toast({
        title: "تعذّر النسخ",
        description: "المتصفح رفض الوصول إلى الحافظة",
        variant: "destructive",
      });
    }
  }, [invite]);

  const qrImageUrl = useMemo<string | null>(() => {
    if (!invite) {
      return null;
    }
    return `https://chart.googleapis.com/chart?cht=qr&chs=300x300&chl=${encodeURIComponent(
      invite.qr_token
    )}`;
  }, [invite]);

  return (
    <div dir="rtl" className="min-h-screen bg-black/8 p-8 backdrop-blur-xl">
      <div className="max-w-3xl mx-auto">
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              رموز الدعوة
            </h1>
            <p className="text-white/55 font-cairo">
              توليد رمز QR لعضو جديد في المشروع {projectId || "—"}
            </p>
          </div>
          <Link
            href="/BREAKAPP/admin/projects"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            العودة
          </Link>
        </div>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-white mb-2 font-cairo">
                الدور
              </label>
              <select
                value={role}
                onChange={handleRoleChange}
                disabled={loading}
                className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
              >
                {ROLE_OPTIONS.map((option) => (
                  <option
                    key={option.value}
                    value={option.value}
                    className="bg-black text-white"
                  >
                    {option.label}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-white mb-2 font-cairo">
                مدة الصلاحية (بالدقائق)
              </label>
              <input
                type="number"
                min={1}
                max={1440}
                value={expiresInMinutes}
                onChange={handleExpiryChange}
                disabled={loading}
                className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
              />
            </div>
          </div>

          <button
            onClick={handleGenerate}
            disabled={loading || !projectId}
            className="mt-4 px-6 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
          >
            {loading ? "جارٍ التوليد..." : "توليد QR"}
          </button>
        </CardSpotlight>

        {invite && qrImageUrl && (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
            <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
              رمز QR جاهز
            </h2>

            <div className="flex flex-col md:flex-row gap-6 items-center">
              <div className="bg-white rounded-[22px] p-4 flex-shrink-0">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={qrImageUrl}
                  alt="رمز QR للدعوة"
                  width={300}
                  height={300}
                  className="block"
                />
              </div>

              <div className="flex-1 w-full">
                <p className="text-sm text-white/55 font-cairo mb-2">
                  الرمز النصي
                </p>
                <textarea
                  readOnly
                  value={invite.qr_token}
                  rows={4}
                  className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white font-mono text-sm mb-3"
                />
                <p className="text-sm text-white/55 font-cairo mb-4">
                  ينتهي في:{" "}
                  <span className="text-white">
                    {new Date(invite.expiresAt).toLocaleString("ar-SA")}
                  </span>
                </p>
                <button
                  onClick={handleCopy}
                  className="px-4 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 font-cairo transition"
                >
                  نسخ الرمز
                </button>
              </div>
            </div>
          </CardSpotlight>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * إنشاء مشروع جديد — New Admin Project
 *
 * @description
 * نموذج بسيط لإنشاء مشروع جديد باسم فقط، يُوجّه بعد النجاح
 * إلى قائمة المشاريع. التحقق يتم على العميل قبل POST.
 *
 * السبب: مدير النظام يفتح مشاريع بصورة متكررة ويحتاج مدخلاً
 * مبسّطاً يُنهي المهمة في خطوة واحدة دون حقول إضافية.
 */

import { api } from "@the-copy/breakapp";
import { AxiosError } from "axios";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useState } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

interface CreatedProject {
  id: string;
  name: string;
  createdAt: string;
}

export default function AdminNewProjectPage() {
  const router = useRouter();
  const [name, setName] = useState<string>("");
  const [submitting, setSubmitting] = useState<boolean>(false);

  const handleNameChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setName(event.target.value);
    },
    []
  );

  const handleSubmit = useCallback(
    async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
      event.preventDefault();
      const trimmed = name.trim();
      if (trimmed.length < 2) {
        toast({
          title: "الاسم قصير",
          description: "يجب أن يكون اسم المشروع حرفين على الأقل",
          variant: "destructive",
        });
        return;
      }

      setSubmitting(true);
      try {
        await api.post<CreatedProject>("/admin/projects", { name: trimmed });
        toast({
          title: "تم الإنشاء",
          description: "تم إنشاء المشروع بنجاح",
        });
        router.push("/BREAKAPP/admin/projects");
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: "فشل الإنشاء",
          description:
            axiosError.message || "تعذّر إنشاء المشروع، حاول مجدداً",
          variant: "destructive",
        });
      } finally {
        setSubmitting(false);
      }
    },
    [name, router]
  );

  return (
    <div dir="rtl" className="min-h-screen bg-black/8 p-8 backdrop-blur-xl">
      <div className="max-w-2xl mx-auto">
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              مشروع جديد
            </h1>
            <p className="text-white/55 font-cairo">
              أدخل اسم المشروع لإنشائه
            </p>
          </div>
          <Link
            href="/BREAKAPP/admin/projects"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            العودة
          </Link>
        </div>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
          <form onSubmit={handleSubmit}>
            <label className="block text-sm font-medium text-white mb-2 font-cairo">
              اسم المشروع
            </label>
            <input
              type="text"
              value={name}
              onChange={handleNameChange}
              placeholder="مثال: فيلم الصحراء"
              disabled={submitting}
              className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white placeholder-white/45 focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
              minLength={2}
              required
            />

            <button
              type="submit"
              disabled={submitting || name.trim().length < 2}
              className="mt-4 px-6 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
            >
              {submitting ? "جارٍ الإنشاء..." : "إنشاء المشروع"}
            </button>
          </form>
        </CardSpotlight>
      </div>
    </div>
  );
}

"use client";

/**
 * أعضاء المشاريع — Admin Users
 *
 * @description
 * تعرض قائمة الأعضاء المنتمين إلى مشروع مختار من قائمة منسدلة،
 * مع دورهم وتاريخ الانضمام.
 *
 * السبب: مدير النظام بحاجة لصورة شفافة عن توزيع الأعضاء
 * على المشاريع قبل اتخاذ قرارات دعوة أو إلغاء صلاحيات.
 */

import { api, getRoleLabel } from "@the-copy/breakapp";
import { AxiosError } from "axios";
import Link from "next/link";
import { useCallback, useEffect, useState } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

interface AdminProject {
  id: string;
  name: string;
  directorUserId: string;
  createdAt: string;
}

interface ProjectMember {
  userId: string;
  role: string;
  joinedAt: string;
}

export default function AdminUsersPage() {
  const [projects, setProjects] = useState<AdminProject[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>("");
  const [members, setMembers] = useState<ProjectMember[]>([]);
  const [loadingProjects, setLoadingProjects] = useState<boolean>(true);
  const [loadingMembers, setLoadingMembers] = useState<boolean>(false);

  const fetchProjects = useCallback(async (): Promise<void> => {
    setLoadingProjects(true);
    try {
      const response = await api.get<AdminProject[]>("/admin/projects");
      setProjects(response.data);
      const first = response.data[0];
      if (first) {
        setSelectedProjectId(first.id);
      }
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب المشاريع",
        description: axiosError.message || "تعذّر تحميل المشاريع",
        variant: "destructive",
      });
    } finally {
      setLoadingProjects(false);
    }
  }, []);

  const fetchMembers = useCallback(
    async (projectId: string): Promise<void> => {
      if (!projectId) {
        setMembers([]);
        return;
      }
      setLoadingMembers(true);
      try {
        const response = await api.get<ProjectMember[]>("/admin/users", {
          params: { projectId },
        });
        setMembers(response.data);
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: "خطأ في جلب الأعضاء",
          description: axiosError.message || "تعذّر تحميل قائمة الأعضاء",
          variant: "destructive",
        });
      } finally {
        setLoadingMembers(false);
      }
    },
    []
  );

  useEffect(() => {
    void fetchProjects();
  }, [fetchProjects]);

  useEffect(() => {
    void fetchMembers(selectedProjectId);
  }, [selectedProjectId, fetchMembers]);

  const handleProjectChange = useCallback(
    (event: React.ChangeEvent<HTMLSelectElement>): void => {
      setSelectedProjectId(event.target.value);
    },
    []
  );

  return (
    <div dir="rtl" className="min-h-screen bg-black/8 p-8 backdrop-blur-xl">
      <div className="max-w-5xl mx-auto">
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              أعضاء المشاريع
            </h1>
            <p className="text-white/55 font-cairo">
              اختر مشروعاً لعرض أعضائه وأدوارهم
            </p>
          </div>
          <Link
            href="/BREAKAPP/admin"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            العودة
          </Link>
        </div>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <label className="block text-sm font-medium text-white mb-2 font-cairo">
            المشروع
          </label>
          <select
            value={selectedProjectId}
            onChange={handleProjectChange}
            disabled={loadingProjects || projects.length === 0}
            className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
          >
            {projects.length === 0 ? (
              <option value="" className="bg-black text-white">
                لا توجد مشاريع
              </option>
            ) : (
              projects.map((project: AdminProject) => (
                <option
                  key={project.id}
                  value={project.id}
                  className="bg-black text-white"
                >
                  {project.name}
                </option>
              ))
            )}
          </select>
        </CardSpotlight>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            الأعضاء ({members.length})
          </h2>
          {loadingMembers ? (
            <div className="flex justify-center py-12">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-white/40" />
            </div>
          ) : members.length === 0 ? (
            <p className="text-white/55 text-center py-8 font-cairo">
              لا يوجد أعضاء في هذا المشروع بعد
            </p>
          ) : (
            <div className="space-y-3">
              {members.map((member: ProjectMember) => (
                <div
                  key={`${member.userId}-${member.joinedAt}`}
                  className="flex flex-col md:flex-row md:items-center justify-between gap-2 p-4 border border-white/8 rounded-[22px] bg-white/[0.02]"
                >
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-white font-mono truncate">
                      {member.userId}
                    </p>
                    <p className="text-xs text-white/45 mt-1 font-cairo">
                      انضمّ في{" "}
                      {new Date(member.joinedAt).toLocaleString("ar-SA")}
                    </p>
                  </div>
                  <span className="px-3 py-1 text-xs bg-white/8 text-white rounded-full font-cairo border border-white/12">
                    {getRoleLabel(member.role)}
                  </span>
                </div>
              ))}
            </div>
          )}
        </CardSpotlight>
      </div>
    </div>
  );
}

"use client";

/**
 * إدارة الموردين — Admin Vendors CRUD
 *
 * @description
 * تُتيح لمدير النظام عرض الموردين وإضافة/تعديل/حذف كل مورد
 * من جدول واحد، مع حقول: اسم، متنقّل، خط عرض، خط طول.
 *
 * السبب: الموردون مكوّن بياني ثقيل يُعاد استخدامه في كل
 * العمليات الميدانية، لذا يحتاج المسؤول CRUD كاملاً بسيطاً.
 */

import { api, type Vendor } from "@the-copy/breakapp";
import { AxiosError } from "axios";
import Link from "next/link";
import { useCallback, useEffect, useState } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

interface VendorFormState {
  name: string;
  is_mobile: boolean;
  lat: string;
  lng: string;
}

const EMPTY_FORM: VendorFormState = {
  name: "",
  is_mobile: false,
  lat: "",
  lng: "",
};

export default function AdminVendorsPage() {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [form, setForm] = useState<VendorFormState>(EMPTY_FORM);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState<boolean>(false);

  const fetchVendors = useCallback(async (): Promise<void> => {
    setLoading(true);
    try {
      const response = await api.get<Vendor[]>("/admin/vendors");
      setVendors(response.data);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب الموردين",
        description: axiosError.message || "تعذّر تحميل القائمة",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchVendors();
  }, [fetchVendors]);

  const resetForm = useCallback((): void => {
    setForm(EMPTY_FORM);
    setEditingId(null);
  }, []);

  const handleNameChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, name: event.target.value }));
    },
    []
  );

  const handleMobileChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, is_mobile: event.target.checked }));
    },
    []
  );

  const handleLatChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, lat: event.target.value }));
    },
    []
  );

  const handleLngChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, lng: event.target.value }));
    },
    []
  );

  const validateForm = useCallback((): {
    valid: boolean;
    lat: number;
    lng: number;
    name: string;
  } => {
    const name = form.name.trim();
    const lat = Number.parseFloat(form.lat);
    const lng = Number.parseFloat(form.lng);

    if (name.length < 2) {
      toast({
        title: "اسم غير صالح",
        description: "اسم المورد يجب أن يكون حرفين على الأقل",
        variant: "destructive",
      });
      return { valid: false, lat: 0, lng: 0, name };
    }
    if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
      toast({
        title: "خط عرض غير صالح",
        description: "يجب أن يقع خط العرض بين -90 و 90",
        variant: "destructive",
      });
      return { valid: false, lat: 0, lng: 0, name };
    }
    if (!Number.isFinite(lng) || lng < -180 || lng > 180) {
      toast({
        title: "خط طول غير صالح",
        description: "يجب أن يقع خط الطول بين -180 و 180",
        variant: "destructive",
      });
      return { valid: false, lat: 0, lng: 0, name };
    }
    return { valid: true, lat, lng, name };
  }, [form]);

  const handleSubmit = useCallback(
    async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
      event.preventDefault();
      const validation = validateForm();
      if (!validation.valid) {
        return;
      }

      setSubmitting(true);
      try {
        const payload = {
          name: validation.name,
          is_mobile: form.is_mobile,
          lat: validation.lat,
          lng: validation.lng,
        };

        if (editingId) {
          await api.patch<Vendor>(`/admin/vendors/${editingId}`, payload);
          toast({ title: "تم التحديث", description: "تم تعديل بيانات المورد" });
        } else {
          await api.post<Vendor>("/admin/vendors", payload);
          toast({ title: "تمت الإضافة", description: "تم إنشاء المورد" });
        }

        resetForm();
        await fetchVendors();
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: editingId ? "فشل التحديث" : "فشل الإضافة",
          description: axiosError.message || "حدث خطأ أثناء الحفظ",
          variant: "destructive",
        });
      } finally {
        setSubmitting(false);
      }
    },
    [editingId, fetchVendors, form.is_mobile, resetForm, validateForm]
  );

  const handleEdit = useCallback((vendor: Vendor): void => {
    setEditingId(vendor.id);
    setForm({
      name: vendor.name,
      is_mobile: Boolean(vendor.is_mobile),
      lat: vendor.fixed_location.lat.toString(),
      lng: vendor.fixed_location.lng.toString(),
    });
  }, []);

  const handleDelete = useCallback(
    async (id: string): Promise<void> => {
      const confirmed = window.confirm("هل تريد حذف هذا المورد نهائياً؟");
      if (!confirmed) {
        return;
      }
      try {
        await api.delete<{ success: boolean }>(`/admin/vendors/${id}`);
        toast({ title: "تم الحذف", description: "تم حذف المورد" });
        if (editingId === id) {
          resetForm();
        }
        await fetchVendors();
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: "فشل الحذف",
          description: axiosError.message || "تعذّر حذف المورد",
          variant: "destructive",
        });
      }
    },
    [editingId, fetchVendors, resetForm]
  );

  return (
    <div dir="rtl" className="min-h-screen bg-black/8 p-8 backdrop-blur-xl">
      <div className="max-w-7xl mx-auto">
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              الموردون
            </h1>
            <p className="text-white/55 font-cairo">
              إدارة الموردين الثابتين والمتنقلين
            </p>
          </div>
          <Link
            href="/BREAKAPP/admin"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            العودة
          </Link>
        </div>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            {editingId ? "تعديل مورد" : "إضافة مورد"}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-white mb-2 font-cairo">
                الاسم
              </label>
              <input
                type="text"
                value={form.name}
                onChange={handleNameChange}
                disabled={submitting}
                className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white placeholder-white/45 focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
                required
                minLength={2}
              />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-white mb-2 font-cairo">
                  خط العرض
                </label>
                <input
                  type="number"
                  step="any"
                  value={form.lat}
                  onChange={handleLatChange}
                  disabled={submitting}
                  className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-white mb-2 font-cairo">
                  خط الطول
                </label>
                <input
                  type="number"
                  step="any"
                  value={form.lng}
                  onChange={handleLngChange}
                  disabled={submitting}
                  className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
                  required
                />
              </div>
            </div>

            <label className="flex items-center gap-2 text-white font-cairo">
              <input
                type="checkbox"
                checked={form.is_mobile}
                onChange={handleMobileChange}
                disabled={submitting}
                className="w-4 h-4 accent-white"
              />
              <span>مورد متنقّل</span>
            </label>

            <div className="flex items-center gap-3">
              <button
                type="submit"
                disabled={submitting}
                className="px-6 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
              >
                {submitting
                  ? "جارٍ الحفظ..."
                  : editingId
                    ? "تحديث المورد"
                    : "إضافة مورد"}
              </button>
              {editingId && (
                <button
                  type="button"
                  onClick={resetForm}
                  disabled={submitting}
                  className="px-4 py-2 bg-white/6 text-white rounded-[22px] hover:bg-white/8 font-cairo transition"
                >
                  إلغاء التعديل
                </button>
              )}
            </div>
          </form>
        </CardSpotlight>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            قائمة الموردين ({vendors.length})
          </h2>
          {loading ? (
            <div className="flex justify-center py-12">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-white/40" />
            </div>
          ) : vendors.length === 0 ? (
            <p className="text-white/55 text-center py-8 font-cairo">
              لا يوجد موردون بعد
            </p>
          ) : (
            <div className="space-y-3">
              {vendors.map((vendor: Vendor) => (
                <div
                  key={vendor.id}
                  className="flex flex-col md:flex-row md:items-center justify-between gap-3 p-4 border border-white/8 rounded-[22px] bg-white/[0.02]"
                >
                  <div className="flex-1">
                    <h3 className="font-semibold text-white font-cairo">
                      {vendor.name}
                    </h3>
                    <p className="text-xs text-white/45 mt-1 font-cairo">
                      {vendor.is_mobile ? "متنقّل" : "ثابت"} •{" "}
                      {vendor.fixed_location.lat.toFixed(4)},{" "}
                      {vendor.fixed_location.lng.toFixed(4)}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => handleEdit(vendor)}
                      className="px-4 py-2 text-sm bg-white/8 text-white rounded-[22px] hover:bg-white/12 font-cairo transition"
                    >
                      تعديل
                    </button>
                    <button
                      onClick={() => void handleDelete(vendor.id)}
                      className="px-4 py-2 text-sm bg-white/6 text-white rounded-[22px] hover:bg-white/12 font-cairo transition border border-white/8"
                    >
                      حذف
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardSpotlight>
      </div>
    </div>
  );
}

"use client";

/**
 * صفحة قائمة الطعام للطاقم - Crew Menu Page
 *
 * @description
 * تتيح لأعضاء الطاقم طلب الطعام من الموردين المتاحين
 * أثناء جلسة التصوير
 *
 * السبب: توفير وسيلة سهلة لطلب الطعام دون مغادرة موقع التصوير
 * مما يحافظ على سير العمل بسلاسة
 */

import {
  api,
  getCurrentUser,
  type MenuItem,
  type OrderItem,
  type Order,
  type Vendor,
} from "@the-copy/breakapp";
import { useSocket } from "@the-copy/breakapp/hooks/useSocket";
import { AxiosError } from "axios";
import { useState, useEffect, useCallback } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

/**
 * حدث تحديث حالة الطلب عبر WebSocket
 */
interface OrderStatusUpdatePayload {
  orderId: string;
  status: Order["status"];
}

export default function CrewMenuPage() {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [selectedVendor, setSelectedVendor] = useState<string | null>(null);
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [sessionId, setSessionId] = useState<string>("");
  const [myOrders, setMyOrders] = useState<Order[]>([]);

  const { connected, on, off } = useSocket({ auth: true });

  /**
   * جلب الموردين من الخادم
   */
  const fetchVendors = useCallback(async (): Promise<void> => {
    try {
      const response = await api.get<Vendor[]>("/vendors");
      setVendors(response.data);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب الموردين",
        description: axiosError.message || "تعذّر تحميل قائمة الموردين",
        variant: "destructive",
      });
    }
  }, []);

  /**
   * جلب طلباتي من الخادم
   */
  const fetchMyOrders = useCallback(async (): Promise<void> => {
    try {
      const response = await api.get<Order[]>("/orders/my-orders");
      setMyOrders(response.data);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب الطلبات",
        description: axiosError.message || "تعذّر تحميل طلباتك",
        variant: "destructive",
      });
    }
  }, []);

  useEffect(() => {
    fetchVendors();
    fetchMyOrders();
  }, [fetchVendors, fetchMyOrders]);

  /**
   * الاستماع لتحديثات حالة الطلبات في الوقت الفعلي
   *
   * السبب: حالة الطلب قد تتغيّر على الخادم (من المخرج أو المورد أو runner)
   * بدون أن يُعيد المستخدم تحميل الصفحة، فنحدّث myOrders تلقائياً.
   */
  useEffect(() => {
    if (!connected) return;

    const statusHandler = (...args: unknown[]): void => {
      const [payload] = args;
      if (
        !payload ||
        typeof payload !== "object" ||
        !("orderId" in payload) ||
        !("status" in payload)
      ) {
        return;
      }
      const data = payload as OrderStatusUpdatePayload;
      setMyOrders((prev: Order[]) =>
        prev.map((order: Order) =>
          order.id === data.orderId ? { ...order, status: data.status } : order
        )
      );
    };

    on("order:status:update", statusHandler);
    return () => {
      off("order:status:update", statusHandler);
    };
  }, [connected, on, off]);

  /**
   * جلب قائمة الطعام من مورد محدد
   */
  const fetchMenu = useCallback(async (vendorId: string): Promise<void> => {
    setLoading(true);
    try {
      const response = await api.get<MenuItem[]>(`/vendors/${vendorId}/menu`);
      setMenuItems(response.data);
      setSelectedVendor(vendorId);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب القائمة",
        description: axiosError.message || "تعذّر تحميل قائمة الطعام",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, []);

  /**
   * إضافة عنصر للسلة
   */
  const addToCart = useCallback((menuItemId: string): void => {
    setCart((prevCart: OrderItem[]) => {
      const existingItem = prevCart.find(
        (item: OrderItem) => item.menuItemId === menuItemId
      );
      if (existingItem) {
        return prevCart.map((item: OrderItem) =>
          item.menuItemId === menuItemId
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prevCart, { menuItemId, quantity: 1 }];
    });
  }, []);

  /**
   * إزالة عنصر من السلة
   */
  const removeFromCart = useCallback((menuItemId: string): void => {
    setCart((prevCart: OrderItem[]) => {
      const existingItem = prevCart.find(
        (item: OrderItem) => item.menuItemId === menuItemId
      );
      if (existingItem && existingItem.quantity > 1) {
        return prevCart.map((item: OrderItem) =>
          item.menuItemId === menuItemId
            ? { ...item, quantity: item.quantity - 1 }
            : item
        );
      }
      return prevCart.filter(
        (item: OrderItem) => item.menuItemId !== menuItemId
      );
    });
  }, []);

  /**
   * تقديم الطلب
   */
  const submitOrder = useCallback(async (): Promise<void> => {
    if (!sessionId || cart.length === 0) {
      toast({
        title: "بيانات ناقصة",
        description: "يرجى إدخال معرّف الجلسة وإضافة عناصر للسلة",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      if (!currentUser) {
        throw new Error("الجلسة غير صالحة. أعد تسجيل الدخول.");
      }

      await api.post("/orders", {
        sessionId,
        userHash: currentUser.userId,
        items: cart,
      });

      toast({
        title: "تم بنجاح",
        description: "تم تقديم الطلب بنجاح!",
      });
      setCart([]);
      fetchMyOrders();
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "فشل تقديم الطلب",
        description: axiosError.message || "حدث خطأ أثناء تقديم الطلب",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [sessionId, cart, fetchMyOrders]);

  /**
   * الحصول على كمية عنصر في السلة
   */
  const getItemQuantityInCart = useCallback(
    (menuItemId: string): number => {
      const item = cart.find((i: OrderItem) => i.menuItemId === menuItemId);
      return item ? item.quantity : 0;
    },
    [cart]
  );

  /**
   * معالج تغيير معرّف الجلسة
   */
  const handleSessionIdChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>): void => {
      setSessionId(e.target.value);
    },
    []
  );

  /**
   * ترجمة حالة الطلب
   */
  const getOrderStatusLabel = useCallback((status: Order["status"]): string => {
    const labels: Record<Order["status"], string> = {
      pending: "معلق",
      processing: "قيد المعالجة",
      completed: "مكتمل",
      cancelled: "ملغي",
    };
    return labels[status] ?? "";
  }, []);

  /**
   * لون حالة الطلب
   */
  const getOrderStatusColor = useCallback((status: Order["status"]): string => {
    const colors: Record<Order["status"], string> = {
      pending: "bg-white/6 text-white/55",
      processing: "bg-white/8 text-white",
      completed: "bg-white/8 text-white",
      cancelled: "bg-white/6 text-white/55",
    };
    return colors[status] ?? "";
  }, []);

  return (
    <div
      dir="rtl"
      className="min-h-screen bg-black/8 p-4 md:p-8 backdrop-blur-xl"
    >
      <div className="max-w-7xl mx-auto">
        {/* العنوان مع زر العودة */}
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              قائمة الطلبات
            </h1>
            <p className="text-white/55 font-cairo">
              اختر العناصر من الموردين المتاحين
            </p>
          </div>
          <a
            href="/BREAKAPP/dashboard"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            العودة للوحة التحكم
          </a>
        </div>

        {/* إدخال معرّف الجلسة */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <label className="block text-sm font-medium text-white mb-2 font-cairo">
            معرّف الجلسة (من المخرج)
          </label>
          <input
            type="text"
            value={sessionId}
            onChange={handleSessionIdChange}
            placeholder="أدخل معرّف الجلسة"
            className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white placeholder-white/45 focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo"
          />
        </CardSpotlight>

        {/* قائمة الموردين */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            الموردون المتاحون
          </h2>
          {vendors.length === 0 ? (
            <p className="text-white/55 text-center py-4 font-cairo">
              لا يوجد موردون متاحون حالياً
            </p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {vendors.map((vendor: Vendor) => (
                <button
                  key={vendor.id}
                  onClick={() => fetchMenu(vendor.id)}
                  className={`p-4 border rounded-[22px] text-right hover:bg-white/8 transition-all ${
                    selectedVendor === vendor.id
                      ? "border-white/20 bg-white/8"
                      : "border-white/8"
                  }`}
                >
                  <h3 className="font-semibold text-white font-cairo">
                    {vendor.name}
                  </h3>
                  <p className="text-sm text-white/55 mt-1 font-cairo">
                    {vendor.is_mobile ? "متنقل" : "موقع ثابت"}
                  </p>
                </button>
              ))}
            </div>
          )}
        </CardSpotlight>

        {/* عناصر القائمة */}
        {menuItems.length > 0 && (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
              عناصر القائمة
            </h2>
            {loading ? (
              <div className="flex justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-white/40" />
              </div>
            ) : (
              <div className="space-y-4">
                {menuItems.map((item: MenuItem) => (
                  <div
                    key={item.id}
                    className="flex items-center justify-between p-4 border border-white/8 rounded-[22px] bg-white/[0.02]"
                  >
                    <div className="flex-1">
                      <h3 className="font-semibold text-white font-cairo">
                        {item.name}
                      </h3>
                      {item.description && (
                        <p className="text-sm text-white/55 mt-1 font-cairo">
                          {item.description}
                        </p>
                      )}
                    </div>
                    <div className="flex items-center gap-3">
                      {getItemQuantityInCart(item.id) > 0 && (
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() => removeFromCart(item.id)}
                            className="w-8 h-8 flex items-center justify-center bg-white/8 text-white rounded-full hover:bg-white/12 transition"
                          >
                            -
                          </button>
                          <span className="w-8 text-center font-semibold text-white">
                            {getItemQuantityInCart(item.id)}
                          </span>
                        </div>
                      )}
                      <button
                        onClick={() => addToCart(item.id)}
                        disabled={!item.available}
                        className="px-4 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
                      >
                        {getItemQuantityInCart(item.id) === 0 ? "إضافة" : "+"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardSpotlight>
        )}

        {/* السلة */}
        {cart.length > 0 && (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
              طلبك ({cart.length} عناصر)
            </h2>
            <div className="space-y-2 mb-4">
              {cart.map((item: OrderItem) => {
                const menuItem = menuItems.find(
                  (m: MenuItem) => m.id === item.menuItemId
                );
                return (
                  <div
                    key={item.menuItemId}
                    className="flex justify-between items-center"
                  >
                    <span className="text-white/85 font-cairo">
                      {menuItem?.name || "عنصر غير معروف"}
                    </span>
                    <span className="font-semibold text-white">
                      x{item.quantity}
                    </span>
                  </div>
                );
              })}
            </div>
            <button
              onClick={submitOrder}
              disabled={loading}
              className="w-full px-6 py-3 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-semibold font-cairo transition"
            >
              {loading ? "جارٍ الإرسال..." : "تقديم الطلب"}
            </button>
          </CardSpotlight>
        )}

        {/* طلباتي */}
        {myOrders.length > 0 && (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
            <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
              طلباتي
            </h2>
            <div className="space-y-4">
              {myOrders.map((order: Order) => (
                <div
                  key={order.id}
                  className="border border-white/8 rounded-[22px] p-4 bg-white/[0.02]"
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-xs text-white/45">
                      {new Date(order.created_at).toLocaleString("ar-SA")}
                    </span>
                    <span
                      className={`px-2 py-1 text-xs rounded-full ${getOrderStatusColor(order.status)}`}
                    >
                      {getOrderStatusLabel(order.status)}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="text-sm text-white/85 font-cairo">
                      {order.items.length} عنصر
                    </div>
                    <a
                      href={`/BREAKAPP/crew/orders/${order.id}`}
                      className="px-3 py-1.5 text-xs bg-white/8 text-white hover:bg-white/12 transition font-cairo rounded-[22px]"
                    >
                      تفاصيل
                    </a>
                  </div>
                </div>
              ))}
            </div>
          </CardSpotlight>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * صفحة تفاصيل الطلب للطاقم - Crew Order Details Page
 *
 * @description
 * تعرض تفاصيل طلب واحد لعضو الطاقم الذي طلبه بما في ذلك
 * timeline للحالة، قائمة العناصر، اسم المورد، وتقدير الوصول.
 * تستمع في الوقت الفعلي لتحديثات حالة الطلب عبر WebSocket.
 *
 * السبب: عضو الطاقم يحتاج رؤية تقدم طلبه لحظياً
 * دون الحاجة لإعادة تحميل الصفحة أو العودة لقائمة الطلبات.
 */

import { api, type Order, type MenuItem } from "@the-copy/breakapp";
import { useSocket } from "@the-copy/breakapp/hooks/useSocket";
import { AxiosError } from "axios";
import { useParams } from "next/navigation";
import { useState, useEffect, useCallback } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

/**
 * شكل الطلب الموسّع القادم من الباك-إند
 *
 * @description
 * الباك-إند يُرجع حقولاً إضافية مع الطلب (اسم المورد، تقدير الوصول،
 * أسماء عناصر القائمة) التي ليست جزءاً من نوع Order الأساسي في
 * الحزمة. نُعلن هذه الحقول محلياً كـ optional لنحترم
 * exactOptionalPropertyTypes ولا نكسر عقد الحزمة.
 */
interface OrderWithDetails extends Order {
  vendorName?: string;
  vendorId?: string;
  estimatedArrival?: string;
  items: (Order["items"][number] & {
      menuItem?: Pick<MenuItem, "id" | "name">;
      name?: string;
    })[];
}

/**
 * حدث تحديث حالة الطلب عبر WebSocket
 */
interface OrderStatusUpdatePayload {
  orderId: string;
  status: Order["status"];
}

/**
 * خطوات الـ timeline المعروضة بالترتيب
 */
const STATUS_STEPS: readonly {
  key: Order["status"];
  label: string;
}[] = [
  { key: "pending", label: "معلق" },
  { key: "processing", label: "قيد المعالجة" },
  { key: "completed", label: "مكتمل" },
];

const STATUS_INDEX: Record<Order["status"], number> = {
  pending: 0,
  processing: 1,
  completed: 2,
  cancelled: -1,
};

export default function CrewOrderDetailsPage(): React.ReactElement {
  const params = useParams<{ id: string }>();
  const orderId = typeof params?.id === "string" ? params.id : "";

  const [order, setOrder] = useState<OrderWithDetails | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [cancelling, setCancelling] = useState<boolean>(false);

  const { connected, on, off } = useSocket({ auth: true });

  /**
   * جلب تفاصيل الطلب من الخادم
   */
  const fetchOrder = useCallback(async (): Promise<void> => {
    if (!orderId) {
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const response = await api.get<OrderWithDetails>(`/orders/${orderId}`);
      setOrder(response.data);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب الطلب",
        description: axiosError.message || "تعذّر تحميل تفاصيل الطلب",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [orderId]);

  useEffect(() => {
    fetchOrder();
  }, [fetchOrder]);

  /**
   * الاستماع لتحديثات حالة الطلب عبر WebSocket
   */
  useEffect(() => {
    if (!connected || !orderId) return;

    const statusHandler = (...args: unknown[]): void => {
      const [payload] = args;
      if (
        !payload ||
        typeof payload !== "object" ||
        !("orderId" in payload) ||
        !("status" in payload)
      ) {
        return;
      }
      const data = payload as OrderStatusUpdatePayload;
      if (data.orderId !== orderId) return;

      setOrder((prev: OrderWithDetails | null): OrderWithDetails | null => {
        if (!prev) return prev;
        return { ...prev, status: data.status };
      });

      toast({
        title: "تحديث حالة الطلب",
        description: `تم تغيير حالة الطلب إلى: ${getStatusLabel(data.status)}`,
      });
    };

    on("order:status:update", statusHandler);
    return () => {
      off("order:status:update", statusHandler);
    };
  }, [connected, orderId, on, off]);

  /**
   * إلغاء الطلب إذا كان لا يزال pending
   */
  const cancelOrder = useCallback(async (): Promise<void> => {
    if (order?.status !== "pending") return;
    setCancelling(true);
    try {
      await api.patch(`/orders/${order.id}/status`, { status: "cancelled" });
      setOrder(
        (prev: OrderWithDetails | null): OrderWithDetails | null =>
          prev ? { ...prev, status: "cancelled" } : prev
      );
      toast({
        title: "تم الإلغاء",
        description: "تم إلغاء الطلب بنجاح",
      });
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "فشل الإلغاء",
        description: axiosError.message || "تعذّر إلغاء الطلب",
        variant: "destructive",
      });
    } finally {
      setCancelling(false);
    }
  }, [order]);

  if (loading) {
    return (
      <div
        dir="rtl"
        className="min-h-screen bg-black/8 p-4 md:p-8 backdrop-blur-xl flex items-center justify-center"
      >
        <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-white/40" />
      </div>
    );
  }

  if (!order) {
    return (
      <div
        dir="rtl"
        className="min-h-screen bg-black/8 p-4 md:p-8 backdrop-blur-xl"
      >
        <div className="max-w-4xl mx-auto">
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
            <p className="text-white/85 text-center font-cairo">
              لم يتم العثور على الطلب.
            </p>
            <div className="mt-4 flex justify-center">
              <a
                href="/BREAKAPP/crew/menu"
                className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
              >
                العودة لقائمة الطلبات
              </a>
            </div>
          </CardSpotlight>
        </div>
      </div>
    );
  }

  const currentIndex = STATUS_INDEX[order.status];
  const isCancelled = order.status === "cancelled";
  const vendorName = order.vendorName ?? order.vendorId ?? "—";

  return (
    <div
      dir="rtl"
      className="min-h-screen bg-black/8 p-4 md:p-8 backdrop-blur-xl"
    >
      <div className="max-w-4xl mx-auto">
        {/* العنوان ورجوع */}
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              تفاصيل الطلب
            </h1>
            <p className="text-white/55 font-cairo font-mono text-sm">
              #{order.id}
            </p>
          </div>
          <a
            href="/BREAKAPP/crew/menu"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            رجوع
          </a>
        </div>

        {/* الحالة العامة */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-semibold text-white font-cairo">
              حالة الطلب
            </h2>
            <span
              className={`px-3 py-1 text-xs rounded-full font-cairo ${
                isCancelled
                  ? "bg-white/6 text-white/55"
                  : "bg-white/8 text-white"
              }`}
            >
              {getStatusLabel(order.status)}
            </span>
          </div>

          {/* Timeline */}
          {isCancelled ? (
            <div className="p-4 bg-white/6 text-white/85 rounded-[22px] font-cairo border border-white/8">
              تم إلغاء هذا الطلب.
            </div>
          ) : (
            <div className="flex items-center justify-between gap-2">
              {STATUS_STEPS.map((step, index: number) => {
                const reached = currentIndex >= index;
                return (
                  <div
                    key={step.key}
                    className="flex-1 flex flex-col items-center"
                  >
                    <div
                      className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-cairo transition ${
                        reached
                          ? "bg-white/12 text-white border border-white/20"
                          : "bg-white/4 text-white/45 border border-white/8"
                      }`}
                    >
                      {index + 1}
                    </div>
                    <span
                      className={`mt-2 text-xs font-cairo ${
                        reached ? "text-white" : "text-white/45"
                      }`}
                    >
                      {step.label}
                    </span>
                    {index < STATUS_STEPS.length - 1 && (
                      <div
                        className={`h-px w-full mt-[-20px] ${
                          currentIndex > index ? "bg-white/20" : "bg-white/8"
                        }`}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </CardSpotlight>

        {/* معلومات المورد والوصول */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            معلومات الطلب
          </h2>
          <div className="space-y-3">
            <div>
              <span className="text-sm text-white/55 font-cairo">المورد:</span>
              <p className="text-white font-cairo">{vendorName}</p>
            </div>
            <div>
              <span className="text-sm text-white/55 font-cairo">
                تاريخ الإنشاء:
              </span>
              <p className="text-white font-cairo">
                {new Date(order.created_at).toLocaleString("ar-SA")}
              </p>
            </div>
            {order.estimatedArrival ? (
              <div>
                <span className="text-sm text-white/55 font-cairo">
                  تقدير الوصول:
                </span>
                <p className="text-white font-cairo">
                  {order.estimatedArrival}
                </p>
              </div>
            ) : null}
          </div>
        </CardSpotlight>

        {/* قائمة العناصر */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            العناصر ({order.items.length})
          </h2>
          {order.items.length === 0 ? (
            <p className="text-white/55 text-center py-4 font-cairo">
              لا توجد عناصر في هذا الطلب
            </p>
          ) : (
            <div className="space-y-3">
              {order.items.map((item, index: number) => {
                const displayName =
                  item.menuItem?.name ?? item.name ?? item.menuItemId;
                return (
                  <div
                    key={`${item.menuItemId}-${index}`}
                    className="flex items-center justify-between p-4 border border-white/8 rounded-[22px] bg-white/[0.02]"
                  >
                    <span className="text-white font-cairo">{displayName}</span>
                    <span className="text-white font-semibold font-cairo">
                      x{item.quantity}
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </CardSpotlight>

        {/* زر الإلغاء */}
        {order.status === "pending" ? (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
            <button
              onClick={cancelOrder}
              disabled={cancelling}
              className="w-full px-6 py-3 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-semibold font-cairo transition"
            >
              {cancelling ? "جارٍ الإلغاء..." : "إلغاء الطلب"}
            </button>
          </CardSpotlight>
        ) : null}
      </div>
    </div>
  );
}

/**
 * ترجمة حالة الطلب لعربية
 */
function getStatusLabel(status: Order["status"]): string {
  const labels: Record<Order["status"], string> = {
    pending: "معلق",
    processing: "قيد المعالجة",
    completed: "مكتمل",
    cancelled: "ملغي",
  };
  return labels[status] ?? "";
}

