"use client";

/**
 * تخطيط الصفحات المحمية — Authentication Guard
 *
 * @description
 * يتحقق من مصادقة المستخدم قبل عرض أي صفحة محمية
 * ويُوجّه غير المصادقين لصفحة تسجيل الدخول تلقائياً.
 *
 * السبب: حماية مركزية للمصادقة. أما فحص الدور (director/crew/...)
 * فيتم في layouts فرعية باستخدام RoleGuard من @the-copy/breakapp.
 */

import { getCurrentUser, isAuthenticated, type CurrentUser } from "@the-copy/breakapp";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

export default function AuthenticatedLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const [user, setUser] = useState<CurrentUser | null>(null);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    if (!isAuthenticated()) {
      router.replace("/BREAKAPP/login/qr");
      return;
    }

    const userData = getCurrentUser();
    if (!userData) {
      router.replace("/BREAKAPP/login/qr");
      return;
    }

    setUser(userData);
    setChecking(false);
  }, [router]);

  if (checking || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-black/8 backdrop-blur-xl">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-white/40 mb-4" />
          <p className="text-white/55 font-cairo">جارٍ التحقق من المصادقة...</p>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

"use client";

/**
 * الملف الشخصي — User Profile
 *
 * @description
 * يعرض بيانات المستخدم الحالي (الدور والمشروع والمعرّف)
 * مع خيار تسجيل الخروج من كل الأجهزة واختيار لغة الواجهة محلياً.
 *
 * السبب: أي مستخدم بأي دور يحتاج شاشة بسيطة لرؤية صلاحياته
 * وإنهاء الجلسة بشكل آمن من مكان موحّد.
 */

import {
  api,
  getCurrentUser,
  getRoleLabel,
  removeToken,
  type CurrentUser,
} from "@the-copy/breakapp";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useState } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

type UiLanguage = "ar" | "en";

export default function ProfilePage() {
  const router = useRouter();
  const [user, setUser] = useState<CurrentUser | null>(null);
  const [language, setLanguage] = useState<UiLanguage>("ar");
  const [loggingOut, setLoggingOut] = useState<boolean>(false);

  useEffect(() => {
    setUser(getCurrentUser());
  }, []);

  const handleLanguageChange = useCallback(
    (event: React.ChangeEvent<HTMLSelectElement>): void => {
      const next = event.target.value;
      if (next === "ar" || next === "en") {
        setLanguage(next);
      }
    },
    []
  );

  const handleLogout = useCallback(async (): Promise<void> => {
    const confirmed = window.confirm(
      "سيتم تسجيل الخروج من كل الأجهزة. هل تريد المتابعة؟"
    );
    if (!confirmed) {
      return;
    }
    setLoggingOut(true);
    try {
      await api.post("/auth/logout", {});
      toast({
        title: "تم تسجيل الخروج",
        description: "انتهت الجلسة من كل الأجهزة",
      });
    } catch {
      toast({
        title: "تحذير",
        description:
          "تعذّر تأكيد الخادم، لكن تم مسح الجلسة محلياً على كل حال",
        variant: "destructive",
      });
    } finally {
      removeToken();
      setLoggingOut(false);
      router.replace("/BREAKAPP/login/qr");
    }
  }, [router]);

  return (
    <div dir="rtl" className="min-h-screen bg-black/8 p-8 backdrop-blur-xl">
      <div className="max-w-3xl mx-auto">
