"use client";

/**
 * صفحة التوصيل النشط للـ Runner - Runner Active Delivery Page
 *
 * @description
 * تعرض المهمة النشطة الحالية للـ runner مع معلومات المورد،
 * الموقع الحالي، الملاحة، وأزرار تحديث الحالة.
 * تبث موقع runner عبر WebSocket وتعرض قائمة جانبية بباقي المهام.
 *
 * السبب: الـ runner يحتاج تركيزاً على مهمة واحدة نشطة مع
 * وصول سريع لقائمة المهام المتبقية وتحديث حالة المهمة لحظياً.
 */

import {
  api,
  getCurrentUser,
  type DeliveryTask,
  type CurrentUser,
} from "@the-copy/breakapp";
import { useGeolocation } from "@the-copy/breakapp/hooks/useGeolocation";
import { useSocket } from "@the-copy/breakapp/hooks/useSocket";
import { AxiosError } from "axios";
import { useState, useEffect, useCallback, useMemo } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

/**
 * مهمة التوصيل الموسّعة القادمة من الباك-إند
 *
 * @description
 * يُرجع الباك-إند حقولاً إضافية (موقع المورد) لا تظهر في نوع
 * DeliveryTask الأساسي. نُعلن هذه كحقول optional محلية لاحترام
 * exactOptionalPropertyTypes بدون كسر عقد الحزمة.
 */
interface DeliveryTaskWithLocation extends DeliveryTask {
  vendorLat?: number;
  vendorLng?: number;
  vendorId?: string;
}

/**
 * الحالات الموسّعة المُرسلة للباك-إند عبر PATCH
 *
 * @description
 * العقد يسمح بـ in-progress | completed | rejected. الحزمة تعرف
 * pending | in-progress | completed فقط؛ نتعامل مع rejected كحالة
 * خاصة تُزيل المهمة من القائمة المحلية بعد نجاح النداء.
 */
type StatusUpdate = "in-progress" | "completed" | "rejected";

export default function RunnerActiveDeliveryPage(): React.ReactElement {
  const [currentUser, setCurrentUser] = useState<CurrentUser | null>(null);
  const [tasks, setTasks] = useState<DeliveryTaskWithLocation[]>([]);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [updatingStatus, setUpdatingStatus] = useState<boolean>(false);

  const { position, error: geoError } = useGeolocation();
  const { connected, emit } = useSocket({ auth: true });

  /**
   * إصلاح C5: runnerId من JWT — لا localStorage
   */
  useEffect(() => {
    setCurrentUser(getCurrentUser());
  }, []);

  const runnerId = currentUser?.userId ?? "";

  /**
   * جلب مهام runner من الخادم
   */
  const fetchTasks = useCallback(async (): Promise<void> => {
    setLoading(true);
    try {
      const response = await api.get<DeliveryTaskWithLocation[]>(
        "/runners/me/tasks"
      );
      setTasks(response.data);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب المهام",
        description: axiosError.message || "تعذّر تحميل مهام التوصيل",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  /**
   * اختيار المهمة الأولى غير المكتملة كمهمة نشطة تلقائياً
   */
  useEffect(() => {
    if (activeTaskId) return;
    const firstOpen = tasks.find(
      (task: DeliveryTaskWithLocation) => task.status !== "completed"
    );
    if (firstOpen) {
      setActiveTaskId(firstOpen.id);
    }
  }, [tasks, activeTaskId]);

  /**
   * تسجيل runner وبث الموقع عند تغيره
   */
  useEffect(() => {
    if (!connected || !runnerId) return;
    emit("runner:register", { runnerId });
  }, [connected, runnerId, emit]);

  useEffect(() => {
    if (!connected || !runnerId || !position) return;
    emit("runner:location", {
      runnerId,
      lat: position.latitude,
      lng: position.longitude,
      timestamp: position.timestamp,
    });
  }, [connected, runnerId, position, emit]);

  const activeTask = useMemo<DeliveryTaskWithLocation | null>(
    () =>
      tasks.find((task: DeliveryTaskWithLocation) => task.id === activeTaskId) ??
      null,
    [tasks, activeTaskId]
  );

  /**
   * تحديث حالة المهمة على الخادم
   */
  const updateStatus = useCallback(
    async (taskId: string, status: StatusUpdate): Promise<void> => {
      setUpdatingStatus(true);
      try {
        await api.patch(`/runners/tasks/${taskId}/status`, { status });

        if (status === "rejected") {
          // إزالة المهمة من القائمة المحلية
          setTasks((prev: DeliveryTaskWithLocation[]) =>
            prev.filter((task: DeliveryTaskWithLocation) => task.id !== taskId)
          );
          if (activeTaskId === taskId) {
            setActiveTaskId(null);
          }
        } else {
          setTasks((prev: DeliveryTaskWithLocation[]) =>
            prev.map((task: DeliveryTaskWithLocation) =>
              task.id === taskId ? { ...task, status } : task
            )
          );
        }

        if (connected) {
          emit("order:status", { orderId: taskId, status });
        }

        const labels: Record<StatusUpdate, string> = {
          "in-progress": "قيد التنفيذ",
          completed: "مكتمل",
          rejected: "مرفوض",
        };
        toast({
          title: "تحديث الحالة",
          description: `تم تغيير حالة المهمة إلى: ${labels[status]}`,
        });
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: "فشل تحديث الحالة",
          description: axiosError.message || "تعذّر تحديث حالة المهمة",
          variant: "destructive",
        });
      } finally {
        setUpdatingStatus(false);
      }
    },
    [activeTaskId, connected, emit]
  );

  const navigationHref = useMemo<string | null>(() => {
    if (activeTask?.vendorLat == null || activeTask?.vendorLng == null) {
      return null;
    }
    return `https://www.google.com/maps/dir/?api=1&destination=${activeTask.vendorLat},${activeTask.vendorLng}`;
  }, [activeTask]);

  const directionText = useMemo<string>(() => {
    if (
      !position ||
      activeTask?.vendorLat == null ||
      activeTask?.vendorLng == null
    ) {
      return "—";
    }
    const dLat = activeTask.vendorLat - position.latitude;
    const dLng = activeTask.vendorLng - position.longitude;
    const ns = dLat > 0 ? "شمالاً" : dLat < 0 ? "جنوباً" : "";
    const ew = dLng > 0 ? "شرقاً" : dLng < 0 ? "غرباً" : "";
    return [ns, ew].filter(Boolean).join(" / ") || "عند الهدف";
  }, [position, activeTask]);

  return (
    <div
      dir="rtl"
      className="min-h-screen bg-black/8 p-4 md:p-8 backdrop-blur-xl"
    >
      <div className="max-w-7xl mx-auto">
        {/* العنوان */}
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              التوصيل النشط
            </h1>
            <p className="text-white/55 font-cairo">
              مهامك الحالية وموقعك المباشر
            </p>
          </div>
          <a
            href="/BREAKAPP/runner/track"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            لوحة التتبع
          </a>
        </div>

        {!currentUser ? (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
            <p className="text-white/85 text-center font-cairo">
              جلسة غير صالحة. أعد تسجيل الدخول.
            </p>
          </CardSpotlight>
        ) : loading ? (
          <div className="flex justify-center py-12">
            <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-white/40" />
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* المهمة النشطة */}
            <div className="lg:col-span-2 space-y-6">
              {activeTask ? (
                <>
                  <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
                    <div className="flex items-center justify-between mb-4">
                      <h2 className="text-xl font-semibold text-white font-cairo">
                        المهمة النشطة
                      </h2>
                      <span
                        className={`px-3 py-1 text-xs rounded-full font-cairo ${
                          activeTask.status === "completed"
                            ? "bg-white/8 text-white"
                            : activeTask.status === "in-progress"
                              ? "bg-white/8 text-white"
                              : "bg-white/6 text-white/55"
                        }`}
                      >
                        {activeTask.status === "completed"
                          ? "مكتمل"
                          : activeTask.status === "in-progress"
                            ? "قيد التنفيذ"
                            : "معلق"}
                      </span>
                    </div>
                    <div className="space-y-3">
                      <div>
                        <span className="text-sm text-white/55 font-cairo">
                          المورد:
                        </span>
                        <p className="text-white font-cairo text-lg">
                          {activeTask.vendorName}
                        </p>
                      </div>
                      <div>
                        <span className="text-sm text-white/55 font-cairo">
                          عدد العناصر:
                        </span>
                        <p className="text-white font-cairo">
                          {activeTask.items} عنصر
                        </p>
                      </div>
                      {activeTask.vendorLat != null &&
                      activeTask.vendorLng != null ? (
                        <div>
                          <span className="text-sm text-white/55 font-cairo">
                            موقع المورد:
                          </span>
                          <p className="text-white font-mono text-sm">
                            {activeTask.vendorLat.toFixed(6)},{" "}
                            {activeTask.vendorLng.toFixed(6)}
                          </p>
                        </div>
                      ) : null}
                    </div>
                  </CardSpotlight>

                  {/* الموقع والملاحة */}
                  <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
                    <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
                      الموقع والملاحة
                    </h2>
                    {geoError ? (
                      <div className="p-4 bg-white/6 text-white/85 rounded-[22px] mb-4 font-cairo border border-white/8">
                        خطأ: {geoError}
                      </div>
                    ) : position ? (
                      <div className="space-y-3 mb-4">
                        <div>
                          <span className="text-sm text-white/55 font-cairo">
                            موقعك الحالي:
                          </span>
                          <p className="text-white font-mono text-sm">
                            {position.latitude.toFixed(6)},{" "}
                            {position.longitude.toFixed(6)}
                          </p>
                        </div>
                        <div>
                          <span className="text-sm text-white/55 font-cairo">
                            الاتجاه للمورد:
                          </span>
                          <p className="text-white font-cairo">
                            {directionText}
                          </p>
                        </div>
                      </div>
                    ) : (
                      <p className="text-white/55 mb-4 font-cairo">
                        جارٍ تحديد الموقع...
                      </p>
                    )}

                    {navigationHref ? (
                      <a
                        href={navigationHref}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="block text-center px-6 py-3 bg-white/8 text-white rounded-[22px] hover:bg-white/12 font-semibold font-cairo transition"
                      >
                        فتح في خرائط Google
                      </a>
                    ) : null}
                  </CardSpotlight>

                  {/* أزرار الحالة */}
                  <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
                    <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
                      تحديث الحالة
                    </h2>
                    <div className="grid grid-cols-2 gap-3">
                      <button
                        onClick={() =>
                          updateStatus(activeTask.id, "in-progress")
                        }
                        disabled={
                          updatingStatus ||
                          activeTask.status === "completed" ||
                          activeTask.status === "in-progress"
                        }
                        className="px-4 py-3 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
                      >
                        وصلت للمورد
                      </button>
                      <button
                        onClick={() =>
                          updateStatus(activeTask.id, "in-progress")
                        }
                        disabled={
                          updatingStatus || activeTask.status === "completed"
                        }
                        className="px-4 py-3 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
                      >
                        استلمت وفي الطريق
                      </button>
                      <button
                        onClick={() => updateStatus(activeTask.id, "completed")}
                        disabled={
                          updatingStatus || activeTask.status === "completed"
                        }
                        className="px-4 py-3 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
                      >
                        سلّمت
                      </button>
                      <button
                        onClick={() => updateStatus(activeTask.id, "rejected")}
                        disabled={updatingStatus}
                        className="px-4 py-3 bg-white/6 text-white/85 rounded-[22px] hover:bg-white/8 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
                      >
                        رفض
                      </button>
                    </div>
                  </CardSpotlight>
                </>
              ) : (
                <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
                  <p className="text-white/85 text-center font-cairo">
                    لا توجد مهمة نشطة حالياً.
                  </p>
                </CardSpotlight>
              )}
            </div>

            {/* القائمة الجانبية: كل المهام */}
            <div>
              <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
                <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
                  كل المهام ({tasks.length})
                </h2>
                {tasks.length === 0 ? (
                  <p className="text-white/55 text-center py-4 font-cairo">
                    لا توجد مهام.
                  </p>
                ) : (
                  <div className="space-y-3">
                    {[...tasks]
                      .sort(
                        (
                          a: DeliveryTaskWithLocation,
                          b: DeliveryTaskWithLocation
                        ) => {
                          const order: Record<DeliveryTask["status"], number> =
                            {
                              "in-progress": 0,
                              pending: 1,
                              completed: 2,
                            };
                          return order[a.status] - order[b.status];
                        }
                      )
                      .map((task: DeliveryTaskWithLocation) => {
                        const isActive = task.id === activeTaskId;
                        return (
                          <button
                            key={task.id}
                            onClick={() => setActiveTaskId(task.id)}
                            className={`w-full text-right p-3 rounded-[22px] border transition ${
                              isActive
                                ? "border-white/20 bg-white/8"
                                : "border-white/8 bg-white/[0.02] hover:bg-white/4"
                            }`}
                          >
                            <div className="flex items-center justify-between mb-1">
                              <span className="text-white font-cairo text-sm">
                                {task.vendorName}
                              </span>
                              <span
                                className={`px-2 py-0.5 text-xs rounded-full font-cairo ${
                                  task.status === "completed"
                                    ? "bg-white/8 text-white"
                                    : task.status === "in-progress"
                                      ? "bg-white/8 text-white"
                                      : "bg-white/6 text-white/55"
                                }`}
                              >
                                {task.status === "completed"
                                  ? "مكتمل"
                                  : task.status === "in-progress"
                                    ? "قيد التنفيذ"
                                    : "معلق"}
                              </span>
                            </div>
                            <span className="text-xs text-white/55 font-cairo">
                              {task.items} عنصر
                            </span>
                          </button>
                        );
                      })}
                  </div>
                )}
              </CardSpotlight>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * صفحة تتبع Runner - Runner Track Page
 *
 * @description
 * تتيح لعامل التوصيل (Runner) تتبع موقعه
 * وإدارة مهام التوصيل المُسندة إليه
 *
 * السبب: تتبع موقع Runner ضروري لتوفير معلومات
 * دقيقة للمخرج عن توقيت وصول الطلبات
 */

import {
  api,
  getCurrentUser,
  type DeliveryTask,
} from "@the-copy/breakapp";
import { useGeolocation } from "@the-copy/breakapp/hooks/useGeolocation";
import { useSocket } from "@the-copy/breakapp/hooks/useSocket";
import { AxiosError } from "axios";
import { useState, useEffect, useCallback } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

/**
 * استجابة API للمهام المجمّعة
 */
interface BatchTaskResponse {
  vendorId: string;
  vendorName: string;
  totalItems: number;
}

export default function RunnerTrackPage() {
  const [isTracking, setIsTracking] = useState(false);
  const [tasks, setTasks] = useState<DeliveryTask[]>([]);
  const [sessionId, setSessionId] = useState<string>("");
  const [loadingTasks, setLoadingTasks] = useState(false);

  const { position, error: geoError } = useGeolocation();
  const { connected, emit, on, off } = useSocket();

  /**
   * إصلاح ثغرة C5: runnerId يُستخرج من JWT (getCurrentUser) وليس من
   * localStorage. ممنوع توليد معرّفات عشوائية محلياً لأن ذلك يسمح
   * بانتحال هوية أي runner من جانب العميل. طبقة (authenticated) تضمن
   * وجود جلسة صالحة؛ إن كان التوكن لا يمكن فك تشفيره نُظهر رسالة
   * واضحة دون redirect لأن المسؤولية تقع على الـ layout الأعلى.
   */
  const currentUser = getCurrentUser();
  const runnerId = currentUser?.userId ?? "";

  // تسجيل Runner والاستماع للمهام
  useEffect(() => {
    if (!connected || !runnerId) return;

    emit("runner:register", { runnerId });

    const taskHandler = (...args: unknown[]): void => {
      const [task] = args;
      if (
        !task ||
        typeof task !== "object" ||
        !("id" in task) ||
        !("vendorName" in task) ||
        !("items" in task) ||
        !("status" in task)
      ) {
        return;
      }

      const deliveryTask = task as DeliveryTask;
      setTasks((prev: DeliveryTask[]) => [...prev, deliveryTask]);
      toast({
        title: "مهمة جديدة",
        description: `تم إسناد مهمة توصيل جديدة من ${deliveryTask.vendorName}`,
      });
    };

    on("task:new", taskHandler);

    return () => {
      off("task:new", taskHandler);
    };
  }, [connected, runnerId, emit, on, off]);

  // بث الموقع عند تتبعه
  useEffect(() => {
    if (!isTracking || !position || !connected) return;

    emit("runner:location", {
      runnerId,
      lat: position.latitude,
      lng: position.longitude,
      timestamp: position.timestamp,
    });
  }, [position, isTracking, connected, runnerId, emit]);

  /**
   * بدء تتبع الموقع
   */
  const startTracking = useCallback((): void => {
    setIsTracking(true);
    toast({
      title: "تتبع الموقع",
      description: "تم تفعيل بث الموقع",
    });
  }, []);

  /**
   * إيقاف تتبع الموقع
   */
  const stopTracking = useCallback((): void => {
    setIsTracking(false);
    toast({
      title: "تتبع الموقع",
      description: "تم إيقاف بث الموقع",
    });
  }, []);

  /**
   * جلب المهام من الخادم
   */
  const fetchTasks = useCallback(async (): Promise<void> => {
    if (!sessionId) {
      toast({
        title: "بيانات ناقصة",
        description: "يرجى إدخال معرّف الجلسة",
        variant: "destructive",
      });
      return;
    }

    setLoadingTasks(true);
    try {
      const response = await api.post<BatchTaskResponse[]>(
        `/orders/session/${sessionId}/batch`,
        {}
      );

      const batchedTasks: DeliveryTask[] = response.data.map(
        (batch: BatchTaskResponse) => ({
          id: batch.vendorId,
          vendorName: batch.vendorName,
          items: batch.totalItems,
          status: "pending" as const,
        })
      );

      setTasks(batchedTasks);
      toast({
        title: "تم التحميل",
        description: `تم تحميل ${batchedTasks.length} مهمة`,
      });
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب المهام",
        description: axiosError.message || "تعذّر تحميل المهام",
        variant: "destructive",
      });
    } finally {
      setLoadingTasks(false);
    }
  }, [sessionId]);

  /**
   * تحديث حالة المهمة
   */
  const updateTaskStatus = useCallback(
    (taskId: string, status: "pending" | "in-progress" | "completed"): void => {
      setTasks((prevTasks: DeliveryTask[]) =>
        prevTasks.map((task: DeliveryTask) =>
          task.id === taskId ? { ...task, status } : task
        )
      );

      if (connected) {
        emit("order:status", { orderId: taskId, status });
      }

      const statusLabels = {
        pending: "معلق",
        "in-progress": "قيد التنفيذ",
        completed: "مكتمل",
      };
      toast({
        title: "تحديث الحالة",
        description: `تم تغيير حالة المهمة إلى: ${statusLabels[status]}`,
      });
    },
    [connected, emit]
  );

  /**
   * معالج تغيير معرّف الجلسة
   */
  const handleSessionIdChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>): void => {
      setSessionId(e.target.value);
    },
    []
  );

  return (
    <div
      dir="rtl"
      className="min-h-screen bg-black/8 p-4 md:p-8 backdrop-blur-xl"
    >
      <div className="max-w-4xl mx-auto">
        {/* العنوان مع زر العودة */}
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              لوحة تحكم Runner
            </h1>
            <p className="text-white/55 font-cairo">
              تتبع موقعك وإدارة مهام التوصيل
            </p>
          </div>
          <a
            href="/BREAKAPP/dashboard"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            العودة للوحة التحكم
          </a>
        </div>

        {/* معلومات Runner */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            معلومات Runner
          </h2>
          <div className="space-y-2">
            <div>
              <span className="text-sm text-white/55 font-cairo">
                معرّف Runner:
              </span>
              {runnerId ? (
                <p className="font-mono text-sm text-white">{runnerId}</p>
              ) : (
                <p className="text-sm text-white/85 font-cairo">
                  جلسة غير صالحة
                </p>
              )}
            </div>
            <div>
              <span className="text-sm text-white/55 font-cairo">
                حالة الاتصال:
              </span>
              <span
                className={`mr-2 px-2 py-1 text-xs rounded-full ${
                  connected
                    ? "bg-white/8 text-white"
                    : "bg-white/6 text-white/55"
                }`}
              >
                {connected ? "متصل" : "غير متصل"}
              </span>
            </div>
          </div>
        </CardSpotlight>

        {/* إدخال معرّف الجلسة */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <label className="block text-sm font-medium text-white mb-2 font-cairo">
            معرّف الجلسة
          </label>
          <div className="flex gap-2">
            <input
              type="text"
              value={sessionId}
              onChange={handleSessionIdChange}
              placeholder="أدخل معرّف الجلسة"
              className="flex-1 px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white placeholder-white/45 focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo"
            />
            <button
              onClick={fetchTasks}
              disabled={loadingTasks}
              className="px-6 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
            >
              {loadingTasks ? "جارٍ التحميل..." : "تحميل المهام"}
            </button>
          </div>
        </CardSpotlight>

        {/* تتبع الموقع */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            تتبع الموقع
          </h2>

          {geoError ? (
            <div className="p-4 bg-white/6 text-white/85 rounded-[22px] mb-4 font-cairo border border-white/8">
              خطأ: {geoError}
            </div>
          ) : position ? (
            <div className="space-y-2 mb-4">
              <div>
                <span className="text-sm text-white/55 font-cairo">
                  خط العرض:
                </span>
                <p className="font-mono text-white">
                  {position.latitude.toFixed(6)}
                </p>
              </div>
              <div>
                <span className="text-sm text-white/55 font-cairo">
                  خط الطول:
                </span>
                <p className="font-mono text-white">
                  {position.longitude.toFixed(6)}
                </p>
              </div>
              <div>
                <span className="text-sm text-white/55 font-cairo">الدقة:</span>
                <p className="text-white font-cairo">
                  {Math.round(position.accuracy)} متر
                </p>
              </div>
            </div>
          ) : (
            <p className="text-white/55 mb-4 font-cairo">
              جارٍ تحديد الموقع...
            </p>
          )}

          <button
            onClick={isTracking ? stopTracking : startTracking}
            disabled={!connected}
            className={`w-full px-6 py-3 text-white rounded-[22px] font-semibold font-cairo transition ${
              isTracking
                ? "bg-white/8 hover:bg-white/12"
                : "bg-white/8 hover:bg-white/12"
            } disabled:bg-white/4 disabled:cursor-not-allowed`}
          >
            {isTracking ? "إيقاف التتبع" : "بدء التتبع"}
          </button>
        </CardSpotlight>

        {/* المهام */}
        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            مهام التوصيل ({tasks.length})
          </h2>

          {tasks.length === 0 ? (
            <p className="text-white/55 text-center py-8 font-cairo">
              لا توجد مهام مُسندة بعد
            </p>
          ) : (
            <div className="space-y-4">
              {tasks.map((task: DeliveryTask) => (
                <div
                  key={task.id}
                  className="border border-white/8 rounded-[22px] p-4 bg-white/[0.02]"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div>
                      <h3 className="font-semibold text-white font-cairo">
                        {task.vendorName}
                      </h3>
                      <p className="text-sm text-white/55 mt-1 font-cairo">
                        {task.items} عنصر للجمع
                      </p>
                    </div>
                    <span
                      className={`px-2 py-1 text-xs rounded-full ${
                        task.status === "completed"
                          ? "bg-white/8 text-white"
                          : task.status === "in-progress"
                            ? "bg-white/8 text-white"
                            : "bg-white/6 text-white/55"
                      }`}
                    >
                      {task.status === "completed"
                        ? "مكتمل"
                        : task.status === "in-progress"
                          ? "قيد التنفيذ"
                          : "معلق"}
                    </span>
                  </div>

                  <div className="flex gap-2">
                    <button
                      onClick={() => updateTaskStatus(task.id, "in-progress")}
                      disabled={task.status !== "pending"}
                      className="flex-1 px-4 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed text-sm font-cairo transition"
                    >
                      بدء
                    </button>
                    <button
                      onClick={() => updateTaskStatus(task.id, "completed")}
                      disabled={task.status === "completed"}
                      className="flex-1 px-4 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed text-sm font-cairo transition"
                    >
                      إتمام
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardSpotlight>
      </div>
    </div>
  );
}

"use client";

/**
 * محرر قائمة المورد — Vendor Menu Editor
 *
 * @description
 * يُتيح للمورد إضافة/تعديل/حذف عناصر قائمة الطعام الخاصة به،
 * مع تبديل حالة التوفّر وإمكانية إدخال سعر اختياري.
 *
 * السبب: قائمة المورد هي المصدر الوحيد الذي يراه الطاقم،
 * لذا يحتاج المورد أداة CRUD مستقلة لا تتطلب تدخّل المسؤول.
 */

import { api, type MenuItem } from "@the-copy/breakapp";
import { AxiosError } from "axios";
import Link from "next/link";
import { useCallback, useEffect, useState } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

interface MenuFormState {
  name: string;
  description: string;
  price: string;
  available: boolean;
}

const EMPTY_FORM: MenuFormState = {
  name: "",
  description: "",
  price: "",
  available: true,
};

interface MenuPayload {
  name: string;
  available: boolean;
  description?: string;
  price?: number;
}

export default function VendorMenuEditorPage() {
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [form, setForm] = useState<MenuFormState>(EMPTY_FORM);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState<boolean>(false);

  const fetchItems = useCallback(async (): Promise<void> => {
    setLoading(true);
    try {
      const response = await api.get<MenuItem[]>("/vendor/menu-items");
      setItems(response.data);
    } catch (error: unknown) {
      const axiosError = error as AxiosError;
      toast({
        title: "خطأ في جلب القائمة",
        description: axiosError.message || "تعذّر تحميل عناصر القائمة",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchItems();
  }, [fetchItems]);

  const resetForm = useCallback((): void => {
    setForm(EMPTY_FORM);
    setEditingId(null);
  }, []);

  const handleNameChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, name: event.target.value }));
    },
    []
  );

  const handleDescriptionChange = useCallback(
    (event: React.ChangeEvent<HTMLTextAreaElement>): void => {
      setForm((prev) => ({ ...prev, description: event.target.value }));
    },
    []
  );

  const handlePriceChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, price: event.target.value }));
    },
    []
  );

  const handleAvailableChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>): void => {
      setForm((prev) => ({ ...prev, available: event.target.checked }));
    },
    []
  );

  const buildPayload = useCallback((): MenuPayload | null => {
    const name = form.name.trim();
    if (name.length < 2) {
      toast({
        title: "اسم غير صالح",
        description: "اسم العنصر يجب أن يكون حرفين على الأقل",
        variant: "destructive",
      });
      return null;
    }

    const payload: MenuPayload = {
      name,
      available: form.available,
    };

    const description = form.description.trim();
    if (description.length > 0) {
      payload.description = description;
    }

    const priceText = form.price.trim();
    if (priceText.length > 0) {
      const priceValue = Number.parseFloat(priceText);
      if (!Number.isFinite(priceValue) || priceValue < 0) {
        toast({
          title: "سعر غير صالح",
          description: "السعر يجب أن يكون رقماً موجباً",
          variant: "destructive",
        });
        return null;
      }
      payload.price = priceValue;
    }

    return payload;
  }, [form]);

  const handleSubmit = useCallback(
    async (event: React.FormEvent<HTMLFormElement>): Promise<void> => {
      event.preventDefault();
      const payload = buildPayload();
      if (!payload) {
        return;
      }

      setSubmitting(true);
      try {
        if (editingId) {
          await api.patch<MenuItem>(
            `/vendor/menu-items/${editingId}`,
            payload
          );
          toast({ title: "تم التحديث", description: "تم تعديل العنصر" });
        } else {
          await api.post<MenuItem>("/vendor/menu-items", payload);
          toast({ title: "تمت الإضافة", description: "تم إنشاء العنصر" });
        }
        resetForm();
        await fetchItems();
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: editingId ? "فشل التحديث" : "فشل الإضافة",
          description: axiosError.message || "حدث خطأ أثناء الحفظ",
          variant: "destructive",
        });
      } finally {
        setSubmitting(false);
      }
    },
    [buildPayload, editingId, fetchItems, resetForm]
  );

  const handleEdit = useCallback((item: MenuItem): void => {
    setEditingId(item.id);
    setForm({
      name: item.name,
      description: item.description ?? "",
      price: "",
      available: item.available,
    });
  }, []);

  const handleDelete = useCallback(
    async (id: string): Promise<void> => {
      const confirmed = window.confirm("هل تريد حذف هذا العنصر نهائياً؟");
      if (!confirmed) {
        return;
      }
      try {
        await api.delete<{ success: boolean }>(`/vendor/menu-items/${id}`);
        toast({ title: "تم الحذف", description: "تم حذف العنصر" });
        if (editingId === id) {
          resetForm();
        }
        await fetchItems();
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: "فشل الحذف",
          description: axiosError.message || "تعذّر حذف العنصر",
          variant: "destructive",
        });
      }
    },
    [editingId, fetchItems, resetForm]
  );

  const handleToggleAvailable = useCallback(
    async (item: MenuItem): Promise<void> => {
      try {
        await api.patch<MenuItem>(`/vendor/menu-items/${item.id}`, {
          available: !item.available,
        });
        await fetchItems();
      } catch (error: unknown) {
        const axiosError = error as AxiosError;
        toast({
          title: "فشل التبديل",
          description: axiosError.message || "تعذّر تحديث حالة التوفّر",
          variant: "destructive",
        });
      }
    },
    [fetchItems]
  );

  return (
    <div dir="rtl" className="min-h-screen bg-black/8 p-8 backdrop-blur-xl">
      <div className="max-w-5xl mx-auto">
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
              محرر القائمة
            </h1>
            <p className="text-white/55 font-cairo">
              أضف وعدّل عناصر قائمة الطعام
            </p>
          </div>
          <Link
            href="/BREAKAPP/vendor/dashboard"
            className="px-4 py-2 text-sm bg-white/6 text-white hover:bg-white/8 transition font-cairo rounded-[22px]"
          >
            لوحة الطلبات
          </Link>
        </div>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            {editingId ? "تعديل عنصر" : "إضافة عنصر"}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-white mb-2 font-cairo">
                الاسم
              </label>
              <input
                type="text"
                value={form.name}
                onChange={handleNameChange}
                disabled={submitting}
                className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white placeholder-white/45 focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
                required
                minLength={2}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-white mb-2 font-cairo">
                الوصف (اختياري)
              </label>
              <textarea
                value={form.description}
                onChange={handleDescriptionChange}
                disabled={submitting}
                rows={3}
                className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white placeholder-white/45 focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-white mb-2 font-cairo">
                السعر (اختياري)
              </label>
              <input
                type="number"
                step="any"
                min={0}
                value={form.price}
                onChange={handlePriceChange}
                disabled={submitting}
                className="w-full px-4 py-2 border border-white/8 rounded-[22px] bg-white/4 text-white focus:ring-2 focus:ring-white/20 focus:border-transparent font-cairo disabled:opacity-50"
              />
            </div>

            <label className="flex items-center gap-2 text-white font-cairo">
              <input
                type="checkbox"
                checked={form.available}
                onChange={handleAvailableChange}
                disabled={submitting}
                className="w-4 h-4 accent-white"
              />
              <span>متوفّر الآن</span>
            </label>

            <div className="flex items-center gap-3">
              <button
                type="submit"
                disabled={submitting}
                className="px-6 py-2 bg-white/8 text-white rounded-[22px] hover:bg-white/12 disabled:bg-white/4 disabled:cursor-not-allowed font-cairo transition"
              >
                {submitting
                  ? "جارٍ الحفظ..."
                  : editingId
                    ? "تحديث العنصر"
                    : "إضافة عنصر"}
              </button>
              {editingId && (
                <button
                  type="button"
                  onClick={resetForm}
                  disabled={submitting}
                  className="px-4 py-2 bg-white/6 text-white rounded-[22px] hover:bg-white/8 font-cairo transition"
                >
                  إلغاء التعديل
                </button>
              )}
            </div>
          </form>
        </CardSpotlight>

        <CardSpotlight className="overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-6">
          <h2 className="text-xl font-semibold mb-4 text-white font-cairo">
            عناصر القائمة ({items.length})
          </h2>
          {loading ? (
            <div className="flex justify-center py-12">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-white/40" />
            </div>
          ) : items.length === 0 ? (
            <p className="text-white/55 text-center py-8 font-cairo">
              لا توجد عناصر بعد
            </p>
          ) : (
            <div className="space-y-3">
              {items.map((item: MenuItem) => (
                <div
                  key={item.id}
                  className="flex flex-col md:flex-row md:items-center justify-between gap-3 p-4 border border-white/8 rounded-[22px] bg-white/[0.02]"
                >
                  <div className="flex-1">
                    <h3 className="font-semibold text-white font-cairo">
                      {item.name}
                    </h3>
                    {item.description && (
                      <p className="text-sm text-white/55 mt-1 font-cairo">
                        {item.description}
                      </p>
                    )}
                    <p className="text-xs text-white/45 mt-1 font-cairo">
                      {item.available ? "متوفّر" : "غير متوفّر"}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => void handleToggleAvailable(item)}
                      className="px-3 py-2 text-sm bg-white/6 text-white rounded-[22px] hover:bg-white/8 font-cairo transition"
                    >
                      {item.available ? "إخفاء" : "إظهار"}
                    </button>
                    <button
                      onClick={() => handleEdit(item)}
                      className="px-3 py-2 text-sm bg-white/8 text-white rounded-[22px] hover:bg-white/12 font-cairo transition"
                    >
                      تعديل
                    </button>
                    <button
                      onClick={() => void handleDelete(item.id)}
                      className="px-3 py-2 text-sm bg-white/6 text-white rounded-[22px] hover:bg-white/12 font-cairo transition border border-white/8"
                    >
                      حذف
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardSpotlight>
      </div>
    </div>
  );
}

"use client";

/**
 * صفحة تسجيل الدخول بـ QR - QR Login Page
 *
 * @description
 * تتيح للمستخدمين الانضمام للمشروع بمسح رمز QR
 * بدلاً من إنشاء حساب تقليدي
 *
 * السبب: تسريع عملية إضافة أعضاء الفريق للمشروع
 * خاصة في بيئات التصوير الميدانية السريعة
 */

import {
  QRTokenSchema,
  generateDeviceHash,
  scanQRAndLogin,
  storeToken,
  type AuthResponse,
} from "@the-copy/breakapp";
import dynamic from "next/dynamic";
import { useRouter } from "next/navigation";
import { useState, useCallback } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import { toast } from "@/hooks/use-toast";

import type { QRScannerErrorDetail } from "@the-copy/breakapp/components/scanner/QRScanner";

const QRScanner = dynamic(
  () => import("@the-copy/breakapp/components/scanner/QRScanner"),
  {
    ssr: false,
    loading: () => (
      <div className="rounded-[22px] border border-white/8 bg-white/6 backdrop-blur-xl p-6 text-center text-sm text-white/55">
        جارٍ تحميل ماسح QR...
      </div>
    ),
  }
);

/**
 * عناوين الأخطاء العربية لكل سبب فشل ممكن
 * السبب: تقديم عنوان مناسب للمستخدم بدل رسالة عامة موحدة
 * المفاتيح مطابقة لـ QRCameraFailureReason + أسباب المكون الإضافية
 */
const ERROR_TITLES: Record<QRScannerErrorDetail["reason"], string> = {
  "insecure-context": "اتصال غير آمن",
  "mediadevices-unavailable": "المتصفح غير مدعوم",
  "permissions-policy-blocked": "الكاميرا محجوبة بواسطة سياسة الموقع",
  "permission-denied": "رفض الإذن للكاميرا",
  "no-camera-device": "لا توجد كاميرا",
  "device-in-use": "الكاميرا مستخدمة من تطبيق آخر",
  overconstrained: "إعدادات الكاميرا غير مدعومة",
  "manual-entry-invalid": "صيغة الرمز غير صحيحة",
  "image-decode-failed": "تعذر استخراج الرمز من الصورة",
  unknown: "خطأ غير متوقع",
};

/**
 * استجابة خطأ API
 */
interface ApiErrorResponse {
  response?: {
    data?: {
      message?: string;
    };
  };
  message?: string;
}

/**
 * صفحة تسجيل الدخول بمسح QR
 */
export default function QRLoginPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  /**
   * معالجة مسح رمز QR
   */
  const handleQRScan = useCallback(
    async (qrToken: string): Promise<void> => {
      try {
        setLoading(true);
        setError(null);

        // التحقق من صيغة الرمز
        const validation = QRTokenSchema.safeParse(qrToken);
        if (!validation.success) {
          setError("صيغة رمز QR غير صالحة");
          toast({
            title: "خطأ في المسح",
            description: "صيغة رمز QR غير صالحة",
            variant: "destructive",
          });
          setLoading(false);
          return;
        }

        // توليد بصمة الجهاز
        const deviceHash = generateDeviceHash();

        // المصادقة مع الخادم
        const result: AuthResponse = await scanQRAndLogin(qrToken, deviceHash);

        // تخزين الرمز
        storeToken(result.access_token);

        // إظهار النجاح
        setSuccess(true);
        toast({
          title: "تم بنجاح",
          description: "تم المصادقة بنجاح، جارٍ التوجيه...",
        });

        // التوجيه للوحة التحكم — مسار صحيح
        setTimeout(() => {
          router.push("/BREAKAPP/dashboard");
        }, 1500);
      } catch (err: unknown) {
        const apiError = err as ApiErrorResponse;
        const errorMsg =
          apiError?.response?.data?.message ||
          apiError?.message ||
          "فشلت عملية المصادقة";
        setError(errorMsg);
        toast({
          title: "فشل المصادقة",
          description: errorMsg,
          variant: "destructive",
        });
        setLoading(false);
      }
    },
    [router]
  );

  /**
   * معالجة خطأ المسح القادم من QRScanner
   * يستقبل detail يحتوي على سبب الفشل والرسالة العربية الموجّهة
   * السبب: توفير تجربة خطأ متسقة عبر مسارات الكاميرا والرفع والإدخال اليدوي
   */
  const handleScanError = useCallback((detail: QRScannerErrorDetail): void => {
    const title = ERROR_TITLES[detail.reason] ?? "خطأ في المسح";
    setError(detail.message);
    toast({
      title,
      description: detail.message,
      variant: "destructive",
    });
  }, []);

  return (
    <div
      dir="rtl"
      className="min-h-screen flex flex-col items-center justify-center bg-black/8 backdrop-blur-xl p-4"
    >
      <CardSpotlight className="max-w-md w-full overflow-hidden rounded-[22px] bg-white/[0.04] backdrop-blur-xl border border-white/8 p-8">
        {/* العنوان */}
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-white mb-2 font-cairo">
            Break Break
          </h1>
          <p className="text-white/55 font-cairo">
            امسح رمز QR للانضمام لمشروعك
          </p>
        </div>

        {success ? (
          /* حالة النجاح */
          <div className="text-center p-8">
            <div className="mb-4">
              <svg
                className="mx-auto h-16 w-16 text-white"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            </div>
            <h2 className="text-2xl font-bold text-white mb-2 font-cairo">
              نجاح!
            </h2>
            <p className="text-white/55 font-cairo">
              جارٍ التوجيه للوحة التحكم...
            </p>
          </div>
        ) : (
          <>
            {/* ماسح QR */}
            <QRScanner onScan={handleQRScan} onError={handleScanError} />

            {/* مؤشر التحميل */}
            {loading && (
              <div className="mt-6 text-center">
                <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-white/40" />
                <p className="mt-2 text-sm text-white/55 font-cairo">
                  جارٍ المصادقة...
                </p>
              </div>
            )}

            {/* رسالة الخطأ */}
            {error && (
              <div className="mt-6 p-4 bg-white/6 text-white/85 rounded-[22px] border border-white/8">
                <p className="text-sm font-medium font-cairo">فشلت المصادقة</p>
                <p className="text-sm mt-1 font-cairo">{error}</p>
              </div>
            )}
          </>
        )}
      </CardSpotlight>

      {/* تعليمات */}
      <div className="mt-8 text-center text-sm text-white/55">
        <p className="font-cairo">تأكد من منح إذن الوصول للكاميرا</p>
      </div>
    </div>
  );
}

