import { beforeEach, describe, expect, it, vi } from "vitest";
import React from "react";
import { fireEvent, renderWithApp, screen } from "../test-utils";
import { useApp } from "../context/AppContext";
import { APP_STORAGE_KEY } from "../lib/storage";

function TestHarness() {
  const { currentView, theme, user, navigate, toggleTheme, handleRegister } =
    useApp();

  return (
    <div>
      <span data-testid="view">{currentView}</span>
      <span data-testid="theme">{theme}</span>
      <span data-testid="user">{user?.name ?? "guest"}</span>
      <button onClick={() => navigate("rhythm")}>goto-rhythm</button>
      <button onClick={toggleTheme}>toggle-theme</button>
      <button
        onClick={() =>
          handleRegister("سارة علي", "sara@example.com", "StrongPass123")
        }
      >
        register
      </button>
    </div>
  );
}

describe("جاهزية الإنتاج - حالة التطبيق", () => {
  beforeEach(() => {
    localStorage.clear();
    window.history.replaceState({}, "", "/actorai-arabic");
    window.scrollTo = vi.fn();
  });

  it("يقرأ العرض الحالي من عنوان الصفحة ثم يثبته عند التنقل", () => {
    window.history.replaceState({}, "", "/actorai-arabic?view=webcam");

    renderWithApp(<TestHarness />);

    expect(screen.getByTestId("view")).toHaveTextContent("webcam");

    fireEvent.click(screen.getByText("goto-rhythm"));

    expect(screen.getByTestId("view")).toHaveTextContent("rhythm");
    expect(new URLSearchParams(window.location.search).get("view")).toBe(
      "rhythm"
    );

    const stored = JSON.parse(
      localStorage.getItem(APP_STORAGE_KEY) ?? "{}"
    ) as { currentView?: string };

    expect(stored.currentView).toBe("rhythm");
  });

  it("يحفظ السمة والمستخدم ويستعيدهما بعد إعادة التحميل", () => {
    const { unmount } = renderWithApp(<TestHarness />);

    fireEvent.click(screen.getByText("toggle-theme"));
    fireEvent.click(screen.getByText("register"));

    expect(screen.getByTestId("theme")).toHaveTextContent("dark");
    expect(screen.getByTestId("user")).toHaveTextContent("سارة علي");

    unmount();

    renderWithApp(<TestHarness />);

    expect(screen.getByTestId("theme")).toHaveTextContent("dark");
    expect(screen.getByTestId("user")).toHaveTextContent("سارة علي");
  });
});

import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import React from "react";
import { act, fireEvent, renderWithApp, screen } from "../test-utils";
import { SelfTapeSuite } from "../self-tape-suite/components/SelfTapeSuite";

const trackStop = vi.fn();
const mockStream = {
  getTracks: () => [{ stop: trackStop }, { stop: trackStop }],
} as unknown as MediaStream;

class MockMediaRecorder {
  static isTypeSupported = vi.fn(() => true);

  public mimeType: string;
  public state: RecordingState = "inactive";
  public ondataavailable: ((event: BlobEvent) => void) | null = null;
  public onstop: (() => void) | null = null;
  public onerror: (() => void) | null = null;

  constructor(_stream: MediaStream, options?: MediaRecorderOptions) {
    this.mimeType = options?.mimeType ?? "video/webm";
  }

  start = vi.fn(() => {
    this.state = "recording";
  });

  stop = vi.fn(() => {
    this.state = "inactive";
    const blob = new Blob(["fake-video"], { type: this.mimeType });
    this.ondataavailable?.({ data: blob } as BlobEvent);
    this.onstop?.();
  });

  pause = vi.fn();
  resume = vi.fn();
  requestData = vi.fn();
  addEventListener = vi.fn();
  removeEventListener = vi.fn();
  dispatchEvent = vi.fn();
}

async function flushMicrotasks() {
  await act(async () => {
    await Promise.resolve();
  });
}

async function advanceTimers(milliseconds: number) {
  await act(async () => {
    vi.advanceTimersByTime(milliseconds);
    await Promise.resolve();
  });
}

async function createRecordedTake() {
  renderWithApp(<SelfTapeSuite />);

  fireEvent.click(screen.getByRole("button", { name: /التسجيل/ }));
  await flushMicrotasks();
  expect(navigator.mediaDevices.getUserMedia).toHaveBeenCalled();

  fireEvent.click(screen.getByRole("button", { name: /بدء التسجيل/ }));
  await flushMicrotasks();

  await advanceTimers(3000);

  fireEvent.click(screen.getByRole("button", { name: /إنهاء التسجيل/ }));
  await flushMicrotasks();
  expect(
    screen.getByText("تم حفظ Take 1 وتوليد تقييمه المحلي بنجاح.")
  ).toBeInTheDocument();
}

describe("SelfTapeSuite", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    localStorage.clear();
    trackStop.mockClear();

    Object.defineProperty(navigator, "mediaDevices", {
      configurable: true,
      value: {
        getUserMedia: vi.fn().mockResolvedValue(mockStream),
      },
    });

    Object.defineProperty(HTMLMediaElement.prototype, "srcObject", {
      configurable: true,
      get() {
        return null;
      },
      set(_value) {
        return undefined;
      },
    });

    vi.spyOn(HTMLMediaElement.prototype, "play").mockResolvedValue(undefined);
    vi.spyOn(HTMLAnchorElement.prototype, "click").mockImplementation(() => {});

    Object.defineProperty(URL, "createObjectURL", {
      configurable: true,
      writable: true,
      value: vi.fn(() => "blob:session-take"),
    });

    Object.defineProperty(URL, "revokeObjectURL", {
      configurable: true,
      writable: true,
      value: vi.fn(),
    });

    vi.stubGlobal(
      "MediaRecorder",
      MockMediaRecorder as unknown as typeof MediaRecorder
    );
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("ينشئ تسجيلاً حياً قابلاً للتصدير بعد إكمال التسجيل", async () => {
    await createRecordedTake();

    expect(screen.getByText("جلسة حيّة")).toBeInTheDocument();
    expect(screen.getByText("Take 1")).toBeInTheDocument();
    expect(
      screen.getAllByRole("button", { name: "📤 تصدير" }).length
    ).toBeGreaterThan(0);
  });

  it("ينزل الملف عند طلب التصدير للتسجيل الحي", async () => {
    await createRecordedTake();

    fireEvent.click(screen.getByRole("button", { name: /التصدير/ }));
    await flushMicrotasks();
    fireEvent.click(screen.getByRole("button", { name: "📤 تنزيل" }));
    await advanceTimers(80);
    await advanceTimers(80);
    await advanceTimers(120);
    expect(screen.getByText(/تم تنزيل Take 1/)).toBeInTheDocument();

    expect(HTMLAnchorElement.prototype.click).toHaveBeenCalled();
  });
});

