/**
 * @fileoverview خطاف وضع اختبار الحفظ
 * يدير كل منطق حفظ النصوص بما في ذلك التتبع والتحقق والتلقين
 * @reason فصل المنطق المعقد (>10 أسطر) إلى خطاف مستقل لتحسين قابلية الصيانة
 */

"use client";

import { useState, useCallback, useRef } from "react";
import { postToBackend } from "@/lib/backend-api";
import type { MemorizationStats } from "../types";
import {
  VALIDATION_CONSTANTS,
  SAMPLE_MEMORIZATION_SCRIPT,
} from "../types/constants";
import { createDeterministicMemorizationMask } from "../lib/studio-engines";

/**
 * مستوى حذف الكلمات
 * @description نسبة الكلمات المحذوفة من النص للاختبار
 */
export type DeletionLevel = 10 | 50 | 90;

/**
 * حالة وضع الحفظ
 */
export interface MemorizationState {
  /** النص المراد حفظه */
  script: string;
  /** مستوى صعوبة الحذف */
  deletionLevel: DeletionLevel;
  /** هل الجلسة نشطة */
  isActive: boolean;
  /** هل الجلسة متوقفة مؤقتاً */
  isPaused: boolean;
  /** هل وضع التلقين مفعل */
  isPromptMode: boolean;
  /** فهرس السطر الحالي */
  currentLineIndex: number;
  /** إدخال المستخدم الحالي */
  userInput: string;
  /** هل تم اكتشاف تردد */
  hesitationDetected: boolean;
  /** إحصائيات الجلسة */
  stats: MemorizationStats;
  /** هل يُعرض تلميح التلقين */
  showPromptHint: boolean;
  /** الكلمة الحالية للتلقين */
  currentPromptWord: string;
}

/**
 * القيم الافتراضية لإحصائيات الحفظ
 */
const DEFAULT_STATS: MemorizationStats = {
  totalAttempts: 0,
  correctWords: 0,
  incorrectWords: 0,
  hesitationCount: 0,
  weakPoints: [],
  averageResponseTime: 0,
};

/**
 * واجهة قيمة العودة من خطاف الحفظ
 */
export interface UseMemorizationReturn {
  /** حالة الحفظ الكاملة */
  state: MemorizationState;
  /** تعيين نص الحفظ */
  setScript: (script: string) => void;
  /** تعيين مستوى الصعوبة */
  setDeletionLevel: (level: DeletionLevel) => void;
  /** بدء جلسة الحفظ */
  startSession: () => { success: boolean; error?: string };
  /** إيقاف جلسة الحفظ */
  stopSession: () => void;
  /** إيقاف مؤقت/استئناف */
  togglePause: () => void;
  /** معالجة إدخال المستخدم */
  handleInput: (value: string) => void;
  /** تقديم إجابة */
  submitAnswer: () => { correct: number; incorrect: number };
  /** تحميل نص نموذجي */
  loadSampleScript: () => void;
  /** زيادة مستوى الصعوبة */
  increaseDifficulty: () => void;
  /** الحصول على الأجزاء الصعبة */
  getDifficultParts: () => string[];
  /** معالجة النص للحفظ (حذف كلمات) */
  processTextForDisplay: () => string;
  /** إعادة التعيين */
  reset: () => void;
}

/**
 * خطاف إدارة وضع اختبار الحفظ
 * @description يدير كل منطق حفظ النصوص بما في ذلك:
 * - حذف كلمات عشوائية حسب مستوى الصعوبة
 * - اكتشاف التردد والتلقين
 * - تتبع نقاط الضعف والإحصائيات
 * - حساب متوسط وقت الاستجابة
 *
 * @example
 * ```tsx
 * const {
 *   state,
 *   setScript,
 *   startSession,
 *   handleInput,
 *   submitAnswer
 * } = useMemorization();
 *
 * // بدء جلسة
 * setScript("النص المراد حفظه...");
 * const result = startSession();
 * if (!result.success) {
 *   console.error(result.error);
 * }
 * ```
 */
export function useMemorization(): UseMemorizationReturn {
  // الحالة الرئيسية
  const [script, setScriptState] = useState("");
  const [deletionLevel, setDeletionLevelState] = useState<DeletionLevel>(10);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isPromptMode, setIsPromptMode] = useState(false);
  const [currentLineIndex, setCurrentLineIndex] = useState(0);
  const [userInput, setUserInput] = useState("");
  const [hesitationDetected, setHesitationDetected] = useState(false);
  const [stats, setStats] = useState<MemorizationStats>(DEFAULT_STATS);
  const [showPromptHint, setShowPromptHint] = useState(false);
  const [currentPromptWord, setCurrentPromptWord] = useState("");

  // مراجع للتتبع
  const hesitationTimerRef = useRef<NodeJS.Timeout | null>(null);
  const attemptStartTimeRef = useRef<number>(0);
  const responseTimesRef = useRef<number[]>([]);
  const weakPointsMapRef = useRef<Map<string, number>>(new Map());

  /**
   * تنظيف مؤقت التردد
   */
  const clearHesitationTimer = useCallback(() => {
    if (hesitationTimerRef.current) {
      clearTimeout(hesitationTimerRef.current);
      hesitationTimerRef.current = null;
    }
  }, []);

  /**
   * تفعيل وضع التلقين
   */
  const activatePromptMode = useCallback(() => {
    setIsPromptMode(true);
    setHesitationDetected(true);
    setStats((prev) => ({
      ...prev,
      hesitationCount: prev.hesitationCount + 1,
    }));

    // عرض تلميح للكلمة التالية
    const lines = script.split("\n");
    const currentLine = lines[currentLineIndex];
    if (currentLine) {
      const words = currentLine.split(/\s+/);
      const firstWord = words[0];
      if (firstWord) {
        setCurrentPromptWord(firstWord);
        setShowPromptHint(true);
      }
    }
  }, [script, currentLineIndex]);

  /**
   * تعيين نص الحفظ
   */
  const setScript = useCallback((newScript: string) => {
    setScriptState(newScript);
  }, []);

  /**
   * تعيين مستوى الصعوبة
   */
  const setDeletionLevel = useCallback((level: DeletionLevel) => {
    setDeletionLevelState(level);
  }, []);

  /**
   * بدء جلسة الحفظ
   */
  const startSession = useCallback((): { success: boolean; error?: string } => {
    if (!script.trim()) {
      return { success: false, error: "الرجاء إدخال نص للحفظ أولاً" };
    }

    if (script.length < VALIDATION_CONSTANTS.MIN_SCRIPT_LENGTH) {
      return { success: false, error: "النص قصير جداً للحفظ" };
    }

    // إعادة تعيين الحالة
    setIsActive(true);
    setIsPaused(false);
    setCurrentLineIndex(0);
    setUserInput("");
    setHesitationDetected(false);
    setIsPromptMode(false);
    setShowPromptHint(false);
    attemptStartTimeRef.current = Date.now();
    responseTimesRef.current = [];
    weakPointsMapRef.current = new Map();
    setStats(DEFAULT_STATS);

    return { success: true };
  }, [script]);

  /**
   * إيقاف جلسة الحفظ
   */
  const stopSession = useCallback(() => {
    setIsActive(false);
    setIsPaused(false);
    clearHesitationTimer();

    // حساب متوسط وقت الاستجابة
    const times = responseTimesRef.current;
    if (times.length > 0) {
      const avgTime = times.reduce((a, b) => a + b, 0) / times.length;
      setStats((prev) => {
        const nextStats = {
          ...prev,
          averageResponseTime: Math.round((avgTime / 1000) * 10) / 10,
        };

        void postToBackend("/api/public/actorai/memorization", nextStats, {
          bestEffort: true,
        });

        return nextStats;
      });
    }
  }, [clearHesitationTimer]);

  /**
   * إيقاف مؤقت/استئناف
   */
  const togglePause = useCallback(() => {
    setIsPaused((prev) => !prev);
  }, []);

  /**
   * معالجة إدخال المستخدم
   */
  const handleInput = useCallback(
    (value: string) => {
      setUserInput(value);

      // إعادة تعيين مؤقت التردد
      clearHesitationTimer();

      // بدء مؤقت جديد للتردد
      hesitationTimerRef.current = setTimeout(() => {
        if (isActive && !isPaused) {
          activatePromptMode();
        }
      }, VALIDATION_CONSTANTS.HESITATION_TIMEOUT);
    },
    [isActive, isPaused, activatePromptMode, clearHesitationTimer]
  );

  /**
   * تقديم إجابة والتحقق منها
   */
  const submitAnswer = useCallback((): {
    correct: number;
    incorrect: number;
  } => {
    const responseTime = Date.now() - attemptStartTimeRef.current;
    responseTimesRef.current.push(responseTime);

    const lines = script.split("\n");
    const currentLine = lines[currentLineIndex];

    if (!currentLine) {
      return { correct: 0, incorrect: 0 };
    }

    const correctLineText = currentLine.trim();
    const userLineText = userInput.trim();

    // مقارنة كلمة بكلمة
    const correctWords = correctLineText.split(/\s+/);
    const userWords = userLineText.split(/\s+/);

    let correct = 0;
    let incorrect = 0;
    const weakWords: string[] = [];

    correctWords.forEach((word, index) => {
      if (
        userWords[index] &&
        userWords[index].toLowerCase() === word.toLowerCase()
      ) {
        correct++;
      } else {
        incorrect++;
        weakWords.push(word);

        // تتبع نقاط الضعف
        const currentCount = weakPointsMapRef.current.get(word) || 0;
        weakPointsMapRef.current.set(word, currentCount + 1);
      }
    });

    // تحديث الإحصائيات
    setStats((prev) => ({
      ...prev,
      totalAttempts: prev.totalAttempts + 1,
      correctWords: prev.correctWords + correct,
      incorrectWords: prev.incorrectWords + incorrect,
      weakPoints: [...new Set([...prev.weakPoints, ...weakWords])].slice(-10),
    }));

    // الانتقال للسطر التالي أو إنهاء الجلسة
    if (currentLineIndex < lines.length - 1) {
      setCurrentLineIndex((prev) => prev + 1);
      setUserInput("");
      attemptStartTimeRef.current = Date.now();
      setShowPromptHint(false);
      setIsPromptMode(false);
    } else {
      // انتهاء النص
      stopSession();
    }

    return { correct, incorrect };
  }, [script, currentLineIndex, userInput, stopSession]);

  /**
   * تحميل نص نموذجي
   */
  const loadSampleScript = useCallback(() => {
    setScriptState(SAMPLE_MEMORIZATION_SCRIPT);
  }, []);

  /**
   * زيادة مستوى الصعوبة
   */
  const increaseDifficulty = useCallback(() => {
    setDeletionLevelState((prev) => {
      if (prev === 10) return 50;
      if (prev === 50) return 90;
      return prev;
    });
  }, []);

  /**
   * الحصول على الأجزاء الصعبة
   */
  const getDifficultParts = useCallback((): string[] => {
    const entries = Array.from(weakPointsMapRef.current.entries());
    return entries
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([word]) => word);
  }, []);

  /**
   * معالجة النص للعرض (حذف كلمات)
   */
  const processTextForDisplay = useCallback((): string => {
    return createDeterministicMemorizationMask(script, deletionLevel);
  }, [script, deletionLevel]);

  /**
   * إعادة تعيين كل شيء
   */
  const reset = useCallback(() => {
    setScriptState("");
    setDeletionLevelState(10);
    setIsActive(false);
    setIsPaused(false);
    setIsPromptMode(false);
    setCurrentLineIndex(0);
    setUserInput("");
    setHesitationDetected(false);
    setStats(DEFAULT_STATS);
    setShowPromptHint(false);
    setCurrentPromptWord("");
    clearHesitationTimer();
    responseTimesRef.current = [];
    weakPointsMapRef.current = new Map();
  }, [clearHesitationTimer]);

  // تجميع الحالة
  const state: MemorizationState = {
    script,
    deletionLevel,
    isActive,
    isPaused,
    isPromptMode,
    currentLineIndex,
    userInput,
    hesitationDetected,
    stats,
    showPromptHint,
    currentPromptWord,
  };

  return {
    state,
    setScript,
    setDeletionLevel,
    startSession,
    stopSession,
    togglePause,
    handleInput,
    submitAnswer,
    loadSampleScript,
    increaseDifficulty,
    getDifficultParts,
    processTextForDisplay,
    reset,
  };
}

export default useMemorization;

/**
 * @fileoverview خطاف الإشعارات للتطبيق
 * يوفر واجهة موحدة لعرض الإشعارات للمستخدم مع دعم أنواع مختلفة
 * @reason فصل منطق الإشعارات لإعادة استخدامه عبر المكونات
 */

"use client";

import { useState, useCallback } from "react";
import type { NotificationType, Notification } from "../types";
import { VALIDATION_CONSTANTS } from "../types/constants";

/**
 * واجهة قيمة العودة من خطاف الإشعارات
 */
export interface UseNotificationReturn {
  /** الإشعار الحالي (أو null إذا لم يكن هناك إشعار) */
  notification: Notification | null;
  /** عرض إشعار جديد */
  showNotification: (type: NotificationType, message: string) => void;
  /** إخفاء الإشعار الحالي */
  hideNotification: () => void;
  /** عرض إشعار نجاح */
  showSuccess: (message: string) => void;
  /** عرض إشعار خطأ */
  showError: (message: string) => void;
  /** عرض إشعار معلومات */
  showInfo: (message: string) => void;
}

/**
 * خطاف إدارة الإشعارات
 * @description يوفر وظائف لعرض وإخفاء الإشعارات مع إخفاء تلقائي
 * @param duration - مدة عرض الإشعار بالمللي ثانية (اختياري)
 * @returns كائن يحتوي على حالة الإشعار والوظائف للتحكم بها
 *
 * @example
 * ```tsx
 * const { notification, showSuccess, showError } = useNotification();
 *
 * const handleSave = () => {
 *   try {
 *     // عملية الحفظ
 *     showSuccess("تم الحفظ بنجاح!");
 *   } catch (error) {
 *     showError("فشل الحفظ");
 *   }
 * };
 * ```
 */
export function useNotification(
  duration: number = VALIDATION_CONSTANTS.NOTIFICATION_DURATION
): UseNotificationReturn {
  const [notification, setNotification] = useState<Notification | null>(null);

  /**
   * عرض إشعار جديد
   * @param type - نوع الإشعار
   * @param message - رسالة الإشعار
   */
  const showNotification = useCallback(
    (type: NotificationType, message: string) => {
      setNotification({ type, message });

      // إخفاء الإشعار تلقائياً بعد المدة المحددة
      setTimeout(() => {
        setNotification(null);
      }, duration);
    },
    [duration]
  );

  /**
   * إخفاء الإشعار الحالي يدوياً
   */
  const hideNotification = useCallback(() => {
    setNotification(null);
  }, []);

  /**
   * عرض إشعار نجاح
   */
  const showSuccess = useCallback(
    (message: string) => {
      showNotification("success", message);
    },
    [showNotification]
  );

  /**
   * عرض إشعار خطأ
   */
  const showError = useCallback(
    (message: string) => {
      showNotification("error", message);
    },
    [showNotification]
  );

  /**
   * عرض إشعار معلومات
   */
  const showInfo = useCallback(
    (message: string) => {
      showNotification("info", message);
    },
    [showNotification]
  );

  return {
    notification,
    showNotification,
    hideNotification,
    showSuccess,
    showError,
    showInfo,
  };
}

export default useNotification;

"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import { postToBackend } from "@/lib/backend-api";

// ==================== أنواع البيانات ====================

export interface VoiceMetrics {
  // طبقة الصوت (Pitch)
  pitch: {
    value: number; // Hz
    level: "low" | "medium" | "high";
    label: string;
  };
  // شدة الصوت (Volume)
  volume: {
    value: number; // dB
    level: "quiet" | "normal" | "loud";
    label: string;
  };
  // سرعة الكلام (WPM)
  speechRate: {
    wpm: number;
    level: "slow" | "normal" | "fast";
    warning: string | null;
  };
  // وضوح المخارج (Articulation)
  articulation: {
    score: number; // 0-100
    level: "poor" | "fair" | "good" | "excellent";
    label: string;
  };
  // نمط التنفس
  breathing: {
    isBreathing: boolean;
    breathCount: number;
    warning: string | null;
    lastBreathTime: number;
  };
  // الوقفات الدرامية
  pauses: {
    count: number;
    averageDuration: number;
    isEffective: boolean;
    feedback: string;
  };
}

export interface VoiceAnalyticsState {
  isListening: boolean;
  isSupported: boolean;
  error: string | null;
  metrics: VoiceMetrics;
  waveformData: number[];
  frequencyData: number[];
  history: VoiceMetrics[];
}

const DEFAULT_METRICS: VoiceMetrics = {
  pitch: { value: 0, level: "medium", label: "متوسط" },
  volume: { value: 0, level: "normal", label: "عادي" },
  speechRate: { wpm: 0, level: "normal", warning: null },
  articulation: { score: 0, level: "fair", label: "جيد" },
  breathing: {
    isBreathing: false,
    breathCount: 0,
    warning: null,
    lastBreathTime: 0,
  },
  pauses: { count: 0, averageDuration: 0, isEffective: true, feedback: "" },
};

// ==================== دوال التحليل ====================

// تحويل التردد إلى طبقة الصوت
function analyzePitch(frequency: number): VoiceMetrics["pitch"] {
  if (frequency === 0) {
    return { value: 0, level: "medium", label: "لا يوجد صوت" };
  }

  if (frequency < 150) {
    return { value: frequency, level: "low", label: "منخفض" };
  } else if (frequency < 300) {
    return { value: frequency, level: "medium", label: "متوسط" };
  } else {
    return { value: frequency, level: "high", label: "مرتفع" };
  }
}

// تحليل مستوى الصوت
function analyzeVolume(decibels: number): VoiceMetrics["volume"] {
  if (decibels < -50) {
    return { value: decibels, level: "quiet", label: "هادئ" };
  } else if (decibels < -20) {
    return { value: decibels, level: "normal", label: "عادي" };
  } else {
    return { value: decibels, level: "loud", label: "مرتفع" };
  }
}

// تحليل سرعة الكلام
function analyzeSpeechRate(wpm: number): VoiceMetrics["speechRate"] {
  if (wpm < 100) {
    return {
      wpm,
      level: "slow",
      warning: "سرعتك بطيئة، حاول زيادة الإيقاع قليلاً",
    };
  } else if (wpm > 180) {
    return {
      wpm,
      level: "fast",
      warning: "⚠️ أنت تتحدث بسرعة! أبطئ لتحسين الوضوح",
    };
  } else {
    return { wpm, level: "normal", warning: null };
  }
}

// تحليل وضوح المخارج
function analyzeArticulation(clarity: number): VoiceMetrics["articulation"] {
  const score = Math.min(100, Math.max(0, clarity));

  if (score < 40) {
    return { score, level: "poor", label: "ضعيف - ركز على وضوح الحروف" };
  } else if (score < 60) {
    return { score, level: "fair", label: "مقبول - يمكن تحسينه" };
  } else if (score < 80) {
    return { score, level: "good", label: "جيد - استمر!" };
  } else {
    return { score, level: "excellent", label: "ممتاز! 🌟" };
  }
}

// خوارزمية بسيطة للكشف عن تردد الصوت الأساسي (autocorrelation)
function detectPitch(buffer: Float32Array, sampleRate: number): number {
  const SIZE = buffer.length;
  const MAX_SAMPLES = Math.floor(SIZE / 2);
  let bestOffset = -1;
  let bestCorrelation = 0;
  let rms = 0;
  let foundGoodCorrelation = false;
  const correlations = new Array(MAX_SAMPLES);

  // حساب RMS لتحديد إذا كان هناك صوت
  for (let i = 0; i < SIZE; i++) {
    const val = buffer[i] ?? 0;
    rms += val * val;
  }
  rms = Math.sqrt(rms / SIZE);

  // إذا كان الصوت ضعيفاً جداً، لا يوجد طبقة صوت
  if (rms < 0.01) return 0;

  let lastCorrelation = 1;
  for (let offset = 0; offset < MAX_SAMPLES; offset++) {
    let correlation = 0;

    for (let i = 0; i < MAX_SAMPLES; i++) {
      const val1 = buffer[i] ?? 0;
      const val2 = buffer[i + offset] ?? 0;
      correlation += Math.abs(val1 - val2);
    }
    correlation = 1 - correlation / MAX_SAMPLES;
    correlations[offset] = correlation;

    if (correlation > 0.9 && correlation > lastCorrelation) {
      foundGoodCorrelation = true;
      if (correlation > bestCorrelation) {
        bestCorrelation = correlation;
        bestOffset = offset;
      }
    } else if (foundGoodCorrelation) {
      const shift =
        (correlations[bestOffset + 1] - correlations[bestOffset - 1]) /
        correlations[bestOffset];
      return sampleRate / (bestOffset + 8 * shift);
    }
    lastCorrelation = correlation;
  }

  if (bestCorrelation > 0.01) {
    return sampleRate / bestOffset;
  }
  return 0;
}

// ==================== الـ Hook الرئيسي ====================

export function useVoiceAnalytics() {
  const [state, setState] = useState<VoiceAnalyticsState>({
    isListening: false,
    isSupported: typeof window !== "undefined" && !!navigator.mediaDevices,
    error: null,
    metrics: DEFAULT_METRICS,
    waveformData: [],
    frequencyData: [],
    history: [],
  });

  // مراجع للصوت
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  // مراجع للتتبع
  const silenceStartRef = useRef<number>(0);
  const pauseCountRef = useRef<number>(0);
  const pauseDurationsRef = useRef<number[]>([]);
  const wordCountRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);
  const lastSpeechTimeRef = useRef<number>(0);
  const breathCountRef = useRef<number>(0);
  const lastBreathTimeRef = useRef<number>(0);

  // تحديث المقاييس
  const updateMetrics = useCallback(() => {
    if (!analyserRef.current || !audioContextRef.current) return;

    const analyser = analyserRef.current;
    const bufferLength = analyser.fftSize;
    const dataArray = new Float32Array(bufferLength);
    const frequencyArray = new Uint8Array(analyser.frequencyBinCount);

    analyser.getFloatTimeDomainData(dataArray);
    analyser.getByteFrequencyData(frequencyArray);

    // حساب مستوى الصوت (RMS to dB)
    let sum = 0;
    for (let i = 0; i < bufferLength; i++) {
      const val = dataArray[i] ?? 0;
      sum += val * val;
    }
    const rms = Math.sqrt(sum / bufferLength);
    const decibels = 20 * Math.log10(rms + 0.0001);

    // الكشف عن تردد الصوت
    const frequency = detectPitch(
      dataArray,
      audioContextRef.current.sampleRate
    );

    // الكشف عن الصمت والوقفات
    const now = Date.now();
    const isSilent = rms < 0.01;

    if (isSilent) {
      if (silenceStartRef.current === 0) {
        silenceStartRef.current = now;
      }

      const silenceDuration = now - silenceStartRef.current;

      // الكشف عن التنفس (صمت قصير بين 300-800ms)
      if (
        silenceDuration > 300 &&
        silenceDuration < 800 &&
        lastBreathTimeRef.current + 2000 < now
      ) {
        breathCountRef.current++;
        lastBreathTimeRef.current = now;
      }

      // الكشف عن الوقفات الدرامية (أكثر من 500ms)
      if (silenceDuration > 500 && lastSpeechTimeRef.current > 0) {
        if (
          pauseDurationsRef.current[pauseDurationsRef.current.length - 1] !==
          silenceDuration
        ) {
          pauseCountRef.current++;
          pauseDurationsRef.current.push(silenceDuration);
        }
      }
    } else {
      silenceStartRef.current = 0;
      lastSpeechTimeRef.current = now;

      // تقدير عدد الكلمات (تقريبي)
      if (frequency > 80) {
        wordCountRef.current += 0.05; // تقدير تقريبي
      }
    }

    // حساب سرعة الكلام
    const elapsedMinutes = (now - startTimeRef.current) / 60000;
    const wpm =
      elapsedMinutes > 0
        ? Math.round(wordCountRef.current / elapsedMinutes)
        : 0;

    // حساب متوسط مدة الوقفات
    const avgPauseDuration =
      pauseDurationsRef.current.length > 0
        ? pauseDurationsRef.current.reduce((a, b) => a + b, 0) /
          pauseDurationsRef.current.length
        : 0;

    // تحديد فعالية الوقفات
    const pausesFeedback =
      avgPauseDuration > 2000
        ? "الوقفات طويلة جداً، حاول تقصيرها"
        : avgPauseDuration > 500
          ? "وقفات درامية جيدة! 👍"
          : "أضف وقفات درامية لتعزيز المعنى";

    // تنبيه التنفس
    const breathingWarning =
      now - lastBreathTimeRef.current > 15000 && rms > 0.01
        ? "⚠️ تذكر أن تتنفس! لا تحبس نفسك"
        : null;

    // حساب وضوح المخارج (تقدير بناءً على spectral clarity)
    const spectralSum = frequencyArray.reduce((a, b) => a + b, 0);
    const spectralAvg = spectralSum / frequencyArray.length;
    const articulationScore = Math.min(100, (spectralAvg / 128) * 100);

    // تحديث الحالة
    setState((prev) => ({
      ...prev,
      metrics: {
        pitch: analyzePitch(frequency),
        volume: analyzeVolume(decibels),
        speechRate: analyzeSpeechRate(wpm),
        articulation: analyzeArticulation(articulationScore),
        breathing: {
          isBreathing: isSilent && now - silenceStartRef.current > 300,
          breathCount: breathCountRef.current,
          warning: breathingWarning,
          lastBreathTime: lastBreathTimeRef.current,
        },
        pauses: {
          count: pauseCountRef.current,
          averageDuration: avgPauseDuration,
          isEffective: avgPauseDuration > 400 && avgPauseDuration < 2500,
          feedback: pausesFeedback,
        },
      },
      waveformData: Array.from(dataArray.slice(0, 128)),
      frequencyData: Array.from(frequencyArray.slice(0, 64)),
    }));

    // استمرار التحليل
    animationFrameRef.current = requestAnimationFrame(updateMetrics);
  }, []);

  // بدء الاستماع
  const startListening = useCallback(async () => {
    try {
      // إعادة تعيين المتتبعات
      silenceStartRef.current = 0;
      pauseCountRef.current = 0;
      pauseDurationsRef.current = [];
      wordCountRef.current = 0;
      startTimeRef.current = Date.now();
      lastSpeechTimeRef.current = 0;
      breathCountRef.current = 0;
      lastBreathTimeRef.current = Date.now();

      // الحصول على إذن الميكروفون
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      streamRef.current = stream;

      // إنشاء سياق الصوت
      const audioContext = new AudioContext();
      audioContextRef.current = audioContext;

      // إنشاء المحلل
      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.8;
      analyserRef.current = analyser;

      // توصيل الميكروفون بالمحلل
      const source = audioContext.createMediaStreamSource(stream);
      source.connect(analyser);

      setState((prev) => ({
        ...prev,
        isListening: true,
        error: null,
      }));

      // بدء التحليل
      updateMetrics();
    } catch (error) {
      setState((prev) => ({
        ...prev,
        error: error instanceof Error ? error.message : "فشل الوصول للميكروفون",
      }));
    }
  }, [updateMetrics]);

  // إيقاف الاستماع
  const stopListening = useCallback(() => {
    // إيقاف التحليل
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }

    // إغلاق سياق الصوت
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }

    // إيقاف البث
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }

    // حفظ المقاييس في التاريخ + إرسالها للباك إند بشكل best-effort
    setState((prev) => {
      void postToBackend("/api/public/actorai/voice-analytics", prev.metrics, {
        bestEffort: true,
      });

      return {
        ...prev,
        isListening: false,
        history: [...prev.history, prev.metrics],
      };
    });
  }, []);

  // إعادة التعيين
  const reset = useCallback(() => {
    stopListening();
    setState({
      isListening: false,
      isSupported: typeof window !== "undefined" && !!navigator.mediaDevices,
      error: null,
      metrics: DEFAULT_METRICS,
      waveformData: [],
      frequencyData: [],
      history: [],
    });
  }, [stopListening]);

  // تنظيف عند إزالة المكون
  useEffect(() => {
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((track) => track.stop());
      }
    };
  }, []);

  return {
    ...state,
    startListening,
    stopListening,
    reset,
  };
}

export default useVoiceAnalytics;

