"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { CardSpotlight } from "@/components/aceternity/card-spotlight";
import {
  buildExportFileName,
  buildTakeInsights,
  inferExtensionFromMimeType,
  pickSupportedMimeType,
  readStoredSelfTapeTakes,
  SELF_TAPE_STORAGE_KEY,
  supportsMediaCapture,
  writeStoredSelfTapeTakes,
  type PersistedSelfTapeTake,
} from "../../lib/self-tape";
import {
  loadRemoteAppState,
  persistRemoteAppState,
} from "@/lib/app-state-client";

type ActiveTool =
  | "teleprompter"
  | "recorder"
  | "comparison"
  | "notes"
  | "export";
type CameraState = "idle" | "requesting" | "ready" | "error";
type NotificationState = {
  type: "success" | "error" | "info";
  message: string;
} | null;
type NoteType = "emotion" | "delivery" | "timing" | "movement" | "improvement";
type NoteSeverity = "positive" | "neutral" | "needs_work";

interface TakeNote {
  id: string;
  timestamp: number;
  type: NoteType;
  content: string;
  severity: NoteSeverity;
  autoGenerated: boolean;
}

interface Take extends PersistedSelfTapeTake {
  notes: TakeNote[];
  videoUrl?: string;
}

interface TeleprompterSettings {
  speed: number;
  fontSize: number;
  mirrorMode: boolean;
  highlightCurrentLine: boolean;
  autoScroll: boolean;
  countdownSeconds: number;
}

interface ExportSettings {
  quality: "casting" | "high" | "medium";
  format: "mp4" | "mov" | "webm";
  includeSlate: boolean;
  slateDuration: number;
  actorName: string;
  projectName: string;
  roleName: string;
  agencyName: string;
}

interface ComparisonView {
  leftTakeId: string | null;
  rightTakeId: string | null;
  syncPlayback: boolean;
}

interface PendingTake {
  id: string;
  name: string;
  recordedAt: string;
  mimeType: string;
  teleprompterUsed: boolean;
}

interface SelfTapeSuiteSnapshot {
  scriptText: string;
  takes: PersistedSelfTapeTake[];
  activeTool: ActiveTool;
  teleprompterSettings: TeleprompterSettings;
  exportSettings: ExportSettings;
  comparisonView: ComparisonView;
  notesTakeId: string | null;
}

const RECORDING_MIME_CANDIDATES = [
  "video/webm;codecs=vp9,opus",
  "video/webm;codecs=vp8,opus",
  "video/webm",
];

const NOTE_TYPE_LABELS: Record<NoteType, string> = {
  emotion: "💫 عاطفة",
  delivery: "🎤 إلقاء",
  timing: "⏱️ توقيت",
  movement: "🎭 حركة",
  improvement: "💡 تحسين",
};

