                  className="bg-black/18 border-purple-500/30"
                >
                  <CardHeader className="pb-3">
                    <CardTitle className="text-lg text-white">
                      {take?.name ?? "اختر تسجيلاً"}
                    </CardTitle>
                    {take && (
                      <CardDescription className="text-purple-300">
                        {formatRecordedAt(take.recordedAt)}
                      </CardDescription>
                    )}
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {take?.videoUrl ? (
                      <video
                        src={take.videoUrl}
                        controls
                        muted={!comparisonView.syncPlayback}
                        className="aspect-video w-full rounded-[22px] bg-black object-cover"
                      />
                    ) : (
                      <div className="flex aspect-video items-center justify-center rounded-[22px] border border-dashed border-purple-500/20 bg-black/40 text-center text-white/55">
                        <div>
                          <p>لا يوجد ملف فيديو مباشر لهذا الجانب.</p>
                          <p className="text-sm">
                            ستبقى المقارنة الرقمية متاحة من خلال التقييمات
                            والملاحظات.
                          </p>
                        </div>
                      </div>
                    )}

                    {take && (
                      <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                          <span className="text-white/55">التقييم</span>
                          <span
                            className={`font-bold ${getScoreColor(take.score)}`}
                          >
                            {take.score ?? 0}%
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-white/55">المدة</span>
                          <span className="text-white">
                            {formatTime(take.duration)}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-white/55">الملاحظات</span>
                          <span className="text-purple-300">
                            {take.notes.length} ملاحظة
                          </span>
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>

            {leftTake && rightTake && (
              <CardSpotlight className="overflow-hidden rounded-[22px] bg-black/18 border-purple-500/30">
                <Card className="bg-black/18 border-purple-500/30 bg-transparent">
                  <CardHeader>
                    <CardTitle className="text-white">
                      📊 ملخص المقارنة
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
                      <div className="rounded-xl bg-black/14 p-4 text-center">
                        <p className="mb-2 text-sm text-white/55">
                          فرق التقييم
                        </p>
                        <p className="text-3xl font-bold text-green-400">
                          {(rightTake.score ?? 0) - (leftTake.score ?? 0) > 0
                            ? "+"
                            : ""}
                          {(rightTake.score ?? 0) - (leftTake.score ?? 0)}%
                        </p>
                      </div>
                      <div className="rounded-xl bg-black/14 p-4 text-center">
                        <p className="mb-2 text-sm text-white/55">فرق المدة</p>
                        <p className="text-3xl font-bold text-purple-400">
                          {Math.abs(rightTake.duration - leftTake.duration)}ث
                        </p>
                      </div>
                      <div className="rounded-xl bg-black/14 p-4 text-center">
                        <p className="mb-2 text-sm text-white/55">
                          النسخة الأفضل
                        </p>
                        <p className="text-xl font-bold text-yellow-400">
                          {(rightTake.score ?? 0) > (leftTake.score ?? 0)
                            ? rightTake.name
                            : leftTake.name}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </CardSpotlight>
            )}
          </div>
        )}

        {activeTool === "notes" && (
          <CardSpotlight className="overflow-hidden rounded-[22px] bg-black/18 border-purple-500/30">
            <Card className="bg-black/18 border-purple-500/30 bg-transparent">
              <CardHeader>
                <CardTitle className="text-white">
                  📝 الملاحظات وتحسين الأداء
                </CardTitle>
                <CardDescription className="text-purple-300">
                  الملاحظات التلقائية تُبنى من نتيجة التسجيل، ويمكنك إضافة
                  ملاحظاتك اليدوية فوقها.
                </CardDescription>
              </CardHeader>
              <CardContent>
                {notesTake ? (
                  <Tabs
                    value={notesTakeId ?? availableTakes[0]?.id ?? ""}
                    onValueChange={(value) => setNotesTakeId(value)}
                  >
                    <TabsList className="mb-4 h-auto flex-wrap gap-2 border border-purple-500/30 bg-black/14 p-2">
                      {availableTakes.map((take) => (
                        <TabsTrigger
                          key={take.id}
                          value={take.id}
                          className="text-white data-[state=active]:bg-purple-600"
                        >
                          {take.name}
                        </TabsTrigger>
                      ))}
                    </TabsList>

                    {availableTakes.map((take) => (
                      <TabsContent key={take.id} value={take.id}>
                        <div className="space-y-6">
                          <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
                            <div className="rounded-xl bg-black/14 p-4 text-center">
                              <p className="text-sm text-white/55">
                                التقييم العام
                              </p>
                              <p
                                className={`text-3xl font-bold ${getScoreColor(take.score)}`}
                              >
                                {take.score ?? 0}%
                              </p>
                            </div>
                            <div className="rounded-xl bg-black/14 p-4 text-center">
                              <p className="text-sm text-white/55">إيجابي</p>
                              <p className="text-3xl font-bold text-green-400">
                                {
                                  take.notes.filter(
                                    (note) => note.severity === "positive"
                                  ).length
                                }
                              </p>
                            </div>
                            <div className="rounded-xl bg-black/14 p-4 text-center">
                              <p className="text-sm text-white/55">
                                تحتاج تحسين
                              </p>
                              <p className="text-3xl font-bold text-yellow-400">
                                {
                                  take.notes.filter(
                                    (note) => note.severity === "needs_work"
                                  ).length
                                }
                              </p>
                            </div>
                            <div className="rounded-xl bg-black/14 p-4 text-center">
                              <p className="text-sm text-white/55">المدة</p>
                              <p className="text-3xl font-bold text-purple-400">
                                {formatTime(take.duration)}
                              </p>
                            </div>
                          </div>

                          <div className="space-y-3">
                            {take.notes.map((note) => (
                              <div
                                key={note.id}
                                className={`rounded-xl border p-4 ${getSeverityContainerClass(
                                  note.severity
                                )}`}
                              >
                                <div className="mb-2 flex items-start justify-between gap-3">
                                  <div className="flex items-center gap-2">
                                    <Badge
                                      className={NOTE_TYPE_COLOR[note.type]}
                                    >
                                      {NOTE_TYPE_LABELS[note.type]}
                                    </Badge>
                                    <span className="text-sm text-white/55">
                                      @{formatTime(note.timestamp)}
                                    </span>
                                  </div>
                                  <Badge
                                    variant="outline"
                                    className="border-purple-500/50 text-purple-300"
                                  >
                                    {note.autoGenerated ? "محلي" : "يدوي"}
                                  </Badge>
                                </div>
                                <p className="text-white">{note.content}</p>
                              </div>
                            ))}
                          </div>

                          <div className="rounded-xl border border-purple-500/30 bg-black/14 p-4">
                            <Label className="mb-3 block text-purple-300">
                              أضف ملاحظة يدوية
                            </Label>
                            <div className="grid grid-cols-1 gap-3 md:grid-cols-[220px_1fr_auto]">
                              <Select
                                value={
                                  manualNoteTypes[take.id] ?? "improvement"
                                }
                                onValueChange={(value) =>
                                  setManualNoteTypes((previous) => ({
                                    ...previous,
                                    [take.id]: value as NoteType,
                                  }))
                                }
                              >
                                <SelectTrigger className="border-purple-500/30 bg-black/18 text-white">
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent className="border-purple-500/30 bg-black/14">
                                  {Object.entries(NOTE_TYPE_LABELS).map(
                                    ([value, label]) => (
                                      <SelectItem
                                        key={value}
                                        value={value}
                                        className="text-white"
                                      >
                                        {label}
                                      </SelectItem>
                                    )
                                  )}
                                </SelectContent>
                              </Select>

                              <Input
                                value={manualNoteDrafts[take.id] ?? ""}
                                onChange={(event) =>
                                  setManualNoteDrafts((previous) => ({
                                    ...previous,
                                    [take.id]: event.target.value,
                                  }))
                                }
                                placeholder="اكتب الملاحظة التي تريد حفظها مع هذا التسجيل"
                                className="border-purple-500/30 bg-black/18 text-white"
                              />

                              <Button
                                className="bg-purple-600 text-white hover:bg-purple-700"
                                onClick={() => addManualNote(take.id)}
                              >
                                إضافة
                              </Button>
                            </div>
                          </div>
                        </div>
                      </TabsContent>
                    ))}
                  </Tabs>
                ) : (
                  <div className="py-12 text-center text-white/55">
                    لا توجد تسجيلات لعرض ملاحظاتها بعد.
                  </div>
                )}
              </CardContent>
            </Card>
          </CardSpotlight>
        )}

        {activeTool === "export" && (
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            <CardSpotlight className="overflow-hidden rounded-[22px] bg-black/18 border-purple-500/30">
              <Card className="bg-black/18 border-purple-500/30 bg-transparent">
                <CardHeader>
                  <CardTitle className="text-white">
                    ⚙️ إعدادات التصدير
                  </CardTitle>
                  <CardDescription className="text-purple-300">
                    التصدير الحالي ينزل الملف الأصلي المسجل كما التقطه المتصفح،
                    مع استخدام الاسم المنظف وبيانات السليت داخل اسم الملف.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                  <div className="space-y-2">
                    <Label className="text-purple-300">جودة الإخراج</Label>
                    <Select
                      value={exportSettings.quality}
                      onValueChange={(value) =>
                        setExportSettings((previous) => ({
                          ...previous,
                          quality: value as ExportSettings["quality"],
                        }))
                      }
                    >
                      <SelectTrigger className="border-purple-500/30 bg-black/14 text-white">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="border-purple-500/30 bg-black/14">
                        <SelectItem value="casting" className="text-white">
                          Casting
                        </SelectItem>
                        <SelectItem value="high" className="text-white">
                          High
                        </SelectItem>
                        <SelectItem value="medium" className="text-white">
                          Medium
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label className="text-purple-300">الصيغة المفضلة</Label>
                    <Select
                      value={exportSettings.format}
                      onValueChange={(value) =>
                        setExportSettings((previous) => ({
                          ...previous,
                          format: value as ExportSettings["format"],
                        }))
                      }
                    >
                      <SelectTrigger className="border-purple-500/30 bg-black/14 text-white">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="border-purple-500/30 bg-black/14">
                        <SelectItem value="webm" className="text-white">
                          WebM
                        </SelectItem>
                        <SelectItem value="mp4" className="text-white">
                          MP4
                        </SelectItem>
                        <SelectItem value="mov" className="text-white">
                          MOV
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="rounded-xl bg-black/14 p-4">
                    <div className="mb-4 flex items-center justify-between">
                      <Label className="text-purple-300">
                        تضمين بيانات السليت
                      </Label>
                      <Button
                        variant="outline"
                        size="sm"
                        className={
                          exportSettings.includeSlate
                            ? "border-purple-600 bg-purple-600 text-white"
                            : "border-purple-500/50 text-white"
                        }
                        onClick={() =>
                          setExportSettings((previous) => ({
                            ...previous,
                            includeSlate: !previous.includeSlate,
                          }))
                        }
                      >
                        {exportSettings.includeSlate ? "✓ مفعل" : "معطل"}
                      </Button>
                    </div>

                    {exportSettings.includeSlate && (
                      <div className="space-y-4">
                        <div>
                          <Label className="text-sm text-purple-300">
                            اسم الممثل
                          </Label>
                          <Input
                            value={exportSettings.actorName}
                            onChange={(event) =>
                              setExportSettings((previous) => ({
                                ...previous,
                                actorName: event.target.value,
                              }))
                            }
                            className="mt-1 border-purple-500/30 bg-black/18 text-white"
                            placeholder="اسم الممثل"
                          />
                        </div>
                        <div>
                          <Label className="text-sm text-purple-300">
                            اسم المشروع
                          </Label>
                          <Input
                            value={exportSettings.projectName}
                            onChange={(event) =>
                              setExportSettings((previous) => ({
                                ...previous,
                                projectName: event.target.value,
                              }))
                            }
                            className="mt-1 border-purple-500/30 bg-black/18 text-white"
                            placeholder="اسم الفيلم أو المشروع"
                          />
                        </div>
                        <div>
                          <Label className="text-sm text-purple-300">
                            اسم الدور
                          </Label>
                          <Input
                            value={exportSettings.roleName}
                            onChange={(event) =>
                              setExportSettings((previous) => ({
                                ...previous,
                                roleName: event.target.value,
                              }))
                            }
                            className="mt-1 border-purple-500/30 bg-black/18 text-white"
                            placeholder="اسم الشخصية"
                          />
                        </div>
                        <div>
                          <Label className="text-sm text-purple-300">
                            الوكالة
                          </Label>
                          <Input
                            value={exportSettings.agencyName}
                            onChange={(event) =>
                              setExportSettings((previous) => ({
                                ...previous,
                                agencyName: event.target.value,
                              }))
                            }
                            className="mt-1 border-purple-500/30 bg-black/18 text-white"
                            placeholder="اختياري"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label className="text-sm text-purple-300">
                            مدة السليت: {exportSettings.slateDuration} ثوان
                          </Label>
                          <Slider
                            value={[exportSettings.slateDuration]}
                            min={3}
                            max={10}
                            step={1}
                            onValueChange={([value]) =>
                              setExportSettings((previous) => ({
                                ...previous,
                                slateDuration: value ?? previous.slateDuration,
                              }))
                            }
                          />
                        </div>
                      </div>
                    )}
                  </div>

                  {exportingTakeId && (
                    <div className="rounded-xl border border-purple-500/30 bg-black/14 p-4">
                      <p className="mb-3 text-white">
                        جاري إعداد الملف للتنزيل...
                      </p>
                      <Progress value={exportProgress} className="h-3" />
                      <p className="mt-2 text-sm text-purple-300">
                        {exportProgress}%
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            </CardSpotlight>

            <CardSpotlight className="overflow-hidden rounded-[22px] bg-black/18 border-purple-500/30">
              <Card className="bg-black/18 border-purple-500/30 bg-transparent">
                <CardHeader>
                  <CardTitle className="text-white">
                    📤 تنزيل التسجيلات
                  </CardTitle>
                  <CardDescription className="text-purple-300">
                    التسجيلات التي تحتوي على ملف فيديو حي فقط ستكون قابلة
                    للتنزيل.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  {availableTakes.map((take) => {
                    const canDownload = blobRegistryRef.current.has(take.id);
                    return (
                      <div
                        key={take.id}
                        className="rounded-xl border border-purple-500/20 bg-black/14 p-4"
                      >
                        <div className="flex items-center justify-between gap-4">
                          <div>
                            <h4 className="font-medium text-white">
                              {take.name}
                            </h4>
                            <p className="text-sm text-white/55">
                              {formatTime(take.duration)} • {take.score ?? 0}%
                            </p>
                          </div>

                          <Button
                            className="bg-green-600 text-white hover:bg-green-700"
                            onClick={() => {
                              void exportTake(take.id);
                            }}
                            disabled={
                              !canDownload || exportingTakeId === take.id
                            }
                          >
                            {canDownload ? "📤 تنزيل" : "غير متاح"}
                          </Button>
                        </div>

                        {!canDownload && (
                          <p className="mt-3 text-sm text-yellow-300">
                            هذا التسجيل محفوظ كمرجع وصفي فقط بعد إعادة التحميل،
                            لذا لا يملك ملف فيديو صالحاً للتنزيل.
                          </p>
                        )}
                      </div>
                    );
                  })}

                  {bestExportableTake && (
                    <div className="border-t border-purple-500/30 pt-4">
                      <Button
                        className="w-full bg-purple-600 text-white hover:bg-purple-700"
                        onClick={() => {
                          void exportTake(bestExportableTake.id);
                        }}
                        disabled={Boolean(exportingTakeId)}
                      >
                        ⭐ تنزيل أفضل تسجيل قابل للتصدير
                      </Button>
                    </div>
                  )}
                </CardContent>
              </Card>
            </CardSpotlight>
          </div>
        )}
      </main>

      <footer className="mt-8 border-t border-purple-500/30 bg-black/30">
        <div className="container mx-auto flex flex-col items-center justify-between gap-4 px-4 py-6 md:flex-row">
          <p className="text-sm text-white/55">
            Self-Tape Suite © 2025 - جزء من منصة ActorAI العربية
          </p>
          <div className="flex items-center gap-4">
            <Badge
              variant="outline"
              className="border-purple-500/50 text-purple-300"
            >
              تخزين محلي + مزامنة خلفية
            </Badge>
            <Badge
              variant="outline"
              className="border-green-500/50 text-green-300"
            >
              v2
            </Badge>
