}

"use client";

import { useCallback, useEffect, useReducer, useRef, useState } from "react";

import {
  AuthRequiredError,
  exportAnalysis,
  fetchAnalysisSnapshot,
  retryStation as retryStationApi,
  startAnalysisStream,
  downloadBlob,
} from "../lib/api";
import { openSse, type SseHandle } from "../lib/sse-client";
import {
  initialState,
  reducer,
  selectAllCompleted,
  selectIsRunning,
  selectProgress,
  type MachineState,
} from "../lib/state-machine";
import { reportTelemetry } from "../lib/telemetry";
import type { StationId, StreamEvent } from "../lib/types";

interface UseAnalysisMachineOptions {
  resumeAnalysisId?: string | null;
  onAuthRequired?: (status: number) => void;
}

interface UseAnalysisMachineReturn {
  state: MachineState;
  progress: number;
  isRunning: boolean;
  allCompleted: boolean;
  start: (input: { text: string; projectId?: string; projectName?: string }) => Promise<void>;
  reset: () => void;
  retryStation: (stationId: StationId, text: string) => Promise<void>;
  exportAs: (format: "json" | "docx" | "pdf") => Promise<void>;
}

export function useAnalysisMachine(
  opts: UseAnalysisMachineOptions = {}
): UseAnalysisMachineReturn {
  const [state, dispatch] = useReducer(reducer, initialState);
  const [streamUrl, setStreamUrl] = useState<string | null>(null);
  const sseRef = useRef<SseHandle | null>(null);
  const lastTextRef = useRef<string>("");

  // --- subscribe to the SSE channel whenever the URL changes ---
  useEffect(() => {
    if (!streamUrl) return;
    const handle = openSse({
      url: streamUrl,
      onEvent: (e: StreamEvent) => dispatch({ type: "STREAM_EVENT", event: e }),
      onError: () => {
        reportTelemetry("analysis.sse.error", { url: streamUrl });
      },
    });
    sseRef.current = handle;
    return () => {
      handle.close();
      sseRef.current = null;
    };
  }, [streamUrl]);

  // --- restore a previous analysis from the server (no local storage) ---
  useEffect(() => {
    let cancelled = false;
    if (!opts.resumeAnalysisId) return;
    void (async () => {
      try {
        const snap = await fetchAnalysisSnapshot(opts.resumeAnalysisId!);
        if (cancelled) return;
        dispatch({ type: "SNAPSHOT_LOADED", snapshot: snap });
        if (snap.status === "running") {
          setStreamUrl(
            `/api/analysis/seven-stations/stream/${encodeURIComponent(snap.analysisId)}`
          );
        }
      } catch (err) {
        if (cancelled) return;
        if (err instanceof AuthRequiredError) {
          opts.onAuthRequired?.(err.status);
          return;
        }
        reportTelemetry("analysis.snapshot.failed", {
          analysisId: opts.resumeAnalysisId,
        });
      }
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [opts.resumeAnalysisId]);

  const start = useCallback(
    async (input: { text: string; projectId?: string; projectName?: string }) => {
      try {
        lastTextRef.current = input.text;
        dispatch({
          type: "START_REQUESTED",
          projectId: input.projectId ?? null,
          projectName: input.projectName ?? "تحليل درامي شامل",
          textLength: input.text.length,
        });
        reportTelemetry("analysis.start", { textLength: input.text.length });
        const { analysisId } = await startAnalysisStream(input);
        dispatch({ type: "SESSION_CREATED", analysisId });
        setStreamUrl(
          `/api/analysis/seven-stations/stream/${encodeURIComponent(analysisId)}`
        );
      } catch (err) {
        if (err instanceof AuthRequiredError) {
          opts.onAuthRequired?.(err.status);
          dispatch({ type: "SESSION_FAILED", message: "يلزم تسجيل الدخول" });
          return;
        }
        const message = err instanceof Error ? err.message : "تعذر بدء التحليل";
        dispatch({ type: "SESSION_FAILED", message });
        reportTelemetry("analysis.start.failed", { message });
      }
    },
    [opts]
  );

  const reset = useCallback(() => {
    sseRef.current?.close();
    sseRef.current = null;
    setStreamUrl(null);
    lastTextRef.current = "";
    dispatch({ type: "RESET" });
  }, []);

  const retryStation = useCallback(
    async (stationId: StationId, text: string) => {
      if (!state.analysisId) return;
      dispatch({ type: "RETRY_REQUESTED", stationId });
      reportTelemetry("analysis.retry", { stationId });
      try {
        await retryStationApi(state.analysisId, stationId, text || lastTextRef.current);
      } catch (err) {
        if (err instanceof AuthRequiredError) {
          opts.onAuthRequired?.(err.status);
          return;
        }
        // The error event will be emitted on the SSE channel by the server.
        reportTelemetry("analysis.retry.failed", {
          stationId,
          message: err instanceof Error ? err.message : "unknown",
        });
      }
    },
    [opts, state.analysisId]
  );

  const exportAs = useCallback(
    async (format: "json" | "docx" | "pdf") => {
      if (!state.analysisId) return;
      reportTelemetry("analysis.export", { format });
      try {
        const blob = await exportAnalysis(state.analysisId, format);
        const ext = format;
        downloadBlob(blob, `analysis-${state.analysisId}.${ext}`);
      } catch (err) {
        if (err instanceof AuthRequiredError) {
          opts.onAuthRequired?.(err.status);
          return;
        }
        reportTelemetry("analysis.export.failed", {
          format,
          message: err instanceof Error ? err.message : "unknown",
        });
      }
    },
    [opts, state.analysisId]
  );

  return {
    state,
    progress: selectProgress(state),
    isRunning: selectIsRunning(state),
    allCompleted: selectAllCompleted(state),
    start,
    reset,
    retryStation,
    exportAs,
  };
}

/**
 * Thin EventSource wrapper that records the latest received event id so the
 * browser's native EventSource can resume cleanly via `Last-Event-ID` on
 * reconnect. Exposes a typed event stream callback.
 */

import type { StreamEvent } from "./types";

export interface SseHandle {
  close(): void;
}

export interface OpenSseOptions {
  url: string;
  onEvent: (event: StreamEvent) => void;
  onError?: (err: Event) => void;
  onOpen?: () => void;
}

export function openSse(opts: OpenSseOptions): SseHandle {
  if (typeof window === "undefined" || typeof EventSource === "undefined") {
    return { close: () => undefined };
  }

  const es = new EventSource(opts.url, { withCredentials: true });
  // Backend uses named events (event: pipeline.started, etc). Listen to them
  // explicitly so the browser's lastEventId tracking remains correct.
  const eventNames: ReadonlyArray<StreamEvent["type"]> = [
    "pipeline.started",
    "pipeline.warning",
    "pipeline.completed",
    "station.started",
    "station.progress",
    "station.token",
    "station.completed",
    "station.error",
  ];

  const handlers = new Map<string, (e: MessageEvent) => void>();
  for (const name of eventNames) {
    const h = (e: MessageEvent) => {
      try {
        const payload = JSON.parse(e.data) as StreamEvent;
        opts.onEvent(payload);
      } catch {
        // ignore malformed payloads
      }
    };
    handlers.set(name, h);
    es.addEventListener(name, h as EventListener);
  }

  if (opts.onOpen) es.addEventListener("open", opts.onOpen);
  if (opts.onError) es.addEventListener("error", opts.onError);

  return {
    close() {
      for (const [name, h] of handlers) {
        es.removeEventListener(name, h as EventListener);
      }
      es.close();
    },
  };
}

/**
 * Shared types for the analysis surface. The shapes mirror the backend's
 * `analysisStream.registry.ts` so events and snapshots can flow end-to-end
 * without translation.
 */

export type StationId = 1 | 2 | 3 | 4 | 5 | 6 | 7;

export type StationStatus =
  | "idle"
  | "queued"
  | "running"
  | "completed"
  | "failed";

export type PipelineStatus =
  | "idle"
  | "running"
  | "completed"
  | "failed"
  | "cancelled";

export interface StationState {
  id: StationId;
  name: string;
  status: StationStatus;
  progress: number;
  startedAt: string | null;
  completedAt: string | null;
  output: unknown | null;
  error: string | null;
  confidence: number | null;
}

export interface PipelineWarning {
  id: string;
  stationId: StationId | null;
  message: string;
  severity: "info" | "warn" | "error";
  at: string;
}

export interface AnalysisSnapshot {
  analysisId: string;
  projectId: string | null;
  projectName: string;
  status: PipelineStatus;
  startedAt: string;
  completedAt: string | null;
  textLength: number;
  stations: StationState[];
  warnings: PipelineWarning[];
  finalReport: string | null;
  metadata: Record<string, unknown>;
}

export type StreamEvent =
  | {
      type: "pipeline.started";
      analysisId: string;
      projectName: string;
      capabilities: { exports: string[] };
    }
  | { type: "pipeline.warning"; warning: PipelineWarning }
  | {
      type: "pipeline.completed";
      status: "completed" | "failed";
      durationMs: number;
    }
  | {
      type: "station.started";
      stationId: StationId;
      name: string;
      at: string;
    }
  | { type: "station.progress"; stationId: StationId; progress: number }
  | { type: "station.token"; stationId: StationId; token: string }
  | {
      type: "station.completed";
      stationId: StationId;
      output: unknown;
      confidence: number | null;
      durationMs: number;
    }
  | { type: "station.error"; stationId: StationId; message: string };

export const STATION_IDS: readonly StationId[] = [1, 2, 3, 4, 5, 6, 7] as const;

export const STATION_NAMES: Record<StationId, string> = {
  1: "التحليل العميق للشخصيات",
  2: "التحليل المتقدم للحوار",
  3: "التحليل البصري والسينمائي",
  4: "تحليل الموضوعات والرسائل",
  5: "التحليل الثقافي والتاريخي",
  6: "تحليل قابلية الإنتاج",
  7: "تحليل الجمهور والتقرير النهائي",
};

export interface AnalysisRelationship {
  source: string;
  target: string;
  kind: string;
  weight: number;
}

