// SettingsPanel.tsx
// لوحة إعدادات التطبيق

"use client";

import React, { useState, useCallback } from "react";
import { AppSettings } from "@/app/(main)/arabic-creative-writing-studio/types";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import { CardSpotlight } from "@/components/aceternity/card-spotlight";

export interface SettingsPanelProps {
  settings: AppSettings;
  onSettingsUpdate: (newSettings: Partial<AppSettings>) => void;
  onTestConnection: () => Promise<void>;
}

export const SettingsPanel: React.FC<SettingsPanelProps> = ({
  settings,
  onSettingsUpdate,
  onTestConnection,
}) => {
  const [isTestingConnection, setIsTestingConnection] =
    useState<boolean>(false);
  const [showApiKey, setShowApiKey] = useState<boolean>(false);
  const [tempSettings, setTempSettings] = useState<AppSettings>(settings);

  // اختبار اتصال API
  const handleTestConnection = useCallback(async () => {
    if (!tempSettings.geminiApiKey) {
      alert("يرجى إدخال مفتاح API أولاً");
      return;
    }

    setIsTestingConnection(true);
    try {
      await onTestConnection();
    } finally {
      setIsTestingConnection(false);
    }
  }, [tempSettings.geminiApiKey, onTestConnection]);

  // حفظ الإعدادات
  const handleSaveSettings = useCallback(() => {
    onSettingsUpdate(tempSettings);
  }, [tempSettings, onSettingsUpdate]);

  // تحديث إعداد مؤقت
  const updateTempSetting = useCallback(
    <K extends keyof AppSettings>(key: K, value: AppSettings[K]) => {
      setTempSettings((prev) => ({ ...prev, [key]: value }));
    },
    []
  );

  return (
    <div className="max-w-4xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-8">⚙️ إعدادات التطبيق</h2>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* إعدادات Gemini API */}
        <CardSpotlight className="rounded-[22px]">
          <CardHeader>
            <CardTitle className="text-white">🤖 إعدادات Gemini API</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="api-key">🔑 مفتاح API</Label>
              <div className="relative">
                <Input
                  id="api-key"
                  type={showApiKey ? "text" : "password"}
                  value={tempSettings.geminiApiKey || ""}
                  onChange={(e) =>
                    updateTempSetting("geminiApiKey", e.target.value)
                  }
                  placeholder="أدخل مفتاح Gemini API هنا..."
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="absolute left-2 top-1/2 transform -translate-y-1/2"
                  onClick={() => setShowApiKey(!showApiKey)}
                >
                  {showApiKey ? "👁️" : "👁️‍🗨️"}
                </Button>
              </div>
            </div>

            <div>
              <Label htmlFor="model-select">🧠 النموذج</Label>
              <Select
                value={tempSettings.geminiModel}
                onValueChange={(value) =>
                  updateTempSetting("geminiModel", value)
                }
              >
                <SelectTrigger id="model-select">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="gemini-2.5-pro">Gemini 2.5 Pro</SelectItem>
                  <SelectItem value="gemini-1.5-pro">Gemini 1.5 Pro</SelectItem>
                  <SelectItem value="gemini-1.5-flash">
                    Gemini 1.5 Flash
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label>🌡️ درجة الحرارة: {tempSettings.geminiTemperature}</Label>
              <Slider
                value={[tempSettings.geminiTemperature]}
                onValueChange={(value) =>
                  updateTempSetting("geminiTemperature", value[0] ?? 0.7)
                }
                max={2}
                min={0}
                step={0.1}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/45 mt-1">
                <span>محافظ (0.0)</span>
                <span>متوازن (1.0)</span>
                <span>إبداعي (2.0)</span>
              </div>
            </div>

            <div>
              <Label>📏 أقصى عدد رموز: {tempSettings.geminiMaxTokens}</Label>
              <Slider
                value={[tempSettings.geminiMaxTokens]}
                onValueChange={(value) =>
                  updateTempSetting("geminiMaxTokens", value[0] ?? 8192)
                }
                max={32768}
                min={1024}
                step={1024}
                className="w-full"
              />
              <div className="text-xs text-white/45 mt-1">1K - 32K رمز</div>
            </div>

            <Button
              onClick={handleTestConnection}
              disabled={isTestingConnection || !tempSettings.geminiApiKey}
              className="w-full"
            >
              {isTestingConnection
                ? "🔄 جاري الاختبار..."
                : "🧪 اختبار الاتصال"}
            </Button>

            {/* دليل الحصول على API Key */}
            <div className="mt-6 p-4 bg-white/[0.04] backdrop-blur-2xl border border-white/8 rounded-[22px]">
              <h4 className="font-semibold text-white mb-2">
                📋 دليل الإعداد السريع:
              </h4>
              <ol className="text-sm text-white/68 space-y-1">
                <li>
                  1. قم بزيارة{" "}
                  <a
                    href="https://ai.google.dev"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="underline"
                  >
                    ai.google.dev
                  </a>
                </li>
                <li>2. اضغط على &quot;Get API Key&quot;</li>
                <li>3. أنشئ مفتاح API جديد</li>
                <li>4. انسخ والصق المفتاح أعل��ه</li>
                <li>5. اضغط &quot;اختبار الاتصال&quot; للتأكد</li>
              </ol>
            </div>
          </CardContent>
        </CardSpotlight>

        {/* إعدادات الواجهة */}
        <CardSpotlight className="rounded-[22px]">
          <CardHeader>
            <CardTitle className="text-white">🎨 إعدادات الواجهة</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="language-select">🌍 اللغة</Label>
              <Select
                value={tempSettings.language}
                onValueChange={(value) =>
                  updateTempSetting("language", value as "ar" | "en")
                }
              >
                <SelectTrigger id="language-select">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ar">العربية</SelectItem>
                  <SelectItem value="en">English</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="block text-sm font-medium text-white/68 mb-2">
                🌙 المظهر
              </Label>
              <div className="grid grid-cols-3 gap-2">
                {(["light", "dark", "auto"] as const).map((theme) => (
                  <Button
                    key={theme}
                    variant={
                      tempSettings.theme === theme ? "default" : "outline"
                    }
                    onClick={() => updateTempSetting("theme", theme)}
                    className="px-3 py-2"
                  >
                    {theme === "light"
                      ? "☀️ فاتح"
                      : theme === "dark"
                        ? "🌙 داكن"
                        : "🔄 تلقائي"}
                  </Button>
                ))}
              </div>
            </div>

            <div>
              <Label className="block text-sm font-medium text-white/68 mb-2">
                📝 حجم الخط
              </Label>
              <div className="grid grid-cols-3 gap-2">
                {(["small", "medium", "large"] as const).map((size) => (
                  <Button
                    key={size}
                    variant={
                      tempSettings.fontSize === size ? "default" : "outline"
                    }
                    onClick={() => updateTempSetting("fontSize", size)}
                    className="px-3 py-2"
                  >
                    {size === "small"
                      ? "صغير"
                      : size === "medium"
                        ? "متوسط"
                        : "كبير"}
                  </Button>
                ))}
              </div>
            </div>

            <div>
              <Label className="block text-sm font-medium text-white/68 mb-2">
                ↔️ اتجاه النص
              </Label>
              <div className="grid grid-cols-2 gap-2">
                {(["rtl", "ltr"] as const).map((direction) => (
                  <Button
                    key={direction}
                    variant={
                      tempSettings.textDirection === direction
                        ? "default"
                        : "outline"
                    }
                    onClick={() =>
                      updateTempSetting("textDirection", direction)
                    }
                    className="px-3 py-2"
                  >
                    {direction === "rtl" ? "⬅️ من اليمين" : "➡️ من اليسار"}
                  </Button>
                ))}
              </div>
            </div>
          </CardContent>
        </CardSpotlight>

        {/* إعدادات الحفظ */}
        <CardSpotlight className="rounded-[22px]">
          <CardHeader>
            <CardTitle className="text-white">💾 إعدادات الحفظ</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <Label className="text-sm font-medium text-white/68">
                  الحفظ التلقائي
                </Label>
                <p className="text-xs text-white/45">
                  حفظ تلقائي للمشاريع أثناء الكتابة
                </p>
              </div>
              <Switch
                checked={tempSettings.autoSave}
                onCheckedChange={(checked) =>
                  updateTempSetting("autoSave", checked)
                }
              />
            </div>

            {tempSettings.autoSave && (
              <div>
                <Label>
                  فترة الحفظ: {tempSettings.autoSaveInterval / 1000} ثانية
                </Label>
                <Slider
                  value={[tempSettings.autoSaveInterval]}
                  onValueChange={(value) =>
                    updateTempSetting("autoSaveInterval", value[0] ?? 30000)
                  }
                  max={300000}
                  min={10000}
                  step={10000}
                  className="w-full"
                />
                <div className="flex justify-between text-xs text-white/45 mt-1">
                  <span>10 ثوان</span>
                  <span>5 دقائق</span>
                </div>
              </div>
            )}
          </CardContent>
        </CardSpotlight>

        {/* معلومات النظام */}
        <CardSpotlight className="rounded-[22px]">
          <CardHeader>
            <CardTitle className="text-white">ℹ️ معلومات النظام</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3 text-sm">
              <div className="flex justify-between">
                <span className="text-white/55">إصدار التطبيق:</span>
                <span className="font-medium">1.0.0</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/55">نموذج الذكاء الاصطناعي:</span>
                <span className="font-medium">{tempSettings.geminiModel}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/55">حالة API:</span>
                <span
                  className={`font-medium ${tempSettings.geminiApiKey ? "text-green-600" : "text-red-600"}`}
                >
                  {tempSettings.geminiApiKey ? "✅ متصل" : "❌ غير متصل"}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/55">اللغة:</span>
                <span className="font-medium">
                  {tempSettings.language === "ar" ? "العربية" : "English"}
                </span>
              </div>
            </div>
          </CardContent>
        </CardSpotlight>
      </div>

      {/* أزرار الحفظ والإلغاء */}
      <div className="flex justify-end space-x-4 space-x-reverse mt-8">
        <Button onClick={() => setTempSettings(settings)} variant="outline">
          ↩️ إلغاء التغييرات
        </Button>
        <Button onClick={handleSaveSettings}>💾 حفظ الإعدادات</Button>
      </div>
    </div>
  );
};

export default SettingsPanel;

import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { WritingEditor } from "@/app/(main)/arabic-creative-writing-studio/components/WritingEditor";
import type { TextAnalysis } from "@/app/(main)/arabic-creative-writing-studio/types";

vi.mock("@/components/aceternity/card-spotlight", () => ({
  CardSpotlight: ({ children, className }: any) => (
    <div className={className}>{children}</div>
  ),
}));

vi.mock("@/components/ui/dropdown-menu", () => ({
  DropdownMenu: ({ children }: any) => <div>{children}</div>,
  DropdownMenuTrigger: ({ children }: any) => children,
  DropdownMenuContent: ({ children }: any) => <div>{children}</div>,
  DropdownMenuItem: ({ children, onSelect }: any) => (
    <button type="button" onClick={onSelect}>
      {children}
    </button>
  ),
}));

const baseProject = {
  id: "project-1",
  title: "مشروع تجريبي",
  content: "هذا نص أولي.",
  promptId: "prompt-1",
  genre: "fantasy" as const,
  wordCount: 3,
  characterCount: 12,
  paragraphCount: 1,
  createdAt: new Date("2026-04-13T10:00:00.000Z"),
  updatedAt: new Date("2026-04-13T10:00:00.000Z"),
  tags: ["تجريب"],
  isCompleted: false,
};

const basePrompt = {
  id: "prompt-1",
  title: "مشهد افتتاحي",
  description: "محفز لاختبار المحرر",
  genre: "fantasy" as const,
  technique: "dialogue_driven" as const,
  difficulty: "intermediate" as const,
  tags: ["اختبار"],
  arabic: "اكتب مشهداً افتتاحياً يتبدل فيه معنى الحوار بين سطر وآخر.",
  tips: ["ابدأ من لحظة توتر مباشرة."],
};

const analysisResult: TextAnalysis = {
  wordCount: 120,
  characterCount: 640,
  paragraphCount: 4,
  sentenceCount: 10,
  averageWordsPerSentence: 12,
  averageSentencesPerParagraph: 3,
  readabilityScore: 78,
  vocabularyDiversity: 71,
  sentenceVariety: 76,
  emotionalTone: "positive",
  qualityMetrics: { clarity: 82, creativity: 74, coherence: 69, impact: 71 },
  suggestions: ["أعد صياغة الفقرة الثالثة لتقوية التماسك."],
};

function buildProps(overrides: Record<string, unknown> = {}) {
  return {
    project: baseProject,
    selectedPrompt: basePrompt,
    onProjectChange: vi.fn(),
    onSave: vi.fn(),
    onAnalyze: vi.fn().mockResolvedValue(analysisResult),
    onExport: vi.fn((project, format) => ({
      success: true,
      format,
      filename: `${project.title}.${format}`,
      message: `تم تجهيز ${format.toUpperCase()} للتنزيل.`,
    })),
    onOpenSettings: vi.fn(),
    analysisAvailable: true,
    analysisBlockedReason:
      "تحليل النص يحتاج مفتاح Gemini صالحاً. أضفه من الإعدادات أولاً ثم عُد إلى المحرر.",
    activeChallenge: null,
    settings: {
      language: "ar" as const,
      theme: "dark" as const,
      textDirection: "rtl" as const,
      fontSize: "medium" as const,
      autoSave: true,
      autoSaveInterval: 30000,
      geminiApiKey: "test-key",
      geminiModel: "gemini-2.5-pro",
      geminiTemperature: 0.7,
      geminiMaxTokens: 8192,
    },
    loading: false,
    ...overrides,
  };
}

describe("WritingEditor", () => {
  it("يعرض سبب تعطيل التحليل ويفتح الإعدادات عند غياب المفتاح", () => {
    const base = buildProps();
    const props = buildProps({
      analysisAvailable: false,
      settings: { ...base.settings, geminiApiKey: undefined },
    });

    render(<WritingEditor {...props} />);

    expect(screen.getByText(props.analysisBlockedReason)).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: "🔍 تحليل النص" })
    ).toBeDisabled();

    fireEvent.click(screen.getByRole("button", { name: "افتح الإعدادات" }));
    expect(props.onOpenSettings).toHaveBeenCalledTimes(1);
  });

  it("يحفظ آخر نسخة مع العنوان والمحتوى والإحصاءات المحدثة", () => {
    const props = buildProps();

    render(<WritingEditor {...props} />);

    fireEvent.change(screen.getByDisplayValue("مشروع تجريبي"), {
      target: { value: "عنوان نهائي" },
    });
    fireEvent.change(screen.getByDisplayValue("هذا نص أولي."), {
      target: { value: "هذا نص جديد تماما" },
    });
    fireEvent.click(screen.getByRole("button", { name: "💾 حفظ" }));

    expect(props.onSave).toHaveBeenCalledWith(
      expect.objectContaining({
        title: "عنوان نهائي",
        content: "هذا نص جديد تماما",
        wordCount: 4,
        paragraphCount: 1,
      })
    );
    expect(screen.getByText("تم حفظ المشروع يدوياً.")).toBeInTheDocument();
  });

  it("يشغّل التحليل ويعرض ملخصاً واضحاً واقتراحات مفهومة", async () => {
    const props = buildProps();

    render(<WritingEditor {...props} />);
    fireEvent.click(screen.getByRole("button", { name: "🔍 تحليل النص" }));

    await waitFor(() => {
      expect(props.onAnalyze).toHaveBeenCalledWith("هذا نص أولي.");
    });

    expect(
      screen.getByText(
        "النص جيد، لكنه يحتاج صقلاً محدوداً قبل النسخة النهائية."
      )
    ).toBeInTheDocument();
    expect(screen.getByText("قابلية القراءة")).toBeInTheDocument();
    expect(screen.getByText("إيجابية")).toBeInTheDocument();
    expect(
      screen.getByText("أعد صياغة الفقرة الثالثة لتقوية التماسك.")
    ).toBeInTheDocument();
    expect(
      screen.getByText("اكتمل التحليل. متوسط الجودة الحالي 74/100.")
    ).toBeInTheDocument();
  });

  it.each([
    ["txt", "📄 نص خالص"],
    ["json", "📋 بيانات منظمة"],
  ] as const)("يصدر بصيغة %s ويعرض نتيجة واضحة", async (format, label) => {
    const props = buildProps();

    render(<WritingEditor {...props} />);
    fireEvent.click(screen.getByRole("button", { name: label }));

    await waitFor(() => {
      expect(props.onExport).toHaveBeenCalledWith(baseProject, format);
    });

    expect(
      screen.getByText(`تم تجهيز ${format.toUpperCase()} للتنزيل.`)
    ).toBeInTheDocument();
  });
});

