import { logger } from "@/lib/ai/utils/logger";

// dataManager.ts
// مدير البيانات المحلية لاستوديو الكتابة الإبداعية

import {
  CreativeProject,
  CreativePrompt,
  AppSettings,
} from "@/app/(main)/arabic-creative-writing-studio/types";

export class DataManager {
  private static instance: DataManager;
  private storage: Map<string, any> = new Map();
  private readonly STORAGE_KEYS = {
    PROJECTS: "creative_projects",
    SETTINGS: "app_settings",
    PROMPTS: "custom_prompts",
    HISTORY: "writing_history",
  };

  private constructor() {
    this.initializeStorage();
  }

  static getInstance(): DataManager {
    if (!DataManager.instance) {
      DataManager.instance = new DataManager();
    }
    return DataManager.instance;
  }

  // تهيئة التخزين
  private initializeStorage(): void {
    // في البيئة المحدودة، نستخدم الذاكرة
    // يمكن توسيعها لاحقاً لدعم localStorage أو IndexedDB
    this.storage.set(this.STORAGE_KEYS.PROJECTS, []);
    this.storage.set(this.STORAGE_KEYS.SETTINGS, this.getDefaultSettings());
    this.storage.set(this.STORAGE_KEYS.PROMPTS, []);
    this.storage.set(this.STORAGE_KEYS.HISTORY, []);
  }

  // الحصول على الإعدادات الافتراضية
  private getDefaultSettings(): AppSettings {
    return {
      language: "ar",
      theme: "dark",
      textDirection: "rtl",
      fontSize: "medium",
      autoSave: true,
      autoSaveInterval: 30000,
      geminiModel: "gemini-2.5-pro",
      geminiTemperature: 0.7,
      geminiMaxTokens: 8192,
    };
  }

  // حفظ المشاريع
  saveProjects(projects: CreativeProject[]): void {
    this.storage.set(this.STORAGE_KEYS.PROJECTS, projects);
  }

  // استرجاع المشاريع
  getProjects(): CreativeProject[] {
    return this.storage.get(this.STORAGE_KEYS.PROJECTS) || [];
  }

  // حفظ مشروع واحد
  saveProject(project: CreativeProject): void {
    const projects = this.getProjects();
    const existingIndex = projects.findIndex((p) => p.id === project.id);

    if (existingIndex >= 0) {
      projects[existingIndex] = { ...project, updatedAt: new Date() };
    } else {
      projects.push(project);
    }

    this.saveProjects(projects);
  }

  // حذف مشروع
  deleteProject(projectId: string): void {
    const projects = this.getProjects();
    const filteredProjects = projects.filter((p) => p.id !== projectId);
    this.saveProjects(filteredProjects);
  }

  // حفظ الإعدادات
  saveSettings(settings: AppSettings): void {
    this.storage.set(this.STORAGE_KEYS.SETTINGS, settings);
  }

  // استرجاع الإعدادات
  getSettings(): AppSettings {
    return (
      this.storage.get(this.STORAGE_KEYS.SETTINGS) || this.getDefaultSettings()
    );
  }

  // حفظ محفز مخصص
  saveCustomPrompt(prompt: CreativePrompt): void {
    const prompts = this.getCustomPrompts();
    prompts.push(prompt);
    this.storage.set(this.STORAGE_KEYS.PROMPTS, prompts);
  }

  // استرجاع المحفزات المخصصة
  getCustomPrompts(): CreativePrompt[] {
    return this.storage.get(this.STORAGE_KEYS.PROMPTS) || [];
  }

  // إضافة إلى التاريخ
  addToHistory(entry: any): void {
    const history = this.getHistory();
    history.unshift({ ...entry, timestamp: new Date() });

    // الاحتفاظ بآخر 50 عنصر فقط
    if (history.length > 50) {
      history.splice(50);
    }

    this.storage.set(this.STORAGE_KEYS.HISTORY, history);
  }

  // استرجاع التاريخ
  getHistory(): any[] {
    return this.storage.get(this.STORAGE_KEYS.HISTORY) || [];
  }

  // تصدير جميع البيانات
  exportAllData(): string {
    const data = {
      projects: this.getProjects(),
      settings: this.getSettings(),
      customPrompts: this.getCustomPrompts(),
      history: this.getHistory(),
      exportDate: new Date().toISOString(),
    };

    return JSON.stringify(data, null, 2);
  }

  // استيراد البيانات
  importData(jsonData: string): boolean {
    try {
      const data = JSON.parse(jsonData);

      if (data.projects) {
        this.saveProjects(data.projects);
      }

      if (data.settings) {
        this.saveSettings({ ...this.getDefaultSettings(), ...data.settings });
      }

      if (data.customPrompts) {
        this.storage.set(this.STORAGE_KEYS.PROMPTS, data.customPrompts);
      }

      if (data.history) {
        this.storage.set(this.STORAGE_KEYS.HISTORY, data.history);
      }

      return true;
    } catch (error) {
      logger.error("خطأ في استيراد البيانات:", error);
      return false;
    }
  }

  // مسح جميع البيانات
  clearAllData(): void {
    this.initializeStorage();
  }

  // إحصائيات الاستخدام
  getUsageStatistics(): any {
    const projects = this.getProjects();
    const history = this.getHistory();

    return {
      totalProjects: projects.length,
      completedProjects: projects.filter((p) => p.isCompleted).length,
      totalWords: projects.reduce((sum, p) => sum + p.wordCount, 0),
      averageWordsPerProject:
        projects.length > 0
          ? Math.round(
              projects.reduce((sum, p) => sum + p.wordCount, 0) /
                projects.length
            )
          : 0,
      mostUsedGenre: this.getMostUsedGenre(projects),
      writingSessions: history.length,
      lastActivity:
        projects.length > 0
          ? Math.max(...projects.map((p) => new Date(p.updatedAt).getTime()))
          : null,
    };
  }

  // النوع الأكثر استخداماً
  private getMostUsedGenre(projects: CreativeProject[]): string {
    const genreCounts: { [key: string]: number } = {};

    projects.forEach((project) => {
      genreCounts[project.genre] = (genreCounts[project.genre] || 0) + 1;
    });

    const mostUsed = Object.entries(genreCounts).sort(
      ([, a], [, b]) => b - a
    )[0];

    return mostUsed ? mostUsed[0] : "غير محدد";
  }

  // نسخة احتياطية تلقائية
  createBackup(): string {
    const backup = {
      version: "1.0",
      timestamp: new Date().toISOString(),
      data: this.exportAllData(),
    };

    return JSON.stringify(backup);
  }

  // استعادة من النسخة الاحتياطية
  restoreFromBackup(backupData: string): boolean {
    try {
      const backup = JSON.parse(backupData);

      if (backup.data) {
        return this.importData(backup.data);
      }

      return false;
    } catch (error) {
      logger.error("خطأ في استعادة النسخة الاحتياطية:", error);
      return false;
    }
  }
}

export default DataManager;

import { CreativeProject } from "@/app/(main)/arabic-creative-writing-studio/types";

export type ExportFormat = "txt" | "json" | "html" | "rtf";

export interface ExportResult {
  success: boolean;
  format: ExportFormat;
  filename: string;
  message: string;
}

const EXPORT_MIME_TYPES: Record<ExportFormat, string> = {
  txt: "text/plain;charset=utf-8",
  json: "application/json;charset=utf-8",
  html: "text/html;charset=utf-8",
  rtf: "application/rtf;charset=utf-8",
};

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function sanitizeFilename(title: string): string {
  const trimmedTitle = title.trim();

  if (!trimmedTitle) {
    return "creative-writing-project";
  }

  return trimmedTitle
    .replace(/[<>:"/\\|?*\u0000-\u001f]/g, "")
    .replace(/\s+/g, "_")
    .slice(0, 80);
}

function buildExportBody(
  project: CreativeProject,
  format: ExportFormat
): string {
  switch (format) {
    case "txt":
      return `${project.title}\n\n${project.content}`;
    case "json":
      return JSON.stringify(project, null, 2);
    case "html":
      return `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
  <meta charset="UTF-8" />
  <title>${escapeHtml(project.title)}</title>
  <style>
    body { font-family: 'Cairo', Arial, sans-serif; padding: 24px; background: #0f172a; color: #f8fafc; line-height: 1.9; }
    h1 { color: #f472b6; }
    .meta { color: #cbd5f5; margin-bottom: 20px; font-size: 14px; }
    .content { white-space: pre-wrap; }
  </style>
</head>
<body>
  <h1>${escapeHtml(project.title)}</h1>
  <div class="meta">الكلمات: ${project.wordCount} | الفقرات: ${project.paragraphCount}</div>
  <div class="content">${escapeHtml(project.content)}</div>
</body>
</html>`;
    case "rtf":
      return `{\\rtf1\\ansi\\deff0 {\\fonttbl {\\f0 Times New Roman;}}\\f0\\fs24 ${project.title}\\par ${project.content.replace(/\n/g, "\\par ")}}`;
  }
}

export function exportProjectDocument(
  project: CreativeProject,
  format: ExportFormat
): ExportResult {
  const filename = `${sanitizeFilename(project.title)}.${format}`;

  if (
    typeof window === "undefined" ||
    typeof document === "undefined" ||
    typeof URL === "undefined" ||
    typeof Blob === "undefined"
  ) {
    return {
      success: false,
      format,
      filename,
      message: "فشل التصدير لأن واجهة المتصفح غير متاحة في هذه البيئة.",
    };
  }

  const content = buildExportBody(project, format);
  const blob = new Blob([content], { type: EXPORT_MIME_TYPES[format] });
  const url = URL.createObjectURL(blob);

  try {
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.rel = "noopener";
    link.style.display = "none";

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    return {
      success: true,
      format,
      filename,
      message: `تم تجهيز الملف ${filename} للتنزيل بصيغة ${format.toUpperCase()}.`,
    };
  } catch {
    return {
      success: false,
      format,
      filename,
      message: `فشل تصدير الملف ${filename}. حاول مرة أخرى.`,
    };
  } finally {
    window.setTimeout(() => URL.revokeObjectURL(url), 0);
  }
}

