    location.type
  );

  return (
    <CardSpotlight className="overflow-hidden rounded-[22px] border border-white/8 bg-white/[0.04] p-5 backdrop-blur-xl">
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
