// CineArchitect AI - Virtual Cinema Skills Trainer
// المدرب الافتراضي للمهارات السينمائية

import { Plugin, PluginInput, PluginOutput } from "../../types";
import { v4 as uuidv4 } from "uuid";

interface TrainingScenario {
  id: string;
  name: string;
  nameAr: string;
  category: TrainingCategory;
  difficulty: "beginner" | "intermediate" | "advanced" | "expert";
  duration: number;
  objectives: string[];
  equipment: string[];
  vrRequired: boolean;
  aiAssisted: boolean;
}

type TrainingCategory =
  | "camera-operation"
  | "lighting-setup"
  | "sound-recording"
  | "directing"
  | "set-design"
  | "color-grading"
  | "visual-effects"
  | "production-management";

interface VREquipment {
  id: string;
  name: string;
  nameAr: string;
  type: string;
  model3D: string;
  interactions: string[];
  tutorials: TutorialStep[];
}

interface TutorialStep {
  step: number;
  title: string;
  titleAr: string;
  description: string;
  descriptionAr: string;
  action: string;
  validationCriteria: string;
}

interface TraineeProgress {
  traineeId: string;
  name: string;
  completedScenarios: CompletedScenario[];
  skillLevels: Record<TrainingCategory, number>;
  totalTrainingHours: number;
  achievements: Achievement[];
  currentStreak: number;
}

interface CompletedScenario {
  scenarioId: string;
  completedAt: Date;
  score: number;
  timeSpent: number;
  feedback: string[];
}

interface Achievement {
  id: string;
  name: string;
  nameAr: string;
  earnedAt: Date;
  category: string;
}

interface PerformanceEvaluation {
  overallScore: number;
  categoryScores: Record<string, number>;
  strengths: string[];
  areasForImprovement: string[];
  recommendations: string[];
  nextScenarios: string[];
}

