"use client";

/**
 * الصفحة: brain-storm-ai / DebatePanel
 * الهوية: لوحة نقاش داخلية بطابع شبكي داكن مع رسائل مميزة بصريًا حسب النوع
 * المتغيرات الخاصة المضافة: تعتمد على متغيرات الصفحة المحقونة أعلى الشجرة
 * مكونات Aceternity المستخدمة: CardSpotlight
 */

import { MessageSquare, Shield } from "lucide-react";
import {
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import type { DebateMessage } from "../../types";
import { CardSpotlight } from "@/components/aceternity/card-spotlight";

interface DebatePanelProps {
  messages: DebateMessage[];
}

function getMessageStyle(type: DebateMessage["type"]) {
  switch (type) {
    case "proposal":
      return "border-blue-400/20 bg-blue-400/10";
    case "decision":
      return "border-purple-400/20 bg-purple-400/10";
    default:
      return "border-emerald-400/20 bg-emerald-400/10";
  }
}

function getMessageTypeLabel(type: DebateMessage["type"]) {
  switch (type) {
    case "proposal":
      return "اقتراح";
    case "decision":
      return "قرار";
    default:
      return "موافقة";
  }
}

export default function DebatePanel({ messages }: DebatePanelProps) {
  if (messages.length === 0) return null;

  return (
    <CardSpotlight className="overflow-hidden rounded-[28px] border border-white/8 bg-black/24 backdrop-blur-2xl">
      <CardHeader>
        <CardTitle className="flex items-center gap-3 text-white">
          <MessageSquare className="w-6 h-6 text-[var(--page-accent,#3b5bdb)]" />
          النقاش
        </CardTitle>
        <CardDescription className="text-white/55">
          {messages.length} رسالة
        </CardDescription>
      </CardHeader>
      <CardContent>
        <ScrollArea className="h-[300px]">
          <div className="space-y-3">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`rounded-2xl border p-4 ${getMessageStyle(msg.type)}`}
              >
                <div className="flex items-center justify-between mb-2 gap-3">
                  <span className="font-medium text-sm text-white">
                    {msg.agentName}
                  </span>
                  <div className="flex items-center gap-2">
                    {msg.uncertainty ? (
                      <TooltipProvider>
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <Badge
                              variant="outline"
                              className={`text-xs ${
                                msg.uncertainty.confidence > 0.7
                                  ? "bg-emerald-500/10"
                                  : msg.uncertainty.confidence > 0.4
                                    ? "bg-amber-500/10"
                                    : "bg-red-500/10"
                              }`}
                            >
                              <Shield className="w-3 h-3 mr-1" />
                              {(msg.uncertainty.confidence * 100).toFixed(0)}%
                            </Badge>
                          </TooltipTrigger>
                          <TooltipContent>
                            <p>
                              الثقة: {msg.uncertainty.confidence.toFixed(2)}
                            </p>
                            <p>النوع: {msg.uncertainty.type}</p>
                          </TooltipContent>
                        </Tooltip>
                      </TooltipProvider>
                    ) : null}
                    <Badge variant="outline" className="text-xs bg-white/5">
                      {getMessageTypeLabel(msg.type)}
                    </Badge>
                  </div>
                </div>
                <p className="text-sm leading-7 text-white/72">{msg.message}</p>
              </div>
            ))}
          </div>
        </ScrollArea>
      </CardContent>
    </CardSpotlight>
  );
}

"use client";

/**
 * @module ExportControls
 * @description أزرار تصدير نتائج الجلسة الحالية مع ردود فعل مرئية
 */

import { useCallback, useState } from "react";
import {
  exportToJSON,
  exportToMarkdown,
  copyToClipboard,
} from "../../lib/export";
import type { ExportResult } from "../../lib/export";
import type { Session, DebateMessage } from "../../types";

interface ExportControlsProps {
  session: Session;
  messages: DebateMessage[];
}

type FeedbackState = {
  type: "idle" | "success" | "error";
  message?: string;
};

const FEEDBACK_TIMEOUT = 2500;

function feedbackFromResult(
  result: ExportResult,
  successMsg: string
): FeedbackState {
  return result.ok
    ? { type: "success", message: successMsg }
    : { type: "error", message: result.error || "فشل التصدير" };
}

export function ExportControls({ session, messages }: ExportControlsProps) {
  const [copyFeedback, setCopyFeedback] = useState<FeedbackState>({
    type: "idle",
  });
  const [jsonFeedback, setJsonFeedback] = useState<FeedbackState>({
    type: "idle",
  });
  const [mdFeedback, setMdFeedback] = useState<FeedbackState>({
    type: "idle",
  });

  const handleExportJSON = useCallback((): void => {
    const result = exportToJSON(session, messages);
    setJsonFeedback(feedbackFromResult(result, "تم التصدير"));
    setTimeout(() => setJsonFeedback({ type: "idle" }), FEEDBACK_TIMEOUT);
  }, [session, messages]);

  const handleExportMD = useCallback((): void => {
    const result = exportToMarkdown(session, messages);
    setMdFeedback(feedbackFromResult(result, "تم التصدير"));
    setTimeout(() => setMdFeedback({ type: "idle" }), FEEDBACK_TIMEOUT);
  }, [session, messages]);

  const handleCopy = useCallback(async (): Promise<void> => {
    const result = await copyToClipboard(session, messages);
    setCopyFeedback(feedbackFromResult(result, "تم النسخ!"));
    setTimeout(() => setCopyFeedback({ type: "idle" }), FEEDBACK_TIMEOUT);
  }, [session, messages]);

  return (
    <div className="flex items-center gap-2 flex-wrap">
      <span className="text-xs text-white/55 font-cairo">تصدير:</span>

      <button
        onClick={handleExportJSON}
        className={`px-3 py-1.5 text-xs border rounded-md transition font-cairo ${
          jsonFeedback.type === "success"
            ? "border-green-500 bg-green-500/10 text-green-300"
            : jsonFeedback.type === "error"
              ? "border-red-500 bg-red-500/10 text-red-300"
              : "border-border bg-background text-foreground hover:bg-white/6"
        }`}
        title="تصدير بصيغة JSON"
      >
        {jsonFeedback.type === "success"
          ? "تم ✓"
          : jsonFeedback.type === "error"
            ? jsonFeedback.message
            : "JSON"}
      </button>

      <button
        onClick={handleExportMD}
        className={`px-3 py-1.5 text-xs border rounded-md transition font-cairo ${
          mdFeedback.type === "success"
            ? "border-green-500 bg-green-500/10 text-green-300"
            : mdFeedback.type === "error"
              ? "border-red-500 bg-red-500/10 text-red-300"
              : "border-border bg-background text-foreground hover:bg-white/6"
        }`}
        title="تصدير بصيغة Markdown"
      >
        {mdFeedback.type === "success"
          ? "تم ✓"
          : mdFeedback.type === "error"
            ? mdFeedback.message
            : "Markdown"}
      </button>

      <button
        onClick={handleCopy}
        className={`px-3 py-1.5 text-xs border rounded-md transition font-cairo ${
          copyFeedback.type === "success"
            ? "border-green-500 bg-green-500/10 text-green-300"
            : copyFeedback.type === "error"
              ? "border-red-500 bg-red-500/10 text-red-300"
              : "border-border bg-background text-foreground hover:bg-white/6"
        }`}
        title="نسخ الملخص"
      >
        {copyFeedback.type === "success"
          ? "تم النسخ!"
          : copyFeedback.type === "error"
            ? copyFeedback.message
            : "نسخ"}
      </button>
    </div>
  );
}

"use client";

/**
 * الصفحة: brain-storm-ai / FeaturesGrid
 * الهوية: شبكة مزايا داخلية بطابع شبكي تحليلي متسق مع القشرة الداكنة الجديدة
 * المتغيرات الخاصة المضافة: تعتمد على متغيرات الصفحة المحقونة أعلى الشجرة
 * مكونات Aceternity المستخدمة: CardSpotlight
 */

import { Brain, Layers, Zap, Shield } from "lucide-react";
import type { BrainstormAgentStats } from "../../types";
import { CardSpotlight } from "@/components/aceternity/card-spotlight";

interface FeaturesGridProps {
  agentStats: BrainstormAgentStats;
}

export default function FeaturesGrid({ agentStats }: FeaturesGridProps) {
  const features = [
    {
      icon: <Brain className="w-6 h-6" />,
      title: "ذكاء اصطناعي متقدم",
      desc: `${agentStats.total} وكيل متخصص`,
    },
    {
      icon: <Layers className="w-6 h-6" />,
      title: "5 فئات متنوعة",
      desc: "أساسي، تحليل، إبداع، تنبؤ، متقدم",
    },
    {
      icon: <Zap className="w-6 h-6" />,
      title: "نظام نقاش ذكي",
      desc: "تعاون حقيقي بين الوكلاء",
    },
    {
      icon: <Shield className="w-6 h-6" />,
      title: "جودة مضمونة",
      desc: `${agentStats.withSelfReflection} وكيل بتأمل ذاتي`,
    },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mt-8">
      {features.map((feature, index) => (
        <CardSpotlight
          key={index}
          className="overflow-hidden rounded-[24px] border border-white/8 bg-black/22 p-6 backdrop-blur-xl"
        >
          <div className="space-y-4 text-right">
            <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-white/8 text-[var(--page-accent,#3b5bdb)]">
              {feature.icon}
            </div>
            <div>
              <h3 className="font-bold mb-2 text-white">{feature.title}</h3>
              <p className="text-sm text-white/58 leading-7">{feature.desc}</p>
            </div>
          </div>
        </CardSpotlight>
      ))}
    </div>
  );
}

"use client";

/**
 * @module FinalResult
 * @description عرض النتيجة النهائية لجلسة العصف الذهني
 *
 * يعرض ملخصاً شاملاً للنتائج والتوصيات والقرارات النهائية
 */

import { useMemo } from "react";
import { CheckCircle, AlertCircle, Lightbulb, Target } from "lucide-react";
import type { Session, DebateMessage } from "../../types";

interface FinalResultProps {
  session: Session;
  messages: DebateMessage[];
  progressPercent: string;
}

interface SummaryItem {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: string | number;
  color: string;
}

export function FinalResult({
  session,
  messages,
  progressPercent,
}: FinalResultProps) {
  const summaryItems = useMemo((): SummaryItem[] => {
    // استخدام الأنواع الصحيحة لـ DebateMessage: agentId وtype وmessage
    const uniqueAgents = new Set(messages.map((m) => m.agentId)).size;
    const totalDecisions = messages.filter((m) =>
      m.message.includes("قرار")
    ).length;
    const recommendations = messages.filter((m) =>
      m.message.includes("توصية")
    ).length;

    return [
      {
        icon: CheckCircle,
        label: "الوكلاء المكتملين",
        value: uniqueAgents,
        color: "text-green-400",
      },
      {
        icon: Target,
        label: "القرارات المتخذة",
        value: totalDecisions,
        color: "text-blue-400",
      },
      {
        icon: Lightbulb,
        label: "التوصيات",
        value: recommendations,
        color: "text-yellow-400",
      },
      {
        icon: AlertCircle,
        label: "نسبة الإنجاز",
        value: `${progressPercent}%`,
        color: "text-purple-400",
      },
    ];
  }, [messages, progressPercent]);

  const finalConclusions = useMemo(() => {
    // استخراج الاستنتاجات النهائية من الرسائل
    // استخراج آخر الرسائل من جميع الوكلاء (DebateMessage لا يملك role، نستخدم agentId وmessage)
    const conclusions = messages
      .slice(-3) // آخر 3 رسائل
      .map((m) => m.message)
      .filter((content) => content.length > 50); // رسائل ذات محتوى

    return conclusions.length > 0
      ? conclusions
      : [
          "تم إكمال جلسة العصف الذهني بنجاح",
          "تم جمع آراء متعددة من الوكلاء المختلفين",
          "النتائج جاهزة للتنفيذ والمتابعة",
        ];
  }, [messages]);

  return (
    <div className="space-y-6">
      {/* رأس النتائج النهائية */}
      <div className="text-center space-y-2">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-green-500/10 mb-4">
          <CheckCircle className="w-8 h-8 text-green-400" />
        </div>
        <h2 className="text-2xl font-bold text-white font-cairo">
          النتائج النهائية
        </h2>
        <p className="text-white/70 font-cairo">
          تم إكمال جلسة العصف الذهني بنجاح بنسبة {progressPercent}%
        </p>
      </div>

      {/* ملخص إحصائي */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {summaryItems.map((item, index) => (
          <div
            key={index}
            className="bg-white/5 rounded-lg p-4 border border-white/10"
          >
            <div className="flex items-center gap-3">
              <item.icon className={`w-5 h-5 ${item.color}`} />
              <div>
                <p className="text-xs text-white/60 font-cairo">{item.label}</p>
                <p className={`text-lg font-bold ${item.color} font-cairo`}>
                  {item.value}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* الاستنتاجات النهائية */}
      <div className="bg-white/5 rounded-lg p-6 border border-white/10">
        <h3 className="text-lg font-semibold text-white mb-4 font-cairo">
          الاستنتاجات النهائية
        </h3>
        <div className="space-y-3">
          {finalConclusions.map((conclusion, index) => (
            <div
              key={index}
              className="flex items-start gap-3 p-3 bg-white/5 rounded-md"
            >
              <CheckCircle className="w-5 h-5 text-green-400 mt-0.5 shrink-0" />
              <p className="text-white/80 font-cairo text-sm leading-relaxed">
                {conclusion}
              </p>
            </div>
          ))}
        </div>
      </div>

      {/* معلومات الجلسة */}
      <div className="bg-white/5 rounded-lg p-6 border border-white/10">
        <h3 className="text-lg font-semibold text-white mb-4 font-cairo">
          معلومات الجلسة
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
          <div>
            <span className="text-white/60 font-cairo">الموضوع: </span>
            <span className="text-white font-cairo">{session.brief}</span>
          </div>
          <div>
            <span className="text-white/60 font-cairo">المرحلة النهائية: </span>
            <span className="text-white font-cairo">
              المرحلة {session.phase}
            </span>
          </div>
          <div>
            <span className="text-white/60 font-cairo">إجمالي الرسائل: </span>
            <span className="text-white font-cairo">{messages.length}</span>
          </div>
          <div>
            <span className="text-white/60 font-cairo">تاريخ الانتهاء: </span>
            <span className="text-white font-cairo">
              {new Date().toLocaleDateString("ar-EG")}
            </span>
          </div>
        </div>
      </div>

      {/* رسالة تشجيعية */}
      <div className="text-center py-6">
        <p className="text-white/70 font-cairo">
          🎉 تم إكمال جلسة العصف الذهني بنجاح!
        </p>
        <p className="text-white/50 text-sm mt-2 font-cairo">
          يمكنك الآن تصدير النتائج أو بدء جلسة جديدة
        </p>
      </div>
    </div>
  );
}

"use client";

/**
 * @module KeyboardShortcutsHelp
 * @description نافذة عرض اختصارات لوحة المفاتيح
 */

import { useCallback, useEffect } from "react";
import { SHORTCUT_LIST } from "../../hooks/useKeyboardShortcuts";

interface KeyboardShortcutsHelpProps {
  isOpen: boolean;
  onClose: () => void;
}

export function KeyboardShortcutsHelp({
  isOpen,
  onClose,
}: KeyboardShortcutsHelpProps) {
  /** إغلاق بـ Escape */
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    },
    [isOpen, onClose]
  );

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* الخلفية */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* المحتوى */}
      <div
        dir="rtl"
        className="relative bg-background border border-border rounded-xl shadow-xl p-6 w-full max-w-md mx-4 animate-in fade-in zoom-in-95 duration-200"
      >
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-lg font-bold text-foreground font-cairo">
            اختصارات لوحة المفاتيح
          </h2>
          <button
            onClick={onClose}
            className="p-1 text-white/55 hover:text-foreground transition"
            aria-label="إغلاق"
          >
            <svg
              className="h-5 w-5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        <div className="space-y-2">
          {SHORTCUT_LIST.map((shortcut) => (
            <div
              key={shortcut.keys}
              className="flex items-center justify-between py-2 border-b border-border/50 last:border-0"
            >
              <span className="text-sm text-foreground font-cairo">
                {shortcut.description}
              </span>
              <kbd className="px-2 py-1 text-xs bg-white/6 border border-border rounded font-mono">
                {shortcut.keys}
              </kbd>
            </div>
          ))}
        </div>

        <p className="mt-4 text-xs text-white/55 text-center font-cairo">
          اضغط Ctrl+/ لإظهار هذه النافذة في أي وقت
        </p>
      </div>
    </div>
  );
}

