import type {
  BreakdownBootstrapResponse,
  BreakdownReport,
  BreakdownReportScene,
  ScenarioAnalysis,
  SceneBreakdown,
  ScriptSegmentResponse,
  ShootingScheduleDay,
} from "../domain/models";

type ApiEnvelope<T> = {
  success: boolean;
  data?: T;
  error?: string;
  details?: unknown;
};

type RequestOptions = {
  method?: "GET" | "POST";
  body?: unknown;
};

function getAppOrigin(): string {
  if (typeof window !== "undefined" && window.location?.origin) {
    return window.location.origin;
  }

  return "http://localhost:3000";
}

function getCsrfToken(): string | null {
  if (typeof document === "undefined") {
    return null;
  }

  const match = document.cookie.match(/(?:^|;\s*)XSRF-TOKEN=([^;]+)/);
  return match?.[1] ? decodeURIComponent(match[1]) : null;
}

async function ensureCsrfToken(): Promise<string | null> {
  const existing = getCsrfToken();
  if (existing) {
    return existing;
  }

  await fetch(resolveApiUrl("/api/breakdown/health"), {
    method: "GET",
    credentials: "include",
    cache: "no-store",
  });

  return getCsrfToken();
}

function resolveApiUrl(path: string): string {
  return new URL(path, getAppOrigin()).toString();
}

async function fetchBreakdown<T>(
  path: string,
  options: RequestOptions = {}
): Promise<T> {
  const csrfToken =
    options.method && options.method !== "GET"
      ? await ensureCsrfToken()
      : getCsrfToken();
  const headers = new Headers({
    "Content-Type": "application/json",
  });

  if (options.method && options.method !== "GET" && csrfToken) {
    headers.set("X-XSRF-TOKEN", csrfToken);
  }

  const response = await fetch(resolveApiUrl(`/api/breakdown${path}`), {
    method: options.method ?? "GET",
    headers,
    credentials: "include",
    ...(options.body !== undefined
      ? { body: JSON.stringify(options.body) }
      : {}),
  });
  const payload = (await response.json()) as ApiEnvelope<T>;

  if (!response.ok || !payload.success || payload.data === undefined) {
    throw new Error(payload.error || "فشل طلب البريك دون");
  }

  return payload.data;
}

export async function bootstrapBreakdownProject(
  scriptContent: string,
  title?: string
): Promise<BreakdownBootstrapResponse> {
  return fetchBreakdown<BreakdownBootstrapResponse>("/projects/bootstrap", {
    method: "POST",
    body: { scriptContent, title },
  });
}

export async function parseBreakdownProject(
  projectId: string,
  scriptContent?: string,
  title?: string
): Promise<ScriptSegmentResponse> {
  return fetchBreakdown<ScriptSegmentResponse>(`/projects/${projectId}/parse`, {
    method: "POST",
    body: { scriptContent, title },
  });
}

export async function analyzeBreakdownProject(
  projectId: string
): Promise<BreakdownReport> {
  return fetchBreakdown<BreakdownReport>(`/projects/${projectId}/analyze`, {
    method: "POST",
  });
}

export async function getBreakdownProjectReport(
  projectId: string
): Promise<BreakdownReport> {
  return fetchBreakdown<BreakdownReport>(`/projects/${projectId}/report`);
}

export async function getBreakdownProjectSchedule(
  projectId: string
): Promise<ShootingScheduleDay[]> {
  return fetchBreakdown<ShootingScheduleDay[]>(
    `/projects/${projectId}/schedule`
  );
}

export async function getBreakdownScene(
  sceneId: string
): Promise<BreakdownReportScene> {
  return fetchBreakdown<BreakdownReportScene>(`/scenes/${sceneId}`);
}

export async function reanalyzeBreakdownScene(
  sceneId: string
): Promise<BreakdownReportScene> {
  return fetchBreakdown<BreakdownReportScene>(`/scenes/${sceneId}/reanalyze`, {
    method: "POST",
  });
}

export async function exportBreakdownReport(
  reportId: string,
  format: "json" | "csv" = "json"
): Promise<{ fileName: string; format: string; content: string }> {
  return fetchBreakdown<{ fileName: string; format: string; content: string }>(
    `/reports/${reportId}/export?format=${format}`
  );
}

export async function chatWithBreakdownAssistant(
  message: string,
  context?: Record<string, unknown>
): Promise<{ answer: string }> {
  return fetchBreakdown<{ answer: string }>("/chat", {
    method: "POST",
    body: { message, context },
  });
}

export function mapReportSceneToWorkspaceScene(
  scene: BreakdownReportScene,
  projectId: string,
  reportId: string,
  index: number
): {
  id: number;
  remoteId: string;
  projectId: string;
  reportId: string;
  header: string;
  content: string;
  headerData: BreakdownReportScene["headerData"];
  stats: SceneBreakdown["stats"];
  elements: SceneBreakdown["elements"];
  warnings: string[];
  source?: "ai" | "fallback";
  isAnalyzed: true;
  analysis: SceneBreakdown;
  scenarios: ScenarioAnalysis;
  versions: [];
} {
  const workspaceScene: {
    id: number;
    remoteId: string;
    projectId: string;
    reportId: string;
    header: string;
    content: string;
    headerData: BreakdownReportScene["headerData"];
    stats: SceneBreakdown["stats"];
    elements: SceneBreakdown["elements"];
    warnings: string[];
    source?: "ai" | "fallback";
    isAnalyzed: true;
    analysis: SceneBreakdown;
    scenarios: ScenarioAnalysis;
    versions: [];
  } = {
    id: index + 1,
    remoteId: scene.sceneId,
    projectId,
    reportId,
    header: scene.header,
    content: scene.content,
    headerData: scene.headerData,
    stats: scene.analysis.stats,
    elements: scene.analysis.elements,
    warnings: scene.analysis.warnings,
    ...(scene.analysis.source ? { source: scene.analysis.source } : {}),
    isAnalyzed: true as const,
    analysis: scene.analysis,
    scenarios: scene.scenarios,
    versions: [] as [],
  };
  return workspaceScene;
}

import type { ScriptSegmentResponse } from "../../domain/models";

const ENGLISH_SCENE_HEADING_PATTERN = /^(?:INT|EXT|INT\/EXT|I\/E|EST)\.?\s+/i;
const ARABIC_SCENE_HEADING_PATTERN = /^(?:مشهد|م)(?:\s|$)/i;
const LOCATION_PREFIX_PATTERN = /^(?:موقع|مكان|المكان|المنطقة)\s*:\s*/;
const TRANSITION_PHRASES = new Set([
  "CUT TO",
  "FADE IN",
  "FADE OUT",
  "DISSOLVE TO",
  "SMASH CUT",
  "MATCH CUT",
  "JUMP CUT",
  "WIPE TO",
  "IRIS IN",
  "IRIS OUT",
  "قطع إلى",
  "تلاشي دخول",
  "تلاشي خروج",
  "ذوبان إلى",
  "قطع مفاجئ",
  "قطع مطابق",
]);
const CHARACTER_PATTERN = /^.{1,40}\s*:\s*$/;
const ACTION_PREFIX_PATTERN = /^[\-–—(]/;

function normalizeLine(line: string): string {
  return line.replace(/\u00A0/g, " ").trim();
}

function normalizeTransitionLine(line: string): string {
  const normalized = normalizeLine(line).replace(/\s+/g, " ");
  const withoutColon = normalized.endsWith(":")
    ? normalized.slice(0, -1).trim()
    : normalized;
  return withoutColon.toUpperCase();
}

function looksLikeTransition(line: string): boolean {
  return TRANSITION_PHRASES.has(normalizeTransitionLine(line));
}

function looksLikeSceneHeading(line: string): boolean {
  const trimmed = normalizeLine(line);

  if (!trimmed) {
    return false;
  }

  if (ENGLISH_SCENE_HEADING_PATTERN.test(trimmed)) {
    return true;
  }

  if (!ARABIC_SCENE_HEADING_PATTERN.test(trimmed)) {
    return false;
  }

  return trimmed.length <= 160;
}

function looksLikeHeaderContinuation(
  line: string,
  currentHeader: string
): boolean {
  const trimmed = normalizeLine(line);

  if (!trimmed || looksLikeSceneHeading(trimmed)) {
    return false;
  }

  if (
    looksLikeTransition(trimmed) ||
    CHARACTER_PATTERN.test(trimmed) ||
    ACTION_PREFIX_PATTERN.test(trimmed)
  ) {
    return false;
  }

  if (LOCATION_PREFIX_PATTERN.test(trimmed)) {
    return true;
  }

  const wordCount = trimmed.split(/\s+/).filter(Boolean).length;
  const currentLooksStructured =
    /^(?:مشهد|م)\s*\d+/i.test(currentHeader) ||
    /^(?:مشهد|م)(?:\s|$)/i.test(currentHeader);

  return currentLooksStructured && wordCount > 0 && wordCount <= 8;
}

function buildHeader(headerLines: string[]): string {
  return headerLines.map(normalizeLine).filter(Boolean).join(" | ");
}

function buildContent(contentLines: string[]): string {
  return contentLines.join("\n").trim();
}

function pushScene(
  scenes: ScriptSegmentResponse["scenes"],
  headerLines: string[],
  contentLines: string[]
): void {
  const header = buildHeader(headerLines);
  const content = buildContent(contentLines);

  if (!header || !content) {
    return;
  }

  scenes.push({ header, content });
}

export function segmentScriptLocally(
  scriptText: string
): ScriptSegmentResponse {
  const lines = scriptText.split(/\r?\n/);
  const scenes: ScriptSegmentResponse["scenes"] = [];

  let currentHeaderLines: string[] = [];
  let currentContentLines: string[] = [];
  let hasStartedScene = false;

  for (let index = 0; index < lines.length; index += 1) {
    const rawLine = lines[index] ?? "";
    const trimmed = normalizeLine(rawLine);

    if (looksLikeSceneHeading(trimmed)) {
      if (hasStartedScene) {
        pushScene(scenes, currentHeaderLines, currentContentLines);
      }

      currentHeaderLines = [trimmed];
      currentContentLines = [];
      hasStartedScene = true;

      const nextLine = lines[index + 1];
      const normalizedNextLine = nextLine ? normalizeLine(nextLine) : "";

      if (
        normalizedNextLine &&
        looksLikeHeaderContinuation(normalizedNextLine, trimmed)
      ) {
        currentHeaderLines.push(normalizedNextLine);
        index += 1;
      }

      continue;
    }

    if (!hasStartedScene) {
      continue;
    }

    currentContentLines.push(rawLine.trimEnd());
  }

  if (hasStartedScene) {
    pushScene(scenes, currentHeaderLines, currentContentLines);
  }

  return { scenes };
}

