 * السبب: نوفر واجهة متكاملة لإدارة بيانات طاقم التمثيل
 * مع تحليلات متقدمة وتصدير للملفات.
 */

import React, { useState, useMemo } from "react";
import {
  CastMember,
  ExtendedCastMember,
  CastAnalysisResult,
} from "../../domain/models";
import {
  UserCircle,
  Star,
  User,
