      isUser
        ? "bg-indigo-600/20 text-indigo-100 rounded-tr-none border border-indigo-500/30"
        : "bg-white/[0.04] text-white/85 rounded-tl-none border border-white/8"
    }
  `}
  >
    {text}
  </div>
);

