                <div className="flex flex-col items-center justify-center h-full text-white/45 gap-1">
                  <span className="text-sm">لا توجد عناصر</span>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </CardSpotlight>
  );
};

