                </div>
              </div>

              {scene.analysis.warnings.length > 0 && (
                <div className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/5 p-3">
                  <p className="mb-2 flex items-center gap-2 text-sm font-medium text-amber-400">
