import { logger } from "@/lib/ai/utils/logger";

/**
 * Cast Agent AI Module
 * Google GenAI integration for advanced character analysis
 */

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { DEFAULT_CAST_MODEL } from "./constants";
import type { CastAgentOptions } from "./types";
import { ExtendedCastMember } from "../../types";
import { getGeminiApiKeyFromEnv } from "../../infrastructure/gemini/env";

// ============================================
// AI INITIALIZATION
// ============================================

/**
 * Initialize Google GenAI with API key - Safe handling
 */
const getAI = (apiKey?: string): GoogleGenAI => {
  const keyToUse = apiKey || getGeminiApiKeyFromEnv();

  if (!keyToUse) {
    logger.warn("⚠️ Warning: GEMINI_API_KEY environment variable is not set.");
  }

  return new GoogleGenAI({ apiKey: keyToUse });
};

// ============================================
// PROMPT BUILDER
// ============================================

/**
 * Build the analysis prompt for the AI model
 */
function buildAnalysisPrompt(content: string, language: string): string {
  return `You are the "Casting Director Agent" for a film production.

Analyze the provided ${language} scene text and identify every speaking character or significant figure.

For each character, provide:
1. **name**: The character's name exactly as written in the script
2. **nameArabic**: Arabic name translation if applicable (null if not)
3. **roleCategory**: Role Category - One of: "Lead", "Supporting", "Bit Part", "Silent", "Group", "Mystery"
4. **ageRange**: Estimated Age Range (e.g., "30s", "Teen", "Child", "Elderly", "40-50")
5. **gender**: "Male", "Female", "Non-binary", or "Unknown"
6. **visualDescription**: Visual Description (Physical appearance details mentioned or implied, 2-3 sentences)
7. **motivation**: What this character wants in this specific scene (1-2 sentences)
8. **personalityTraits**: Array of personality traits if observable (optional)
9. **relationships**: Array of relationship objects { character: "name", type: "relationship" } if mentioned (optional)

Return ONLY a valid JSON object with a "members" array containing all characters.

SCRIPT TO ANALYZE:
${content.substring(0, 25000)}`;
}

// ============================================
// SCHEMA BUILDER
// ============================================

/**
 * Build the JSON schema for structured AI response
 */
function buildCastSchema(): Schema {
  return {
    type: Type.OBJECT,
    properties: {
      members: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: {
              type: Type.STRING,
              description: "Unique character identifier",
            },
            name: {
              type: Type.STRING,
              description: "Character name as written in script",
            },
            nameArabic: {
              type: Type.STRING,
              description: "Arabic name if applicable",
            },
            roleCategory: {
              type: Type.STRING,
              description:
                "Lead, Supporting, Bit Part, Silent, Group, or Mystery",
              enum: [
                "Lead",
                "Supporting",
                "Bit Part",
                "Silent",
                "Group",
                "Mystery",
              ],
            },
            ageRange: {
              type: Type.STRING,
              description: "Age range like 30s, Teen, Child, Elderly",
            },
            gender: {
              type: Type.STRING,
              description: "Male, Female, Non-binary, or Unknown",
              enum: ["Male", "Female", "Non-binary", "Unknown"],
            },
            visualDescription: {
              type: Type.STRING,
              description: "Visual appearance description",
            },
            motivation: {
              type: Type.STRING,
              description: "Character's goal in this scene",
            },
            personalityTraits: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Observable personality traits",
            },
            relationships: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  character: { type: Type.STRING },
                  type: { type: Type.STRING },
                },
              },
              description: "Relationships to other characters",
            },
          },
          required: [
            "name",
            "roleCategory",
            "ageRange",
            "gender",
            "visualDescription",
            "motivation",
          ],
        },
      },
    },
    required: ["members"],
  };
}

// ============================================
// LANGUAGE DETECTION
// ============================================

/**
 * Detect script language from content
 */
function detectScriptLanguage(content: string): string {
  const hasArabic = /[\u0600-\u06FF]/.test(content);
  const hasEnglish = /[a-zA-Z]/.test(content);

  if (hasArabic && hasEnglish) return "Arabic and English";
  if (hasArabic) return "Arabic";
  return "English";
}

// ============================================
// MAIN AI AGENT FUNCTION
// ============================================

/**
 * Independent Cast Agent using Google GenAI.
 * Focused solely on extracting deep character details from the scene.
 */
export const runCastAgent = async (
  sceneContent: string,
  options: CastAgentOptions = {}
): Promise<ExtendedCastMember[]> => {
  const { apiKey, model = DEFAULT_CAST_MODEL } = options;
  const ai = getAI(apiKey);

  const scriptLanguage = detectScriptLanguage(sceneContent);
  const prompt = buildAnalysisPrompt(sceneContent, scriptLanguage);
  const castSchema = buildCastSchema();

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: [
        { role: "user", parts: [{ text: prompt }] },
        { role: "user", parts: [{ text: `SCENE CONTENT:\n${sceneContent}` }] },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: castSchema,
      },
    });

    const result = response.text ? JSON.parse(response.text) : { members: [] };

    // Post-process to ensure IDs exist
    return (result.members || []).map((m: any, index: number) => ({
      ...m,
      id: m.id || `char-${Date.now()}-${index}`,
    }));
  } catch (error) {
    logger.error("Cast Agent Error:", error);
    return [];
  }
};

/**
 * Cast Agent Analyzer
 * Analysis functions for character and script processing
 */

import {
  EMOTION_KEYWORDS,
  MALE_PATTERNS,
  FEMALE_PATTERNS,
  GROUP_KEYWORDS,
  ARABIC_TITLES,
} from "./constants";
import { isSceneHeading, isTransition, normalizeArabic } from "./parser";
import type {
  EmotionType,
  EmotionStats,
  GenderAnalysis,
  CharacterProfile,
  MergeSuggestion,
  SceneData,
  Connection,
} from "./types";

// ============================================
// EMOTION ANALYSIS
// ============================================

/**
 * Analyzes text for emotional content and returns emotion statistics
 */
export const analyzeEmotion = (text: string): EmotionStats => {
  const normalized = text.toLowerCase();
  const stats: EmotionStats = {
    neutral: 0,
    positive: 0,
    negative: 0,
    intense: 0,
    mysterious: 0,
    dominant: "neutral",
  };

  Object.entries(EMOTION_KEYWORDS).forEach(([emotion, keywords]) => {
    const count = keywords.filter((kw) =>
      normalized.includes(kw.toLowerCase())
    ).length;
    stats[emotion as EmotionType] = count;
  });

  // Find dominant emotion
  const emotionEntries = Object.entries(stats).filter(
    ([k]) => k !== "dominant"
  ) as [EmotionType, number][];
  const max = Math.max(...emotionEntries.map(([, v]) => v));

  if (max > 0) {
    stats.dominant =
      emotionEntries.find(([, v]) => v === max)?.[0] || "neutral";
  }

  return stats;
};

// ============================================
// GENDER ANALYSIS
// ============================================

/**
 * Analyzes script lines for gender indicators and detects conflicts
 */
export const analyzeGenderAndConflict = (
  lines: string[],
  charName: string
): GenderAnalysis => {
  let maleScore = 0;
  let femaleScore = 0;
  let firstDesc = "";

  const normName = normalizeArabic(charName);

  lines.forEach((line) => {
    if (isSceneHeading(line) || isTransition(line)) return;

    if (normalizeArabic(line).includes(normName)) {
      if (!firstDesc) firstDesc = line;
      if (MALE_PATTERNS.some((p) => p.test(line))) maleScore++;
      if (FEMALE_PATTERNS.some((p) => p.test(line))) femaleScore++;
    }
  });

  let gender = "";
  if (maleScore > femaleScore) gender = "ذكر";
  else if (femaleScore > maleScore) gender = "أنثى";

  const total = maleScore + femaleScore;
  const conflict = total > 3 && Math.min(maleScore, femaleScore) / total > 0.25;

  return { gender, conflict, desc: firstDesc };
};

// ============================================
// CHARACTER TAGS GENERATION
// ============================================

/**
 * Generates descriptive tags for a character based on their profile
 */
export const generateCharacterTags = (char: CharacterProfile): string[] => {
  const tags: string[] = [];

  if (char.roleType === "Lead") tags.push("protagonist");
  if (char.dialogueCount > 50) tags.push("talkative");
  if (char.scenes.length > char.scenes.length * 0.5) tags.push("frequent");
  if (char.mentionCount > 10) tags.push("mentioned");
  if (char.genderConflict) tags.push("conflict");
  if (char.isTimeVariant) tags.push("time-variant");

  if (char.scenes.length > 0) {
    const span = char.lastScene - char.firstScene;
    if (span > char.scenes.length * 0.7) tags.push("arc-span");
  }

  return tags;
};

// ============================================
// CONNECTION ANALYSIS
// ============================================

/**
 * Calculates connections between characters based on scene co-appearance
 */
export const calculateConnections = (scenes: SceneData[]): Connection[] => {
  const connections: Connection[] = [];
  const connectionMap = new Map<string, Connection>();

  scenes.forEach((scene) => {
    // Filter out group characters for more meaningful connections
    const chars = scene.characters.filter(
      (c) => !GROUP_KEYWORDS.some((k) => c.includes(k))
    );

    // Create pairwise connections for all characters in scene
    for (let i = 0; i < chars.length; i++) {
      for (let j = i + 1; j < chars.length; j++) {
        const source = chars[i];
        const target = chars[j];
        if (!source || !target) {
          continue;
        }

        const key = [source, target].sort().join("-");
        const existing = connectionMap.get(key);

        if (existing) {
          existing.strength++;
          existing.scenes.push(scene.number);
        } else {
          const conn: Connection = {
            source,
            target,
            strength: 1,
            scenes: [scene.number],
          };
          connectionMap.set(key, conn);
          connections.push(conn);
        }
      }
    }
  });

  return connections.sort((a, b) => b.strength - a.strength);
};

// ============================================
// MERGE SUGGESTIONS
// ============================================

/**
 * Generates suggestions for merging duplicate or related characters
 */
export const generateMergeSuggestions = (
  profiles: CharacterProfile[]
): MergeSuggestion[] => {
  const suggestions: MergeSuggestion[] = [];
  const processed = new Set<string>();
  const sorted = [...profiles].sort((a, b) => b.name.length - a.name.length);

  for (let i = 0; i < sorted.length; i++) {
    for (let j = i + 1; j < sorted.length; j++) {
      const long = sorted[i];
      const short = sorted[j];
      if (!long || !short) {
        continue;
      }

      // Skip groups and mysteries
      if (
        long.roleType === "Group" ||
        short.roleType === "Group" ||
        long.roleType === "Mystery" ||
        short.roleType === "Mystery"
      ) {
        continue;
      }

      const key = `${long.id}-${short.id}`;
      if (processed.has(key)) continue;

      // Check for exact normalized match
      if (long.normalizedName === short.normalizedName) {
        suggestions.push({
          sourceId: short.id,
          targetId: long.id,
          reason: "تطابق إملائي (Spelling)",
        });
        processed.add(key);
      }
      // Check for title variations
      else if (long.name.includes(short.name) && short.name.length > 2) {
        const diff = long.name.replace(short.name, "").trim();
        if (ARABIC_TITLES.some((t) => diff.includes(t))) {
          suggestions.push({
            sourceId: short.id,
            targetId: long.id,
            reason: `احتواء اللقب (${diff})`,
          });
          processed.add(key);
        }
      }
    }
  }

  return suggestions;
};

/**
 * Cast Agent Parser
 * Text parsing and NLP helper functions for script analysis
 */

import { TRANSITIONS, TECHNICAL_EXTENSIONS, ARABIC_TITLES } from "./constants";
import type { ParsedName, SceneLocation } from "./types";

// ============================================
// TEXT NORMALIZATION
// ============================================

/**
 * Normalizes Arabic text for accurate matching by removing diacritics,
 * tatweel, and standardizing letter forms
 */
export const normalizeArabic = (text: string): string => {
  if (!text) return "";
  let normalized = text;
  normalized = normalized.replace(/\u0640/g, ""); // Remove tatweel
  normalized = normalized.replace(/[\u064B-\u065F\u0670]/g, ""); // Remove diacritics
  normalized = normalized.replace(/[أإآ]/g, "ا");
  normalized = normalized.replace(/ى/g, "ي");
  normalized = normalized.replace(/ة/g, "ه");
  return normalized.trim().toUpperCase();
};

/**
 * Counts words in text
 */
export const countWords = (text: string): number => {
  return text.trim().split(/\s+/).length;
};

// ============================================
// LINE TYPE DETECTION
// ============================================

/**
 * Checks if a line is a scene heading (slug line)
 */
export const isSceneHeading = (line: string): boolean => {
  const upperLine = line.trim().toUpperCase();
  const patterns = [
    /^INT\./,
    /^EXT\./,
    /^I\/E\./,
    /^INT\/EXT/,
    /^DAKHEL/,
    /^KHAREG/,
    /^مشهد/,
    /^داخلي/,
    /^خارجي/,
    /^ليل/,
    /^نهار/,
    /^\d+\s*[\-\.]/,
  ];
  return patterns.some((pattern) => pattern.test(upperLine));
};

/**
 * Checks if a line is a transition (CUT TO, FADE OUT, etc.)
 */
export const isTransition = (line: string): boolean => {
  const upper = line.trim().toUpperCase();
  return TRANSITIONS.some(
    (t) => upper.startsWith(t) || upper.endsWith(t.replace(":", ""))
  );
};

/**
 * Checks if a line is a comment or annotation
 */
export const isComment = (line: string): boolean => {
  const trim = line.trim();
  return (
    trim.startsWith("//") ||
    trim.startsWith("[[") ||
    (trim.startsWith("(") && trim.endsWith(")"))
  );
};

// ============================================
// CHARACTER NAME PARSING
// ============================================

/**
 * Parses character name from a script header line, handling technical
 * extensions like (V.O), (O.S), (CONT'D), etc.
 */
export const parseNameHeader = (line: string): ParsedName => {
  let raw = line.trim();
  const parenMatch = raw.match(/\((.*?)\)/);
  let isVariant = false;

  if (parenMatch) {
    const content = parenMatch[1]?.toUpperCase().trim() ?? "";
    const isTech = TECHNICAL_EXTENSIONS.some(
      (ext) => content.includes(ext) || content === ext
    );
    if (isTech) {
      raw = raw.replace(/\(.*?\)/, "").trim();
    } else {
      isVariant = true;
    }
  }

  raw = raw.replace(/[:\-]$/, "").trim();
  raw = raw.replace(/^[\.\-\*]+/, "").trim();

  return { name: raw.toUpperCase(), isVariant };
};

/**
 * Determines if a line is likely a character name header based on
 * formatting conventions and context
 */
export const isLikelyCharacter = (line: string, nextLine: string): boolean => {
  const trimmed = line.trim();
  const nextTrimmed = nextLine ? nextLine.trim() : "";

  // Exclude non-character lines
  if (
    !trimmed ||
    isSceneHeading(line) ||
    isTransition(line) ||
    isComment(line)
  ) {
    return false;
  }
  if (trimmed.length > 40) return false;

  // Check various character name patterns
  const isAllUpper = trimmed === trimmed.toUpperCase() && /[A-Z]/.test(trimmed);
  const isArabicName = /[\u0600-\u06FF]/.test(trimmed);
  const startsWithTitle = ARABIC_TITLES.some((t) =>
    trimmed.startsWith(t + " ")
  );

  const isShortLine = trimmed.length < 30 && trimmed.split(" ").length <= 5;
  const nextIsDialogue =
    nextTrimmed.length > 0 &&
    !isSceneHeading(nextTrimmed) &&
    !isTransition(nextTrimmed);
  const hasNumber = /\d/.test(trimmed);

  return (
    (isAllUpper || isArabicName || startsWithTitle || hasNumber) &&
    isShortLine &&
    nextIsDialogue
  );
};

// ============================================
// SCENE PARSING
// ============================================

/**
 * Extracts location and time of day from a scene heading
 */
export const extractSceneLocation = (heading: string): SceneLocation => {
  const upper = heading.toUpperCase();
  let timeOfDay = "unknown";
  let location = "unknown";

  // Time of day detection
  if (
    upper.includes("NIGHT") ||
    upper.includes("ليلا") ||
    upper.includes("ليل")
  ) {
    timeOfDay = "night";
  } else if (
    upper.includes("DAY") ||
    upper.includes("نهار") ||
    upper.includes("صباح")
  ) {
    timeOfDay = "day";
  } else if (upper.includes("MORNING") || upper.includes("صباحا")) {
    timeOfDay = "morning";
  } else if (upper.includes("EVENING") || upper.includes("مساء")) {
    timeOfDay = "evening";
  } else if (upper.includes("SUNSET") || upper.includes("غروب")) {
    timeOfDay = "sunset";
  } else if (upper.includes("DAWN") || upper.includes("فجر")) {
    timeOfDay = "dawn";
  }

  // Location extraction
  const locationMatch = heading.match(
    /(?:INT\.|EXT\.|DAKHEL|KHAREG|داخلي|خارجي)\s*(.+?)(?:\s*-\s*[A-Z]+)?$/
  );
  if (locationMatch?.[1]) {
    location = locationMatch[1].trim();
  }

  return { location, timeOfDay };
};

// ============================================
// MENTION SCANNING
// ============================================

/**
 * Scans text for mentions of known character names
 */
export const scanForMentions = (
  text: string,
  knownNames: string[]
): string[] => {
  if (!text) return [];
  const found: string[] = [];
  const normText = normalizeArabic(text);

  knownNames.forEach((name) => {
    if (name.length < 3) return;
    const normName = normalizeArabic(name);
    if (
      normText.includes(` ${normName} `) ||
      normText.startsWith(`${normName} `) ||
      normText.endsWith(` ${normName}`)
    ) {
      found.push(name);
    }
  });

  return [...new Set(found)];
};

