interface StudioMiniLegendProps {
  icon: LucideIcon;
  label: string;
  value: React.ReactNode;
  className?: string;
}

export function StudioMiniLegend({
  icon: Icon,
  label,
  value,
  className,
}: StudioMiniLegendProps) {
  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-[8px] border border-[#262626] bg-[#070707] px-3 py-2",
        className
      )}
    >
      <Icon className="h-4 w-4 text-[#e5b54f]" />
      <div className="min-w-0">
        <p className="text-[10px] uppercase tracking-[0.24em] text-[#7f7b71]">
          {label}
        </p>
        <p className="truncate text-sm text-white">{value}</p>
      </div>
    </div>
  );
}

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it } from "vitest";
import { LensSimulatorTool } from "./LensSimulatorTool";

Object.defineProperty(Element.prototype, "hasPointerCapture", {
  configurable: true,
  value: () => false,
});

Object.defineProperty(Element.prototype, "setPointerCapture", {
  configurable: true,
  value: () => undefined,
});

Object.defineProperty(Element.prototype, "releasePointerCapture", {
  configurable: true,
  value: () => undefined,
});

Object.defineProperty(Element.prototype, "scrollIntoView", {
  configurable: true,
  value: () => undefined,
});

describe("Cinematography controls", () => {
  it("locks preset-bound lens fields until manual unlock", async () => {
    const user = userEvent.setup();
    render(<LensSimulatorTool />);

    await user.click(screen.getByRole("combobox"));
    await user.click(
      screen.getByText((content) => content.includes("Zeiss Master Prime"))
    );

    const focalInput = screen.getByRole("spinbutton", {
      name: /البعد البؤري input/i,
    });

    expect(
      screen.getByText((content) => content.includes("يثبّت البعد البؤري"))
