  .fn()
  .mockResolvedValue({ success: true, data: {} });
const mockCreateLocalShotAnalysis = vi.fn();
const mockCreateLocalFootageSummary = vi.fn();

vi.mock("react-hot-toast", () => ({
  toast: {
    success: vi.fn(),
    error: vi.fn(),
    loading: vi.fn(),
  },
  default: {
    success: vi.fn(),
    error: vi.fn(),
    loading: vi.fn(),
  },
}));

vi.mock("../../lib/studio-route-client", () => ({
