/**
 * @fileoverview Hook مخصص لإدارة أدوات أثناء التصوير
 *
 * هذا الـ Hook يوفر جميع الوظائف المطلوبة لمرحلة التصوير الفعلي
 * بما في ذلك تحليل اللقطات وإدارة الإعدادات التقنية.
 * يتضمن معالجة الأخطاء والتحقق من صحة البيانات.
 *
 * @module cinematography-studio/hooks/useProduction
 */

"use client";

import { useState, useCallback, useEffect, useMemo, useRef } from "react";
import { toast } from "react-hot-toast";
import type { VisualMood, ShotAnalysis } from "../types";
import { ShotAnalysisSchema } from "../types";
import { postStudioFormData, postStudioJson } from "../lib/studio-route-client";
import { createLocalShotAnalysis } from "../lib/local-shot-analysis";
import { resolveAnalysisWinner } from "../lib/resolve-analysis-winner";
import { patchSession, readSession } from "../lib/session-storage";
import { publishDiagnostics } from "../lib/diagnostics-bus";
import { useMediaInputPipeline } from "./useMediaInputPipeline";

// ============================================
// واجهات الحالة الداخلية
// ============================================

/**
 * حالة تحليل اللقطة
 */
interface AnalysisState {
  /** حالة التحليل جارية */
  isAnalyzing: boolean;
  /** نتيجة التحليل */
  analysis: ShotAnalysis | null;
  /** مصدر التحليل الفعلي */
  source: "remote" | "local-fallback" | null;
  /** رسالة الخطأ إن وجدت */
  error: string | null;
  /** سؤال المستخدم للمساعد */
  question: string;
}

/**
 * حالة المساعد الذكي — منفصلة عن حالة التحليل لأن الإجابة والخطأ
 * يجب أن يبقيا داخل لوحة المساعد لا في إشعار toast العابر.
 */
interface AssistantState {
  isLoading: boolean;
  /** آخر إجابة ناجحة */
  answer: string | null;
  /** آخر سؤال أُرسل بنجاح (لعرضه فوق الإجابة) */
  lastQuestion: string | null;
  /** آخر خطأ */
  error: string | null;
}

/**
 * الإعدادات التقنية للكاميرا
 */
interface TechnicalSettings {
  /** Focus Peaking */
  focusPeaking: boolean;
  /** False Color */
  falseColor: boolean;
  /** درجة حرارة اللون بالكلفن */
  colorTemp: number;
}

// ============================================
// الثوابت
// ============================================

/**
 * الحالة الابتدائية للتحليل
 */
const initialAnalysisState: AnalysisState = {
  isAnalyzing: false,
  analysis: null,
  source: null,
  error: null,
  question: "",
};

const initialAssistantState: AssistantState = {
  isLoading: false,
  answer: null,
  lastQuestion: null,
  error: null,
};

/** حد المهلة لطلب المساعد الذكي (ms). */
const ASSISTANT_REQUEST_TIMEOUT_MS = 15_000;

/**
 * الإعدادات التقنية الافتراضية
 */
const defaultTechnicalSettings: TechnicalSettings = {
  focusPeaking: true,
  falseColor: false,
  colorTemp: 3200,
};

interface ValidateShotResponse {
  success?: boolean;
  validation?: {
    score?: number;
    status?: string;
    exposure?: string;
    composition?: string;
    focus?: string;
    colorBalance?: string;
    suggestions?: string[];
    improvements?: string[];
  };
}

interface ChatResponse {
  success?: boolean;
  data?: {
    response?: string;
  };
}

// ============================================
// الـ Hook الرئيسي
// ============================================

/**
 * Hook مخصص لإدارة أدوات أثناء التصوير
 *
 * يوفر هذا الـ Hook:
 * - تحليل اللقطات بالذكاء الاصطناعي
 * - إدارة الإعدادات التقنية للكاميرا
 * - نظام تحذيرات ذكي
 * - معالجة الأخطاء مع إشعارات Toast
 *
 * @example
 * ```tsx
 * const {
 *   analysis,
 *   isAnalyzing,
 *   handleAnalyzeShot,
 *   technicalSettings
 * } = useProduction("noir");
 * ```
 *
 * @param mood - المود البصري للمشروع
 * @returns كائن يحتوي على الحالة والدوال المساعدة
 */
export function useProduction(mood: VisualMood = "noir") {
  // ============================================
  // الحالة
  // ============================================

  const [analysisState, setAnalysisState] =
    useState<AnalysisState>(initialAnalysisState);
  const [assistantState, setAssistantState] = useState<AssistantState>(
    initialAssistantState
  );
  const [technicalSettings, setTechnicalSettings] = useState<TechnicalSettings>(
    defaultTechnicalSettings
  );
  const mediaInput = useMediaInputPipeline("image");
  const persistenceHydrated = useRef(false);

  // استعادة الإعدادات التقنية وآخر تحليل عند أول تركيب — ثم نسمح بالحفظ.
  useEffect(() => {
    if (persistenceHydrated.current) {
      return;
    }
    persistenceHydrated.current = true;
    const persisted = readSession();
    if (!persisted) {
      return;
    }
    if (persisted.technicalSettings) {
      setTechnicalSettings(persisted.technicalSettings);
    }
    if (persisted.lastAnalysis) {
      setAnalysisState((prev) => ({
        ...prev,
        analysis: persisted.lastAnalysis ?? null,
        source: "local-fallback",
      }));
    }
    if (persisted.lastAssistant?.answer) {
      setAssistantState({
        isLoading: false,
        answer: persisted.lastAssistant.answer,
        lastQuestion: persisted.lastAssistant.question ?? null,
        error: null,
      });
    }
  }, []);

  // حفظ الإعدادات التقنية بعد الهيدرة الأولى.
  useEffect(() => {
    if (!persistenceHydrated.current) {
      return;
    }
    patchSession({ technicalSettings });
  }, [technicalSettings]);

  // حفظ آخر تحليل وآخر إجابة مساعد (نص فقط، بدون وسائط).
  useEffect(() => {
    if (!persistenceHydrated.current) {
      return;
    }
    patchSession({ lastAnalysis: analysisState.analysis });
  }, [analysisState.analysis]);

  useEffect(() => {
    if (!persistenceHydrated.current) {
      return;
    }
    patchSession({
      lastAssistant: assistantState.answer
        ? {
            question: assistantState.lastQuestion,
            answer: assistantState.answer,
          }
        : null,
    });
  }, [assistantState.answer, assistantState.lastQuestion]);

  // نشر حالة المساعد لطبقة التشخيص.
  useEffect(() => {
    publishDiagnostics({
      slice: "assistant",
      data: {
        isLoading: assistantState.isLoading,
        lastQuestion: assistantState.lastQuestion,
        answerLength: assistantState.answer?.length ?? 0,
        error: assistantState.error,
      },
    });
  }, [
    assistantState.answer,
    assistantState.error,
    assistantState.isLoading,
    assistantState.lastQuestion,
  ]);

  // عدّاد إعادة التركيب للتشخيص.
  const productionRenderCount = useRef(0);
  productionRenderCount.current += 1;
  useEffect(() => {
    publishDiagnostics({
      slice: "renderCount",
      data: { production: productionRenderCount.current },
    });
  });

  // ============================================
  // دوال التحليل
  // ============================================

  /**
   * حد المهلة لمسار التحليل البعيد (ms).
   */
  const REMOTE_ANALYSIS_TIMEOUT_MS = 12_000;

  /**
   * تحليل اللقطة الحالية — مسار متوازٍ
   *
   * يبدأ الطلب البعيد والبديل المحلي معًا.
   * إذا عاد البعيد بنتيجة صالحة قبل المهلة يُعتمد.
   * إذا تأخر أو فشل يُثبَّت البديل المحلي فورًا.
   */
  const handleAnalyzeShot = useCallback(
    async (file?: File | null) => {
      const effectiveFile = file ?? mediaInput.state.analysisFile;

      if (!effectiveFile) {
        toast.error(
          "يرجى اختيار صورة أو فيديو أو التقاط إطار من الكاميرا أولاً"
        );
        return;
      }

      setAnalysisState((prev) => ({
        ...prev,
        isAnalyzing: true,
        error: null,
      }));

      toast.loading("جاري المسح الطيفي للقطة...", { id: "analyzing" });

      // تجهيز البديل المحلي بالتوازي من اللحظة الأولى
      const localPromise = createLocalShotAnalysis(effectiveFile, mood)
        .then((analysis) => {
          const validation = ShotAnalysisSchema.safeParse(analysis);
          return validation.success ? validation.data : null;
        })
        .catch(() => null);

      // الطلب البعيد مع مهلة واضحة
      const formData = new FormData();
      formData.set("image", effectiveFile);

      const remotePromise = postStudioFormData<ValidateShotResponse>(
        "/api/cineai/validate-shot",
        formData,
        {
          timeoutMs: REMOTE_ANALYSIS_TIMEOUT_MS,
          timeoutMessage:
            "انتهت المهلة الزمنية لتحليل اللقطة. سيُستخدم التحليل المحلي.",
        }
      )
        .then((remoteData) => {
          if (!remoteData?.validation) {
            return null;
          }

          const analysis = normalizeShotAnalysis(remoteData.validation);
          const validation = ShotAnalysisSchema.safeParse(analysis);
          return validation.success ? validation.data : null;
        })
        .catch(() => null);

      const winner = await resolveAnalysisWinner({
        remote: remotePromise,
        local: localPromise,
      });

      if (winner?.source === "remote") {
        setAnalysisState((prev) => ({
          ...prev,
          isAnalyzing: false,
          analysis: winner.value,
          source: "remote",
          error: null,
        }));

        if (winner.value.issues.length > 0) {
          toast.success(
            `تم التحليل بنجاح - يوجد ${winner.value.issues.length} ملاحظة`,
            { id: "analyzing" }
          );
        } else {
          toast.success("اللقطة جاهزة للتصوير!", { id: "analyzing" });
        }
        return;
      }

      if (winner?.source === "local-fallback") {
        setAnalysisState((prev) => ({
          ...prev,
          isAnalyzing: false,
          error: null,
          analysis: winner.value,
          source: "local-fallback",
        }));
        toast.success("تم تفعيل التحليل المحلي البديل بنجاح", {
          id: "analyzing",
        });
        return;
      }

      // كلا المسارين فشلا
      setAnalysisState((prev) => ({
        ...prev,
        isAnalyzing: false,
        source: null,
        error: "فشل في تحليل اللقطة من جميع المصادر",
      }));
      toast.error("فشل في تحليل اللقطة", { id: "analyzing" });
    },
    [mediaInput.state.analysisFile, mood]
  );

  /**
   * تحديث سؤال المستخدم
   *
   * @param question - السؤال الجديد
   */
  const setQuestion = useCallback((question: string) => {
    setAnalysisState((prev) => ({
      ...prev,
      question,
    }));
  }, []);

  /**
   * إرسال سؤال للمساعد الذكي.
   *
   * - يضع حالة تحميل داخل لوحة المساعد (لا يعتمد على toast فقط).
   * - يحترم مهلة محددة عبر `postStudioJson`.
   * - عند النجاح: يعرض الإجابة داخل اللوحة ويمسح السؤال الحالي.
   * - عند الفشل: يعرض الخطأ داخل اللوحة ويُبقي السؤال الذي كتبه المستخدم.
   */
  const askAssistant = useCallback(async () => {
    const trimmedQuestion = analysisState.question.trim();

    if (!trimmedQuestion) {
      setAssistantState((prev) => ({
        ...prev,
        error: "يرجى كتابة سؤالك أولاً",
      }));
      return;
    }

    if (assistantState.isLoading) {
      // منع الإرسال المزدوج عبر زر الإدخال أو النقر المتكرر
      return;
    }

    setAssistantState({
      isLoading: true,
      answer: null,
      lastQuestion: trimmedQuestion,
      error: null,
    });

    try {
      const response = await postStudioJson<ChatResponse>(
        "/api/ai/chat",
        {
          message: trimmedQuestion,
          context: {
            assistant: "cinematography-assistant",
            mood,
            latestAnalysis: analysisState.analysis,
          },
        },
        {
          requireCsrf: true,
          timeoutMs: ASSISTANT_REQUEST_TIMEOUT_MS,
          timeoutMessage:
            "انتهت المهلة الزمنية للمساعد. تحقق من الاتصال ثم أعد المحاولة.",
        }
      );

      const answerText = response.data?.response?.trim();

      if (!answerText) {
        throw new Error("لم يصل المساعد بإجابة قابلة للعرض. حاول مرة أخرى.");
      }

      setAssistantState({
        isLoading: false,
        answer: answerText,
        lastQuestion: trimmedQuestion,
        error: null,
      });

      // مسح السؤال فقط بعد نجاح الإرسال
      setAnalysisState((prev) => ({
        ...prev,
        question: "",
      }));
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "فشل في إرسال السؤال";
      setAssistantState((prev) => ({
        ...prev,
        isLoading: false,
        answer: null,
        error: message,
      }));
    }
  }, [
    analysisState.analysis,
    analysisState.question,
    assistantState.isLoading,
    mood,
  ]);

  /**
   * مسح آخر إجابة/خطأ من لوحة المساعد دون مسح السؤال الحالي.
   */
  const dismissAssistantResult = useCallback(() => {
    setAssistantState((prev) => ({
      ...prev,
      answer: null,
      error: null,
    }));
  }, []);

  /**
   * إعادة تعيين حالة التحليل
   */
  const resetAnalysis = useCallback(() => {
    setAnalysisState(initialAnalysisState);
    setAssistantState(initialAssistantState);
    mediaInput.clearMedia();
  }, [mediaInput.clearMedia]);

  // ============================================
  // دوال الإعدادات التقنية
  // ============================================

  /**
   * تبديل إعداد Focus Peaking
   */
  const toggleFocusPeaking = useCallback(() => {
    setTechnicalSettings((prev) => ({
      ...prev,
      focusPeaking: !prev.focusPeaking,
    }));
    toast.success(
      technicalSettings.focusPeaking
        ? "تم إيقاف Focus Peaking"
        : "تم تفعيل Focus Peaking"
    );
  }, [technicalSettings.focusPeaking]);

  /**
   * تبديل إعداد False Color
   */
  const toggleFalseColor = useCallback(() => {
    setTechnicalSettings((prev) => ({
      ...prev,
      falseColor: !prev.falseColor,
    }));
    toast.success(
      technicalSettings.falseColor
        ? "تم إيقاف False Color"
        : "تم تفعيل False Color"
    );
  }, [technicalSettings.falseColor]);

  /**
   * تحديث درجة حرارة اللون
   *
   * @param colorTemp - درجة الحرارة بالكلفن
   */
  const setColorTemp = useCallback((colorTemp: number) => {
    if (colorTemp >= 2000 && colorTemp <= 10000) {
      setTechnicalSettings((prev) => ({
        ...prev,
        colorTemp,
      }));
    }
  }, []);

  /**
   * تحديث درجة حرارة اللون من Slider (يأخذ مصفوفة)
   *
   * @param value - القيمة كمصفوفة من الـ Slider
   */
  const setColorTempFromSlider = useCallback(
    (value: number[]) => {
      const temp = value[0] ?? 3200;
      setColorTemp(temp);
    },
    [setColorTemp]
  );

  /**
   * قيمة درجة الحرارة كمصفوفة للـ Slider
   */
  const colorTempValue = useMemo(
    () => [technicalSettings.colorTemp],
    [technicalSettings.colorTemp]
  );

  // ============================================
  // قيم محسوبة
  // ============================================

  /**
   * درجة الحرارة الموصى بها بناءً على المود الحالي
   */
  const recommendedColorTemp = useMemo((): number => {
    const moodDefaults: Record<VisualMood, number> = {
      noir: 3200,
      realistic: 5600,
      surreal: 4500,
      vintage: 3800,
    };
    return moodDefaults[mood];
  }, [mood]);

  /**
   * التحقق من وجود تحليل جاهز
   */
  const hasAnalysis = useMemo((): boolean => {
    return analysisState.analysis !== null;
  }, [analysisState.analysis]);

  /**
   * التحقق من وجود مشاكل في اللقطة
   */
  const hasIssues = useMemo((): boolean => {
    return (analysisState.analysis?.issues.length ?? 0) > 0;
  }, [analysisState.analysis]);

  /**
   * حالة الجاهزية للتصوير
   */
  const isReadyToShoot = useMemo((): boolean => {
    return hasAnalysis && !hasIssues;
  }, [hasAnalysis, hasIssues]);

  // ============================================
  // القيمة المُرجعة
  // ============================================

  return {
    // حالة التحليل
    analysis: analysisState.analysis,
    analysisSource: analysisState.source,
    isAnalyzing: analysisState.isAnalyzing,
    error: analysisState.error,
    question: analysisState.question,

    // دوال التحليل
    handleAnalyzeShot,
    setQuestion,
    askAssistant,
    resetAnalysis,
    dismissAssistantResult,

    // حالة المساعد الذكي
    assistantAnswer: assistantState.answer,
    assistantError: assistantState.error,
    assistantLastQuestion: assistantState.lastQuestion,
    isAssistantLoading: assistantState.isLoading,

    // إدخال الوسائط
    mediaInput,

    // الإعدادات التقنية
    technicalSettings,
    toggleFocusPeaking,
    toggleFalseColor,
    setColorTemp,
    setColorTempFromSlider,
    colorTempValue,

    // قيم محسوبة
    hasAnalysis,
    hasIssues,
    isReadyToShoot,
    recommendedColorTemp,
  };
}

export default useProduction;

function normalizeShotAnalysis(
  validation:
    | {
        score?: number;
        status?: string;
        exposure?: string;
        composition?: string;
        focus?: string;
        colorBalance?: string;
        suggestions?: string[];
        improvements?: string[];
      }
    | undefined
): ShotAnalysis {
  const issues = [
    ...(validation?.suggestions ?? []),
    ...(validation?.improvements ?? []),
  ].filter((value, index, array) => array.indexOf(value) === index);

  return {
    score: clampScore(validation?.score),
    dynamicRange: validation?.composition || validation?.exposure || "غير متاح",
    grainLevel: validation?.focus || validation?.colorBalance || "غير متاح",
    issues,
    exposure: clampScore(validation?.score),
  };
}

function clampScore(value: number | undefined): number {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return 0;
  }

  return Math.max(0, Math.min(100, Math.round(value)));
}

/**
 * اختبارات تكامل للمحلل المحلي البديل.
 *
 * الهدف:
 * - التأكد من أن مسار الطوارئ ينتج مخرجات صالحة.
 * - التأكد من ثبات العقد عند غياب الخدمة الخلفية.
 */

import { describe, expect, it, vi, beforeAll } from "vitest";
import {
  createLocalFootageSummary,
  createLocalShotAnalysis,
} from "../local-shot-analysis";

// jsdom لا يدعم URL.createObjectURL — نُعيد تعريفه بحيث يُرجع URL وهمي.
// HTMLImageElement في jsdom لا يُطلق onload للـ blob URLs، لذا نستبدله
// بإصدار يُطلق onload كـ microtask فور تعيين المعالج، مما يسمح للـ Promise
// بالتهيؤ قبل الاستدعاء.
beforeAll(() => {
  // محاكاة createObjectURL / revokeObjectURL
  Object.defineProperty(URL, "createObjectURL", {
    writable: true,
    value: vi.fn(() => "blob:mock-url"),
  });
  Object.defineProperty(URL, "revokeObjectURL", {
    writable: true,
    value: vi.fn(),
  });

  // استبدال Image بنسخة تُطلق onload كـ microtask بعد تعيينه
  vi.stubGlobal(
    "Image",
    class MockImage {
      naturalWidth = 320;
      naturalHeight = 180;
      src = "";
      private _onload: (() => void) | null = null;
      private _onerror: ((e: unknown) => void) | null = null;

      set onload(fn: (() => void) | null) {
        this._onload = fn;
        if (fn) {
          // يُطلق المعالج كـ microtask بعد تعيينه مباشرةً
          void Promise.resolve().then(() => fn());
        }
      }
      get onload() {
        return this._onload;
      }

      set onerror(fn: ((e: unknown) => void) | null) {
        this._onerror = fn;
      }
      get onerror() {
        return this._onerror;
      }
    }
  );
});

/** ينشئ ملف PNG وهمي ضمن الذاكرة — لا يعتمد على ملفات fixture خارجية */
function createInMemoryImageFile(): File {
  // أصغر PNG صالح: 1×1 بكسل أبيض مشفّر يدويًا
  const pngBytes = new Uint8Array([
    0x89,
    0x50,
    0x4e,
    0x47,
    0x0d,
    0x0a,
    0x1a,
    0x0a, // PNG signature
    0x00,
    0x00,
    0x00,
    0x0d,
    0x49,
    0x48,
    0x44,
    0x52, // IHDR chunk length + type
    0x00,
    0x00,
    0x00,
    0x01,
    0x00,
    0x00,
    0x00,
    0x01, // width=1, height=1
    0x08,
    0x02,
    0x00,
    0x00,
    0x00,
    0x90,
    0x77,
    0x53, // bit depth=8, colorType=2(RGB)
    0xde,
    0x00,
    0x00,
    0x00,
    0x0c,
    0x49,
    0x44,
    0x41, // IDAT chunk
    0x54,
    0x08,
    0xd7,
    0x63,
    0xf8,
    0xcf,
    0xc0,
    0x00, // compressed image data
    0x00,
    0x00,
    0x02,
    0x00,
    0x01,
    0xe2,
    0x21,
    0xbc, // more data
    0x33,
    0x00,
    0x00,
    0x00,
    0x00,
    0x49,
    0x45,
    0x4e, // IEND chunk
    0x44,
    0xae,
    0x42,
    0x60,
    0x82, // IEND CRC
  ]);
  return new File([pngBytes], "sample-shot.png", { type: "image/png" });
}

describe("local-shot-analysis integration", () => {
  it("ينتج تحليل لقطة صالحًا بعقد ثابت", async () => {
    const file = createInMemoryImageFile();
    const analysis = await createLocalShotAnalysis(file, "noir");

    expect(analysis.score).toBeGreaterThanOrEqual(0);
    expect(analysis.score).toBeLessThanOrEqual(100);
    expect(analysis.exposure).toBeGreaterThanOrEqual(0);
    expect(analysis.exposure).toBeLessThanOrEqual(100);
    expect(typeof analysis.dynamicRange).toBe("string");
    expect(typeof analysis.grainLevel).toBe("string");
    expect(Array.isArray(analysis.issues)).toBe(true);
    expect(analysis.issues.length).toBeGreaterThan(0);
  });

  it("ينتج ملخص مشاهد صالحًا للاستهلاك في الواجهة", async () => {
    const file = createInMemoryImageFile();
    const summary = await createLocalFootageSummary(file, "vintage");

    expect(summary.score).toBeGreaterThanOrEqual(0);
    expect(summary.score).toBeLessThanOrEqual(100);
    expect(typeof summary.status).toBe("string");
    expect(typeof summary.exposure).toBe("string");
    expect(typeof summary.colorBalance).toBe("string");
    expect(typeof summary.focus).toBe("string");
    expect(Array.isArray(summary.suggestions)).toBe(true);
  });
});

/**
 * مدير إعدادات مسار إدخال الوسائط في استوديو التصوير السينمائي.
 *
 * الهدف:
 * - توحيد قيم الحدود التشغيلية في نقطة مركزية.
 * - السماح بتمرير القيم من متغيرات البيئة عند الحاجة.
 * - تقديم قيم افتراضية آمنة عند غياب الضبط الخارجي.
 */

const DEFAULT_IMAGE_MAX_SIZE_MB = 12;
const DEFAULT_VIDEO_MAX_SIZE_MB = 280;
const DEFAULT_CAPTURE_WIDTH = 1280;
const DEFAULT_CAPTURE_HEIGHT = 720;
const DEFAULT_CAPTURE_MIME = "image/png";
const DEFAULT_CAPTURE_QUALITY = 0.92;

function readEnvNumber(
  key: string,
  fallback: number,
  min: number,
  max: number
): number {
  const raw = process.env[key];
  if (!raw) {
    return fallback;
  }

  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) {
    return fallback;
  }

  return Math.min(max, Math.max(min, parsed));
}

function readCaptureMime(): string {
  const raw = (process.env["NEXT_PUBLIC_CINE_CAPTURE_MIME"] || "").trim();
  if (!raw) {
    return DEFAULT_CAPTURE_MIME;
  }

  if (raw !== "image/png" && raw !== "image/jpeg") {
    return DEFAULT_CAPTURE_MIME;
  }

  return raw;
}

export interface CinematographyInputConfig {
  imageMaxSizeBytes: number;
  videoMaxSizeBytes: number;
  captureMimeType: string;
  captureQuality: number;
  captureWidth: number;
  captureHeight: number;
}

export function createCinematographyInputConfig(): CinematographyInputConfig {
  const imageMaxSizeMb = readEnvNumber(
    "NEXT_PUBLIC_CINE_IMAGE_MAX_MB",
    DEFAULT_IMAGE_MAX_SIZE_MB,
    2,
    200
  );

  const videoMaxSizeMb = readEnvNumber(
    "NEXT_PUBLIC_CINE_VIDEO_MAX_MB",
    DEFAULT_VIDEO_MAX_SIZE_MB,
    8,
    2000
  );

  const captureWidth = Math.round(
    readEnvNumber(
      "NEXT_PUBLIC_CINE_CAPTURE_WIDTH",
      DEFAULT_CAPTURE_WIDTH,
      320,
      3840
    )
  );

  const captureHeight = Math.round(
    readEnvNumber(
      "NEXT_PUBLIC_CINE_CAPTURE_HEIGHT",
      DEFAULT_CAPTURE_HEIGHT,
      240,
      2160
    )
  );

  const captureQuality = readEnvNumber(
    "NEXT_PUBLIC_CINE_CAPTURE_QUALITY",
    DEFAULT_CAPTURE_QUALITY,
    0.1,
    1
  );

  return {
    imageMaxSizeBytes: Math.round(imageMaxSizeMb * 1024 * 1024),
    videoMaxSizeBytes: Math.round(videoMaxSizeMb * 1024 * 1024),
    captureMimeType: readCaptureMime(),
    captureQuality,
    captureWidth,
    captureHeight,
  };
}

export const cinematographyInputConfig = Object.freeze(
  createCinematographyInputConfig()
);

/**
 * تحليل محلي احتياطي عند تعذر وصول خدمة التحليل الخلفية.
 *
 * هذا المسار لا يستبدل الخدمة الرسمية، لكنه يضمن استمرار التدفق
 * بوضع متدهور واضح مع نتيجة قابلة للاستخدام الفوري.
 */

import type {
  ShotAnalysis,
  VisualMood,
  FootageAnalysisSummary,
} from "../types";

interface LocalImageStats {
  meanLuma: number;
  varianceLuma: number;
}

function fallbackStats(): LocalImageStats {
  return {
    meanLuma: 0.5,
    varianceLuma: 0.08,
  };
}

async function estimateImageStats(file: File): Promise<LocalImageStats> {
  if (typeof window === "undefined") {
    return fallbackStats();
  }

  const objectUrl = URL.createObjectURL(file);
  try {
    const image = new Image();
    image.src = objectUrl;

    await new Promise<void>((resolve, reject) => {
      image.onload = () => resolve();
      image.onerror = () =>
        reject(new Error("تعذر قراءة الصورة داخل محلل الطوارئ المحلي."));
    });

    const width = Math.min(320, image.naturalWidth || 320);
    const height = Math.min(320, image.naturalHeight || 180);

    if (width <= 0 || height <= 0) {
      return fallbackStats();
    }

    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (!context) {
      return fallbackStats();
    }

    context.drawImage(image, 0, 0, width, height);
    const { data } = context.getImageData(0, 0, width, height);

    let sum = 0;
    let sumSquares = 0;
    let samples = 0;

    for (let index = 0; index < data.length; index += 4) {
      const red = data[index] || 0;
      const green = data[index + 1] || 0;
      const blue = data[index + 2] || 0;
      const luma = (red * 0.2126 + green * 0.7152 + blue * 0.0722) / 255;

      sum += luma;
      sumSquares += luma * luma;
      samples += 1;
    }

    if (samples === 0) {
      return fallbackStats();
    }

    const meanLuma = sum / samples;
    const varianceLuma = Math.max(
      0,
      sumSquares / samples - meanLuma * meanLuma
    );

    return { meanLuma, varianceLuma };
  } catch {
    return fallbackStats();
  } finally {
    URL.revokeObjectURL(objectUrl);
  }
}

function computeMoodBias(mood: VisualMood): number {
  switch (mood) {
    case "noir":
      return -6;
    case "surreal":
      return 4;
    case "vintage":
      return -2;
    default:
      return 0;
  }
}

function scoreFromStats(stats: LocalImageStats, mood: VisualMood): number {
  const exposureBalance = 1 - Math.abs(stats.meanLuma - 0.5) * 1.8;
  const textureBalance = Math.min(1, stats.varianceLuma * 3.2 + 0.25);
  const raw = (exposureBalance * 0.65 + textureBalance * 0.35) * 100;
  const moodBias = computeMoodBias(mood);
  return Math.max(0, Math.min(100, Math.round(raw + moodBias)));
}

function exposureLabel(meanLuma: number): string {
  if (meanLuma < 0.3) {
    return "تعريض منخفض";
  }
  if (meanLuma > 0.72) {
    return "تعريض مرتفع";
  }
  return "تعريض متوازن";
}

function dynamicRangeLabel(variance: number): string {
  if (variance < 0.035) {
    return "تباين محدود";
  }
  if (variance > 0.14) {
    return "تباين واسع";
  }
  return "تباين متزن";
}

function grainLevelLabel(variance: number): string {
  if (variance > 0.16) {
    return "حِدّة مرتفعة";
  }
  if (variance < 0.04) {
    return "تفاصيل ناعمة";
  }
  return "تفاصيل متوازنة";
}

function buildSuggestions(stats: LocalImageStats, mood: VisualMood): string[] {
  const suggestions: string[] = [];

  if (stats.meanLuma < 0.3) {
    suggestions.push("ارفع التعريض نصف درجة لتفادي فقدان التفاصيل في الظلال.");
  } else if (stats.meanLuma > 0.72) {
    suggestions.push("خفّض الإضاءة الرئيسية أو استخدم ND لتجنب الحرق.");
  } else {
    suggestions.push("التعريض ضمن النطاق المقبول للمشهد الحالي.");
  }

  if (stats.varianceLuma < 0.04) {
    suggestions.push("أضف فصلًا ضوئيًا خفيفًا لرفع عمق المشهد.");
  } else if (stats.varianceLuma > 0.16) {
    suggestions.push("قلّل التباين القاسي للحفاظ على التفاصيل في الهايلايت.");
  } else {
    suggestions.push("التباين جيد ويمكن البناء عليه في التدرج النهائي.");
  }

  if (mood === "noir") {
    suggestions.push("المود النواري يستفيد من إضاءة جانبية مع ملء محدود.");
  }

  return suggestions;
}

export async function createLocalShotAnalysis(
  file: File,
  mood: VisualMood
): Promise<ShotAnalysis> {
  const stats = await estimateImageStats(file);
  const score = scoreFromStats(stats, mood);

  return {
    score,
    dynamicRange: dynamicRangeLabel(stats.varianceLuma),
    grainLevel: grainLevelLabel(stats.varianceLuma),
    exposure: Math.max(0, Math.min(100, Math.round(stats.meanLuma * 100))),
    issues: buildSuggestions(stats, mood),
  };
}

export async function createLocalFootageSummary(
  file: File,
  mood: VisualMood
): Promise<FootageAnalysisSummary> {
  const shot = await createLocalShotAnalysis(file, mood);
  return {
    score: shot.score,
    status: shot.score >= 75 ? "ready" : "review-needed",
    exposure: exposureLabel(shot.exposure / 100),
    colorBalance:
      mood === "vintage"
        ? "دفء متوازن"
        : mood === "noir"
          ? "بارد مزاجيًا"
          : "متزن",
    focus: shot.grainLevel,
    suggestions: shot.issues,
  };
}

/**
 * @fileoverview طبقة حفظ آمنة لجلسة استوديو التصوير السينمائي.
 *
 * - تحفظ في localStorage تحت مفتاح ثابت ومختوم بنسخة (v1).
 * - لا تحفظ ملفات وسائط ثقيلة. الفيديو لا يُسلسل أبدًا. الصور المُلتقطة
 *   لا تُحفظ في النسخة الأولى — يكتفى ببقاء آخر تحليل نصي فقط.
 * - تتسامح مع البيانات الفاسدة وتعيد null بدلًا من رمي استثناء.
 *
 * مفتاح التخزين الرسمي:
 *
 *     cinematography-studio.session.v1
 */

import type { Phase, ShotAnalysis, ViewMode, VisualMood } from "../types";

export const SESSION_STORAGE_KEY = "cinematography-studio.session.v1";

/** حقول الجلسة المحفوظة. كلها اختيارية لأن المتصفح قد لا يجد بعضها. */
export interface PersistedStudioSession {
  phase?: Phase;
  view?: ViewMode;
  mood?: VisualMood;
  activeTool?: string | null;
  technicalSettings?: {
    focusPeaking: boolean;
    falseColor: boolean;
    colorTemp: number;
  };
  lastAnalysis?: ShotAnalysis | null;
  lastAssistant?: {
    question: string | null;
    answer: string | null;
  } | null;
  savedAt?: string;
}

const VALID_PHASES: ReadonlyArray<Phase> = ["pre", "production", "post"];
const VALID_VIEWS: ReadonlyArray<ViewMode> = ["dashboard", "phases"];
const VALID_MOODS: ReadonlyArray<VisualMood> = [
  "noir",
  "realistic",
  "surreal",
  "vintage",
];

function isBrowser(): boolean {
  return typeof window !== "undefined" && typeof window.localStorage !== "undefined";
}

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function asBoolean(value: unknown): boolean | undefined {
  return typeof value === "boolean" ? value : undefined;
}

function asNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function sanitizeAnalysis(value: unknown): ShotAnalysis | null {
  if (!value || typeof value !== "object") {
    return null;
  }
  const candidate = value as Record<string, unknown>;
  const score = asNumber(candidate.score);
  const exposure = asNumber(candidate.exposure);
  if (score === undefined || exposure === undefined) {
    return null;
  }

  const issuesRaw = candidate.issues;
  const issues = Array.isArray(issuesRaw)
    ? issuesRaw.filter((entry): entry is string => typeof entry === "string")
    : [];

  return {
    score,
    exposure,
    dynamicRange: asString(candidate.dynamicRange) ?? "غير متاح",
    grainLevel: asString(candidate.grainLevel) ?? "غير متاح",
    issues,
  };
}

function sanitizeSession(value: unknown): PersistedStudioSession | null {
  if (!value || typeof value !== "object") {
    return null;
  }
  const candidate = value as Record<string, unknown>;
  const result: PersistedStudioSession = {};

  const phase = asString(candidate.phase);
  if (phase && (VALID_PHASES as ReadonlyArray<string>).includes(phase)) {
    result.phase = phase as Phase;
  }

  const view = asString(candidate.view);
  if (view && (VALID_VIEWS as ReadonlyArray<string>).includes(view)) {
    result.view = view as ViewMode;
  }

  const mood = asString(candidate.mood);
  if (mood && (VALID_MOODS as ReadonlyArray<string>).includes(mood)) {
    result.mood = mood as VisualMood;
  }

  if (candidate.activeTool === null) {
    result.activeTool = null;
  } else {
    const tool = asString(candidate.activeTool);
    if (tool) {
      result.activeTool = tool;
    }
  }

  if (candidate.technicalSettings && typeof candidate.technicalSettings === "object") {
    const techRaw = candidate.technicalSettings as Record<string, unknown>;
    const focusPeaking = asBoolean(techRaw.focusPeaking);
    const falseColor = asBoolean(techRaw.falseColor);
    const colorTemp = asNumber(techRaw.colorTemp);
    if (
      focusPeaking !== undefined &&
      falseColor !== undefined &&
      colorTemp !== undefined &&
      colorTemp >= 2000 &&
      colorTemp <= 10000
    ) {
      result.technicalSettings = { focusPeaking, falseColor, colorTemp };
    }
  }

  result.lastAnalysis = sanitizeAnalysis(candidate.lastAnalysis);

  if (candidate.lastAssistant && typeof candidate.lastAssistant === "object") {
    const assistantRaw = candidate.lastAssistant as Record<string, unknown>;
    const question = asString(assistantRaw.question);
    const answer = asString(assistantRaw.answer);
    if (question || answer) {
      result.lastAssistant = {
        question: question ?? null,
        answer: answer ?? null,
      };
    } else {
      result.lastAssistant = null;
    }
  }

  const savedAt = asString(candidate.savedAt);
  if (savedAt) {
    result.savedAt = savedAt;
  }

  return result;
}

/**
 * يقرأ الجلسة المحفوظة. يعيد null عند غياب المتصفح أو عند فساد البيانات.
 * لا يرمي أبدًا.
 */
export function readSession(): PersistedStudioSession | null {
  if (!isBrowser()) {
    return null;
  }

  try {
    const raw = window.localStorage.getItem(SESSION_STORAGE_KEY);
    if (!raw) {
      return null;
    }
    const parsed = JSON.parse(raw);
    return sanitizeSession(parsed);
  } catch {
    return null;
  }
}

/**
 * يدمج تحديثًا جزئيًا مع الجلسة الحالية ويحفظ النتيجة.
 * يتحمّل أخطاء الكوتا أو وضع الخصوصية بصمت.
 */
export function patchSession(patch: PersistedStudioSession): void {
  if (!isBrowser()) {
    return;
  }
  try {
    const current = readSession() ?? {};
    const merged: PersistedStudioSession = {
      ...current,
      ...patch,
      savedAt: new Date().toISOString(),
    };
    window.localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(merged));
  } catch {
    // تجاهل الأخطاء — عدم إعاقة المستخدم بسبب فشل تخزين محلي.
  }
}

/**
 * يمسح جلسة الاستوديو المحفوظة بالكامل.
 */
export function clearSession(): void {
  if (!isBrowser()) {
    return;
  }
  try {
    window.localStorage.removeItem(SESSION_STORAGE_KEY);
  } catch {
    // تجاهل
  }
}

"use client";

const CSRF_COOKIE_NAME = "XSRF-TOKEN";

function getCookie(name: string): string | null {
  if (typeof document === "undefined") {
    return null;
  }

  const entry = document.cookie
    .split("; ")
    .find((cookie) => cookie.startsWith(`${name}=`));

  if (!entry) {
    return null;
  }

  const [, value] = entry.split("=");
  return value ? decodeURIComponent(value) : null;
}

async function ensureCsrfToken(): Promise<string> {
  const existingToken = getCookie(CSRF_COOKIE_NAME);
  if (existingToken) {
    return existingToken;
  }

  await fetch("/api/health", {
    method: "GET",
    credentials: "include",
    cache: "no-store",
  });

  const refreshedToken = getCookie(CSRF_COOKIE_NAME);
  if (!refreshedToken) {
    throw new Error(
      "تعذر الحصول على رمز الحماية. أعد تسجيل الجلسة ثم حاول مرة أخرى."
    );
  }

  return refreshedToken;
}

async function buildError(response: Response): Promise<Error> {
  let message = `فشل الطلب (${response.status})`;

  try {
    const payload = (await response.json()) as {
      error?: string;
      message?: string;
      code?: string;
    };

    if (
      payload.code === "CSRF_TOKEN_MISSING" ||
      payload.code === "CSRF_TOKEN_INVALID"
    ) {
      message = "فشل التحقق الأمني للطلب. أعد تسجيل الجلسة ثم حاول مرة أخرى.";
    } else {
      message = payload.message || payload.error || message;
    }
  } catch {
    // Keep the generic message when the payload is not JSON.
  }

  return new Error(message);
}

export interface StudioRequestOptions {
  requireCsrf?: boolean;
  /** Timeout in milliseconds. When exceeded the request is aborted. */
  timeoutMs?: number;
  /** Custom message surfaced when the timeout fires. */
  timeoutMessage?: string;
}

async function postStudioRoute<TResponse>(
  path: string,
  init: RequestInit,
  options: StudioRequestOptions = {}
): Promise<TResponse> {
  const { requireCsrf = false, timeoutMs, timeoutMessage } = options;
  const headers = new Headers(init.headers);

  if (requireCsrf) {
    const csrfToken = await ensureCsrfToken();
    headers.set("X-XSRF-TOKEN", csrfToken);
    headers.set("x-xsrf-token", csrfToken);
  }

  const controller = timeoutMs != null ? new AbortController() : null;
  const timer =
    controller && timeoutMs != null
      ? setTimeout(() => controller.abort(), timeoutMs)
      : null;

  try {
    const response = await fetch(path, {
      ...init,
      headers,
      credentials: "include",
      cache: "no-store",
      signal: controller?.signal ?? init.signal ?? null,
    });

    if (!response.ok) {
      throw await buildError(response);
    }

    return (await response.json()) as TResponse;
  } catch (error) {
    if (error instanceof DOMException && error.name === "AbortError") {
      throw new Error(
        timeoutMessage ??
          `انتهت المهلة الزمنية للطلب (${timeoutMs}ms). حاول مرة أخرى.`
      );
    }
    throw error;
  } finally {
    if (timer != null) clearTimeout(timer);
  }
}

export async function postStudioJson<TResponse>(
  path: string,
  body: unknown,
  options?: StudioRequestOptions
): Promise<TResponse> {
  return postStudioRoute<TResponse>(
    path,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    },
    options
  );
}

export async function postStudioFormData<TResponse>(
  path: string,
  formData: FormData,
  options?: StudioRequestOptions
): Promise<TResponse> {
  return postStudioRoute<TResponse>(
    path,
    {
      method: "POST",
      body: formData,
    },
    options
  );
}

