/**
 * @fileoverview أنواع البيانات الخاصة بصفحة التطوير الإبداعي
 *
 * يحتوي هذا الملف على جميع الـ Interfaces والـ Types المستخدمة
 * في مكونات التطوير الإبداعي لضمان Type Safety كاملة
 *
 * @module development/types
 */

import { z } from "zod";

/**
 * أنواع المهام الإبداعية المتاحة
 * تُستخدم لتحديد نوع المهمة التي يختارها المستخدم
 */
export enum CreativeTaskType {
  /** إبداع محاكي - توليد محتوى إبداعي جديد */
  CREATIVE = "CREATIVE",
  /** إكمال النص - إكمال نص ناقص */
  COMPLETION = "COMPLETION",
  /** إعادة الكتابة التكيفية - تعديل النص حسب السياق */
  ADAPTIVE_REWRITING = "ADAPTIVE_REWRITING",
  /** مولد المشاهد - توليد مشاهد جديدة */
  SCENE_GENERATOR = "SCENE_GENERATOR",
  /** صوت الشخصية - محاكاة صوت شخصية معينة */
  CHARACTER_VOICE = "CHARACTER_VOICE",
  /** بناء العالم - توسيع عالم القصة */
  WORLD_BUILDER = "WORLD_BUILDER",
  /** متنبئ الحبكة - التنبؤ بأحداث القصة */
  PLOT_PREDICTOR = "PLOT_PREDICTOR",
  /** محسّن التوتر - تحسين التوتر الدرامي */
  TENSION_OPTIMIZER = "TENSION_OPTIMIZER",
  /** خريطة الإيقاع - تحليل إيقاع القصة */
  RHYTHM_MAPPING = "RHYTHM_MAPPING",
  /** شبكة الشخصيات - تحليل علاقات الشخصيات */
  CHARACTER_NETWORK = "CHARACTER_NETWORK",
  /** تشريح الحوار - تحليل عميق للحوارات */
  DIALOGUE_FORENSICS = "DIALOGUE_FORENSICS",
  /** استخراج الثيمات - اكتشاف الموضوعات الرئيسية */
  THEMATIC_MINING = "THEMATIC_MINING",
  /** بصمة الأسلوب - تحليل الأسلوب الكتابي */
  STYLE_FINGERPRINT = "STYLE_FINGERPRINT",
  /** ديناميكيات الصراع - تحليل الصراعات الدرامية */
  CONFLICT_DYNAMICS = "CONFLICT_DYNAMICS",
}

/**
 * تسميات المهام الإبداعية بالعربية
 * تُستخدم لعرض أسماء المهام في واجهة المستخدم
 */
export const CREATIVE_TASK_LABELS: Record<CreativeTaskType, string> = {
  [CreativeTaskType.CREATIVE]: "إبداع محاكي",
  [CreativeTaskType.COMPLETION]: "إكمال النص",
  [CreativeTaskType.ADAPTIVE_REWRITING]: "إعادة الكتابة التكيفية",
  [CreativeTaskType.SCENE_GENERATOR]: "مولد المشاهد",
  [CreativeTaskType.CHARACTER_VOICE]: "صوت الشخصية",
  [CreativeTaskType.WORLD_BUILDER]: "بناء العالم",
  [CreativeTaskType.PLOT_PREDICTOR]: "متنبئ الحبكة",
  [CreativeTaskType.TENSION_OPTIMIZER]: "محسّن التوتر",
  [CreativeTaskType.RHYTHM_MAPPING]: "خريطة الإيقاع",
  [CreativeTaskType.CHARACTER_NETWORK]: "شبكة الشخصيات",
  [CreativeTaskType.DIALOGUE_FORENSICS]: "تشريح الحوار",
  [CreativeTaskType.THEMATIC_MINING]: "استخراج الثيمات",
  [CreativeTaskType.STYLE_FINGERPRINT]: "بصمة الأسلوب",
  [CreativeTaskType.CONFLICT_DYNAMICS]: "ديناميكيات الصراع",
};

/**
 * إعدادات أنظمة الذكاء الاصطناعي المتقدمة
 * تتحكم في تفعيل/تعطيل الأنظمة المتقدمة
 */
export interface AdvancedAISettings {
  /** تفعيل نظام الاسترجاع المعزز (RAG) */
  enableRAG: boolean;
  /** تفعيل النقد الذاتي للمخرجات */
  enableSelfCritique: boolean;
  /** تفعيل الذكاء الدستوري للالتزام بالقواعد */
  enableConstitutional: boolean;
  /** تفعيل كشف الهلوسات والتحقق من الدقة */
  enableHallucination: boolean;
  /** تفعيل قياس عدم اليقين */
  enableUncertainty: boolean;
  /** تفعيل النقاش متعدد الوكلاء */
  enableDebate: boolean;
}

/**
 * القيم الافتراضية لإعدادات الذكاء الاصطناعي
 */
export const DEFAULT_AI_SETTINGS: AdvancedAISettings = {
  enableRAG: true,
  enableSelfCritique: true,
  enableConstitutional: true,
  enableHallucination: true,
  enableUncertainty: false,
  enableDebate: false,
};

/**
 * ملف معالج للإدخال
 * يمثل ملفاً تم تحميله وجاهز للمعالجة
 */
export interface ProcessedInputFile {
  /** اسم الملف */
  fileName: string;
  /** محتوى الملف النصي */
  textContent: string;
  /** حجم الملف بالأحرف */
  size: number;
  /** حجم الملف بالبايت */
  sizeBytes: number;
}

/**
 * استجابة الذكاء الاصطناعي
 * تمثل الرد من نظام الذكاء الاصطناعي
 */
export interface AIResponseData {
  /** النص المولد */
  text: string;
  /** البيانات الخام من النموذج */
  raw: string;
  /** مستوى الثقة في الاستجابة */
  confidence?: number;
  /** البيانات الوصفية الإضافية */
  metadata?: Record<string, unknown>;
}

/**
 * طلب الذكاء الاصطناعي
 * يمثل طلباً مرسلاً لنظام الذكاء الاصطناعي
 */
export interface AIRequestData {
  /** معرف الوكيل المستهدف */
  agent: string;
  /** الطلب أو التعليمات الخاصة */
  prompt: string;
  /** سياق الطلب */
  context: {
    /** الملفات المرفقة */
    files: ProcessedInputFile[];
  };
  /** خيارات إضافية */
  options: {
    /** معلومات إضافية */
    additionalInfo?: string;
    /** تقرير التحليل السابق */
    analysisReport?: string;
    /** معرف التحليل */
    analysisId?: string | null;
    /** نطاق الإكمال المطلوب */
    completionScope?: string;
    /** التحسينات المختارة للإكمال */
    selectedCompletionEnhancements?: CreativeTaskType[];
  };
}

/**
 * بيانات تحليل المحطات السبع
 * تمثل نتائج تحليل سابق من نظام المحطات السبع
 */
export interface SevenStationsAnalysis {
  /** التقرير النهائي */
  finalReport: string;
  /** النص الأصلي */
  originalText: string;
  /** مستوى الثقة */
  confidence: number;
  /** مخرجات المحطات */
  stationOutputs?: {
    station7?: unknown;
  };
}

/**
 * تقرير الوكيل
 * يمثل تقريراً مولداً من أحد الوكلاء
 */
export interface AgentReport {
  /** اسم الوكيل */
  agentName: string;
  /** معرف الوكيل */
  agentId: string;
  /** نص التقرير */
  text: string;
  /** مستوى الثقة */
  confidence: number;
  /** الطابع الزمني */
  timestamp: string;
}

/**
 * نتائج المهام
 * يمثل مجموعة من نتائج المهام المنجزة
 */
export type TaskResults = Record<string, AgentReport>;

/**
 * حالة التطوير الإبداعي
 * تمثل الحالة الكاملة لصفحة التطوير
 */
export interface CreativeDevelopmentState {
  /** النص المدخل */
  textInput: string;
  /** المهمة المختارة */
  selectedTask: CreativeTaskType | null;
  /** المتطلبات الخاصة */
  specialRequirements: string;
  /** معلومات إضافية */
  additionalInfo: string;
  /** نطاق الإكمال */
  completionScope: string;
  /** التحسينات المختارة */
  selectedCompletionEnhancements: CreativeTaskType[];
  /** تقرير التحليل */
  analysisReport: string;
  /** هل اكتمل التحليل */
  isAnalysisComplete: boolean;
  /** نتائج المهام */
  taskResults: TaskResults;
  /** معرف modal التقرير المعروض */
  showReportModal: string | null;
  /** معرف التحليل */
  analysisId: string | null;
  /** إعدادات الذكاء الاصطناعي المتقدمة */
  advancedSettings: AdvancedAISettings;
  /** استجابة الذكاء الاصطناعي */
  aiResponse: AIResponseData | null;
  /** رسالة الخطأ */
  error: string | null;
  /** حالة التحميل */
  isLoading: boolean;
}

// ============================================
// Development Full Agent Catalog Types (27 tasks)
// ============================================

/**
 * فئة المهمة داخل كتالوج أدوات التطوير
 *
 * - `core`       — المهام الأساسية الموروثة من المسار الكلاسيكي (14 مهمة)
 * - `analysis`   — مهام التحليل العميق للنص الدرامي
 * - `creative`   — مهام توليد المحتوى الإبداعي
 * - `predictive` — مهام التنبؤ بمسار القصة
 * - `advanced`   — وكلاء متخصصون ذوو قدرات متقدمة
 */
export type DevelopmentTaskCategory =
  | "core"
  | "analysis"
  | "creative"
  | "predictive"
  | "advanced";

/**
 * وضع التنفيذ الذي يحدد المسار الخلفي لكل مهمة
 *
 * - `brainstorm`       — يُرسل الطلب إلى POST /api/brainstorm (المسار الكلاسيكي، 16 مهمة)
 * - `workflow-single`  — يُرسل الطلب إلى POST /api/workflow/execute-custom بخطوة واحدة (9 مهام)
 * - `workflow-custom`  — يُرسل الطلب إلى POST /api/workflow/execute-custom بمسار متعدد الخطوات (2 مهمة مركبة)
 */
export type DevelopmentExecutionMode =
  | "brainstorm"
  | "workflow-single"
  | "workflow-custom";

/**
 * تعريف مهمة واحدة قابلة للاختيار من المستخدم داخل صفحة development
 *
 * يُستخدم لبناء كتالوج 27 مهمة موزعة على 5 فئات.
 * قيمة `executionMode` تحدد شكل `backendTarget` والمسار الخلفي المُستخدم.
 */
export interface DevelopmentTaskDefinition {
  /** معرّف فريد للمهمة داخل الكتالوج — يجب أن يتطابق مع معرّف الوكيل في الباك إند */
  id: string;
  /** الاسم العربي للمهمة كما يظهر للمستخدم في الواجهة */
  nameAr: string;
  /** فئة المهمة لتجميع العرض في الواجهة */
  category: DevelopmentTaskCategory;
  /** اسم الأيقونة المرتبطة بالمهمة في task-icon-mapper */
  icon: string;
  /** وصف مختصر يظهر كـ tooltip عند تحريك المؤشر على الزر */
  description: string;
  /** وضع التنفيذ الذي يحدد المسار الخلفي المُستخدم */
  executionMode: DevelopmentExecutionMode;
  /**
   * الهدف الخلفي للمهمة:
   * - سلسلة نصية لمعرّف الوكيل عند `brainstorm`
   * - كائن `WorkflowTaskTarget` عند `workflow-single` أو `workflow-custom`
   */
  backendTarget: string | WorkflowTaskTarget;
  /**
   * معرّف الخطوة النهائية المُستخدم لاستخراج `finalText` من نتيجة التنفيذ.
   * يجب أن يشير إلى خطوة فعلية قابلة للاستخراج من ناتج التنفيذ.
   */
  finalStepId: string;
}

/**
 * المدخلات المشتركة التي يستخدمها أي تشغيل داخل صفحة development
 *
 * تُبنى من حالة الهوك وتُمرَّر إلى ExecutionAdapter لتحديد المسار الصحيح.
 * `completionScope` و`selectedCompletionEnhancements` مشروطان ولا يُمرَّران
 * إلا عند اختيار مهمة `completion`.
 */
export interface DevelopmentExecutionInput {
  /** معرّف المهمة المختارة من الكتالوج */
  taskId: string;
  /** النص الدرامي الأصلي المُدخَل من المستخدم — خاضع لحد الطول الأدنى 100 حرف */
  originalText: string;
  /** تقرير تحليل المحطات السبع — يجب أن يكون متاحًا قبل فتح التنفيذ */
  analysisReport: string;
  /** معرّف جلسة التحليل أو null إذا لم يكن متاحًا */
  analysisId: string | null;
  /** متطلبات خاصة أو توجيهات إضافية للوكيل */
  specialRequirements: string;
  /** معلومات سياقية داعمة اختيارية */
  additionalInfo: string;
  /** نطاق الإكمال المطلوب — مطلوب فقط للمهام التي تحتاجه (completion) */
  completionScope?: string;
  /** التحسينات المختارة للإكمال — صالح فقط في مسار completion */
  selectedCompletionEnhancements?: string[];
  /** إعدادات أنظمة الذكاء الاصطناعي المتقدمة */
  advancedSettings: AdvancedAISettings;
}

/**
 * خطوة واحدة داخل تكوين workflow مخصص
 *
 * تُستخدم لبناء `WorkflowTaskTarget` للمهام التي تُنفَّذ عبر execute-custom.
 * المهام أحادية الوكيل تمتلك خطوة واحدة فقط بدون تبعيات.
 */
export interface WorkflowTaskStep {
  /** معرّف الخطوة — يُستخدم كـ finalStepId في تعريف المهمة */
  id: string;
  /** معرّف الوكيل المنفّذ لهذه الخطوة */
  agentId: string;
  /** نوع المهمة التي سيؤديها الوكيل */
  taskType: string;
  /**
   * التبعيات على خطوات سابقة — تحدد ترتيب التنفيذ ومتطلبات الاعتماد.
   * تُترك فارغة للخطوات الأولى أو المستقلة.
   */
  dependencies?: Array<{
    agentId: string;
    taskType: string;
    /** إذا كان true يتوقف التنفيذ عند فشل هذه التبعية */
    required?: boolean;
    /** الحد الأدنى لمستوى الثقة المقبول من التبعية */
    minConfidence?: number;
  }>;
  /** إذا كان true يمكن تنفيذ هذه الخطوة بالتوازي مع خطوات أخرى */
  parallel?: boolean;
}

/**
 * التكوين الداخلي للمهام التي تُنفَّذ عبر POST /api/workflow/execute-custom
 *
 * يُبنى إما من خطوة واحدة (workflow-single) أو خطوات متعددة (workflow-custom).
 * يُمرَّر كحقل `config` في جسم الطلب إلى الباك إند.
 */
export interface WorkflowTaskTarget {
  /** نوع ثابت يُعرّف هذا الكائن كـ custom workflow */
  type: "custom-workflow";
  /** اسم الـ workflow يُستخدم في السجلات والتتبع */
  name: string;
  /** وصف يُوضح الغرض من الـ workflow */
  description: string;
  /** مصفوفة الخطوات المُرتبة — الخطوة الأخيرة تُنتج finalText */
  steps: WorkflowTaskStep[];
}

/**
 * ناتج خطوة واحدة داخل workflow أو مخرجات داعمة من مسار brainstorm
 *
 * يُستخدم لعرض النتائج الداعمة في AgentReportViewer وتصديرها عبر AgentReportsExporter.
 * الخطوات ذات `status !== "completed"` تُستثنى من التصدير.
 */
export interface SupportingStepResult {
  /** معرّف الخطوة يُطابق `WorkflowTaskStep.id` */
  stepId: string;
  /** معرّف الوكيل الذي نفّذ الخطوة */
  agentId: string;
  /** عنوان الخطوة للعرض في الواجهة */
  title: string;
  /** النص الناتج من الخطوة */
  text: string;
  /** مستوى الثقة في الناتج (0–1) */
  confidence?: number;
  /** حالة تنفيذ الخطوة */
  status: "completed" | "failed" | "skipped";
  /** الطابع الزمني لبداية التنفيذ (ISO 8601) */
  startedAt?: string;
  /** الطابع الزمني لانتهاء التنفيذ (ISO 8601) */
  completedAt?: string;
}

/**
 * التقرير الموحّد الذي تستهلكه الواجهة بعد التطبيع بغض النظر عن مسار التنفيذ
 *
 * يُنتج من `normalizeResult()` في result-normalizer.ts ويُضمَن دائمًا
 * عند نجاح التنفيذ في جميع المسارات (brainstorm / workflow-single / workflow-custom).
 * `finalText` يأتي من `finalStepId` أو من النص النهائي لمسار brainstorm.
 * `taskResults` يحتوي فقط النتائج المكتملة فعليًا (`status === "completed"`).
 */
export interface UnifiedDevelopmentReport {
  /** معرّف المهمة المُنفَّذة — يُطابق `DevelopmentTaskDefinition.id` */
  taskId: string;
  /** وضع التنفيذ المُستخدم — يُستخدم لتتبع الفشل وتشخيص المسار */
  executionMode: DevelopmentExecutionMode;
  /** النص النهائي المُستخرج من الخطوة المحددة بـ finalStepId */
  finalText: string;
  /** استجابة الذكاء الاصطناعي الكاملة للعرض والتصدير */
  aiResponse: AIResponseData;
  /** خريطة نتائج الخطوات المكتملة — مفتاحها معرّف الخطوة أو الوكيل */
  taskResults: Record<string, AgentReport>;
}

/**
 * اسم بديل لـ UnifiedDevelopmentReport يُستخدم كشكل الناتج الأساسي في الواجهة
 *
 * يضمن توافق الأنواع عند استهلاك النتائج من أي مسار تنفيذ.
 */
export type NormalizedDevelopmentResult = UnifiedDevelopmentReport;

// ============================================
// Zod Schemas للتحقق من البيانات
// ============================================

/**
 * مخطط التحقق من إعدادات الذكاء الاصطناعي
 */
export const advancedAISettingsSchema = z.object({
  enableRAG: z.boolean(),
  enableSelfCritique: z.boolean(),
  enableConstitutional: z.boolean(),
  enableHallucination: z.boolean(),
  enableUncertainty: z.boolean(),
  enableDebate: z.boolean(),
});

/**
 * مخطط التحقق من ملف معالج
 */
export const processedInputFileSchema = z.object({
  fileName: z.string().min(1, "اسم الملف مطلوب"),
  textContent: z.string().min(100, "يجب أن يحتوي النص على 100 حرف على الأقل"),
  size: z.number().positive(),
  sizeBytes: z.number().positive(),
});

/**
 * مخطط التحقق من طلب الذكاء الاصطناعي
 */
export const aiRequestSchema = z.object({
  agent: z.string().min(1, "معرف الوكيل مطلوب"),
  prompt: z.string(),
  context: z.object({
    files: z.array(processedInputFileSchema),
  }),
  options: z.object({
    additionalInfo: z.string().optional(),
    analysisReport: z.string().optional(),
    analysisId: z.string().nullable().optional(),
    completionScope: z.string().optional(),
    selectedCompletionEnhancements: z
      .array(z.nativeEnum(CreativeTaskType))
      .optional(),
  }),
});

/**
 * مخطط التحقق من مدخلات التقديم
 */
export const submitInputSchema = z.object({
  textInput: z.string().min(100, "يجب أن يحتوي النص على 100 حرف على الأقل"),
  selectedTask: z.nativeEnum(CreativeTaskType),
  completionScope: z.string().optional(),
});

/**
 * نوع الطلب بعد التحقق
 */
export type ValidatedAIRequest = z.infer<typeof aiRequestSchema>;

/**
 * نوع مدخلات التقديم بعد التحقق
 */
export type ValidatedSubmitInput = z.infer<typeof submitInputSchema>;

/**
 * @fileoverview Unit tests for result-normalizer.ts (T026)
 *
 * Covers:
 *  - BrainstormDebateResponse with finalDecision → finalText extracted
 *  - BrainstormDebateResponse with judgeReasoning fallback
 *  - BrainstormDebateResponse with only proposals → concatenation
 *  - WorkflowExecutionResponse single-step → finalText from results[finalStepId]
 *  - WorkflowExecutionResponse multi-step → taskResults populated for completed steps
 *  - Failed step excluded from taskResults
 */

import { describe, it, expect } from "vitest";
import { normalizeResult } from "./result-normalizer";
import type { DevelopmentTaskDefinition } from "../types";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Build a minimal DevelopmentTaskDefinition for testing */
function makeTask(
  id: string,
  finalStepId: string,
  executionMode: DevelopmentTaskDefinition["executionMode"] = "brainstorm"
): DevelopmentTaskDefinition {
  return {
    id,
    nameAr: `مهمة ${id}`,
    category: "core",
    icon: "Test",
    description: "test task",
    executionMode,
    backendTarget: "/api/brainstorm",
    finalStepId,
  };
}

// ---------------------------------------------------------------------------
// Brainstorm response tests
// ---------------------------------------------------------------------------

describe("normalizeResult — BrainstormDebateResponse", () => {
  const task = makeTask("creative", "creative", "brainstorm");

  it("extracts finalDecision as finalText when present", () => {
    const raw = {
      finalDecision: "النص النهائي من القاضي",
      judgeReasoning: "تفسير القاضي",
      proposals: [
        { agentId: "agent1", text: "اقتراح الوكيل", confidence: 0.8 },
      ],
    };

    const report = normalizeResult(raw, task);

    expect(report.finalText).toBe("النص النهائي من القاضي");
    expect(report.taskId).toBe("creative");
    expect(report.executionMode).toBe("brainstorm");
  });

  it("falls back to judgeReasoning when finalDecision is absent", () => {
    const raw = {
      judgeReasoning: "تفسير القاضي المفصل",
      proposals: [{ agentId: "agent1", text: "اقتراح", confidence: 0.7 }],
    };

    const report = normalizeResult(raw, task);

    expect(report.finalText).toBe("تفسير القاضي المفصل");
  });

  it("falls back to judgeReasoning when finalDecision is an empty string", () => {
    const raw = {
      finalDecision: "   ",
      judgeReasoning: "تفسير مهم",
    };

    const report = normalizeResult(raw, task);

    // trimmed empty string is falsy — should fall through to judgeReasoning
    expect(report.finalText).toBe("تفسير مهم");
  });

  it("concatenates proposals text when finalDecision and judgeReasoning are absent", () => {
    const raw = {
      proposals: [
        { agentId: "agent1", text: "الاقتراح الأول", confidence: 0.9 },
        { agentId: "agent2", text: "الاقتراح الثاني", confidence: 0.8 },
      ],
    };

    const report = normalizeResult(raw, task);

    expect(report.finalText).toContain("الاقتراح الأول");
    expect(report.finalText).toContain("الاقتراح الثاني");
  });

  it("proposals without text are filtered out during concatenation", () => {
    const raw = {
      proposals: [
        { agentId: "agent1", text: "النص الصحيح", confidence: 0.9 },
        { agentId: "agent2", text: "", confidence: 0.5 },
        { agentId: "agent3", confidence: 0.4 },
      ],
    };

    const report = normalizeResult(raw, task);

    expect(report.finalText).toContain("النص الصحيح");
    expect(report.finalText).not.toContain("agent2");
  });

  it("aiResponse.text equals finalText", () => {
    const raw = { finalDecision: "النص النهائي" };
    const report = normalizeResult(raw, task);

    expect(report.aiResponse.text).toBe(report.finalText);
  });

  it("aiResponse.raw is a JSON string of the original response", () => {
    const raw = { finalDecision: "نص", proposals: [] };
    const report = normalizeResult(raw, task);

    const parsed = JSON.parse(report.aiResponse.raw) as typeof raw;
    expect(parsed.finalDecision).toBe("نص");
  });

  it("taskResults is populated from proposals with valid text", () => {
    const raw = {
      proposals: [
        {
          agentId: "agent1",
          agentName: "الوكيل الأول",
          text: "نتيجة الوكيل 1",
          confidence: 0.9,
        },
        {
          agentId: "agent2",
          agentName: "الوكيل الثاني",
          text: "نتيجة الوكيل 2",
          confidence: 0.7,
        },
      ],
    };

    const report = normalizeResult(raw, task);

    expect(report.taskResults).toHaveProperty("agent1");
    expect(report.taskResults).toHaveProperty("agent2");
    expect(report.taskResults["agent1"].text).toBe("نتيجة الوكيل 1");
    expect(report.taskResults["agent2"].confidence).toBe(0.7);
  });

  it("taskResults excludes proposals without agentId", () => {
    const raw = {
      proposals: [
        { text: "نص بدون agentId", confidence: 0.8 },
        { agentId: "agent1", text: "نص مع agentId", confidence: 0.9 },
      ],
    };

    const report = normalizeResult(raw, task);

    expect(Object.keys(report.taskResults)).toHaveLength(1);
    expect(report.taskResults).toHaveProperty("agent1");
  });

  it("returns empty string finalText when all fields are missing", () => {
    const raw = {};
    const report = normalizeResult(raw, task);

    expect(report.finalText).toBe("");
  });

  it("handles null input gracefully", () => {
    const report = normalizeResult(null, task);

    expect(report.finalText).toBe("");
    expect(report.taskId).toBe("creative");
  });
});

// ---------------------------------------------------------------------------
// Workflow response tests
// ---------------------------------------------------------------------------

describe("normalizeResult — WorkflowExecutionResponse", () => {
  const singleStepTask = makeTask(
    "character-deep-analyzer",
    "character-deep-analyzer",
    "workflow-single"
  );

  it("extracts finalText from results[finalStepId] for single-step workflow", () => {
    const raw = {
      status: "completed",
      results: {
        "character-deep-analyzer": {
          agentId: "character-deep-analyzer",
          taskType: "character-deep-analyzer",
          status: "completed",
          output: { text: "تحليل الشخصيات المعمق", confidence: 0.95 },
        },
      },
    };

    const report = normalizeResult(raw, singleStepTask);

    expect(report.finalText).toBe("تحليل الشخصيات المعمق");
    expect(report.executionMode).toBe("workflow-single");
    expect(report.taskId).toBe("character-deep-analyzer");
  });

  it("aiResponse.confidence comes from the final step output", () => {
    const raw = {
      status: "completed",
      results: {
        "character-deep-analyzer": {
          status: "completed",
          output: { text: "النتيجة", confidence: 0.88 },
        },
      },
    };

    const report = normalizeResult(raw, singleStepTask);

    expect(report.aiResponse.confidence).toBe(0.88);
  });

  it("taskResults is populated for all completed steps in multi-step workflow", () => {
    const multiTask = makeTask("integrated", "integrated", "workflow-custom");
    const raw = {
      status: "completed",
      results: {
        analysis: {
          agentId: "analysis",
          taskType: "analysis",
          status: "completed",
          output: { text: "نتيجة التحليل", confidence: 0.9 },
        },
        creative: {
          agentId: "creative",
          taskType: "creative",
          status: "completed",
          output: { text: "نتيجة الإبداع", confidence: 0.85 },
        },
        integrated: {
          agentId: "integrated",
          taskType: "integrated",
          status: "completed",
          output: { text: "النتيجة المتكاملة", confidence: 0.92 },
        },
      },
    };

    const report = normalizeResult(raw, multiTask);

    expect(report.taskResults).toHaveProperty("analysis");
    expect(report.taskResults).toHaveProperty("creative");
    expect(report.taskResults).toHaveProperty("integrated");
    expect(report.taskResults["analysis"].text).toBe("نتيجة التحليل");
    expect(report.taskResults["creative"].text).toBe("نتيجة الإبداع");
    expect(report.finalText).toBe("النتيجة المتكاملة");
  });

  it("failed step is excluded from taskResults", () => {
    const multiTask = makeTask(
      "recommendations-generator",
      "recommendations",
      "workflow-custom"
    );
    const raw = {
      status: "partial",
      results: {
        "target-audience": {
          agentId: "target-audience-analyzer",
          status: "completed",
          output: { text: "تحليل الجمهور", confidence: 0.8 },
        },
        "literary-quality": {
          agentId: "literary-quality-analyzer",
          status: "failed",
          output: { text: "حدث خطأ", confidence: 0 },
        },
        recommendations: {
          agentId: "recommendations-generator",
          status: "completed",
          output: { text: "التوصيات النهائية", confidence: 0.75 },
        },
      },
    };

    const report = normalizeResult(raw, multiTask);

    expect(report.taskResults).toHaveProperty("target-audience");
    expect(report.taskResults).toHaveProperty("recommendations");
    // failed step must NOT appear
    expect(report.taskResults).not.toHaveProperty("literary-quality");
  });

  it("step with empty output text is excluded from taskResults", () => {
    const raw = {
      status: "completed",
      results: {
        "character-deep-analyzer": {
          agentId: "character-deep-analyzer",
          status: "completed",
          output: { text: "", confidence: 0 },
        },
      },
    };

    const report = normalizeResult(raw, singleStepTask);

    expect(Object.keys(report.taskResults)).toHaveLength(0);
    expect(report.finalText).toBe("");
  });

  it("returns empty finalText when finalStepId is not in results", () => {
    const raw = {
      status: "completed",
      results: {
        "some-other-step": {
          agentId: "other",
          status: "completed",
          output: { text: "نتيجة خطوة أخرى", confidence: 0.8 },
        },
      },
    };

    const report = normalizeResult(raw, singleStepTask);

    // finalStepId is 'character-deep-analyzer' but only 'some-other-step' exists
    expect(report.finalText).toBe("");
  });

  it("taskResults agentName falls back to stepId when agentId is absent", () => {
    const raw = {
      status: "completed",
      results: {
        "character-deep-analyzer": {
          // no agentId field
          status: "completed",
          output: { text: "النتيجة", confidence: 0.9 },
        },
      },
    };

    const report = normalizeResult(raw, singleStepTask);

    expect(report.taskResults["character-deep-analyzer"].agentName).toBe(
      "character-deep-analyzer"
    );
    expect(report.taskResults["character-deep-analyzer"].agentId).toBe(
      "character-deep-analyzer"
    );
  });

  it("aiResponse.raw is a JSON string of the original workflow response", () => {
    const raw = {
      status: "completed",
      results: {
        "character-deep-analyzer": {
          status: "completed",
          output: { text: "نص", confidence: 0.9 },
        },
      },
      metrics: { duration: 1234 },
    };

    const report = normalizeResult(raw, singleStepTask);

    const parsed = JSON.parse(report.aiResponse.raw) as typeof raw;
    expect(parsed.status).toBe("completed");
    expect(parsed.metrics).toEqual({ duration: 1234 });
  });

  it("aiResponse.metadata comes from workflow metrics", () => {
    const raw = {
      status: "completed",
      results: {
        "character-deep-analyzer": {
          status: "completed",
          output: { text: "نتيجة", confidence: 0.9 },
        },
      },
      metrics: { totalDuration: 500, agentCount: 1 },
    };

    const report = normalizeResult(raw, singleStepTask);

    expect(report.aiResponse.metadata).toEqual({
      totalDuration: 500,
      agentCount: 1,
    });
  });

  it("distinguishes workflow from brainstorm by presence of results object", () => {
    // Same shape test: if `results` key exists → workflow path
    const withResults = { results: {} };
    const withoutResults = { finalDecision: "نص" };

    const workflowReport = normalizeResult(withResults, singleStepTask);
    const brainstormReport = normalizeResult(
      withoutResults,
      makeTask("creative", "creative", "brainstorm")
    );

    // workflow path returns finalText from results[finalStepId] (empty here)
    expect(workflowReport.finalText).toBe("");
    // brainstorm path returns finalDecision
    expect(brainstormReport.finalText).toBe("نص");
  });
});

import type {
  DevelopmentTaskDefinition,
  UnifiedDevelopmentReport,
  AIResponseData,
} from "../types";

interface BrainstormProposal {
  agentId?: string;
  agentName?: string;
  text?: string;
  confidence?: number;
}

interface BrainstormResponse {
  finalDecision?: string;
  judgeReasoning?: string;
  proposals?: BrainstormProposal[];
  metadata?: Record<string, unknown>;
}

interface WorkflowStepOutput {
  text?: string;
  confidence?: number;
}

interface WorkflowStepResult {
  agentId?: string;
  taskType?: string;
  status?: string;
  output?: WorkflowStepOutput;
}

interface WorkflowResponse {
  status?: string;
  results?: Record<string, WorkflowStepResult>;
  metrics?: Record<string, unknown>;
}

function extractBrainstormFinalText(data: BrainstormResponse): string {
  if (data.finalDecision?.trim()) return data.finalDecision;
  if (data.judgeReasoning?.trim()) return data.judgeReasoning;
  if (data.proposals?.length) {
    return data.proposals
      .filter((p) => p.text?.trim())
      .map((p) => p.text)
      .join("\n\n");
  }
  return "";
}

function normalizeBrainstorm(
  raw: BrainstormResponse,
  task: DevelopmentTaskDefinition
): UnifiedDevelopmentReport {
  const finalText = extractBrainstormFinalText(raw);
  const confidence = raw.proposals?.[0]?.confidence;
  const metadata = raw.metadata;

  const aiResponse: AIResponseData = {
    text: finalText,
    raw: JSON.stringify(raw),
    ...(typeof confidence === "number" ? { confidence } : {}),
    ...(metadata ? { metadata } : {}),
  };

  const taskResults: Record<
    string,
    {
      agentName: string;
      agentId: string;
      text: string;
      confidence: number;
      timestamp: string;
    }
  > = {};
  if (raw.proposals) {
    for (const proposal of raw.proposals) {
      if (proposal.agentId && proposal.text?.trim()) {
        taskResults[proposal.agentId] = {
          agentName: proposal.agentName || proposal.agentId,
          agentId: proposal.agentId,
          text: proposal.text,
          confidence: proposal.confidence ?? 0,
          timestamp: new Date().toISOString(),
        };
      }
    }
  }

  return {
    taskId: task.id,
    executionMode: task.executionMode,
    finalText,
    aiResponse,
    taskResults,
  };
}

function normalizeWorkflow(
  raw: WorkflowResponse,
  task: DevelopmentTaskDefinition
): UnifiedDevelopmentReport {
  const results = raw.results || {};
  const finalStep = results[task.finalStepId];
  const finalText = finalStep?.output?.text || "";
  const confidence = finalStep?.output?.confidence;
  const metadata = raw.metrics as Record<string, unknown> | undefined;

  const aiResponse: AIResponseData = {
    text: finalText,
    raw: JSON.stringify(raw),
    ...(typeof confidence === "number" ? { confidence } : {}),
    ...(metadata ? { metadata } : {}),
  };

  const taskResults: Record<
    string,
    {
      agentName: string;
      agentId: string;
      text: string;
      confidence: number;
      timestamp: string;
    }
  > = {};
  for (const [stepId, step] of Object.entries(results)) {
    if (step.status === "completed" && step.output?.text?.trim()) {
      taskResults[stepId] = {
        agentName: step.agentId || stepId,
        agentId: step.agentId || stepId,
        text: step.output.text,
        confidence: step.output.confidence ?? 0,
        timestamp: new Date().toISOString(),
      };
    }
  }

  return {
    taskId: task.id,
    executionMode: task.executionMode,
    finalText,
    aiResponse,
    taskResults,
  };
}

export function normalizeResult(
  raw: unknown,
  task: DevelopmentTaskDefinition
): UnifiedDevelopmentReport {
  const data =
    typeof raw === "object" && raw !== null
      ? (raw as Record<string, unknown>)
      : {};

  // Workflow responses have a `results` object with step outputs
  if ("results" in data && typeof data.results === "object") {
    return normalizeWorkflow(data as unknown as WorkflowResponse, task);
  }

  // Brainstorm responses have proposals/finalDecision
  return normalizeBrainstorm(data as unknown as BrainstormResponse, task);
}

/**
 * @fileoverview أداة ربط الأيقونات بالمهام
 *
 * تُستخدم لتبسيط تعقيد المكون الرئيسي عن طريق فصل منطق
 * اختيار الأيقونات إلى وحدة منفصلة مع بحث O(1)
 *
 * @module development/utils/task-icon-mapper
 */

import {
  Lightbulb,
  Sparkles,
  FileText,
  PenTool,
  Users,
  Search,
  Film,
  Globe,
  BarChart,
  Wand2,
  Brain,
  MessageSquare,
  TrendingUp,
  Zap,
  Music,
  Network,
  Palette,
  Target,
  // أيقونات المهام المتقدمة الجديدة
  UserCheck,
  MessagesSquare,
  Camera,
  BookOpen,
  Landmark,
  Factory,
  Award,
  ListChecks,
  Layers,
  Activity,
  Gem,
  Fingerprint,
  Swords,
  RefreshCw,
  Mic,
  Gauge,
  Heart,
  Monitor,
  PenLine,
} from "lucide-react";
import { TaskType, TaskCategory } from "@/types/enums";
import { CreativeTaskType } from "../types";

/**
 * خريطة الأيقونات لأنواع المهام العامة
 * تُستخدم للوصول السريع O(1) بدلاً من switch متعددة
 */
const TASK_TYPE_ICONS: Partial<Record<TaskType, React.ReactNode>> = {
  [TaskType.ANALYSIS]: <Lightbulb className="w-4 h-4" />,
  [TaskType.CREATIVE]: <Sparkles className="w-4 h-4" />,
  [TaskType.INTEGRATED]: <FileText className="w-4 h-4" />,
  [TaskType.COMPLETION]: <PenTool className="w-4 h-4" />,
  [TaskType.CHARACTER_DEEP_ANALYZER]: <Users className="w-4 h-4" />,
  [TaskType.DIALOGUE_ADVANCED_ANALYZER]: <Search className="w-4 h-4" />,
  [TaskType.VISUAL_CINEMATIC_ANALYZER]: <Film className="w-4 h-4" />,
  [TaskType.THEMES_MESSAGES_ANALYZER]: <Lightbulb className="w-4 h-4" />,
  [TaskType.CULTURAL_HISTORICAL_ANALYZER]: <Globe className="w-4 h-4" />,
  [TaskType.PRODUCIBILITY_ANALYZER]: <BarChart className="w-4 h-4" />,
  [TaskType.TARGET_AUDIENCE_ANALYZER]: <Users className="w-4 h-4" />,
