"use client";

import React from "react";
import dynamic from "next/dynamic";
import { useSearchParams } from "next/navigation";
import type { ApiResponse, Project } from "@/lib/api-types";
import { clearCurrentProject, setCurrentProject } from "@/lib/projectStore";
import { DirectorsEditorConfigManager } from "@/lib/directors-editor/config-manager";
import { directorsEditorLogger } from "@/lib/directors-editor/logger";

const EditorApp = dynamic(
  () => import("./src/App").then((m) => ({ default: m.App })),
  {
    ssr: false,
    loading: () => (
      <div className="flex h-screen items-center justify-center bg-[oklch(0.145_0_0)] text-[oklch(0.985_0_0)]">
        <span className="text-sm" style={{ fontFamily: "Cairo, sans-serif" }}>
          جارٍ تحميل المحرر...
        </span>
      </div>
    ),
  }
);

let initialized = false;

export default function EditorPage() {
  const searchParams = useSearchParams();
  const searchParamsKey = searchParams.toString();
  const [projectSyncError, setProjectSyncError] = React.useState<string | null>(
    null
  );

  React.useEffect(() => {
    if (initialized) return;
    initialized = true;
    let isActive = true;
    let toasterElement: HTMLElement | null = null;

    void import("./src/providers").then(({ createThemeProvider }) => {
      if (!isActive) return;
      createThemeProvider({
        attribute: "class",
        defaultTheme: "dark",
        enableSystem: false,
        storageKey: "filmlane.theme",
      });
    });

    void import("./src/components/ui/toaster").then(({ createToaster }) => {
      if (!isActive || typeof document === "undefined") return;
      const toaster = createToaster();
      toasterElement = toaster.element;
      document.body.appendChild(toaster.element);
    });

    return () => {
      isActive = false;
      if (toasterElement?.isConnected) {
        toasterElement.remove();
      }
    };
  }, []);

  React.useEffect(() => {
    const config = DirectorsEditorConfigManager.getConfig();
    const params = new URLSearchParams(searchParamsKey);
    const projectId =
      params.get(config.projectQueryParam)?.trim() ??
      params.get("projectId")?.trim() ??
      "";

    if (!projectId) {
      setProjectSyncError(null);
      return;
    }

    let active = true;

    const syncProjectFromQuery = async () => {
      directorsEditorLogger.info({
        event: "editor-project-sync-started",
        message: "Project sync from editor query has started.",
        data: { projectId },
      });
      setProjectSyncError(null);

      try {
        const response = await fetch(
          `/api/projects/${encodeURIComponent(projectId)}`,
          {
            method: "GET",
            credentials: "include",
            cache: "no-store",
          }
        );
        const payload = (await response.json()) as ApiResponse<Project>;
        const project = payload?.data;

        if (!response.ok || !payload?.success || !project?.id) {
          const reason =
            payload?.error ||
            `تعذر تحميل المشروع المطلوب (${response.status}).`;
          throw new Error(reason);
        }

        const normalizedProject: Project = {
          ...project,
          scriptContent: project.scriptContent ?? null,
        };
        setCurrentProject(normalizedProject);

        if (typeof window !== "undefined") {
          window.dispatchEvent(
            new CustomEvent("directors-editor:project-synced")
          );
        }

        if (!active) return;
        setProjectSyncError(null);

        directorsEditorLogger.info({
          event: "editor-project-sync-succeeded",
          message: "Editor query project synced successfully.",
          data: {
            projectId: normalizedProject.id,
            projectTitle: normalizedProject.title,
          },
        });
      } catch (error) {
        clearCurrentProject();

        if (typeof window !== "undefined") {
          window.dispatchEvent(
            new CustomEvent("directors-editor:project-synced")
          );
        }

        const message =
          error instanceof Error && error.message.trim()
            ? error.message.trim()
            : "تعذر مزامنة المشروع المطلوب.";

        directorsEditorLogger.error({
          event: "editor-project-sync-failed",
          message: "Failed to sync editor project context from query.",
          data: { projectId, error: message },
        });

        if (!active) return;
        setProjectSyncError(message);
      }
    };

    void syncProjectFromQuery();

    return () => {
      active = false;
    };
  }, [searchParamsKey]);

  return (
    <main className="relative h-screen">
      {projectSyncError ? (
        <div
          className="pointer-events-none absolute top-4 left-1/2 z-[120] w-[min(92vw,760px)] -translate-x-1/2 rounded-xl border border-red-500/40 bg-red-950/80 px-4 py-3 text-right text-sm text-red-100 shadow-2xl backdrop-blur-xl"
          data-testid="editor-project-sync-error"
          role="alert"
          aria-live="assertive"
        >
          فشل تحميل المشروع من رابط الاستوديو.
          <br />
          {projectSyncError}
        </div>
      ) : null}
      <EditorApp />
    </main>
  );
}

import { readdir, unlink, writeFile } from "fs/promises";
import { join } from "path";

// فئة مخصصة لتسجيل الأحداث بشكل احترافي لتجنب استخدام console.log الممنوع هندسياً
class Logger {
  static info(message: string): void {
    process.stdout.write(
      `[معلومات] ${new Date().toISOString()} - ${message}\n`
    );
  }

  static error(message: string, error?: unknown): void {
    process.stderr.write(
      `[خطأ] ${new Date().toISOString()} - ${message} - ${error ? String(error) : ""}\n`
    );
  }
}

// فئة لإدارة إعدادات بيئة التنظيف والاستبعاد لضمان فصل الإعدادات عن المنطق البرمجي
class ConfigManager {
  // محتوى ملفات الاستبعاد التي سيتم إنشاؤها لتوجيه وكيل الذكاء الاصطناعي
  static readonly IGNORE_CONTENT: string = `
# المجلدات المستبعدة من الفهرسة
node_modules/
dist/
fonts/

# الملفات المؤقتة والسجلات
*.log
*.timestamp-*.mjs
*.zip

# المستندات الثنائية
*.doc
*.docx
`.trim();

  // أسماء ملفات الاستبعاد الشائعة لوكلاء البرمجة
  static readonly IGNORE_FILES: string[] = [".windsurfignore", ".cursorignore"];

  // الأنماط النصية (Regex) للملفات المؤقتة التي يجب حذفها فعلياً لتنظيف البيئة
  static readonly DELETE_PATTERNS: RegExp[] = [
    /\.timestamp-.*\.mjs$/,
    /^firebase-debug.*\.log$/,
  ];

  // المجلدات التي يجب تخطيها أثناء البحث لضمان سرعة الأداء
  static readonly SKIP_DIRECTORIES: string[] = [
    "node_modules",
    "dist",
    ".git",
    ".agents",
  ];
}

// الفئة المسؤولة عن تنفيذ عمليات التنظيف وإنشاء الملفات بشكل غير متزامن
class WorkspaceCleaner {
  private readonly targetDirectory: string;

  constructor(targetDirectory: string = process.cwd()) {
    this.targetDirectory = targetDirectory;
  }

  // الدالة الرئيسية التي تدير دورة العمل
  public async execute(): Promise<void> {
    Logger.info("بدء عملية تجهيز مساحة العمل للفهرسة...");
    try {
      await Promise.all([
        this.generateIgnoreFiles(),
        this.removeTemporaryFiles(this.targetDirectory),
      ]);
      Logger.info("تم الانتهاء من تجهيز مساحة العمل بنجاح.");
    } catch (error) {
      Logger.error("فشل في تنفيذ عملية التجهيز الشاملة", error);
    }
  }

  // دالة لإنشاء أو تحديث ملفات الاستبعاد الخاصة بوكلاء الذكاء الاصطناعي
  private async generateIgnoreFiles(): Promise<void> {
    for (const fileName of ConfigManager.IGNORE_FILES) {
      const filePath = join(this.targetDirectory, fileName);
      try {
        await writeFile(filePath, ConfigManager.IGNORE_CONTENT, {
          encoding: "utf8",
        });
        Logger.info(`تم إنشاء/تحديث ملف الاستبعاد: ${fileName}`);
      } catch (error) {
        Logger.error(`فشل في إنشاء ملف ${fileName}`, error);
      }
    }
  }

  // دالة للبحث المتكرر وحذف الملفات المؤقتة بناءً على الأنماط المحددة (Recursion)
  private async removeTemporaryFiles(directory: string): Promise<void> {
    try {
      const entries = await readdir(directory, { withFileTypes: true });

      const deletePromises = entries.map(async (entry) => {
        const fullPath = join(directory, entry.name);

        if (entry.isDirectory()) {
          // استثناء المجلدات الثقيلة من البحث لتسريع الأداء وتجنب استهلاك الذاكرة
          if (ConfigManager.SKIP_DIRECTORIES.includes(entry.name)) {
            return;
          }
          await this.removeTemporaryFiles(fullPath);
        } else if (entry.isFile()) {
          // التحقق مما إذا كان الملف يطابق أي نمط من أنماط الحذف
          const shouldDelete = ConfigManager.DELETE_PATTERNS.some((pattern) =>
            pattern.test(entry.name)
          );
          if (shouldDelete) {
            try {
              await unlink(fullPath);
              Logger.info(`تم حذف الملف المؤقت: ${entry.name}`);
            } catch (deleteError) {
              Logger.error(`لم يتم حذف الملف: ${fullPath}`, deleteError);
            }
          }
        }
      });

      await Promise.all(deletePromises);
    } catch (error) {
      Logger.error(`خطأ أثناء قراءة المجلد: ${directory}`, error);
    }
  }
}

// نقطة الإطلاق للتنفيذ الفوري
(async () => {
  const cleaner = new WorkspaceCleaner();
  await cleaner.execute();
})();

