#!/usr/bin/env tsx
/**
 * DOCX to DOC Converter (TypeScript + Word COM)
 *
 * تحويل ملفات DOCX إلى DOC باستخدام Microsoft Word COM Automation
 *
 * Usage:
 *   npx tsx server/docx-to-doc.final.ts input.docx [output.doc] [--overwrite]
 *
 * Requirements:
 *   - Microsoft Word installed
 *   - npm install winax
 */

import * as path from "path";
import * as fs from "fs";
import { fileURLToPath } from "node:url";

// Type definitions for winax
interface WordApplication {
  Visible: boolean;
  Documents: {
    Open(filename: string): WordDocument;
  };
  Quit(): void;
}

interface WordDocument {
  SaveAs(filename: string, fileFormat: number): void;
  Close(saveChanges: boolean): void;
}

interface WinaxModule {
  Object: new (
    progId: string,
    options?: {
      activate?: boolean;
      type?: boolean;
    }
  ) => WordApplication;
}

// Word format constants
const WdFormatDocument97 = 0; // DOC format

const writeInfo = (message: string): void => {
  process.stdout.write(`${message}\n`);
};

const writeError = (message: string): void => {
  process.stderr.write(`${message}\n`);
};

const toErrorMessage = (error: unknown): string =>
  error instanceof Error ? error.message : String(error);

async function convertDocxToDoc(
  inputPath: string,
  outputPath?: string,
  overwrite: boolean = false
): Promise<void> {
  // Resolve absolute paths
  const absInputPath = path.resolve(inputPath);

  if (!fs.existsSync(absInputPath)) {
    throw new Error(`Input file not found: ${absInputPath}`);
  }

  // Determine output path
  const absOutputPath = outputPath
    ? path.resolve(outputPath)
    : absInputPath.replace(/\.docx$/i, ".doc");

  // Check if output exists
  if (fs.existsSync(absOutputPath) && !overwrite) {
    throw new Error(
      `Output file already exists: ${absOutputPath}\nUse --overwrite to replace it.`
    );
  }

  writeInfo(`📄 Input:  ${absInputPath}`);
  writeInfo(`💾 Output: ${absOutputPath}`);
  writeInfo("🔄 Converting...");

  let wordApp: WordApplication | null = null;
  let doc: WordDocument | null = null;

  try {
    // Import winax dynamically (ESM-safe)
    const winaxModule = await import("winax");
    const winax =
      (winaxModule as unknown as { default?: WinaxModule }).default ??
      (winaxModule as unknown as WinaxModule);

    // Create Word Application COM object
    const app = new winax.Object("Word.Application", {
      activate: false,
      type: true,
    });
    wordApp = app;

    // Hide Word window
    app.Visible = false;

    // Open document
    doc = app.Documents.Open(absInputPath);

    // Save as DOC format
    doc.SaveAs(absOutputPath, WdFormatDocument97);

    // Close document
    doc.Close(false);
    doc = null;

    writeInfo("✅ Conversion successful!");

    // Get file size
    const stats = fs.statSync(absOutputPath);
    const sizeKB = (stats.size / 1024).toFixed(2);
    writeInfo(`📊 Output size: ${sizeKB} KB`);
  } catch (error: unknown) {
    const message = toErrorMessage(error);
    writeError(`❌ Error: ${message}`);

    if (message.includes("winax")) {
      writeError("\n💡 Install winax: npm install winax");
    }

    if (message.includes("Word.Application")) {
      writeError("\n💡 Make sure Microsoft Word is installed.");
    }

    throw error;
  } finally {
    // Cleanup
    try {
      doc?.Close(false);
      wordApp?.Quit();
    } catch {
      // Ignore cleanup errors
    }
  }
}

// CLI interface
async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0 || args.includes("--help") || args.includes("-h")) {
    writeInfo(`
DOCX to DOC Converter (TypeScript + Word COM)

Usage:
  npx tsx server/docx-to-doc.final.ts <input.docx> [output.doc] [--overwrite]

Arguments:
  input.docx      Path to input DOCX file
  output.doc      (Optional) Output DOC file path
                  Default: same name as input with .doc extension
  --overwrite     Overwrite output file if it exists

Examples:
  npx tsx server/docx-to-doc.final.ts document.docx
  npx tsx server/docx-to-doc.final.ts document.docx output.doc
  npx tsx server/docx-to-doc.final.ts document.docx --overwrite

Requirements:
  - Microsoft Word must be installed
  - Run: npm install winax
    `);
    process.exit(0);
  }

  const inputPath = args[0];
  if (!inputPath) {
    writeError("❌ Input path is required.");
    process.exit(1);
  }

  const hasOverwrite = args.includes("--overwrite");

  // Find output path (if provided and not --overwrite)
  const outputPath = args.find(
    (arg, idx) => idx > 0 && arg !== "--overwrite" && !arg.startsWith("-")
  );

  try {
    await convertDocxToDoc(inputPath, outputPath, hasOverwrite);
    process.exit(0);
  } catch (error: unknown) {
    writeError(`\n❌ Conversion failed: ${toErrorMessage(error)}`);
    process.exit(1);
  }
}

const isMainModule = (): boolean => {
  const currentFile = fileURLToPath(import.meta.url);
  const entryFile = process.argv[1] ? path.resolve(process.argv[1]) : "";
  return entryFile === path.resolve(currentFile);
};

// Run if called directly
if (isMainModule()) {
  main();
}

export { convertDocxToDoc };

/**
 * @description KarankBridge — مدير subprocess للتواصل مع محرك Python عبر stdio JSON lines
 */

import { spawn, spawnSync } from "node:child_process";
import { createInterface } from "node:readline";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { existsSync } from "node:fs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ENGINE_PATH = resolve(
  __dirname,
  "karank_engine",
  "engine",
  "ts_bridge.py"
);
const MIN_PYTHON_MAJOR = 3;
const MIN_PYTHON_MINOR = 10;

const resolveTimeoutFromEnv = (name, fallbackMs) => {
  const rawValue = process.env[name];
  if (!rawValue) return fallbackMs;

  const parsedValue = Number.parseInt(rawValue, 10);
  if (!Number.isFinite(parsedValue) || parsedValue <= 0) {
    return fallbackMs;
  }

  return parsedValue;
};

const PING_TIMEOUT_MS = resolveTimeoutFromEnv("KARANK_PING_TIMEOUT_MS", 10_000);
const REQUEST_TIMEOUT_MS = resolveTimeoutFromEnv(
  "KARANK_REQUEST_TIMEOUT_MS",
  30_000
);
const DOCX_REQUEST_TIMEOUT_MS = Math.max(
  REQUEST_TIMEOUT_MS,
  resolveTimeoutFromEnv("KARANK_DOCX_REQUEST_TIMEOUT_MS", 120_000)
);
const SHUTDOWN_TIMEOUT_MS = 5_000;

/** @type {{ command: string, args: string[], version: { major: number, minor: number } } | null} */
let resolvedPythonRuntime = null;

/** @type {"idle" | "starting" | "ready" | "dead" | "error"} */
let state = "idle";

/** @type {import("node:child_process").ChildProcess | null} */
let proc = null;

/** @type {import("node:readline").Interface | null} */
let rl = null;

/** @type {Map<string, { resolve: Function, reject: Function, timer: NodeJS.Timeout }>} */
const pending = new Map();

let requestCounter = 0;
let retryAttempted = false;

/**
 * التحقق من توفر Python 3.10+ وحلّ الأمر المناسب لتشغيل المحرك.
 */
const trimEnvValue = (value) => (typeof value === "string" ? value.trim() : "");

const parsePythonVersion = (output) => {
  const match = String(output ?? "").match(/Python\s+(\d+)\.(\d+)/u);
  if (!match) {
    return null;
  }

  return {
    major: Number(match[1]),
    minor: Number(match[2]),
  };
};

const isSupportedPythonVersion = (version) => {
  if (!version) {
    return false;
  }

  return (
    version.major > MIN_PYTHON_MAJOR ||
    (version.major === MIN_PYTHON_MAJOR && version.minor >= MIN_PYTHON_MINOR)
  );
};

const formatCandidateLabel = (candidate) =>
  [candidate.command, ...candidate.args].join(" ").trim();

const getPythonCandidates = () => {
  const candidates = [];
  const configuredExecutable =
    trimEnvValue(process.env.KARANK_PYTHON_BIN) ||
    trimEnvValue(process.env.PYTHON_BIN) ||
    trimEnvValue(process.env.PYTHON_EXECUTABLE) ||
    trimEnvValue(process.env.PYTHON);

  if (configuredExecutable) {
    candidates.push({ command: configuredExecutable, args: [] });
  }

  if (process.platform === "win32") {
    const preferredVersion = trimEnvValue(process.env.KARANK_PYTHON_VERSION);
    if (preferredVersion) {
      candidates.push({ command: "py", args: [`-${preferredVersion}`] });
    }

    for (const version of ["3.13", "3.12", "3.11", "3.10"]) {
      candidates.push({ command: "py", args: [`-${version}`] });
    }
  }

  candidates.push({ command: "python", args: [] });
  candidates.push({ command: "python3", args: [] });

  const deduped = [];
  const seen = new Set();
  for (const candidate of candidates) {
    const key = formatCandidateLabel(candidate);
    if (!key || seen.has(key)) {
      continue;
    }

    seen.add(key);
    deduped.push(candidate);
  }

  return deduped;
};

const probePythonCandidate = (candidate) => {
  const result = spawnSync(
    candidate.command,
    [...candidate.args, "--version"],
    {
      encoding: "utf-8",
      timeout: 5_000,
      windowsHide: true,
    }
  );

  if (result.error) {
    return {
      ok: false,
      candidate,
      reason: result.error.message,
    };
  }

  const output = `${result.stdout || ""}\n${result.stderr || ""}`.trim();
  const version = parsePythonVersion(output);
  if (!version) {
    return {
      ok: false,
      candidate,
      reason: `تعذر تحديد إصدار Python من الناتج: "${output || "<empty>"}".`,
    };
  }

  if (!isSupportedPythonVersion(version)) {
    return {
      ok: false,
      candidate,
      reason: `Python ${version.major}.${version.minor} غير مدعوم. المطلوب: Python ${MIN_PYTHON_MAJOR}.${MIN_PYTHON_MINOR}+.`,
    };
  }

  return {
    ok: true,
    candidate,
    version,
  };
};

const checkPython = () => {
  if (resolvedPythonRuntime) {
    return resolvedPythonRuntime;
  }

  const attempts = [];
  for (const candidate of getPythonCandidates()) {
    const probe = probePythonCandidate(candidate);
    if (probe.ok) {
      resolvedPythonRuntime = {
        command: candidate.command,
        args: candidate.args,
        version: probe.version,
      };
      return resolvedPythonRuntime;
    }

    attempts.push(`${formatCandidateLabel(candidate)} → ${probe.reason}`);
  }

  throw new Error(
    [
      `تعذر العثور على Python مناسب لتشغيل karank bridge. المطلوب: Python ${MIN_PYTHON_MAJOR}.${MIN_PYTHON_MINOR}+.`,
      attempts.length > 0 ? `المحاولات: ${attempts.join(" | ")}` : null,
      "يمكنك ضبط KARANK_PYTHON_BIN على المسار الصحيح لـ python.exe أو استخدام KARANK_PYTHON_VERSION مع py على ويندوز.",
    ]
      .filter(Boolean)
      .join(" ")
  );
};

/**
 * التحقق من وجود ملفات المحرك
 */
const checkEngineFiles = () => {
  if (!existsSync(ENGINE_PATH)) {
    throw new Error(
      `ملف المحرك غير موجود: ${ENGINE_PATH}. تأكد من نسخ ملفات المحرك إلى server/karank_engine/engine/.`
    );
  }
};

const nextId = () => `req-${++requestCounter}-${Date.now()}`;

/**
 * إعادة تعيين المحرك بعد طلب متعثر حتى لا تبقى الطلبات اللاحقة عالقة خلفه.
 * @param {string} requestId
 * @param {number} timeoutMs
 */
const restartAfterTimeout = (requestId, timeoutMs) => {
  if (!proc || proc.killed) {
    state = "dead";
    return;
  }

  console.warn(
    `[karank-bridge] انتهت مهلة ${requestId} بعد ${timeoutMs}ms، إعادة تشغيل المحرك.`
  );
  state = "dead";
  proc.kill();
};

/**
 * معالجة سطر JSON قادم من stdout
 */
const handleLine = (line) => {
  const trimmed = line.trim();
  if (!trimmed) return;

  let parsed;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    console.warn("[karank-bridge] تعذر تحليل سطر JSON:", trimmed.slice(0, 200));
    return;
  }

  const id = parsed?.id;
  if (!id || !pending.has(id)) return;

  const { resolve: res, timer } = pending.get(id);
  clearTimeout(timer);
  pending.delete(id);
  res(parsed);
};

/**
 * تشغيل عملية Python
 */
const spawnProcess = () => {
  state = "starting";

  const pythonRuntime = checkPython();
  proc = spawn(
    pythonRuntime.command,
    [...pythonRuntime.args, "-u", ENGINE_PATH],
    {
      stdio: ["pipe", "pipe", "pipe"],
      windowsHide: true,
      env: { ...process.env, PYTHONUTF8: "1" },
    }
  );

  rl = createInterface({ input: proc.stdout });
  rl.on("line", handleLine);

  proc.stderr.on("data", (chunk) => {
    const text = chunk.toString().trim();
    if (text) console.warn("[karank-bridge:stderr]", text);
  });

  proc.on("close", (code) => {
    const wasReady = state === "ready";
    state = "dead";
    rl = null;
    proc = null;

    // reject all pending requests
    for (const [_id, { reject: rej, timer }] of pending) {
      clearTimeout(timer);
      rej(new Error(`عملية المحرك انتهت برمز ${code}`));
    }
    pending.clear();

    if (wasReady) {
      console.warn(`[karank-bridge] العملية انتهت برمز ${code}`);
    }
  });
};

/**
 * إرسال طلب JSON وانتظار الرد
 */
const sendRequest = (payload, timeoutMs = REQUEST_TIMEOUT_MS) => {
  return new Promise((resolve, reject) => {
    if (!proc || !proc.stdin.writable) {
      reject(new Error("عملية المحرك غير نشطة"));
      return;
    }

    const id = payload.id;
    const timer = setTimeout(() => {
      pending.delete(id);
      const timeoutError = new Error(`انتهت مهلة الطلب ${id} (${timeoutMs}ms)`);
      restartAfterTimeout(id, timeoutMs);
      reject(timeoutError);
    }, timeoutMs);

    pending.set(id, { resolve, reject, timer });

    proc.stdin.write(JSON.stringify(payload) + "\n", "utf-8", (err) => {
      if (err) {
        clearTimeout(timer);
        pending.delete(id);
        reject(err);
      }
    });
  });
};

/**
 * إرسال ping والتحقق من الجاهزية
 */
const ping = async () => {
  const id = nextId();
  const response = await sendRequest({ id, action: "ping" }, PING_TIMEOUT_MS);
  if (!response?.ok) {
    throw new Error("المحرك لم يُرجع ping ناجح");
  }
  return response;
};

/**
 * ضمان جاهزية البريدج — lazy spawn + ping
 */
const ensureReady = async () => {
  if (state === "ready" && proc && !proc.killed) return;

  if (state === "error") {
    throw new Error("المحرك في حالة خطأ نهائي. أعد تشغيل الخادم.");
  }

  checkPython();
  checkEngineFiles();

  spawnProcess();

  try {
    await ping();
    state = "ready";
    retryAttempted = false;
    console.log("[karank-bridge] المحرك جاهز");
  } catch (error) {
    if (!retryAttempted) {
      retryAttempted = true;
      console.warn("[karank-bridge] فشل ping الأول، محاولة إعادة تشغيل...");

      if (proc && !proc.killed) proc.kill();
      proc = null;
      rl = null;

      spawnProcess();

      try {
        await ping();
        state = "ready";
        console.log("[karank-bridge] المحرك جاهز بعد إعادة التشغيل");
      } catch (retryError) {
        state = "error";
        if (proc && !proc.killed) proc.kill();
        proc = null;
        rl = null;
        throw new Error(
          `تعذر تشغيل المحرك بعد محاولتين. ${retryError.message}`,
          { cause: retryError }
        );
      }
    } else {
      state = "error";
      throw error;
    }
  }
};

/**
 * تحليل نص عبر المحرك
 * @param {string} text - النص العربي
 * @returns {Promise<object>} نتيجة التحليل
 */
export const parseText = async (text) => {
  await ensureReady();
  const id = nextId();
  const response = await sendRequest({
    id,
    action: "parseText",
    text,
  });

  if (!response?.ok) {
    const errMsg = response?.error?.message || "فشل تحليل النص";
    throw new Error(errMsg);
  }

  return response.result;
};

/**
 * تحليل ملف DOCX عبر المحرك
 * @param {string} docxPath - المسار المطلق لملف DOCX
 * @param {number} [timeoutMs] - مهلة اختيارية لهذا الطلب فقط
 * @returns {Promise<object>} نتيجة التحليل
 */
export const parseDocx = async (
  docxPath,
  timeoutMs = DOCX_REQUEST_TIMEOUT_MS
) => {
  await ensureReady();
  const id = nextId();
  const response = await sendRequest(
    {
      id,
      action: "parseDocx",
      path: docxPath,
    },
    timeoutMs
  );

  if (!response?.ok) {
    const errMsg = response?.error?.message || "فشل تحليل DOCX";
    throw new Error(errMsg);
  }

  return response.result;
};

/**
 * إيقاف البريدج بشكل آمن
 */
export const destroy = async () => {
  if (!proc || proc.killed) {
    state = "idle";
    return;
  }

  try {
    const id = nextId();
    proc.stdin.write(
      JSON.stringify({ id, action: "shutdown" }) + "\n",
      "utf-8"
    );

    await new Promise((resolve) => {
      const timer = setTimeout(() => {
        if (proc && !proc.killed) proc.kill();
        resolve();
      }, SHUTDOWN_TIMEOUT_MS);

      proc.on("close", () => {
        clearTimeout(timer);
        resolve();
      });
    });
  } catch {
    if (proc && !proc.killed) proc.kill();
  }

  proc = null;
  rl = null;
  state = "idle";
  pending.clear();
  retryAttempted = false;
};

/**
 * الحصول على حالة البريدج الحالية
 */
export const getState = () => state;

import { execFile } from "node:child_process";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, dirname, join, resolve } from "node:path";
import process from "node:process";
import { fileURLToPath, pathToFileURL } from "node:url";
import { promisify } from "node:util";
import pino from "pino";
import { getPdfOcrAgentConfig } from "./pdf-ocr-agent-config.mjs";
import { stripOcrArtifactLines } from "./ocr-text-cleanup.mjs";
import {
  buildPdfReference,
  probePdftoppmDependency,
  renderPdfPages,
} from "./pdf-reference-builder.mjs";
import { runVisionProofread } from "./pdf-vision-proofread.mjs";
import { enforceTokenMatch } from "./token-enforcement.mjs";
import { writeMismatchReport } from "./mismatch-reporter.mjs";
import { saveProofreadDocx } from "./proofread-docx-writer.mjs"; // Fixed corrupted import name

const execFileAsync = promisify(execFile);
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const toFileUrl = (filePath) => pathToFileURL(filePath).href;

const DEFAULT_MISTRAL_REQUEST_ADAPTER_PATH = resolve(
  __dirname,
  "mistral-ocr-request-adapter.mjs"
);

const logger = pino({
  name: "pdf-ocr-agent",
  level: process.env.PDF_OCR_AGENT_LOG_LEVEL || "info",
});

const MAX_STDIO_BUFFER = 64 * 1024 * 1024;
const CLASSIFY_TIMEOUT_MS = 30_000;
const WRITE_OUTPUT_TIMEOUT_MS = 60_000;
const PIPELINE_OPEN_AGENT_BOOT_TIMEOUT_MS = 10_000;
const MISMATCH_REPORTS_ROOT = resolve(
  __dirname,
  "..",
  "tmp",
  "mismatch-reports"
);
const CANONICAL_MISTRAL_OCR_MODEL = "mistral-ocr-latest";
const CANONICAL_MISTRAL_OCR_ENDPOINT = "https://api.mistral.ai/v1/ocr";
const CANONICAL_VISION_COMPARE_MODEL = "mistral-large-latest";

// ─── دوال مساعدة عامة ─────────────────────────────────────────

const toChildProcessEnv = (overrideEnv = {}) => {
  const merged = { ...process.env, ...overrideEnv };
  const safeEnv = {};

  for (const [key, value] of Object.entries(merged)) {
    if (!key || key.includes("=") || typeof value === "undefined") {
      continue;
    }
    safeEnv[key] = String(value);
  }

  return safeEnv;
};

const toSafePdfFilename = (filename) => {
  const candidate = basename(filename || "document.pdf");
  if (candidate.toLowerCase().endsWith(".pdf")) return candidate;
  return `${candidate}.pdf`;
};

const getMockMode = () =>
  (process.env.PDF_OCR_AGENT_MOCK_MODE || "").trim().toLowerCase();

const buildMockSuccessResult = () => {
  const text =
    process.env.PDF_OCR_AGENT_MOCK_TEXT?.trim() ||
    "هذا نص OCR تجريبي من وضع المحاكاة.";
  const forcedReject = /^(1|true|yes|on)$/iu.test(
    (process.env.PDF_OCR_AGENT_MOCK_FORCE_REJECT || "").trim()
  );

  return {
    text,
    textRaw: text,
    textMarkdown: text,
    method: "ocr-mistral",
    usedOcr: true,
    attempts: [
      "pdf-ocr-agent",
      "classify",
      "ocr-mistral",
      "write-output",
      "mock-success",
    ],
    warnings: [],
    qualityScore: forcedReject ? 0.2 : 1,
    quality: {
      wordMatch: forcedReject ? 92 : 100,
      structuralMatch: forcedReject ? 95 : 100,
      accepted: !forcedReject,
    },
    mismatchReport: forcedReject
      ? [
          {
            page: 1,
            line: 1,
            token: "مشهد1",
            expected: "مشهد1",
            actual: "مسـاهد 1",
            severity: "critical",
          },
        ]
      : [],
    status: forcedReject ? "rejected" : "accepted",
    rejectionReason: forcedReject
      ? "mock rejection requested by PDF_OCR_AGENT_MOCK_FORCE_REJECT."
      : undefined,
    referenceMode: "pdf-vision",
    payloadVersion: 2,
    classification: null,
    rawExtractedText: text,
  };
};

const collectStderrWarnings = (stderr) => {
  if (typeof stderr !== "string" || !stderr.trim()) return [];
  return stderr
    .split(/\r?\n/u)
    .map((line) => line.trim())
    .filter(Boolean);
};

const buildTsxNodeArgs = (scriptPath, scriptArgs = [], extraImports = []) => {
  const nodeArgs = [];

  for (const importTarget of extraImports) {
    if (typeof importTarget === "string" && importTarget.trim()) {
      nodeArgs.push("--import", importTarget.trim());
    }
  }

  nodeArgs.push("--import", "tsx", scriptPath, ...scriptArgs);
  return nodeArgs;
};

const parseJsonObject = (raw, label) => {
  const rawText = typeof raw === "string" ? raw.trim() : "";
  if (!rawText) {
    throw new Error(`${label} returned empty output.`);
  }

  const tryParse = (candidate) => {
    try {
      return JSON.parse(candidate);
    } catch {
      return null;
    }
  };

  let parsed = tryParse(rawText);
  if (!parsed) {
    const lines = rawText
      .split(/\r?\n/u)
      .map((line) => line.trim())
      .filter(Boolean);

    for (let index = lines.length - 1; index >= 0; index -= 1) {
      const line = lines[index];
      if (!line.startsWith("{") || !line.endsWith("}")) {
        continue;
      }
      parsed = tryParse(line);
      if (parsed) {
        break;
      }
    }
  }

  if (!parsed) {
    const firstBraceIndex = rawText.indexOf("{");
    const lastBraceIndex = rawText.lastIndexOf("}");
    if (
      firstBraceIndex >= 0 &&
      lastBraceIndex > firstBraceIndex &&
      lastBraceIndex <= rawText.length - 1
    ) {
      parsed = tryParse(rawText.slice(firstBraceIndex, lastBraceIndex + 1));
    }
  }

  if (!parsed) {
    throw new Error(`${label} returned invalid JSON: unable to parse output.`);
  }

  if (typeof parsed !== "object") {
    throw new Error(`${label} returned malformed payload.`);
  }

  return parsed;
};

const readFileIfExists = async (filePath) => {
  try {
    return await readFile(filePath, "utf-8");
  } catch {
    return "";
  }
};

const runOpenPdfAgentScript = async (
  config,
  inputPath,
  ocrJsonPath,
  outputTxtPath,
  outputMcpMdPath
) => {
  logger.info(
    {
      script: config.openPdfAgentScriptPath,
      file: inputPath,
      pages: config.pages,
    },
    "open-agent-start"
  );

  const args = buildTsxNodeArgs(config.openPdfAgentScriptPath, [
    "--input",
    inputPath,
    "--output-json",
    ocrJsonPath,
    "--output-txt",
    outputTxtPath,
    "--output-mcp-md",
    outputMcpMdPath,
    "--pages",
    config.pages || "all",
  ]);

  const { stdout, stderr } = await execFileAsync(process.execPath, args, {
    timeout: config.timeoutMs + PIPELINE_OPEN_AGENT_BOOT_TIMEOUT_MS,
    maxBuffer: MAX_STDIO_BUFFER,
    env: toChildProcessEnv({
      MISTRAL_API_KEY: config.mistralApiKey,
      MISTRAL_OCR_MODEL: CANONICAL_MISTRAL_OCR_MODEL,
      MISTRAL_OCR_ENDPOINT: CANONICAL_MISTRAL_OCR_ENDPOINT,
      MOONSHOT_API_KEY: config.moonshotApiKey,
      PDF_VISION_COMPARE_MODEL: CANONICAL_VISION_COMPARE_MODEL,
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ?? "",
      OPEN_PDF_AGENT_VERIFY_FOOTPRINT: String(config.openAgentVerifyFootprint),
      OPEN_PDF_AGENT_ENABLE_MCP_STAGE: String(config.openAgentEnableMcpStage),
    }),
  });

  if (stderr?.trim()) {
    logger.debug({ stderr: stderr.trim() }, "open-agent-stderr");
  }

  const payload = parseJsonObject(stdout.trim(), "open-pdf-agent");
  if (payload.success === false) {
    const reason =
      typeof payload.error === "string" ? payload.error : "Unknown agent error";
    throw new Error(`open-pdf-agent failed: ${reason}`);
  }

  logger.info(
    {
      classificationType:
        typeof payload?.classification?.type === "string"
          ? payload.classification.type
          : "unknown",
      mcpSummaryPreview:
        typeof payload?.meta?.mcp?.summary === "string"
          ? payload.meta.mcp.summary.slice(0, 120)
          : null,
    },
    "open-agent-complete"
  );

  return payload;
};

// ─── خطوة 1: تصنيف PDF (classify-pdf.ts) ──────────────────────

const _runClassifyScript = async (config, pdfPath) => {
  logger.info(
    { script: config.classifyScriptPath, file: pdfPath },
    "classify-start"
  );

  try {
    const { stdout, stderr } = await execFileAsync(
      process.execPath,
      buildTsxNodeArgs(config.classifyScriptPath, [pdfPath]),
      {
        timeout: CLASSIFY_TIMEOUT_MS,
        maxBuffer: MAX_STDIO_BUFFER,
        env: toChildProcessEnv({
          MISTRAL_API_KEY: config.mistralApiKey,
        }),
      }
    );

    if (stderr?.trim()) {
      logger.debug({ stderr: stderr.trim() }, "classify-stderr");
    }

    const result = JSON.parse(stdout.trim());
    logger.info(
      {
        type: result.type,
        pages: result.pages,
        engine: result.recommended_engine,
      },
      "classify-complete"
    );
    return result;
  } catch (error) {
    logger.warn(
      { error: error instanceof Error ? error.message : String(error) },
      "classify-failed"
    );
    return {
      type: "scanned",
      pages: 0,
      size_mb: 0,
      filename: basename(pdfPath),
      has_arabic: true,
      recommended_engine: "mistral",
      notes: ["التصنيف فشل — يُفترض أن الملف ممسوح ضوئياً"],
    };
  }
};

// ─── خطوة 2: استخراج OCR (ocr-mistral.ts) ─────────────────────

const buildOcrArguments = (config, inputPath, outputPath) => {
  const adapterPath =
    process.env.PDF_OCR_MISTRAL_REQUEST_ADAPTER_PATH?.trim() ||
    DEFAULT_MISTRAL_REQUEST_ADAPTER_PATH;

  const args = [
    ...buildTsxNodeArgs(config.ocrScriptPath, [], [toFileUrl(adapterPath)]),
    "--input",
    inputPath,
    "--output",
    outputPath,
  ];

  if (config.pages && config.pages !== "all") {
    args.push("--pages", config.pages);
  }

  return args;
};

const parseOcrPayload = (raw) => {
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (error) {
    throw new Error(
      `PDF OCR agent produced invalid JSON output: ${
        error instanceof Error ? error.message : String(error)
      }`,
      { cause: error }
    );
  }

  if (!payload || typeof payload !== "object") {
    throw new Error("PDF OCR agent output is malformed.");
  }

  const pages = Array.isArray(payload.pages) ? payload.pages : [];
  const orderedPages = pages
    .filter(
      (page) =>
        page &&
        typeof page === "object" &&
        typeof page.markdown === "string" &&
        typeof page.index === "number"
    )
    .sort((a, b) => a.index - b.index);

  const text = orderedPages
    .map((page) => page.markdown.trim())
    .filter(Boolean)
    .join("\n\n");

  if (!text.trim()) {
    throw new Error("PDF OCR agent completed but returned empty text.");
  }

  return {
    text,
    pages: orderedPages.length,
    model: typeof payload.model === "string" ? payload.model : "unknown",
  };
};

const _runOcrScript = async (config, inputPath, outputJsonPath) => {
  logger.info({ script: config.ocrScriptPath, file: inputPath }, "ocr-start");

  const args = buildOcrArguments(config, inputPath, outputJsonPath);

  const { stderr } = await execFileAsync(process.execPath, args, {
    timeout: config.timeoutMs,
    maxBuffer: MAX_STDIO_BUFFER,
    env: toChildProcessEnv({
      MISTRAL_API_KEY: config.mistralApiKey,
      MISTRAL_OCR_MODEL: CANONICAL_MISTRAL_OCR_MODEL,
      MISTRAL_OCR_ENDPOINT: CANONICAL_MISTRAL_OCR_ENDPOINT,
      PDF_VISION_COMPARE_MODEL: CANONICAL_VISION_COMPARE_MODEL,
    }),
  });

  const outputRaw = await readFile(outputJsonPath, "utf-8");
  const parsed = parseOcrPayload(outputRaw);
  const warnings = collectStderrWarnings(stderr);

  logger.info({ pages: parsed.pages, model: parsed.model }, "ocr-complete");

  return { ...parsed, warnings };
};

// ─── خطوة 3: تنسيق المخرجات (write-output.ts) ────────────────

const _runWriteOutputScript = async (
  config,
  ocrJsonPath,
  format,
  outputPath
) => {
  logger.info(
    { script: config.writeOutputScriptPath, format, output: outputPath },
    "write-output-start"
  );

  try {
    const { stderr } = await execFileAsync(
      process.execPath,
      buildTsxNodeArgs(config.writeOutputScriptPath, [
        "--input",
        ocrJsonPath,
        "--format",
        format,
        "--output",
        outputPath,
      ]),
      {
        timeout: WRITE_OUTPUT_TIMEOUT_MS,
        maxBuffer: MAX_STDIO_BUFFER,
        env: toChildProcessEnv(),
      }
    );

    if (stderr?.trim()) {
      logger.debug({ stderr: stderr.trim() }, "write-output-stderr");
    }

    const formattedText = await readFile(outputPath, "utf-8");
    logger.info(
      { sizeKb: Math.round(Buffer.byteLength(formattedText, "utf-8") / 1024) },
      "write-output-complete"
    );
    return formattedText;
  } catch (error) {
    logger.warn(
      { error: error instanceof Error ? error.message : String(error) },
      "write-output-failed"
    );
    return null;
  }
};

const buildCriticalTokenList = (text) => {
  const seed = ["مشهد1", "مشهد2", "قطع", "داخلي", "خارجي", "نهار", "ليل"];

  const dynamic = String(text ?? "")
    .match(/\b(?:مشهد[0-9٠-٩]+|[0-9٠-٩]+)\b/gu)
    ?.map((token) => token.trim());

  return Array.from(new Set([...seed, ...(dynamic ?? [])])).filter(Boolean);
};

const buildRunFileKey = (filename) => {
  const base = basename(filename || "document.pdf")
    .replace(/[^a-zA-Z0-9._-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80);
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const random = Math.random().toString(36).slice(2, 8);
  return `${base || "document.pdf"}-${stamp}-${random}`;
};

// ─── الأوركسترا الرئيسية ──────────────────────────────────────

export const runPdfOcrAgent = async ({ buffer, filename }) => {
  const config = getPdfOcrAgentConfig();
  if (!config.enabled) {
    throw new Error("PDF OCR agent is disabled by configuration.");
  }

  const mockMode = getMockMode();
  if (mockMode === "success") {
    return buildMockSuccessResult();
  }
  if (mockMode === "failure") {
    throw new Error("PDF OCR agent mocked failure.");
  }

  // Pre-flight: ensure pdftoppm is available before starting the pipeline
  const pdftoppmProbe = await probePdftoppmDependency();
  if (!pdftoppmProbe.available) {
    throw new Error(
      `[${pdftoppmProbe.errorCode}] ${pdftoppmProbe.errorMessage}`
    );
  }

  const tempRoot = await mkdtemp(join(tmpdir(), "mo7rer-pdf-ocr-"));
  const inputPath = join(tempRoot, toSafePdfFilename(filename));
  const ocrJsonPath = join(tempRoot, "ocr-result.json");
  const formattedTxtPath = join(tempRoot, "output.txt");
  const mcpNormalizedOutputPath = join(tempRoot, "mcp-normalized.md");

  const startedAt = Date.now();
  const attempts = ["pdf-ocr-agent"];
  const allWarnings = [];

  logger.info(
    {
      file: filename,
      timeoutMs: config.timeoutMs,
      pages: config.pages,
      enableClassification: config.enableClassification,
      enableEnhancement: config.enableEnhancement,
      enableVisionProofread: config.enableVisionProofread,
      visionProofreadModel: config.visionProofreadModel,
      visionCompareModel: config.visionCompareModel,
      visionJudgeModel: config.visionJudgeModel,
    },
    "pipeline-start"
  );

  try {
    await writeFile(inputPath, buffer);

    // Vision preflight removed — saves ~48s of redundant API calls.
    // The models are verified implicitly when buildPdfReference runs.

    // ── المسار الأساسي: وكيل فتح PDF (مهارة + MCP) ──────────
    let classification = null;
    let pipelineFootprint = null;
    let finalText = "";
    let finalMarkdownText = "";
    let pipelinePages = 0;
    const pipelineModel = CANONICAL_MISTRAL_OCR_MODEL;

    attempts.push("pipeline-open-agent");
    const openAgentPayload = await runOpenPdfAgentScript(
      config,
      inputPath,
      ocrJsonPath,
      formattedTxtPath,
      mcpNormalizedOutputPath
    );

    classification =
      openAgentPayload?.classification &&
      typeof openAgentPayload.classification === "object"
        ? openAgentPayload.classification
        : null;
    pipelinePages =
      typeof classification?.pages === "number"
        ? Number(classification.pages)
        : 0;

    finalText =
      typeof openAgentPayload?.text === "string" ? openAgentPayload.text : "";
    finalMarkdownText =
      typeof openAgentPayload?.textMarkdown === "string"
        ? openAgentPayload.textMarkdown
        : "";
    if (!finalText.trim()) {
      throw new Error("open-pdf-agent returned empty raw text.");
    }

    if (Array.isArray(openAgentPayload?.attempts)) {
      attempts.push(
        ...openAgentPayload.attempts.filter(
          (entry) => typeof entry === "string" && entry.trim()
        )
      );
    }

    if (Array.isArray(openAgentPayload?.warnings)) {
      allWarnings.push(
        ...openAgentPayload.warnings.filter(
          (entry) => typeof entry === "string" && entry.trim()
        )
      );
    }

    const checkedDirectories = Array.isArray(
      openAgentPayload?.meta?.footprint?.checkedDirectories
    )
      ? openAgentPayload.meta.footprint.checkedDirectories.filter(
          (entry) => typeof entry === "string" && entry.trim()
        )
      : [];
    const checkedFiles = Array.isArray(
      openAgentPayload?.meta?.footprint?.checkedFiles
    )
      ? openAgentPayload.meta.footprint.checkedFiles.filter(
          (entry) => typeof entry === "string" && entry.trim()
        )
      : [];

    if (checkedDirectories.length > 0 || checkedFiles.length > 0) {
      pipelineFootprint = {
        checkedDirectories,
        checkedFiles,
      };
    }

    if (classification?.type === "protected") {
      throw new Error("الملف محمي بكلمة مرور — يتطلب فك التشفير أولاً.");
    }
    if (classification?.notes?.length) {
      allWarnings.push(...classification.notes);
    }

    const rawExtractedText = finalText;
    let artifactLinesRemoved = 0;
    const normalizationApplied = [];
    const cleaned = stripOcrArtifactLines(finalText);
    finalText = cleaned.text;
    artifactLinesRemoved = cleaned.removedLines;
    if (artifactLinesRemoved > 0) {
      normalizationApplied.push("strip-ocr-artifact-lines");
      allWarnings.push(`تم حذف ${artifactLinesRemoved} سطرًا مصطنعًا من OCR`);
      logger.info({ artifactLinesRemoved }, "ocr-artifacts-stripped");
    }

    if (!finalMarkdownText.trim()) {
      const markdownFromFile = await readFileIfExists(mcpNormalizedOutputPath);
      if (markdownFromFile.trim()) {
        finalMarkdownText = markdownFromFile;
      } else {
        finalMarkdownText = finalText;
      }
    }

    // ── Gemini Vision Proofread (post-correction) ─────────────
    // Enabled by default (PDF_OCR_ENABLE_VISION_PROOFREAD=true).
    // Renders each page to an image, sends image + OCR text to
    // Gemini 2.5 Flash, and gets back corrected text.
    if (config.enableVisionProofread && config.geminiApiKey) {
      attempts.push("vision-proofread");
      logger.info(
        {
          model: config.visionProofreadModel,
          renderDpi: config.visionRenderDpi,
        },
        "vision-proofread-start"
      );
      const tProofread = Date.now();

      try {
        // Render PDF pages to PNG images
        const proofreadPageImages = await renderPdfPages({
          pdfPath: inputPath,
          dpi: config.visionRenderDpi,
        });

        // Build ocrPages from the OCR JSON
        const ocrJsonRaw = await readFile(ocrJsonPath, "utf-8");
        const ocrPayload = JSON.parse(ocrJsonRaw);
        const ocrPagesForProofread = Array.isArray(ocrPayload?.pages)
          ? ocrPayload.pages
              .filter(
                (p) =>
                  p &&
                  typeof p === "object" &&
                  typeof p.index === "number" &&
                  typeof p.markdown === "string"
              )
              .sort((a, b) => a.index - b.index)
              .map((p) => ({ index: p.index, text: p.markdown.trim() }))
          : [];

        if (
          ocrPagesForProofread.length === 0 ||
          proofreadPageImages.length === 0
        ) {
          throw new Error(
            `vision-proofread missing source data [VISION_PROOFREAD_NO_DATA]: ocrPages=${ocrPagesForProofread.length}, renderedImages=${proofreadPageImages.length}`
          );
        }

        const proofreadResult = await runVisionProofread({
          apiKey: config.geminiApiKey,
          model: config.visionProofreadModel,
          pageImages: proofreadPageImages,
          ocrPages: ocrPagesForProofread,
          timeoutMs: config.visionProofreadTimeoutMs,
        });

        const proofreadText = proofreadResult.pages
          .sort((a, b) => a.page - b.page)
          .map((p) => p.text.trim())
          .filter(Boolean)
          .join("\n\n");

        if (!proofreadText.trim()) {
          throw new Error(
            "vision-proofread returned empty text [VISION_PROOFREAD_EMPTY_RESULT]"
          );
        }

        const originalLen = finalText.length;
        finalText = proofreadText;
        finalMarkdownText = proofreadText;
        normalizationApplied.push("vision-proofread-gemini");
        logger.info(
          {
            durationMs: Date.now() - tProofread,
            originalLen,
            correctedLen: proofreadText.length,
            pages: proofreadResult.pages.length,
          },
          "vision-proofread-complete"
        );
      } catch (proofreadError) {
        const message =
          proofreadError instanceof Error
            ? proofreadError.message
            : String(proofreadError);
        logger.error(
          {
            error: message,
            durationMs: Date.now() - tProofread,
          },
          "vision-proofread-failed"
        );
        throw new Error(`vision-proofread failed: ${message}`, {
          cause: proofreadError,
        });
      }
    } else if (!config.enableVisionProofread) {
      attempts.push("vision-proofread-disabled");
      logger.info(
        "vision-proofread-disabled (PDF_OCR_ENABLE_VISION_PROOFREAD is not set)"
      );
    } else {
      attempts.push("vision-proofread-no-key");
      logger.warn("vision-proofread-skipped (GEMINI_API_KEY missing)");
    }

    // ── حفظ نسخ DOCX من النص المُراجع (للتجربة) ───────────
    // يُولّد نسختين: خام (raw) + مُنسّق (formatted)
    // الملفات تُحفظ في server/proofread-output/
    try {
      const docxResult = await saveProofreadDocx(
        // Fixed corrupted function call
        finalText,
        filename
      );
      if (docxResult.rawPath) {
        attempts.push("docx-export");
        logger.info(
          {
            rawPath: docxResult.rawPath,
            formattedPath: docxResult.formattedPath,
          },
          "proofread-docx-exported"
        );
      }
    } catch (docxError) {
      // غير حرجة — لو فشلت الكتابة نكمل عادي
      logger.warn(
        {
          error:
            docxError instanceof Error ? docxError.message : String(docxError),
        },
        "proofread-docx-export-failed"
      );
    }

    // ── Vision reference (compare + judge + enforcement) ─────
    // Disabled by default — Mistral OCR output is used directly.
    // Set PDF_OCR_ENABLE_VISION_QA=true to enable the full
    // vision-compare → kimi-judge → token-enforcement pipeline.
    const enableVisionQA = /^(1|true|yes|on)$/iu.test(
      (process.env.PDF_OCR_ENABLE_VISION_QA || "").trim()
    );

    let status = "accepted";
    let rejectionReason = undefined;
    let mismatchReport = [];
    let quality = { wordMatch: 100, structuralMatch: 100, accepted: true };
    let referenceMode = "ocr-direct";
    let mismatchReportPath = "";

    if (enableVisionQA) {
      attempts.push("vision-reference-build");
      logger.info(
        {
          compareModel: config.visionCompareModel,
          judgeModel: config.visionJudgeModel,
          renderDpi: config.visionRenderDpi,
        },
        "vision-reference-build-start"
      );
      const reference = await buildPdfReference({
        pdfPath: inputPath,
        ocrJsonPath,
        externalReferencePath: config.externalReferencePath || undefined,
        compare: {
          apiKey: config.mistralApiKey,
          model: config.visionCompareModel,
          timeoutMs: config.visionCompareTimeoutMs,
        },
        judge: {
          apiKey: config.moonshotApiKey,
          model: config.visionJudgeModel,
          timeoutMs: config.visionJudgeTimeoutMs,
        },
        renderDpi: config.visionRenderDpi,
        visionPreflightDone: true,
      });
      logger.info(
        {
          referenceMode: reference.referenceMode,
          renderedPages: Number(reference?.compareReport?.renderedPages ?? 0),
          proposedPatches: Number(
            reference?.compareReport?.proposedPatches ?? 0
          ),
          approvedPatches: Number(
            reference?.compareReport?.approvedPatches ?? 0
          ),
          rejectedPatches: Number(
            reference?.compareReport?.rejectedPatches ?? 0
          ),
        },
        "vision-reference-build-complete"
      );

      attempts.push("token-enforcement");
      const enforcement = enforceTokenMatch({
        candidateText: finalText,
        referenceText: reference.referenceText,
        pageLineBoundaries: reference.pageLineBoundaries,
        criticalTokens: buildCriticalTokenList(reference.referenceText),
        minWordMatch: 99.5,
      });
      logger.info(
        {
          status: enforcement.status,
          wordMatch: enforcement?.quality?.wordMatch,
          structuralMatch: enforcement?.quality?.structuralMatch,
        },
        "token-enforcement-complete"
      );

      status = enforcement.status;
      rejectionReason = enforcement.rejectionReason;
      mismatchReport = enforcement.mismatchReport;
      quality = enforcement.quality;
      referenceMode = reference.referenceMode;

      if (status === "rejected" && rejectionReason) {
        allWarnings.push(`extraction-rejected: ${rejectionReason}`);
      }

      mismatchReportPath = join(
        MISMATCH_REPORTS_ROOT,
        `${buildRunFileKey(filename)}.json`
      );
      await writeMismatchReport(mismatchReportPath, {
        payloadVersion: 2,
        status,
        referenceMode,
        quality,
        mismatchReport,
        rejectionReason,
        attempts,
      });
    } else {
      attempts.push("vision-qa-skipped");
      logger.info("vision-qa-skipped (PDF_OCR_ENABLE_VISION_QA is not set)");
    }

    // ── بناء النتيجة النهائية ────────────────────────────────
    const durationMs = Date.now() - startedAt;
    const uniqueAttempts = Array.from(
      new Set(attempts.filter((entry) => typeof entry === "string" && entry))
    );

    logger.info(
      {
        file: filename,
        pages: pipelinePages,
        model: pipelineModel,
        classificationType: classification?.type ?? "skipped",
        artifactLinesRemoved,
        status,
        referenceMode,
        durationMs,
      },
      "pipeline-complete"
    );

    return {
      text: finalText,
      textRaw: finalText,
      textMarkdown: finalMarkdownText,
      method: "ocr-mistral",
      usedOcr: true,
      attempts: uniqueAttempts,
      warnings: allWarnings,
      qualityScore: Number((quality.wordMatch / 100).toFixed(4)),
      quality,
      mismatchReport,
      status,
      rejectionReason,
      referenceMode,
      payloadVersion: 2,
      classification,
      rawExtractedText,
      pipelineFootprint,
      artifactLinesRemoved,
      normalizationApplied,
      mismatchReportPath,
    };
  } catch (error) {
    const durationMs = Date.now() - startedAt;
    logger.error(
      {
        file: filename,
        durationMs,
        attempts,
        error: error instanceof Error ? error.message : String(error),
      },
      "pipeline-failed"
    );
    throw new Error(
      `PDF OCR agent failed: ${
        error instanceof Error ? error.message : String(error)
      }`,
      { cause: error }
    );
  } finally {
    await rm(tempRoot, { recursive: true, force: true }).catch(() => undefined);
  }
};

import { execFile } from "node:child_process";
import { mkdtemp, readdir, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import process from "node:process";
import { basename, join, resolve } from "node:path";
import { promisify } from "node:util";
import { runVisionCompare } from "./pdf-vision-compare.mjs";
import { runVisionJudge } from "./pdf-vision-judge.mjs";

const log = (tag, data) => {
  const ts = new Date().toISOString();
  console.warn(
    `[${ts}] [pdf-ref] ${tag}`,
    data != null ? JSON.stringify(data) : ""
  );
};

const execFileAsync = promisify(execFile);
const PDFTOPPM_BINARY =
  process.platform === "win32" ? "pdftoppm.exe" : "pdftoppm";
const PDFTOPPM_CHECK_TIMEOUT_MS = 10_000;
const PDFTOPPM_CHECK_BUFFER = 8 * 1024 * 1024;

const toErrorMessage = (error) =>
  error instanceof Error ? error.message : String(error ?? "unknown error");

const hasPdftoppmHint = (value) =>
  typeof value === "string" && /pdftoppm|poppler/iu.test(value);

const buildMissingRendererMessage = (command) =>
  `PDF vision misconfigured: pdftoppm is required to render page images (command: ${command}).`;

const buildUnusableRendererMessage = (command, reason) =>
  `PDF vision misconfigured: pdftoppm command is not usable (command: ${command}). ${reason}`;

export const resolvePdftoppmCommand = () => {
  const popplerBin = process.env.POPPLER_BIN?.trim();
  if (popplerBin) {
    return join(popplerBin, PDFTOPPM_BINARY);
  }
  return PDFTOPPM_BINARY;
};

export const probePdftoppmDependency = async () => {
  const command = resolvePdftoppmCommand();

  try {
    await execFileAsync(command, ["-v"], {
      timeout: PDFTOPPM_CHECK_TIMEOUT_MS,
      maxBuffer: PDFTOPPM_CHECK_BUFFER,
    });

    return {
      available: true,
      command,
    };
  } catch (error) {
    // On some platforms `pdftoppm -v` may return non-zero despite command availability.
    if (
      typeof error?.code === "number" &&
      (hasPdftoppmHint(error?.stdout) || hasPdftoppmHint(error?.stderr))
    ) {
      return {
        available: true,
        command,
      };
    }

    const spawnCode = typeof error?.code === "string" ? error.code : "";
    if (spawnCode === "ENOENT") {
      return {
        available: false,
        command,
        errorCode: "PDF_OCR_PDF_RENDERER_MISSING",
        errorMessage: buildMissingRendererMessage(command),
      };
    }

    return {
      available: false,
      command,
      errorCode: "PDF_OCR_PDF_RENDERER_UNUSABLE",
      errorMessage: buildUnusableRendererMessage(
        command,
        toErrorMessage(error)
      ),
    };
  }
};

const tokenize = (line) => {
  const tokens = String(line ?? "").match(/[\p{L}\p{N}_]+|[^\s]/gu);
  return Array.isArray(tokens) ? tokens : [];
};

const normalizeText = (text) =>
  String(text ?? "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n");

const parseOcrPages = (raw) => {
  const payload = JSON.parse(String(raw ?? "{}"));
  const pages = Array.isArray(payload?.pages) ? payload.pages : [];
  return pages
    .filter(
      (page) =>
        page &&
        typeof page === "object" &&
        typeof page.index === "number" &&
        typeof page.markdown === "string"
    )
    .sort((a, b) => a.index - b.index)
    .map((page) => ({
      index: Number(page.index),
      text: String(page.markdown).trim(),
    }));
};

const ensurePdftoppmAvailable = async () => {
  const probe = await probePdftoppmDependency();
  if (!probe.available) {
    throw new Error(`[${probe.errorCode}] ${probe.errorMessage}`);
  }
  return probe.command;
};

const sortPngPages = (files, prefixBaseName) =>
  files
    .filter(
      (name) =>
        name.startsWith(prefixBaseName) &&
        name.toLowerCase().endsWith(".png") &&
        /-\d+\.png$/u.test(name)
    )
    .sort((a, b) => {
      const ai = Number(a.match(/-(\d+)\.png$/u)?.[1] ?? "0");
      const bi = Number(b.match(/-(\d+)\.png$/u)?.[1] ?? "0");
      return ai - bi;
    });

export const renderPdfPages = async ({ pdfPath, dpi }) => {
  log("render-start", { pdfPath, dpi });
  const t0 = Date.now();
  const pdftoppmCommand = await ensurePdftoppmAvailable();
  const renderRoot = await mkdtemp(join(tmpdir(), "mo7rer-pdf-vision-"));
  const prefix = join(renderRoot, "page");

  await execFileAsync(
    pdftoppmCommand,
    ["-png", "-r", String(dpi), resolve(pdfPath), prefix],
    { timeout: 180_000, maxBuffer: 16 * 1024 * 1024 }
  );

  const files = await readdir(renderRoot);
  const sorted = sortPngPages(files, basename(prefix));
  if (sorted.length === 0) {
    throw new Error(
      "[PDF_OCR_PDF_RENDERER_EMPTY_OUTPUT] PDF vision renderer produced no page images."
    );
  }

  log("render-done", { pages: sorted.length, ms: Date.now() - t0 });
  return sorted.map((name) => join(renderRoot, name));
};

const _renderFirstPdfPage = async ({ pdfPath, dpi }) => {
  const pdftoppmCommand = await ensurePdftoppmAvailable();
  const renderRoot = await mkdtemp(join(tmpdir(), "mo7rer-pdf-vision-probe-"));
  const prefix = join(renderRoot, "probe");

  await execFileAsync(
    pdftoppmCommand,
    [
      "-png",
      "-singlefile",
      "-f",
      "1",
      "-l",
      "1",
      "-r",
      String(dpi),
      resolve(pdfPath),
      prefix,
    ],
    { timeout: 60_000, maxBuffer: 16 * 1024 * 1024 }
  );

  const files = await readdir(renderRoot);
  const firstPng = files.find((name) => name.toLowerCase().endsWith(".png"));
  if (!firstPng) {
    throw new Error(
      "[PDF_OCR_VISION_PREFLIGHT_RENDER_FAILED] Vision preflight failed: unable to render first page image."
    );
  }

  return {
    renderRoot,
    imagePath: join(renderRoot, firstPng),
  };
};

const applyPatchToPageText = (pageText, patch) => {
  const lines = normalizeText(pageText).split("\n");
  const lineIndex = Math.max(0, Number(patch.line) - 1);
  const line = lines[lineIndex] ?? "";
  const tokens = tokenize(line);
  const tokenIndex = Math.max(0, Number(patch.tokenIndex));

  if (patch.operation === "replace") {
    tokens[tokenIndex] = String(patch.expected ?? "");
  } else if (patch.operation === "insert") {
    tokens.splice(tokenIndex, 0, String(patch.expected ?? ""));
  } else if (patch.operation === "delete") {
    if (tokenIndex < tokens.length) {
      tokens.splice(tokenIndex, 1);
    }
  }

  lines[lineIndex] = tokens.join(" ").trim();
  return lines.join("\n");
};

const buildPageLineBoundaries = (pages) => {
  const boundaries = [];
  let acc = 0;
  for (const page of pages) {
    const count = normalizeText(page.text).split("\n").length;
    acc += count;
    boundaries.push(acc);
  }
  return boundaries;
};

// verifyVisionModelCapabilities removed — preflight is no longer needed.
// Models are verified implicitly during the actual compare/judge runs.

export const buildPdfReference = async ({
  pdfPath,
  ocrJsonPath,
  externalReferencePath,
  compare,
  judge,
  renderDpi = 300,
  visionPreflightDone: _visionPreflightDone = false,
}) => {
  if (externalReferencePath) {
    const referenceText = await readFile(
      resolve(externalReferencePath),
      "utf-8"
    );
    return {
      referenceMode: "external",
      referenceText,
      pageLineBoundaries: [],
      compareReport: {
        renderedPages: 0,
        proposedPatches: 0,
        approvedPatches: 0,
        rejectedPatches: 0,
      },
    };
  }

  log("build-ref-start", { pdfPath, ocrJsonPath, renderDpi });
  const tTotal = Date.now();

  const ocrJsonRaw = await readFile(ocrJsonPath, "utf-8");
  const ocrPages = parseOcrPages(ocrJsonRaw);
  if (ocrPages.length === 0) {
    throw new Error(
      "Cannot build pdf-vision reference: OCR pages are missing."
    );
  }
  log("ocr-pages-parsed", { count: ocrPages.length });

  const pageImages = await renderPdfPages({ pdfPath, dpi: renderDpi });

  log("vision-compare-start", {
    pages: pageImages.length,
    model: compare.model,
  });
  const tCompare = Date.now();
  const compareResult = await runVisionCompare({
    apiKey: compare.apiKey,
    model: compare.model,
    pageImages,
    ocrPages,
    timeoutMs: compare.timeoutMs,
  });
  log("vision-compare-done", {
    patches: compareResult.proposedPatchCount,
    ms: Date.now() - tCompare,
  });

  log("vision-judge-start", {
    pages: compareResult.pages.length,
    model: judge.model,
  });
  const tJudge = Date.now();
  const judgeResult = await runVisionJudge({
    apiKey: judge.apiKey,
    model: judge.model,
    comparePages: compareResult.pages,
    timeoutMs: judge.timeoutMs,
    skipPreflight: true,
  });
  log("vision-judge-done", {
    approved: judgeResult.approvedPatches.length,
    rejected: judgeResult.rejectedPatches.length,
    ms: Date.now() - tJudge,
  });

  const patchedPages = compareResult.pages.map((item) => ({
    page: item.page,
    text: item.referencePageText,
  }));
  const pageByNumber = new Map(patchedPages.map((page) => [page.page, page]));

  for (const patch of judgeResult.approvedPatches) {
    const page = pageByNumber.get(Number(patch.page));
    if (!page) continue;
    page.text = applyPatchToPageText(page.text, patch);
  }

  const referenceText = patchedPages
    .sort((a, b) => a.page - b.page)
    .map((page) => page.text.trim())
    .filter(Boolean)
    .join("\n\n")
    .trim();

  log("build-ref-done", {
    totalMs: Date.now() - tTotal,
    renderedPages: pageImages.length,
    proposed: compareResult.proposedPatchCount,
    approved: judgeResult.approvedPatches.length,
    rejected: judgeResult.rejectedPatches.length,
  });

  return {
    referenceMode: "pdf-vision",
    referenceText,
    pageLineBoundaries: buildPageLineBoundaries(
      patchedPages.sort((a, b) => a.page - b.page)
    ),
    compareReport: {
      renderedPages: pageImages.length,
      proposedPatches: compareResult.proposedPatchCount,
      approvedPatches: judgeResult.approvedPatches.length,
      rejectedPatches: judgeResult.rejectedPatches.length,
    },
  };
};

import { readFile } from "node:fs/promises";
import { setTimeout as sleep } from "node:timers/promises";
import { resolveMoonshotChatRuntime } from "./provider-api-runtime.mjs";

const log = (tag, data) => {
  const ts = new Date().toISOString();
  console.warn(
    `[${ts}] [vision-judge] ${tag}`,
    data != null ? JSON.stringify(data) : ""
  );
};

const DEFAULT_TIMEOUT_MS = 180_000;
const DEFAULT_MAX_RETRIES = 2;
const DEFAULT_RETRY_BASE_MS = 500;
const DEFAULT_KIMI_THINKING_MODE = "disabled";
const JUDGE_CONCURRENCY = 3;
const MAX_PATCHES_PER_JUDGE_REQUEST = 150;

const toDataUrl = (buffer, mimeType) =>
  `data:${mimeType};base64,${buffer.toString("base64")}`;

const toErrorMessage = (error) =>
  error instanceof Error ? error.message : String(error ?? "unknown error");

const isRetryableStatus = (status) =>
  status === 408 || status === 425 || status === 429 || status >= 500;

const toOptionalTrimmedString = (value, maxLength = 256) => {
  if (typeof value !== "string") return "";
  return value.trim().slice(0, maxLength);
};

const isKimiK25Model = (model) => /^kimi-k2\.5(?:$|[-_])/iu.test(model.trim());

const resolveKimiJudgeRuntime = (model) => {
  const moonshotRuntime = resolveMoonshotChatRuntime(process.env);
  const parsedModel =
    toOptionalTrimmedString(model, 128) || String(model ?? "").trim();
  const isK2_5 = parsedModel ? isKimiK25Model(parsedModel) : false;
  const thinkingRaw = toOptionalTrimmedString(
    process.env.KIMI_THINKING_MODE,
    32
  ).toLowerCase();
  const thinkingType =
    thinkingRaw === "enabled" || thinkingRaw === "disabled"
      ? thinkingRaw
      : DEFAULT_KIMI_THINKING_MODE;

  return {
    baseUrl: moonshotRuntime.baseUrl,
    endpoint: moonshotRuntime.chatCompletionsEndpoint,
    model: parsedModel,
    isK2_5,
    thinkingType,
  };
};

const createTimeoutState = (timeoutMs) => {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return {
    signal: controller.signal,
    cleanup: () => clearTimeout(timer),
  };
};

const extractAssistantMessageText = (content) => {
  if (typeof content === "string") {
    return content.trim();
  }

  if (!Array.isArray(content)) {
    return "";
  }

  return content
    .map((part) => {
      if (typeof part === "string") return part.trim();
      if (
        part &&
        typeof part === "object" &&
        part.type === "text" &&
        typeof part.text === "string"
      ) {
        return part.text.trim();
      }
      return "";
    })
    .filter(Boolean)
    .join("\n")
    .trim();
};

const parseJsonObject = (raw, label) => {
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    return raw;
  }

  const text = String(raw ?? "").trim();
  if (!text) {
    throw new Error(`${label} returned empty response.`);
  }

  try {
    return JSON.parse(text);
  } catch {
    const first = text.indexOf("{");
    const last = text.lastIndexOf("}");
    if (first >= 0 && last > first) {
      return JSON.parse(text.slice(first, last + 1));
    }
    throw new Error(`${label} returned invalid JSON.`);
  }
};

const requestKimiJudge = async ({
  apiKey,
  model,
  imageDataUrl,
  currentText,
  patches,
  timeoutMs = DEFAULT_TIMEOUT_MS,
  maxRetries = DEFAULT_MAX_RETRIES,
  retryBaseDelayMs = DEFAULT_RETRY_BASE_MS,
  _pageLabel = "?",
}) => {
  const runtime = resolveKimiJudgeRuntime(model);
  const url = runtime.endpoint;
  let attempt = 0;
  let lastError;

  log("api-call-start", {
    page: _pageLabel,
    model: runtime.model,
    isK2_5: runtime.isK2_5,
    thinking: runtime.thinkingType,
    endpoint: url,
    patches: patches.length,
    timeoutMs,
  });
  const t0 = Date.now();

  const prompt = [
    "You are a strict OCR patch judge.",
    "Given page image + current OCR text + proposed patches, decide each patch.",
    "Return JSON only:",
    '{"decisions":[{"id":"string","approve":true,"confidence":0.0,"reason":"string"}]}',
    "Rules:",
    "1) Approve only if page image supports change.",
    "2) Reject speculative language rewrites.",
    "3) Keep structural markers precise.",
    "",
    "Current OCR page text:",
    currentText,
    "",
    "Proposed patches:",
    JSON.stringify(patches),
  ].join("\n");

  while (attempt <= maxRetries) {
    const timeoutState = createTimeoutState(timeoutMs);
    try {
      // codeql[js/file-access-to-http]
      const response = await fetch(url, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        // codeql[js/file-access-to-http]
        body: JSON.stringify({
          model: runtime.model,
          // kimi-k2.5: temperature/top_p/n/presence_penalty/frequency_penalty
          // are FIXED by the server and MUST NOT be sent (docs: "Any other value will result in an error").
          // max_tokens defaults to 32768 for k2.5; the general API deprecates it in favour of max_completion_tokens.
          // For non-k2.5 models we still set temperature=0 and response_format for deterministic JSON.
          ...(runtime.isK2_5
            ? {
                thinking: { type: runtime.thinkingType },
                // JSON Mode is supported for vision, but NOT when thinking is enabled
                // (thinking mode streams reasoning_content first).
                ...(runtime.thinkingType === "disabled"
                  ? { response_format: { type: "json_object" } }
                  : {}),
              }
            : {
                temperature: 0,
                response_format: { type: "json_object" },
              }),
          messages: [
            {
              role: "system",
              content: "Strict OCR patch judge. JSON only.",
            },
            {
              role: "user",
              content: [
                { type: "text", text: prompt },
                {
                  type: "image_url",
                  image_url: {
                    url: imageDataUrl,
                  },
                },
              ],
            },
          ],
        }),
        signal: timeoutState.signal,
      });

      const raw = await response.text();
      if (!response.ok) {
        const error = new Error(
          `kimi-judge failed: ${response.status} ${response.statusText} ${raw}`
        );
        if (isRetryableStatus(response.status) && attempt < maxRetries) {
          attempt += 1;
          await sleep(retryBaseDelayMs * 2 ** Math.max(0, attempt - 1));
          continue;
        }
        throw error;
      }

      const root = parseJsonObject(raw, "kimi-judge-http");
      const choices = Array.isArray(root?.choices) ? root.choices : [];
      const firstChoice = choices[0] ?? {};
      const content = extractAssistantMessageText(
        firstChoice?.message?.content
      );
      const parsed = parseJsonObject(content, "kimi-judge-content");
      const decisions = Array.isArray(parsed?.decisions)
        ? parsed.decisions
        : [];
      log("api-call-done", {
        page: _pageLabel,
        ms: Date.now() - t0,
        attempt,
        decisions: decisions.length,
      });
      return decisions;
    } catch (error) {
      lastError = error;
      if (attempt >= maxRetries) break;
      attempt += 1;
      await sleep(retryBaseDelayMs * 2 ** Math.max(0, attempt - 1));
    } finally {
      timeoutState.cleanup();
    }
  }

  log("api-call-failed", {
    page: _pageLabel,
    ms: Date.now() - t0,
    error: toErrorMessage(lastError),
  });
  throw new Error(
    `kimi-judge failed after retries: ${toErrorMessage(lastError)}`
  );
};

export const runVisionJudgePreflight = async ({
  apiKey,
  model,
  imagePath,
  timeoutMs = DEFAULT_TIMEOUT_MS,
}) => {
  if (typeof imagePath !== "string" || !imagePath.trim()) {
    throw new Error(
      "[PDF_OCR_VISION_JUDGE_PREFLIGHT_INVALID_INPUT] Vision judge preflight failed: first-page image path is required."
    );
  }

  try {
    const imageBuffer = await readFile(imagePath);
    const imageDataUrl = toDataUrl(imageBuffer, "image/png");
    await requestKimiJudge({
      apiKey,
      model,
      imageDataUrl,
      currentText: "preflight",
      patches: [{ id: "preflight", actual: "x", expected: "y" }],
      timeoutMs,
      maxRetries: 0,
    });
  } catch (error) {
    throw new Error(
      `[PDF_OCR_VISION_JUDGE_PREFLIGHT_FAILED] Vision judge preflight failed: ${
        error instanceof Error ? error.message : String(error)
      }`,
      { cause: error }
    );
  }
};

const processJudgePage = async ({ page, apiKey, model, timeoutMs }) => {
  const allPatches = Array.isArray(page.proposedPatches)
    ? page.proposedPatches
    : [];
  if (allPatches.length === 0) {
    log("page-skip", { page: page.page, reason: "no-patches" });
    return { approved: [], rejected: [] };
  }

  // Sort by confidence descending — send only the top N to Kimi to avoid
  // hanging on enormous payloads (1000+ patches would make the prompt huge).
  const sorted = [...allPatches].sort(
    (a, b) => (b.confidence ?? 0) - (a.confidence ?? 0)
  );
  const patchesToJudge = sorted.slice(0, MAX_PATCHES_PER_JUDGE_REQUEST);
  const autoRejected = sorted.slice(MAX_PATCHES_PER_JUDGE_REQUEST);

  log("page-start", {
    page: page.page,
    totalPatches: allPatches.length,
    sentToJudge: patchesToJudge.length,
    autoRejected: autoRejected.length,
  });
  const t0 = Date.now();

  const imageBuffer = await readFile(page.imagePath);
  const imageDataUrl = toDataUrl(imageBuffer, "image/png");
  const decisions = await requestKimiJudge({
    apiKey,
    model,
    imageDataUrl,
    currentText: String(page.currentPageText ?? ""),
    patches: patchesToJudge,
    timeoutMs,
    _pageLabel: page.page,
  });

  const decisionsById = new Map(
    decisions
      .filter((item) => item && typeof item.id === "string")
      .map((item) => [
        item.id,
        {
          approve: Boolean(item.approve),
          reason:
            typeof item.reason === "string" && item.reason.trim()
              ? item.reason.trim()
              : "no-reason",
          confidence:
            typeof item.confidence === "number" &&
            Number.isFinite(item.confidence)
              ? item.confidence
              : 0,
        },
      ])
  );

  const approved = [];
  const rejected = [];

  for (const patch of patchesToJudge) {
    const decision = decisionsById.get(patch.id);
    if (!decision) {
      rejected.push({
        ...patch,
        judgeReason: "missing-judge-decision",
        judgeConfidence: 0,
      });
      continue;
    }

    if (decision.approve) {
      approved.push({
        ...patch,
        judgeReason: decision.reason,
        judgeConfidence: decision.confidence,
      });
    } else {
      rejected.push({
        ...patch,
        judgeReason: decision.reason,
        judgeConfidence: decision.confidence,
      });
    }
  }

  // Overflow patches are auto-rejected (not judged) to avoid API hang.
  for (const patch of autoRejected) {
    rejected.push({
      ...patch,
      judgeReason: "overflow-auto-rejected",
      judgeConfidence: 0,
    });
  }

  log("page-done", {
    page: page.page,
    approved: approved.length,
    rejected: rejected.length,
    ms: Date.now() - t0,
  });
  return { approved, rejected };
};

const runParallelBatches = async (items, concurrency, fn) => {
  const results = [];
  for (let i = 0; i < items.length; i += concurrency) {
    const batch = items.slice(i, i + concurrency);
    const batchResults = await Promise.all(batch.map(fn));
    results.push(...batchResults);
  }
  return results;
};

export const runVisionJudge = async ({
  apiKey,
  model,
  comparePages,
  timeoutMs = DEFAULT_TIMEOUT_MS,
  skipPreflight: _skipPreflight = false,
}) => {
  if (!Array.isArray(comparePages) || comparePages.length === 0) {
    throw new Error("vision judge requires compare pages.");
  }

  // Preflight removed — skip always (called separately if needed)

  const pagesWithPatches = comparePages.filter(
    (page) =>
      Array.isArray(page.proposedPatches) && page.proposedPatches.length > 0
  );

  const pageResults = await runParallelBatches(
    pagesWithPatches,
    JUDGE_CONCURRENCY,
    (page) => processJudgePage({ page, apiKey, model, timeoutMs })
  );

  const approvedPatches = [];
  const rejectedPatches = [];
  for (const result of pageResults) {
    approvedPatches.push(...result.approved);
    rejectedPatches.push(...result.rejected);
  }

  return {
    approvedPatches,
    rejectedPatches,
  };
};

export const getVisionJudgeRuntime = ({ model }) =>
  resolveKimiJudgeRuntime(model);

/**
 * @module server/proofread-docx-writer
 * @description يُولّد نسختين من ملف DOCX بعد مرحلة vision-proofread:
 *
 *  1. **raw** — كل سطر في paragraph مستقل، بدون أي تنسيق
 *  2. **formatted** — عناوين مشاهد كـ Heading، أسماء شخصيات Bold،
 *     إرشادات أكشن بخط عادي، حوار بخط مائل
 *
 * الملفات تُحفظ في مجلد `server/proofread-output/` بتسمية:
 *   `{filename}-raw.docx`  و  `{filename}-formatted.docx`
 */

import {
  Document,
  Packer,
  Paragraph,
  TextRun,
  HeadingLevel,
  AlignmentType,
} from "docx";
import { writeFile, mkdir } from "node:fs/promises";
import { basename, join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// logger بسيط — بيستخدم pino لو موجود، وإلا console
let logger;
try {
  const pino = (await import("pino")).default;
  logger = pino({ name: "proofread-docx-writer", level: "info" });
} catch {
  logger = {
    info: (obj, msg) =>
      console.warn(
        `[proofread-docx] INFO: ${msg || ""}`,
        typeof obj === "string" ? obj : ""
      ),
    warn: (obj, msg) =>
      console.warn(
        `[proofread-docx] WARN: ${msg || ""}`,
        typeof obj === "string" ? obj : ""
      ),
    error: (obj, msg) =>
      console.error(
        `[proofread-docx] ERROR: ${msg || ""}`,
        typeof obj === "string" ? obj : ""
      ),
  };
}

const OUTPUT_DIR = resolve(__dirname, "proofread-output");

// ─── أنماط التعرّف على عناصر السيناريو ────────────────────────

const SCENE_HEADER_RE = /^(?:مشهد|مسـاهد|scene)\s*[0-9٠-٩]+/i;
const SCENE_LOCATION_RE = /^(?:نهار|ليل|صباح|مساء|غروب|فجر|شروق)\s*[-–—]/i;
const LOCATION_LINE_RE =
  /^(?:شقة|بيت|منزل|غرفة|شارع|مكتب|مستشفى|مسجد|كنيسة|مطعم|فندق|سيارة|طريق)/;
const CHARACTER_DIALOGUE_RE = /^([^\s:：]{1,20})\s*[:：]\s*(.+)$/;
const BULLET_CHARACTER_RE = /^[▪•●○]\s*([^\s:：]{1,20})\s*[:：]\s*(.+)$/;
const ACTION_CUE_RE = /^[-–—]\s+/;
const BASMALA_RE = /بسم\s*(?:الله|اللّه|اهلل)/;
const TRANSITION_RE = /^(?:قطع|CUT|FADE|انتقال)/i;

/**
 * يُصنّف سطراً واحداً إلى نوع سيناريو تقريبي.
 * التصنيف هنا مبسّط — الهدف منه التنسيق وليس الدقة الكاملة.
 */
const classifyLineSimple = (line) => {
  const trimmed = (line ?? "").replace(/[\u200f\u200e\ufeff]/g, "").trim();
  if (!trimmed) return { type: "empty", text: trimmed };

  if (BASMALA_RE.test(trimmed)) {
    return { type: "basmala", text: trimmed };
  }

  if (SCENE_HEADER_RE.test(trimmed)) {
    return { type: "scene-header", text: trimmed };
  }

  if (SCENE_LOCATION_RE.test(trimmed)) {
    return { type: "scene-location", text: trimmed };
  }

  if (LOCATION_LINE_RE.test(trimmed)) {
    return { type: "scene-location", text: trimmed };
  }

  if (TRANSITION_RE.test(trimmed)) {
    return { type: "transition", text: trimmed };
  }

  // شخصية + حوار في سطر واحد (بـ bullet أو بدون)
  const bulletMatch = trimmed.match(BULLET_CHARACTER_RE);
  if (bulletMatch) {
    return {
      type: "character-dialogue",
      character: bulletMatch[1].trim(),
      dialogue: bulletMatch[2].trim(),
      text: trimmed,
    };
  }

  const charMatch = trimmed.match(CHARACTER_DIALOGUE_RE);
  if (charMatch) {
    const namePart = charMatch[1].trim();
    // تأكد إن الاسم مش طويل جداً ومش جملة عادية
    if (namePart.length <= 15 && !/[.!?؟،]/.test(namePart)) {
      return {
        type: "character-dialogue",
        character: namePart,
        dialogue: charMatch[2].trim(),
        text: trimmed,
      };
    }
  }

  // أكشن (يبدأ بشرطة)
  if (ACTION_CUE_RE.test(trimmed)) {
    return {
      type: "action-cue",
      text: trimmed.replace(ACTION_CUE_RE, "").trim(),
    };
  }

  return { type: "narrative", text: trimmed };
};

// ─── توليد DOCX خام ───────────────────────────────────────────

const buildRawDocx = (text, _filename) => {
  const lines = text.split(/\r?\n/);
  const paragraphs = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      // سطر فارغ → paragraph فارغ
      paragraphs.push(new Paragraph({ text: "" }));
      continue;
    }

    paragraphs.push(
      new Paragraph({
        children: [
          new TextRun({
            text: trimmed,
            font: "Simplified Arabic",
            size: 24, // 12pt
            rightToLeft: true,
          }),
        ],
        bidirectional: true,
        alignment: AlignmentType.RIGHT,
      })
    );
  }

  return new Document({
    sections: [
      {
        properties: {
          page: {
            size: { width: 12240, height: 15840 }, // Letter
          },
        },
        children: paragraphs,
      },
    ],
  });
};

// ─── توليد DOCX مُنسّق ───────────────────────────────────────

const buildFormattedDocx = (text, _filename) => {
  const lines = text.split(/\r?\n/);
  const paragraphs = [];

  for (const line of lines) {
    const classified = classifyLineSimple(line);

    if (classified.type === "empty") {
      paragraphs.push(new Paragraph({ text: "" }));
      continue;
    }

    if (classified.type === "basmala") {
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: classified.text,
              font: "Simplified Arabic",
              size: 28, // 14pt
              bold: true,
              rightToLeft: true,
            }),
          ],
          heading: HeadingLevel.HEADING_1,
          bidirectional: true,
          alignment: AlignmentType.CENTER,
        })
      );
      continue;
    }

    if (classified.type === "scene-header") {
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: classified.text,
              font: "Simplified Arabic",
              size: 26, // 13pt
              bold: true,
              rightToLeft: true,
            }),
          ],
          heading: HeadingLevel.HEADING_2,
          bidirectional: true,
          alignment: AlignmentType.RIGHT,
          spacing: { before: 240, after: 60 },
        })
      );
      continue;
    }

    if (classified.type === "scene-location") {
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: classified.text,
              font: "Simplified Arabic",
              size: 24,
              bold: true,
              italics: true,
              rightToLeft: true,
            }),
          ],
          heading: HeadingLevel.HEADING_3,
          bidirectional: true,
          alignment: AlignmentType.RIGHT,
          spacing: { before: 60, after: 120 },
        })
      );
      continue;
    }

    if (classified.type === "transition") {
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: classified.text,
              font: "Simplified Arabic",
              size: 24,
              bold: true,
              rightToLeft: true,
            }),
          ],
          bidirectional: true,
          alignment: AlignmentType.CENTER,
          spacing: { before: 120, after: 120 },
        })
      );
      continue;
    }

    if (classified.type === "character-dialogue") {
      // اسم الشخصية bold + الحوار عادي
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: `${classified.character} : `,
              font: "Simplified Arabic",
              size: 24,
              bold: true,
              rightToLeft: true,
            }),
            new TextRun({
              text: classified.dialogue,
              font: "Simplified Arabic",
              size: 24,
              rightToLeft: true,
            }),
          ],
          bidirectional: true,
          alignment: AlignmentType.RIGHT,
        })
      );
      continue;
    }

    if (classified.type === "action-cue") {
      // أكشن — بشرطة في الأول + خط مائل
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: `- ${classified.text}`,
              font: "Simplified Arabic",
              size: 24,
              italics: true,
              rightToLeft: true,
            }),
          ],
          bidirectional: true,
          alignment: AlignmentType.RIGHT,
        })
      );
      continue;
    }

    // narrative / fallback
    paragraphs.push(
      new Paragraph({
        children: [
          new TextRun({
            text: classified.text,
            font: "Simplified Arabic",
            size: 24,
            rightToLeft: true,
          }),
        ],
        bidirectional: true,
        alignment: AlignmentType.RIGHT,
      })
    );
  }

  return new Document({
    sections: [
      {
        properties: {
          page: {
            size: { width: 12240, height: 15840 },
          },
        },
        children: paragraphs,
      },
    ],
  });
};

// ─── الدالة الرئيسية ──────────────────────────────────────────

/**
 * يحفظ النص المُراجع كملفي DOCX (خام + مُنسّق).
 *
 * @param {string} text - النص النهائي بعد vision-proofread
 * @param {string} originalFilename - اسم ملف PDF الأصلي
 * @returns {Promise<{rawPath: string, formattedPath: string}>}
 */
export const saveProofreadDocx = async (text, originalFilename) => {
  if (!text || !text.trim()) {
    logger.warn("proofread-docx-skip: empty text");
    return { rawPath: "", formattedPath: "" };
  }

  const baseName =
    basename(originalFilename || "document.pdf", ".pdf")
      .replace(/[^a-zA-Z0-9\u0600-\u06FF._-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 60) || "document";

  const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
  const rawFileName = `${baseName}-${timestamp}-raw.docx`;
  const formattedFileName = `${baseName}-${timestamp}-formatted.docx`;

  try {
    await mkdir(OUTPUT_DIR, { recursive: true });

    const rawDoc = buildRawDocx(text, originalFilename);
    const formattedDoc = buildFormattedDocx(text, originalFilename);

    const rawBuffer = await Packer.toBuffer(rawDoc);
    const formattedBuffer = await Packer.toBuffer(formattedDoc);

    const rawPath = join(OUTPUT_DIR, rawFileName);
    const formattedPath = join(OUTPUT_DIR, formattedFileName);

    await writeFile(rawPath, rawBuffer);
    await writeFile(formattedPath, formattedBuffer);

    logger.info(
      {
        rawPath,
        formattedPath,
        rawSize: rawBuffer.length,
        formattedSize: formattedBuffer.length,
        textLength: text.length,
      },
      "proofread-docx-saved"
    );

    return { rawPath, formattedPath };
  } catch (error) {
    logger.error(
      {
        error: error instanceof Error ? error.message : String(error),
        baseName,
      },
      "proofread-docx-failed"
    );
    return { rawPath: "", formattedPath: "" };
  }
};

import { resolveReviewChannelConfig } from "./provider-config.mjs";

const CANONICAL_MISTRAL_BASE_URL = "https://api.mistral.ai";
export const CANONICAL_MISTRAL_OCR_ENDPOINT = "https://api.mistral.ai/v1/ocr";
export const CANONICAL_MISTRAL_CHAT_COMPLETIONS_ENDPOINT =
  "https://api.mistral.ai/v1/chat/completions";
export const CANONICAL_MISTRAL_CONVERSATIONS_ENDPOINT =
  "https://api.mistral.ai/v1/conversations";
export const CANONICAL_MISTRAL_AGENTS_ENDPOINT =
  "https://api.mistral.ai/v1/agents";
export const CANONICAL_MISTRAL_AGENTS_COMPLETIONS_ENDPOINT =
  "https://api.mistral.ai/v1/agents/completions";
const DEFAULT_MOONSHOT_BASE_URL = "https://api.moonshot.ai/v1";
const DEFAULT_ANTHROPIC_BASE_URL = "https://api.anthropic.com";
const DEFAULT_ANTHROPIC_API_VERSION = "2023-06-01";
const reviewRuntimeSnapshots = new Map();

const toOptionalTrimmedString = (value, maxLength = 256) => {
  if (typeof value !== "string") return "";
  return value.trim().slice(0, maxLength);
};

const normalizeBaseUrl = (value, fallback) => {
  const normalized = toOptionalTrimmedString(value);
  if (!normalized) return fallback;
  return normalized.replace(/\/+$/u, "");
};

const withVersionedPath = (baseUrl, pathAfterV1) => {
  if (/\/v\d+$/iu.test(baseUrl)) {
    return `${baseUrl}${pathAfterV1}`;
  }
  return `${baseUrl}/v1${pathAfterV1}`;
};

export const resolveMistralOcrRuntime = (_env = process.env) => {
  return {
    baseUrl: CANONICAL_MISTRAL_BASE_URL,
    ocrEndpoint: CANONICAL_MISTRAL_OCR_ENDPOINT,
    endpointSource: "hard-locked-canonical",
  };
};

export const resolveMistralChatRuntime = (_env = process.env) => {
  return {
    baseUrl: CANONICAL_MISTRAL_BASE_URL,
    chatCompletionsEndpoint: CANONICAL_MISTRAL_CHAT_COMPLETIONS_ENDPOINT,
    endpointSource: "hard-locked-canonical",
  };
};

export const resolveMistralConversationsRuntime = (_env = process.env) => {
  return {
    baseUrl: CANONICAL_MISTRAL_BASE_URL,
    conversationsEndpoint: CANONICAL_MISTRAL_CONVERSATIONS_ENDPOINT,
    endpointSource: "hard-locked-canonical",
  };
};

export const resolveMistralAgentsRuntime = (_env = process.env) => {
  return {
    baseUrl: CANONICAL_MISTRAL_BASE_URL,
    agentsEndpoint: CANONICAL_MISTRAL_AGENTS_ENDPOINT,
    agentsCompletionsEndpoint: CANONICAL_MISTRAL_AGENTS_COMPLETIONS_ENDPOINT,
    endpointSource: "hard-locked-canonical",
  };
};

export const resolveMoonshotChatRuntime = (env = process.env) => {
  const baseUrl = normalizeBaseUrl(
    env.MOONSHOT_BASE_URL ?? env.KIMI_BASE_URL,
    DEFAULT_MOONSHOT_BASE_URL
  );

  return {
    baseUrl,
    chatCompletionsEndpoint: withVersionedPath(baseUrl, "/chat/completions"),
  };
};

export const resolveAnthropicApiRuntime = (env = process.env) => {
  const baseUrl = normalizeBaseUrl(
    env.ANTHROPIC_BASE_URL,
    DEFAULT_ANTHROPIC_BASE_URL
  );
  const apiVersion =
    toOptionalTrimmedString(env.ANTHROPIC_API_VERSION, 64).toLowerCase() ||
    DEFAULT_ANTHROPIC_API_VERSION;

  return {
    baseUrl,
    apiVersion,
    messagesEndpoint: withVersionedPath(baseUrl, "/messages"),
  };
};

const cloneReviewRuntimeSnapshot = (snapshot) => ({
  ...snapshot,
  credentialWarnings: [...snapshot.credentialWarnings],
});

const buildConfiguredReviewSnapshot = (channel, env = process.env) => {
  const config = resolveReviewChannelConfig(channel, env);

  return {
    channel,
    requestedModel: config.requestedModel,
    resolvedProvider: config.resolvedProvider,
    resolvedModel: config.resolvedModel,
    resolvedSpecifier: config.resolvedSpecifier,
    fallbackRequestedModel: config.requestedFallbackModel,
    fallbackProvider: config.fallback?.valid ? config.fallback.provider : null,
    fallbackModel: config.fallback?.valid ? config.fallback.model : null,
    fallbackSpecifier: config.fallback?.valid
      ? config.fallback.specifier
      : null,
    fallbackConfigured: Boolean(config.fallbackConfigured),
    configured: Boolean(config.configured),
    credentialWarnings: [...config.warnings],
    apiBaseUrl: config.primary?.baseUrl ?? null,
    apiVersion: config.primary?.apiVersion ?? null,
    activeProvider: config.resolvedProvider,
    activeModel: config.resolvedModel,
    activeSpecifier: config.resolvedSpecifier,
    usedFallback: false,
    fallbackReason: null,
    lastStatus: "idle",
    lastErrorClass: null,
    lastErrorMessage: null,
    lastProviderStatusCode: null,
    retryCount: 0,
    latencyMs: null,
    lastInvocationAt: null,
    lastSuccessAt: null,
    lastFailureAt: null,
    lastUpdatedAt: null,
  };
};

export const getReviewRuntimeSnapshot = (channel, env = process.env) => {
  const baseSnapshot = buildConfiguredReviewSnapshot(channel, env);
  const existingSnapshot = reviewRuntimeSnapshots.get(channel);

  if (!existingSnapshot) {
    return cloneReviewRuntimeSnapshot(baseSnapshot);
  }

  const configChanged =
    existingSnapshot.requestedModel !== baseSnapshot.requestedModel ||
    existingSnapshot.fallbackRequestedModel !==
      baseSnapshot.fallbackRequestedModel ||
    existingSnapshot.resolvedSpecifier !== baseSnapshot.resolvedSpecifier ||
    existingSnapshot.fallbackSpecifier !== baseSnapshot.fallbackSpecifier;

  return cloneReviewRuntimeSnapshot({
    ...existingSnapshot,
    requestedModel: baseSnapshot.requestedModel,
    resolvedProvider: baseSnapshot.resolvedProvider,
    resolvedModel: baseSnapshot.resolvedModel,
    resolvedSpecifier: baseSnapshot.resolvedSpecifier,
    fallbackRequestedModel: baseSnapshot.fallbackRequestedModel,
    fallbackProvider: baseSnapshot.fallbackProvider,
    fallbackModel: baseSnapshot.fallbackModel,
    fallbackSpecifier: baseSnapshot.fallbackSpecifier,
    fallbackConfigured: baseSnapshot.fallbackConfigured,
    configured: baseSnapshot.configured,
    credentialWarnings: baseSnapshot.credentialWarnings,
    apiBaseUrl: baseSnapshot.apiBaseUrl,
    apiVersion: baseSnapshot.apiVersion,
    activeProvider: configChanged
      ? baseSnapshot.resolvedProvider
      : existingSnapshot.activeProvider,
    activeModel: configChanged
      ? baseSnapshot.resolvedModel
      : existingSnapshot.activeModel,
    activeSpecifier: configChanged
      ? baseSnapshot.resolvedSpecifier
      : existingSnapshot.activeSpecifier,
    usedFallback: configChanged ? false : existingSnapshot.usedFallback,
    fallbackReason: configChanged ? null : existingSnapshot.fallbackReason,
    lastStatus: configChanged ? "idle" : existingSnapshot.lastStatus,
    lastErrorClass: configChanged ? null : existingSnapshot.lastErrorClass,
    lastErrorMessage: configChanged ? null : existingSnapshot.lastErrorMessage,
    lastProviderStatusCode: configChanged
      ? null
      : existingSnapshot.lastProviderStatusCode,
    retryCount: configChanged ? 0 : existingSnapshot.retryCount,
    latencyMs: configChanged ? null : existingSnapshot.latencyMs,
  });
};

export const updateReviewRuntimeSnapshot = (
  channel,
  patch,
  env = process.env
) => {
  const currentSnapshot = getReviewRuntimeSnapshot(channel, env);
  const nextSnapshot = {
    ...currentSnapshot,
    ...patch,
    lastUpdatedAt: Date.now(),
  };
  reviewRuntimeSnapshots.set(channel, nextSnapshot);
  return cloneReviewRuntimeSnapshot(nextSnapshot);
};

export const getAllReviewRuntimeSnapshots = (env = process.env) => ({
  agentReview: getReviewRuntimeSnapshot("agent-review", env),
  suspicionReview: getReviewRuntimeSnapshot("suspicion-review", env),
  finalReview: getReviewRuntimeSnapshot("final-review", env),
});

/**
 * @description خدمة استخراج النصوص من ملفات DOC عبر antiword
 */

import process from "node:process";
import { execFile, execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, extname, join } from "node:path";
import {
  ExecFileClassifiedError,
  classifyExecError,
} from "../exec-file-error-classifier.mjs";
import { normalizeIncomingText } from "./text-normalizer.mjs";
import { cleanExtractedDocText } from "./text-normalizer.mjs";

const DOC_CONVERTER_TIMEOUT_MS = 30_000;
const DOC_CONVERTER_MAX_BUFFER = 64 * 1024 * 1024;
const DEFAULT_ANTIWORD_PATH = "antiword";
const DEFAULT_ANTIWORD_HOME = "/usr/share/antiword";

export { DEFAULT_ANTIWORD_PATH, DEFAULT_ANTIWORD_HOME };

const toExecBuffer = (value) =>
  Buffer.isBuffer(value) ? value : Buffer.from(value ?? "", "utf-8");

const decodeUtf8Buffer = (value) => {
  if (!value) return "";
  if (typeof value === "string") return value;
  return new TextDecoder("utf-8").decode(value);
};

export const resolveAntiwordRuntime = () => {
  const antiwordPath =
    process.env.ANTIWORD_PATH?.trim() || DEFAULT_ANTIWORD_PATH;
  const antiwordHome =
    process.env.ANTIWORDHOME?.trim() || DEFAULT_ANTIWORD_HOME;

  return {
    antiwordPath,
    antiwordHome,
    runtimeSource: process.env.ANTIWORD_PATH?.trim() ? "env" : "path-default",
  };
};

export const runAntiwordPreflight = () => {
  const runtime = resolveAntiwordRuntime();
  const warnings = [];
  let binaryAvailable = false;

  try {
    execFileSync(runtime.antiwordPath, ["-h"], {
      stdio: "pipe",
      timeout: 5000,
      windowsHide: true,
      env: {
        ...process.env,
        HOME: runtime.antiwordHome,
        ANTIWORDHOME: runtime.antiwordHome,
      },
    });
    binaryAvailable = true;
  } catch (error) {
    const code = typeof error?.code === "string" ? error.code : "";
    if (code === "ENOENT") {
      warnings.push(
        `antiword binary غير موجود على المسار الحالي: ${runtime.antiwordPath}`
      );
    } else if (code === "EACCES") {
      warnings.push(
        `antiword binary موجود لكنه غير قابل للتنفيذ: ${runtime.antiwordPath}`
      );
    } else {
      // antiword قد يرجع exit code غير صفري مع -h رغم وجوده.
      binaryAvailable = true;
    }
  }

  const antiwordHomeExists = existsSync(runtime.antiwordHome);
  if (!antiwordHomeExists) {
    warnings.push(
      `ANTIWORDHOME غير موجود أو غير صحيح: ${runtime.antiwordHome}`
    );
  }

  return {
    ...runtime,
    binaryAvailable,
    antiwordHomeExists,
    warnings,
  };
};

const runAntiword = async (antiwordPath, args, antiwordHome) =>
  new Promise((resolve, reject) => {
    execFile(
      antiwordPath,
      args,
      {
        encoding: "buffer",
        timeout: DOC_CONVERTER_TIMEOUT_MS,
        maxBuffer: DOC_CONVERTER_MAX_BUFFER,
        windowsHide: true,
        env: {
          ...process.env,
          HOME: antiwordHome,
          ANTIWORDHOME: antiwordHome,
        },
      },
      (error, stdout, stderr) => {
        const stdoutBuffer = toExecBuffer(stdout);
        const stderrBuffer = toExecBuffer(stderr);

        if (error) {
          reject(
            classifyExecError(
              error,
              "antiword",
              DOC_CONVERTER_TIMEOUT_MS,
              stdoutBuffer,
              stderrBuffer
            )
          );
          return;
        }

        resolve({ stdout: stdoutBuffer, stderr: stderrBuffer });
      }
    );
  });

const resolveTempFilename = (filename) => {
  const base = basename(filename || "document.doc");
  const hscene_header_3ocExt = extname(base).toLowerCase() === ".doc";
  return hscene_header_3ocExt ? base : `${base}.doc`;
};

export const convertDocBufferToText = async (buffer, filename) => {
  const warnings = [];
  const attempts = ["doc-converter-flow"];
  const runtime = resolveAntiwordRuntime();
  let tempDirPath = null;

  try {
    tempDirPath = await mkdtemp(join(tmpdir(), "doc-converter-flow-"));
    const tempFilePath = join(tempDirPath, resolveTempFilename(filename));
    await writeFile(tempFilePath, buffer);

    const { stdout, stderr } = await runAntiword(
      runtime.antiwordPath,
      ["-m", "UTF-8.txt", "-w", "0", tempFilePath],
      runtime.antiwordHome
    );

    const stderrText = decodeUtf8Buffer(stderr).trim();
    if (stderrText) warnings.push(stderrText);

    const decoded = decodeUtf8Buffer(stdout);
    const cleaned = cleanExtractedDocText(decoded);
    if (!cleaned) {
      throw new Error("antiword أعاد نصًا فارغًا");
    }

    return {
      text: cleaned,
      method: "doc-converter-flow",
      usedOcr: false,
      attempts,
      warnings,
      antiword: runtime,
    };
  } catch (error) {
    if (error instanceof ExecFileClassifiedError) {
      const stderrText = normalizeIncomingText(
        error.classifiedError?.stderrPreview,
        400
      );
      if (stderrText) warnings.push(stderrText);
      throw new ExecFileClassifiedError(
        `فشل تحويل ملف DOC عبر antiword (${runtime.antiwordPath}): ${error.message}`,
        {
          statusCode: error.statusCode,
          category: error.category,
          classifiedError: {
            ...error.classifiedError,
            antiwordPath: runtime.antiwordPath,
            antiwordHome: runtime.antiwordHome,
          },
        }
      );
    }
    throw new Error(
      `فشل تحويل ملف DOC عبر antiword (${runtime.antiwordPath}): ${
        error instanceof Error ? error.message : String(error)
      }`,
      {
        cause: error,
      }
    );
  } finally {
    if (tempDirPath) {
      await rm(tempDirPath, { recursive: true, force: true }).catch(() => {});
    }
  }
};

export const decodeUtf8Fallback = (buffer) => {
  const utf8Text = buffer.toString("utf8");
  const hasReplacementChars =
    utf8Text.includes("\uFFFD") || utf8Text.includes("�");
  if (!hasReplacementChars) return utf8Text;
  return buffer.toString("latin1");
};

/**
 * @description خدمة استخراج النصوص من ملفات DOCX عبر Mammoth مباشرةً ثم fallback إلى DOC/antiword عند الحاجة
 */

import process from "node:process";
import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdtemp, readFile, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, extname, join } from "node:path";
import { fileURLToPath } from "node:url";
import mammoth from "mammoth";
import {
  ExecFileClassifiedError,
  classifyExecError,
} from "../exec-file-error-classifier.mjs";
import {
  cleanExtractedDocText,
  normalizeIncomingText,
} from "./text-normalizer.mjs";
import { convertDocBufferToText } from "./doc-extractor.mjs";

const DOCX_TO_DOC_CONVERTER_TIMEOUT_MS = 90_000;
const DOC_CONVERTER_MAX_BUFFER = 64 * 1024 * 1024;

export const DOCX_TO_DOC_SCRIPT_PATH = fileURLToPath(
  new URL("../docx-to-doc.final.ts", import.meta.url)
);
export const DOCX_TO_DOC_SCRIPT_EXISTS = existsSync(DOCX_TO_DOC_SCRIPT_PATH);

const toExecBuffer = (value) =>
  Buffer.isBuffer(value) ? value : Buffer.from(value ?? "", "utf-8");

const decodeUtf8Buffer = (value) => {
  if (!value) return "";
  if (typeof value === "string") return value;
  return new TextDecoder("utf-8").decode(value);
};

const normalizeMammothWarnings = (messages) =>
  Array.isArray(messages)
    ? messages
        .map((entry) => {
          if (!entry || typeof entry !== "object") return "";
          return normalizeIncomingText(entry.message, 400);
        })
        .filter(Boolean)
    : [];

const resolveDocxTempFilename = (filename) => {
  const base = basename(filename || "document.docx");
  const hscene_header_3ocxExt = extname(base).toLowerCase() === ".docx";
  if (hscene_header_3ocxExt) return base;
  const withoutExt = base.replace(/\.[^.]+$/, "");
  return `${withoutExt || "document"}.docx`;
};

const runDocxToDocConverter = async (inputDocxPath, outputDocPath) =>
  new Promise((resolve, reject) => {
    const args = [
      "--import",
      "tsx",
      DOCX_TO_DOC_SCRIPT_PATH,
      inputDocxPath,
      outputDocPath,
      "--overwrite",
    ];

    execFile(
      process.execPath,
      args,
      {
        encoding: "buffer",
        timeout: DOCX_TO_DOC_CONVERTER_TIMEOUT_MS,
        maxBuffer: DOC_CONVERTER_MAX_BUFFER,
        windowsHide: true,
      },
      (error, stdout, stderr) => {
        const stdoutBuffer = toExecBuffer(stdout);
        const stderrBuffer = toExecBuffer(stderr);

        if (error) {
          reject(
            classifyExecError(
              error,
              "docx-to-doc.final.ts",
              DOCX_TO_DOC_CONVERTER_TIMEOUT_MS,
              stdoutBuffer,
              stderrBuffer
            )
          );
          return;
        }

        resolve({ stdout: stdoutBuffer, stderr: stderrBuffer });
      }
    );
  });

export const convertDocxBufferToTextWithMammoth = async (buffer, filename) => {
  const normalizedBuffer = Buffer.isBuffer(buffer)
    ? buffer
    : Buffer.from(buffer ?? "");

  const result = await mammoth.extractRawText({ buffer: normalizedBuffer });
  const text = cleanExtractedDocText(result.value ?? "");

  if (!text) {
    throw new Error(
      `تعذر استخراج نص DOCX مباشرةً من الملف: ${filename || "document.docx"}`
    );
  }

  return {
    text,
    method: "mammoth",
    usedOcr: false,
    attempts: ["mammoth-direct"],
    warnings: normalizeMammothWarnings(result.messages),
    normalizationApplied: ["docx-mammoth-extract"],
  };
};

export const convertDocxBufferToDocThenExtract = async (buffer, filename) => {
  const warnings = [];
  const attempts = ["docx-to-doc.final", "doc-converter-flow"];
  let tempDirPath = null;

  try {
    tempDirPath = await mkdtemp(join(tmpdir(), "docx-to-doc-flow-"));
    const sourceDocxPath = join(tempDirPath, resolveDocxTempFilename(filename));
    const convertedDocPath = sourceDocxPath.replace(/\.docx$/i, ".doc");

    await writeFile(sourceDocxPath, buffer);
    const { stdout, stderr } = await runDocxToDocConverter(
      sourceDocxPath,
      convertedDocPath
    );

    const converterStdout = decodeUtf8Buffer(stdout).trim();
    const converterStderr = decodeUtf8Buffer(stderr).trim();
    if (converterStdout) warnings.push(converterStdout);
    if (converterStderr) warnings.push(converterStderr);

    if (!existsSync(convertedDocPath)) {
      throw new Error(
        `تم تشغيل محول DOCX لكن ملف DOC الناتج غير موجود: ${convertedDocPath}`
      );
    }

    const convertedDocBuffer = await readFile(convertedDocPath);
    const extractedDoc = await convertDocBufferToText(
      convertedDocBuffer,
      basename(convertedDocPath)
    );

    return {
      ...extractedDoc,
      method: "doc-converter-flow",
      attempts: [...attempts, ...extractedDoc.attempts],
      warnings: [...warnings, ...extractedDoc.warnings],
    };
  } catch (error) {
    if (error instanceof ExecFileClassifiedError) {
      const stdoutText = normalizeIncomingText(
        error.classifiedError?.stdoutPreview,
        400
      );
      const stderrText = normalizeIncomingText(
        error.classifiedError?.stderrPreview,
        400
      );
      if (stdoutText) warnings.push(stdoutText);
      if (stderrText) warnings.push(stderrText);
      throw new ExecFileClassifiedError(
        `فشل مسار تحويل DOCX→DOC عبر docx-to-doc.final.ts: ${error.message}${
          warnings.length > 0 ? ` | logs: ${warnings.join(" | ")}` : ""
        }`,
        {
          statusCode: error.statusCode,
          category: error.category,
          classifiedError: {
            ...error.classifiedError,
            converterScript: DOCX_TO_DOC_SCRIPT_PATH,
          },
        }
      );
    }

    throw new Error(
      `فشل مسار تحويل DOCX→DOC عبر docx-to-doc.final.ts: ${
        error instanceof Error ? error.message : String(error)
      }${warnings.length > 0 ? ` | logs: ${warnings.join(" | ")}` : ""}`,
      {
        cause: error,
      }
    );
  } finally {
    if (tempDirPath) {
      await rm(tempDirPath, { recursive: true, force: true }).catch(() => {});
    }
  }
};

/**
 * @description خدمات تطبيع النصوص المستخرجة من الملفات
 */

export const isObjectRecord = (value) =>
  typeof value === "object" && value !== null;

export const isNonEmptyString = (value) =>
  typeof value === "string" && value.trim().length > 0;

export const normalizeIncomingText = (value, maxLength = 50_000) => {
  if (typeof value !== "string") return "";
  return value.trim().slice(0, maxLength);
};

export const stripAsciiControlChars = (value, options = {}) => {
  const { preserveTabs = false, preserveNewlines = false } = options;
  const text = String(value ?? "");
  let cleaned = "";

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    const code = ch.charCodeAt(0);
    const isAsciiControl = code <= 0x1f || code === 0x7f;

    if (!isAsciiControl) {
      cleaned += ch;
      continue;
    }

    if (preserveTabs && code === 0x09) {
      cleaned += ch;
      continue;
    }

    if (preserveNewlines && (code === 0x0a || code === 0x0d)) {
      cleaned += ch;
    }
  }

  return cleaned;
};

export const normalizeText = (value) =>
  stripAsciiControlChars(
    String(value ?? "")
      .replace(/\r\n/g, "\n")
      .replace(/\r/g, "\n"),
    {
      preserveNewlines: true,
    }
  )
    .replace(/\n{3,}/g, "\n\n")
    .trim();

export const cleanExtractedDocText = (text) =>
  normalizeText(text)
    .replace(/\u00a0/g, " ")
    .split("\n")
    .map((line) => line.replace(/[^\S\r\n]{2,}/g, " ").trimEnd())
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

