import React, { useMemo, useState } from "react";
import { Search } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { HoverBorderGradient } from "@/components/ui/hover-border-gradient";
import {
  EDITOR_SHELL_SIDEBAR_BOTTOM_PX,
  EDITOR_SHELL_SIDEBAR_RIGHT_PX,
  EDITOR_SHELL_SIDEBAR_TOP_PX,
} from "../../constants/shell-layout";

export interface AppSidebarSection {
  id: string;
  label: string;
  icon: LucideIcon;
  items: readonly string[];
}

export interface AppSidebarProps {
  sections: readonly AppSidebarSection[];
  openSectionId: string | null;
  isMobile: boolean;
  onToggleSection: (sectionId: string) => void;
  onItemAction: (sectionId: string, itemLabel: string) => void;
  settingsPanel: React.ReactNode;
  /**
   * نص المحرر الحالي — يُستخدم لحساب عدد مطابقات البحث داخل المستند.
   * عند تزويده، يظهر قسم «نتائج من المحرر» في نتائج البحث (BUG-005).
   */
  documentText?: string;
  /**
   * يُستدعى عند الضغط على نتيجة المحرر — يطلب من الأب الانتقال
   * إلى أول مطابقة داخل المحرر (تحديد + scrollIntoView).
   */
  onEditorSearchJump?: (query: string) => void;
}

/**
 * الشريط الجانبي للمحرر.
 *
 * إعادة تصميم بصري فقط: تحولت اللوحة من خلفية داكنة إلى "بطاقة عائمة"
 * بيضاء دافئة فوق سطح ورقي. حوافها ناعمة، ظلها واسع وخفيف، والنص داكن.
 * لم يتغير أي سلوك: البحث، التصفية، فتح/طي الأقسام، حقن لوحة الإعدادات،
 * ومنطق onItemAction — جميعها محفوظة كما هي.
 */
export function AppSidebar({
  sections,
  openSectionId,
  isMobile: _isMobile,
  onToggleSection,
  onItemAction,
  settingsPanel,
  documentText = "",
  onEditorSearchJump,
}: AppSidebarProps): React.JSX.Element {
  const [searchQuery, setSearchQuery] = useState("");
  const normalizedQuery = searchQuery.trim().toLowerCase();

  const visibleSections = useMemo(
    () =>
      sections.map((section) => ({
        ...section,
        filteredItems:
          normalizedQuery.length === 0
            ? section.items
            : section.items.filter((item) =>
                item.toLowerCase().includes(normalizedQuery)
              ),
      })),
    [normalizedQuery, sections]
  );

  /**
   * حساب عدد مطابقات البحث داخل نص المحرر (غير حساس للحالة).
   * السبب: QA أشار إلى أن البحث في الشريط الجانبي لا يرى محتوى
   * المحرر — كلمة «أمين» موجودة لكنه يُرجع «لا توجد نتائج» (BUG-005).
   */
  const editorMatchCount = useMemo(() => {
    if (normalizedQuery.length === 0) return 0;
    if (!documentText) return 0;
    const haystack = documentText.toLowerCase();
    let count = 0;
    let index = 0;
    while ((index = haystack.indexOf(normalizedQuery, index)) !== -1) {
      count += 1;
      index += normalizedQuery.length;
    }
    return count;
  }, [normalizedQuery, documentText]);

  /**
   * مقتطف قصير من نص المحرر يحيط بأول مطابقة — لعرضه كمعاينة
   * أسفل زر النتائج. يُظهر المستخدم أن البحث عثر على السياق الصحيح.
   */
  const editorMatchPreview = useMemo(() => {
    if (editorMatchCount === 0) return "";
    const idx = documentText.toLowerCase().indexOf(normalizedQuery);
    if (idx === -1) return "";
    const start = Math.max(0, idx - 24);
    const end = Math.min(
      documentText.length,
      idx + normalizedQuery.length + 24
    );
    const prefix = start > 0 ? "…" : "";
    const suffix = end < documentText.length ? "…" : "";
    return `${prefix}${documentText.slice(start, end).replace(/\s+/g, " ").trim()}${suffix}`;
  }, [editorMatchCount, documentText, normalizedQuery]);

  const hasAnySearchResult =
    normalizedQuery.length === 0 ||
    editorMatchCount > 0 ||
    visibleSections.some((section) => section.filteredItems.length > 0);

  return (
    <aside
      className="app-sidebar fixed z-30 flex w-72 flex-col"
      style={{
        top: `${EDITOR_SHELL_SIDEBAR_TOP_PX}px`,
        right: `${EDITOR_SHELL_SIDEBAR_RIGHT_PX}px`,
        bottom: `${EDITOR_SHELL_SIDEBAR_BOTTOM_PX}px`,
        maxHeight: `calc(100vh - ${EDITOR_SHELL_SIDEBAR_TOP_PX + EDITOR_SHELL_SIDEBAR_BOTTOM_PX}px)`,
      }}
      data-layout-mode="fixed-desktop"
      data-testid="app-sidebar"
      aria-label="الشريط الجانبي للمحرر"
    >
      <div className="app-sidebar-card relative z-[2] flex h-full min-h-0 w-full flex-col items-stretch overflow-hidden p-4">
        <HoverBorderGradient
          containerClassName="rounded-xl mb-6"
          className="flex w-full items-center gap-2 rounded-xl bg-transparent px-3 py-3 text-[color:var(--mf-text-muted)]"
          duration={2}
        >
          <Search
            className="size-4 transition-colors group-focus-within:text-[color:var(--mf-accent)]"
            aria-hidden="true"
          />
          <input
            id="sidebar-search"
            name="sidebar-search"
            type="text"
            autoComplete="off"
            spellCheck={false}
            data-form-type="other"
            data-lpignore="true"
            data-1p-ignore="true"
            suppressHydrationWarning
            placeholder="بحث..."
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            data-testid="sidebar-search"
            className="w-full border-none bg-transparent text-[13px] text-[color:var(--mf-text)] placeholder:text-[color:var(--mf-text-faint)] focus:outline-none"
          />
          <kbd className="hidden rounded border border-[color:var(--mf-border)] bg-white px-1.5 py-0.5 text-[10px] group-hover:block">
            ⌘K
          </kbd>
        </HoverBorderGradient>

        <div
          className="scrollbar-none min-h-0 flex-1 space-y-2 overflow-y-auto pr-1"
          data-testid="sidebar-sections-scroll"
        >
          {!hasAnySearchResult && (
            <div className="app-sidebar-focus-tip px-3 py-2 text-right text-xs">
              لا توجد نتائج مطابقة للبحث.
            </div>
          )}

          {normalizedQuery.length > 0 && editorMatchCount > 0 && (
            <div className="mb-3" data-testid="sidebar-editor-search-results">
              <HoverBorderGradient
                as="button"
                type="button"
                suppressHydrationWarning
                onClick={() => {
                  if (onEditorSearchJump) {
                    onEditorSearchJump(searchQuery.trim());
                  }
                }}
                containerClassName="rounded-xl w-full"
                className="app-sidebar-section group flex w-full flex-col items-stretch gap-1 rounded-xl bg-transparent p-3 text-right text-[color:var(--mf-text-muted)] transition-all duration-200 hover:text-[color:var(--mf-text-strong)] focus-visible:ring-2 focus-visible:ring-[color:var(--mf-accent)]/60 focus-visible:outline-none"
                duration={2}
              >
                <span className="flex items-center justify-between gap-2 text-sm font-medium">
                  <span className="text-[11px] font-normal text-[color:var(--mf-text-faint)]">
                    اضغط للانتقال
                  </span>
                  <span>
                    {editorMatchCount === 1
                      ? "نتيجة واحدة في المحرر"
                      : `${editorMatchCount} نتائج في المحرر`}
                  </span>
                </span>
                {editorMatchPreview && (
                  <span className="truncate text-[11px] text-[color:var(--mf-text-faint)]">
                    {editorMatchPreview}
                  </span>
                )}
              </HoverBorderGradient>
            </div>
          )}

          {visibleSections.map((section) => {
            const SIcon = section.icon;
            const isOpen = openSectionId === section.id;
            const visibleItems = section.filteredItems;
            const hasItems = visibleItems.length > 0;
            const shouldRenderSection =
              normalizedQuery.length === 0 ||
              hasItems ||
              section.id === "settings";

            if (!shouldRenderSection) {
              return null;
            }

            return (
              <div key={section.id} className="mb-2">
                <HoverBorderGradient
                  as="button"
                  type="button"
                  suppressHydrationWarning
                  data-open={isOpen ? "true" : "false"}
                  onClick={() => onToggleSection(section.id)}
                  containerClassName="rounded-xl w-full"
                  className={`app-sidebar-section group flex w-full items-center gap-3 rounded-xl bg-transparent p-3 transition-all duration-200 focus-visible:ring-2 focus-visible:ring-[color:var(--mf-accent)]/60 focus-visible:outline-none ${
                    isOpen
                      ? "text-[color:var(--mf-text-strong)]"
                      : "text-[color:var(--mf-text-muted)] hover:text-[color:var(--mf-text-strong)]"
                  }`}
                  duration={2}
                >
                  <SIcon
                    className={`size-[18px] transition-colors ${
                      isOpen
                        ? "text-[color:var(--mf-text-strong)]"
                        : "text-[color:var(--mf-text-muted)] group-hover:text-[color:var(--mf-text-strong)]"
                    }`}
                  />
                  <span className="flex-1 text-right text-sm font-medium">
                    {section.label}
                  </span>
                  {section.items.length > 0 && (
                    <span
                      className={`text-[color:var(--mf-text-faint)] transition-transform duration-300 ${
                        isOpen ? "-rotate-90" : ""
                      }`}
                    >
                      {hasItems ? "‹" : "·"}
                    </span>
                  )}
                </HoverBorderGradient>

                {isOpen && hasItems && (
                  <div className="mt-2 space-y-1 pr-4">
                    {visibleItems.map((item) => (
                      <HoverBorderGradient
                        as="button"
                        type="button"
                        suppressHydrationWarning
                        key={`${section.id}-${item}`}
                        onClick={() => onItemAction(section.id, item)}
                        containerClassName="rounded-lg w-full"
                        className="app-sidebar-item flex w-full items-center gap-2 rounded-lg bg-transparent px-3 py-2 text-xs text-[color:var(--mf-text-muted)] transition-colors hover:text-[color:var(--mf-text-strong)] focus-visible:ring-2 focus-visible:ring-[color:var(--mf-accent)]/60 focus-visible:outline-none"
                        duration={2}
                      >
                        <span
                          className="h-1 w-1 rounded-full bg-[color:var(--mf-text-faint)]"
                          aria-hidden="true"
                        />
                        {item}
                      </HoverBorderGradient>
                    ))}
                  </div>
                )}

                {isOpen &&
                  !hasItems &&
                  section.id !== "settings" &&
                  normalizedQuery.length > 0 && (
                    <div className="app-sidebar-focus-tip mt-2 px-3 py-2 text-right text-[11px]">
                      لا توجد عناصر لهذا القسم حسب البحث الحالي.
                    </div>
                  )}

                {isOpen && section.id === "settings" && settingsPanel}
              </div>
            );
          })}
        </div>

        <div className="mt-auto">
          <div className="app-sidebar-focus-tip flex w-full flex-col items-start p-4">
            <span
              className="mb-2 text-base text-[color:var(--mf-accent)]"
              aria-hidden="true"
            >
              ✦
            </span>
            <p className="text-xs leading-relaxed font-light text-[color:var(--mf-text-muted)]">
              تم تفعيل وضع التركيز الذكي. استمتع بتجربة كتابة خالية من المشتتات.
            </p>
          </div>
        </div>
      </div>
    </aside>
  );
}

"use client";

import { definedProps } from "@/lib/defined-props";
import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  pipelineRecorder,
  type PipelineEvent,
  type RecordedAICorrection,
} from "@editor/extensions/pipeline-recorder";
import type { ProgressiveSurfaceState } from "../editor";

// ─── أنواع ─────────────────────────────────────────────────────────

interface StageEntry {
  stage: string;
  lineCount: number;
  changes: number;
  latencyMs: number;
  timestamp: number;
  metadata?: Record<string, unknown>;
  activeFiles: string[];
}

interface RunState {
  runId: string;
  source: string;
  inputLines: number;
  inputChars: number;
  startedAt: number;
  stages: StageEntry[];
  aiCorrections: RecordedAICorrection[];
  finished: boolean;
  totalDurationMs: number;
  finalTypeDist: Record<string, number>;
}

// ─── ثوابت المراحل ──────────────────────────────────────────────────

const STAGE_META: Record<string, { label: string; icon: string }> = {
  "engine-bridge": { label: "البريدج", icon: "🌉" },
  "schema-style-classify": { label: "تصنيف Schema", icon: "📐" },
  "forward-pass": { label: "التمرير الأمامي", icon: "➡️" },
  retroactive: { label: "التصحيح الرجعي", icon: "🔄" },
  "reverse-pass": { label: "التمرير العكسي", icon: "⬅️" },
  viterbi: { label: "Viterbi", icon: "🧬" },
  "render-first": { label: "العرض الأول", icon: "🖥️" },
  "gemini-context": { label: "Gemini سياق", icon: "🤖" },
  "final-review": { label: "المراجعة النهائية", icon: "🧠" },
};

const getStageMeta = (stage: string) =>
  STAGE_META[stage] ?? { label: stage, icon: "⚙️" };

// ─── مكون شريط التقدم ──────────────────────────────────────────────

const ProgressBar: React.FC<{ current: number; total: number }> = ({
  current,
  total,
}) => {
  const pct = total > 0 ? Math.round((current / total) * 100) : 0;
  return (
    <div className="h-1.5 w-full overflow-hidden rounded-full bg-black/18">
      <div
        className="h-full rounded-full bg-gradient-to-l from-cyan-400 to-blue-600 transition-all duration-300"
        style={{ width: `${pct}%` }}
      />
    </div>
  );
};

// ─── مكون مرحلة واحدة ──────────────────────────────────────────────

const StageRow: React.FC<{
  entry: StageEntry;
  isActive: boolean;
  isLast: boolean;
}> = ({ entry, isActive, isLast }) => {
  const meta = getStageMeta(entry.stage);
  return (
    <>
      <div
        className={`flex items-center gap-2 rounded-md px-3 py-1.5 text-xs transition-colors ${
          isActive
            ? "border border-cyan-700/40 bg-cyan-950/60"
            : isLast
              ? "bg-black/18"
              : "bg-transparent"
        }`}
      >
        <span className="shrink-0 text-sm">{meta.icon}</span>
        <span className="min-w-[100px] font-medium text-white">
          {meta.label}
        </span>
        <span className="text-white/45 tabular-nums">
          {entry.lineCount} سطر
        </span>
        {entry.changes > 0 && (
          <span className="text-amber-400 tabular-nums">Δ{entry.changes}</span>
        )}
        {entry.latencyMs > 0 && (
          <span className="ms-auto text-white/55 tabular-nums">
            {entry.latencyMs}ms
          </span>
        )}
        {isActive && (
          <span className="relative ms-1 flex h-2 w-2">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-cyan-400 opacity-60" />
            <span className="relative inline-flex h-2 w-2 rounded-full bg-cyan-400" />
          </span>
        )}
      </div>
      {entry.activeFiles.length > 0 && (
        <div className="-mt-0.5 flex flex-wrap gap-1 px-3 pb-1">
          {entry.activeFiles.map((f) => (
            <span
              key={f}
              className="rounded bg-black/18 px-1.5 py-0.5 font-mono text-[9px] text-cyan-400/70"
            >
              {f}
            </span>
          ))}
        </div>
      )}
    </>
  );
};

// ─── مكون توزيع الأنواع ──────────────────────────────────────────

const TYPE_COLORS: Record<string, string> = {
  action: "bg-emerald-500",
  dialogue: "bg-blue-500",
  character: "bg-purple-500",
  scene_header_1: "bg-amber-500",
  scene_header_2: "bg-orange-500",
  scene_header_3: "bg-yellow-500",
  transition: "bg-red-500",
  parenthetical: "bg-pink-500",
  basmala: "bg-teal-500",
};

const TypeDistBar: React.FC<{ dist: Record<string, number> }> = ({ dist }) => {
  const total = Object.values(dist).reduce((a, b) => a + b, 0);
  if (total === 0) return null;
  const entries = Object.entries(dist).sort(([, a], [, b]) => b - a);
  return (
    <div className="space-y-1">
      <div className="flex h-2 gap-px overflow-hidden rounded-full">
        {entries.map(([type, count]) => (
          <div
            key={type}
            className={`${TYPE_COLORS[type] ?? "bg-white/45"} transition-all duration-500`}
            style={{ width: `${(count / total) * 100}%` }}
            title={`${type}: ${count}`}
          />
        ))}
      </div>
      <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-[10px] text-white/45">
        {entries.map(([type, count]) => (
          <span key={type} className="flex items-center gap-1">
            <span
              className={`inline-block h-1.5 w-1.5 rounded-full ${TYPE_COLORS[type] ?? "bg-white/45"}`}
            />
            {type.replace(/_/g, " ")} ({count})
          </span>
        ))}
      </div>
    </div>
  );
};

// ─── المكون الرئيسي ──────────────────────────────────────────────

const KNOWN_STAGES = [
  "schema-style-classify",
  "forward-pass",
  "retroactive",
  "reverse-pass",
  "viterbi",
  "render-first",
  "gemini-context",
  "final-review",
];

export const PipelineMonitor: React.FC<{
  visible: boolean;
  progressiveSurfaceState: ProgressiveSurfaceState | null;
  onDismissFailure: () => void;
  onClose: () => void;
}> = ({ visible, progressiveSurfaceState, onDismissFailure, onClose }) => {
  const [run, setRun] = useState<RunState | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const logRef = useRef<HTMLDivElement>(null);
  const [logEntries, setLogEntries] = useState<string[]>([]);

  const addLog = useCallback((msg: string) => {
    const ts = new Date().toLocaleTimeString("ar-EG", {
      hour12: false,
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    setLogEntries((prev) => [...prev.slice(-60), `[${ts}] ${msg}`]);
  }, []);

  useEffect(() => {
    const unsub = pipelineRecorder.subscribe((event: PipelineEvent) => {
      switch (event.kind) {
        case "run-start":
          setRun({
            runId: event.runId,
            source: event.source,
            inputLines: event.input.lineCount,
            inputChars: event.input.textLength,
            startedAt: performance.now(),
            stages: [],
            aiCorrections: [],
            finished: false,
            totalDurationMs: 0,
            finalTypeDist: {},
          });
          setElapsed(0);
          addLog(
            `▶ بداية run — المصدر: ${event.source} | ${event.input.lineCount} سطر`
          );
          break;

        case "snapshot":
          setRun((prev) => {
            if (!prev) return prev;
            return {
              ...prev,
              stages: [
                ...prev.stages,
                definedProps({
                  stage: event.stage,
                  lineCount: event.lineCount,
                  changes: event.changes,
                  latencyMs: event.latencyMs,
                  timestamp: performance.now(),
                  metadata: event.metadata,
                  activeFiles: event.activeFiles,
                }),
              ],
            };
          });
          addLog(
            `${getStageMeta(event.stage).icon} ${getStageMeta(event.stage).label} — ${event.lineCount} سطر${event.changes > 0 ? ` | ${event.changes} تغيير` : ""}${event.latencyMs > 0 ? ` | ${event.latencyMs}ms` : ""}${event.activeFiles.length > 0 ? `\n    📁 ${event.activeFiles.join(" · ")}` : ""}`
          );
          break;

        case "ai-correction":
          setRun((prev) => {
            if (!prev) return prev;
            return {
              ...prev,
              aiCorrections: [...prev.aiCorrections, event.correction],
            };
          });
          addLog(
            `🤖 تصحيح AI [${event.correction.lineIndex}]: ${event.correction.previousType} → ${event.correction.correctedType} (${event.correction.applied ? "✅" : "❌"})`
          );
          break;

        case "approval":
          addLog(
            `✅ اعتماد النسخة ${event.approval.approvedVersionId} مع ${event.approval.elementCount} عنصر`
          );
          break;

        case "run-end":
          setRun((prev) => {
            if (!prev) return prev;
            return {
              ...prev,
              finished: true,
              totalDurationMs: event.totalDurationMs,
              finalTypeDist: event.finalTypeDist,
            };
          });
          addLog(
            `${event.outcome === "failed-after-visible" ? "⚠️ انتهى مع فشل بعد الظهور" : "✅ اكتمل"} في ${(event.totalDurationMs / 1000).toFixed(1)}s — ${event.totalVerdicts} تصحيح AI`
          );
          break;

        case "run-failure":
          addLog(
            `⛔ فشل المرحلة ${event.stage}: ${event.message}${event.code ? ` [${event.code}]` : ""}`
          );
          break;

        case "engine-bridge":
          addLog(
            `🌉 البريدج — المصدر: ${event.source} | ${event.elementCount} عنصر | ${event.latencyMs}ms`
          );
          break;

        case "file-open":
          addLog(
            `📂 فتح ملف: ${event.fileName} (نوع: ${event.fileType} | وضع: ${event.mode})`
          );
          break;

        case "file-extract-done":
          addLog(
            `📦 استخراج: ${event.fileName} — طريقة: ${event.method}${event.usedOcr ? " (OCR)" : ""} | ${event.textLength} حرف | ${event.schemaElementCount} عنصر schema | ${event.latencyMs}ms`
          );
          break;
      }
    });

    return unsub;
  }, [addLog]);

  // مؤقت الوقت المنقضي
  useEffect(() => {
    if (run && !run.finished) {
      timerRef.current = setInterval(() => {
        setElapsed(Math.round(performance.now() - run.startedAt));
      }, 100);
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [run?.finished, run?.startedAt, run]);

  // Auto-scroll log
  useEffect(() => {
    logRef.current?.scrollTo({
      top: logRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, [logEntries]);

  if (!visible) return null;

  const completedStages = run?.stages.map((s) => s.stage) ?? [];
  const activeStageIndex = run && !run.finished ? completedStages.length : -1;
  const appliedCorrections =
    run?.aiCorrections.filter((c) => c.applied).length ?? 0;

  const downloadLog = () => {
    if (logEntries.length === 0) return;
    const header = run
      ? `Pipeline Run: ${run.runId}\nSource: ${run.source}\nLines: ${run.inputLines} | Chars: ${run.inputChars}\nDuration: ${run.finished ? `${(run.totalDurationMs / 1000).toFixed(1)}s` : "in-progress"}\n${"─".repeat(50)}\n\n`
      : "";
    const blob = new Blob([header + logEntries.join("\n")], {
      type: "text/plain;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `pipeline-log-${new Date().toISOString().slice(0, 19).replace(/:/g, "-")}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div
      ref={panelRef}
      dir="rtl"
      className="fixed bottom-4 left-4 z-[9999] flex max-h-[85vh] w-[420px] flex-col overflow-hidden rounded-[22px] border border-white/8 bg-black/14 shadow-2xl shadow-black/40 backdrop-blur-xl select-none"
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between border-b border-white/8 px-4 py-2.5">
        <div className="flex items-center gap-2">
          <span className="text-base">📡</span>
          <span className="text-sm font-semibold text-white">
            مراقب الـ Pipeline
          </span>
          {run && !run.finished && (
            <span className="animate-pulse text-[10px] text-cyan-400 tabular-nums">
              LIVE
            </span>
          )}
        </div>
        <div className="flex items-center gap-2">
          {run && (
            <span className="text-[10px] text-white/45 tabular-nums">
              {run.finished
                ? `${(run.totalDurationMs / 1000).toFixed(1)}s`
                : `${(elapsed / 1000).toFixed(1)}s`}
            </span>
          )}
          <button
            onClick={downloadLog}
            disabled={logEntries.length === 0}
            className="px-1 text-sm leading-none text-white/45 transition-colors hover:text-white/68 disabled:cursor-not-allowed disabled:opacity-30"
            title="تحميل السجل"
          >
            ⬇
          </button>
          <button
            onClick={onClose}
            className="px-1 text-lg leading-none text-white/45 transition-colors hover:text-white/68"
            title="إغلاق (Ctrl+Shift+M)"
          >
            ✕
          </button>
        </div>
      </div>

      {/* ── Run Info ── */}
      {run ? (
        <div className="space-y-1 border-b border-white/8 px-4 py-2 text-[11px] text-white/45">
          <div className="flex justify-between">
            <span>
              المصدر: <span className="text-white/68">{run.source}</span>
            </span>
            <span>
              {run.inputLines} سطر · {run.inputChars} حرف
            </span>
          </div>
          <ProgressBar
            current={completedStages.length}
            total={KNOWN_STAGES.length}
          />
        </div>
      ) : (
        <div className="px-4 py-6 text-center text-xs text-white/55">
          في انتظار عملية لصق أو استيراد ملف...
        </div>
      )}

      {progressiveSurfaceState?.activeRun?.status === "failed-after-visible" &&
        progressiveSurfaceState.activeRun.failureRecoveryRequired && (
          <div className="border-b border-white/8 bg-black/22 px-4 py-3 text-[11px] text-white/85">
            <div className="font-bold">آخر نسخة صالحة ما زالت ظاهرة</div>
            <div className="mt-1 text-white/68">
              {progressiveSurfaceState.activeRun.latestFailureMessage ??
                "فشل تشغيل لاحق بعد الظهور."}
            </div>
            <button
              type="button"
              onClick={onDismissFailure}
              className="mt-3 rounded-md bg-amber-500 px-3 py-1.5 text-[11px] font-bold text-black transition-colors hover:bg-amber-400"
            >
              إغلاق الفشل وفتح السطح
            </button>
          </div>
        )}

      {/* ── Stages ── */}
      {run && (
        <div className="max-h-[220px] space-y-1 overflow-y-auto border-b border-white/8 px-3 py-2">
          {KNOWN_STAGES.map((stageKey, idx) => {
            const entry = run.stages.find((s) => s.stage === stageKey);
            const isActive = idx === activeStageIndex;
            const isPending = !entry && !run.finished;
            const isSkipped = !entry && run.finished;

            if (entry) {
              return (
                <StageRow
                  key={stageKey}
                  entry={entry}
                  isActive={isActive}
                  isLast={idx === completedStages.length - 1}
                />
              );
            }

            const meta = getStageMeta(stageKey);
            return (
              <div
                key={stageKey}
                className={`flex items-center gap-2 rounded-md px-3 py-1.5 text-xs ${
                  isActive ? "border border-cyan-800/30 bg-cyan-950/30" : ""
                }`}
              >
                <span
                  className={`shrink-0 text-sm ${isPending ? "opacity-30" : "opacity-20"}`}
                >
                  {meta.icon}
                </span>
                <span
                  className={`min-w-[100px] font-medium ${isPending ? "text-white/55" : "text-white/68 line-through"}`}
                >
                  {meta.label}
                </span>
                {isSkipped && (
                  <span className="text-[10px] text-white/68">تخطي</span>
                )}
                {isActive && (
                  <span className="relative ms-auto flex h-2 w-2">
                    <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-cyan-400 opacity-60" />
                    <span className="relative inline-flex h-2 w-2 rounded-full bg-cyan-400" />
                  </span>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* ── AI Corrections Summary ── */}
      {run && run.aiCorrections.length > 0 && (
        <div className="border-b border-white/8 px-4 py-2 text-[11px]">
          <span className="text-white/45">
            تصحيحات AI:{" "}
            <span className="text-emerald-400">{appliedCorrections} مطبّق</span>
            {" · "}
            <span className="text-white/55">
              {run.aiCorrections.length - appliedCorrections} مرفوض
            </span>
          </span>
        </div>
      )}

      {/* ── Type Distribution ── */}
      {run?.finished && Object.keys(run.finalTypeDist).length > 0 && (
        <div className="border-b border-white/8 px-4 py-2">
          <TypeDistBar dist={run.finalTypeDist} />
        </div>
      )}

      {/* ── Live Log ── */}
      <div
        ref={logRef}
        className="max-h-[180px] min-h-[100px] flex-1 space-y-0.5 overflow-y-auto px-3 py-2 font-mono text-[10px] leading-relaxed text-white/45"
      >
        {logEntries.length === 0 ? (
          <div className="py-4 text-center text-white/55">
            السجل فارغ — الصق نص أو افتح ملف
          </div>
        ) : (
          logEntries.map((entry, i) => (
            <div key={i} className="break-all whitespace-pre-wrap">
              {entry}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

"use client";

import React from "react";
import {
  TYPING_MODE_OPTIONS,
  toLiveIdleMinutesLabel,
} from "../../constants/format-mappings";
import type { TypingSystemSettings } from "../../types";

interface SettingsPanelProps {
  typingSystemSettings: TypingSystemSettings;
  onTypingModeChange: (
    nextMode: TypingSystemSettings["typingSystemMode"]
  ) => void;
  onLiveIdleMinutesChange: (nextMinutes: number) => void;
  onRunExportClassified: () => void;
  onRunProcessNow: () => void;
  lockedEditorFontLabel: string;
  lockedEditorSizeLabel: string;
  supportedLegacyFormatCount: number;
  classifierOptionCount: number;
  actionBlockSpacing: string;
  hasFileImportBackend: boolean;
}

/**
 * لوحة الإعدادات الفرعية داخل الشريط الجانبي.
 *
 * إعادة تصميم بصري فقط: تحولت الألوان من داكن/نيون إلى "بطاقة داخل بطاقة"
 * بيضاء دافئة. جميع callbacks (onTypingModeChange، onLiveIdleMinutesChange،
 * onRunExportClassified، onRunProcessNow) والقيم وترتيب العناصر محفوظة
 * بالكامل كما كانت.
 */
export function SettingsPanel({
  typingSystemSettings,
  onTypingModeChange,
  onLiveIdleMinutesChange,
  onRunExportClassified,
  onRunProcessNow,
  lockedEditorFontLabel,
  lockedEditorSizeLabel,
  supportedLegacyFormatCount,
  classifierOptionCount,
  actionBlockSpacing,
  hasFileImportBackend,
}: SettingsPanelProps): React.JSX.Element {
  const activeTypingMode = TYPING_MODE_OPTIONS.find(
    (option) => option.value === typingSystemSettings.typingSystemMode
  );

  return (
    <div className="app-settings-panel mt-3 space-y-4 p-4 text-right">
      <div className="space-y-1.5">
        <label
          className="block text-xs font-semibold text-[color:var(--mf-text-strong)]"
          htmlFor="typing-system-mode"
        >
          وضع نظام الكتابة
        </label>
        <select
          id="typing-system-mode"
          className="app-settings-select w-full px-3 py-2 text-xs outline-none focus:border-[color:var(--mf-accent)]"
          value={typingSystemSettings.typingSystemMode}
          onChange={(event) =>
            onTypingModeChange(
              event.target.value as TypingSystemSettings["typingSystemMode"]
            )
          }
        >
          {TYPING_MODE_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        <p className="text-[11px] text-[color:var(--mf-text-muted)]">
          {activeTypingMode?.description ?? ""}
        </p>
      </div>

      <div className="space-y-1.5">
        <div className="flex items-center justify-between text-[11px] text-[color:var(--mf-text)]">
          <span className="font-semibold">
            {toLiveIdleMinutesLabel(typingSystemSettings.liveIdleMinutes)}
          </span>
          <span className="text-[color:var(--mf-text-muted)]">
            مهلة المعالجة الحية
          </span>
        </div>
        <input
          type="range"
          min={1}
          max={15}
          step={1}
          value={typingSystemSettings.liveIdleMinutes}
          onChange={(event) =>
            onLiveIdleMinutesChange(Number(event.target.value))
          }
          className="w-full accent-[color:var(--mf-accent)]"
        />
        <div className="flex items-center justify-between text-[10px] text-[color:var(--mf-text-faint)]">
          <span>1</span>
          <span>15</span>
        </div>
      </div>

      <button
        type="button"
        className="app-settings-primary w-full px-3 py-2.5 text-xs font-bold focus-visible:ring-2 focus-visible:ring-[color:var(--mf-accent)]/60 focus-visible:outline-none"
        onClick={onRunExportClassified}
      >
        موافقة واعتماد النص (تصدير)
      </button>

      <button
        type="button"
        className="app-settings-secondary w-full px-3 py-2.5 text-xs font-semibold transition-colors focus-visible:ring-2 focus-visible:ring-[color:var(--mf-accent)]/60 focus-visible:outline-none"
        onClick={onRunProcessNow}
      >
        تشغيل المعالجة الآن
      </button>

      <div className="app-settings-info space-y-1.5 px-3 py-2.5 text-[10px]">
        <div className="flex items-center justify-between">
          <span className="font-semibold text-[color:var(--mf-text)]">
            {lockedEditorFontLabel}
          </span>
          <span className="text-[color:var(--mf-text-muted)]">الخط النشط</span>
        </div>
        <div className="flex items-center justify-between">
          <span className="font-semibold text-[color:var(--mf-text)]">
            {lockedEditorSizeLabel}pt
          </span>
          <span className="text-[color:var(--mf-text-muted)]">الحجم النشط</span>
        </div>
        <div className="flex items-center justify-between">
          <span className="font-semibold text-[color:var(--mf-text)]">
            {supportedLegacyFormatCount}
          </span>
          <span className="text-[color:var(--mf-text-muted)]">
            تنسيقات مدعومة
          </span>
        </div>
        <div className="flex items-center justify-between">
          <span className="font-semibold text-[color:var(--mf-text)]">
            {classifierOptionCount}
          </span>
          <span className="text-[color:var(--mf-text-muted)]">
            خيارات التصنيف
          </span>
        </div>
        <div className="flex items-center justify-between">
          <span className="font-semibold text-[color:var(--mf-text)]">
            {actionBlockSpacing}
          </span>
          <span className="text-[color:var(--mf-text-muted)]">
            تباعد الحدث→الحدث
          </span>
        </div>
      </div>

      <div className="space-y-1 text-[10px] text-[color:var(--mf-text-muted)]">
        <div className="flex items-center justify-between">
          <span
            className={`h-2 w-2 rounded-full ${
              hasFileImportBackend
                ? "bg-[color:var(--mf-success)]"
                : "bg-[color:var(--mf-warning)]"
            }`}
            aria-hidden="true"
          />
          <span>
            Backend File Extract:{" "}
            {hasFileImportBackend ? "Configured" : "Not configured"}
          </span>
        </div>
      </div>
    </div>
  );
}

