const createArea = () => {
  const inserted: string[] = [];
  const selections: Array<{ from: number; to: number }> = [];

  const chain = () => ({
    focus: vi.fn().mockReturnThis(),
    insertContent: vi.fn((value: string) => {
      inserted.push(value);
      return chainObject;
    }),
    setTextSelection: vi.fn((range: { from: number; to: number }) => {
