    expect(area.setFormat).toHaveBeenCalledWith("action");
    expect(inserted).toEqual(["وصف الحدث..."]);
    expect(selections).toEqual([
      {
        from: 7,
        to: 7 + "وصف الحدث...".length,
      },
    ]);
    expect(toast).toHaveBeenCalledWith({
      title: "تم الإدراج",
      description: "تم إدراج قالب الوصف/الحركة.",
    });
  });
});

