/**
 * @module extensions/line-repair
 * @description
 * أدوات إصلاح النصوص الملصوقة — تنظيف HTML وعلامات الترقيم ودمج الأسطر المكسورة.
 *
 * يُصدّر:
 * - {@link extractPlainTextFromHtmlLikeLine} — استخراج نص عادي من سطر يحتوي وسوم HTML
 * - {@link parseBulletLine} — تنظيف سطر من HTML + علامات نقطية + تطبيع
 * - {@link shouldMergeWrappedLines} — يحدد إذا كان سطران حوار متتاليان يجب دمجهما
 * - {@link mergeBrokenCharacterName} — يدمج اسم شخصية مقسوم على سطرين (شائع في Word/PDF)
 *
 * يُستهلك في {@link PasteClassifier} أثناء المعالجة المسبقة للنص الملصوق.
 */
import type { ElementType } from "./classification-types";
import { CHARACTER_RE } from "./arabic-patterns";
import {
  hasActionVerbStructure,
  isActionVerbStart,
  matchesActionStartPattern,
  normalizeLine,
  stripLeadingBullets,
} from "./text-utils";
import { pipelineRecorder } from "./pipeline-recorder";

/** نمط regex لمطابقة وسوم HTML */
const HTML_TAG_RE = /<[^>]+>/g;

/**
 * يستخرج نصاً عادياً من سطر يحتوي وسوم HTML.
 *
 * يستبدل كل وسم بمسافة ثم يطبّع المسافات المتعددة.
 * إذا لم يحتوِ السطر على `<` أو `>` يُعيده كما هو.
 *
 * @param line - السطر الخام (قد يحتوي HTML)
 * @returns النص العادي بدون وسوم
 */
export const extractPlainTextFromHtmlLikeLine = (line: string): string => {
  const raw = (line ?? "").trim();
  if (!raw || !/[<>]/.test(raw)) return raw;

  return raw
    .replace(HTML_TAG_RE, " ")
    .replace(/\u00A0/g, " ")
    .replace(/\s+/g, " ")
    .trim();
};

/**
 * ينظّف سطراً من HTML ثم يزيل العلامات النقطية ويطبّعه.
 *
 * سلسلة المعالجة: HTML → نص عادي → إزالة نقاط → تطبيع.
 *
 * @param line - السطر الخام
 * @returns النص المُنظّف والمُطبّع
 */
export const parseBulletLine = (line: string): string => {
  const plain = extractPlainTextFromHtmlLikeLine(line);
  return normalizeLine(stripLeadingBullets(plain));
};

/**
 * أفعال وصفية/حركية تمنع دمج السطر في حوار عند ظهورها بعد "ثم".
 * القائمة قابلة للتوسيع حسب الحاجة.
 */
const ACTION_VERBS_AFTER_THUMMA: readonly string[] = [
  "يخرج",
  "يدخل",
  "ينهض",
  "يلتفت",
  "يرفع",
  "يفتح",
  "يغلق",
  "يمشي",
  "يجلس",
  "يقف",
  "ينظر",
  "يشير",
  "يضع",
  "يسحب",
  "يمسك",
  "يأخذ",
  "يرمي",
  "يركض",
  "يقفز",
  "يسقط",
  "يصعد",
  "ينزل",
  "يتحرك",
  "يتوقف",
  "يبتعد",
  "يقترب",
  "يتراجع",
  "يهرب",
  "يعود",
  "يتقدم",
  "يدور",
  "يستدير",
  "يتجه",
  "تخرج",
  "تدخل",
  "تنهض",
  "تلتفت",
  "ترفع",
  "تفتح",
  "تغلق",
  "تمشي",
  "تجلس",
  "تقف",
  "تنظر",
  "تشير",
  "تضع",
  "تسحب",
];

const THUMMA_ACTION_RE = new RegExp(
  `^ثم\\s+(?:${ACTION_VERBS_AFTER_THUMMA.join("|")})`,
  "u"
);

/**
 * دمج التفاف السطر للحوار فقط عندما يبدو استكمالًا لنفس الجملة.
 */
/**
 * يحدد إذا كان سطرا حوار متتاليان يجب دمجهما كاستمرار لنفس الجملة.
 *
 * شروط الدمج:
 * 1. السطر السابق كان `dialogue`
 * 2. لا يبدأ أي منهما بشرطة أو نقطة
 * 3. السطر الحالي لا ينتهي بنقطتين (ليس اسم شخصية)
 * 4. السطر الحالي يبدأ بعلامة استمرار (`…`، `،`، `و`، `ثم`)
 * 5. السطر السابق لم ينتهِ بعلامة نهاية جملة
 *
 * @param previousLine - السطر السابق
 * @param currentLine - السطر الحالي
 * @param previousType - نوع السطر السابق
 * @returns `true` إذا يجب دمج السطرين
 */
export const shouldMergeWrappedLines = (
  previousLine: string,
  currentLine: string,
  previousType?: ElementType
): boolean => {
  const prev = normalizeLine(previousLine);
  const curr = normalizeLine(currentLine);
  if (!prev || !curr) return false;
  if (previousType !== "dialogue") return false;
  if (/^[-–—•●○]/.test(prev) || /^[-–—•●○]/.test(curr)) return false;
  if (/[:：]\s*$/.test(curr)) return false;

  const prevEndsSentence = /[.!?؟…»"]\s*$/.test(prev);
  const startsAsContinuation = /^(?:\.{3}|…|،|(?:و|ثم)\s+)/.test(curr);
  if (!startsAsContinuation || prevEndsSentence) return false;

  // منع الدمج إذا كان "ثم" متبوعاً بفعل وصفي/حركي — هذا أكشن وليس استكمال حوار
  if (THUMMA_ACTION_RE.test(curr)) return false;

  return true;
};

/**
 * يحاول دمج اسم شخصية منقسم على سطرين (حالة شائعة في نسخ Word/PDF).
 */
/**
 * يدمج اسم شخصية مقسوم على سطرين — حالة شائعة في نسخ Word/PDF.
 *
 * شروط الدمج:
 * 1. السطر السابق لا ينتهي بعلامة نهاية جملة
 * 2. السطر الحالي ينتهي بنقطتين
 * 3. كل جزء ≤ 25 حرفاً والمجموع ≤ 32
 * 4. الاسم المدمج يتطابق مع {@link CHARACTER_RE}
 * 5. لا يحتوي على علامات ترقيم غير مسموحة
 *
 * @param previousLine - السطر السابق (الجزء الأول من الاسم)
 * @param currentLine - السطر الحالي (الجزء الثاني + النقطتين)
 * @returns الاسم المدمج مع النقطتين، أو `null` إذا فشل الدمج
 *
 * @example
 * ```ts
 * mergeBrokenCharacterName('عبد', 'الرحمن:')  // 'عبد الرحمن:'
 * mergeBrokenCharacterName('جملة طويلة.', 'أحمد:') // null
 * ```
 */
export const mergeBrokenCharacterName = (
  previousLine: string,
  currentLine: string
): string | null => {
  pipelineRecorder.trackFile("line-repair.ts");
  const prevRaw = parseBulletLine(previousLine);
  const currRaw = parseBulletLine(currentLine);

  if (!prevRaw || !currRaw) return null;
  if (/[.!؟"]$/.test(prevRaw)) return null;
  if (!/[:：]\s*$/.test(currRaw)) return null;

  const prevNamePart = prevRaw.replace(/[:：]+\s*$/, "").trim();
  const currNamePart = currRaw.replace(/[:：]+\s*$/, "").trim();
  if (!prevNamePart || !currNamePart) return null;

  // اسم شخصية مقسوم مستحيل يكون أكثر من 3 كلمات في الجزء الأول
  if (prevNamePart.split(/\s+/).filter(Boolean).length > 3) return null;
  if (currNamePart.split(/\s+/).filter(Boolean).length > 3) return null;

  // لو الجزء الأول فيه أفعال أو بنية سردية → ده نص سردي مش اسم
  if (
    isActionVerbStart(prevNamePart) ||
    matchesActionStartPattern(prevNamePart) ||
    hasActionVerbStructure(prevNamePart)
  ) {
    return null;
  }

  if (prevNamePart.length > 25) return null;
  if (prevNamePart.length + currNamePart.length > 32) return null;

  const directMerge = `${prevNamePart}${currNamePart}`;
  const spaceMerge = `${prevNamePart} ${currNamePart}`;

  if (CHARACTER_RE.test(`${directMerge}:`) && !/[.!؟,،"«»]/.test(directMerge)) {
    return `${directMerge}:`;
  }

  if (CHARACTER_RE.test(`${spaceMerge}:`) && !/[.!؟,،"«»]/.test(spaceMerge)) {
    return `${spaceMerge}:`;
  }

  return null;
};

/**
 * @module extensions/local-weight-learner
 * @description
 * معايرة خفيفة للأوزان — تتعلم من تصحيحات المستخدم في نفس الجلسة.
 *
 * مش RL كامل — مجرد deltas تُضاف على الأوزان الثابتة:
 * - لو المستخدم صحّح dialogue → action مرتين → الـ action evidence بيزيد وزنها
 * - لو المستخدم صحّح action → dialogue → الـ dialogue cues بتزيد وزنها
 *
 * الأوزان بتنتهي مع الجلسة (مفيش persistence — الجلسة الجاية بتبدأ من الصفر).
 *
 * يُصدّر:
 * - {@link WeightDeltas} — الـ deltas الحالية
 * - {@link LocalWeightLearner} — الفئة الرئيسية
 *
 * يُستهلك في: paste-classifier (عند التصنيف) + EditorArea (عند تصحيح المستخدم).
 */

import { logger } from "../utils/logger";
import type { ElementType } from "./classification-types";

const learnerLogger = logger.createScope("weight-learner");

// ─── الأنواع ──────────────────────────────────────────────────────

/** الـ deltas اللي بتنطبق على الأوزان الثابتة */
export interface WeightDeltas {
  /** bonus/penalty لـ action evidence score */
  readonly actionEvidenceBonus: number;
  /** bonus/penalty لـ dialogue evidence score */
  readonly dialogueEvidenceBonus: number;
  /** bonus/penalty لـ context weight (recency) */
  readonly contextRecencyBonus: number;
  /** عدد التصحيحات اللي اتعلمنا منها */
  readonly correctionCount: number;
}

/** تصحيح مستخدم واحد */
export interface UserCorrection {
  readonly lineText: string;
  readonly fromType: ElementType;
  readonly toType: ElementType;
  readonly lineIndex: number;
}

// ─── ثوابت ─────────────────────────────────────────────────────────

/** أقصى delta مسموح (عشان ما يطغاش على الأوزان الأصلية) */
const MAX_DELTA = 3.0;

/** حجم خطوة التعلم */
const LEARNING_RATE = 0.5;

/** أقل عدد تصحيحات عشان الـ deltas تبدأ تأثر */
const MIN_CORRECTIONS_TO_ACTIVATE = 2;

// ─── الفئة الرئيسية ──────────────────────────────────────────────

export class LocalWeightLearner {
  private _actionBonus = 0;
  private _dialogueBonus = 0;
  private _contextBonus = 0;
  private _correctionCount = 0;

  /**
   * تسجيل تصحيح مستخدم — يحدّث الـ deltas.
   *
   * @param correction - التصحيح (من أي نوع → لأي نوع)
   */
  recordCorrection(correction: UserCorrection): void {
    const { fromType, toType } = correction;

    // تصحيح dialogue → action: الـ action evidence كان لازم يكون أقوى
    if (fromType === "dialogue" && toType === "action") {
      this._actionBonus = clamp(
        this._actionBonus + LEARNING_RATE,
        -MAX_DELTA,
        MAX_DELTA
      );
      this._dialogueBonus = clamp(
        this._dialogueBonus - LEARNING_RATE * 0.5,
        -MAX_DELTA,
        MAX_DELTA
      );
    }

    // تصحيح action → dialogue: الـ dialogue cues كان لازم تكون أقوى
    if (fromType === "action" && toType === "dialogue") {
      this._dialogueBonus = clamp(
        this._dialogueBonus + LEARNING_RATE,
        -MAX_DELTA,
        MAX_DELTA
      );
      this._actionBonus = clamp(
        this._actionBonus - LEARNING_RATE * 0.5,
        -MAX_DELTA,
        MAX_DELTA
      );
    }

    // تصحيح action/dialogue → character: الـ context كان لازم يكون أقوى
    if (
      toType === "character" &&
      (fromType === "action" || fromType === "dialogue")
    ) {
      this._contextBonus = clamp(
        this._contextBonus + LEARNING_RATE * 0.3,
        -MAX_DELTA,
        MAX_DELTA
      );
    }

    // تصحيح character → action/dialogue: الـ context كان مضلل
    if (
      fromType === "character" &&
      (toType === "action" || toType === "dialogue")
    ) {
      this._contextBonus = clamp(
        this._contextBonus - LEARNING_RATE * 0.3,
        -MAX_DELTA,
        MAX_DELTA
      );
    }

    this._correctionCount++;

    learnerLogger.info("correction-recorded", {
      fromType,
      toType,
      actionBonus: this._actionBonus.toFixed(2),
      dialogueBonus: this._dialogueBonus.toFixed(2),
      contextBonus: this._contextBonus.toFixed(2),
      totalCorrections: this._correctionCount,
    });
  }

  /**
   * الـ deltas الحالية — بتتطبق على أوزان التصنيف.
   *
   * بترجع أصفار لو عدد التصحيحات < الحد الأدنى (عشان تصحيح واحد ما يأثرش).
   */
  getDeltas(): WeightDeltas {
    if (this._correctionCount < MIN_CORRECTIONS_TO_ACTIVATE) {
      return {
        actionEvidenceBonus: 0,
        dialogueEvidenceBonus: 0,
        contextRecencyBonus: 0,
        correctionCount: this._correctionCount,
      };
    }

    return {
      actionEvidenceBonus: this._actionBonus,
      dialogueEvidenceBonus: this._dialogueBonus,
      contextRecencyBonus: this._contextBonus,
      correctionCount: this._correctionCount,
    };
  }

  /** إعادة تعيين الأوزان (بداية جلسة جديدة) */
  reset(): void {
    this._actionBonus = 0;
    this._dialogueBonus = 0;
    this._contextBonus = 0;
    this._correctionCount = 0;
  }
}

// ─── أداة مساعدة ──────────────────────────────────────────────────

const clamp = (value: number, min: number, max: number): number =>
  Math.max(min, Math.min(max, value));

/**
 * @module extensions/parenthetical
 * @description
 * عنصر الإرشاد التمثيلي (Parenthetical) — توجيهات أداء الممثل داخل الحوار.
 *
 * يُصدّر:
 * - {@link isParentheticalLine} — كاشف أسطر الإرشاد التمثيلي (أقواس عربية/لاتينية)
 * - {@link Parenthetical} — عقدة Tiptap للإرشاد التمثيلي
 *
 * سلوك Enter: الانتقال إلى {@link Dialogue} (حوار).
 */
import { Node, mergeAttributes } from "@tiptap/core";
import { PARENTHETICAL_RE } from "./arabic-patterns";
import { buildProgressiveNodeAttributes } from "./shared-node-attrs";
import { normalizeLine } from "./text-utils";

/**
 * يفحص ما إذا كان السطر إرشاداً تمثيلياً محاطاً بأقواس.
 *
 * @param text - النص الخام للسطر
 * @returns `true` إذا طابق {@link PARENTHETICAL_RE}
 */
export const isParentheticalLine = (text: string): boolean => {
  const normalized = normalizeLine(text);
  return PARENTHETICAL_RE.test(normalized);
};

/**
 * الإرشاد التمثيلي (Parenthetical)
 * توجيهات أداء داخل الحوار
 */
export const Parenthetical = Node.create({
  name: "parenthetical",
  group: "block",
  content: "inline*",
  defining: true,

  addAttributes() {
    return buildProgressiveNodeAttributes();
  },

  parseHTML() {
    return [{ tag: 'div[data-type="parenthetical"]' }];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(HTMLAttributes, {
        "data-type": "parenthetical",
        class: "screenplay-parenthetical",
      }),
      0,
    ];
  },

  addKeyboardShortcuts() {
    return {
      Enter: ({ editor }) => {
        if (!editor.isActive("parenthetical")) return false;
        return editor.chain().focus().splitBlock().setDialogue().run();
      },
    };
  },
});

