type DebugWindow = Window & {
  __diagnosePipeline?: unknown;
  __showPipelineRun?: unknown;
  __showLineJourney?: unknown;
  __pipelineRecorderUiRegistered?: boolean;
};

const resetDebugWindow = (): void => {
  const debugWindow = window as DebugWindow;
  delete debugWindow.__diagnosePipeline;
  delete debugWindow.__showPipelineRun;
  delete debugWindow.__showLineJourney;
  delete debugWindow.__pipelineRecorderUiRegistered;
};

afterEach(() => {
  localStorage.clear();
  vi.restoreAllMocks();
  resetDebugWindow();
});

describe("pipeline debug registration", () => {
  it("يخفي رسائل الجاهزية افتراضيًا مع بقاء الأدوات اليدوية", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    registerPipelineRecorderUI();
    registerPipelineDiagnostics(() => "سطر تجريبي");

    const debugWindow = window as DebugWindow;
    expect(typeof debugWindow.__showPipelineRun).toBe("function");
    expect(typeof debugWindow.__showLineJourney).toBe("function");
    expect(typeof debugWindow.__diagnosePipeline).toBe("function");
    expect(warnSpy).not.toHaveBeenCalled();
  });
});

/**
 * @module pipeline-diagnostics
 * @description أداة تشخيص تلقائية — تشغّل الـ pipeline بكل تركيبة flags
 *   وتقارن النتايج مع الـ baseline في ضربة واحدة.
 *
 *   الاستخدام من الـ console:
 *     window.__diagnosePipeline()          // يستخدم النص الموجود في المحرر
 *     window.__diagnosePipeline(myText)    // يستخدم نص مخصص
 */
import {
  classifyLines,
  PIPELINE_FLAGS,
  type ClassifyLinesContext,
} from "./paste-classifier";
import type { ClassifiedDraftWithId } from "./paste-classifier-helpers";
import { registerPipelineRecorderUI } from "./pipeline-recorder";

// ─── أنواع التقرير ────────────────────────────────────────────────

type FlagKey = keyof typeof PIPELINE_FLAGS;

interface LayerDiff {
  lineIndex: number;
  text: string;
  baselineType: string;
  variantType: string;
  baselineConfidence: number;
  variantConfidence: number;
}

interface LayerReport {
  flag: FlagKey;
  totalLines: number;
  changedLines: number;
  changeRate: string;
  diffs: LayerDiff[];
  typeDistDelta: Record<string, number>;
}

interface DiagnosticReport {
  timestamp: string;
  inputLines: number;
  baselineTypeDist: Record<string, number>;
  layers: LayerReport[];
  /** الطبقات مرتبة من الأكثر تأثير للأقل */
  ranking: { flag: FlagKey; changedLines: number; changeRate: string }[];
  /** تركيبة كل الطبقات مع بعض */
  allOnReport: LayerReport;
}

// ─── دوال مساعدة ──────────────────────────────────────────────────

const ALL_FLAGS: FlagKey[] = [
  "DCG_ENABLED",
  "SELF_REFLECTION_ENABLED",
  "RETRO_NEW_PATTERNS_ENABLED",
  "REVERSE_PASS_ENABLED",
  "VITERBI_OVERRIDE_ENABLED",
];

/** حفظ الحالة الحالية واسترجاعها */
const snapshotFlags = (): Record<FlagKey, boolean> => ({ ...PIPELINE_FLAGS });

const restoreFlags = (snapshot: Record<FlagKey, boolean>): void => {
  for (const key of ALL_FLAGS) {
    (PIPELINE_FLAGS as Record<FlagKey, boolean>)[key] = snapshot[key];
  }
};

const setAllFlags = (value: boolean): void => {
  for (const key of ALL_FLAGS) {
    (PIPELINE_FLAGS as Record<FlagKey, boolean>)[key] = value;
  }
};

const typeDist = (
  classified: readonly ClassifiedDraftWithId[]
): Record<string, number> => {
  const dist: Record<string, number> = {};
  for (const item of classified) {
    dist[item.type] = (dist[item.type] ?? 0) + 1;
  }
  return dist;
};

const diffClassified = (
  baseline: readonly ClassifiedDraftWithId[],
  variant: readonly ClassifiedDraftWithId[]
): LayerDiff[] => {
  const diffs: LayerDiff[] = [];
  const len = Math.max(baseline.length, variant.length);
  for (let i = 0; i < len; i++) {
    const b = baseline[i];
    const v = variant[i];
    if (!b || !v) {
      diffs.push({
        lineIndex: i,
        text: (b?.text ?? v?.text ?? "").slice(0, 60),
        baselineType: b?.type ?? "—",
        variantType: v?.type ?? "—",
        baselineConfidence: b?.confidence ?? 0,
        variantConfidence: v?.confidence ?? 0,
      });
      continue;
    }
    if (b.type !== v.type) {
      diffs.push({
        lineIndex: i,
        text: b.text.slice(0, 60),
        baselineType: b.type,
        variantType: v.type,
        baselineConfidence: b.confidence,
        variantConfidence: v.confidence,
      });
    }
  }
  return diffs;
};

const typeDistDelta = (
  baselineDist: Record<string, number>,
  variantDist: Record<string, number>
): Record<string, number> => {
  const allTypes = new Set([
    ...Object.keys(baselineDist),
    ...Object.keys(variantDist),
  ]);
  const delta: Record<string, number> = {};
  for (const t of allTypes) {
    const d = (variantDist[t] ?? 0) - (baselineDist[t] ?? 0);
    if (d !== 0) delta[t] = d;
  }
  return delta;
};

// ─── المحرك الرئيسي ──────────────────────────────────────────────

const runWithFlags = (
  text: string,
  ctx?: ClassifyLinesContext
): ClassifiedDraftWithId[] => {
  return classifyLines(text, ctx);
};

/**
 * يشغّل التشخيص الكامل ويرجع تقرير مفصّل.
 */
export const diagnosePipeline = (
  text: string,
  ctx?: ClassifyLinesContext
): DiagnosticReport => {
  const saved = snapshotFlags();

  try {
    // ── 1) Baseline: كل الطبقات OFF ──
    setAllFlags(false);
    const baseline = runWithFlags(text, ctx);
    const baselineDist = typeDist(baseline);

    // ── 2) كل طبقة لوحدها ──
    const layers: LayerReport[] = [];
    for (const flag of ALL_FLAGS) {
      setAllFlags(false);
      (PIPELINE_FLAGS as Record<FlagKey, boolean>)[flag] = true;

      const variant = runWithFlags(text, ctx);
      const diffs = diffClassified(baseline, variant);
      const vDist = typeDist(variant);

      layers.push({
        flag,
        totalLines: variant.length,
        changedLines: diffs.length,
        changeRate:
          baseline.length > 0
            ? ((diffs.length / baseline.length) * 100).toFixed(1) + "%"
            : "0%",
        diffs,
        typeDistDelta: typeDistDelta(baselineDist, vDist),
      });
    }

    // ── 3) كل الطبقات ON مع بعض ──
    setAllFlags(true);
    const allOn = runWithFlags(text, ctx);
    const allOnDiffs = diffClassified(baseline, allOn);
    const allOnDist = typeDist(allOn);
    const allOnReport: LayerReport = {
      flag: "ALL_ON" as FlagKey,
      totalLines: allOn.length,
      changedLines: allOnDiffs.length,
      changeRate:
        baseline.length > 0
          ? ((allOnDiffs.length / baseline.length) * 100).toFixed(1) + "%"
          : "0%",
      diffs: allOnDiffs,
      typeDistDelta: typeDistDelta(baselineDist, allOnDist),
    };

    // ── 4) ترتيب الطبقات بالتأثير ──
    const ranking = layers
      .map((l) => ({
        flag: l.flag,
        changedLines: l.changedLines,
        changeRate: l.changeRate,
      }))
      .sort((a, b) => b.changedLines - a.changedLines);

    return {
      timestamp: new Date().toISOString(),
      inputLines: baseline.length,
      baselineTypeDist: baselineDist,
      layers,
      ranking,
      allOnReport,
    };
  } finally {
    restoreFlags(saved);
  }
};

// ─── عرض التقرير في الـ console ────────────────────────────────────

const printReport = (report: DiagnosticReport): void => {
  console.warn(
    "%c╔══════════════════════════════════════════════════════╗",
    "color: #00ff88; font-weight: bold"
  );
  console.warn(
    "%c║      🔬 Pipeline Layer Diagnostics Report           ║",
    "color: #00ff88; font-weight: bold"
  );
  console.warn(
    "%c╚══════════════════════════════════════════════════════╝",
    "color: #00ff88; font-weight: bold"
  );

  console.warn(`\n📊 Baseline: ${report.inputLines} lines`);

  console.table(report.baselineTypeDist);

  console.warn(
    "\n%c🏆 Layer Impact Ranking (من الأكثر تأثير للأقل):",
    "color: #ffcc00; font-weight: bold"
  );

  console.table(
    report.ranking.map((r) => ({
      "🏷️ Layer": r.flag,
      "📐 Changed Lines": r.changedLines,
      "📊 Change Rate": r.changeRate,
    }))
  );

  // تفاصيل كل طبقة
  for (const layer of report.layers) {
    if (layer.changedLines === 0) {
      console.warn(`\n✅ ${layer.flag}: لا تغيير`);
      continue;
    }

    console.warn(
      `\n%c⚠️ ${layer.flag}: ${layer.changedLines} lines changed (${layer.changeRate})`,
      "color: #ff6b6b; font-weight: bold"
    );

    if (Object.keys(layer.typeDistDelta).length > 0) {
      console.warn("   Type distribution delta:");

      console.table(layer.typeDistDelta);
    }

    // أول 10 تغييرات كمثال
    const sample = layer.diffs.slice(0, 10);

    console.table(
      sample.map((d) => ({
        "Line#": d.lineIndex,
        Text: d.text.slice(0, 40),
        Baseline: d.baselineType,
        "→ Variant": d.variantType,
        "Δ Conf":
          d.variantConfidence - d.baselineConfidence > 0
            ? `+${d.variantConfidence - d.baselineConfidence}`
            : `${d.variantConfidence - d.baselineConfidence}`,
      }))
    );
    if (layer.diffs.length > 10) {
      console.warn(`   ... و ${layer.diffs.length - 10} تغيير تاني`);
    }
  }

  // ALL ON
  console.warn(
    `\n%c🔥 ALL LAYERS ON: ${report.allOnReport.changedLines} lines changed (${report.allOnReport.changeRate})`,
    "color: #ff00ff; font-weight: bold"
  );
  if (report.allOnReport.diffs.length > 0) {
    console.table(
      report.allOnReport.diffs.slice(0, 15).map((d) => ({
        "Line#": d.lineIndex,
        Text: d.text.slice(0, 40),
        Baseline: d.baselineType,
        "→ All ON": d.variantType,
      }))
    );
  }

  console.warn("\n%c─── Full report object: ───", "color: #888");
  console.warn(report);
};

// ─── ربط بالـ window للاستخدام من الـ console ──────────────────────

const isPipelineConsoleDebugEnabled = (): boolean => {
  if (typeof window === "undefined") return false;
  try {
    return window.localStorage.getItem("filmlane.pipeline.debug") === "true";
  } catch {
    return false;
  }
};

/**
 * يسجّل `window.__diagnosePipeline` و `window.__lastDiagReport`.
 *
 * @param getEditorText - دالة ترجع النص الحالي من المحرر
 */
export const registerPipelineDiagnostics = (
  getEditorText: () => string
): void => {
  if (typeof window === "undefined") return;

  const win = window as unknown as Record<string, unknown>;

  win["__diagnosePipeline"] = (
    customText?: string,
    ctx?: ClassifyLinesContext
  ): DiagnosticReport => {
    const text = customText ?? getEditorText();
    if (!text.trim()) {
      console.warn("⚠️ مفيش نص — افتح ملف الأول أو مرّر نص كـ argument");
      return {} as DiagnosticReport;
    }

    console.warn(`🔬 Running diagnostics on ${text.length} chars...`);
    const t0 = performance.now();
    const report = diagnosePipeline(text, ctx);
    const elapsed = (performance.now() - t0).toFixed(0);
    console.warn(`⏱️ Done in ${elapsed}ms\n`);

    printReport(report);
    win["__lastDiagReport"] = report;
    return report;
  };

  // ── تسجيل أدوات الـ Pipeline Recorder (رادار شامل) ──
  registerPipelineRecorderUI();

  if (isPipelineConsoleDebugEnabled()) {
    console.warn(
      "%c🔬 Pipeline diagnostics ready! Run: __diagnosePipeline()",
      "color: #00ff88; font-weight: bold; font-size: 13px"
    );
  }
};

/**
 * @module extensions/pipeline-recorder
 * @description
 * رادار شامل — يسجّل كل مراحل الـ pipeline من لحظة اللصق حتى آخر تصحيح AI.
 *
 * يأخذ snapshot في كل مرحلة ويحسب الـ diffs بين كل مرحلتين متتاليتين.
 * يسجّل تصحيحات AI بشكل فردي (applied/skipped).
 *
 * الاستخدام من الـ console:
 *   window.__showPipelineRun()        // تقرير مُنسّق بالجداول
 *   window.__showLineJourney(15)      // رحلة سطر واحد عبر كل المراحل
 *   window.__lastPipelineRun          // الـ raw data
 *
 * يُصدّر:
 * - {@link pipelineRecorder} — الـ singleton
 * - {@link registerPipelineRecorderUI} — ربط بالـ window
 */

import { definedProps } from "@/lib/defined-props";

type PipelineRecorderDebugWindow = Window & {
  __lastPipelineRun?: PipelineRunReport | null;
  __showPipelineRun?: () => void;
  __showLineJourney?: (lineIndex: number) => void;
  __pipelineRecorderUiRegistered?: boolean;
};

const isPipelineConsoleDebugEnabled = (): boolean => {
  if (typeof window === "undefined") return false;
  try {
    return window.localStorage.getItem("filmlane.pipeline.debug") === "true";
  } catch {
    return false;
  }
};

// ─── الأنواع ──────────────────────────────────────────────────────

/** سطر واحد في snapshot (خفيف — بدون النص الكامل) */
export interface SnapshotLine {
  readonly type: string;
  readonly confidence: number;
  readonly method: string;
  readonly text: string; // أول 50 حرف
}

/** snapshot لمرحلة واحدة */
export interface PipelineSnapshot {
  readonly stage: string;
  readonly timestamp: number; // performance.now()
  readonly lines: readonly SnapshotLine[];
  readonly metadata?: Record<string, unknown>;
}

/** تغيير سطر بين مرحلتين */
export interface LineChange {
  readonly lineIndex: number;
  readonly text: string;
  readonly fromType: string;
  readonly toType: string;
  readonly confidenceDelta: number;
}

/** diff بين مرحلتين متتاليتين */
export interface StageDiff {
  readonly fromStage: string;
  readonly toStage: string;
  readonly latencyMs: number;
  readonly changes: readonly LineChange[];
}

/** تصحيح AI مسجّل */
export interface RecordedAICorrection {
  readonly lineIndex: number;
  readonly text: string;
  readonly previousType: string;
  readonly correctedType: string;
  readonly confidence: number;
  readonly source: string;
  readonly applied: boolean;
  readonly reason?: string;
}

export interface RecordedApproval {
  readonly runId: string;
  readonly approvedVersionId: string;
  readonly replacesVersionId: string | null;
  readonly elementCount: number;
  readonly approvedAt: string;
}

/** تقرير run كامل */
export interface PipelineRunReport {
  readonly runId: string;
  readonly source: string;
  readonly sourceType?: string;
  readonly intakeKind?: "paste" | "file-open";
  readonly fileName?: string | null;
  readonly startTime: number;
  endTime: number;
  totalDurationMs: number;
  readonly input: { textLength: number; lineCount: number };
  readonly snapshots: PipelineSnapshot[];
  readonly diffs: StageDiff[];
  readonly aiCorrections: RecordedAICorrection[];
  readonly approvals: RecordedApproval[];
  finalTypeDist: Record<string, number>;
  failure?: {
    stage: string;
    message: string;
    code?: string;
  };
}

// ─── Snapshot Line Builder ────────────────────────────────────────

const toSnapshotLine = (item: {
  type: string;
  text: string;
  confidence: number;
  classificationMethod?: string;
}): SnapshotLine => ({
  type: item.type,
  confidence: item.confidence,
  method: item.classificationMethod ?? "unknown",
  text: item.text.slice(0, 50),
});

// ─── Diff Engine ──────────────────────────────────────────────────

const computeDiff = (
  from: PipelineSnapshot,
  to: PipelineSnapshot
): StageDiff => {
  const changes: LineChange[] = [];
  const len = Math.max(from.lines.length, to.lines.length);

  for (let i = 0; i < len; i++) {
    const f = from.lines[i];
    const t = to.lines[i];
    if (!f || !t) {
      // سطر مضاف أو محذوف
      changes.push({
        lineIndex: i,
        text: (f?.text ?? t?.text ?? "").slice(0, 50),
        fromType: f?.type ?? "—",
        toType: t?.type ?? "—",
        confidenceDelta: (t?.confidence ?? 0) - (f?.confidence ?? 0),
      });
      continue;
    }
    if (f.type !== t.type) {
      changes.push({
        lineIndex: i,
        text: f.text,
        fromType: f.type,
        toType: t.type,
        confidenceDelta: t.confidence - f.confidence,
      });
    }
  }

  return {
    fromStage: from.stage,
    toStage: to.stage,
    latencyMs: Math.round(to.timestamp - from.timestamp),
    changes,
  };
};

// ─── Type Distribution ────────────────────────────────────────────

const computeTypeDist = (
  lines: readonly SnapshotLine[]
): Record<string, number> => {
  const dist: Record<string, number> = {};
  for (const line of lines) {
    dist[line.type] = (dist[line.type] ?? 0) + 1;
  }
  return dist;
};

// ─── Event Bus ────────────────────────────────────────────────────

export type PipelineEvent =
  | {
      kind: "run-start";
      runId: string;
      source: string;
      sourceType?: string;
      intakeKind?: "paste" | "file-open";
      fileName?: string | null;
      input: { textLength: number; lineCount: number };
    }
  | {
      kind: "snapshot";
      stage: string;
      lineCount: number;
      changes: number;
      latencyMs: number;
      metadata?: Record<string, unknown>;
      activeFiles: string[];
    }
  | { kind: "ai-correction"; correction: RecordedAICorrection }
  | { kind: "approval"; approval: RecordedApproval }
  | {
      kind: "run-failure";
      stage: string;
      message: string;
      code?: string;
    }
  | {
      kind: "run-end";
      totalDurationMs: number;
      totalVerdicts: number;
      finalTypeDist: Record<string, number>;
      outcome: "settled" | "failed-after-visible";
    }
  | {
      kind: "engine-bridge";
      source: string;
      elementCount: number;
      latencyMs: number;
    }
  | { kind: "file-open"; fileName: string; fileType: string; mode: string }
  | {
      kind: "file-extract-done";
      fileName: string;
      method: string;
      usedOcr: boolean;
      textLength: number;
      schemaElementCount: number;
      latencyMs: number;
    };

type PipelineEventListener = (event: PipelineEvent) => void;

// ─── الفئة الرئيسية ──────────────────────────────────────────────

class PipelineRecorder {
  private _currentRun: PipelineRunReport | null = null;
  private _lastCompletedRun: PipelineRunReport | null = null;
  private readonly _listeners = new Set<PipelineEventListener>();
  private readonly _trackedFiles = new Set<string>();

  subscribe(listener: PipelineEventListener): () => void {
    this._listeners.add(listener);
    return () => {
      this._listeners.delete(listener);
    };
  }

  private _emit(event: PipelineEvent): void {
    for (const listener of this._listeners) {
      try {
        listener(event);
      } catch {
        /* سلامة — لا نوقف الـ pipeline بسبب خطأ UI */
      }
    }
  }

  /**
   * بداية run جديد — يُستدعى عند أول مرحلة في الـ pipeline.
   */
  startRun(
    source: string,
    input: { textLength: number; lineCount: number },
    metadata?: {
      sourceType?: string;
      intakeKind?: "paste" | "file-open";
      fileName?: string | null;
    }
  ): void {
    const runId = `run-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    this._currentRun = {
      runId,
      source,
      fileName: metadata?.fileName ?? null,
      startTime: performance.now(),
      endTime: 0,
      totalDurationMs: 0,
      input,
      snapshots: [],
      diffs: [],
      aiCorrections: [],
      approvals: [],
      finalTypeDist: {},
      ...definedProps({
        sourceType: metadata?.sourceType,
        intakeKind: metadata?.intakeKind,
      }),
    };
    this._emit({
      kind: "run-start" as const,
      runId,
      source,
      fileName: metadata?.fileName ?? null,
      input,
      ...definedProps({
        sourceType: metadata?.sourceType,
        intakeKind: metadata?.intakeKind,
      }),
    });
  }

  /**
   * تسجيل snapshot لمرحلة.
   *
   * @param stage - اسم المرحلة (مثل "forward-pass", "retroactive")
   * @param classified - مصفوفة العناصر المصنفة
   * @param metadata - بيانات إضافية (مثل عدد التصحيحات لكل pattern)
   */
  snapshot(
    stage: string,
    classified: readonly {
      type: string;
      text: string;
      confidence: number;
      classificationMethod?: string;
    }[],
    metadata?: Record<string, unknown>
  ): void {
    if (!this._currentRun) return;

    const snap: PipelineSnapshot = definedProps({
      stage,
      timestamp: performance.now(),
      lines: classified.map(toSnapshotLine),
      metadata,
    });

    const snaps = this._currentRun.snapshots as PipelineSnapshot[];
    snaps.push(snap);

    let changes = 0;
    let latencyMs = 0;
    // حساب diff مع المرحلة السابقة
    if (snaps.length >= 2) {
      const prev = snaps.at(-2);
      if (prev) {
        const diff = computeDiff(prev, snap);
        (this._currentRun.diffs as StageDiff[]).push(diff);
        changes = diff.changes.length;
        latencyMs = diff.latencyMs;
      }
    }

    const activeFiles = [...this._trackedFiles];
    this._trackedFiles.clear();
    this._emit({
      kind: "snapshot",
      stage,
      lineCount: classified.length,
      changes,
      latencyMs,
      activeFiles,
      ...definedProps({ metadata }),
    });
  }

  /**
   * تسجيل تصحيح AI (من progressive updater).
   */
  logAICorrection(correction: RecordedAICorrection): void {
    if (!this._currentRun) return;
    (this._currentRun.aiCorrections as RecordedAICorrection[]).push(correction);
    this._emit({ kind: "ai-correction", correction });
  }

  logApproval(approval: RecordedApproval): void {
    const targetRun = this._currentRun ?? this._lastCompletedRun;
    if (!targetRun) return;
    (targetRun.approvals as RecordedApproval[]).push(approval);
    this._emit({ kind: "approval", approval });
  }

  logRunFailure(stage: string, message: string, code?: string): void {
    if (!this._currentRun) return;
    this._currentRun.failure = definedProps({ stage, message, code });
    this._emit({
      kind: "run-failure" as const,
      stage,
      message,
      ...definedProps({ code }),
    });
  }

  /**
   * رصد ملف كود اشتغل — يُستدعى من الملفات نفسها عند تنفيذ دوالها.
   */
  trackFile(fileName: string): void {
    this._trackedFiles.add(fileName);
  }

  /**
   * رصد استدعاء البريدج — observation only بدون لمس حالة الـ run.
   */
  logBridgeCall(source: string, elementCount: number, latencyMs: number): void {
    this._emit({ kind: "engine-bridge", source, elementCount, latencyMs });
  }

  /**
   * رصد فتح ملف — بداية رحلة الملف.
   */
  logFileOpen(fileName: string, fileType: string, mode: string): void {
    this._emit({ kind: "file-open", fileName, fileType, mode });
  }

  /**
   * رصد انتهاء استخراج الملف — الباك إند خلص.
   */
  logFileExtractDone(info: {
    fileName: string;
    method: string;
    usedOcr: boolean;
    textLength: number;
    schemaElementCount: number;
    latencyMs: number;
  }): void {
    this._emit({ kind: "file-extract-done", ...info });
  }

  /**
   * إنهاء الـ run الحالي.
   */
  finishRun(): void {
    if (!this._currentRun) return;

    this._currentRun.endTime = performance.now();
    this._currentRun.totalDurationMs = Math.round(
      this._currentRun.endTime - this._currentRun.startTime
    );

    // حساب الـ type distribution النهائي
    const lastSnap =
      this._currentRun.snapshots[this._currentRun.snapshots.length - 1];
    if (lastSnap) {
      this._currentRun.finalTypeDist = computeTypeDist(lastSnap.lines);
    }

    this._emit({
      kind: "run-end",
      totalDurationMs: this._currentRun.totalDurationMs,
      totalVerdicts: this._currentRun.aiCorrections.filter((c) => c.applied)
        .length,
      finalTypeDist: this._currentRun.finalTypeDist,
      outcome: this._currentRun.failure ? "failed-after-visible" : "settled",
    });

    this._lastCompletedRun = this._currentRun;
    this._currentRun = null;
  }

  /**
   * هل فيه run شغّال دلوقتي؟
   */
  get isRunning(): boolean {
    return this._currentRun !== null;
  }

  /**
   * آخر run اتسجّل (أو الشغّال حالياً).
   */
  get lastRun(): PipelineRunReport | null {
    return this._currentRun ?? this._lastCompletedRun;
  }
}

// ─── Singleton ────────────────────────────────────────────────────

export const pipelineRecorder = new PipelineRecorder();

// ─── Console UI ───────────────────────────────────────────────────

const printRunReport = (report: PipelineRunReport): void => {
  console.warn(
    "%c╔══════════════════════════════════════════════════════╗",
    "color: #00ccff; font-weight: bold"
  );
  console.warn(
    "%c║      📡 Pipeline Run Report                          ║",
    "color: #00ccff; font-weight: bold"
  );
  console.warn(
    "%c╚══════════════════════════════════════════════════════╝",
    "color: #00ccff; font-weight: bold"
  );

  // ── ملخص عام ──
  const frontendMs =
    report.snapshots.length >= 2
      ? Math.round(
          (report.snapshots.find((s) => s.stage === "render-first")
            ?.timestamp ??
            report.snapshots[report.snapshots.length - 1]?.timestamp ??
            0) - (report.snapshots[0]?.timestamp ?? 0)
        )
      : 0;
  const aiMs = report.totalDurationMs - frontendMs;

  console.warn(
    `\n📋 Source: ${report.source} | ${report.input.lineCount} lines | ${report.input.textLength} chars`
  );
  console.warn(
    `⏱️ Total: ${(report.totalDurationMs / 1000).toFixed(1)}s (frontend: ${frontendMs}ms, AI: ${(aiMs / 1000).toFixed(1)}s)`
  );
  console.warn(`🆔 Run ID: ${report.runId}`);

  // ── جدول المراحل ──
  console.warn(
    "\n%c━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "color: #888"
  );
  console.warn(
    "%c📊 Stage-by-Stage Progression:",
    "color: #ffcc00; font-weight: bold"
  );

  const stageTable = report.snapshots.map((snap, idx) => {
    const diff = idx > 0 ? report.diffs[idx - 1] : null;
    const prevSnap = idx > 0 ? report.snapshots[idx - 1] : null;
    const latency = prevSnap
      ? Math.round(snap.timestamp - prevSnap.timestamp)
      : 0;

    return {
      "#": idx + 1,
      Stage: snap.stage,
      Lines: snap.lines.length,
      Changes: diff ? diff.changes.length : "—",
      Duration: idx === 0 ? "—" : `${latency}ms`,
      Notes: snap.metadata
        ? Object.entries(snap.metadata)
            .map(([k, v]) => `${k}=${v}`)
            .join(", ")
            .slice(0, 60)
        : "",
    };
  });

  console.table(stageTable);

  // ── Type Distribution النهائي ──
  console.warn(
    "\n%c📦 Final Type Distribution:",
    "color: #00ff88; font-weight: bold"
  );

  console.table(report.finalTypeDist);

  // ── Diffs بين المراحل ──
  for (const diff of report.diffs) {
    if (diff.changes.length === 0) continue;

    console.warn(
      `\n%c🔄 ${diff.fromStage} → ${diff.toStage}: ${diff.changes.length} changes (${diff.latencyMs}ms)`,
      "color: #ff6b6b; font-weight: bold"
    );

    const sample = diff.changes.slice(0, 15);

    console.table(
      sample.map((c) => ({
        "Line#": c.lineIndex,
        Text: c.text.slice(0, 40),
        Before: c.fromType,
        "→ After": c.toType,
        "Δ Conf":
          c.confidenceDelta > 0
            ? `+${c.confidenceDelta}`
            : `${c.confidenceDelta}`,
      }))
    );
    if (diff.changes.length > 15) {
      console.warn(`   ... و ${diff.changes.length - 15} تغيير تاني`);
    }
  }

  // ── تصحيحات AI ──
  const applied = report.aiCorrections.filter((c) => c.applied);
  const skipped = report.aiCorrections.filter((c) => !c.applied);

  if (report.aiCorrections.length > 0) {
    console.warn(
      "\n%c━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
      "color: #888"
    );
    console.warn(
      `%c🤖 AI Corrections: ${applied.length} applied, ${skipped.length} skipped`,
      "color: #ff00ff; font-weight: bold"
    );

    // تجميع حسب المصدر
    const bySource = new Map<string, { applied: number; skipped: number }>();
    for (const c of report.aiCorrections) {
      const entry = bySource.get(c.source) ?? { applied: 0, skipped: 0 };
      if (c.applied) entry.applied++;
      else entry.skipped++;
      bySource.set(c.source, entry);
    }

    console.table(
      Object.fromEntries(
        Array.from(bySource.entries()).map(([source, stats]) => [source, stats])
      )
    );

    if (applied.length > 0) {
      console.warn(
        "\n%c✅ Applied AI Corrections:",
        "color: #00ff88; font-weight: bold"
      );

      console.table(
        applied.slice(0, 20).map((c) => ({
          "Line#": c.lineIndex,
          Text: c.text.slice(0, 35),
          From: c.previousType,
          "→ To": c.correctedType,
          Conf: c.confidence.toFixed(2),
          Source: c.source,
        }))
      );
    }
  }

  console.warn("\n%c─── Full report object: ───", "color: #888");
  console.warn(report);
};

const printLineJourney = (
  report: PipelineRunReport,
  lineIndex: number
): void => {
  console.warn(
    `%c📍 Line Journey: #${lineIndex}`,
    "color: #00ccff; font-weight: bold; font-size: 14px"
  );

  // بحث عن النص من أول snapshot
  const firstSnap = report.snapshots[0];
  const lineText = firstSnap?.lines[lineIndex]?.text ?? "???";
  console.warn(`   "${lineText}"\n`);

  // رحلة عبر الـ snapshots
  const journey: {
    Stage: string;
    Type: string;
    Confidence: number;
    Method: string;
    Changed: string;
  }[] = [];

  let prevType: string | null = null;
  for (const snap of report.snapshots) {
    const line = snap.lines[lineIndex];
    if (!line) continue;

    const changed =
      prevType !== null && line.type !== prevType
        ? `⚠️ ${prevType} → ${line.type}`
        : prevType === null
          ? "—"
          : "✅ unchanged";

    journey.push({
      Stage: snap.stage,
      Type: line.type,
      Confidence: line.confidence,
      Method: line.method,
      Changed: changed,
    });

    prevType = line.type;
  }

  console.table(journey);

  // تصحيحات AI لهذا السطر
  const aiForLine = report.aiCorrections.filter(
    (c) => c.lineIndex === lineIndex
  );
  if (aiForLine.length > 0) {
    console.warn(
      `\n%c🤖 AI corrections for this line:`,
      "color: #ff00ff; font-weight: bold"
    );

    console.table(
      aiForLine.map((c) => ({
        Source: c.source,
        From: c.previousType,
        "→ To": c.correctedType,
        Conf: c.confidence.toFixed(2),
        Applied: c.applied ? "✅" : "❌",
      }))
    );
  }

  // الحالة النهائية
  const lastSnap = report.snapshots[report.snapshots.length - 1];
  const finalLine = lastSnap?.lines[lineIndex];
  const lastAIApplied = aiForLine.filter((c) => c.applied).pop();

  const finalType = lastAIApplied?.correctedType ?? finalLine?.type ?? "???";
  console.warn(
    `\n   Final type: %c${finalType}`,
    "color: #00ff88; font-weight: bold; font-size: 14px"
  );
};

// ─── ربط بالـ window ──────────────────────────────────────────────

/**
 * يسجّل `__showPipelineRun` و `__showLineJourney` و `__lastPipelineRun` على الـ window.
 */
export const registerPipelineRecorderUI = (): void => {
  if (typeof window === "undefined") return;

  const win = window as PipelineRecorderDebugWindow;
  const shouldLogReady =
    !win.__pipelineRecorderUiRegistered && isPipelineConsoleDebugEnabled();

  Object.defineProperty(win, "__lastPipelineRun", {
    get: () => pipelineRecorder.lastRun,
    configurable: true,
  });

  win.__showPipelineRun = (): void => {
    const report = pipelineRecorder.lastRun;
    if (!report) {
      console.warn("⚠️ مفيش pipeline run مسجّل — الصق نص أو افتح ملف الأول");
      return;
    }
    printRunReport(report);
  };

  win.__showLineJourney = (lineIndex: number): void => {
    const report = pipelineRecorder.lastRun;
    if (!report) {
      console.warn("⚠️ مفيش pipeline run مسجّل — الصق نص أو افتح ملف الأول");
      return;
    }
    if (typeof lineIndex !== "number" || lineIndex < 0) {
      console.warn("⚠️ ادخل رقم السطر: __showLineJourney(15)");
      return;
    }
    printLineJourney(report, lineIndex);
  };

  win.__pipelineRecorderUiRegistered = true;

  if (shouldLogReady) {
    console.warn(
      "%c📡 Pipeline recorder ready! After paste/import, run: __showPipelineRun() or __showLineJourney(lineIndex)",
      "color: #00ccff; font-weight: bold; font-size: 13px"
    );
  }
};

import { classifyText } from "./paste-classifier";
import { logger } from "../utils/logger";

export type ProductionSelfCheckTrigger =
  | "editor-import"
  | "manual-auto-check"
  | "manual-reclassify";

export interface ProductionSelfCheckOptions {
  trigger: ProductionSelfCheckTrigger;
  sampleText?: string;
  force?: boolean;
}

export interface ProductionSelfCheckReport {
  trigger: ProductionSelfCheckTrigger;
  executedFunctions: number;
  failedFunctions: number;
  uiFunctionsExecuted: number;
  extensionFunctionsExecuted: number;
  durationMs: number;
  failures: ReadonlyArray<{ name: string; message: string }>;
}

const selfCheckLogger = logger.createScope("production-self-check");

let hasExecutedSelfCheck = false;
let lastReport: ProductionSelfCheckReport | null = null;
let inFlightSelfCheck: Promise<ProductionSelfCheckReport> | null = null;

const safeMessage = (error: unknown): string =>
  error instanceof Error ? error.message : String(error);

const runExtensionChecks = (sampleText: string): number => {
  const classified = classifyText(sampleText);
  if (classified.length === 0) {
    throw new Error("Classification returned no lines.");
  }
  return 1;
};

export const runProductionSelfCheck = async (
  options: ProductionSelfCheckOptions
): Promise<ProductionSelfCheckReport> => {
  if (!options.force && hasExecutedSelfCheck && lastReport) {
    return lastReport;
  }

  if (!options.force && inFlightSelfCheck) {
    return inFlightSelfCheck;
  }

  const run = (async (): Promise<ProductionSelfCheckReport> => {
    const startedAt = performance.now();
    const failures: Array<{ name: string; message: string }> = [];

    const sampleText =
      (options.sampleText ?? "ثم يدخل أحمد إلى البيت.").trim() ||
      "ثم يدخل أحمد إلى البيت.";

    let extensionFunctionsExecuted = 0;

    try {
      extensionFunctionsExecuted += runExtensionChecks(sampleText);
    } catch (error) {
      failures.push({ name: "classification", message: safeMessage(error) });
    }

    const report: ProductionSelfCheckReport = {
      trigger: options.trigger,
      executedFunctions: extensionFunctionsExecuted,
      failedFunctions: failures.length,
      uiFunctionsExecuted: 0,
      extensionFunctionsExecuted,
      durationMs: Math.round(performance.now() - startedAt),
      failures,
    };

    hasExecutedSelfCheck = true;
    lastReport = report;

    selfCheckLogger.info("Production self-check completed", report);

    return report;
  })();

  inFlightSelfCheck = run;

  try {
    return await run;
  } finally {
    inFlightSelfCheck = null;
  }
};

import { describe, expect, it } from "vitest";

import { retroactiveCorrectionPass } from "./retroactive-corrector";
import type { ClassifiedDraft } from "./classification-types";

const draft = (
  overrides: Partial<ClassifiedDraft> & Pick<ClassifiedDraft, "type" | "text">
): ClassifiedDraft => ({
  confidence: overrides.confidence ?? 70,
  classificationMethod: overrides.classificationMethod ?? "context",
  ...overrides,
});

describe("retroactive-corrector — النقطتان المصطنعة عند التحويل من character إلى dialogue", () => {
  it("ينزع النقطتين من نص الشخصية الزائفة عند إعادة تصنيفها إلى حوار (Pattern 2)", () => {
    const classified: ClassifiedDraft[] = [
      draft({ type: "character", text: "اميرة:" }),
      draft({ type: "character", text: "وما بلغتش:" }),
      draft({ type: "dialogue", text: "ليه ؟" }),
    ];

    const corrections = retroactiveCorrectionPass(classified);

    expect(corrections).toBeGreaterThan(0);
    expect(classified[0]?.type).toBe("character");
    expect(classified[0]?.text).toBe("اميرة:");

    expect(classified[1]?.type).toBe("dialogue");
    // النقطتان المضافتان تلقائيًا لا تتسرّبان إلى نص الحوار النهائي
    expect(classified[1]?.text).toBe("وما بلغتش");
    expect(classified[1]?.text).not.toMatch(/[:：]\s*$/);

    expect(classified[2]?.type).toBe("dialogue");
    expect(classified[2]?.text).toBe("ليه ؟");
  });

  it("ينزع أيضًا النقطتين العربية الكاملة العرض «：» عند التحويل", () => {
    const classified: ClassifiedDraft[] = [
      draft({ type: "character", text: "اميرة:" }),
      draft({ type: "character", text: "وما بلغتش：" }),
      draft({ type: "dialogue", text: "ليه ؟" }),
    ];

    retroactiveCorrectionPass(classified);

    expect(classified[1]?.type).toBe("dialogue");
    expect(classified[1]?.text).toBe("وما بلغتش");
    expect(classified[1]?.text).not.toMatch(/[:：]\s*$/);
  });

  it("لا يغيّر نص سطر dialogue أصلًا حتى لو انتهى صدفة بنقطتين", () => {
    // هذا السطر مصنف dialogue من البداية — لا يمر بـ correctedDraft أصلًا،
    // لكن يُبرهن أن النزع محصور حصرًا بتحويلات character → dialogue.
    const classified: ClassifiedDraft[] = [
      draft({ type: "character", text: "أحمد:" }),
      draft({ type: "dialogue", text: "قال لي:" }),
    ];

    retroactiveCorrectionPass(classified);

    expect(classified[1]?.type).toBe("dialogue");
    expect(classified[1]?.text).toBe("قال لي:");
  });

  it("يحافظ على الناتج المطلوب للسيناريو المرجعي: «اميرة:» ثم «وما بلغتش ليه ؟»", () => {
    // هذا اختبار التكامل الحاكم: المدخل يحاكي ناتج الممر الأمامي الخاطئ
    // بعد أن قسّم المصنّف المحلي سطر الحوار الصحيح إلى ثلاثة مقاطع،
    // والمطلوب أن يُنتج الممر الرجعي بنية قابلة للعودة إلى السطرين الأصليين
    // دون أي نقطتين مصطنعة تتسرّب إلى نص الحوار.
    const classified: ClassifiedDraft[] = [
      draft({ type: "character", text: "اميرة:" }),
      draft({ type: "character", text: "وما بلغتش:" }),
      draft({ type: "dialogue", text: "ليه ؟" }),
    ];

    retroactiveCorrectionPass(classified);

    // لا يجوز أن يظهر أي سطر dialogue ينتهي بنقطتين مصطنعة
    const dialogueLines = classified.filter((d) => d.type === "dialogue");
    for (const line of dialogueLines) {
      expect(line.text).not.toMatch(/[:：]\s*$/);
    }

    // البنية النهائية يجب أن تكون: character → dialogue → dialogue
    expect(classified.map((d) => d.type)).toEqual([
      "character",
      "dialogue",
      "dialogue",
    ]);

    // عند دمج سطري الحوار المتتاليين نحصل على نص الحوار الأصلي كما أخرجه كرنك
    const mergedDialogue = dialogueLines.map((d) => d.text).join(" ");
    expect(mergedDialogue).toBe("وما بلغتش ليه ؟");
  });
});

