    expect(summary.sentToModel).toBe(35);
    expect(summary.sentLocalReview).toBe(14);
    expect(summary.sentAgentCandidate).toBe(20);
    expect(summary.sentAgentForced).toBe(1);
    expect(summary.passSkipped).toBe(0);
  });

  it("لا يعتبر pass حالة شك مرسلة للنموذج", () => {
    const bands: SuspicionBand[] = [
      "pass",
      "local-review",
      "agent-candidate",
      "agent-forced",
    ];

    const summary = summarizeSuspicionReviewDispatchBands(bands);

    expect(summary.totalLocalCases).toBe(4);
    expect(summary.sentToModel).toBe(3);
    expect(summary.passSkipped).toBe(1);
    expect(bands.filter(isModelReviewSuspicionBand)).toEqual([
      "local-review",
      "agent-candidate",
      "agent-forced",
    ]);
  });

  it("يسمح لنموذج الشك بإسقاط الحالات الضعيفة قبل المراجعة النهائية", () => {
    expect(
      shouldKeepSuspicionModelDecisionForFinalReview({
        verdict: "dismiss",
        routingBand: "agent-candidate",
      })
    ).toBe(false);

    expect(
      shouldKeepSuspicionModelDecisionForFinalReview({
        verdict: "confirm",
        routingBand: "local-review",
      })
    ).toBe(false);

    expect(
      shouldKeepSuspicionModelDecisionForFinalReview({
        verdict: "escalate",
        routingBand: "agent-forced",
      })
    ).toBe(true);
  });
});

/**
 * @module extensions/transition
 * @description
 * عنصر الانتقال (Transition) — أوامر المونتاج بين المشاهد.
 *
 * يُصدّر:
 * - {@link isTransitionLine} — كاشف أسطر الانتقال (قطع إلى، مزج إلى، إلخ)
 * - {@link Transition} — عقدة Tiptap للانتقال
 *
 * سلوك Enter: الانتقال إلى {@link SceneHeaderTopLine} (رأس مشهد جديد).
 */
import { Node, mergeAttributes } from "@tiptap/core";
import { buildProgressiveNodeAttributes } from "./shared-node-attrs";
import { TRANSITION_RE } from "./arabic-patterns";
import { normalizeLine } from "./text-utils";

/**
 * يفحص ما إذا كان السطر أمر انتقال مونتاجي.
 *
 * @param text - النص الخام للسطر
 * @returns `true` إذا طابق {@link TRANSITION_RE}
 */
export const isTransitionLine = (text: string): boolean => {
  const normalized = normalizeLine(text);
  if (!normalized) return false;
  return TRANSITION_RE.test(normalized);
};

/**
 * الانتقال (Transition)
 * مثال: قطع إلى، مزج إلى
 */
export const Transition = Node.create({
  name: "transition",
  group: "block",
  content: "inline*",
  defining: true,

  addAttributes() {
    return buildProgressiveNodeAttributes();
  },

  parseHTML() {
    return [{ tag: 'div[data-type="transition"]' }];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(HTMLAttributes, {
        "data-type": "transition",
        class: "screenplay-transition",
      }),
      0,
    ];
  },

  addKeyboardShortcuts() {
    return {
      Enter: ({ editor }) => {
        if (!editor.isActive("transition")) return false;
        return editor
          .chain()
          .focus()
          .splitBlock()
          .setSceneHeaderTopLine()
          .run();
      },
    };
  },
});

