import { editDistanceRatio } from "../metrics";

export type LineMatch = {
  sourceIndex: number;
  ocrIndex: number;
  score: number; // 0..1 similarity
};

export function simpleLineAlignment(
  sourceLines: string[],
  ocrLines: string[]
): LineMatch[] {
  // Greedy alignment مع نافذة؛ عملي وسريع كبداية
  const matches: LineMatch[] = [];
  let j = 0;

  for (let i = 0; i < sourceLines.length; i++) {
    const sourceLine = sourceLines[i];
    if (sourceLine === undefined) {
      continue;
    }

    let bestJ = -1;
    let bestScore = -1;

    const windowEnd = Math.min(ocrLines.length - 1, j + 4);
    for (let k = j; k <= windowEnd; k++) {
      const ocrLine = ocrLines[k];
      if (ocrLine === undefined) {
        continue;
      }
      const ratio = editDistanceRatio(sourceLine, ocrLine);
      const sim = 1 - ratio;
      if (sim > bestScore) {
        bestScore = sim;
        bestJ = k;
      }
    }

    if (bestJ >= 0) {
      matches.push({ sourceIndex: i, ocrIndex: bestJ, score: bestScore });
      j = bestJ; // لا نتراجع للخلف
    }
  }

  return matches;
}

import type { OcrPageResult, PageExtraction, PipelineConfig } from "../types";
import { patchSuspiciousLinesFromOcr } from "./patch-apply";

export function applyOcrPatchesToPages(args: {
  pages: PageExtraction[];
  ocrResults: OcrPageResult[];
  config: PipelineConfig;
}): { pages: PageExtraction[]; patchedLines: number } {
  const pageMap = new Map<number, OcrPageResult>();
  for (const p of args.ocrResults) pageMap.set(p.page, p);

  let totalPatched = 0;

  for (const page of args.pages) {
    const ocr = pageMap.get(page.page);
    if (!ocr?.lines?.length) continue;

    const r = patchSuspiciousLinesFromOcr({
      pageLines: page.lines,
      ocrLines: ocr.lines,
      suspiciousThreshold: args.config.quality.suspiciousThreshold,
      maxEditDistanceRatio: args.config.patch.maxEditDistanceRatio,
    });

    page.lines = r.lines;
    page.usedOcr = r.patched > 0;
    totalPatched += r.patched;
  }

  return { pages: args.pages, patchedLines: totalPatched };
}

import { editDistanceRatio } from "../metrics";
import { simpleLineAlignment } from "./align";
import type { ExtractedLine } from "../types";

export function patchSuspiciousLinesFromOcr(opts: {
  pageLines: ExtractedLine[];
  ocrLines: string[];
  suspiciousThreshold: number;
  maxEditDistanceRatio: number;
}): { patched: number; lines: ExtractedLine[] } {
  const { pageLines, ocrLines, suspiciousThreshold, maxEditDistanceRatio } =
    opts;

  const patchedLines = [...pageLines];
  const sourceTexts = pageLines.map((l) => l.text);

  const matches = simpleLineAlignment(sourceTexts, ocrLines);

  let patched = 0;

  for (const m of matches) {
    const line = patchedLines[m.sourceIndex];
    if (!line) continue;
    if (line.quality.score >= suspiciousThreshold) continue; // لا نلمس السطور الجيدة

    const candidate = (ocrLines[m.ocrIndex] || "").trim();
    if (!candidate) continue;

    const ratio = editDistanceRatio(line.text, candidate);

    // تصحيح مقيد: فقط إذا الاختلاف معقول (تصحيح OCR) وليس إعادة كتابة كاملة
    if (ratio <= maxEditDistanceRatio) {
      if (candidate !== line.text) {
        line.text = candidate;
        line.source = "patched";
        line.flags.push("patched_from_ocr");
        patched++;
      }
    } else {
      line.flags.push("patch_rejected_large_diff");
    }
  }

  return { patched, lines: patchedLines };
}

import type { ExtractedLine, LineQuality } from "../types";

const ARABIC_RE = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]/g;
const DIGIT_RE = /[0-9٠-٩]/g;
const PUNCT_RE = /[.,;:!?،؛()\x5B\x5D{}"'—–-]/g;

// أحرف غريبة شائعة في OCR/استخراج سيئ
const WEIRD_RE = /[�□■▪●◦◆◇¤§±©®™`~^_|\\]/g;

// أنماط تشير إلى كسر عربي/فصل غير طبيعي
const BROKEN_ARABIC_PATTERNS: RegExp[] = [
  /[اأإآبتثجحخدذرزسشصضطظعغفقكلمنهويى]\s+[اأإآبتثجحخدذرزسشصضطظعغفقكلمنهويى]\s+[اأإآبتثجحخدذرزسشصضطظعغفقكلمنهويى]\s+[اأإآبتثجحخدذرزسشصضطظعغفقكلمنهويى]/,
  /[:：]\s*$/, // سطر ينتهي بنقطتين غالبًا حوار ناقص
];

// أنماط حوار/عنصر سيناريو مشبوه
const SUSPICIOUS_DIALOGUE_PATTERNS: RegExp[] = [
  /^[^:]{1,40}\s*[:：]\s*$/, // اسم شخصية فقط بدون جملة
  /[:：].{0,2}$/, // حوار ناقص جدًا بعد النقطتين
];

export function scoreLine(text: string): LineQuality {
  const len = Math.max(text.length, 1);
  const arabicCount = (text.match(ARABIC_RE) || []).length;
  const digitCount = (text.match(DIGIT_RE) || []).length;
  const punctCount = (text.match(PUNCT_RE) || []).length;
  const weirdCount = (text.match(WEIRD_RE) || []).length;

  const arabicRatio = arabicCount / len;
  const digitRatio = digitCount / len;
  const punctuationRatio = punctCount / len;
  const weirdCharRatio = weirdCount / len;

  const hasBrokenArabicPattern = BROKEN_ARABIC_PATTERNS.some((rx) =>
    rx.test(text)
  );
  const suspiciousDialoguePattern = SUSPICIOUS_DIALOGUE_PATTERNS.some((rx) =>
    rx.test(text)
  );

  const probableArtifact =
    /^\s*\d+\s*$/.test(text) ||
    /^[-—–]{3,}$/.test(text) ||
    /^(page|footer|header)\b/i.test(text.trim());

  const reasons: string[] = [];
  let score = 1.0;

  if (weirdCharRatio > 0.12) {
    score -= 0.35;
    reasons.push("weird_char_ratio_high");
  }
  if (hasBrokenArabicPattern) {
    score -= 0.2;
    reasons.push("broken_arabic_pattern");
  }
  if (suspiciousDialoguePattern) {
    score -= 0.15;
    reasons.push("suspicious_dialogue_pattern");
  }
  if (probableArtifact) {
    score -= 0.4;
    reasons.push("probable_artifact");
  }
  if (text.trim().length === 0) {
    score -= 0.5;
    reasons.push("empty");
  }

  score = Math.max(0, Math.min(1, score));

  return {
    score,
    reasons,
    weirdCharRatio,
    arabicRatio,
    digitRatio,
    punctuationRatio,
    hasBrokenArabicPattern,
    suspiciousDialoguePattern,
    probableArtifact,
  };
}

export function applyQualityScoring(lines: ExtractedLine[]): ExtractedLine[] {
  for (const l of lines) {
    l.quality = scoreLine(l.text);
    if (l.quality.score < 0.62) l.flags.push("suspicious");
  }
  return lines;
}

