import { PostClassificationReviewer } from "../../extensions/classification-core";
import type {
  ClassifiedLine,
  SuspiciousLine as ClassificationSuspiciousLine,
  SuspicionRoutingBand,
} from "../../extensions/classification-types";
import {
  type PipelineLineRef,
  type RawValidationResult,
  validateRawScreenplayLines,
} from "./raw-screenplay-validator";

export interface RawSuspiciousLineCandidate {
  readonly lineIndex: number;
  readonly pageIndex?: number;
  readonly pageLineIndex?: number;
  readonly text: string;
  readonly rawValidationScore: number; // 0..100
  readonly reasons: string[];
}

export interface FusedSuspiciousLineCandidate {
  readonly lineIndex: number;
  readonly pageIndex?: number;
  readonly pageLineIndex?: number;
  readonly text: string;
  readonly rawValidationScore: number;
  readonly classificationSuspicionScore: number;
  readonly fusedScore: number;
  readonly routingBand: SuspicionRoutingBand | "ocr-fallback";
  readonly reasons: string[];
  readonly classificationReview?: ClassificationSuspiciousLine;
}

export interface BuildSuspiciousOptions {
  readonly rawThreshold?: number;
  readonly fusedThresholdForOcrFallback?: number;
  readonly classificationOnlyThreshold?: number;
}

function buildRawReasonsByLine(
  raw: RawValidationResult
): Map<number, string[]> {
  const map = new Map<number, string[]>();
  for (const issue of raw.issues) {
    const bucket = map.get(issue.lineIndex) ?? [];
    bucket.push(`${issue.code}: ${issue.reason}`);
    map.set(issue.lineIndex, bucket);
  }
  return map;
}

export function collectRawSuspiciousLines(
  lines: readonly PipelineLineRef[],
  classifiedLines?: readonly ClassifiedLine[],
  rawThreshold = 35
): RawSuspiciousLineCandidate[] {
  const raw = validateRawScreenplayLines(lines, {
    pdfMode: true,
    suspiciousThreshold: rawThreshold,
    ...(classifiedLines !== undefined ? { classifiedLines } : {}),
  });

  const reasonsByLine = buildRawReasonsByLine(raw);
  const refsByLine = new Map<number, PipelineLineRef>();
  for (const ref of lines) {
    refsByLine.set(ref.lineIndex, ref);
  }

  const out: RawSuspiciousLineCandidate[] = [];
  for (const lineIndex of raw.suspiciousLineIndexes) {
    const ref = refsByLine.get(lineIndex);
    if (!ref) continue;
    out.push({
      lineIndex,
      ...(ref.pageIndex !== undefined ? { pageIndex: ref.pageIndex } : {}),
      ...(ref.pageLineIndex !== undefined
        ? { pageLineIndex: ref.pageLineIndex }
        : {}),
      text: ref.text,
      rawValidationScore: raw.lineScores.get(lineIndex) ?? 0,
      reasons: reasonsByLine.get(lineIndex) ?? [],
    });
  }

  return out;
}

export function collectClassificationSuspiciousLines(
  classifiedLines: readonly ClassifiedLine[]
): ClassificationSuspiciousLine[] {
  const reviewer = new PostClassificationReviewer();
  const packet = reviewer.review(classifiedLines);
  return [...packet.suspiciousLines];
}

function mapClassificationScore(
  suspicion: ClassificationSuspiciousLine | undefined
): number {
  if (!suspicion) return 0;
  return Math.max(0, Math.min(100, Math.round(suspicion.escalationScore)));
}

function fuseScores(rawScore: number, clsScore: number): number {
  // دمج منحاز قليلًا لصالح مؤشرات النص الخام لأن هدف الملف OCR fallback
  return Math.min(100, Math.round(rawScore * 0.6 + clsScore * 0.4));
}

export function fuseSuspiciousSignals(
  lines: readonly PipelineLineRef[],
  classifiedLines: readonly ClassifiedLine[],
  options: BuildSuspiciousOptions = {}
): FusedSuspiciousLineCandidate[] {
  const rawThreshold = options.rawThreshold ?? 35;
  const fusedThresholdForOcrFallback =
    options.fusedThresholdForOcrFallback ?? 55;
  const classificationOnlyThreshold = options.classificationOnlyThreshold ?? 65;

  const reviewer = new PostClassificationReviewer();
  const rawList = collectRawSuspiciousLines(
    lines,
    classifiedLines,
    rawThreshold
  );
  const clsList = reviewer.review(classifiedLines).suspiciousLines;

  const byRaw = new Map<number, RawSuspiciousLineCandidate>();
  rawList.forEach((item) => byRaw.set(item.lineIndex, item));

  const byCls = new Map<number, ClassificationSuspiciousLine>();
  clsList.forEach((item) => byCls.set(item.line.lineIndex, item));

  const refsByLine = new Map<number, PipelineLineRef>();
  for (const ref of lines) {
    refsByLine.set(ref.lineIndex, ref);
  }

  const unionIndexes = new Set<number>([
    ...Array.from(byRaw.keys()),
    ...Array.from(byCls.keys()),
  ]);

  const fused: FusedSuspiciousLineCandidate[] = [];

  for (const lineIndex of Array.from(unionIndexes).sort((a, b) => a - b)) {
    const ref = refsByLine.get(lineIndex);
    if (!ref) continue;

    const raw = byRaw.get(lineIndex);
    const cls = byCls.get(lineIndex);
    const rawScore = raw?.rawValidationScore ?? 0;
    const clsScore = mapClassificationScore(cls);
    const fusedScore = fuseScores(rawScore, clsScore);

    const reasons = [
      ...(raw?.reasons ?? []),
      ...(cls?.findings.map((f) => `${f.detectorId}: ${f.reason}`) ?? []),
    ];

    let routingBand: FusedSuspiciousLineCandidate["routingBand"] = "pass";

    if (
      rawScore >= fusedThresholdForOcrFallback ||
      fusedScore >= fusedThresholdForOcrFallback
    ) {
      routingBand = "ocr-fallback";
    } else if (cls && clsScore >= classificationOnlyThreshold) {
      routingBand = cls.routingBand;
    } else if (cls) {
      routingBand = "local-review";
    }

    fused.push({
      lineIndex,
      ...(ref.pageIndex !== undefined ? { pageIndex: ref.pageIndex } : {}),
      ...(ref.pageLineIndex !== undefined
        ? { pageLineIndex: ref.pageLineIndex }
        : {}),
      text: ref.text,
      rawValidationScore: rawScore,
      classificationSuspicionScore: clsScore,
      fusedScore,
      routingBand,
      reasons,
      ...(cls !== undefined ? { classificationReview: cls } : {}),
    });
  }

  return fused;
}

export function selectOcrFallbackTargets(
  fused: readonly FusedSuspiciousLineCandidate[],
  maxLines = 200
): FusedSuspiciousLineCandidate[] {
  return fused
    .filter((x) => x.routingBand === "ocr-fallback")
    .sort((a, b) => b.fusedScore - a.fusedScore || a.lineIndex - b.lineIndex)
    .slice(0, maxLines);
}

export function groupOcrTargetsByPage(
  targets: readonly FusedSuspiciousLineCandidate[]
): Map<number, FusedSuspiciousLineCandidate[]> {
  const map = new Map<number, FusedSuspiciousLineCandidate[]>();
  for (const target of targets) {
    if (typeof target.pageIndex !== "number") continue;
    const bucket = map.get(target.pageIndex) ?? [];
    bucket.push(target);
    map.set(target.pageIndex, bucket);
  }
  return map;
}

/**
 * @module pipeline/sanitized-import-pipeline
 * @description خط أنابيب الاستيراد المُنظَّف — مسار مستقل للملفات الشاذة
 *
 * يكشف الملفات ذات التنسيقات غير القياسية (مثل بادئات `[pStyle=-]` من Word)
 * وينظفها قبل تمريرها للتصنيف والمراجعة والوكيل.
 *
 * التدفق:
 * ```
 * نص خام → كشف (needsSanitization) → تنظيف (sanitizeInput)
 *         → تصنيف → مراجعة لاحقة → self-check → وكيل AI
 * ```
 *
 * هذا المسار مستقل تماماً عن:
 * - مسار اللصق (`paste-classifier`)
 * - مسار DOC/DOCX (`import-classified-text`)
 * - مسار الكتل البنيوية (`import-structured-blocks`)
 */

import { logger } from "@editor/utils/logger";
import type { SanitizationReport } from "./input-sanitizer";
import { needsSanitization, sanitizeInput } from "./input-sanitizer";

const sanitizedPipelineLogger = logger.createScope("pipeline.sanitized-import");

// ─── الأنواع ─────────────────────────────────────────────────────

/** نتيجة تشغيل خط أنابيب التنظيف */
export interface SanitizedImportResult {
  /** النص بعد التنظيف (جاهز للتصنيف) */
  readonly cleanText: string;
  /** النص الأصلي قبل التنظيف */
  readonly originalText: string;
  /** هل تم تعديل النص */
  readonly wasModified: boolean;
  /** تقرير التنظيف المفصل */
  readonly sanitizationReport: SanitizationReport;
}

// ─── الدوال المصدّرة ─────────────────────────────────────────────

/**
 * يتحقق مما إذا كان النص يحتاج للمرور عبر خط أنابيب التنظيف.
 *
 * يُستخدم في {@link buildFileOpenPipelineAction} لتوجيه الملفات الشاذة
 * إلى مسار `import-sanitized-text` بدلاً من المسار العادي.
 */
export function shouldUseSanitizedPipeline(text: string): boolean {
  return needsSanitization(text);
}

/**
 * يُنفّذ خط أنابيب التنظيف على النص الخام.
 *
 * 1. يكتشف التنسيقات غير القياسية
 * 2. ينظف النص (حذف بادئات، وسوم XML، أكواد حقول، إلخ)
 * 3. يُسجّل telemetry
 * 4. يُرجع النص النظيف جاهزاً للتصنيف
 *
 * @param text - النص الخام المستورد
 * @returns نتيجة التنظيف مع التقرير
 */
export function runSanitizedImportPipeline(
  text: string
): SanitizedImportResult {
  const sanitized = sanitizeInput(text);

  if (sanitized.report.wasModified) {
    const appliedRules = sanitized.report.rulesApplied
      .filter((r) => r.applied)
      .map((r) => r.ruleId);

    sanitizedPipelineLogger.telemetry("sanitized-pipeline-executed", {
      inputLines: sanitized.report.inputLineCount,
      outputLines: sanitized.report.outputLineCount,
      totalMatches: sanitized.report.totalMatchCount,
      rulesApplied: appliedRules,
      durationMs: sanitized.report.durationMs,
    });
  }

  return {
    cleanText: sanitized.text,
    originalText: text,
    wasModified: sanitized.report.wasModified,
    sanitizationReport: sanitized.report,
  };
}

/**
 * @module pipeline/trust-policy
 * @description Structured Input Trust Policy — المرحلة 1 من إعادة الهيكلة
 *
 * يُحدد مستويات الثقة للمدخلات المهيكلة ويقرر مسار المعالجة:
 * - trusted_structured → استيراد مباشر كعقد + فحص خلفي
 * - semi_structured → fallback مناسب مع تصنيف جزئي
 * - raw_text → المصنف النصي الكامل (paste-classifier)
 *
 * الثقة هنا ليست "بنية لغوية عربية جاهزة" بل "بنية تشغيلية داخلية
 * ناتجة من التطبيق/الاستخراج الداخلي".
 */

// ─── مستويات الثقة ──────────────────────────────────────────────

export type InputTrustLevel =
  | "trusted_structured"
  | "semi_structured"
  | "raw_text";

// ─── معايير الثقة ───────────────────────────────────────────────

export interface TrustAssessment {
  /** مستوى الثقة المُحدد */
  level: InputTrustLevel;
  /** هل المدخل system-generated */
  isSystemGenerated: boolean;
  /** هل المدخل مُتحقق من المخطط (schema-valid) */
  isSchemaValid: boolean;
  /** هل المدخل مُعلّم بالمصدر (source-tagged) */
  isSourceTagged: boolean;
  /** هل المدخل مُتحقق من السلامة (integrity-checked) */
  isIntegrityChecked: boolean;
  /** مصدر المدخل */
  source: string;
  /** سبب تحديد المستوى */
  reason: string;
  /** إصدار المخطط الرقمي — لدعم هجرة بنية StructuredBlock مستقبلاً */
  schemaVersion: number;
}

/** الإصدار الحالي لمخطط StructuredBlock */
export const CURRENT_SCHEMA_VERSION = 1;

// ─── واجهة كتلة مهيكلة ─────────────────────────────────────────

export interface StructuredBlock {
  /** نوع العنصر */
  type: string;
  /** النص */
  text: string;
  /** بيانات إضافية */
  meta?: Record<string, unknown>;
}

export interface StructuredInput {
  /** الكتل المهيكلة */
  blocks: StructuredBlock[];
  /** المصدر */
  source?: string;
  /** هل وُلّدت من النظام */
  systemGenerated?: boolean;
  /** هل تم التحقق من المخطط */
  schemaValid?: boolean;
  /** هل تم التحقق من السلامة */
  integrityChecked?: boolean;
}

// ─── تحديد مستوى الثقة ─────────────────────────────────────────

const VALID_TYPES = new Set([
  "action",
  "dialogue",
  "character",
  "scene_header_top_line",
  "scene_header_1",
  "scene_header_2",
  "scene_header_3",
  "transition",
  "parenthetical",
  "basmala",
]);

/**
 * فحص صلاحية المخطط — كل كتلة يجب أن تحتوي type صالح و text غير فارغ.
 */
const validateSchema = (blocks: readonly StructuredBlock[]): boolean => {
  if (!Array.isArray(blocks) || blocks.length === 0) return false;
  return blocks.every(
    (block) =>
      block &&
      typeof block.type === "string" &&
      VALID_TYPES.has(block.type) &&
      typeof block.text === "string" &&
      block.text.trim().length > 0
  );
};

/**
 * تقييم مستوى الثقة لمدخل مهيكل.
 *
 * القاعدة:
 * - إذا كانت الكتل system-generated + schema-valid + source-tagged + integrity-checked
 *   ⇒ trusted_structured
 * - إذا كانت schema-valid فقط
 *   ⇒ semi_structured
 * - غير ذلك
 *   ⇒ raw_text
 */
export const assessTrustLevel = (input: StructuredInput): TrustAssessment => {
  const isSchemaValid = validateSchema(input.blocks);
  const isSystemGenerated = input.systemGenerated === true;
  const isSourceTagged =
    typeof input.source === "string" && input.source.length > 0;
  const isIntegrityChecked = input.integrityChecked === true;

  if (
    isSystemGenerated &&
    isSchemaValid &&
    isSourceTagged &&
    isIntegrityChecked
  ) {
    return {
      level: "trusted_structured",
      isSystemGenerated,
      isSchemaValid,
      isSourceTagged,
      isIntegrityChecked,
      source: input.source ?? "unknown",
      reason: "جميع معايير الثقة مستوفاة — استيراد مباشر مع فحص خلفي",
      schemaVersion: CURRENT_SCHEMA_VERSION,
    };
  }

  if (isSchemaValid) {
    return {
      level: "semi_structured",
      isSystemGenerated,
      isSchemaValid,
      isSourceTagged,
      isIntegrityChecked,
      source: input.source ?? "unknown",
      reason: "المخطط صالح لكن معايير الثقة غير مكتملة",
      schemaVersion: CURRENT_SCHEMA_VERSION,
    };
  }

  return {
    level: "raw_text",
    isSystemGenerated,
    isSchemaValid,
    isSourceTagged,
    isIntegrityChecked,
    source: input.source ?? "unknown",
    reason: "المدخل غير مهيكل أو المخطط غير صالح — fallback للمصنف النصي",
    schemaVersion: CURRENT_SCHEMA_VERSION,
  };
};

// ─── مسار المعالجة ─────────────────────────────────────────────

export type ImportAction =
  | "direct_import" // استيراد مباشر كعقد
  | "direct_import_with_bg_check" // استيراد مباشر + فحص خلفي
  | "fallback_to_classifier"; // المصنف النصي الكامل

/**
 * تحديد مسار المعالجة بناءً على مستوى الثقة.
 */
export const resolveImportAction = (level: InputTrustLevel): ImportAction => {
  switch (level) {
    case "trusted_structured":
      return "direct_import_with_bg_check";
    case "semi_structured":
      return "fallback_to_classifier";
    case "raw_text":
      return "fallback_to_classifier";
  }
};

