import type { UnstructuredReconstructionResult } from "./types";
import { detectUnstructured } from "./detect";
import { normalizeForUnstructuredWork } from "./normalize";
import { segmentToChunks, splitCutSceneGlue } from "./segmenter";
import { classifyUnstructuredLines } from "./classifier";
import { validateUnstructuredResult } from "./validator";
import { toStructuredBlocks, toStructuredText } from "./to-structured";

export interface MaybeReconstructOptions {
  threshold: number;
  replaceBullets?: boolean;
}

export function maybeReconstructUnstructured(
  text: string,
  opt: MaybeReconstructOptions
): UnstructuredReconstructionResult {
  const decision = detectUnstructured(text, { threshold: opt.threshold });

  if (!decision.applied) {
    return {
      applied: false,
      qualityScore: decision.qualityScore,
      structuredText: text ?? "",
      structuredBlocks: [],
      debug: {
        reasons: decision.reasons,
        operationsCount: 0,
        itemsCount: 0,
      },
    };
  }

  const work = normalizeForUnstructuredWork(text ?? "", {
    replaceBullets: opt.replaceBullets ?? true,
    collapseBlankLines: true,
  });

  let chunks = segmentToChunks(work);
  chunks = splitCutSceneGlue(chunks);

  const lines = chunks.map((c) => c.raw);

  const classified = classifyUnstructuredLines(lines);
  const v = validateUnstructuredResult(classified);

  if (!v.ok) {
    return {
      applied: false,
      qualityScore: decision.qualityScore,
      structuredText: text ?? "",
      structuredBlocks: [],
      debug: {
        reasons: decision.reasons.concat(
          v.errors.slice(0, 5).map((e) => `V_${e.code}`)
        ),
        operationsCount: classified.operations.length,
        itemsCount: classified.items.length,
      },
    };
  }

  const structuredBlocks = toStructuredBlocks(classified);
  const structuredText = toStructuredText(structuredBlocks);

  return {
    applied: true,
    qualityScore: decision.qualityScore,
    structuredText,
    structuredBlocks,
    debug: {
      reasons: decision.reasons,
      operationsCount: classified.operations.length,
      itemsCount: classified.items.length,
    },
  };
}

import type { ScreenplayBlock } from "../../utils/file-import/document-model";
import type { UnstructuredItemType, UnstructuredResult } from "./types";

function assertUnreachable(value: never): never {
  throw new Error(`Unhandled UnstructuredItemType: ${String(value)}`);
}

function mapTypeToFormatId(
  t: UnstructuredItemType
): ScreenplayBlock["formatId"] {
  switch (t) {
    case "BASMALA":
      return "basmala";
    case "scene_header_1":
      return "scene_header_1";
    case "scene_header_2":
      return "scene_header_2";
    case "scene_header_3":
      return "scene_header_3";
    case "ACTION":
      return "action";
    case "CHARACTER":
      return "character";
    case "DIALOGUE":
      return "dialogue";
    case "TRANSITION":
      return "transition";
    default:
      return assertUnreachable(t);
  }
}

export function toStructuredBlocks(
  result: UnstructuredResult
): ScreenplayBlock[] {
  return result.items.map((it) => ({
    formatId: mapTypeToFormatId(it.type),
    text: it.normalized.trimEnd(),
  }));
}

export function toStructuredText(blocks: ScreenplayBlock[]): string {
  return blocks
    .map((b) => (b.text ?? "").trimEnd())
    .filter((t) => t.length > 0)
    .join("\n");
}

import type { UnstructuredResult, UnstructuredItemType } from "./types";

export interface UnstructuredValidationError {
  code: string;
  message: string;
  itemIndex?: number;
}

export interface UnstructuredValidationResult {
  ok: boolean;
  errors: UnstructuredValidationError[];
}

const ELEMENTS: UnstructuredItemType[] = [
  "BASMALA",
  "scene_header_1",
  "scene_header_2",
  "scene_header_3",
  "ACTION",
  "CHARACTER",
  "DIALOGUE",
  "TRANSITION",
];

const ELEMENT_SET = new Set(ELEMENTS);

const DIALOGUE_SPEAKER_PREFIX_RE = /^\s*[^:：]{1,60}\s*[：:]\s*/u;

export function validateUnstructuredResult(
  result: UnstructuredResult
): UnstructuredValidationResult {
  const errors: UnstructuredValidationError[] = [];

  if (!result || result.version !== "unstructured-v1") {
    return {
      ok: false,
      errors: [
        {
          code: "INVALID_VERSION",
          message: "version يجب أن تكون unstructured-v1.",
        },
      ],
    };
  }

  if (!Array.isArray(result.items) || result.items.length === 0) {
    return {
      ok: false,
      errors: [{ code: "MISSING_ITEMS", message: "items[] مفقودة أو فارغة." }],
    };
  }

  for (let k = 0; k < result.items.length; k++) {
    const it = result.items[k]!;
    const expected = k + 1;

    if (it === undefined) {
      errors.push({
        code: "MISSING_ITEM",
        message: "تم العثور على عنصر مفقود داخل items[].",
        itemIndex: expected,
      });
      continue;
    }

    if (it.i !== expected) {
      errors.push({
        code: "INVALID_INDEX",
        message: "i يجب أن يكون تسلسليًا يبدأ من 1 بدون فجوات.",
        itemIndex: it.i,
      });
    }

    if (!ELEMENT_SET.has(it.type)) {
      errors.push({
        code: "UNKNOWN_ELEMENT",
        message: `type غير معتمد: ${String(it.type)}`,
        itemIndex: it.i,
      });
    }

    if (typeof it.raw !== "string" || typeof it.normalized !== "string") {
      errors.push({
        code: "INVALID_TEXT",
        message: "raw/normalized يجب أن يكونا نصوصًا.",
        itemIndex: it.i,
      });
      continue;
    }

    if (it.raw.trim() === "" || it.normalized.trim() === "") {
      errors.push({
        code: "EMPTY_TEXT",
        message: "ممنوع raw/normalized فارغ.",
        itemIndex: it.i,
      });
    }

    if (it.type === "CHARACTER") {
      if (!it.normalized.trim().endsWith(":")) {
        errors.push({
          code: "CHARACTER_MISSING_COLON",
          message: "CHARACTER.normalized يجب أن ينتهي بـ ':'",
          itemIndex: it.i,
        });
      }
    }

    if (it.type === "DIALOGUE") {
      const normalized = it.normalized.trim();
      if (DIALOGUE_SPEAKER_PREFIX_RE.test(normalized)) {
        errors.push({
          code: "DIALOGUE_CONTAINS_SPEAKER_PREFIX",
          message:
            "DIALOGUE يحتوي بادئة متكلم (اسم :)—يجب فصل CHARACTER كسطر مستقل.",
          itemIndex: it.i,
        });
      }

      if (/(---+|End of Extraction|هل ترغب|والباقي)/iu.test(normalized)) {
        errors.push({
          code: "LEAKED_META_TEXT",
          message: "تم رصد نصوص ميتا/فواصل داخل normalized.",
          itemIndex: it.i,
        });
      }
    }

    if (/(---+|End of Extraction|هل ترغب|والباقي)/iu.test(it.normalized)) {
      errors.push({
        code: "LEAKED_META_TEXT",
        message: "تم رصد نصوص ميتا/فواصل داخل normalized.",
        itemIndex: it.i,
      });
    }
  }

  return { ok: errors.length === 0, errors };
}

export function assertUnstructuredValid(v: UnstructuredValidationResult): void {
  if (!v.ok) {
    const msg =
      "Unstructured validation failed:\n" +
      v.errors
        .map((e) => `- [${e.code}] i=${e.itemIndex ?? "?"} ${e.message}`)
        .join("\n");
    throw new Error(msg);
  }
}

export type Theme = "light" | "dark";

export interface ThemeProviderOptions {
  attribute?: "class" | "data-theme";
  defaultTheme?: Theme;
  storageKey?: string;
  enableSystem?: boolean;
}

const resolveSystemTheme = (): Theme =>
  window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";

/**
 * @description مزود السمة (Theme Provider) الذي يدير حالة المظهر (فاتح/داكن/نظام) ويطبقه على الواجهة.
 *
 * @complexity الزمنية: O(1) | المكانية: O(1)
 *
 * @sideEffects
 *   - يتفاعل مع `localStorage` لحفظ التفضيلات واستعادتها.
 *   - يعدل `document.documentElement` (`classList` أو `attributes`) لتطبيق السمة.
 *
 * @dependencies
 *   - واجهات المتصفح المدمجة (`window.matchMedia`, `localStorage`, `document.documentElement`).
 *
 * @usedBy
 *   - نقطة الدخول الرئيسية للتطبيق (`main.tsx` أو ما شابه) لتهيئة حالة السمة.
 *
 * @example الاستخدام الأساسي
 * ```typescript
 * const provider = new ThemeProvider({ defaultTheme: 'dark' });
 * provider.init();
 * provider.toggleTheme();
 * ```
 */
export class ThemeProvider {
  private readonly options: Required<ThemeProviderOptions>;
  private currentTheme: Theme;

  constructor(options: ThemeProviderOptions = {}) {
    this.options = {
      attribute: options.attribute ?? "class",
      defaultTheme: options.defaultTheme ?? "dark",
      storageKey: options.storageKey ?? "filmlane.theme",
      enableSystem: options.enableSystem ?? false,
    };

    this.currentTheme = this.options.defaultTheme;
  }

  init(): Theme {
    if (typeof window === "undefined") return this.currentTheme;

    const fromStorage = window.localStorage.getItem(this.options.storageKey);
    const initial =
      fromStorage === "light" || fromStorage === "dark"
        ? (fromStorage as Theme)
        : this.options.enableSystem
          ? resolveSystemTheme()
          : this.options.defaultTheme;

    this.setTheme(initial);
    return initial;
  }

  setTheme(theme: Theme): void {
    this.currentTheme = theme;

    if (typeof document === "undefined") return;

    const root = document.documentElement;
    if (this.options.attribute === "class") {
      root.classList.remove("light", "dark");
      root.classList.add(theme);
    } else {
      root.setAttribute("data-theme", theme);
    }

    if (typeof window !== "undefined") {
      window.localStorage.setItem(this.options.storageKey, theme);
    }
  }

  getTheme(): Theme {
    return this.currentTheme;
  }

  toggleTheme(): Theme {
    const next = this.currentTheme === "dark" ? "light" : "dark";
    this.setTheme(next);
    return next;
  }
}

/**
 * @description دالة مساعدة (Factory Function) لإنشاء وضبط مزود السمة وتفعيله فوراً بخطوة واحدة.
 *
 * @param {ThemeProviderOptions} options - خيارات التهيئة لمزود السمة (اختيارية).
 *
 * @returns {ThemeProvider} كائن مزود السمة المُهيأ.
 *
 * @complexity الزمنية: O(1) | المكانية: O(1)
 *
 * @sideEffects
 *   - ينفذ دالة `init()` مما يسبب تأثيرات جانبية على `localStorage` والـ DOM.
 *
 * @usedBy
 *   - نقطة الدخول لبناء وتغليف حالة السمة بسرعة.
 *
 * @example بناء المزود
 * ```typescript
 * const themeProvider = createThemeProvider({ defaultTheme: 'light' });
 * ```
 */
export const createThemeProvider = (
  options: ThemeProviderOptions = {}
): ThemeProvider => {
  const provider = new ThemeProvider(options);
  provider.init();
  return provider;
};

import * as fs from "fs";
import * as path from "path";
import { CodeChunk } from "./types";
import { CHUNK_SIZE, CHUNK_OVERLAP, logger } from "./config";

const APPROX_CHARS_PER_TOKEN = 4;
const MAX_CHUNK_CHARS = CHUNK_SIZE * APPROX_CHARS_PER_TOKEN;
const OVERLAP_CHARS = CHUNK_OVERLAP * APPROX_CHARS_PER_TOKEN;

export function chunkFile(filePath: string): CodeChunk[] {
  const content = fs.readFileSync(filePath, "utf-8");
  const fileName = path.basename(filePath);
  const fileType = path.extname(filePath).slice(1);
  const language = getLanguage(fileType);

  if (
    fileType === "ts" ||
    fileType === "tsx" ||
    fileType === "js" ||
    fileType === "jsx"
  ) {
    return chunkCodeFile(content, filePath, fileName, fileType, language);
  } else if (fileType === "md") {
    return chunkMarkdownFile(content, filePath, fileName, fileType, language);
  } else {
    return chunkGenericFile(content, filePath, fileName, fileType, language);
  }
}

function chunkCodeFile(
  content: string,
  filePath: string,
  fileName: string,
  fileType: string,
  language: string
): CodeChunk[] {
  const lines = content.split("\n");
  const chunks: CodeChunk[] = [];
  let currentChunk = "";
  let startLine = 1;
  let chunkIndex = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (line === undefined) continue;
    if (currentChunk.length + line.length > MAX_CHUNK_CHARS) {
      if (currentChunk.trim()) {
        chunks.push({
          content: currentChunk.trim(),
          metadata: {
            filePath,
            fileName,
            fileType,
            chunkIndex,
            totalChunks: 0,
            language,
            startLine,
            endLine: i,
          },
        });
        chunkIndex++;

        const overlapLines = Math.floor(OVERLAP_CHARS / 80);
        const overlapStart = Math.max(0, i - overlapLines);
        currentChunk = lines.slice(overlapStart, i + 1).join("\n") + "\n";
        startLine = overlapStart + 1;
      }
    } else {
      currentChunk += line + "\n";
    }
  }

  if (currentChunk.trim()) {
    chunks.push({
      content: currentChunk.trim(),
      metadata: {
        filePath,
        fileName,
        fileType,
        chunkIndex,
        totalChunks: 0,
        language,
        startLine,
        endLine: lines.length,
      },
    });
  }

  chunks.forEach((chunk, idx) => {
    chunk.metadata.totalChunks = chunks.length;
    chunk.metadata.chunkIndex = idx;
  });

  return chunks;
}

function chunkMarkdownFile(
  content: string,
  filePath: string,
  fileName: string,
  fileType: string,
  language: string
): CodeChunk[] {
  const sections = content.split(/^#{1,6}\s+/m);
  const chunks: CodeChunk[] = [];
  let chunkIndex = 0;

  for (const section of sections) {
    if (!section.trim()) continue;

    const lines = section.split("\n");
    const sectionTitle = lines[0]?.trim() || "Untitled Section";

    if (section.length <= MAX_CHUNK_CHARS) {
      chunks.push({
        content: section.trim(),
        metadata: {
          filePath,
          fileName,
          fileType,
          chunkIndex,
          totalChunks: 0,
          section: sectionTitle,
          language,
        },
      });
      chunkIndex++;
    } else {
      const subChunks = splitLargeText(section, MAX_CHUNK_CHARS, OVERLAP_CHARS);
      subChunks.forEach((subChunk) => {
        chunks.push({
          content: subChunk.trim(),
          metadata: {
            filePath,
            fileName,
            fileType,
            chunkIndex,
            totalChunks: 0,
            section: sectionTitle,
            language,
          },
        });
        chunkIndex++;
      });
    }
  }

  chunks.forEach((chunk) => {
    chunk.metadata.totalChunks = chunks.length;
  });

  return chunks;
}

function chunkGenericFile(
  content: string,
  filePath: string,
  fileName: string,
  fileType: string,
  language: string
): CodeChunk[] {
  const chunks: CodeChunk[] = [];
  const textChunks = splitLargeText(content, MAX_CHUNK_CHARS, OVERLAP_CHARS);

  textChunks.forEach((chunk, idx) => {
    chunks.push({
      content: chunk.trim(),
      metadata: {
        filePath,
        fileName,
        fileType,
        chunkIndex: idx,
        totalChunks: textChunks.length,
        language,
      },
    });
  });

  return chunks;
}

function splitLargeText(
  text: string,
  maxChars: number,
  overlap: number
): string[] {
  const chunks: string[] = [];
  let start = 0;

  while (start < text.length) {
    const end = Math.min(start + maxChars, text.length);
    chunks.push(text.slice(start, end));
    start = end - overlap;

    if (start >= text.length - overlap) break;
  }

  return chunks;
}

function getLanguage(fileType: string): string {
  const languageMap: Record<string, string> = {
    ts: "typescript",
    tsx: "typescript",
    js: "javascript",
    jsx: "javascript",
    md: "markdown",
    json: "json",
    css: "css",
    html: "html",
    py: "python",
  };

  return languageMap[fileType] || "text";
}

export function getAllCodeFiles(rootDir: string): string[] {
  const files: string[] = [];
  const excludeDirs = [
    "node_modules",
    "dist",
    "build",
    ".git",
    "coverage",
    "test-results",
  ];
  const includeExtensions = [".ts", ".tsx", ".js", ".jsx", ".md"];

  function traverse(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        if (!excludeDirs.includes(entry.name)) {
          traverse(fullPath);
        }
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name);
        if (includeExtensions.includes(ext)) {
          files.push(fullPath);
        }
      }
    }
  }

  traverse(rootDir);
  logger.info(`Found ${files.length} code files to index`);
  return files;
}

