  InternalResolutionRoute,
  SuspicionBand,
} from "@editor/suspicion-engine/types";

export function toExternalBand(route: InternalResolutionRoute): SuspicionBand {
  return INTERNAL_TO_EXTERNAL_BAND[route];
}

