import type { Editor } from "@tiptap/core";
import {
  FILMLANE_CLIPBOARD_MIME,
  type ClipboardOrigin,
  type EditorClipboardOperationResult,
  type EditorClipboardPayload,
} from "../types/editor-clipboard";
import type { ScreenplayBlock } from "../utils/file-import";
import { htmlToScreenplayBlocks } from "../utils/file-import";

/**
 * @description أدوات مساعدة لعمليات الحافظة في محرر السيناريو
 */

// Hash function for text validation
const hashText = (value: string): string => {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
};

const clipboardResult = (
  result: EditorClipboardOperationResult
): EditorClipboardOperationResult => result;

// Validate clipboard payload structure
const isValidClipboardPayload = (
  value: unknown
): value is EditorClipboardPayload => {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<EditorClipboardPayload>;
  if (typeof candidate.plainText !== "string") return false;
  if (typeof candidate.hash !== "string") return false;
  if (typeof candidate.createdAt !== "string") return false;
  if (
    candidate.sourceKind !== "selection" &&
    candidate.sourceKind !== "document"
  )
    return false;
  if (candidate.blocks && !Array.isArray(candidate.blocks)) return false;
  return true;
};

/**
 * @description نسخ النص المحدد أو المستند كاملاً إلى الحافظة
 */
export const copyToClipboard = async (
  editor: Editor,
  selectionOnly = false
): Promise<EditorClipboardOperationResult> => {
  if (typeof navigator === "undefined" || !navigator.clipboard) {
    return clipboardResult({
      ok: false,
      status: "unavailable",
      message: "الحافظة غير متاحة في هذا المتصفح.",
    });
  }

  const hasSelection = !editor.state.selection.empty;
  const plainText = hasSelection
    ? editor.state.doc.textBetween(
        editor.state.selection.from,
        editor.state.selection.to,
        "\n"
      )
    : editor.getText();

  if (!plainText.trim()) {
    return clipboardResult({
      ok: false,
      status: selectionOnly ? "empty-selection" : "empty-document",
      message: selectionOnly
        ? "لا يوجد نص محدد لنسخه."
        : "لا يوجد محتوى يمكن نسخه.",
    });
  }

  const blocks =
    selectionOnly || !hasSelection
      ? undefined
      : htmlToScreenplayBlocks(editor.getHTML());

  const payload: EditorClipboardPayload = {
    plainText,
    ...(blocks !== undefined ? { blocks } : {}),
    sourceKind: hasSelection ? "selection" : "document",
    hash: hashText(plainText),
    createdAt: new Date().toISOString(),
  };

  const serializedPayload = JSON.stringify(payload);

  try {
    if (
      typeof ClipboardItem !== "undefined" &&
      typeof navigator.clipboard.write === "function"
    ) {
      const clipboardItem = new ClipboardItem({
        "text/plain": new Blob([plainText], { type: "text/plain" }),
        [FILMLANE_CLIPBOARD_MIME]: new Blob([serializedPayload], {
          type: FILMLANE_CLIPBOARD_MIME,
        }),
      });
      await navigator.clipboard.write([clipboardItem]);
      return clipboardResult({
        ok: true,
        status: "success",
        message: "تم نسخ النص إلى الحافظة.",
        textLength: plainText.length,
        sourceKind: payload.sourceKind,
      });
    }
  } catch {
    // fallback to plain text write when custom MIME fails.
  }

  if (typeof navigator.clipboard.writeText === "function") {
    try {
      await navigator.clipboard.writeText(plainText);
      return clipboardResult({
        ok: true,
        status: "success",
        message: "تم نسخ النص إلى الحافظة.",
        textLength: plainText.length,
        sourceKind: payload.sourceKind,
      });
    } catch {
      return clipboardResult({
        ok: false,
        status: "permission-denied",
        message: "رفض المتصفح صلاحية الكتابة إلى الحافظة.",
      });
    }
  }

  return clipboardResult({
    ok: false,
    status: "unavailable",
    message: "واجهة الكتابة إلى الحافظة غير متاحة.",
  });
};

/**
 * @description قص النص المحدد من المحرر ونسخه إلى الحافظة
 */
export const cutToClipboard = async (
  editor: Editor
): Promise<EditorClipboardOperationResult> => {
  if (editor.state.selection.empty) {
    return clipboardResult({
      ok: false,
      status: "empty-selection",
      message: "حدد نصاً قبل تنفيذ القص.",
    });
  }

  const copied = await copyToClipboard(editor, true);
  if (!copied.ok) return copied;

  const deleted = editor.chain().focus().deleteSelection().run();
  if (!deleted) {
    return clipboardResult({
      ok: false,
      status: "failed",
      message: "تم النسخ لكن تعذر حذف التحديد من المحرر.",
    });
  }

  return clipboardResult({
    ok: true,
    status: "success",
    message: "تم قص النص المحدد إلى الحافظة.",
    textLength: copied.textLength ?? 0,
    sourceKind: copied.sourceKind ?? "selection",
  });
};

/**
 * @description لصق النص من الحافظة إلى المحرر مع التصنيف التلقائي
 */
export const pasteFromClipboard = async (
  origin: ClipboardOrigin,
  importClassifiedText: (
    text: string,
    mode: "insert",
    context?: { classificationProfile?: "paste" | "generic-open" }
  ) => Promise<void>,
  importStructuredBlocks: (
    blocks: ScreenplayBlock[],
    mode: "insert"
  ) => Promise<void>
): Promise<EditorClipboardOperationResult> => {
  void origin;
  if (typeof navigator === "undefined" || !navigator.clipboard) {
    return clipboardResult({
      ok: false,
      status: "unavailable",
      message: "الحافظة غير متاحة في هذا المتصفح.",
    });
  }

  try {
    if (typeof navigator.clipboard.read === "function") {
      const items = await navigator.clipboard.read();
      let blocksToImport: ScreenplayBlock[] | null = null;
      let textToImport: string | null = null;

      for (const item of items) {
        if (item.types.includes(FILMLANE_CLIPBOARD_MIME)) {
          const payloadBlob = await item.getType(FILMLANE_CLIPBOARD_MIME);
          const payloadText = await payloadBlob.text();
          const parsed = JSON.parse(payloadText) as unknown;
          if (
            isValidClipboardPayload(parsed) &&
            parsed.hash === hashText(parsed.plainText)
          ) {
            if (parsed.blocks && parsed.blocks.length > 0) {
              blocksToImport = parsed.blocks;
              break;
            }

            if (parsed.plainText.trim()) {
              textToImport = parsed.plainText;
              break;
            }
          }
        }

        if (item.types.includes("text/plain")) {
          const plainBlob = await item.getType("text/plain");
          const text = await plainBlob.text();
          if (text.trim()) {
            textToImport = text;
            break;
          }
        }
      }

      if (blocksToImport) {
        await importStructuredBlocks(blocksToImport, "insert");
        return clipboardResult({
          ok: true,
          status: "success",
          message: "تم لصق كتل السيناريو من الحافظة.",
          textLength: blocksToImport
            .map((block) => block.text ?? "")
            .join("\n").length,
        });
      }

      if (textToImport) {
        await importClassifiedText(textToImport, "insert", {
          classificationProfile: "paste",
        });
        return clipboardResult({
          ok: true,
          status: "success",
          message: "تم لصق النص من الحافظة.",
          textLength: textToImport.length,
        });
      }
    }
  } catch {
    // fallback to readText below.
  }

  if (typeof navigator.clipboard.readText !== "function") {
    return clipboardResult({
      ok: false,
      status: "unavailable",
      message: "واجهة القراءة من الحافظة غير متاحة.",
    });
  }

  let text = "";
  try {
    text = await navigator.clipboard.readText();
  } catch {
    return clipboardResult({
      ok: false,
      status: "permission-denied",
      message: "رفض المتصفح صلاحية القراءة من الحافظة.",
    });
  }

  if (!text.trim()) {
    return clipboardResult({
      ok: false,
      status: "empty-clipboard",
      message: "لا يوجد نص قابل للصق في الحافظة.",
    });
  }

  await importClassifiedText(text, "insert", {
    classificationProfile: "paste",
  });
  return clipboardResult({
    ok: true,
    status: "success",
    message: "تم لصق النص من الحافظة.",
    textLength: text.length,
  });
};

import {
  FOOTER_HEIGHT_PX,
  FOOTER_TEMPLATE_LINE_COUNT,
  HEADER_TEMPLATE_LINE_COUNT,
  PAGE_HEIGHT_PX,
  PAGE_MARGIN_BOTTOM_PX,
  PAGE_MARGIN_LEFT_PX,
  PAGE_MARGIN_RIGHT_PX,
  PAGE_MARGIN_TOP_PX,
  PAGE_WIDTH_PX,
} from "../constants";
import {
  applyEditorFormatStyleVariables,
  LOCKED_EDITOR_FONT_FAMILY,
  LOCKED_EDITOR_FONT_SIZE,
  LOCKED_EDITOR_LINE_HEIGHT,
} from "../constants";

/**
 * @description أدوات مساعدة لتطبيق تخطيط وطباعة محرر السيناريو
 */

/**
 * @description تطبيق مقاييس التخطيط الثابتة على ورقة السيناريو
 */
export const applyLayoutMetrics = (sheet: HTMLDivElement): void => {
  sheet.style.setProperty("--page-width", `${PAGE_WIDTH_PX}px`);
  sheet.style.setProperty("--page-height", `${PAGE_HEIGHT_PX}px`);
  sheet.style.setProperty("--page-header-height", "77px");
  sheet.style.setProperty("--page-footer-height", `${FOOTER_HEIGHT_PX}px`);
  sheet.style.setProperty(
    "--page-header-line-count",
    `${HEADER_TEMPLATE_LINE_COUNT}`
  );
  sheet.style.setProperty(
    "--page-footer-line-count",
    `${FOOTER_TEMPLATE_LINE_COUNT}`
  );
  sheet.style.setProperty("--page-margin-top", `${PAGE_MARGIN_TOP_PX}px`);
  sheet.style.setProperty("--page-margin-bottom", `${PAGE_MARGIN_BOTTOM_PX}px`);
  sheet.style.setProperty("--page-margin-left", `${PAGE_MARGIN_LEFT_PX}px`);
  sheet.style.setProperty("--page-margin-right", `${PAGE_MARGIN_RIGHT_PX}px`);
  applyEditorFormatStyleVariables(sheet.style);
};

/**
 * @description تطبيق خصائص الطباعة الثابتة على عنصر المحرر
 */
export const applyEditorTypography = (target: HTMLElement): void => {
  target.style.setProperty(
    "font-family",
    LOCKED_EDITOR_FONT_FAMILY,
    "important"
  );
  target.style.setProperty("font-size", LOCKED_EDITOR_FONT_SIZE, "important");
  target.style.setProperty(
    "line-height",
    LOCKED_EDITOR_LINE_HEIGHT,
    "important"
  );
  target.style.setProperty("direction", "rtl");
  target.style.setProperty("font-weight", "700");
};

import type { Editor } from "@tiptap/core";
import { CONTENT_HEIGHT_PX } from "../constants";

/**
 * @description إدارة نموذج الصفحات ومراقبتها في محرر السيناريو
 */
export class EditorPageModel {
  private editor: Editor;
  private body: HTMLDivElement;
  private hasPagesExtension: boolean;
  private resizeObserver: ResizeObserver | null = null;
  private paginationObserver: MutationObserver | null = null;
  private estimatedPages = 1;
  private onPageModelChange?: () => void;

  constructor(
    editor: Editor,
    body: HTMLDivElement,
    hasPagesExtension: boolean,
    onPageModelChange?: () => void
  ) {
    this.editor = editor;
    this.body = body;
    this.hasPagesExtension = hasPagesExtension;
    if (onPageModelChange) {
      this.onPageModelChange = onPageModelChange;
    }
  }

  /**
   * @description ربط مراقبي نموذج الصفحات
   */
  bindObservers(): void {
    if (typeof window !== "undefined") {
      window.addEventListener("resize", this.handleWindowResize);
    }

    if (typeof ResizeObserver === "undefined") return;

    const attachObserver = (): void => {
      const editorRoot = this.body.querySelector<HTMLElement>(
        ".filmlane-prosemirror-root, .ProseMirror"
      );
      if (!editorRoot) return;

      this.resizeObserver?.disconnect();
      this.resizeObserver = new ResizeObserver(() => {
        this.refreshPageModel();
        this.onPageModelChange?.();
      });
      this.resizeObserver.observe(editorRoot);
    };

    attachObserver();
    window.setTimeout(attachObserver, 0);

    if (typeof MutationObserver === "undefined") return;

    this.paginationObserver?.disconnect();
    this.paginationObserver = new MutationObserver(() => {
      this.refreshPageModel();
      this.onPageModelChange?.();
    });
    this.paginationObserver.observe(this.body, {
      childList: true,
      subtree: true,
    });
  }

  /**
   * @description فصل مراقبي نموذج الصفحات
   */
  disconnectObservers(): void {
    if (typeof window !== "undefined") {
      window.removeEventListener("resize", this.handleWindowResize);
    }
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
    this.paginationObserver?.disconnect();
    this.paginationObserver = null;
  }

  /**
   * @description تحديث نموذج الصفحات
   */
  refreshPageModel(force = false): void {
    const visiblePages = this.normalizeTrailingPagination();
    const pagesFromStorage = this.getPagesFromExtensionStorage();
    const nextPages =
      visiblePages ??
      pagesFromStorage ??
      (this.hasPagesExtension
        ? this.estimatedPages
        : this.measurePageEstimate());

    if (!force && nextPages === this.estimatedPages) return;

    this.estimatedPages = nextPages;
  }

  /**
   * @description إخفاء الصفحات الذيلية الفارغة التي يولّدها امتداد Pages
   *   بعد آخر كتلة محتوى فعلية. نُبقي فوتر الصفحة الأخيرة الظاهرة ونزيل فقط
   *   الفجوة/الهيدر اللاحقين والـ page breaks التالية الفارغة.
   *
   * @returns {number | null} عدد الصفحات الظاهر فعليًا بعد التطبيع، أو `null`
   *   إذا لم تتوفر بعد معطيات كافية من DOM.
   */
  private normalizeTrailingPagination(): number | null {
    const editorRoot = this.body.querySelector<HTMLElement>(
      ".filmlane-prosemirror-root, .ProseMirror"
    );
    if (!editorRoot) return null;

    const paginationRoot = editorRoot.querySelector<HTMLElement>(
      "[data-tiptap-pagination]"
    );
    if (!paginationRoot) return null;

    const pageBreaks = Array.from(
      paginationRoot.querySelectorAll<HTMLElement>(".tiptap-page-break")
    );
    if (pageBreaks.length === 0) return null;

    for (const pageBreak of pageBreaks) {
      delete pageBreak.dataset["filmlaneTerminalPage"];
      delete pageBreak.dataset["filmlaneTrailingPage"];
      pageBreak.style.removeProperty("display");
    }

    const contentBlocks = Array.from(
      editorRoot.querySelectorAll<HTMLElement>("[data-type]")
    );
    const lastContentBlock = contentBlocks.at(-1);
    if (!lastContentBlock) return null;

    const lastContentPage = this.resolveLastContentPage(lastContentBlock);
    if (!lastContentPage || lastContentPage < 1) return null;

    const terminalBreak = pageBreaks.find((pageBreak) =>
      pageBreak.querySelector(
        `.tiptap-page-footer[data-footer-page-number="${lastContentPage}"]`
      )
    );

    if (!terminalBreak) {
      return lastContentPage;
    }

    const terminalBreakIndex = pageBreaks.indexOf(terminalBreak);
    if (terminalBreakIndex < 0) {
      return lastContentPage;
    }

    terminalBreak.dataset["filmlaneTerminalPage"] = "true";

    for (
      let index = terminalBreakIndex + 1;
      index < pageBreaks.length;
      index += 1
    ) {
      const trailingBreak = pageBreaks[index];
      if (!trailingBreak) continue;
      trailingBreak.dataset["filmlaneTrailingPage"] = "true";
      trailingBreak.style.setProperty("display", "none", "important");
    }

    const terminalFooter = terminalBreak.querySelector<HTMLElement>(
      ".tiptap-page-footer"
    );
    if (terminalFooter) {
      const paginationRect = paginationRoot.getBoundingClientRect();
      const footerRect = terminalFooter.getBoundingClientRect();
      const minHeight = Math.max(
        1,
        Math.ceil(footerRect.bottom - paginationRect.top)
      );
      editorRoot.style.minHeight = `${minHeight}px`;
    }

    return lastContentPage;
  }

  /**
   * @description تحديد الصفحة الفعلية لآخر عنصر محتوى.
   *   نفضّل واجهة امتداد Pages نفسها، ونرجع إلى قياس مواضع الفوترات عند الحاجة.
   */
  private resolveLastContentPage(lastContentBlock: HTMLElement): number | null {
    const storage = this.editor.storage as {
      pages?: { getPageForPosition?: (pos: number) => number };
    };
    const getPageForPosition = storage.pages?.getPageForPosition;

    if (typeof getPageForPosition === "function") {
      try {
        const position = this.editor.view.posAtDOM(lastContentBlock, 0);
        const page = getPageForPosition(position);
        if (typeof page === "number" && Number.isFinite(page) && page >= 1) {
          return Math.floor(page);
        }
      } catch {
        /* fallback إلى القياس الهندسي */
      }
    }

    const footers = Array.from(
      this.body.querySelectorAll<HTMLElement>(".tiptap-page-footer")
    );
    if (footers.length === 0) return 1;

    const lastBottom = lastContentBlock.getBoundingClientRect().bottom;
    for (const footer of footers) {
      const footerTop = footer.getBoundingClientRect().top;
      if (lastBottom < footerTop) {
        const pageNumber = Number(footer.dataset["footerPageNumber"] ?? "0");
        if (Number.isFinite(pageNumber) && pageNumber >= 1) {
          return pageNumber;
        }
      }
    }

    return footers.length + 1;
  }

  /**
   * @description قياس تقدير عدد الصفحات
   */
  private measurePageEstimate(): number {
    const editorRoot = this.body.querySelector<HTMLElement>(
      ".filmlane-prosemirror-root, .ProseMirror"
    );
    if (!editorRoot) return 1;

    const pageBodyHeight = Math.max(1, CONTENT_HEIGHT_PX);
    const contentHeight = Math.max(1, editorRoot.scrollHeight);
    return Math.max(1, Math.ceil(contentHeight / pageBodyHeight));
  }

  /**
   * @description الحصول على عدد الصفحات من امتداد الصفحات
   */
  private getPagesFromExtensionStorage(): number | null {
    const storage = this.editor.storage as {
      pages?: { getPageCount?: () => number };
    };
    const pages = storage.pages?.getPageCount?.();
    if (typeof pages !== "number" || !Number.isFinite(pages)) return null;
    return Math.max(1, Math.floor(pages));
  }

  /**
   * @description معالج تغيير حجم النافذة
   */
  private handleWindowResize = (): void => {
    this.refreshPageModel();
    this.onPageModelChange?.();
  };

  /**
   * @description الحصول على عدد الصفحات المقدر
   */
  get estimatedPagesCount(): number {
    return this.estimatedPages;
  }
}

import type { ScreenplayBlock } from "../file-import/document-model";
import { sanitizeExportFileBaseName } from "./shared";

interface ExportAsClassifiedOptions {
  fileNameBase?: string;
  blocks: ScreenplayBlock[];
}

const mapFormatIdToClassifiedElement = (
  formatId: ScreenplayBlock["formatId"]
): string => {
  switch (formatId) {
    case "basmala":
      return "BASMALA";
    case "scene_header_1":
      return "SCENE-HEADER-1";
    case "scene_header_2":
      return "SCENE-HEADER-2";
    case "scene_header_3":
      return "SCENE-HEADER-3";
    case "scene_header_top_line":
      return "ACTION";
    case "action":
      return "ACTION";
    case "character":
      return "CHARACTER";
    case "dialogue":
      return "DIALOGUE";
    case "parenthetical":
      return "PARENTHETICAL";
    case "transition":
      return "TRANSITION";
    default:
      return "ACTION";
  }
};

const normalizeText = (text: string): string => {
  return text.replace(/\s+/g, " ").trim();
};

export const generateClassifiedText = (blocks: ScreenplayBlock[]): string => {
  const lines: string[] = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    if (!block) continue;
    const text = normalizeText(block.text);
    if (!text) continue;

    if (block.formatId === "scene_header_top_line") {
      continue;
    }

    const element = mapFormatIdToClassifiedElement(block.formatId);
    if (!element) {
      continue;
    }
    let finalValue = text;

    if (element === "CHARACTER") {
      if (!finalValue.endsWith(":")) {
        finalValue += " :";
      }
    }

    lines.push(`${element} = ${finalValue}`);
  }

  return lines.join("\n");
};

export const exportAsClassified = ({
  fileNameBase,
  blocks,
}: ExportAsClassifiedOptions): void => {
  const textContent = generateClassifiedText(blocks);
  const safeName =
    (sanitizeExportFileBaseName(fileNameBase ?? "النص_المصنف") ||
      "النص_المصنف") + ".txt";

  const blob = new Blob([textContent], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = safeName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

import {
  buildPayloadMarker,
  createPayloadFromBlocks,
  encodeScreenplayPayload,
  type ScreenplayBlock,
} from "../file-import/document-model";

import {
  type DocxParagraphPreset,
  getDocxPresetForFormat,
  normalizeText,
  pointsToTwips,
  resolveBlocksForExport,
} from "./shared";

type DocxAlignmentType = typeof import("docx").AlignmentType;
type DocxParagraphClass = typeof import("docx").Paragraph;
type DocxTextRunClass = typeof import("docx").TextRun;

interface DocxModules {
  AlignmentType: DocxAlignmentType;
  Paragraph: DocxParagraphClass;
  TextRun: DocxTextRunClass;
}

export interface ExportToDocxOptions {
  blocks?: ScreenplayBlock[];
}

const DEFAULT_DOCX_FONT = "AzarMehrMonospaced-San";

const DEFAULT_DOCX_SIZE_HALF_POINTS = 24;

const mapAlignment = (
  AlignmentType: DocxAlignmentType,

  alignment: DocxParagraphPreset["alignment"]
) => {
  switch (alignment) {
    case "center":
      return AlignmentType.CENTER;

    case "left":
      return AlignmentType.LEFT;

    case "justify":
      return AlignmentType.JUSTIFIED;

    default:
      return AlignmentType.RIGHT;
  }
};

/**

 * يبني فقرة DOCX واحدة من كتلة سيناريو.

 */

const buildDocxParagraph = (
  block: ScreenplayBlock,

  modules: DocxModules
) => {
  const { AlignmentType, Paragraph, TextRun } = modules;

  const preset = getDocxPresetForFormat(block.formatId);

  return new Paragraph({
    bidirectional: true,

    alignment: mapAlignment(AlignmentType, preset.alignment),

    spacing: {
      before: pointsToTwips(preset.spacingBeforePt ?? 0),

      after: pointsToTwips(preset.spacingAfterPt ?? 0),
    },

    ...(preset.indentStartTwip !== undefined ||
    preset.indentEndTwip !== undefined
      ? {
          indent: {
            ...(preset.indentStartTwip !== undefined
              ? { start: preset.indentStartTwip }
              : {}),
            ...(preset.indentEndTwip !== undefined
              ? { end: preset.indentEndTwip }
              : {}),
          },
        }
      : {}),

    children: [
      new TextRun({
        text: normalizeText(block.text),

        font: DEFAULT_DOCX_FONT,

        size: DEFAULT_DOCX_SIZE_HALF_POINTS,

        ...(preset.bold !== undefined ? { bold: preset.bold } : {}),

        ...(preset.italics !== undefined ? { italics: preset.italics } : {}),
      }),
    ],
  });
};

/**

 * يبني فقرة scene_header_top_line خاصة:

 * header-1 (يمين) + tab + header-2 (يسار) في نفس السطر.

 *

 * في DOCX: نستخدم tab stops لمحاكاة flex layout.

 * header-1 على اليمين، header-2 على اليسار باستخدام right tab stop.

 */

const buildTopLineParagraph = (
  header1Text: string,

  header2Text: string,

  modules: DocxModules
) => {
  const { Paragraph, TextRun, AlignmentType } = modules;

  const h1 = normalizeText(header1Text);

  const h2 = normalizeText(header2Text);

  return new Paragraph({
    bidirectional: true,

    alignment: AlignmentType.RIGHT,

    spacing: {
      before: pointsToTwips(12),

      after: pointsToTwips(0),
    },

    children: [
      new TextRun({
        text: h1,

        font: DEFAULT_DOCX_FONT,

        size: DEFAULT_DOCX_SIZE_HALF_POINTS,

        bold: true,
      }),

      // إضافة مسافات بين header-1 و header-2

      new TextRun({
        text: `\t${h2}`,

        font: DEFAULT_DOCX_FONT,

        size: DEFAULT_DOCX_SIZE_HALF_POINTS,

        bold: true,
      }),
    ],

    tabStops: [
      {
        type: "left" as const,

        position: 8640, // ~6 inches (نهاية السطر تقريبًا)
      },
    ],
  });
};

export const exportToDocx = async (
  content: string,

  filename: string = "screenplay.docx",

  options?: ExportToDocxOptions
): Promise<void> => {
  const docxLib = await import("docx");

  const { AlignmentType, Document, Packer, Paragraph, TextRun } = docxLib;

  const modules: DocxModules = {
    AlignmentType,

    Paragraph,

    TextRun,
  };

  const blocks = resolveBlocksForExport(content, options?.blocks);

  const payload = createPayloadFromBlocks(blocks, {
    font: "AzarMehrMonospaced-San",

    size: "12pt",
  });

  const payloadMarker = buildPayloadMarker(encodeScreenplayPayload(payload));

  const paragraphs: InstanceType<DocxParagraphClass>[] = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    if (!block) continue;

    const text = normalizeText(block.text);

    if (!text && block.formatId !== "scene_header_top_line") continue;

    // scene_header_top_line: wrapper — نتخطاه (الأبناء header-1 + header-2 موجودين)

    if (block.formatId === "scene_header_top_line") {
      continue;
    }

    // دمج scene_header_1 + scene_header_2 في سطر واحد

    if (block.formatId === "scene_header_1") {
      const next = blocks[i + 1];

      if (next && next.formatId === "scene_header_2") {
        paragraphs.push(buildTopLineParagraph(text, next.text, modules));

        i += 1;
      } else {
        paragraphs.push(buildDocxParagraph(block, modules));
      }

      continue;
    }

    paragraphs.push(buildDocxParagraph(block, modules));
  }

  if (paragraphs.length === 0) {
    paragraphs.push(
      new Paragraph({
        bidirectional: true,

        children: [
          new TextRun({
            text: "",

            font: DEFAULT_DOCX_FONT,

            size: DEFAULT_DOCX_SIZE_HALF_POINTS,
          }),
        ],
      })
    );
  }

  // Marker مخفي لاسترجاع payload 1:1 عند إعادة فتح الملف.

  paragraphs.push(
    new Paragraph({
      bidirectional: true,

      spacing: { before: 0, after: 0 },

      children: [
        new TextRun({
          text: payloadMarker,

          color: "FFFFFF",

          size: 2,

          font: DEFAULT_DOCX_FONT,
        }),
      ],
    })
  );

  const doc = new Document({
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: 1440,

              right: 1440,

              bottom: 1440,

              left: 1440,
            },
          },
        },

        children: paragraphs,
      },
    ],
  });

  const blob = await Packer.toBlob(doc);

  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");

  link.href = url;

  link.download = filename;

  document.body.appendChild(link);

  link.click();

  document.body.removeChild(link);

  URL.revokeObjectURL(url);
};

