import type { ScreenplayBlock } from "../file-import/document-model";
import {
  type BlockExportRequest,
  downloadBlob,
  normalizeText,
  resolveBlocksForExport,
  sanitizeExportFileBaseName,
} from "./shared";

/**
 * يبني نص Fountain من كتل السيناريو.
 *
 * قواعد Fountain للعربي:
 * - `@` prefix لأسماء الشخصيات (العربية ليس فيها UPPERCASE)
 * - `.` prefix لعناوين المشاهد (لا تبدأ بـ INT./EXT.)
 * - `> text <` للنص المركزي (بسملة، انتقال)
 * - بين الأقواس: (نص) بين شخصية وحوار
 *
 * قواعد الترتيب:
 * - شخصية → حوار (أو بين أقواس → حوار)
 * - حوار → شخصية أو أكشن أو انتقال (مش حوار تاني إلا لو نفس الشخصية)
 */
const buildFountainString = (blocks: ScreenplayBlock[]): string => {
  const lines: string[] = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    if (!block) continue;
    const text = normalizeText(block.text);
    if (!text) continue;

    switch (block.formatId) {
      case "basmala":
        lines.push("", `> ${text} <`, "");
        break;

      case "scene_header_top_line":
        // wrapper فقط — نتخطاه
        break;

      case "scene_header_1": {
        // دمج scene_header_1 + scene_header_2 المتتاليين
        const next = blocks[i + 1];
        let heading = text;
        if (next && next.formatId === "scene_header_2") {
          const nextText = normalizeText(next.text);
          if (nextText) {
            heading = `${text} - ${nextText}`;
          }
          i += 1;
        }
        // لو في scene_header_3 بعدهم
        const afterNext = blocks[i + 1];
        if (afterNext && afterNext.formatId === "scene_header_3") {
          const h3Text = normalizeText(afterNext.text);
          if (h3Text) {
            heading = `${heading}\n${h3Text}`;
          }
          i += 1;
        }
        lines.push("", `.${heading}`, "");
        break;
      }

      case "scene_header_2":
      case "scene_header_3":
        lines.push("", `.${text}`, "");
        break;

      case "action":
        lines.push("", text, "");
        break;

      case "character":
        lines.push("", `@${text}`);
        break;

      case "dialogue":
        lines.push(text, "");
        break;

      case "parenthetical": {
        const cleaned = text.replace(/^\(|\)$/g, "");
        lines.push(`(${cleaned})`);
        break;
      }

      case "transition":
        lines.push("", `> ${text} <`, "");
        break;

      default:
        lines.push("", text, "");
        break;
    }
  }

  // تنظيف الأسطر الفارغة المتتالية (3+ → 2)
  return (
    lines
      .join("\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim() + "\n"
  );
};

export const exportAsFountain = (request: BlockExportRequest): void => {
  const blocks = resolveBlocksForExport(request.html, request.blocks);
  const fileBase = sanitizeExportFileBaseName(request.fileNameBase);

  const fountainText = buildFountainString(blocks);

  const blob = new Blob([fountainText], {
    type: "text/plain;charset=utf-8",
  });
  downloadBlob(`${fileBase}.fountain`, blob);
};

import { jsPDF } from "jspdf";
import DOMPurify from "isomorphic-dompurify";
import {
  type ExportRequest,
  buildFullHtmlDocument,
  sanitizeExportFileBaseName,
} from "./shared";

/**
 * يُصدّر المستند كـ PDF عبر jsPDF + html2canvas.
 *
 * الإصلاح: النسخة القديمة كانت تحقن HTML خام بدون أي CSS.
 * الآن: يبني HTML كامل عبر buildFullHtmlDocument (نفس تنسيقات المحرر)
 * ثم يحوّله لـ PDF.
 */
export const exportAsPdf = async (request: ExportRequest): Promise<void> => {
  const fileBase = sanitizeExportFileBaseName(request.fileNameBase);

  // بناء HTML كامل بالتنسيقات — مثل ما المستخدم شايفه في المحرر
  const styledHtml = buildFullHtmlDocument(request.html, request.title);

  // Sanitize the HTML before injecting it to prevent XSS vulnerabilities
  const sanitizedHtml = DOMPurify.sanitize(styledHtml, {
    WHOLE_DOCUMENT: true,
  });

  // BUG-010: jsPDF.html() يستدعي html2canvas داخلياً، و html2canvas
  // يعدّل viewport المستند بشكل مؤقت لالتقاط المحتوى — ما يسبب
  // تغيير زوم المحرر وتحريك الـ scroll لدى المستخدم.
  //
  // الحل:
  // 1. نلتقط scrollX/scrollY قبل التشغيل ونُعيدها بعده.
  // 2. نستخدم iframe مستقلاً ذا viewport ثابت بدل document الرئيسي،
  //    فيعمل html2canvas داخله بدون مساس بصفحة المستخدم.
  const previousScrollX = window.scrollX;
  const previousScrollY = window.scrollY;

  const iframe = document.createElement("iframe");
  iframe.setAttribute("aria-hidden", "true");
  iframe.style.position = "fixed";
  iframe.style.left = "-10000px";
  iframe.style.top = "0";
  iframe.style.width = "794px";
  iframe.style.height = "1123px";
  iframe.style.border = "0";
  iframe.style.pointerEvents = "none";
  iframe.style.visibility = "hidden";
  document.body.appendChild(iframe);

  try {
    const iframeDoc = iframe.contentDocument;
    if (!iframeDoc) {
      throw new Error("pdf-export: تعذّر تحضير مستند داخلي لـ jsPDF");
    }

    iframeDoc.open();
    iframeDoc.write(sanitizedHtml);
    iframeDoc.close();

    // ننتظر حتى يبني المتصفح شجرة DOM داخل iframe قبل الإلتقاط
    await new Promise<void>((resolve) => {
      if (iframeDoc.readyState === "complete") {
        resolve();
        return;
      }
      iframe.addEventListener("load", () => resolve(), { once: true });
    });

    const innerBody = iframeDoc.body;

    const pdf = new jsPDF({
      orientation: "portrait",
      unit: "pt",
      format: "a4",
      compress: true,
    });
    pdf.setR2L(true);

    await pdf.html(innerBody, {
      x: 24,
      y: 24,
      margin: [24, 24, 24, 24],
      autoPaging: "text",
      width: 547,
      windowWidth: 794,
      html2canvas: {
        scale: 1.5,
        useCORS: true,
        logging: false,
        // نمنع html2canvas من تحريك صفحة المستخدم أثناء الالتقاط
        scrollX: 0,
        scrollY: 0,
        windowWidth: 794,
        windowHeight: 1123,
      },
    });

    pdf.save(`${fileBase}.pdf`);
  } finally {
    iframe.remove();
    // استرجاع موضع التمرير الأصلي كضمان إضافي حتى لا يقفز المحرر
    window.scrollTo(previousScrollX, previousScrollY);
  }
};

