"use client";
/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 */
import React, { useState } from "react";
import { RotateCcwIcon, ChevronLeftIcon } from "./icons";
import Spinner from "./Spinner";
import { AnimatePresence, motion } from "framer-motion";
import { Compare } from "./ui/compare";
import { CardSpotlight } from "@/components/aceternity/card-spotlight";

interface CanvasProps {
  displayImageUrl: string | null;
  videoUrl?: string | null;
  compareImages?: { left: string; right: string } | null;
  onStartOver: () => void;
  isLoading: boolean;
  loadingMessage: string;
  onSelectPose: (index: number) => void;
  poseInstructions: string[];
  currentPoseIndex: number;
  availablePoseKeys: string[];
}

const Canvas: React.FC<CanvasProps> = ({
  displayImageUrl,
  videoUrl,
  compareImages,
  onStartOver,
  isLoading,
  loadingMessage,
}) => {
  const [] = useState(false);

  // 1. حالة العرض: فيديو (اختبار ضغط)
  if (videoUrl) {
    return (
      <CardSpotlight className="overflow-hidden rounded-[22px] w-full h-full flex items-center justify-center p-4 relative animate-zoom-in bg-black/8">
        <button
          onClick={onStartOver}
          className="absolute top-4 left-4 z-30 flex items-center justify-center text-center bg-white/[0.04] text-white font-bold py-2 px-4 rounded-full text-xs backdrop-blur-xl hover:bg-white/8"
        >
          <ChevronLeftIcon className="w-4 h-4 mr-2" />
          Back to Image
        </button>
        <video
          src={videoUrl}
          controls
          autoPlay
          loop
          className="max-w-full max-h-full rounded-[16px] shadow-2xl border border-white/8"
        />
      </CardSpotlight>
    );
  }

  // 2. حالة العرض: مقارنة (A/B Testing)
  if (compareImages) {
    return (
      <CardSpotlight className="overflow-hidden rounded-[22px] w-full h-full flex flex-col items-center justify-center p-4 relative animate-fade-in">
        <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-black/14 text-white px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest z-30 shadow-lg border border-white/8">
          A/B Comparison Mode
        </div>
        <Compare
          firstImage={compareImages.left}
          secondImage={compareImages.right}
          className="w-full h-full max-w-3xl max-h-[80vh] rounded-[16px] shadow-2xl border border-white/8"
          slideMode="drag"
        />
        <div className="mt-4 flex gap-8 text-xs font-bold uppercase tracking-widest text-white/45">
          <span>Left: Previous Design</span>
          <span>Right: Current Simulation</span>
        </div>
      </CardSpotlight>
    );
  }

  // 3. حالة العرض: صورة عادية (Standard Fit)
  return (
    <CardSpotlight className="overflow-hidden rounded-[22px] w-full h-full flex items-center justify-center p-4 relative animate-zoom-in group bg-black/8">
      {/* CSS Animation for Scanning Effect defined inline for scope */}
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>

      {/* Start Over Button */}
      <button
        onClick={onStartOver}
        className="absolute top-4 left-4 z-30 flex items-center justify-center text-center bg-white/[0.04] border border-white/8 text-white font-semibold py-2 px-4 rounded-full transition-all duration-200 ease-in-out hover:bg-white/8 hover:border-white/12 active:scale-95 text-sm backdrop-blur-xl"
      >
        <RotateCcwIcon className="w-4 h-4 mr-2" />
        Start Over
      </button>

      {/* Image Display or Placeholder */}
      <div className="relative w-full h-full flex items-center justify-center">
        {displayImageUrl ? (
          <img
            key={displayImageUrl} // Use key to force re-render
            src={displayImageUrl}
            alt="Virtual try-on model"
            className="max-w-full max-h-full object-contain transition-opacity duration-500 animate-fade-in rounded-lg shadow-md"
          />
        ) : (
          <div className="w-[400px] h-[600px] bg-white/6 border border-white/8 rounded-[16px] flex flex-col items-center justify-center">
            <Spinner />
            <p className="text-md font-serif text-white/68 mt-4">
              Initializing Reality Engine...
            </p>
          </div>
        )}

        <AnimatePresence>
          {isLoading && (
            <motion.div
              className="absolute inset-0 bg-black/40 backdrop-blur-xl flex flex-col items-center justify-center z-20 rounded-[16px]"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              <Spinner />
              {loadingMessage && (
                <p className="text-lg font-serif text-white/85 mt-4 text-center px-4 animate-pulse">
                  {loadingMessage}
                </p>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Basic Pose Controls (Visual only for now) */}
      {displayImageUrl && !isLoading && (
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-30 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
          <div className="flex items-center justify-center gap-2 bg-white/[0.04] backdrop-blur-xl rounded-full p-2 border border-white/8 shadow-sm">
            <span className="text-[10px] font-bold uppercase tracking-widest text-white/55 px-2">
              Static View
            </span>
          </div>
        </div>
      )}
    </CardSpotlight>
  );
};

export default Canvas;

"use client";
/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 */

import React from "react";
import { motion } from "framer-motion";

export interface SceneCardData {
  id: string;
  sceneNumber: string;
  slugline: string;
  time: "DAY" | "NIGHT";
  costumeId: string | null;
  isContinuous: boolean;
}

interface ContinuityTimelineProps {
  scenes: SceneCardData[];
  activeSceneId: string;
  onSceneSelect: (id: string) => void;
  onFixContinuity: (targetSceneId: string, sourceOutfitId: string) => void;
}

const ContinuityTimeline: React.FC<ContinuityTimelineProps> = ({
  scenes,
  activeSceneId,
  onSceneSelect,
  onFixContinuity,
}) => {
  return (
    <div className="w-full bg-black/14 border-t border-white/8 flex flex-col">
      <div className="px-6 py-2 flex justify-between items-center bg-black/14">
        <h3 className="text-[10px] font-bold text-white/45 uppercase tracking-widest flex items-center gap-2">
          <span className="w-1.5 h-1.5 rounded-full bg-red-500/80 animate-pulse"></span>
          Timeline Sequence
        </h3>
        <div className="flex gap-1">
          {Array.from({ length: 20 }).map((_, i) => (
            <div
              key={i}
              className={`w-px h-1 ${i % 5 === 0 ? "bg-white/55 h-2" : "bg-white/18"}`}
            ></div>
          ))}
        </div>
      </div>

      <div className="flex overflow-x-auto p-4 gap-1 scrollbar-hide relative min-h-[100px] items-center">
        <div className="absolute top-1/2 left-0 w-full h-px bg-white/18 -z-0"></div>

        {scenes.map((scene, index) => {
          const prevScene = scenes[index - 1];
          const hasRaccordError =
            scene.isContinuous &&
            prevScene &&
            prevScene.costumeId !== scene.costumeId;
          const isActive = scene.id === activeSceneId;

          return (
            <div
              key={scene.id}
              className="relative flex items-center group z-10"
            >
              {hasRaccordError && (
                <button
                  onClick={() =>
                    prevScene.costumeId &&
                    onFixContinuity(scene.id, prevScene.costumeId)
                  }
                  className="absolute -top-10 left-1/2 -translate-x-1/2 bg-red-600/20 border border-red-500/50 text-red-300 text-[9px] font-bold px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap backdrop-blur-xl"
                >
                  Fix Continuity
                </button>
              )}

              <motion.button
                onClick={() => onSceneSelect(scene.id)}
                whileHover={{ y: -2 }}
                className={`
                  relative w-28 h-16 rounded-[22px] overflow-hidden flex flex-col justify-between p-2 text-left transition-all border backdrop-blur-xl
                  ${isActive ? "bg-white/8 border-white/20 shadow-[0_0_15px_rgba(212,180,131,0.1)]" : "bg-black/18 border-white/8 hover:border-white/20"}
                  ${hasRaccordError ? "border-red-500/50 ring-1 ring-red-500/30" : ""}
                `}
              >
                <div className="flex justify-between items-center w-full">
                  <span className="text-[9px] font-mono text-white/55 font-bold">
                    {scene.sceneNumber}
                  </span>
                  <div
                    className={`w-1.5 h-1.5 rounded-full ${scene.costumeId ? "bg-green-500" : "bg-white/18"}`}
                  ></div>
                </div>

                <div>
                  <span
                    className={`text-[8px] font-bold px-1 rounded ${scene.time === "DAY" ? "bg-blue-600/30 text-blue-200" : "bg-purple-600/30 text-purple-200"}`}
                  >
                    {scene.time}
                  </span>
                  <p className="text-[9px] text-white/55 truncate mt-1 font-mono uppercase opacity-85">
                    {scene.slugline.split(".")[1] || scene.slugline}
                  </p>
                </div>
              </motion.button>

              {/* Connector Line */}
              {index < scenes.length - 1 && (
                <div
                  className={`w-4 h-0.5 ${scene.isContinuous ? "bg-white/55" : "bg-white/18 border-t border-dashed border-white/45 bg-transparent"}`}
                ></div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ContinuityTimeline;

