"use client";
import { logger } from "@/lib/ai/utils/logger";
/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 */
import React, { useState } from "react";
import type { WardrobeItem } from "../types";
import { UploadCloudIcon, CheckCircleIcon } from "./icons";
import { CardSpotlight } from "@/components/aceternity/card-spotlight";

interface WardrobePanelProps {
  onGarmentSelect: (garmentFile: File, garmentInfo: WardrobeItem) => void;
  activeGarmentIds: string[];
  isLoading: boolean;
  wardrobe: WardrobeItem[];
}

// Helper to convert image URL to a File object using a canvas to bypass potential CORS issues.
const urlToFile = (url: string, filename: string): Promise<File> => {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.setAttribute("crossOrigin", "anonymous");

    image.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = image.naturalWidth;
      canvas.height = image.naturalHeight;

      const ctx = canvas.getContext("2d");
      if (!ctx) {
        return reject(new Error("Could not get canvas context."));
      }
      ctx.drawImage(image, 0, 0);

      canvas.toBlob((blob) => {
        if (!blob) {
          return reject(new Error("Canvas toBlob failed."));
        }
        const mimeType = blob.type || "image/png";
        const file = new File([blob], filename, { type: mimeType });
        resolve(file);
      }, "image/png");
    };

    image.onerror = (error) => {
      reject(
        new Error(
          `Could not load image from URL for canvas conversion. Error: ${error}`
        )
      );
    };

    image.src = url;
  });
};

const WardrobePanel: React.FC<WardrobePanelProps> = ({
  onGarmentSelect,
  activeGarmentIds,
  isLoading,
  wardrobe,
}) => {
  const [error, setError] = useState<string | null>(null);

  const handleGarmentClick = async (item: WardrobeItem) => {
    if (isLoading || activeGarmentIds.includes(item.id)) return;
    setError(null);
    try {
      // If the item was from an upload, its URL is a blob URL. We need to fetch it to create a file.
      // If it was a default item, it's a regular URL. This handles both.
      const file = await urlToFile(item.url, item.name);
      onGarmentSelect(file, item);
    } catch (err) {
      const detailedError = `Failed to load wardrobe item. This is often a CORS issue. Check the developer console for details.`;
      setError(detailedError);
      logger.error(
        `[CORS Check] Failed to load and convert wardrobe item from URL: ${item.url}. The browser's console should have a specific CORS error message if that's the issue.`,
        err
      );
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.startsWith("image/")) {
        setError("Please select an image file.");
        return;
      }
      const customGarmentInfo: WardrobeItem = {
        id: `custom-${Date.now()}`,
        name: file.name,
        url: URL.createObjectURL(file),
      };
      onGarmentSelect(file, customGarmentInfo);
    }
  };

  return (
    <CardSpotlight className="overflow-hidden rounded-[22px] pt-6 border-t border-white/8">
      <h2 className="text-xl font-serif tracking-wider text-white mb-3">
        Wardrobe
      </h2>
      <div className="grid grid-cols-3 gap-3">
        {wardrobe.map((item) => {
          const isActive = activeGarmentIds.includes(item.id);
          return (
            <button
              key={item.id}
              onClick={() => handleGarmentClick(item)}
              disabled={isLoading || isActive}
              className="relative aspect-square border border-white/8 rounded-[12px] overflow-hidden transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-white/20 group disabled:opacity-60 disabled:cursor-not-allowed"
              aria-label={`Select ${item.name}`}
            >
              <img
                src={item.url}
                alt={item.name}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <p className="text-white text-xs font-bold text-center p-1">
                  {item.name}
                </p>
              </div>
              {isActive && (
                <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                  <CheckCircleIcon className="w-8 h-8 text-white" />
                </div>
              )}
            </button>
          );
        })}
        <label
          htmlFor="custom-garment-upload"
          className={`relative aspect-square border-2 border-dashed border-white/8 rounded-[12px] flex flex-col items-center justify-center text-white/55 transition-colors ${isLoading ? "cursor-not-allowed bg-white/6" : "hover:border-white/12 hover:text-white/68 cursor-pointer"}`}
        >
          <UploadCloudIcon className="w-6 h-6 mb-1" />
          <span className="text-xs text-center">Upload</span>
          <input
            id="custom-garment-upload"
            type="file"
            className="hidden"
            accept="image/png, image/jpeg, image/webp, image/avif, image/heic, image/heif"
            onChange={handleFileChange}
            disabled={isLoading}
          />
        </label>
      </div>
      {wardrobe.length === 0 && (
        <p className="text-center text-sm text-white/45 mt-4">
          Your uploaded garments will appear here.
        </p>
      )}
      {error && <p className="text-red-500 text-sm mt-4">{error}</p>}
    </CardSpotlight>
  );
};

export default WardrobePanel;

