import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  ReactNode,
} from "react";

// ==========================================
// إدارة حالة المشروع (State Management)
// بنستخدم Context عشان نربط الـ Director بالـ Designer
// ==========================================

type Role = "Director" | "Costume Designer" | "Producer";

const DEFAULT_PROJECT_ID = "styleist-demo";

interface ProjectState {
  projectId: string;
  projectName: string;
  currentRole: Role;
  activeScene: string;
  notifications: string[];
}

interface ProjectContextType extends ProjectState {
  setRole: (role: Role) => void;
  addNotification: (msg: string) => void;
  updateScene: (scene: string) => void;
}

const ProjectContext = createContext<ProjectContextType | undefined>(undefined);

interface ProjectProviderProps {
  children: ReactNode;
  projectId?: string;
}

export const ProjectProvider: React.FC<ProjectProviderProps> = ({
  children,
  projectId: externalProjectId,
}) => {
  const [state, setState] = useState<ProjectState>({
    projectId: externalProjectId || DEFAULT_PROJECT_ID,
    projectName: "The Last Shadow - Season 1",
    currentRole: "Costume Designer",
    activeScene: "INT. HANGAR - NIGHT",
    notifications: [
      "تم اعتماد الميزانية للمشهد 4",
      "تنبيه: تغيير في إضاءة موقع التصوير",
    ],
  });

  useEffect(() => {
    if (!externalProjectId) return;
    // تحديث الـ projectId لو اتغير من بره
    setState((prev) => ({ ...prev, projectId: externalProjectId }));
  }, [externalProjectId]);

  const setRole = (role: Role) =>
    setState((prev) => ({ ...prev, currentRole: role }));
  const addNotification = useCallback(
    (msg: string) =>
      setState((prev) => ({
        ...prev,
        notifications: [msg, ...prev.notifications],
      })),
    []
  );
  const updateScene = (scene: string) =>
    setState((prev) => ({ ...prev, activeScene: scene }));

  return (
    <ProjectContext.Provider
      value={{ ...state, setRole, addNotification, updateScene }}
    >
      {children}
    </ProjectContext.Provider>
  );
};

export const useProject = () => {
  const context = useContext(ProjectContext);
  if (!context)
    throw new Error("useProject must be used within a ProjectProvider");
  return context;
};

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 */
import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function getFriendlyErrorMessage(
  error: unknown,
  context: string
): string {
  let rawMessage = "An unknown error occurred.";
  if (error instanceof Error) {
    rawMessage = error.message;
  } else if (typeof error === "string") {
    rawMessage = error;
  } else if (error) {
    rawMessage = String(error);
  }

  if (rawMessage.includes("Unsupported MIME type")) {
    try {
      const errorJson = JSON.parse(rawMessage);
      const nestedMessage = errorJson?.error?.message;
      if (nestedMessage && nestedMessage.includes("Unsupported MIME type")) {
        const mimeType = nestedMessage.split(": ")[1] || "unsupported";
        return `File type '${mimeType}' is not supported. Please use a format like PNG, JPEG, or WEBP.`;
      }
    } catch {
      // Not a JSON string
    }
    return `Unsupported file format. Please upload an image format like PNG, JPEG, or WEBP.`;
  }

  return `${context}. ${rawMessage}`;
}

/**
 * Convert File to Base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      // Remove data URL prefix if present to get raw base64
      const base64 = result.includes(",")
        ? (result.split(",")[1] ?? "")
        : result;
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Convert URL to File object.
 */
export const urlToFile = async (
  url: string,
  filename: string
): Promise<File> => {
  if (url.startsWith("data:")) {
    const arr = url.split(",");
    const mimeMatch = arr[0]?.match(/:(.*?);/);
    const mime = mimeMatch?.[1] ?? "image/png";
    const bstr = atob(arr[1] ?? "");
    let n = bstr.length;
    const u8arr = new Uint8Array(n);
    while (n--) {
      u8arr[n] = bstr.charCodeAt(n);
    }
    return new File([u8arr], filename, { type: mime });
  }

  const response = await fetch(url);
  const blob = await response.blob();
  if (!blob.type) {
    return new File([blob], filename);
  }

  return new File([blob], filename, { type: blob.type });
};

