import { useState } from "react";
import { motion } from "framer-motion";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Eye, EyeOff, Activity } from "lucide-react";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

interface RhythmData {
  sceneId: string;
  sceneName: string;
  act: number;
  intensity: number; // 0-100
}

interface RhythmMapProps {
  data?: RhythmData[];
  showMap?: boolean;
  onToggle?: (show: boolean) => void;
}

const defaultData: RhythmData[] = [
  { sceneId: "s1", sceneName: "المقدمة", act: 1, intensity: 20 },
  { sceneId: "s2", sceneName: "التعريف بالشخصيات", act: 1, intensity: 30 },
  { sceneId: "s3", sceneName: "الحدث المحرك", act: 1, intensity: 50 },
  { sceneId: "s4", sceneName: "قبول المهمة", act: 1, intensity: 40 },
  { sceneId: "s5", sceneName: "التحضير للرحلة", act: 1, intensity: 35 },
  { sceneId: "s6", sceneName: "أول عقبة", act: 2, intensity: 60 },
  { sceneId: "s7", sceneName: "تطوير المهارات", act: 2, intensity: 45 },
  { sceneId: "s8", sceneName: "كشف السر", act: 2, intensity: 70 },
  { sceneId: "s9", sceneName: "الخيانة", act: 2, intensity: 80 },
  { sceneId: "s10", sceneName: "نقطة اللاعودة", act: 2, intensity: 85 },
  { sceneId: "s11", sceneName: "الاستعداد للنهاية", act: 3, intensity: 55 },
  { sceneId: "s12", sceneName: "المواجهة النهائية", act: 3, intensity: 95 },
  { sceneId: "s13", sceneName: "الذروة", act: 3, intensity: 100 },
  { sceneId: "s14", sceneName: "الحل", act: 3, intensity: 40 },
  { sceneId: "s15", sceneName: "الخاتمة", act: 3, intensity: 25 },
];

const getIntensityColor = (intensity: number): string => {
  if (intensity >= 80) return "var(--state-flagged)";
  if (intensity >= 60) return "var(--state-alt)";
  if (intensity >= 40) return "var(--color-accent)";
  return "var(--state-draft)";
};

const getIntensityLabel = (intensity: number): string => {
  if (intensity >= 80) return "عالي جداً";
  if (intensity >= 60) return "عالي";
  if (intensity >= 40) return "متوسط";
  if (intensity >= 20) return "منخفض";
  return "هادئ";
};

export function RhythmMap({
  data = defaultData,
  showMap = true,
  onToggle,
}: RhythmMapProps) {
  const [isVisible, setIsVisible] = useState(showMap);

  const handleToggle = () => {
    const newState = !isVisible;
    setIsVisible(newState);
    onToggle?.(newState);
  };

  const acts = Array.from(new Set(data.map((d) => d.act))).sort();
  const maxIntensity = Math.max(...data.map((d) => d.intensity));

  return (
    <Card className="bg-[var(--color-panel)] border-[var(--color-surface)]">
      <div className="p-4 border-b border-[var(--color-surface)] flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Activity className="w-5 h-5 text-[var(--color-accent)]" />
          <h3 className="text-[var(--color-text)]" dir="rtl">
            خريطة الإيقاع
          </h3>
        </div>
        <Button
          variant="ghost"
          size="sm"
          onClick={handleToggle}
          className="text-[var(--color-muted)] hover:bg-[var(--color-surface)]"
        >
          {isVisible ? (
            <>
              <EyeOff className="w-4 h-4 ml-2" />
              إخفاء
            </>
          ) : (
            <>
              <Eye className="w-4 h-4 ml-2" />
              إظهار
            </>
          )}
        </Button>
      </div>

      {isVisible && (
        <div className="p-6">
          <div className="space-y-6">
            {/* Acts */}
            {acts.map((act) => {
              const actScenes = data.filter((d) => d.act === act);

              return (
                <motion.div
                  key={act}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: act * 0.1 }}
                >
                  <div className="mb-3">
                    <h4 className="text-[var(--color-text)]" dir="rtl">
                      الفصل {act}
                    </h4>
                    <p className="text-[var(--color-muted)]" dir="rtl">
                      {actScenes.length} مشهد
                    </p>
                  </div>

                  {/* Heatmap Grid */}
                  <div
                    className="grid gap-2"
                    style={{
                      gridTemplateColumns: `repeat(${Math.min(actScenes.length, 8)}, minmax(0, 1fr))`,
                    }}
                  >
                    <TooltipProvider>
                      {actScenes.map((scene, idx) => (
                        <Tooltip key={scene.sceneId}>
                          <TooltipTrigger asChild>
                            <motion.div
                              initial={{ opacity: 0, scale: 0.8 }}
                              animate={{ opacity: 1, scale: 1 }}
                              transition={{ delay: act * 0.1 + idx * 0.03 }}
                              className="aspect-square rounded-lg cursor-pointer transition-transform hover:scale-110"
                              style={{
                                backgroundColor: getIntensityColor(
                                  scene.intensity
                                ),
                                opacity:
                                  0.2 + (scene.intensity / maxIntensity) * 0.8,
                              }}
                            />
                          </TooltipTrigger>
                          <TooltipContent
                            side="top"
                            className="bg-[var(--color-panel)] border-[var(--color-surface)]"
                          >
                            <div className="text-right" dir="rtl">
                              <p className="text-[var(--color-text)] mb-1">
                                {scene.sceneName}
                              </p>
                              <div className="flex items-center gap-2">
                                <span className="text-[var(--color-muted)]">
                                  الإيقاع:
                                </span>
                                <span
                                  style={{
                                    color: getIntensityColor(scene.intensity),
                                  }}
                                >
                                  {getIntensityLabel(scene.intensity)} (
                                  {scene.intensity}%)
                                </span>
                              </div>
                            </div>
                          </TooltipContent>
                        </Tooltip>
                      ))}
                    </TooltipProvider>
                  </div>
                </motion.div>
              );
            })}
          </div>

          {/* Legend */}
          <div className="mt-6 pt-6 border-t border-[var(--color-surface)]">
            <h4 className="text-[var(--color-text)] mb-3" dir="rtl">
              مقياس الكثافة
            </h4>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <div
                  className="w-4 h-4 rounded"
                  style={{
                    backgroundColor: "var(--state-draft)",
                    opacity: 0.6,
                  }}
                />
                <span className="text-[var(--color-muted)]">هادئ</span>
              </div>
              <div className="flex items-center gap-2">
                <div
                  className="w-4 h-4 rounded"
                  style={{
                    backgroundColor: "var(--color-accent)",
                    opacity: 0.6,
                  }}
                />
                <span className="text-[var(--color-muted)]">متوسط</span>
              </div>
              <div className="flex items-center gap-2">
                <div
                  className="w-4 h-4 rounded"
                  style={{ backgroundColor: "var(--state-alt)", opacity: 0.8 }}
                />
                <span className="text-[var(--color-muted)]">عالي</span>
              </div>
              <div className="flex items-center gap-2">
                <div
                  className="w-4 h-4 rounded"
                  style={{
                    backgroundColor: "var(--state-flagged)",
                    opacity: 1,
                  }}
                />
                <span className="text-[var(--color-muted)]">ذروة</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </Card>
  );
}

import { motion } from "framer-motion";
import { Badge } from "@/components/ui/badge";
import { Clock, ArrowRight, ArrowLeft, Flag } from "lucide-react";

/**
 * Scene status type
 */
export type SceneStatus = "draft" | "final" | "alt" | "flagged";

/**
 * Core scene data
 */
export interface SceneData {
  id: string;
  title: string;
  beats?: string[];
  duration?: string;
  status: SceneStatus;
}

/**
 * Scene connection info
 */
export interface SceneConnections {
  linksIn?: number;
  linksOut?: number;
}

/**
 * Display configuration
 */
export interface SceneDisplayConfig {
  density?: "compact" | "comfortable";
  isFocused?: boolean;
}

/**
 * Scene card props - grouped to reduce parameter count from 10 to 5
 */
interface SceneCardProps {
  scene: SceneData;
  connections?: SceneConnections;
  display?: SceneDisplayConfig;
  onClick?: () => void;
}

const statusColors = {
  draft: "var(--state-draft)",
  final: "var(--state-final)",
  alt: "var(--state-alt)",
  flagged: "var(--state-flagged)",
};

const statusLabels = {
  draft: "مسودة",
  final: "نهائي",
  alt: "بديل",
  flagged: "مُعلّم",
};

export function SceneCard({
  scene,
  connections = {},
  display = {},
  onClick,
}: SceneCardProps) {
  const { id, title, beats = [], duration, status } = scene;
  const { linksIn = 0, linksOut = 0 } = connections;
  const { density = "comfortable", isFocused = false } = display;
  const isCompact = density === "compact";

  return (
    <motion.div
      className={`
        relative bg-[var(--color-panel)] border-2 rounded-xl overflow-hidden cursor-pointer
        transition-all duration-300 group
        ${isFocused ? "border-[var(--color-accent)] shadow-2xl" : "border-[var(--color-surface)] hover:border-[var(--color-accent-weak)]"}
        ${isCompact ? "min-w-[280px] min-h-[160px]" : "min-w-[320px] min-h-[200px]"}
      `}
      onClick={onClick}
      whileHover={{ scale: isFocused ? 1 : 1.02 }}
      layoutId={`scene-${id}`}
      style={{
        boxShadow: isFocused
          ? "0 20px 60px rgba(138, 155, 255, 0.3)"
          : "0 8px 24px rgba(0, 0, 0, 0.12)",
      }}
    >
      {/* Status indicator */}
      <div
        className="absolute top-0 right-0 w-1 h-full"
        style={{ backgroundColor: statusColors[status] }}
      />

      <div
        className={`p-${isCompact ? "4" : "6"} flex flex-col gap-${isCompact ? "2" : "3"}`}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3">
          <h3
            className="flex-1 text-[var(--color-text)] line-clamp-2"
            dir="rtl"
          >
            {title}
          </h3>
          {status === "flagged" && (
            <Flag
              className="w-4 h-4 flex-shrink-0"
              style={{ color: statusColors.flagged }}
            />
          )}
        </div>

        {/* Beats */}
        {beats.length > 0 && (
          <div className="flex flex-wrap gap-2" dir="rtl">
            {beats.slice(0, isCompact ? 2 : 4).map((beat, idx) => (
              <Badge
                key={idx}
                variant="secondary"
                className="bg-[var(--color-surface)] text-[var(--color-muted)] hover:bg-[var(--color-surface)]"
              >
                {beat}
              </Badge>
            ))}
            {beats.length > (isCompact ? 2 : 4) && (
              <Badge
                variant="secondary"
                className="bg-[var(--color-surface)] text-[var(--color-muted)]"
              >
                +{beats.length - (isCompact ? 2 : 4)}
              </Badge>
            )}
          </div>
        )}

        {/* Footer */}
        <div className="flex items-center justify-between mt-auto pt-3 border-t border-[var(--color-surface)]">
          <div className="flex items-center gap-4">
            {duration && (
              <div className="flex items-center gap-1 text-[var(--color-muted)]">
                <Clock className="w-4 h-4" />
                <span>{duration}</span>
              </div>
            )}
            <Badge
              variant="outline"
              className="border-current"
              style={{
                color: statusColors[status],
                borderColor: statusColors[status],
              }}
            >
              {statusLabels[status]}
            </Badge>
          </div>

          <div className="flex items-center gap-2 text-[var(--color-muted)]">
            {linksIn > 0 && (
              <div className="flex items-center gap-1">
                <ArrowLeft className="w-4 h-4" />
                <span>{linksIn}</span>
              </div>
            )}
            {linksOut > 0 && (
              <div className="flex items-center gap-1">
                <ArrowRight className="w-4 h-4" />
                <span>{linksOut}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

import { motion } from "framer-motion";
import { CheckCircle, Circle, Loader2, Eye } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";

interface StationItem {
  id: number;
  title: string;
  state: "idle" | "running" | "review" | "finalized";
}

interface SevenStationsDockProps {
  current: number;
  progress: "idle" | "running" | "review" | "finalized";
  items: StationItem[];
  onNext?: () => void;
  onPrev?: () => void;
  onViewDetails?: (stationId: number) => void;
}

export function SevenStationsDock({
  current,
  progress,
  items,
  onNext,
  onPrev,
  onViewDetails,
}: SevenStationsDockProps) {
  const progressPercentage = (current / 7) * 100;

  return (
    <div className="bg-[var(--color-panel)] border border-[var(--color-surface)] rounded-xl overflow-hidden">
      <div className="p-4 border-b border-[var(--color-surface)]">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-[var(--color-text)]" dir="rtl">
            المحطات السبع للتحليل
          </h3>
          <Badge
            variant="outline"
            className={`
              ${progress === "idle" && "border-[var(--color-muted)] text-[var(--color-muted)]"}
              ${progress === "running" && "border-[var(--color-accent)] text-[var(--color-accent)]"}
              ${progress === "review" && "border-[var(--state-alt)] text-[var(--state-alt)]"}
              ${progress === "finalized" && "border-[var(--state-final)] text-[var(--state-final)]"}
            `}
          >
            {progress === "idle" && "جاهز"}
            {progress === "running" && "قيد التشغيل"}
            {progress === "review" && "مراجعة"}
            {progress === "finalized" && "مكتمل"}
          </Badge>
        </div>
        <Progress value={progressPercentage} className="h-2" />
        <p className="text-[var(--color-muted)] mt-2" dir="rtl">
          المحطة {current} من 7
        </p>
      </div>

      <div className="divide-y divide-[var(--color-surface)]">
        {items.map((station, index) => {
          const isActive = station.id === current;
          const isCompleted = station.id < current;
          const isCurrent = station.id === current;

          return (
            <motion.div
              key={station.id}
              className={`
                p-4 transition-all duration-300
                ${isActive ? "bg-[var(--color-surface)]" : "bg-transparent hover:bg-[var(--color-surface)]/50"}
              `}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.05 }}
            >
              <div className="flex items-start gap-3">
                <div className="flex-shrink-0 mt-1">
                  {isCompleted && (
                    <CheckCircle className="w-5 h-5 text-[var(--state-final)]" />
                  )}
                  {isCurrent && station.state === "running" && (
                    <Loader2 className="w-5 h-5 text-[var(--color-accent)] animate-spin" />
                  )}
                  {isCurrent && station.state !== "running" && (
                    <Circle className="w-5 h-5 text-[var(--color-accent)]" />
                  )}
                  {!isCompleted && !isCurrent && (
                    <Circle className="w-5 h-5 text-[var(--color-muted)]" />
                  )}
                </div>

                <div className="flex-1">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <h4
                        className={`
                          ${isActive ? "text-[var(--color-text)]" : "text-[var(--color-muted)]"}
                        `}
                        dir="rtl"
                      >
                        {station.id}. {station.title}
                      </h4>
                      {station.state === "review" && (
                        <p className="text-[var(--color-muted)] mt-1">
                          جاهز للمراجعة
                        </p>
                      )}
                      {station.state === "finalized" && (
                        <p className="text-[var(--state-final)] mt-1">مكتمل</p>
                      )}
                    </div>

                    {(station.state === "review" ||
                      station.state === "finalized") && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => onViewDetails?.(station.id)}
                        className="text-[var(--color-accent)] hover:bg-[var(--color-surface)]"
                      >
                        <Eye className="w-4 h-4 ml-1" />
                        عرض
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>

      <div className="p-4 border-t border-[var(--color-surface)] flex items-center justify-between gap-3">
        <Button
          variant="outline"
          size="sm"
          onClick={onPrev}
          disabled={current === 1}
          className="border-[var(--color-surface)] text-[var(--color-text)] hover:bg-[var(--color-surface)]"
          dir="rtl"
        >
          السابق
        </Button>
        <Button
          variant="default"
          size="sm"
          onClick={onNext}
          disabled={current === 7 || progress === "running"}
          className="bg-[var(--color-accent)] hover:bg-[var(--color-accent)]/90 text-[var(--color-bg)]"
          dir="rtl"
        >
          {current === 7 ? "إنهاء" : "التالي"}
        </Button>
      </div>
    </div>
  );
}

