  });

  // ================================================================
  // 4) فتح القفل بالتقرير اليدوي
  // ================================================================
  describe("unlock with manual report", () => {
    it("تقرير يدوي بمحتوى كافٍ يفتح القفل", () => {
      const manualReport = {
        text: "تحليل يدوي للسيناريو مع ملاحظات تفصيلية عن البنية والشخصيات والحوار",
        wordCount: 10,
        isManual: true,
