});

/**
 * شبكة انحدار: brain-storm-ai — أزرار التصدير وتصدير سجل الجلسات
 *
 * يتحقق من:
 * - export buttons: exportToJSON و exportToMarkdown و copyToClipboard
 * - session history export: حفظ/تحميل/حذف/مسح الجلسات
 */
import { describe, it, expect, beforeEach } from "vitest";
import type {
  Session,
  DebateMessage,
} from "@/app/(main)/brain-storm-ai/src/types";

// ------------------------------------------------------------------
// بيانات اختبار مشتركة
// ------------------------------------------------------------------
function createMockSession(overrides?: Partial<Session>): Session {
  return {
    id: "session-001",
    brief: "عصف ذهني حول فكرة فيلم",
    phase: 3,
    status: "active",
    startTime: new Date("2026-04-10T10:00:00Z"),
    activeAgents: ["agent-1", "agent-2"],
    results: { topIdea: "فكرة رئيسية" },
    ...overrides,
  };
}

function createMockMessages(): DebateMessage[] {
  return [
    {
      agentId: "agent-1",
      agentName: "المحلل",
      message: "اقتراح: نركز على الجانب الإنساني",
      timestamp: new Date("2026-04-10T10:05:00Z"),
      type: "proposal",
    },
    {
      agentId: "agent-2",
      agentName: "الناقد",
      message: "ملاحظة: يحتاج تعمق أكثر",
      timestamp: new Date("2026-04-10T10:06:00Z"),
      type: "critique",
    },
    {
      agentId: "agent-1",
      agentName: "المحلل",
      message: "قرار: نمضي بالاتجاه الإنساني",
      timestamp: new Date("2026-04-10T10:10:00Z"),
      type: "decision",
    },
  ];
}

describe("شبكة انحدار: brain-storm-ai — التصدير", () => {
  // ================================================================
  // 1) أزرار التصدير — بنية البيانات
  // ================================================================
  describe("export buttons — بنية البيانات", () => {
    it("بيانات التصدير JSON تحتوي الحقول المطلوبة", () => {
      const session = createMockSession();
      const messages = createMockMessages();

      // محاكاة prepareExportData
      const exportData = {
        session: {
          id: session.id,
          brief: session.brief,
          phase: session.phase,
          status: session.status,
          startTime: session.startTime.toISOString(),
        },
        messages: messages.map((m) => ({
          agent: m.agentName,
          type: m.type,
          message: m.message,
          timestamp: m.timestamp.toISOString(),
        })),
        results: session.results || {},
        exportedAt: new Date().toISOString(),
        version: "1.0",
      };

      expect(exportData.session.id).toBe("session-001");
      expect(exportData.messages).toHaveLength(3);
      expect(exportData.version).toBe("1.0");
      expect(exportData.results).toHaveProperty("topIdea");
    });

    it("بيانات التصدير Markdown تحتوي العناوين المطلوبة", () => {
      const session = createMockSession();

      // محاكاة بناء Markdown
      let md = `# تقرير جلسة العصف الذهني\n\n`;
      md += `**المعرّف:** ${session.id}\n\n`;
      md += `**الموجز:** ${session.brief}\n\n`;
      md += `**المرحلة:** ${session.phase} / 5\n\n`;

      expect(md).toContain("# تقرير جلسة العصف الذهني");
      expect(md).toContain(session.id);
      expect(md).toContain(session.brief);
      expect(md).toContain(`${session.phase} / 5`);
    });

    it("نسخ الحافظة يتضمن القرارات والاقتراحات", () => {
      const messages = createMockMessages();

      const decisions = messages.filter((m) => m.type === "decision");
      const proposals = messages.filter((m) => m.type === "proposal");

      expect(decisions).toHaveLength(1);
      expect(proposals).toHaveLength(1);
      expect(decisions[0].agentName).toBe("المحلل");
    });
  });

  // ================================================================
  // 2) سجل الجلسات — بنية التخزين
  // ================================================================
  describe("session history export", () => {
    beforeEach(() => {
      localStorage.clear();
    });

    it("الجلسة المحفوظة تحتوي session و messages و savedAt", () => {
      const savedSession = {
        session: createMockSession(),
        messages: createMockMessages(),
        savedAt: new Date().toISOString(),
      };

      expect(savedSession).toHaveProperty("session");
      expect(savedSession).toHaveProperty("messages");
      expect(savedSession).toHaveProperty("savedAt");
      expect(savedSession.messages).toHaveLength(3);
    });

    it("التاريخ يُحوَّل من Date إلى string ويعود", () => {
      const session = createMockSession();
      const serialized = session.startTime.toISOString();
      const restored = new Date(serialized);

      expect(restored.getTime()).toBe(session.startTime.getTime());
    });

    it("التخزين يحتفظ بـ 20 جلسة كحد أقصى", () => {
      const sessions = Array.from({ length: 25 }, (_, i) => ({
        session: createMockSession({ id: `session-${i}` }),
        messages: [],
        savedAt: new Date().toISOString(),
      }));

      // محاكاة سلوك الحد الأقصى
      const trimmed = sessions.slice(0, 20);
      expect(trimmed).toHaveLength(20);
    });

    it("حفظ جلسة موجودة يحدّثها بدل إضافة نسخة جديدة", () => {
      const store = [
        {
          session: createMockSession({ id: "dup-1" }),
          messages: [],
          savedAt: "2026-04-10T10:00:00Z",
        },
      ];

      const updated = {
        session: createMockSession({
          id: "dup-1",
          status: "completed",
        }),
        messages: createMockMessages(),
        savedAt: "2026-04-10T11:00:00Z",
      };

      const idx = store.findIndex((s) => s.session.id === updated.session.id);
      if (idx >= 0) {
        store[idx] = updated;
      }

      expect(store).toHaveLength(1);
      expect(store[0].session.status).toBe("completed");
      expect(store[0].messages).toHaveLength(3);
    });

    it("localStorage يُكتب ويُقرأ بالتنسيق الصحيح", () => {
      const data = {
        sessions: [
          {
            session: {
              id: "s1",
              brief: "test",
              phase: 1,
              status: "active",
              startTime: "2026-04-10T10:00:00.000Z",
              activeAgents: [],
            },
            messages: [],
            savedAt: "2026-04-10T10:00:00.000Z",
          },
        ],
        version: 1,
      };

      localStorage.setItem("brainstorm_sessions", JSON.stringify(data));
      const raw = localStorage.getItem("brainstorm_sessions");
      expect(raw).not.toBeNull();

      const parsed = JSON.parse(raw!);
      expect(parsed.sessions).toHaveLength(1);
      expect(parsed.version).toBe(1);
    });
  });
});

/**
 * شبكة انحدار: cinematography — المنزلقات الحرجة تستجيب
 *
 * يتحقق من:
 * - Zod schemas تقبل القيم الصحيحة وترفض غيرها
 * - تحويل المرحلة ↔ التبويب يعمل في الاتجاهين
 * - دوال التحقق isValidTabValue و isValidVisualMood
 * - ScenePromptSchema و ColorTemperatureSchema و ShotAnalysisSchema
 */
import { describe, it, expect } from "vitest";
import {
  PRODUCTION_PHASES,
  TAB_VALUES,
  VISUAL_MOODS,
  VIEW_MODES,
  PhaseSchema,
  VisualMoodSchema,
  ViewModeSchema,
  ShotAnalysisSchema,
  CineStudioStateSchema,
  ColorHexSchema,
  TAB_VALUE_BY_PHASE,
  PHASE_BY_TAB,
  isValidTabValue,
  isValidVisualMood,
  validateScenePrompt,
  validateColorTemperature,
} from "@/app/(main)/cinematography-studio/types";

describe("شبكة انحدار: cinematography — المنزلقات الحرجة", () => {
  // ================================================================
  // 1) الثوابت الأساسية
  // ================================================================
  describe("الثوابت", () => {
    it("PRODUCTION_PHASES تحتوي pre و production و post", () => {
      expect(PRODUCTION_PHASES).toEqual(["pre", "production", "post"]);
    });

    it("TAB_VALUES تحتوي 3 قيم", () => {
      expect(TAB_VALUES).toHaveLength(3);
      expect(TAB_VALUES).toContain("pre-production");
      expect(TAB_VALUES).toContain("production");
      expect(TAB_VALUES).toContain("post-production");
    });

    it("VISUAL_MOODS تحتوي 4 أمزجة", () => {
      expect(VISUAL_MOODS).toEqual(["noir", "realistic", "surreal", "vintage"]);
    });

    it("VIEW_MODES تحتوي dashboard و phases", () => {
      expect(VIEW_MODES).toEqual(["dashboard", "phases"]);
    });
  });

  // ================================================================
  // 2) خرائط التحويل Phase ↔ Tab
  // ================================================================
  describe("خرائط التحويل", () => {
    it("TAB_VALUE_BY_PHASE يحوّل كل مرحلة لقيمة تبويب", () => {
      expect(TAB_VALUE_BY_PHASE.pre).toBe("pre-production");
      expect(TAB_VALUE_BY_PHASE.production).toBe("production");
      expect(TAB_VALUE_BY_PHASE.post).toBe("post-production");
    });

    it("PHASE_BY_TAB يحوّل كل تبويب لمرحلة", () => {
      expect(PHASE_BY_TAB["pre-production"]).toBe("pre");
      expect(PHASE_BY_TAB["production"]).toBe("production");
      expect(PHASE_BY_TAB["post-production"]).toBe("post");
    });

    it("التحويل ذهاباً وإياباً يعيد القيمة الأصلية", () => {
      for (const phase of PRODUCTION_PHASES) {
        const tab = TAB_VALUE_BY_PHASE[phase];
        const backToPhase = PHASE_BY_TAB[tab];
        expect(backToPhase).toBe(phase);
      }
    });
  });

  // ================================================================
  // 3) دوال التحقق
  // ================================================================
  describe("دوال التحقق", () => {
    it("isValidTabValue تقبل القيم الصحيحة", () => {
      expect(isValidTabValue("pre-production")).toBe(true);
      expect(isValidTabValue("production")).toBe(true);
      expect(isValidTabValue("post-production")).toBe(true);
    });

    it("isValidTabValue ترفض القيم الخاطئة", () => {
      expect(isValidTabValue("invalid")).toBe(false);
      expect(isValidTabValue("")).toBe(false);
      expect(isValidTabValue("PRE-PRODUCTION")).toBe(false);
    });

    it("isValidVisualMood تقبل القيم الصحيحة", () => {
      for (const mood of VISUAL_MOODS) {
        expect(isValidVisualMood(mood)).toBe(true);
      }
    });

    it("isValidVisualMood ترفض القيم الخاطئة", () => {
      expect(isValidVisualMood("bright")).toBe(false);
      expect(isValidVisualMood("")).toBe(false);
    });
  });

  // ================================================================
  // 4) Zod Schemas
  // ================================================================
  describe("Zod Schemas", () => {
    it("PhaseSchema يقبل المراحل الصحيحة فقط", () => {
      expect(PhaseSchema.safeParse("pre").success).toBe(true);
      expect(PhaseSchema.safeParse("production").success).toBe(true);
      expect(PhaseSchema.safeParse("post").success).toBe(true);
      expect(PhaseSchema.safeParse("invalid").success).toBe(false);
    });

    it("VisualMoodSchema يقبل الأمزجة الصحيحة فقط", () => {
      expect(VisualMoodSchema.safeParse("noir").success).toBe(true);
      expect(VisualMoodSchema.safeParse("fantasy").success).toBe(false);
    });

    it("ViewModeSchema يقبل dashboard و phases فقط", () => {
      expect(ViewModeSchema.safeParse("dashboard").success).toBe(true);
      expect(ViewModeSchema.safeParse("phases").success).toBe(true);
      expect(ViewModeSchema.safeParse("list").success).toBe(false);
    });

    it("ScenePromptSchema يقبل prompt بين 10 و 1000 حرف", () => {
      const valid = validateScenePrompt({
        prompt: "وصف مشهد طويل بما يكفي للتحقق",
        darkness: 50,
        complexity: 30,
      });
      expect(valid.success).toBe(true);

      const tooShort = validateScenePrompt({
        prompt: "قصير",
        darkness: 50,
        complexity: 30,
      });
      expect(tooShort.success).toBe(false);
    });

    it("ScenePromptSchema يرفض darkness خارج 0-100", () => {
      const invalid = validateScenePrompt({
        prompt: "وصف مشهد طويل بما يكفي للتحقق",
        darkness: 150,
        complexity: 30,
      });
      expect(invalid.success).toBe(false);
    });

    it("ColorTemperatureSchema يقبل 2000-10000", () => {
      expect(validateColorTemperature(5500).success).toBe(true);
      expect(validateColorTemperature(2000).success).toBe(true);
      expect(validateColorTemperature(10000).success).toBe(true);
      expect(validateColorTemperature(1999).success).toBe(false);
      expect(validateColorTemperature(10001).success).toBe(false);
    });

    it("ColorHexSchema يقبل #RRGGBB فقط", () => {
      expect(ColorHexSchema.safeParse("#FF0000").success).toBe(true);
      expect(ColorHexSchema.safeParse("#abc123").success).toBe(true);
      expect(ColorHexSchema.safeParse("FF0000").success).toBe(false);
      expect(ColorHexSchema.safeParse("#GGG000").success).toBe(false);
    });

    it("CineStudioStateSchema يقبل حالة صحيحة", () => {
      const valid = CineStudioStateSchema.safeParse({
        currentPhase: "pre",
        visualMood: "noir",
        activeTool: null,
        activeView: "dashboard",
      });
      expect(valid.success).toBe(true);
    });

    it("CineStudioStateSchema يرفض حالة بمرحلة خاطئة", () => {
      const invalid = CineStudioStateSchema.safeParse({
        currentPhase: "invalid-phase",
        visualMood: "noir",
        activeTool: null,
        activeView: "dashboard",
      });
      expect(invalid.success).toBe(false);
    });

    it("ShotAnalysisSchema يقبل تحليل صحيح", () => {
      const valid = ShotAnalysisSchema.safeParse({
        score: 85,
        dynamicRange: "high",
        grainLevel: "low",
        issues: ["exposure warning"],
        exposure: 70,
      });
      expect(valid.success).toBe(true);
    });

    it("ShotAnalysisSchema يرفض score > 100", () => {
      const invalid = ShotAnalysisSchema.safeParse({
        score: 150,
        dynamicRange: "high",
        grainLevel: "low",
        issues: [],
        exposure: 70,
      });
      expect(invalid.success).toBe(false);
    });
  });
});

import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
import "@testing-library/jest-dom";
import React, { Suspense } from "react";

// Helper component for wrapping pages with Suspense
const PageWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <Suspense fallback={<div>Loading...</div>}>{children}</Suspense>
);

const RouteWrapper: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => <>{children}</>;

async function renderRouteComponent(
  path: string,
  PageComponent: React.ComponentType
) {
  const Wrapper =
    path === "/directors-studio"
      ? (await import("../(main)/directors-studio/layout")).default
      : RouteWrapper;

  return render(
    <Wrapper>
      <PageWrapper>
        <PageComponent />
      </PageWrapper>
    </Wrapper>
  );
}

// Define critical routes for testing
const CRITICAL_ROUTES = [
  {
    path: "/",
    name: "الصفحة الرئيسية",
    elements: ["home", "hero", "welcome"],
  },
  {
    path: "/arabic-creative-writing-studio",
    name: "ورشة الكتابة الإبداعية العربية",
    elements: ["creative", "writing", "studio", "arabic"],
  },
  {
    path: "/directors-studio",
    name: "استوديو المخرجين",
    elements: ["director", "studio", "project"],
  },
  {
    path: "/cinematography-studio",
    name: "استوديو التصوير",
    elements: ["cinema", "photography", "studio"],
  },
  {
    path: "/actorai-arabic",
    name: "استوديو الذكاء الاصطناعي للممثلين",
