  cast: "#3B82F6",
  extras: "#F97316",
  props: "#EAB308",
  handProps: "#CA8A04",
  setDressing: "#8B5CF6",
  costumes: "#A855F7",
  makeup: "#EC4899",
  sound: "#06B6D4",
  soundRequirements: "#0891B2",
  equipment: "#64748B",
  specialEquipment: "#475569",
  vehicles: "#EF4444",
