  continuity: "#E11D48",
};

/** استرداد مفتاح Gemini API من متغيرات البيئة */
function getGeminiApiKey(): string {
  return (
    process.env["GEMINI_API_KEY"] ||
    process.env["GOOGLE_GENAI_API_KEY"] ||
    process.env["API_KEY"] ||
