"use client";

import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Download, Eye, FileText } from "lucide-react";
import { toText } from "@/ai/gemini-core";

// =====================================================
// Types
// =====================================================

export interface AgentReport {
  agentName: string;
  agentId: string;
  text: string;
  confidence: number;
  notes?: string[];
  timestamp?: string;
  metadata?: Record<string, any>;
}

interface AgentReportViewerProps {
  report: AgentReport;
  trigger?: React.ReactNode;
  taskResults?: Record<string, AgentReport>;
}

interface AgentReportsExporterProps {
  reports: AgentReport[];
  projectTitle?: string;
}

// =====================================================
// Helper Functions
// =====================================================

function exportToTextFile(content: string, filename: string): void {
  const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function formatSingleReport(report: AgentReport): string {
  const lines: string[] = [];

  lines.push("=".repeat(60));
  lines.push(`تقرير الوكيل: ${report.agentName}`);
  lines.push("=".repeat(60));
  lines.push("");

  if (report.timestamp) {
    lines.push(`التاريخ: ${report.timestamp}`);
    lines.push("");
  }

  lines.push(`مستوى الثقة: ${(report.confidence * 100).toFixed(0)}%`);
  lines.push("");

  lines.push("--- التحليل ---");
  lines.push("");
  lines.push(toText(report.text));
  lines.push("");

  if (report.notes && report.notes.length > 0) {
    lines.push("--- ملاحظات ---");
    report.notes.forEach((note) => {
      lines.push(`• ${note}`);
    });
    lines.push("");
  }

  if (report.metadata) {
    lines.push("--- معلومات إضافية ---");
    Object.entries(report.metadata).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        lines.push(`${key}: ${value}`);
      }
    });
    lines.push("");
  }

  lines.push("=".repeat(60));
  lines.push("");

  return lines.join("\n");
}

function formatAllReports(
  reports: AgentReport[],
  projectTitle?: string
): string {
  const lines: string[] = [];

  lines.push("═".repeat(80));
  lines.push("═".repeat(80));
  lines.push("");
  lines.push("           التقرير النهائي الشامل - التطوير الإبداعي");
  lines.push("");
  lines.push("═".repeat(80));
  lines.push("═".repeat(80));
  lines.push("");

  if (projectTitle) {
    lines.push(`المشروع: ${projectTitle}`);
    lines.push("");
  }

  lines.push(`التاريخ: ${new Date().toLocaleString("ar")}`);
  lines.push(`عدد الوكلاء المستخدمة: ${reports.length}`);
  lines.push("");

  // Summary
  lines.push("═".repeat(80));
  lines.push("الملخص التنفيذي");
  lines.push("═".repeat(80));
  lines.push("");

  const avgConfidence =
    reports.reduce((sum, r) => sum + r.confidence, 0) / reports.length;
  lines.push(`متوسط الثقة: ${(avgConfidence * 100).toFixed(0)}%`);

  const highConfidenceCount = reports.filter((r) => r.confidence >= 0.8).length;
  const mediumConfidenceCount = reports.filter(
    (r) => r.confidence >= 0.6 && r.confidence < 0.8
  ).length;
  const lowConfidenceCount = reports.filter((r) => r.confidence < 0.6).length;

  lines.push("");
  lines.push("توزيع مستويات الثقة:");
  lines.push(`  • عالية (≥80%): ${highConfidenceCount} وكيل`);
  lines.push(`  • متوسطة (60-79%): ${mediumConfidenceCount} وكيل`);
  lines.push(`  • منخفضة (<60%): ${lowConfidenceCount} وكيل`);
  lines.push("");

  // Individual reports
  lines.push("═".repeat(80));
  lines.push("التقارير الفردية");
  lines.push("═".repeat(80));
  lines.push("");

  reports.forEach((report, index) => {
    lines.push(`\n\n${"─".repeat(80)}`);
    lines.push(`الوكيل ${index + 1} من ${reports.length}`);
    lines.push("─".repeat(80));
    lines.push("");
    lines.push(formatSingleReport(report));
  });

  // Footer
  lines.push("");
  lines.push("═".repeat(80));
  lines.push("نهاية التقرير");
  lines.push("═".repeat(80));
  lines.push("");
  lines.push("تم إنشاء هذا التقرير بواسطة نظام التطوير الإبداعي الذكي");
  lines.push("");

  return lines.join("\n");
}

function getConfidenceColor(confidence: number): string {
  if (confidence >= 0.8) return "bg-green-500";
  if (confidence >= 0.6) return "bg-yellow-500";
  return "bg-red-500";
}

function getConfidenceLabel(confidence: number): string {
  if (confidence >= 0.8) return "عالية";
  if (confidence >= 0.6) return "متوسطة";
  return "منخفضة";
}

// =====================================================
// Single Report Viewer Component
// =====================================================

export function AgentReportViewer({
  report,
  trigger,
  taskResults,
}: AgentReportViewerProps) {
  const [open, setOpen] = useState(false);

  const handleExport = () => {
    const content = formatSingleReport(report);
    const filename = `${report.agentId}-${Date.now()}.txt`;
    exportToTextFile(content, filename);
  };

  const defaultTrigger = (
    <Button variant="outline" size="sm" className="gap-2">
      <Eye className="h-4 w-4" />
      عرض التقرير
    </Button>
  );

  return (
    <>
      <div onClick={() => setOpen(true)} className="inline-block">
        {trigger || defaultTrigger}
      </div>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-4xl max-h-[80vh]">
          <DialogHeader>
            <DialogTitle className="text-xl font-bold flex items-center gap-2">
              <FileText className="h-5 w-5" />
              {report.agentName}
            </DialogTitle>
            <DialogDescription className="flex items-center gap-2 pt-2">
              <Badge
                variant="outline"
                className={`${getConfidenceColor(report.confidence)} text-white`}
              >
                الثقة: {(report.confidence * 100).toFixed(0)}%
              </Badge>
              <Badge variant="secondary">
                {getConfidenceLabel(report.confidence)}
              </Badge>
              {report.timestamp && (
                <span className="text-sm text-muted-foreground">
                  {report.timestamp}
                </span>
              )}
            </DialogDescription>
          </DialogHeader>

          <ScrollArea className="h-[50vh] w-full rounded-md border p-4">
            <div className="space-y-4">
              {/* Main Content */}
              <div>
                <h3 className="font-semibold text-sm text-muted-foreground mb-2">
                  التحليل
                </h3>
                <div
                  className="whitespace-pre-wrap text-sm"
                  dir="rtl"
                  style={{ fontFamily: "inherit" }}
                >
                  {toText(report.text)}
                </div>
              </div>

              {/* Notes */}
              {report.notes && report.notes.length > 0 && (
                <div>
                  <h3 className="font-semibold text-sm text-muted-foreground mb-2">
                    ملاحظات
                  </h3>
                  <ul className="space-y-1">
                    {report.notes.map((note, i) => (
                      <li key={i} className="text-sm flex items-start gap-2">
                        <span className="text-primary">•</span>
                        <span>{note}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Metadata */}
              {report.metadata && Object.keys(report.metadata).length > 0 && (
                <div>
                  <h3 className="font-semibold text-sm text-muted-foreground mb-2">
                    معلومات إضافية
                  </h3>
                  <div className="space-y-1 text-sm">
                    {Object.entries(report.metadata).map(([key, value]) => (
                      <div key={key} className="flex gap-2">
                        <span className="font-medium">{key}:</span>
                        <span className="text-muted-foreground">
                          {String(value)}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Supporting Task Results */}
              {taskResults && Object.keys(taskResults).length > 0 && (
                <details className="mt-4 border rounded-lg p-3">
                  <summary className="cursor-pointer font-medium text-sm">
                    النتائج الداعمة ({Object.keys(taskResults).length})
                  </summary>
                  <div className="mt-2 space-y-3">
                    {Object.entries(taskResults).map(([key, result]) => (
                      <div key={key} className="border-t pt-2">
                        <h4 className="font-medium text-sm">
                          {result.agentName}
                        </h4>
                        <p className="text-sm text-muted-foreground whitespace-pre-wrap">
                          {result.text}
                        </p>
                      </div>
                    ))}
                  </div>
                </details>
              )}
            </div>
          </ScrollArea>

          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => setOpen(false)}>
              إغلاق
            </Button>
            <Button onClick={handleExport} className="gap-2">
              <Download className="h-4 w-4" />
              تصدير التقرير
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

// =====================================================
// Multiple Reports Exporter Component
// =====================================================

export function AgentReportsExporter({
  reports,
  projectTitle,
}: AgentReportsExporterProps) {
  const handleExportAll = () => {
    if (reports.length === 0) {
      alert("لا توجد تقارير للتصدير");
      return;
    }

    const content = formatAllReports(reports, projectTitle);
    const filename = `final-report-${Date.now()}.txt`;
    exportToTextFile(content, filename);
  };

  const avgConfidence =
    reports.length > 0
      ? reports.reduce((sum, r) => sum + r.confidence, 0) / reports.length
      : 0;

  return (
    <div className="flex items-center gap-4 p-4 border rounded-lg bg-card">
      <div className="flex-1">
        <h3 className="font-semibold text-lg">التقرير النهائي الشامل</h3>
        <p className="text-sm text-muted-foreground">
          {reports.length} تقرير • متوسط الثقة:{" "}
          {(avgConfidence * 100).toFixed(0)}%
        </p>
      </div>
      <Button
        onClick={handleExportAll}
        disabled={reports.length === 0}
        size="lg"
        className="gap-2"
      >
        <Download className="h-5 w-5" />
        تصدير التقرير النهائي
      </Button>
    </div>
  );
}

// =====================================================
// Export Helper (can be used independently)
// =====================================================

export function exportAgentReport(report: AgentReport): void {
  const content = formatSingleReport(report);
  const filename = `${report.agentId}-${Date.now()}.txt`;
  exportToTextFile(content, filename);
}

export function exportAllAgentReports(
  reports: AgentReport[],
  projectTitle?: string
): void {
  const content = formatAllReports(reports, projectTitle);
  const filename = `final-report-${Date.now()}.txt`;
  exportToTextFile(content, filename);
}

import React from 'react';

export interface AgentReportsExporterProps {
  reports: Record<string, any>;
  originalText?: string;
  onExport?: (format: 'txt' | 'json') => void;
}

export const AgentReportsExporter: React.FC<AgentReportsExporterProps>;

/**
 * @fileoverview Unit tests for AgentReportsExporter (T027)
 *
 * Covers:
 *  - JSON export includes finalText and taskResults with all completed steps
 *  - Markdown/text export starts with final text then appends ## {title} heading per completed step
 *  - Steps with status !== "completed" are absent from both export formats
 *  - Empty/missing taskResults does not break export
 */

import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { AgentReportsExporter } from "./agent-reports-exporter";
import type { AgentTaskResult } from "./agent-reports-exporter";

// ---------------------------------------------------------------------------
// Browser API mocks
// ---------------------------------------------------------------------------

const mockRevokeObjectURL = vi.fn();
const mockCreateObjectURL = vi.fn(() => "blob:mock-url");

// Track Blob constructor calls so we can inspect content
let lastBlobContent = "";
let lastBlobOptions: BlobPropertyBag = {};

class MockBlob {
  constructor(parts: BlobPart[], options?: BlobPropertyBag) {
    lastBlobContent = parts.join("");
    lastBlobOptions = options ?? {};
  }
}

// Mock anchor click so no real navigation happens
const mockAnchorClick = vi.fn();
const mockAppendChild = vi.fn();
const mockRemoveChild = vi.fn();

// Mock useToast so the component doesn't fail due to missing toast context
vi.mock("@/hooks/use-toast", () => ({
  useToast: () => ({ toast: vi.fn() }),
}));

beforeEach(() => {
  vi.stubGlobal("Blob", MockBlob);
  vi.stubGlobal("URL", {
    createObjectURL: mockCreateObjectURL,
    revokeObjectURL: mockRevokeObjectURL,
  });

  // Mock document.createElement to intercept anchor creation
  const originalCreateElement = document.createElement.bind(document);
  vi.spyOn(document, "createElement").mockImplementation((tag: string) => {
    if (tag === "a") {
      const anchor = originalCreateElement("a");
      anchor.click = mockAnchorClick;
      return anchor;
    }
    return originalCreateElement(tag);
  });

  vi.spyOn(document.body, "appendChild").mockImplementation(mockAppendChild);
  vi.spyOn(document.body, "removeChild").mockImplementation(mockRemoveChild);
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
  lastBlobContent = "";
  lastBlobOptions = {};
  mockAnchorClick.mockClear();
  mockCreateObjectURL.mockClear();
  mockRevokeObjectURL.mockClear();
});

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const sampleReports: Record<string, unknown> = {
  "agent-alpha": "نتيجة الوكيل ألفا",
};

const completedStep1: AgentTaskResult = {
  agentName: "محلل التحليل",
  agentId: "analysis-step",
  text: "نتيجة خطوة التحليل التفصيلية",
  confidence: 0.9,
  timestamp: "2026-04-03T10:00:00Z",
};

const completedStep2: AgentTaskResult = {
  agentName: "مولد الإبداع",
  agentId: "creative-step",
  text: "نتيجة خطوة الإبداع التفصيلية",
  confidence: 0.85,
  timestamp: "2026-04-03T10:01:00Z",
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function renderExporter(
  props: Partial<React.ComponentProps<typeof AgentReportsExporter>> = {}
) {
  const defaultProps = {
    reports: sampleReports,
    originalText: "النص الأصلي للنص الدرامي",
  };
  return render(<AgentReportsExporter {...defaultProps} {...props} />);
}

function clickJsonExport() {
  fireEvent.click(screen.getByRole("button", { name: /تصدير json/i }));
}

function clickTextExport() {
  fireEvent.click(screen.getByRole("button", { name: /تصدير نصي/i }));
}

// ---------------------------------------------------------------------------
// JSON Export Tests
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — JSON export", () => {
  it("produces valid JSON containing the reports object", () => {
    renderExporter();
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("reports");
    expect((parsed.reports as Record<string, unknown>)["agent-alpha"]).toBe(
      "نتيجة الوكيل ألفا"
    );
  });

  it("includes taskResults in JSON export when provided", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
      "creative-step": completedStep2,
    };

    renderExporter({ taskResults });
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("taskResults");

    const exportedResults = parsed.taskResults as Record<
      string,
      AgentTaskResult
    >;
    expect(exportedResults).toHaveProperty("analysis-step");
    expect(exportedResults["analysis-step"].text).toBe(
      "نتيجة خطوة التحليل التفصيلية"
    );
    expect(exportedResults["analysis-step"].agentName).toBe("محلل التحليل");
    expect(exportedResults).toHaveProperty("creative-step");
    expect(exportedResults["creative-step"].text).toBe(
      "نتيجة خطوة الإبداع التفصيلية"
    );
  });

  it("includes originalText in JSON export", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("originalText", "النص الأصلي للنص الدرامي");
  });

  it("taskResults defaults to empty object when not provided", () => {
    renderExporter();
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("taskResults");
    expect(parsed.taskResults).toEqual({});
  });

  it("uses application/json MIME type", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickJsonExport();

    expect(lastBlobOptions.type).toBe("application/json");
  });

  it("triggers file download (createObjectURL + anchor click)", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickJsonExport();

    expect(mockCreateObjectURL).toHaveBeenCalledOnce();
    expect(mockAnchorClick).toHaveBeenCalledOnce();
    expect(mockRevokeObjectURL).toHaveBeenCalledWith("blob:mock-url");
  });
});

// ---------------------------------------------------------------------------
// Text / Markdown Export Tests
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — Text/Markdown export", () => {
  it("produces text containing agent report sections", () => {
    renderExporter();
    clickTextExport();

    expect(lastBlobContent).toContain("نتائج التحليل");
    expect(lastBlobContent).toContain("agent-alpha");
    expect(lastBlobContent).toContain("نتيجة الوكيل ألفا");
  });

  it("includes originalText section when originalText is provided", () => {
    renderExporter({ originalText: "نص درامي تجريبي" });
    clickTextExport();

    expect(lastBlobContent).toContain("النص الأصلي");
    expect(lastBlobContent).toContain("نص درامي تجريبي");
  });

  it("appends ## {agentName} heading for each completed step", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
      "creative-step": completedStep2,
    };

    renderExporter({ taskResults });
    clickTextExport();

    expect(lastBlobContent).toContain("## محلل التحليل");
    expect(lastBlobContent).toContain("## مولد الإبداع");
  });

  it("appends step text body after each heading", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
    };

    renderExporter({ taskResults });
    clickTextExport();

    expect(lastBlobContent).toContain("نتيجة خطوة التحليل التفصيلية");
  });

  it("appends supporting steps section header when taskResults are present", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
    };

    renderExporter({ taskResults });
    clickTextExport();

    expect(lastBlobContent).toContain("النتائج الداعمة");
  });

  it("does not append supporting steps section when taskResults is empty", () => {
    renderExporter({ taskResults: {} });
    clickTextExport();

    expect(lastBlobContent).not.toContain("النتائج الداعمة");
  });

  it("does not append supporting steps section when taskResults is undefined", () => {
    renderExporter({ taskResults: undefined });
    clickTextExport();

    expect(lastBlobContent).not.toContain("النتائج الداعمة");
  });

  it("skips steps with empty text from the supporting steps section", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
      "empty-step": {
        agentName: "وكيل فارغ",
        agentId: "empty-step",
        text: "",
        confidence: 0,
        timestamp: "2026-04-03T10:02:00Z",
      },
      "whitespace-step": {
        agentName: "وكيل مسافات",
        agentId: "whitespace-step",
        text: "   ",
        confidence: 0,
        timestamp: "2026-04-03T10:03:00Z",
      },
    };

    renderExporter({ taskResults });
    clickTextExport();

    // Sections with text present
    expect(lastBlobContent).toContain("## محلل التحليل");
    // Steps without meaningful text must NOT appear as headings
    expect(lastBlobContent).not.toContain("## وكيل فارغ");
    expect(lastBlobContent).not.toContain("## وكيل مسافات");
  });

  it("uses text/plain MIME type with utf-8 charset", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickTextExport();

    expect(lastBlobOptions.type).toBe("text/plain;charset=utf-8");
  });

  it("triggers file download for text export", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickTextExport();

    expect(mockCreateObjectURL).toHaveBeenCalledOnce();
    expect(mockAnchorClick).toHaveBeenCalledOnce();
    expect(mockRevokeObjectURL).toHaveBeenCalledWith("blob:mock-url");
  });
});

// ---------------------------------------------------------------------------
// Missing / Empty taskResults — Robustness
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — missing/empty taskResults robustness", () => {
  it("JSON export does not throw when taskResults is undefined", () => {
    renderExporter({ taskResults: undefined });
    expect(() => clickJsonExport()).not.toThrow();
  });

  it("JSON export does not throw when taskResults is empty object", () => {
    renderExporter({ taskResults: {} });
    expect(() => clickJsonExport()).not.toThrow();
    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
