/**
 * Encrypted Screenplay Editor
 * محرر السيناريو المشفر
 *
 * يدمج التشفير Zero-Knowledge مع محرر السيناريو
 */

"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import {
  saveEncryptedDocument,
  loadEncryptedDocument,
  listEncryptedDocuments,
  deleteEncryptedDocument,
  getKeyManager,
} from "@/lib/crypto";

interface EncryptedEditorProps {
  userId: string;
  docId?: string;
  onSave?: (docId: string) => void;
  onLoad?: (content: string) => void;
  children: (props: EditorChildProps) => React.ReactNode;
}

interface EditorChildProps {
  content: string;
  isLoading: boolean;
  isSaving: boolean;
  error: string | null;
  onContentChange: (newContent: string) => void;
  onSave: () => Promise<void>;
  onLoad: (docId: string) => Promise<void>;
  onDelete: (docId: string) => Promise<void>;
  documents: DocumentMetadata[];
}

interface DocumentMetadata {
  id: string;
  version: number;
  ciphertextSize: number;
  createdAt: string;
  lastModified: string;
}

export function EncryptedScreenplayEditor({
  userId,
  docId,
  onSave,
  onLoad,
  children,
}: EncryptedEditorProps) {
  const router = useRouter();
  const [content, setContent] = useState("");
  const [currentDocId, setCurrentDocId] = useState(docId);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [documents, setDocuments] = useState<DocumentMetadata[]>([]);

  // التحقق من وجود KEK
  useEffect(() => {
    const keyManager = getKeyManager();
    if (!keyManager.hasKEK()) {
      router.push("/login?redirect=editor");
    }
  }, [router]);

  // تحميل المستند عند التهيئة
  useEffect(() => {
    if (currentDocId) {
      handleLoad(currentDocId);
    }
  }, [currentDocId]);

  // تحميل قائمة المستندات
  useEffect(() => {
    loadDocumentsList();
  }, []);

  const loadDocumentsList = async () => {
    const result = await listEncryptedDocuments();
    if (result.success && result.documents) {
      setDocuments(result.documents);
    }
  };

  const handleContentChange = useCallback((newContent: string) => {
    setContent(newContent);
    setError(null);
  }, []);

  const handleSave = async () => {
    setIsSaving(true);
    setError(null);

    try {
      const result = await saveEncryptedDocument({
        content,
        userId,
        ...(currentDocId ? { docId: currentDocId } : {}),
      });

      if (result.success) {
        if (!currentDocId && result.docId) {
          setCurrentDocId(result.docId);
        }
        await loadDocumentsList();
        onSave?.(result.docId || currentDocId || "");
      } else {
        setError(result.error || "فشل الحفظ");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "خطأ في الحفظ");
    } finally {
      setIsSaving(false);
    }
  };

  const handleLoad = async (docIdToLoad: string) => {
    setIsLoading(true);
    setError(null);

    try {
      const result = await loadEncryptedDocument({
        docId: docIdToLoad,
        userId,
      });

      if (result.success && result.content) {
        setContent(result.content);
        setCurrentDocId(docIdToLoad);
        onLoad?.(result.content);
      } else {
        setError(result.error || "فشل التحميل");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "خطأ في التحميل");
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (docIdToDelete: string) => {
    if (
      !confirm(
        "هل أنت متأكد من حذف هذا المستند؟ لا يمكن التراجع عن هذا الإجراء."
      )
    ) {
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const result = await deleteEncryptedDocument(docIdToDelete);

      if (result.success) {
        if (currentDocId === docIdToDelete) {
          setContent("");
          setCurrentDocId(undefined);
        }
        await loadDocumentsList();
      } else {
        setError(result.error || "فشل الحذف");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "خطأ في الحذف");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {children({
        content,
        isLoading,
        isSaving,
        error,
        onContentChange: handleContentChange,
        onSave: handleSave,
        onLoad: handleLoad,
        onDelete: handleDelete,
        documents,
      })}
    </>
  );
}

/**
 * مكون عرض الأخطاء
 */
export function EncryptionError({ error }: { error: string }) {
  return (
    <div
      className="fixed top-4 right-4 bg-red-50 border border-red-300 text-red-700 px-4 py-3 rounded shadow-lg z-50"
      role="alert"
      dir="rtl"
    >
      <div className="flex items-center">
        <svg className="w-5 h-5 ml-2" fill="currentColor" viewBox="0 0 20 20">
          <path
            fillRule="evenodd"
            d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
            clipRule="evenodd"
          />
        </svg>
        <p className="text-sm font-medium">{error}</p>
      </div>
    </div>
  );
}

/**
 * مكون حالة التشفير/الحفظ
 */
export function EncryptionStatus({
  isLoading,
  isSaving,
}: {
  isLoading: boolean;
  isSaving: boolean;
}) {
  if (!isLoading && !isSaving) return null;

  return (
    <div className="fixed bottom-4 right-4 bg-blue-50 border border-blue-300 text-blue-700 px-4 py-3 rounded shadow-lg z-50 flex items-center">
      <svg
        className="animate-spin h-5 w-5 ml-2"
        xmlns="http://www.w3.org/2000/svg"
        fill="none"
        viewBox="0 0 24 24"
      >
        <circle
          className="opacity-25"
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeWidth="4"
        />
        <path
          className="opacity-75"
          fill="currentColor"
          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
        />
      </svg>
      <span className="text-sm font-medium">
        {isLoading ? "جارٍ فك التشفير..." : "جارٍ الحفظ والتشفير..."}
      </span>
    </div>
  );
}

"use client";

import type React from "react";
import { useState } from "react";

const ERROR_IMG_SRC =
  "data:image/svg+xml;base64,";

export function ImageWithFallback(
  props: React.ImgHTMLAttributes<HTMLImageElement>
) {
  const [didError, setDidError] = useState(false);

  const handleError = () => {
    setDidError(true);
  };

  const { src, alt, style, className, ...rest } = props;

  if (didError) {
    return (
      <div
        className={`inline-block bg-muted text-center align-middle ${className ?? ""}`}
        style={style}
      >
        <div className="flex items-center justify-center w-full h-full">
          <img
            src={ERROR_IMG_SRC || "/placeholder.svg"}
            alt="Error loading image"
            {...rest}
            data-original-url={src}
          />
        </div>
      </div>
    );
  }

  return (
    <img
      src={src || "/placeholder.svg"}
      alt={alt}
      className={className}
      style={style}
      {...rest}
      onError={handleError}
    />
  );
}

"use client";

import { useState, useCallback } from "react";
import { Upload, File, X, CheckCircle, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";

interface FileUploadProps {
  onFileContent: (content: string, filename: string) => void;
  accept?: string;
  maxSize?: number; // in MB
  className?: string;
}

interface UploadedFile {
  name: string;
  size: number;
  type: string;
  content: string;
  status: "uploading" | "success" | "error";
  progress: number;
}

export default function FileUpload({
  onFileContent,
  accept = ".pdf,.docx,.txt",
  maxSize = 10,
  className = "",
}: FileUploadProps) {
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [isDragging, setIsDragging] = useState(false);

  const extractTextFromFile = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = async (e) => {
        try {
          const arrayBuffer = e.target?.result as ArrayBuffer;

          if (!arrayBuffer) {
            reject(new Error("فشل في قراءة الملف"));
            return;
          }

          if (file.type === "text/plain") {
            // Handle TXT files
            const text = new TextDecoder().decode(arrayBuffer);
            resolve(text);
          } else if (file.type === "application/pdf") {
            // Handle PDF files using PDF.js with proper worker setup
            const pdfjsLib = await import("pdfjs-dist");

            // Use CDN worker that works in production
            pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@4.4.168/build/pdf.worker.min.mjs`;

            const pdf = await pdfjsLib.getDocument({ data: arrayBuffer })
              .promise;
            let fullText = "";

            for (let i = 1; i <= pdf.numPages; i++) {
              const page = await pdf.getPage(i);
              const textContent = await page.getTextContent();
              const pageText = textContent.items
                .map((item: any) => item.str)
                .join(" ");
              fullText += pageText + "\n";
            }

            resolve(fullText);
          } else if (
            file.type ===
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
          ) {
            // Handle DOCX files using mammoth
            const mammoth = await import("mammoth");
            const result = await mammoth.extractRawText({ arrayBuffer });
            resolve(result.value);
          } else {
            reject(new Error("نوع الملف غير مدعوم"));
          }
        } catch (error) {
          reject(error);
        }
      };

      reader.onerror = () => reject(new Error("فشل في قراءة الملف"));
      reader.readAsArrayBuffer(file);
    });
  };

  const processFile = useCallback(
    async (file: File) => {
      // Add file to state with uploading status
      const newFile: UploadedFile = {
        name: file.name,
        size: file.size,
        type: file.type,
        content: "",
        status: "uploading",
        progress: 0,
      };

      setFiles((prev) => [...prev, newFile]);

      try {
        // Simulate progress
        const progressInterval = setInterval(() => {
          setFiles((prev) =>
            prev.map((f) =>
              f.name === file.name
                ? { ...f, progress: Math.min(f.progress + 10, 90) }
                : f
            )
          );
        }, 100);

        // Extract text content
        const content = await extractTextFromFile(file);

        clearInterval(progressInterval);

        // Update file status
        setFiles((prev) =>
          prev.map((f) =>
            f.name === file.name
              ? { ...f, content, status: "success", progress: 100 }
              : f
          )
        );

        // Call callback with content
        onFileContent(content, file.name);
      } catch (error) {
        setFiles((prev) =>
          prev.map((f) =>
            f.name === file.name ? { ...f, status: "error", progress: 0 } : f
          )
        );
        console.error("خطأ في معالجة الملف:", error);
      }
    },
    [onFileContent]
  );

  const handleFileSelect = useCallback(
    (selectedFiles: FileList | null) => {
      if (!selectedFiles) return;

      Array.from(selectedFiles).forEach((file) => {
        // Check file size
        if (file.size > maxSize * 1024 * 1024) {
          alert(`الملف ${file.name} كبير جداً. الحد الأقصى ${maxSize}MB`);
          return;
        }

        // Check file type
        const allowedTypes = [
          "text/plain",
          "application/pdf",
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        ];

        if (!allowedTypes.includes(file.type)) {
          alert(
            `نوع الملف ${file.name} غير مدعوم. الأنواع المدعومة: PDF, DOCX, TXT`
          );
          return;
        }

        processFile(file);
      });
    },
    [maxSize, processFile]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      handleFileSelect(e.dataTransfer.files);
    },
    [handleFileSelect]
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const removeFile = (fileName: string) => {
    setFiles((prev) => prev.filter((f) => f.name !== fileName));
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  };

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Upload Area */}
      <Card
        className={`border-2 border-dashed transition-colors ${
          isDragging
            ? "border-blue-500 bg-blue-50"
            : "border-gray-300 hover:border-gray-400"
        }`}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <CardContent className="p-8 text-center">
          <Upload className="w-12 h-12 mx-auto mb-4 text-gray-400" />
          <h3 className="text-lg font-semibold mb-2">تحميل الملفات</h3>
          <p className="text-gray-600 mb-4">
            اسحب الملفات هنا أو انقر للاختيار
          </p>
          <p className="text-sm text-gray-500 mb-4">
            الأنواع المدعومة: PDF, DOCX, TXT (حتى {maxSize}MB)
          </p>

          <input
            type="file"
            multiple
            accept={accept}
            onChange={(e) => handleFileSelect(e.target.files)}
            className="hidden"
            id="file-upload"
          />

          <Button asChild>
            <label htmlFor="file-upload" className="cursor-pointer">
              <Upload className="w-4 h-4 mr-2" />
              اختيار الملفات
            </label>
          </Button>
        </CardContent>
      </Card>

      {/* Uploaded Files List */}
      {files.length > 0 && (
        <div className="space-y-2">
          <h4 className="font-medium">الملفات المحملة:</h4>
          {files.map((file, index) => (
            <Card key={index} className="p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3 space-x-reverse">
                  <File className="w-5 h-5 text-blue-500" />
                  <div>
                    <p className="font-medium text-sm">{file.name}</p>
                    <p className="text-xs text-gray-500">
                      {formatFileSize(file.size)}
                    </p>
                  </div>
                </div>

                <div className="flex items-center space-x-2 space-x-reverse">
                  {file.status === "uploading" && (
                    <div className="flex items-center space-x-2 space-x-reverse">
                      <Progress value={file.progress} className="w-20" />
                      <span className="text-xs text-gray-500">
                        {file.progress}%
                      </span>
                    </div>
                  )}

                  {file.status === "success" && (
                    <CheckCircle className="w-5 h-5 text-green-500" />
                  )}

                  {file.status === "error" && (
                    <AlertCircle className="w-5 h-5 text-red-500" />
                  )}

                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => removeFile(file.name)}
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>
              </div>

              {file.status === "uploading" && (
                <Progress value={file.progress} className="mt-2" />
              )}
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { logger } from "@/lib/ai/utils/logger";
import { forwardRef } from "react";

interface VideoTextMaskProps {
  videoSrc: string;
  text: string;
  className?: string;
}

export const VideoTextMask = forwardRef<HTMLDivElement, VideoTextMaskProps>(
  ({ videoSrc, text, className = "" }, ref) => {
    return (
      <div className={`relative ${className}`}>
        {/* Wrapper للفيديو والماسك معاً - هذا الـ ref للتحريك */}
        <div ref={ref} className="absolute inset-0 w-full h-full">
          {/* الفيديو في الخلف */}
          <video
            autoPlay
            loop
            muted
            playsInline
            className="absolute inset-0 w-full h-full object-cover"
            style={{ zIndex: 1 }}
            src={videoSrc}
            onError={(e) => {
              logger.error("Video failed to load:", e);
              // Fallback to a solid color background
              e.currentTarget.style.display = "none";
            }}
          />

          {/* Canvas للنص مع تأثير القناع */}
          <canvas
            className="absolute inset-0 w-full h-full"
            style={{ zIndex: 2 }}
            ref={(canvas) => {
              if (!canvas) return;

              const ctx = canvas.getContext("2d");
              if (!ctx) return;

              const updateCanvas = () => {
                const rect = canvas.getBoundingClientRect();
                canvas.width = rect.width;
                canvas.height = rect.height;

                // Fill with white background
                ctx.fillStyle = "white";
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                // Set text properties
                const fontSize = Math.min(
                  canvas.width * 0.28,
                  canvas.height * 0.4
                );
                ctx.font = `900 ${fontSize}px 'Tajawal', 'Cairo', 'Noto Kufi Arabic', system-ui, sans-serif`;
                ctx.textAlign = "center";
                ctx.textBaseline = "middle";

                // Create text mask (black text cuts through white)
                ctx.globalCompositeOperation = "destination-out";
                ctx.fillStyle = "black";
                ctx.fillText(text, canvas.width / 2, canvas.height / 2);
              };

              updateCanvas();
              window.addEventListener("resize", updateCanvas);

              return () => {
                window.removeEventListener("resize", updateCanvas);
              };
            }}
          />
        </div>

        {/* خلفية سوداء احتياطية */}
        <div className="absolute inset-0 -z-10 bg-black" />

        {/* Fallback text if video fails */}
        <div
          className="absolute inset-0 flex items-center justify-center text-white"
          style={{ zIndex: 0 }}
        >
          <h1
            className="text-center m-0 p-0 leading-none opacity-20"
            style={{
              fontSize: "clamp(8rem, 28vw, 40rem)",
              fontWeight: 900,
              fontFamily:
                "'Tajawal', 'Cairo', 'Noto Kufi Arabic', 'system-ui', sans-serif",
              letterSpacing: "-0.08em",
            }}
          >
            {text}
          </h1>
        </div>
      </div>
    );
  }
);

VideoTextMask.displayName = "VideoTextMask";

