  PARTICLE_THRESHOLDS,
} from "@/components/particle-letters.constants";
import type {
  ParticleVelocity,
  ParticlePosition,
  EffectConfig,
} from "@/components/particle-effects";

import {
  getDeviceCapabilities,
  getParticleLODConfig,
  logDeviceCapabilities,
} from "@/components/device-detection";
import {
  applySparkEffect,
  applyWaveEffect,
  applyVortexEffect,
  applyDefaultEffect,
  calculateWaveColor,
  calculateVortexColor,
  performanceMonitor,
} from "@/components/particle-effects";

