                          const imageSrc = getImage(i);
                          const imageStyle = HERO_CARD_IMAGE_STYLES[imageSrc];
                          return (
                            <ImageWithFallback
                              src={imageSrc}
                              alt={`Scene ${i}`}
                              className="w-full h-full object-cover"
                              style={imageStyle}
                            />
                          );
                        })()}
                        <div className="hero-card-sheen absolute inset-0 pointer-events-none" />
                      </div>
