  // اختبار دالة المسافة للدائرة
  const sdCircle = (
    px: number,
    py: number,
    cx: number,
    cy: number,
    r: number
  ) => Math.hypot(px - cx, py - cy) - r;

  const result = sdCircle(1, 1, 0, 0, 2);
