      console.warn("خطأ تم التعامل معه:", (error as Error).message);
      return [];
    }
  };

  const result = testFunction(null);
  console.log(
    "✅ اختبار معالجة الأخطاء:",
    Array.isArray(result) && result.length === 0
  );
