  testSDF();
  testBatchProcessing();
  testErrorHandling();
  console.log("🎉 جميع الاختبارات نجحت!");
} catch (error) {
  console.error("❌ فشل في أحد الاختبارات:", error);
}

export { testSDF, testBatchProcessing, testErrorHandling };

