"use client";

import * as React from "react";
import * as LabelPrimitive from "@radix-ui/react-label";
import { Slot } from "@radix-ui/react-slot";
import {
  Controller,
  FormProvider,
  useFormContext,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from "react-hook-form";

import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";

const Form = FormProvider;

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName;
};

const FormFieldContext = React.createContext<FormFieldContextValue>(
  {} as FormFieldContextValue
);

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
};

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  const { getFieldState, formState } = useFormContext();

  const fieldState = getFieldState(fieldContext.name, formState);

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>");
  }

  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
};

type FormItemContextValue = {
  id: string;
};

const FormItemContext = React.createContext<FormItemContextValue>(
  {} as FormItemContextValue
);

const FormItem = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => {
  const id = React.useId();

  return (
    <FormItemContext.Provider value={{ id }}>
      <div ref={ref} className={cn("space-y-2", className)} {...props} />
    </FormItemContext.Provider>
  );
});
FormItem.displayName = "FormItem";

const FormLabel = React.forwardRef<
  React.ElementRef<typeof LabelPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root>
>(({ className, ...props }, ref) => {
  const { error, formItemId } = useFormField();

  return (
    <Label
      ref={ref}
      className={cn(error && "text-destructive", className)}
      htmlFor={formItemId}
      {...props}
    />
  );
});
FormLabel.displayName = "FormLabel";

const FormControl = React.forwardRef<
  React.ElementRef<typeof Slot>,
  React.ComponentPropsWithoutRef<typeof Slot>
>(({ ...props }, ref) => {
  const { error, formItemId, formDescriptionId, formMessageId } =
    useFormField();

  return (
    <Slot
      ref={ref}
      id={formItemId}
      aria-describedby={
        !error
          ? `${formDescriptionId}`
          : `${formDescriptionId} ${formMessageId}`
      }
      aria-invalid={!!error}
      {...props}
    />
  );
});
FormControl.displayName = "FormControl";

const FormDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => {
  const { formDescriptionId } = useFormField();

  return (
    <p
      ref={ref}
      id={formDescriptionId}
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
});
FormDescription.displayName = "FormDescription";

const FormMessage = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, children, ...props }, ref) => {
  const { error, formMessageId } = useFormField();
  const body = error ? String(error?.message ?? "") : children;

  if (!body) {
    return null;
  }

  return (
    <p
      ref={ref}
      id={formMessageId}
      className={cn("text-sm font-medium text-destructive", className)}
      {...props}
    >
      {body}
    </p>
  );
});
FormMessage.displayName = "FormMessage";

export {
  useFormField,
  Form,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  FormField,
};

"use client";
import React, { useCallback, useEffect, useState } from "react";

import { motion } from "motion/react";
import { cn } from "@/lib/utils";

type Direction = "TOP" | "LEFT" | "BOTTOM" | "RIGHT";

type HoverBorderGradientProps = {
  as?: React.ElementType;
  children?: React.ReactNode;
  containerClassName?: string;
  className?: string;
  duration?: number;
  clockwise?: boolean;
} & Record<string, unknown>;

export function HoverBorderGradient({
  children,
  containerClassName,
  className,
  as,
  duration = 6,
  clockwise = true,
  ...props
}: HoverBorderGradientProps) {
  const Tag = (as || "button") as React.ElementType;
  const tagProps = props as React.HTMLAttributes<HTMLElement>;
  const [hovered, setHovered] = useState<boolean>(false);
  const [direction, setDirection] = useState<Direction>("TOP");
  const handleMouseEnter = tagProps.onMouseEnter;
  const handleMouseLeave = tagProps.onMouseLeave;

  const rotateDirection = useCallback(
    (currentDirection: Direction): Direction => {
      const directions: Direction[] = ["TOP", "LEFT", "BOTTOM", "RIGHT"];
      const currentIndex = directions.indexOf(currentDirection);
      const nextIndex = clockwise
        ? (currentIndex - 1 + directions.length) % directions.length
        : (currentIndex + 1) % directions.length;
      return directions[nextIndex] ?? "TOP";
    },
    [clockwise]
  );

  const movingMap: Record<Direction, string> = {
    TOP: "radial-gradient(20.7% 50% at 50% 0%, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0) 100%)",
    LEFT: "radial-gradient(16.6% 43.1% at 0% 50%, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0) 100%)",
    BOTTOM:
      "radial-gradient(20.7% 50% at 50% 100%, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0) 100%)",
    RIGHT:
      "radial-gradient(16.2% 41.199999999999996% at 100% 50%, rgba(255, 255, 255, 0.18) 0%, rgba(255, 255, 255, 0) 100%)",
  };

  const highlight =
    "radial-gradient(75% 181.15942028985506% at 50% 50%, rgba(2, 151, 132, 0.72) 0%, rgba(255, 255, 255, 0) 100%)";

  useEffect(() => {
    if (hovered) return;

    const interval = window.setInterval(() => {
      setDirection((prevState) => rotateDirection(prevState));
    }, duration * 1000);

    return () => window.clearInterval(interval);
  }, [hovered, duration, rotateDirection]);

  const content = [
    <div
      key="hover-border-gradient-content"
      className={cn(
        "relative z-30 w-auto rounded-[inherit] bg-transparent text-current",
        className
      )}
    >
      {children}
    </div>,
    <motion.div
      key="hover-border-gradient-motion"
      className={cn(
        "pointer-events-none absolute inset-0 z-0 flex-none overflow-hidden rounded-[inherit]"
      )}
      style={{
        position: "absolute",
        width: "100%",
        height: "100%",
        padding: "1px",
        WebkitMask:
          "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
        WebkitMaskComposite: "xor",
        maskComposite: "exclude",
      }}
      initial={{ background: movingMap[direction] }}
      animate={{
        background: hovered
          ? [movingMap[direction], highlight]
          : movingMap[direction],
      }}
      transition={{ ease: "linear", duration: duration ?? 1 }}
    />,
    <div
      key="hover-border-gradient-overlay"
      className="pointer-events-none absolute inset-[2px] z-10 flex-none rounded-[100px] bg-transparent"
    />,
  ];

  return React.createElement(
    Tag,
    {
      ...tagProps,
      onMouseEnter: (event: React.MouseEvent<HTMLElement>) => {
        setHovered(true);
        handleMouseEnter?.(event);
      },
      onMouseLeave: (event: React.MouseEvent<HTMLElement>) => {
        setHovered(false);
        handleMouseLeave?.(event);
      },
      className: cn(
        "relative flex h-min w-fit flex-col flex-nowrap content-center items-center justify-center gap-10 overflow-visible rounded-full border bg-transparent p-px decoration-clone transition duration-500",
        containerClassName
      ),
    },
    ...content
  );
}

"use client";

import React, { useState, useCallback } from "react";
import Image, { ImageProps } from "next/image";

export interface ImageWithFallbackProps extends Omit<ImageProps, "src"> {
  src: string;
  fallbackSrc?: string;
  fallbackClassName?: string;
}

const ImageWithFallback = React.forwardRef<
  HTMLImageElement,
  ImageWithFallbackProps
>(
  (
    {
      src,
      fallbackSrc = "/images/fallback.jpg",
      fallbackClassName,
      onError,
      className,
      alt,
      ...props
    },
    ref
  ) => {
    const [currentSrc, setCurrentSrc] = useState(src);
    const [hasTriedFallback, setHasTriedFallback] = useState(false);
    const [isUsingFallback, setIsUsingFallback] = useState(false);
    const resolvedClassName = isUsingFallback
      ? [className, fallbackClassName].filter(Boolean).join(" ")
      : className;

    const handleError = useCallback(
      (error: React.SyntheticEvent<HTMLImageElement, Event>): void => {
        // إذا لم نكن قد جربنا fallback بعد، جربه
        if (!hasTriedFallback && currentSrc !== fallbackSrc) {
          setCurrentSrc(fallbackSrc);
          setHasTriedFallback(true);
          setIsUsingFallback(true);
        } else {
          // إذا فشل fallback أيضاً، استدعي onError الأصلي
          onError?.(error);
        }
      },
      [currentSrc, fallbackSrc, hasTriedFallback, onError]
    );

    const handleLoad = useCallback(
      (event: React.SyntheticEvent<HTMLImageElement, Event>): void => {
        // إذا تم تحميل الصورة بنجاح وأصبحنا نستخدم fallback، ذلك يعني أن fallback نجح
        if (isUsingFallback) {
          // سيتم التعامل مع هذا كما لو أن الصورة تحملت بنجاح
        }
        // استدعي onLoad الأصلي إذا كان موجوداً
        if (props.onLoad) {
          props.onLoad(event);
        }
      },
      [isUsingFallback, props.onLoad]
    );

    return (
      <Image
        ref={ref}
        src={currentSrc}
        alt={alt}
        className={resolvedClassName}
        onError={handleError}
        onLoad={handleLoad}
        {...props}
      />
    );
  }
);

ImageWithFallback.displayName = "ImageWithFallback";

export { ImageWithFallback };

