import { useState, useEffect } from "react";
import { getCurrentUser } from "@/lib/api";

export function useAuth() {
  const [user, setUser] = useState<unknown | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;

    async function fetchUser() {
      try {
        const userData = await getCurrentUser();
        if (mounted) {
          setUser(userData);
        }
      } catch {
        if (mounted) {
          setUser(null);
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    }

    fetchUser();

    return () => {
      mounted = false;
    };
  }, []);

  return { user, loading };
}

/**
 * Metrics API Hook
 *
 * Custom hook for fetching system metrics from backend
 */

import { useQuery } from "@tanstack/react-query";
import type {
  MetricsSnapshot,
  DashboardSummary,
  HealthStatus,
  PerformanceReport,
  DatabaseMetrics,
  RedisMetrics,
  QueueMetrics,
  ApiMetrics,
  ResourceMetrics,
  GeminiMetrics,
} from "@/types/metrics";

const API_BASE_URL = (process.env["NEXT_PUBLIC_API_URL"] || "").replace(
  /\/$/,
  ""
);

/**
 * Fetch helper with authentication
 */
async function fetchWithAuth<T>(endpoint: string): Promise<T> {
  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    headers: {
      "Content-Type": "application/json",
    },
    credentials: "include", // Include cookies for auth
  });

  if (!response.ok) {
    throw new Error(`API Error: ${response.status} ${response.statusText}`);
  }

  const data = await response.json();

  if (!data.success) {
    throw new Error(data.error || "Unknown error occurred");
  }

  return data.data;
}

/**
 * Hook to fetch dashboard summary
 */
export function useDashboardSummary(refreshInterval = 30000) {
  return useQuery<DashboardSummary>({
    queryKey: ["metrics", "dashboard"],
    queryFn: () => fetchWithAuth<DashboardSummary>("/api/metrics/dashboard"),
    refetchInterval: refreshInterval,
    staleTime: 20000, // Consider data stale after 20s
  });
}

