/**
 * Screenplay Editor Hooks - هوks محرر السيناريو
 *
 * hooks مخصصة لاستخدامها مع محرر السيناريو العربي
 *
 * @module hooks/useScreenplayEditor
 */

import { useEffect, useCallback, useRef } from "react";
import { useScreenplayStore } from "@/lib/stores/screenplayStore";
import { ScreenplayClassifier } from "@/lib/screenplay/classifier";
import type { FormattedLine } from "@/lib/stores/screenplayStore";

/**
 * hook لمحرر السيناريو
 * يوفر جميع الوظائف المطلوبة للمحرر
 */
export function useScreenplayEditor(documentId?: string) {
  const {
    content,
    formattedLines,
    cursorPosition,
    selection,
    isDirty,
    stats,
    settings,
    isSaving,
    isLoading,
    currentFormat,
    setContent,
    setFormattedLines,
    setCursorPosition,
    setSelection,
    saveDocument,
    loadDocument,
    exportDocument,
    markDirty,
    markClean,
    calculateStats,
    setCurrentFormat,
  } = useScreenplayStore();

  // Classifier instance
  const classifierRef = useRef(new ScreenplayClassifier());

  /**
   * Auto-save effect
   */
  useEffect(() => {
    if (!documentId || !isDirty) return;

    const timer = setTimeout(() => {
      saveDocument();
    }, settings.autoSaveInterval);

    return () => clearTimeout(timer);
  }, [content, isDirty, documentId, settings.autoSaveInterval]);

  /**
   * Load document on mount
   */
  useEffect(() => {
    if (documentId) {
      loadDocument(documentId);
    }
  }, [documentId]);

  /**
   * Process text and classify lines
   */
  const processText = useCallback(
    (text: string) => {
      const lines = text.split("\n");
      const newFormattedLines: FormattedLine[] = [];
      let lineNumber = 0;

      for (const line of lines) {
        lineNumber++;

        const lineType = classifierRef.current.classifyLine(line);

        newFormattedLines.push({
          id: `line_${lineNumber}_${Date.now()}`,
          text: line,
          type: lineType as any,
          number: lineNumber,
        });
      }

      setContent(text);
      setFormattedLines(newFormattedLines);
      calculateStats();
    },
    [setContent, setFormattedLines, calculateStats]
  );

  /**
   * Insert text at cursor
   */
  const insertText = useCallback(
    (text: string) => {
      if (selection) {
        const { start, end } = selection;
        const newContent =
          content.substring(0, start) + text + content.substring(end);
        processText(newContent);
        setCursorPosition(start + text.length);
        setSelection(null);
      } else {
        const newContent =
          content.substring(0, cursorPosition) +
          text +
          content.substring(cursorPosition);
        processText(newContent);
        setCursorPosition(cursorPosition + text.length);
      }

      markDirty();
    },
    [content, cursorPosition, selection, processText, markDirty]
  );

  /**
   * Delete text
   */
  const deleteText = useCallback(
    (start: number, end: number) => {
      const newContent = content.substring(0, start) + content.substring(end);
      processText(newContent);
      setCursorPosition(start);
      markDirty();
    },
    [content, processText, markDirty]
  );

  /**
   * Replace text
   */
  const replaceText = useCallback(
    (start: number, end: number, text: string) => {
      const newContent =
        content.substring(0, start) + text + content.substring(end);
      processText(newContent);
      setCursorPosition(start + text.length);
      markDirty();
    },
    [content, processText, markDirty]
  );

  /**
   * Format line
   */
  const formatLine = useCallback(
    (lineNumber: number, formatType: string) => {
      const newFormattedLines = [...formattedLines];
      if (newFormattedLines[lineNumber]) {
        newFormattedLines[lineNumber].type = formatType as any;
        setFormattedLines(newFormattedLines);
      }
    },
    [formattedLines, setFormattedLines]
  );

  /**
   * Apply formatting
   */
  const applyFormatting = useCallback(
    (formatType: string) => {
      if (selection) {
        // Format selected text
        const { start, end } = selection;

        let startLine = -1;
        let endLine = -1;
        let currentPos = 0;

        const lines = content.split("\n");

        for (let i = 0; i < lines.length; i++) {
          const line = lines[i] ?? "";
          const lineEnd = currentPos + line.length;

          if (startLine === -1 && start <= lineEnd) {
            startLine = i;
          }

          if (endLine === -1 && end <= lineEnd + 1) {
            endLine = i;
          }

          currentPos = lineEnd + 1;
        }

        if (endLine === -1) endLine = lines.length - 1;
        if (startLine === -1) startLine = 0;

        const newFormattedLines = [...formattedLines];
        let hasChanges = false;

        for (let i = startLine; i <= endLine; i++) {
          const formattedLine = newFormattedLines[i];
          if (formattedLine && formattedLine.type !== formatType) {
            newFormattedLines[i] = {
              ...formattedLine,
              type: formatType as FormattedLine["type"],
            };
            hasChanges = true;
          }
        }

        if (hasChanges) {
          setFormattedLines(newFormattedLines);
          markDirty();
        }
      } else {
        // Format current line
        setCurrentFormat(formatType);
      }
    },
    [
      content,
      selection,
      formattedLines,
      setFormattedLines,
      markDirty,
      setCurrentFormat,
    ]
  );

  return {
    // State
    content,
    formattedLines,
    cursorPosition,
    selection,
    isDirty,
    stats,
    settings,
    isSaving,
    isLoading,
    currentFormat,

    // Actions
    processText,
    insertText,
    deleteText,
    replaceText,
    formatLine,
    applyFormatting,
    saveDocument,
    exportDocument,
    markDirty,
    markClean,
    setCurrentFormat,
  };
}

/**
 * hook للتصدير
 */
export function useExportScreenplay() {
  const { content, exportDocument } = useScreenplayStore();

  const exportAsHTML = useCallback(() => {
    return exportDocument("html");
  }, [exportDocument]);

  const exportAsTXT = useCallback(() => {
    return exportDocument("txt");
  }, [exportDocument]);

  const exportAsPDF = useCallback(() => {
    return exportDocument("pdf");
  }, [exportDocument]);

  return {
    exportAsHTML,
    exportAsTXT,
    exportAsPDF,
    content,
  };
}

/**
 * hook للإحصائيات
 */
export function useScreenplayStats() {
  const { stats, calculateStats } = useScreenplayStore();

  useEffect(() => {
    calculateStats();
  }, []);

  return stats;
}

/**
 * hook للإعدادات
 */
export function useEditorSettings() {
  const { settings, updateSettings, setFontSize, setFontFamily, toggleTheme } =
    useScreenplayStore();

  return {
    settings,
    updateSettings,
    setFontSize,
    setFontFamily,
    toggleTheme,
  };
}

/**
 * hook للحفظ التلقائي
 */
export function useAutoSave(interval: number = 30000) {
  const { isDirty, saveDocument, updateSettings } = useScreenplayStore();

  useEffect(() => {
    // Update auto-save interval
    updateSettings({ autoSaveInterval: interval });
  }, [interval, updateSettings]);

  useEffect(() => {
    if (!isDirty) return;

    const timer = setInterval(() => {
      saveDocument();
    }, interval);

    return () => clearInterval(timer);
  }, [isDirty, interval, saveDocument]);
}

/**
 * hook لتصنيف النصوص
 */
export function useClassifier() {
  const classifierRef = useRef(new ScreenplayClassifier());

  /**
   * Classify a single line
   */
  const classifyLine = useCallback((line: string) => {
    return classifierRef.current.classifyLine(line);
  }, []);

  /**
   * Classify multiple lines
   */
  const classifyLines = useCallback(
    (lines: string[]) => {
      return lines.map((line) => classifyLine(line));
    },
    [classifyLine]
  );

  /**
   * Check if line is specific type
   */
  const isBasmala = useCallback((line: string) => {
    return ScreenplayClassifier.isBasmala(line);
  }, []);

  const isSceneHeader = useCallback((line: string) => {
    return ScreenplayClassifier.isSceneHeaderStart(line);
  }, []);

  const isCharacter = useCallback((line: string) => {
    return ScreenplayClassifier.isCharacterLine(line);
  }, []);

  const isDialogue = useCallback((line: string) => {
    return (
      !ScreenplayClassifier.isLikelyAction(line) &&
      !ScreenplayClassifier.isSceneHeaderStart(line) &&
      !ScreenplayClassifier.isCharacterLine(line)
    );
  }, []);

  const isAction = useCallback((line: string) => {
    return ScreenplayClassifier.isLikelyAction(line);
  }, []);

  const isTransition = useCallback((line: string) => {
    return ScreenplayClassifier.isTransition(line);
  }, []);

  return {
    classifyLine,
    classifyLines,
    isBasmala,
    isSceneHeader,
    isCharacter,
    isDialogue,
    isAction,
    isTransition,
  };
}

/**
 * @module hooks/useSevenStationsAnalysis
 * @description هوك مخصص لإدارة تحليل المحطات السبع للتحليل الدرامي
 *
 * السبب: فصل منطق إدارة الحالة وعمليات الـ API عن مكونات واجهة المستخدم،
 * مما يسهّل الصيانة، الاختبار، وإعادة الاستخدام.
 *
 * يوفر هذا الهوك:
 * - إدارة حالة التحليل (text, status, result, error)
 * - وظيفة تنفيذ التحليل مع التحقق من الصحة
 * - معالجة الأخطاء موحدة مع toast notifications
 */

"use client";

import { useState, useCallback, useMemo } from "react";
import { toast } from "@/hooks/use-toast";
import {
  type AnalysisResult,
  type AnalysisStatus,
  AnalysisRequestSchema,
  AnalysisResultSchema,
  ANALYSIS_ERROR_MESSAGES,
} from "@/types/analysis";

/**
 * واجهة القيم المرتجعة من الهوك
 */
interface UseSevenStationsAnalysisReturn {
  /** النص الحالي للتحليل */
  text: string;
  /** تعيين النص للتحليل */
  setText: (text: string) => void;
  /** حالة التحليل الحالية */
  status: AnalysisStatus;
  /** هل التحليل جاري حالياً */
  isAnalyzing: boolean;
  /** نتيجة التحليل */
  result: AnalysisResult | null;
  /** رسالة الخطأ */
  error: string | null;
  /** تنفيذ التحليل */
  analyze: () => Promise<void>;
  /** إعادة تعيين الحالة */
  reset: () => void;
  /** هل يمكن بدء التحليل */
  canAnalyze: boolean;
}

/**
 * خيارات تهيئة الهوك
 */
interface UseSevenStationsAnalysisOptions {
  /** تفعيل تحليل التدفقات */
  enableFlows?: boolean;
  /** تفعيل RAG للنصوص الطويلة */
  enableRAG?: boolean;
  /** معالج نجاح مخصص */
  onSuccess?: (result: AnalysisResult) => void;
  /** معالج خطأ مخصص */
  onError?: (error: string) => void;
}

/**
 * هوك مخصص لإدارة تحليل المحطات السبع
 *
 * السبب الرئيسي: فصل منطق الأعمال عن واجهة المستخدم يُسهّل:
 * 1. اختبار المنطق بشكل مستقل
 * 2. إعادة استخدام المنطق في مكونات متعددة
 * 3. تبسيط المكونات وجعلها أكثر قابلية للقراءة
 *
 * @param options - خيارات تهيئة الهوك
 * @returns كائن يحتوي على الحالة والدوال
 *
 * @example
 * ```tsx
 * const { text, setText, analyze, result, isAnalyzing } = useSevenStationsAnalysis();
 * ```
 */
export function useSevenStationsAnalysis(
  options: UseSevenStationsAnalysisOptions = {}
): UseSevenStationsAnalysisReturn {
  const { enableFlows = true, enableRAG = true, onSuccess, onError } = options;

  // ==========================================
  // الحالة الداخلية
  // ==========================================

  const [text, setText] = useState("");
  const [status, setStatus] = useState<AnalysisStatus>("idle");
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  // ==========================================
  // القيم المحسوبة
  // ==========================================

  /**
   * هل التحليل جاري حالياً
   * السبب: تبسيط التحقق من حالة التحميل
   */
  const isAnalyzing = useMemo(() => status === "loading", [status]);

  /**
   * هل يمكن بدء التحليل
   * السبب: التحقق من إمكانية بدء التحليل
   */
  const canAnalyze = useMemo(
    () => text.trim().length > 0 && !isAnalyzing,
    [text, isAnalyzing]
  );

  // ==========================================
  // معالجة الأخطاء
  // ==========================================

  /**
   * عرض رسالة خطأ موحدة
   * السبب: توحيد تجربة المستخدم عند حدوث أخطاء
   */
  const showError = useCallback(
    (message: string) => {
      setError(message);
      toast({
        variant: "destructive",
        title: "خطأ في التحليل",
        description: message,
      });
      onError?.(message);
    },
    [onError]
  );

  /**
   * عرض رسالة نجاح
   * السبب: إعلام المستخدم بنجاح العملية
   */
  const showSuccess = useCallback(() => {
    toast({
      title: "تم التحليل بنجاح",
      description: "اكتمل تحليل السيناريو عبر المحطات السبع",
    });
  }, []);

  // ==========================================
  // وظائف التحليل
  // ==========================================

  /**
   * تنفيذ التحليل
   * السبب: العملية الرئيسية للهوك - إرسال النص للتحليل
   * يحاول أولاً عبر الخادم، وعند الفشل يقبل أي بيانات صالحة أو يُبلغ بالخطأ
   */
  const analyze = useCallback(async () => {
    // التحقق من صحة المدخلات
    const validationResult = AnalysisRequestSchema.safeParse({
      text,
      enableFlows,
      enableRAG,
    });

    if (!validationResult.success) {
      showError(ANALYSIS_ERROR_MESSAGES.EMPTY_TEXT);
      return;
    }

    // تحديث الحالة
    setStatus("loading");
    setError(null);
    setResult(null);

    try {
      // إرسال الطلب للـ API عبر المسار العام
      const response = await fetch("/api/public/analysis/seven-stations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: validationResult.data.text,
          async: false,
        }),
      });

      // التحقق من حالة الاستجابة
      if (!response.ok) {
        const errorText = await response.text().catch(() => "");
        throw new Error(
          `${ANALYSIS_ERROR_MESSAGES.API_ERROR}: ${response.status}${errorText ? ` — ${errorText.slice(0, 200)}` : ""}`
        );
      }

      // تحليل الاستجابة
      const data = await response.json();

      // قبول أي بيانات تحتوي success أو detailedResults أو stationOutputs
      // بدون رفض صارم عبر Zod (البنية تختلف بين AI و fallback)
      const parseResult = AnalysisResultSchema.safeParse(data);

      if (parseResult.success) {
        setResult(parseResult.data);
      } else {
        // البيانات قد تكون بصيغة pipeline payload أو backend response
        // نقبلها كما هي لأن المكوّنات تتعامل مع الشكلين
        setResult(data as AnalysisResult);
      }

      // حفظ handoff لصفحة التطوير
      try {
        localStorage.setItem("sevenStationsAnalysis", JSON.stringify(data));
        sessionStorage.setItem("stationAnalysisResults", JSON.stringify(data));
      } catch {
        // التخزين قد لا يتوفر
      }

      setStatus("success");
      showSuccess();
      onSuccess?.(data);
    } catch (err) {
      setStatus("error");
      const errorMessage =
        err instanceof Error
          ? err.message
          : ANALYSIS_ERROR_MESSAGES.UNKNOWN_ERROR;
      showError(errorMessage);
    }
  }, [text, enableFlows, enableRAG, onSuccess, showError, showSuccess]);

  /**
   * إعادة تعيين الحالة
   * السبب: تمكين المستخدم من بدء تحليل جديد
   */
  const reset = useCallback(() => {
    setText("");
    setStatus("idle");
    setResult(null);
    setError(null);
  }, []);

  // ==========================================
  // القيم المرتجعة
  // ==========================================

  return {
    text,
    setText,
    status,
    isAnalyzing,
    result,
    error,
    analyze,
    reset,
    canAnalyze,
  };
}

import { logger } from "@/lib/ai/utils/logger";

import * as Sentry from "@sentry/nextjs";

export async function register() {
  const dsn = process.env["NEXT_PUBLIC_SENTRY_DSN"];
  const isDevelopment = process.env["NODE_ENV"] === "development";

  // تعطيل Sentry تماماً في Development لتجنب logging spam
  if (isDevelopment) {
    logger.info("[Sentry] Disabled in development mode");
    return;
  }

  if (!dsn) {
    logger.warn("[Sentry] DSN not configured, monitoring disabled");
    return;
  }

  if (process.env["NEXT_RUNTIME"] === "nodejs") {
    // Server-side initialization
    Sentry.init({
      dsn,
      environment: process.env["NODE_ENV"] || "development",
      tracesSampleRate: isDevelopment ? 0.1 : 0.2,
      debug: false,
      tracePropagationTargets: [
        "localhost",
        process.env["BACKEND_URL"] || "",
        "googleapis.com",
      ],
      integrations: [Sentry.httpIntegration()],
      profilesSampleRate: isDevelopment ? 0.1 : 0.2,
      beforeSend(event) {
        if (isDevelopment) return null;
        return event;
      },
      beforeSendTransaction(event) {
        if (event.transaction?.startsWith("/api/")) {
          event.transaction = event.transaction.replace(
            /\/[0-9a-f-]{36}/g,
            "/:id"
          );
        }
        return event;
      },
      tracesSampler(samplingContext) {
        const pathname = samplingContext.name || "";
        if (pathname.includes("/api/") || pathname.includes("/genkit/")) {
          return 1.0;
        }
        return isDevelopment ? 1.0 : 0.2;
      },
    });
    logger.info("[Sentry] Server initialized");
  }

  if (process.env["NEXT_RUNTIME"] === "edge") {
    // Edge runtime initialization
    Sentry.init({
      dsn,
      environment: process.env["NODE_ENV"] || "development",
      tracesSampleRate: isDevelopment ? 0.1 : 0.2,
      debug: false,
      integrations: [],
      beforeSend(event) {
        if (isDevelopment) return null;
        return event;
      },
      beforeSendTransaction(event) {
        if (event.transaction?.startsWith("/api/")) {
          event.transaction = event.transaction.replace(
            /\/[0-9a-f-]{36}/g,
            "/:id"
          );
        }
        return event;
      },
      tracesSampler(samplingContext) {
        const pathname = samplingContext.name || "";
        if (pathname.includes("/api/")) {
          return 1.0;
        }
        return isDevelopment ? 1.0 : 0.2;
      },
    });
    logger.info("[Sentry] Edge runtime initialized");
  }
}

export const onRequestError = Sentry.captureRequestError;

import { describe, it, expect, beforeEach, vi, afterEach } from "vitest";
import {
  getCurrentProject,
  setCurrentProject,
  clearCurrentProject,
} from "../projectStore";
import type { Project } from "../projectStore";

describe("projectStore", () => {
  const mockProject: Project = {
    id: "test-123",
    name: "Test Project",
    description: "A test project",
  };

  beforeEach(() => {
    // Clear storage before each test
    sessionStorage.clear();
    // Clear memory store by calling clearCurrentProject
    clearCurrentProject();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe("getCurrentProject", () => {
    it("should return null initially", () => {
      expect(getCurrentProject()).toBeNull();
    });

    it("should return project from sessionStorage if available", () => {
      sessionStorage.setItem("currentProject", JSON.stringify(mockProject));

      const project = getCurrentProject();
      expect(project).toEqual(mockProject);
    });

    it("should return project from memory if sessionStorage is empty but project was set", () => {
      // Temporarily mock window to be undefined to only set memory
      const originalWindow = global.window;
      // @ts-expect-error Mocking window to test memory store
      delete global.window;

      setCurrentProject(mockProject);

      // Restore window
      global.window = originalWindow;

      // Now getCurrentProject should return from memory because sessionStorage is empty
      expect(getCurrentProject()).toEqual(mockProject);
    });

    it("should fall back to memory when window is undefined", () => {
      setCurrentProject(mockProject);

      const originalWindow = global.window;
      // @ts-expect-error Mocking window to test undefined behavior
      delete global.window;

      expect(getCurrentProject()).toEqual(mockProject);

      global.window = originalWindow;
    });
  });

  describe("setCurrentProject", () => {
    it("should set project in memory and sessionStorage", () => {
      setCurrentProject(mockProject);

      expect(getCurrentProject()).toEqual(mockProject);
      expect(JSON.parse(sessionStorage.getItem("currentProject")!)).toEqual(
        mockProject
      );
    });

    it("should only set in memory when window is undefined", () => {
      const originalWindow = global.window;
      // @ts-expect-error Mocking window to test undefined behavior
      delete global.window;

      setCurrentProject(mockProject);

      expect(getCurrentProject()).toEqual(mockProject);

      global.window = originalWindow;

      // sessionStorage should still be empty since window was undefined during set
      expect(sessionStorage.getItem("currentProject")).toBeNull();
    });
  });

  describe("clearCurrentProject", () => {
    it("should clear project from memory and sessionStorage", () => {
      setCurrentProject(mockProject);
      clearCurrentProject();

      expect(getCurrentProject()).toBeNull();
      expect(sessionStorage.getItem("currentProject")).toBeNull();
    });

    it("should only clear from memory when window is undefined", () => {
      setCurrentProject(mockProject);

      const originalWindow = global.window;
      // @ts-expect-error Mocking window to test undefined behavior
      delete global.window;

      clearCurrentProject();

      expect(getCurrentProject()).toBeNull();

      global.window = originalWindow;

      // sessionStorage should still have the item since window was undefined during clear
      expect(JSON.parse(sessionStorage.getItem("currentProject")!)).toEqual(
        mockProject
      );
    });
  });
});

"use server";

import { z } from "zod";
import { clientEnv } from "@/env";
import {
  buildFallbackSevenStationsResult,
  serializeAnalysisValue,
  type AnalysisPipelinePayload,
} from "@/lib/analysis/seven-stations-fallback";

// ==========================================
// مخطط التحقق من مدخلات خط الأنابيب
// ==========================================
const pipelineRequestSchema = z.object({
  fullText: z.string().min(1, "النص مطلوب"),
  projectName: z.string().min(1).default("تحليل درامي شامل"),
});

export type PipelineInput = z.infer<typeof pipelineRequestSchema>;
export type PipelineResult = AnalysisPipelinePayload;

// ==========================================
// ثوابت المحطات المتوقعة
// ==========================================
const EXPECTED_STATION_KEYS = [
  "station1",
  "station2",
  "station3",
  "station4",
  "station5",
  "station6",
  "station7",
] as const;

// ==========================================
// تحديد عنوان الخادم الخلفي
// ==========================================
function resolveBackendBaseUrl(): string | null {
  // الأولوية: متغيرات الخادم ثم متغيرات العميل ثم القيمة الافتراضية للتطوير
  return (
    process.env["NEXT_PUBLIC_API_URL"] ||
    process.env["NEXT_PUBLIC_BACKEND_URL"] ||
    process.env["BACKEND_URL"] ||
    clientEnv.NEXT_PUBLIC_API_URL ||
    clientEnv.NEXT_PUBLIC_BACKEND_URL ||
    (process.env["NODE_ENV"] !== "production"
      ? "http://localhost:3001"
      : null) ||
    null
  );
}

// ==========================================
// تطبيع مخرجات محطة واحدة من الخادم إلى الشكل الموحد
// ==========================================
// الخادم يعيد: { stationId, stationName, details: { fullAnalysis, finalReport, ... } }
// الواجهة تتوقع: محتوى مسطّح مباشر (logline, majorCharacters, finalReport, ...)
function normalizeBackendStation(
  raw: Record<string, unknown>
): Record<string, unknown> {
  // إذا كان المحتوى يحتوي مباشرة على بنية الـ fallback، أعِده كما هو
  if (
    raw.logline ||
    raw.finalReport ||
    raw.efficiencyMetrics ||
    raw.dynamicAnalysisResults
  ) {
    return raw;
  }

  // إذا كان بشكل الخادم الخلفي { details: { ... } }، استخرج المحتوى
  const details = raw.details as Record<string, unknown> | undefined;
  if (details && typeof details === "object") {
    return {
      ...details,
      stationId: raw.stationId,
      stationName: raw.stationName,
      status: raw.status,
      executionTime: raw.executionTime,
    };
  }

  // أعِده كما هو مع كل الحقول
  return raw;
}

// ==========================================
// تطبيع نتيجة خط الأنابيب الكاملة
// ==========================================
function normalizePipelineResult(
  result: Record<string, unknown>,
  request: PipelineInput
): AnalysisPipelinePayload {
  const rawOutputs = (result.stationOutputs ||
    result.detailedResults ||
    {}) as Record<string, Record<string, unknown>>;

  const serialized = serializeAnalysisValue(rawOutputs) as Record<
    string,
    Record<string, unknown>
  >;

  // تطبيع كل محطة من شكل الخادم إلى الشكل الموحد
  const normalizedOutputs: Record<string, Record<string, unknown>> = {};
  for (const key of EXPECTED_STATION_KEYS) {
    if (serialized[key] && typeof serialized[key] === "object") {
      normalizedOutputs[key] = normalizeBackendStation(serialized[key]);
    }
  }

  const metadata = serializeAnalysisValue(
    (result.metadata || result.pipelineMetadata || {}) as Record<
      string,
      unknown
    >
  ) as Record<string, unknown>;

  const hasStations = Object.keys(normalizedOutputs).length > 0;

  if (!hasStations) {
    throw new Error(
      "لم تُنتج المحطات أي مخرجات قابلة للعرض — " +
        `المفاتيح الواردة: [${Object.keys(serialized).join(", ")}]`
    );
  }

  return {
    success: Boolean(result.success),
    mode: "ai",
    warnings: [],
    stationOutputs:
      normalizedOutputs as AnalysisPipelinePayload["stationOutputs"],
    metadata: {
      ...metadata,
      analysisMode: "ai",
      projectName: request.projectName,
      textLength: request.fullText.length,
    },
  };
}

// ==========================================
// تنفيذ خط الأنابيب مع fallback تلقائي
// ==========================================
export async function runFullPipeline(
  input: PipelineInput
): Promise<PipelineResult> {
  const request = pipelineRequestSchema.parse(input);
  const backendBaseUrl = resolveBackendBaseUrl();

  // إذا لم يكن الخادم مهيأ، فعّل المسار الاحتياطي مباشرة
  if (!backendBaseUrl) {
    return buildFallbackSevenStationsResult({
      fullText: request.fullText,
      projectName: request.projectName,
      warning:
        "لم يتم تهيئة عنوان الخادم الخلفي — يتم استخدام المسار الاحتياطي المحلي.",
    });
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 280_000); // أقل من maxDuration

    const response = await fetch(
      `${backendBaseUrl.replace(/\/$/, "")}/api/public/analysis/seven-stations`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: request.fullText, async: false }),
        cache: "no-store",
        signal: controller.signal,
      }
    );

    clearTimeout(timeoutId);

    if (!response.ok) {
      const errorText = await response.text().catch(() => "");
      const statusDetail = `HTTP ${response.status}${errorText ? ` — ${errorText.slice(0, 200)}` : ""}`;
      // فشل الخادم — تفعيل المسار الاحتياطي
      return buildFallbackSevenStationsResult({
        fullText: request.fullText,
        projectName: request.projectName,
        warning: `فشل الخادم الخلفي (${statusDetail}) — يتم استخدام التحليل الاحتياطي المحلي.`,
      });
    }

    const payload = (await response.json()) as Record<string, unknown>;

    // المسار الأول: الخادم يعيد detailedResults (شكل buildPipelineResponse)
    if (payload.detailedResults) {
      try {
        return normalizePipelineResult(
          { ...payload, stationOutputs: payload.detailedResults },
          request
        );
      } catch {
        // إذا فشل التطبيع، فعّل المسار الاحتياطي
        return buildFallbackSevenStationsResult({
          fullText: request.fullText,
          projectName: request.projectName,
          warning:
            "بيانات الخادم الخلفي غير مكتملة — يتم استخدام التحليل الاحتياطي.",
        });
      }
    }

    // المسار الثاني: الخادم يعيد stationOutputs مباشرة
    if (payload.stationOutputs) {
      try {
        return normalizePipelineResult(payload, request);
      } catch {
        return buildFallbackSevenStationsResult({
          fullText: request.fullText,
          projectName: request.projectName,
          warning:
            "بيانات الخادم غير قابلة للتطبيع — يتم استخدام التحليل الاحتياطي.",
        });
      }
    }

    // لا detailedResults ولا stationOutputs — المسار الاحتياطي
    return buildFallbackSevenStationsResult({
      fullText: request.fullText,
      projectName: request.projectName,
      warning:
        "استجابة الخادم لا تحتوي على مخرجات محطات — يتم استخدام التحليل الاحتياطي.",
    });
  } catch (error) {
    // أي خطأ شبكي أو timeout — فعّل المسار الاحتياطي
    const reason = error instanceof Error ? error.message : "خطأ غير معروف";
    return buildFallbackSevenStationsResult({
      fullText: request.fullText,
      projectName: request.projectName,
      warning: `تعذر الاتصال بالخادم الخلفي (${reason}) — يتم استخدام التحليل الاحتياطي المحلي.`,
    });
  }
}

"use server";

/**
 * @fileOverview AI team agent for brainstorming ideas for screenwriters.
 *
 * - aiTeamBrainstorming - A function to initiate the brainstorming process with AI agents.
 * - AITeamBrainstormingInput - The input type for the aiTeamBrainstorming function.
 * - AITeamBrainstormingOutput - The return type for the aiTeamBrainstorming function.
 */

import { ai } from "@/ai/genkit";
import { z } from "genkit";

const AITeamBrainstormingInputSchema = z.object({
  scriptConcept: z
    .string()
    .describe("The initial concept or premise for the script."),
  numberOfAgents: z
    .number()
    .min(2)
    .max(5)
    .default(3)
    .describe("The number of AI agents to use for brainstorming (2-5)."),
  specificRequests: z
    .string()
    .optional()
    .describe(
      "Any specific requests or guidelines for the brainstorming session."
    ),
});
export type AITeamBrainstormingInput = z.infer<
  typeof AITeamBrainstormingInputSchema
>;

const AITeamBrainstormingOutputSchema = z.object({
  brainstormingSessionSummary: z
    .string()
    .describe(
      "A summary of the brainstorming session, including key ideas and perspectives."
    ),
  agentIdeas: z.array(
    z.object({
      agentName: z.string().describe("The name of the AI agent."),
      ideas: z.array(z.string()).describe("Ideas generated by the agent."),
    })
  ),
});
export type AITeamBrainstormingOutput = z.infer<
  typeof AITeamBrainstormingOutputSchema
>;

export async function aiTeamBrainstorming(
  input: AITeamBrainstormingInput
): Promise<AITeamBrainstormingOutput> {
  return aiTeamBrainstormingFlow(input);
}

const agentPrompt = ai.definePrompt({
  name: "agentPrompt",
  input: { schema: AITeamBrainstormingInputSchema },
  output: { schema: z.object({ ideas: z.array(z.string()) }) },
  prompt: `You are an AI agent participating in a brainstorming session for a screenplay.

  Your task is to generate creative and innovative ideas based on the provided script concept and any specific requests.

  Script Concept: {{{scriptConcept}}}
  Specific Requests: {{{specificRequests}}}

  Generate a list of ideas that could enhance the script, explore new directions, or address potential weaknesses. Be creative, unconventional, and think outside the box.

  Ideas (as a numbered list):
  `,
});

const aiTeamBrainstormingFlow = ai.defineFlow(
  {
    name: "aiTeamBrainstormingFlow",
    inputSchema: AITeamBrainstormingInputSchema,
    outputSchema: AITeamBrainstormingOutputSchema,
  },
  async (input) => {
    const { numberOfAgents, scriptConcept, specificRequests } = input;

    const agentTasks = Array.from({ length: numberOfAgents }, (_, i) => {
      const agentName = `Agent${i + 1}`;
      return {
        agentName,
        task: agentPrompt(input),
      };
    });

    const agentResults = await Promise.all(
      agentTasks.map(async (agentTask) => {
        const taskResult = await agentTask.task;
        return {
          agentName: agentTask.agentName,
          ideas: taskResult.output?.ideas || [],
        };
      })
    );

    const brainstormingSessionSummary = `Brainstorming session with ${numberOfAgents} agents for the script concept: ${scriptConcept}. Specific requests: ${specificRequests || "None"}.`;

    return {
      brainstormingSessionSummary,
      agentIdeas: agentResults,
    };
  }
);

// Constitutional AI Module - Exports all constitutional AI functionality

// Core ConstitutionalAI class (defined below)
export interface ConstitutionalPrinciple {
  id: string;
  name: string;
  description: string;
  weight: number;
}

export interface ConstitutionalCheck {
  principle: ConstitutionalPrinciple;
  passed: boolean;
  confidence: number;
  explanation: string;
}

export interface ConstitutionalResult {
  overallScore: number;
  checks: ConstitutionalCheck[];
  recommendations: string[];
}

export class ConstitutionalAI {
  private principles: ConstitutionalPrinciple[] = [
    {
      id: "helpfulness",
      name: "Helpfulness",
      description: "Content should be helpful and constructive",
      weight: 1.0,
    },
    {
      id: "harmlessness",
      name: "Harmlessness",
      description: "Content should not cause harm",
      weight: 1.0,
    },
    {
      id: "honesty",
      name: "Honesty",
      description: "Content should be truthful and accurate",
      weight: 1.0,
    },
  ];

  async evaluate(_content: string): Promise<ConstitutionalResult> {
    const checks: ConstitutionalCheck[] = [];

    for (const principle of this.principles) {
      const check: ConstitutionalCheck = {
        principle,
        passed: true,
        confidence: 0.9,
        explanation: `Content adheres to ${principle.name} principle`,
      };
      checks.push(check);
    }

    const overallScore =
      checks.reduce(
        (sum, check) =>
          sum + (check.passed ? check.confidence * check.principle.weight : 0),
        0
      ) / checks.length;

    return {
      overallScore,
      checks,
      recommendations: [],
    };
  }
}

export const constitutionalAI = new ConstitutionalAI();

// Export from multi-agent-debate.ts
export {
  MultiAgentDebateSystem,
  getMultiAgentDebateSystem,
} from "./multi-agent-debate";
export type {
  DebateParticipant,
  DebateArgument,
  DebateRound,
  ConsensusArea,
  DisputedArea,
  FinalVerdict,
  DebateVerdict,
  DebateDynamics,
  DebateResult,
} from "./multi-agent-debate";

// Export from principles.ts
export { checkConstitutionalCompliance } from "./principles";
export type { ConstitutionalCheckResult } from "./principles";

// Export from uncertainty-quantification.ts
export { getUncertaintyQuantificationEngine } from "./uncertainty-quantification";
export type {
  UncertaintyMetrics,
  UncertaintyQuantificationEngine,
} from "./uncertainty-quantification";

export default constitutionalAI;

// frontend/src/lib/ai/constitutional/multi-agent-debate.ts

import { GeminiService } from "../../ai/stations/gemini-service";
import { stripHtmlTags } from "@/lib/security/sanitize-html";

export interface DebateParticipant {
  role: "prosecutor" | "defender" | "judge";
  name: string;
  perspective: string;
}

export interface DebateArgument {
  participant: string;
  argument: string;
  evidence: string[];
  strength: number;
}

export interface DebateRound {
  round: number;
  prosecutorArgument: DebateArgument;
  defenderArgument: DebateArgument;
  judgeComments: string;
}

export interface ConsensusArea {
  aspect: string;
  agreement: string;
  confidence: number;
}

export interface DisputedArea {
  aspect: string;
  prosecutorView: string;
  defenderView: string;
  judgeOpinion: string;
  resolution: string;
}

export interface FinalVerdict {
  overallAssessment: string;
  strengths: string[];
  weaknesses: string[];
  recommendations: string[];
  confidence: number;
}

export interface DebateVerdict {
  consensusAreas: ConsensusArea[];
  disputedAreas: DisputedArea[];
  finalVerdict: FinalVerdict;
}

export interface DebateDynamics {
  rounds: number;
  convergenceScore: number; // مدى تقارب الآراء
  controversialTopics: string[];
}

export interface DebateResult {
  participants: DebateParticipant[];
  rounds: DebateRound[];
  verdict: DebateVerdict;
  debateDynamics: DebateDynamics;
}

export class MultiAgentDebateSystem {
  constructor(private geminiService: GeminiService) {}

  /**
   * إجراء نقاش متعدد الوكلاء حول تحليل
   */
  async conductDebate(
    text: string,
    analysis: string,
    context: {
      analysisType: string;
      previousResults?: any;
    },
    maxRounds: number = 3
  ): Promise<DebateResult> {
    console.log(
      `[Multi-Agent Debate] Starting debate with max ${maxRounds} rounds`
    );

    // Define participants
    const participants: DebateParticipant[] = [
      {
        role: "prosecutor",
        name: "المدعي الناقد",
        perspective: "تحديد نقاط الضعف والأخطاء والتحيزات",
      },
      {
        role: "defender",
        name: "المدافع البناء",
        perspective: "إبراز نقاط القوة والجوانب الإيجابية",
      },
      {
        role: "judge",
        name: "القاضي الموضوعي",
        perspective: "التوصل لحكم متوازن وشامل",
      },
    ];

    const rounds: DebateRound[] = [];

    // Conduct debate rounds
    for (let i = 0; i < maxRounds; i++) {
      console.log(`[Multi-Agent Debate] Round ${i + 1}/${maxRounds}`);

      const round = await this.conductDebateRound(
        i + 1,
        text,
        analysis,
        context,
        rounds // Previous rounds for context
      );

      rounds.push(round);

      // Check for convergence
      const convergence = await this.checkConvergence(rounds);
      if (convergence > 0.8 && i >= 1) {
        console.log(`[Multi-Agent Debate] Converged after ${i + 1} rounds`);
        break;
      }
    }

    // Generate final verdict
    const verdict = await this.generateVerdict(text, analysis, rounds);

    // Calculate debate dynamics
    const debateDynamics = {
      rounds: rounds.length,
      convergenceScore: await this.checkConvergence(rounds),
      controversialTopics: await this.identifyControversialTopics(rounds),
    };

    console.log(`[Multi-Agent Debate] Complete after ${rounds.length} rounds`);

    return {
      participants,
      rounds,
      verdict,
      debateDynamics,
    };
  }

  /**
   * إجراء جولة نقاش واحدة
   */
  private async conductDebateRound(
    roundNumber: number,
    text: string,
    analysis: string,
    _context: any,
    previousRounds: DebateRound[]
  ): Promise<DebateRound> {
    // Build context from previous rounds
    let debateContext = "";
    if (previousRounds.length > 0) {
      debateContext = "\n\nالجولات السابقة:\n";
      previousRounds.forEach((round, index) => {
        debateContext += `\nجولة ${index + 1}:\n`;
        debateContext += `المدعي: ${round.prosecutorArgument.argument.substring(0, 200)}...\n`;
        debateContext += `المدافع: ${round.defenderArgument.argument.substring(0, 200)}...\n`;
      });
    }

    // Prosecutor's argument
    const prosecutorArg = await this.generateProsecutorArgument(
      text,
      analysis,
      debateContext
    );

    // Defender's response
    const defenderArg = await this.generateDefenderArgument(
      text,
      analysis,
      prosecutorArg.argument,
      debateContext
    );

    // Judge's comments
    const judgeComments = await this.generateJudgeComments(
      prosecutorArg,
      defenderArg
    );

    return {
      round: roundNumber,
      prosecutorArgument: prosecutorArg,
      defenderArgument: defenderArg,
      judgeComments,
    };
  }

  /**
   * توليد حجة المدعي
   */
  private async generateProsecutorArgument(
    text: string,
    analysis: string,
    debateContext: string
  ): Promise<DebateArgument> {
    const prompt = `
أنت المدعي الناقد في نقاش علمي حول جودة التحليل.
مهمتك: تحديد نقاط الضعف والأخطاء والتحيزات في التحليل المقدم.

النص الأصلي:
"""
 ${text.substring(0, 2000)}
"""

التحليل المقدم:
"""
 ${analysis.substring(0, 2000)}
"""

 ${debateContext}

قدم حجتك النقدية مع التركيز على:
1. **الأخطاء المنطقية**: هل هناك تناقضات أو قفزات منطقية؟
2. **التحيزات**: هل يظهر التحليل تحيزاً معيناً؟
3. **النقاط غير المدعومة**: ادعاءات بدون دليل كافٍ
4. **الإغفالات**: جوانب مهمة لم يتطرق لها التحليل

قدم إجابتك بالصيغة التالية:
الحجة: [حجتك النقدية الرئيسية]
الأدلة: 
- [دليل 1]
- [دليل 2]
- [دليل 3]
قوة الحجة: [رقم من 0 إلى 10]
`;

    try {
      const result = await this.geminiService.generate<string>({
        prompt,
        temperature: 0.6,
        maxTokens: 2048,
        validator: (value): value is string => typeof value === "string",
      });

      return this.parseDebateArgument(result.content, "المدعي الناقد");
    } catch (error) {
      console.error("Failed to generate prosecutor argument:", error);
      // Return a default argument in case of failure
      return {
        participant: "المدعي الناقد",
        argument: "تعذر إنشاء حجة بسبب خطأ في الخدمة.",
        evidence: [],
        strength: 0,
      };
    }
  }

  /**
   * توليد حجة المدافع
   */
  private async generateDefenderArgument(
    text: string,
    analysis: string,
    prosecutorArgument: string,
    debateContext: string
  ): Promise<DebateArgument> {
    const prompt = `
أنت المدافع البناء في نقاش علمي حول جودة التحليل.
مهمتك: إبراز نقاط القوة والرد على اتهامات المدعي بشكل موضوعي.

النص الأصلي:
"""
 ${text.substring(0, 2000)}
"""

التحليل المقدم:
"""
 ${analysis.substring(0, 2000)}
"""

حجة المدعي:
"""
 ${prosecutorArgument}
"""

 ${debateContext}

قدم دفاعك مع التركيز على:
1. **نقاط القوة**: ما الجيد في هذا التحليل؟
2. **الرد على الاتهامات**: رد موضوعي على نقاط المدعي
3. **السياق المفقود**: جوانب لم يأخذها المدعي بعين الاعتبار
4. **القيمة الإجمالية**: ما القيمة التي يضيفها هذا التحليل؟

قدم إجابتك بالصيغة التالية:
الحجة: [حجتك الدفاعية الرئيسية]
الأدلة:
- [دليل 1]
- [دليل 2]
- [دليل 3]
قوة الحجة: [رقم من 0 إلى 10]
`;

    try {
      const result = await this.geminiService.generate<string>({
        prompt,
        temperature: 0.6,
        maxTokens: 2048,
        validator: (value): value is string => typeof value === "string",
      });

      return this.parseDebateArgument(result.content, "المدافع البناء");
    } catch (error) {
      console.error("Failed to generate defender argument:", error);
      // Return a default argument in case of failure
      return {
        participant: "المدافع البناء",
        argument: "تعذر إنشاء حجة بسبب خطأ في الخدمة.",
        evidence: [],
        strength: 0,
      };
    }
  }

  /**
   * توليد تعليقات القاضي
   */
  private async generateJudgeComments(
    prosecutorArg: DebateArgument,
    defenderArg: DebateArgument
  ): Promise<string> {
    const prompt = `
أنت القاضي الموضوعي في نقاش علمي.
مهمتك: تقييم حجج الطرفين بموضوعية والتعليق على الجولة.

حجة المدعي:
 ${prosecutorArg.argument}

حجة المدافع:
 ${defenderArg.argument}

قدم تعليقاً موجزاً (3-4 جمل) يتضمن:
1. تقييم قوة كل حجة
2. النقاط الصحيحة من كل طرف
3. ما الذي نتفق عليه حتى الآن؟
`;

    try {
      const result = await this.geminiService.generate<string>({
        prompt,
        temperature: 0.3,
        maxTokens: 512,
        validator: (value): value is string => typeof value === "string",
      });
      return result.content;
    } catch (error) {
      console.error("Failed to generate judge comments:", error);
      return "تعذر إنشاء تعليقات القاضي بسبب خطأ في الخدمة.";
    }
  }

  /**
   * توليد الحكم النهائي
   */
  private async generateVerdict(
    _text: string,
    _analysis: string,
    rounds: DebateRound[]
  ): Promise<DebateVerdict> {
    // Build summary of debate
    let debateSummary = "ملخص النقاش:\n\n";
    rounds.forEach((round, index) => {
      debateSummary += `جولة ${index + 1}:\n`;
      debateSummary += `- المدعي: ${round.prosecutorArgument.argument.substring(0, 150)}...\n`;
      debateSummary += `- المدافع: ${round.defenderArgument.argument.substring(0, 150)}...\n`;
      debateSummary += `- تعليق القاضي: ${round.judgeComments.substring(0, 100)}...\n\n`;
    });

    const prompt = `
بصفتك القاضي الموضوعي، قدم حكمك النهائي على التحليل بناءً على النقاش الكامل.

 ${debateSummary}

قدم حكمك بالصيغة التالية (JSON):
{
  "consensusAreas": [
    {
      "aspect": "الجانب المتفق عليه",
      "agreement": "وصف الاتفاق",
      "confidence": 0.9
    }
  ],
  "disputedAreas": [
    {
      "aspect": "الجانب الخلافي",
      "prosecutorView": "رأي المدعي",
      "defenderView": "رأي المدافع",
      "judgeOpinion": "رأيك كقاضي",
      "resolution": "الحل المقترح"
    }
  ],
  "finalVerdict": {
    "overallAssessment": "تقييم شامل للتحليل",
    "strengths": ["نقطة قوة 1", "نقطة قوة 2"],
    "weaknesses": ["نقطة ضعف 1", "نقطة ضعف 2"],
    "recommendations": ["توصية 1", "توصية 2"],
    "confidence": 0.85
  }
}
`;

    try {
      const result = await this.geminiService.generate<string>({
        prompt,
        temperature: 0.2,
        maxTokens: 3072,
        validator: (value): value is string => typeof value === "string",
      });

      // Try to parse the JSON result
      return JSON.parse(result.content);
    } catch (error) {
      console.error("Failed to generate verdict:", error);
      // Return a default verdict in case of failure
      return {
        consensusAreas: [],
        disputedAreas: [],
        finalVerdict: {
          overallAssessment: "تعذر إصدار حكم نهائي بسبب خطأ في الخدمة.",
          strengths: [],
          weaknesses: [],
          recommendations: [],
          confidence: 0,
        },
      };
    }
  }

  /**
   * فحص التقارب بين الآراء
   */
  private async checkConvergence(rounds: DebateRound[]): Promise<number> {
    if (rounds.length < 2) return 0;

    // Simple heuristic: compare strength scores
    const lastRound = rounds[rounds.length - 1];
    const prevRound = rounds[rounds.length - 2];

    if (!lastRound || !prevRound) {
      return 0.5; // Return default convergence if rounds are missing
    }

    const lastDiff = Math.abs(
      lastRound.prosecutorArgument.strength -
        lastRound.defenderArgument.strength
    );
    const prevDiff = Math.abs(
      prevRound.prosecutorArgument.strength -
        prevRound.defenderArgument.strength
    );

    // If difference is decreasing, we're converging
    if (lastDiff < prevDiff) {
      return 0.7 + (prevDiff - lastDiff) / 10;
    }

    return 0.3;
  }

  /**
   * تحديد المواضيع الخلافية
   */
  private async identifyControversialTopics(
    rounds: DebateRound[]
  ): Promise<string[]> {
    const topics: string[] = [];

    for (const round of rounds) {
      // Find topics where prosecutor and defender strongly disagree
      const strengthDiff = Math.abs(
        round.prosecutorArgument.strength - round.defenderArgument.strength
      );

      if (strengthDiff > 5) {
        // Extract topic from arguments
        const prosecutorTopics = this.extractTopics(
          round.prosecutorArgument.argument
        );
        const defenderTopics = this.extractTopics(
          round.defenderArgument.argument
        );

        // Find common topics (they're arguing about the same thing)
        const commonTopics = prosecutorTopics.filter((t) =>
          defenderTopics.some((dt) => dt.includes(t) || t.includes(dt))
        );

        topics.push(...commonTopics);
      }
    }

    // Return unique topics
    return [...new Set(topics)].slice(0, 5);
  }

  /**
   * استخراج المواضيع من نص
   */
  private extractTopics(text: string): string[] {
    // Simple keyword extraction
    const keywords = [
      "شخصية",
      "حبكة",
      "حوار",
      "موضوع",
      "بنية",
      "أسلوب",
      "رسالة",
    ];
    return keywords.filter((keyword) => text.includes(keyword));
  }

  /**
   * تحليل حجة من نص
   */
  private parseDebateArgument(
    text: string,
    participant: string
  ): DebateArgument {
    const argumentMatch = text.match(
      /الحجة:\s*([^\n]+(?:\n(?!الأدلة|قوة)[^\n]+)*)/
    );
    const evidenceMatch = text.match(/الأدلة:\s*((?:\n\s*-[^\n]+)+)/);
    const strengthMatch = text.match(/قوة الحجة:\s*(\d+(?:\.\d+)?)/);

    const argument = argumentMatch?.[1]?.trim() ?? text;
    const evidenceText = evidenceMatch?.[1] ?? "";
    const strength = strengthMatch?.[1] ? parseFloat(strengthMatch[1]) : 5;

    // Parse evidence list
    const evidence = evidenceText
      .split("\n")
      .map((line) => line.replace(/^\s*-\s*/, "").trim())
      .filter((line) => line.length > 0);

    return {
      participant,
      // Sanitize AI content to prevent XSS
      argument: stripHtmlTags(argument),
      evidence: evidence.map((e) => stripHtmlTags(e)),
      strength,
    };
  }
}

// Export singleton instance
let debateSystemInstance: MultiAgentDebateSystem | null = null;

export function getMultiAgentDebateSystem(
  geminiService: GeminiService
): MultiAgentDebateSystem {
  if (!debateSystemInstance) {
    debateSystemInstance = new MultiAgentDebateSystem(geminiService);
  }
  return debateSystemInstance;
}

