import { BaseStation, StationInput, StationOptions } from "./base-station";
import { GeminiService, GeminiModel } from "./gemini-service";

export interface Station1Input extends StationInput {
  proseFilePath?: string;
  station1Options?: {
    enableDialogueAnalysis?: boolean;
    enableVoiceDistinction?: boolean;
    minCharacters?: number;
    maxCharacters?: number;
  };
}

export interface CharacterProfile {
  name: string;
  role: "protagonist" | "antagonist" | "supporting" | "minor";
  personalityTraits: string[];
  motivations: string[];
  goals: string[];
  obstacles: string[];
  arc: {
    type: "positive" | "negative" | "flat" | "complex";
    description: string;
    keyMoments: string[];
  };
  confidence: number;
}

export interface DialogueMetrics {
  efficiency: number;
  distinctiveness: number;
  naturalness: number;
  subtext: number;
  issues: Array<{
    type:
      | "redundancy"
      | "inconsistency"
      | "exposition_dump"
      | "on_the_nose"
      | "pacing";
    location: string;
    severity: "low" | "medium" | "high";
    suggestion: string;
  }>;
}

export interface VoiceProfile {
  character: string;
  distinctiveness: number;
  characteristics: string[];
  sampleLines: string[];
}

