        throw new Error("Invalid narrative style response");
      }

      return {
        overallTone: parsed.overall_tone,
        toneElements: parsed.tone_elements || [],
        pacingAnalysis: {
          overall: this.normalizePacingSpeed(parsed.pacing?.overall),
