        opportunitiesForImprovement: [],
        threatsToCoherence: [],
        finalRecommendations: {
          mustDo: [],
          shouldDo: [],
          couldDo: [],
        },
        audienceResonance: {
          emotionalImpact: 0,
          intellectualEngagement: 0,
          relatability: 0,
          memorability: 0,
          viralPotential: 0,
          primaryResponse: "",
          secondaryResponses: [],
          controversialElements: [],
        },
        rewritingSuggestions: [],
      },
      scoreMatrix: {
        foundation: 0,
        conceptual: 0,
        conflictNetwork: 0,
        efficiency: 0,
        dynamicSymbolic: 0,
        diagnostics: 0,
        overall: 0,
      },
      finalConfidence: {
        overallConfidence: 0,
        stationConfidences: new Map(),
        uncertaintyAggregation: {
          epistemicUncertainties: [],
          aleatoricUncertainties: [],
          resolvableIssues: [],
        },
      },
      metadata: {
        analysisTimestamp: new Date(),
        totalExecutionTime: 0,
        stationsCompleted: 0,
        agentsUsed: [],
        tokensUsed: 0,
        modelUsed: "gemini-2.5-pro",
        status: "Failed",
      },
    };
  }
}

