// أنواع البيانات المشتركة لنظام المحطات السبع
export type StationInput = {
  text: string;
  prev?: unknown;
};

export type StationOutput = {
  summary: string;
  confidence: number;
  uncertainties?: {
    type: "epistemic" | "aleatoric";
    note: string;
  }[];
  alternates?: {
    hypothesis: string;
    confidence: number;
  }[];
  meta?: Record<string, unknown>;
};

export interface Station {
  id: `S${1 | 2 | 3 | 4 | 5 | 6 | 7}`;
  run(input: StationInput): Promise<StationOutput>;
}

export type OrchestrationResult = {
  stations: Record<string, StationOutput>;
  finalReport: string;
  totalConfidence: number;
  executionTime: number;
};

// Pipeline types
export interface PipelineInputSchema {
  text: string;
  options?: Record<string, unknown>;
}

export interface PipelineInput {
  text: string;
  options?: Record<string, unknown>;
}

export interface PipelineRunResult {
  success: boolean;
  data?: OrchestrationResult;
  error?: string;
}

export interface EnhancedPipelineRunResult extends PipelineRunResult {
  stationOutputs?: Record<string, StationOutput>;
  metadata?: Record<string, unknown>;
}

export enum StationStatus {
  PENDING = "pending",
  RUNNING = "running",
  COMPLETED = "completed",
  FAILED = "failed",
}

// Validation function
export function validateAndNormalizePipelineInput(
  input: unknown
): PipelineInput {
  if (typeof input === "string") {
    return { text: input };
  }

  if (typeof input === "object" && input !== null && "text" in input) {
    return input as PipelineInput;
  }

  throw new Error("Invalid pipeline input");
}

// Stub file created by Worktree-5 to resolve type errors
// This module was referenced but missing from the codebase

export interface ChunkOptions {
  maxChunkSize?: number;
  overlap?: number;
}

export interface TextChunk {
  text: string;
  index: number;
  start: number;
  end: number;
}

export function chunkText(text: string, options?: ChunkOptions): TextChunk[] {
  const maxSize = options?.maxChunkSize || 1000;
  const overlap = options?.overlap || 100;
  const chunks: TextChunk[] = [];

  let start = 0;
  let index = 0;

  while (start < text.length) {
    const end = Math.min(start + maxSize, text.length);
    chunks.push({
      text: text.substring(start, end),
      index: index++,
      start,
      end,
    });
    start += maxSize - overlap;
  }

  return chunks;
}

export default {
  chunkText,
};

export interface LogLevel {
  ERROR: "error";
  WARN: "warn";
  INFO: "info";
  DEBUG: "debug";
}

export class Logger {
  private logLevel: keyof LogLevel = "INFO";

  setLevel(level: keyof LogLevel) {
    this.logLevel = level;
  }

  private shouldLog(level: keyof LogLevel): boolean {
    const levels = ["DEBUG", "INFO", "WARN", "ERROR"];
    return levels.indexOf(level) >= levels.indexOf(this.logLevel);
  }

  private formatMessage(level: string, message: string, meta?: any): string {
    const timestamp = new Date().toISOString();
    const metaStr = meta ? ` ${JSON.stringify(meta)}` : "";
    return `[${timestamp}] ${level.toUpperCase()}: ${message}${metaStr}`;
  }

  error(message: string, meta?: any) {
    if (this.shouldLog("ERROR")) {
      console.error(this.formatMessage("error", message, meta));
    }
  }

  warn(message: string, meta?: any) {
    if (this.shouldLog("WARN")) {
      console.warn(this.formatMessage("warn", message, meta));
    }
  }

  info(message: string, meta?: any) {
    if (this.shouldLog("INFO")) {
      console.info(this.formatMessage("info", message, meta));
    }
  }

  debug(message: string, meta?: any) {
    if (this.shouldLog("DEBUG")) {
      console.debug(this.formatMessage("debug", message, meta));
    }
  }
}

export const logger = new Logger();
export default logger;

export function toText(content: { raw?: unknown } | string): string {
  if (typeof content === "string") {
    return content.trim();
  }
  if (content && typeof content === "object" && "raw" in content) {
    return String(content.raw || "").trim();
  }
  return "";
}

export function safeSub(text: string, start: number, end: number): string {
  if (!text || typeof text !== "string") {
    return "";
  }
  return text.substring(start, Math.min(end, text.length));
}

