import type { AppStateId } from "@/lib/app-state-contract";

interface AppStateApiResponse<T extends object> {
  success: boolean;
  data: T;
  updatedAt: string;
}

function resolveServerBaseUrl(): string {
  const baseUrl =
    process.env["NEXT_PUBLIC_APP_STATE_BASE_URL"] ||
    process.env["BACKEND_URL"] ||
    process.env["NEXT_PUBLIC_BACKEND_URL"] ||
    process.env["NEXT_PUBLIC_API_URL"];

  if (!baseUrl) {
    throw new Error(
      "App state backend URL is not configured. Set BACKEND_URL or NEXT_PUBLIC_BACKEND_URL."
    );
  }

  return baseUrl.replace(/\/$/, "");
}

function buildAppStateUrl(appId: AppStateId): string {
  const path = `/api/app-state/${appId}`;

  if (typeof window !== "undefined" && window.location?.origin) {
    return new URL(path, window.location.origin).toString();
  }

  return new URL(path, resolveServerBaseUrl()).toString();
}

function getCsrfToken(): string | null {
  if (typeof document === "undefined") return null;

  const cookieMatch = document.cookie
    .split("; ")
    .find((entry) => entry.startsWith("XSRF-TOKEN="));

  if (!cookieMatch) return null;

  const [, value] = cookieMatch.split("=");
  return value ? decodeURIComponent(value) : null;
}

async function ensureCsrfToken(): Promise<string | null> {
  const existingToken = getCsrfToken();
  if (existingToken) {
    return existingToken;
  }

  await fetch("/api/health", {
    method: "GET",
    credentials: "same-origin",
    cache: "no-store",
  });

  return getCsrfToken();
}

async function parseJson<T>(response: Response): Promise<T> {
  const json = (await response.json()) as T;
  return json;
}

export async function loadRemoteAppState<T extends object>(
  appId: AppStateId
): Promise<T | null> {
  const response = await fetch(buildAppStateUrl(appId), {
    method: "GET",
    cache: "no-store",
    credentials: "same-origin",
  });

  if (!response.ok) {
    throw new Error(`Failed to load app state for ${appId}`);
  }

  const payload = await parseJson<AppStateApiResponse<T>>(response);
  return payload.data ?? null;
}

export async function persistRemoteAppState<T extends object>(
  appId: AppStateId,
  data: T
): Promise<T> {
  const csrfToken = await ensureCsrfToken();
  const headers = new Headers({
    "Content-Type": "application/json",
  });

  if (csrfToken) {
    headers.set("X-XSRF-TOKEN", csrfToken);
    headers.set("x-xsrf-token", csrfToken);
  }

  const response = await fetch(buildAppStateUrl(appId), {
    method: "PUT",
    headers,
    credentials: "same-origin",
    body: JSON.stringify({ data }),
  });

  if (!response.ok) {
    throw new Error(`Failed to persist app state for ${appId}`);
  }

  const payload = await parseJson<AppStateApiResponse<T>>(response);
  return payload.data;
}

export async function clearRemoteAppState(appId: AppStateId): Promise<void> {
  const csrfToken = await ensureCsrfToken();
  const headers = new Headers();

  if (csrfToken) {
    headers.set("X-XSRF-TOKEN", csrfToken);
    headers.set("x-xsrf-token", csrfToken);
  }

  const response = await fetch(buildAppStateUrl(appId), {
    method: "DELETE",
    headers,
    credentials: "same-origin",
  });

  if (!response.ok) {
    throw new Error(`Failed to clear app state for ${appId}`);
  }
}

function normalizeBaseUrl(url?: string | null): string | null {
  if (!url) return null;
  return url.replace(/\/$/, "");
}

export function getBackendBaseUrl(): string | null {
  return normalizeBaseUrl(
    process.env["NEXT_PUBLIC_BACKEND_URL"] ||
      process.env["NEXT_PUBLIC_API_URL"] ||
      null
  );
}

function getCsrfToken(): string | null {
  if (typeof document === "undefined") return null;

  const cookieMatch = document.cookie
    .split("; ")
    .find((entry) => entry.startsWith("XSRF-TOKEN="));

  if (!cookieMatch) return null;

  const [, value] = cookieMatch.split("=");
  return value ? decodeURIComponent(value) : null;
}

async function ensureCsrfToken(baseUrl: string): Promise<string | null> {
  const existingToken = getCsrfToken();
  if (existingToken) {
    return existingToken;
  }

  await fetch(`${baseUrl}/api/health`, {
    method: "GET",
    credentials: "include",
    cache: "no-store",
  });

  return getCsrfToken();
}

export async function postToBackend<TResponse = unknown>(
  path: string,
  body: unknown,
  options?: { bestEffort?: boolean }
): Promise<TResponse | null> {
  const baseUrl = getBackendBaseUrl();
  if (!baseUrl) {
    if (options?.bestEffort) return null;
    throw new Error("NEXT_PUBLIC_BACKEND_URL is not configured");
  }

  const csrfToken = await ensureCsrfToken(baseUrl);
  const response = await fetch(`${baseUrl}${path}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(csrfToken ? { "X-XSRF-TOKEN": csrfToken } : {}),
    },
    credentials: "include",
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    if (options?.bestEffort) return null;

    let message = `Backend request failed with status ${response.status}`;
    try {
      const payload = (await response.json()) as {
        error?: string;
        message?: string;
      };
      message = payload.message || payload.error || message;
    } catch {
      // ignore JSON parse failure and keep generic message
    }
    throw new Error(message);
  }

  if (response.status === 204) return null;
  return (await response.json()) as TResponse;
}

/**
 * Cache Middleware for Next.js API Routes
 *
 * Provides caching layer for API responses with Redis
 */

import { NextRequest, NextResponse } from "next/server";
import { getCached, setCached, invalidateCache } from "@/lib/redis";

export interface CacheOptions {
  /** Cache key prefix */
  keyPrefix?: string;
  /** Time to live in seconds */
  ttl?: number;
  /** Skip cache for certain conditions */
  shouldCache?: (request: NextRequest) => boolean;
  /** Generate custom cache key */
  keyGenerator?: (request: NextRequest) => string;
}

/**
 * Generates a cache key from request
 */
function generateCacheKey(
  request: NextRequest,
  prefix: string = "api"
): string {
  const url = new URL(request.url);
  const pathname = url.pathname;
  const search = url.search;
  const method = request.method;

  // Include request method and query params in cache key
  return `${prefix}:${method}:${pathname}${search}`;
}

/**
 * Cache wrapper for API route handlers
 */
export function withCache<T = any>(
  handler: (request: NextRequest) => Promise<NextResponse<T>>,
  options: CacheOptions = {}
) {
  return async (request: NextRequest): Promise<NextResponse<T>> => {
    const {
      keyPrefix = "api",
      ttl = 3600, // 1 hour default
      shouldCache = () => request.method === "GET",
      keyGenerator = (req) => generateCacheKey(req, keyPrefix),
    } = options;

    // Only cache GET requests by default
    if (!shouldCache(request)) {
      return handler(request);
    }

    const cacheKey = keyGenerator(request);

    try {
      // Try to get from cache
      const cached = await getCached<T>(cacheKey);

      if (cached) {
        return NextResponse.json(cached, {
          headers: {
            "X-Cache": "HIT",
            "Cache-Control": `public, s-maxage=${ttl}, stale-while-revalidate=${ttl * 2}`,
          },
        }) as NextResponse<T>;
      }

      // If not in cache, execute handler
      const response = await handler(request);

      // Only cache successful responses
      if (response.status >= 200 && response.status < 300) {
        const data = await response.json();
        await setCached(cacheKey, data, { ttl });
        return NextResponse.json(data, {
          headers: {
            "X-Cache": "MISS",
            "Cache-Control": `public, s-maxage=${ttl}, stale-while-revalidate=${ttl * 2}`,
          },
        }) as NextResponse<T>;
      }

      return response as NextResponse<T>;
    } catch {
      // If caching fails, execute handler normally
      const response = await handler(request);

      // Add cache miss header
      const headers = new Headers(response.headers);
      headers.set("X-Cache", "MISS");

      return new NextResponse(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers,
      });
    }
  };
}

/**
 * Invalidate cache for a specific pattern
 */
export async function invalidateCachePattern(pattern: string): Promise<void> {
  await invalidateCache(pattern);
}

/**
 * Common cache TTL values (in seconds)
 */
export const CACHE_TTL = {
  MINUTE: 60,
  FIVE_MINUTES: 300,
  FIFTEEN_MINUTES: 900,
  HOUR: 3600,
  DAY: 86400,
  WEEK: 604800,
} as const;

export default withCache;

/**
 * CDN Asset Helper Utilities
 * ===========================
 * Utilities for managing static assets with CDN support.
 *
 * أدوات مساعدة لإدارة الأصول الثابتة مع دعم CDN
 */

/**
 * Get the CDN URL from environment variables
 * الحصول على رابط CDN من متغيرات البيئة
 */
const CDN_URL = process.env["NEXT_PUBLIC_CDN_URL"] || "";
const ENABLE_CDN = process.env["NEXT_PUBLIC_ENABLE_CDN"] === "true";

/**
 * Get the full URL for a static asset
 * الحصول على الرابط الكامل لأصل ثابت
 *
 * @param path - The path to the asset (e.g., '/images/logo.png')
 * @returns The full URL with CDN prefix if enabled, or the original path
 *
 * @example
 * ```tsx
 * import { getAssetUrl } from '@/lib/cdn';
 *
 * // In a component
 * <img src={getAssetUrl('/images/logo.png')} alt="Logo" />
 * ```
 */
export function getAssetUrl(path: string): string {
  // Ensure path starts with /
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;

  // If CDN is enabled and URL is configured, use CDN
  if (ENABLE_CDN && CDN_URL) {
    // Remove trailing slash from CDN URL if present
    const cdnBase = CDN_URL.endsWith("/") ? CDN_URL.slice(0, -1) : CDN_URL;
    return `${cdnBase}${normalizedPath}`;
  }

  // Otherwise, use local path
  return normalizedPath;
}

/**
 * Get the full URL for a font file
 * الحصول على الرابط الكامل لملف خط
 *
 * @param fontName - The font filename (e.g., 'amiri-400.woff2')
 * @returns The full URL to the font file
 *
 * @example
 * ```tsx
 * import { getFontUrl } from '@/lib/cdn';
 *
 * const fontUrl = getFontUrl('amiri-400.woff2');
 * ```
 */
export function getFontUrl(fontName: string): string {
  return getAssetUrl(`/fonts/${fontName}`);
}

/**
 * Get the full URL for an image file
 * الحصول على الرابط الكامل لملف صورة
 *
 * @param imagePath - The image path relative to /images (e.g., 'fallback.jpg')
 * @returns The full URL to the image file
 *
 * @example
 * ```tsx
 * import { getImageUrl } from '@/lib/cdn';
 *
 * <img src={getImageUrl('fallback.jpg')} alt="Fallback" />
 * ```
 */
export function getImageUrl(imagePath: string): string {
  // If path already starts with /images, use it as is
  if (imagePath.startsWith("/images/")) {
    return getAssetUrl(imagePath);
  }

  // Otherwise, prepend /images/
  return getAssetUrl(`/images/${imagePath}`);
}

/**
 * Get the full URL for a Directors Studio asset
 * الحصول على الرابط الكامل لأصل استوديو المخرجين
 *
 * @param fileName - The filename in /directors-studio directory
 * @returns The full URL to the asset
 *
 * @example
 * ```tsx
 * import { getDirectorsStudioUrl } from '@/lib/cdn';
 *
 * const heroImage = getDirectorsStudioUrl('Film_production_hero_image_6b2179d4.png');
 * ```
 */
export function getDirectorsStudioUrl(fileName: string): string {
  return getAssetUrl(`/directors-studio/${fileName}`);
}

/**
 * Check if CDN is currently enabled
 * التحقق من تفعيل CDN
 *
 * @returns true if CDN is enabled, false otherwise
 */
export function isCdnEnabled(): boolean {
  return ENABLE_CDN && !!CDN_URL;
}

/**
 * Get the current CDN base URL
 * الحصول على رابط CDN الأساسي
 *
 * @returns The CDN base URL or empty string if not configured
 */
export function getCdnBaseUrl(): string {
  return ENABLE_CDN ? CDN_URL : "";
}

/**
 * Preload a static asset (useful for critical resources)
 * تحميل أصل ثابت مسبقاً (مفيد للموارد الحرجة)
 *
 * @param path - The path to the asset
 * @param type - The resource type (image, font, style, script)
 *
 * @example
 * ```tsx
 * import { preloadAsset } from '@/lib/cdn';
 *
 * // In a component or page
 * useEffect(() => {
 *   preloadAsset('/fonts/amiri-400.woff2', 'font');
 * }, []);
 * ```
 */
export function preloadAsset(
  path: string,
  type: "image" | "font" | "style" | "script" = "image"
): void {
  if (typeof document === "undefined") return;

  const url = getAssetUrl(path);
  const link = document.createElement("link");
  link.rel = "preload";
  link.href = url;
  link.as = type;

  // Add crossorigin for fonts
  if (type === "font") {
    link.crossOrigin = "anonymous";
  }

  document.head.appendChild(link);
}

/**
 * Export configuration for debugging
 * تصدير الإعدادات للتشخيص
 */
export const cdnConfig = {
  url: CDN_URL,
  enabled: ENABLE_CDN,
  isActive: isCdnEnabled(),
} as const;

