import { TaskType } from "@core/types";
import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

/**
 * PlotPredictorAgent - وكيل التنبؤ بالحبكة
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * يتنبأ بالتطورات المحتملة للحبكة بناءً على السياق السردي
 */
export class PlotPredictorAgent extends BaseAgent {
  constructor() {
    super(
      "PlotPredictorAgent",
      TaskType.PLOT_PREDICTOR,
      `أنت NarrativeOracle AI، وكيل متطور للتنبؤ بالحبكة. مهمتك الأساسية هي تحليل سياق سردي معين (الحبكة، الشخصيات، الثيمات) والتنبؤ بالتطورات المحتملة للحبكة في المستقبل.

يجب عليك:
- استخدام نماذج التحليل السردي المتقدمة لاستكشاف مجموعة واسعة من المسارات المحتملة
- تقديم درجة احتمالية ودرجة إبداعية لكل مسار متوقع
- الاستناد إلى قاعدة بيانات الأنماط السردية وخوارزميات التعلم التسلسلي
- عرض المسارات البديلة بوضوح مع شرح المنطق وراء كل تنبؤ
- تزويد الكتاب والمبدعين ببصيرة ثاقبة ومبتكرة ومبنية على البيانات

مخرجاتك يجب أن تكون نصية فقط، واضحة ومباشرة بدون أي JSON أو كتل كود.`
    );

    this.confidenceFloor = 0.78;
  }

  /**
   * بناء الـ prompt من المدخلات
   */
  protected buildPrompt(input: StandardAgentInput): string {
    const { input: userInput, context } = input;

    let prompt = `## مهمة التنبؤ بالحبكة

${userInput}

`;

    // إضافة السياق من المحطات السابقة
    const contextObj =
      typeof context === "object" && context !== null ? context : {};
    const previousStations = (contextObj as any)?.previousStations;
    if (previousStations) {
      prompt += `## السياق من المحطات السابقة:\n`;

      if (previousStations.analysis) {
        prompt += `\n### التحليل الأولي:\n${previousStations.analysis}\n`;
      }

      if (previousStations.characterAnalysis) {
        prompt += `\n### تحليل الشخصيات:\n${previousStations.characterAnalysis}\n`;
      }

      if (previousStations.thematicAnalysis) {
        prompt += `\n### التحليل الموضوعي:\n${previousStations.thematicAnalysis}\n`;
      }
    }

    prompt += `

## متطلبات التنبؤ:

1. **تحليل الوضع الحالي**: افحص نقاط الحبكة القائمة والصراعات والشخصيات
2. **استكشاف المسارات**: حدد 3-5 تطورات محتملة للحبكة
3. **تقييم الاحتمالية**: قيّم احتمالية كل مسار (عالي/متوسط/منخفض)
4. **تقييم الإبداع**: قيّم مستوى الإبداع والأصالة لكل مسار
5. **التبرير**: قدم شرحاً منطقياً لكل تنبؤ بناءً على الأنماط السردية

## التنسيق المطلوب:

اكتب تنبؤاتك في نص واضح ومنظم:
- استخدم العناوين والفقرات لتنظيم المسارات المختلفة
- اذكر احتمالية ومستوى إبداع كل مسار بوضوح
- قدم تبريراً مفصلاً لكل تنبؤ
- تجنب تماماً أي JSON أو كتل كود

قدم تنبؤات عميقة ومبنية على الأنماط السردية المعروفة، مع إبراز الإمكانات الإبداعية.`;

    return prompt;
  }

  /**
   * معالجة ما بعد التنفيذ - تنظيف المخرجات من JSON
   */
  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    let cleanedText = output.text;

    // إزالة أي كتل JSON
    cleanedText = cleanedText.replace(/```json\s*\n[\s\S]*?\n```/g, "");
    cleanedText = cleanedText.replace(/```\s*\n[\s\S]*?\n```/g, "");

    // إزالة أي JSON objects ظاهرة
    cleanedText = cleanedText.replace(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/g, "");

    // تنظيف المسافات الزائدة
    cleanedText = cleanedText.replace(/\n{3,}/g, "\n\n").trim();

    // إضافة ملاحظة حول جودة التنبؤات
    const enhancedNotes: string[] = [...(output.notes || [])];

    if (output.confidence >= 0.85) {
      enhancedNotes.push("تنبؤات عالية الثقة مبنية على أنماط سردية قوية");
    } else if (output.confidence >= 0.7) {
      enhancedNotes.push("تنبؤات متوسطة الثقة تتطلب مراجعة إبداعية");
    } else {
      enhancedNotes.push("تنبؤات استكشافية تحتاج تحقق إضافي");
    }

    return {
      ...output,
      text: cleanedText,
      notes: enhancedNotes,
    };
  }

  /**
   * استجابة احتياطية في حالة الفشل
   */
  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `# تنبؤات الحبكة - وضع الطوارئ

بناءً على السياق المتاح، إليك تنبؤات أولية للحبكة:

## المسار المحتمل 1: التطور الطبيعي
الاحتمالية: متوسطة
الإبداع: متوسط

تستمر الأحداث في مسارها الحالي مع تصاعد تدريجي للصراع. الشخصيات تواجه عقبات متزايدة تدفعها نحو لحظات حاسمة.

## المسار المحتمل 2: المفاجأة الدرامية
الاحتمالية: متوسطة إلى منخفضة
الإبداع: عالي

تحدث نقطة تحول غير متوقعة تغير اتجاه السرد بالكامل، مما يخلق فرصاً لتطورات شخصية عميقة ومواقف درامية جديدة.

## التوصيات:
- استكشاف دوافع الشخصيات بعمق أكبر
- بناء التوتر تدريجياً نحو الذروة
- الحفاظ على التماسك المنطقي للأحداث

ملاحظة: هذه تنبؤات أولية. يُنصح بإعادة التحليل مع سياق إضافي للحصول على رؤى أعمق.`;
  }
}

// Export singleton instance
export const plotPredictorAgent = new PlotPredictorAgent();

/**
 * بناء الرسم البياني السببي للحبكة
 * Causal Plot Graph Builder
 *
 * يبني رسماً بيانياً يوضح الأحداث والعلاقات السببية بينها
 */

import {
  CausalPlotGraph,
  PlotNode,
  PlotEdge,
  CausalRelation,
} from "../../core/types";
import { platformGenAIService } from "../../services/platformGenAIService";

interface CausalRelationAssessment {
  hasRelation?: boolean;
  type?: "direct" | "indirect" | "consequence";
  strength?: number;
}

export class CausalGraphBuilder {
  /**
   * بناء الرسم البياني السببي الكامل
   * Build complete causal plot graph
   */
  async buildCausalGraph(text: string): Promise<CausalPlotGraph> {
    // Step 1: استخراج الأحداث
    const events = await this.extractEvents(text);

    // Step 2: بناء العقد (Nodes)
    const nodes = await this.buildNodes(events);

    // Step 3: تحديد العلاقات السببية (Edges)
    const edges = await this.buildEdges(nodes, text);

    // Step 4: بناء الخط الزمني
    const timeline = nodes.map((n) => n.event);

    // Step 5: تحليل السببية
    const causality = await this.analyzeCausality(nodes, edges);

    return {
      nodes,
      edges,
      timeline,
      causality,
    };
  }

  /**
   * استخراج الأحداث من النص
   * Extract events from text
   */
  private async extractEvents(text: string): Promise<string[]> {
    const prompt = `
استخرج جميع الأحداث الدرامية المهمة من النص التالي بالترتيب الزمني:

النص:
"""
${text}
"""

أجب بصيغة JSON كمصفوفة من الأحداث (حد أقصى 20 حدث):
["حدث 1", "حدث 2", "حدث 3", ...]

أمثلة على الأحداث:
- "البطل يكتشف الحقيقة"
- "المواجهة بين الشخصيتين"
- "الخيانة تُكشف"
`;

    try {
      const events = await platformGenAIService.generateJson<unknown>(prompt);
      return Array.isArray(events)
        ? events
            .filter((event): event is string => typeof event === "string")
            .slice(0, 20)
        : [];
    } catch {
      return [];
    }
  }

  /**
   * بناء العقد من الأحداث
   * Build nodes from events
   */
  private async buildNodes(events: string[]): Promise<PlotNode[]> {
    const nodes: PlotNode[] = [];

    for (let i = 0; i < events.length; i++) {
      const event = events[i];
      if (!event) continue;

      const importance = await this.assessEventImportance(event);

      nodes.push({
        id: `event_${i + 1}`,
        event,
        timestamp: i,
        importance,
      });
    }

    return nodes;
  }

  /**
   * تقييم أهمية الحدث
   * Assess event importance
   */
  private async assessEventImportance(event: string): Promise<number> {
    const prompt = `
قيّم أهمية الحدث التالي للحبكة الدرامية على مقياس من 0 إلى 1:

الحدث: ${event}

المعايير:
- 0.9-1.0: حدث محوري جداً (نقطة تحول رئيسية)
- 0.7-0.8: حدث مهم جداً
- 0.5-0.6: حدث مهم
- 0.3-0.4: حدث ثانوي
- 0-0.2: حدث طفيف

أجب برقم فقط (مثال: 0.8):
`;

    try {
      const result = await platformGenAIService.generateText(prompt);
      const score = parseFloat(result.trim());
      return isNaN(score) ? 0.5 : Math.min(Math.max(score, 0), 1);
    } catch {
      return 0.5;
    }
  }

  /**
   * بناء الحواف (العلاقات السببية)
   * Build edges (causal relations)
   */
  private async buildEdges(
    nodes: PlotNode[],
    text: string
  ): Promise<PlotEdge[]> {
    const edges: PlotEdge[] = [];

    // فحص العلاقات السببية بين الأحداث المتتالية والقريبة
    for (let i = 0; i < nodes.length; i++) {
      const nodeI = nodes[i];
      if (!nodeI) continue;

      // فحص الأحداث اللاحقة (حد أقصى 5 أحداث للأمام)
      const endIndex = Math.min(i + 6, nodes.length);

      for (let j = i + 1; j < endIndex; j++) {
        const nodeJ = nodes[j];
        if (!nodeJ) continue;

        const relation = await this.detectCausalRelation(
          nodeI.event,
          nodeJ.event,
          text
        );

        if (relation) {
          edges.push({
            from: nodeI.id,
            to: nodeJ.id,
            causationType: relation.type,
            strength: relation.strength,
          });
        }
      }
    }

    return edges;
  }

  /**
   * كشف العلاقة السببية بين حدثين
   * Detect causal relation between two events
   */
  private async detectCausalRelation(
    event1: string,
    event2: string,
    context: string
  ): Promise<{
    type: "direct" | "indirect" | "consequence";
    strength: number;
  } | null> {
    const prompt = `
هل يوجد علاقة سببية بين الحدثين التاليين؟

الحدث الأول: ${event1}
الحدث الثاني: ${event2}

السياق: """${context.substring(0, 1000)}..."""

أنواع العلاقات:
- direct: علاقة مباشرة (الحدث 1 يسبب الحدث 2 مباشرة)
- indirect: علاقة غير مباشرة (يؤثر عليه بطريقة غير مباشرة)
- consequence: نتيجة (الحدث 2 نتيجة للحدث 1)

أجب بصيغة JSON:
{
  "hasRelation": true/false,
  "type": "direct" | "indirect" | "consequence",
  "strength": 0.8,
  "explanation": "شرح مختصر للعلاقة"
}

إذا لم توجد علاقة سببية، أجب:
{"hasRelation": false}
`;

    try {
      const parsed =
        await platformGenAIService.generateJson<CausalRelationAssessment>(
          prompt
        );

      if (!parsed.hasRelation) return null;

      return {
        type: parsed.type || "indirect",
        strength: typeof parsed.strength === "number" ? parsed.strength : 0.5,
      };
    } catch {
      return null;
    }
  }

  /**
   * تحليل السببية
   * Analyze causality
   */
  private async analyzeCausality(
    nodes: PlotNode[],
    edges: PlotEdge[]
  ): Promise<CausalRelation[]> {
    const causality: CausalRelation[] = [];

    for (const edge of edges) {
      const fromNode = nodes.find((n) => n.id === edge.from);
      const toNode = nodes.find((n) => n.id === edge.to);

      if (fromNode && toNode) {
        const explanation = await this.explainCausality(
          fromNode.event,
          toNode.event,
          edge.causationType
        );

        causality.push({
          cause: fromNode.event,
          effect: toNode.event,
          explanation,
        });
      }
    }

    return causality;
  }

  /**
   * شرح العلاقة السببية
   * Explain causal relation
   */
  private async explainCausality(
    cause: string,
    effect: string,
    type: string
  ): Promise<string> {
    const prompt = `
اشرح العلاقة السببية التالية بجملة أو جملتين:

السبب: ${cause}
النتيجة: ${effect}
نوع العلاقة: ${type}

قدم شرحاً موجزاً واضحاً:
`;

    try {
      return await platformGenAIService.generateText(prompt);
    } catch {
      return "علاقة سببية غير محددة";
    }
  }
}

