      dependsOn: [TaskType.ANALYSIS, TaskType.CREATIVE],
      enhances: [],
      systemPrompt: "تحليل وإبداع متكامل",
      cacheStrategy: "aggressive",
      parallelizable: true,
      confidenceThreshold: 0.9,
    },
  ],
}));

describe("AgentFactory", () => {
  let getAgentConfig: any;
  let listAgentConfigs: any;

  beforeEach(async () => {
    vi.resetModules();
    const agentFactoryModule = await import("./agentFactory");
    getAgentConfig = agentFactoryModule.getAgentConfig;
    listAgentConfigs = agentFactoryModule.listAgentConfigs;
  });

  describe("getAgentConfig", () => {
    it("should return agent config for valid task type", () => {
      const config = getAgentConfig(TaskType.ANALYSIS);

      expect(config).toBeDefined();
      expect(config?.id).toBe(TaskType.ANALYSIS);
      expect(config?.name).toBe("تحليل");
      expect(config?.description).toContain("تحليل");
    });

    it("should return config for CREATIVE task", () => {
      const config = getAgentConfig(TaskType.CREATIVE);

      expect(config).toBeDefined();
      expect(config?.id).toBe(TaskType.CREATIVE);
      expect(config?.name).toBe("إبداع");
    });

    it("should return config for INTEGRATED task", () => {
      const config = getAgentConfig(TaskType.INTEGRATED);

      expect(config).toBeDefined();
      expect(config?.id).toBe(TaskType.INTEGRATED);
      expect(config?.capabilities.multiModal).toBe(true);
    });

    it("should return undefined for unknown task type", () => {
      const config = getAgentConfig("UNKNOWN_TASK" as TaskType);

      expect(config).toBeUndefined();
    });

    it("should return config with all required properties", () => {
      const config = getAgentConfig(TaskType.ANALYSIS);

      expect(config).toBeDefined();
      expect(config?.id).toBeDefined();
      expect(config?.name).toBeDefined();
      expect(config?.description).toBeDefined();
      expect(config?.category).toBeDefined();
      expect(config?.capabilities).toBeDefined();
      expect(config?.systemPrompt).toBeDefined();
      expect(config?.cacheStrategy).toBeDefined();
    });

    it("should return config with correct capabilities", () => {
      const config = getAgentConfig(TaskType.ANALYSIS);

      expect(config?.capabilities).toBeDefined();
      expect(config?.capabilities.multiModal).toBe(true);
      expect(config?.capabilities.reasoningChains).toBe(true);
      expect(config?.capabilities.accuracyLevel).toBe(0.9);
    });

    it("should return config with collaboration info", () => {
      const config = getAgentConfig(TaskType.CREATIVE);

      expect(config?.collaboratesWith).toBeDefined();
      expect(Array.isArray(config?.collaboratesWith)).toBe(true);
      expect(config?.collaboratesWith).toContain(TaskType.ANALYSIS);
    });

    it("should return config with dependency info", () => {
      const config = getAgentConfig(TaskType.INTEGRATED);

      expect(config?.dependsOn).toBeDefined();
      expect(Array.isArray(config?.dependsOn)).toBe(true);
      expect(config?.dependsOn).toContain(TaskType.ANALYSIS);
      expect(config?.dependsOn).toContain(TaskType.CREATIVE);
    });

    it("should return config with cache strategy", () => {
      const analysisConfig = getAgentConfig(TaskType.ANALYSIS);
      const creativeConfig = getAgentConfig(TaskType.CREATIVE);
      const integratedConfig = getAgentConfig(TaskType.INTEGRATED);

      expect(analysisConfig?.cacheStrategy).toBe("adaptive");
      expect(creativeConfig?.cacheStrategy).toBe("none");
      expect(integratedConfig?.cacheStrategy).toBe("aggressive");
    });

    it("should return config with parallelizable flag", () => {
      const analysisConfig = getAgentConfig(TaskType.ANALYSIS);
      const creativeConfig = getAgentConfig(TaskType.CREATIVE);

      expect(analysisConfig?.parallelizable).toBe(true);
      expect(creativeConfig?.parallelizable).toBe(false);
    });

    it("should return config with confidence threshold", () => {
      const config = getAgentConfig(TaskType.ANALYSIS);

      expect(config?.confidenceThreshold).toBeDefined();
      expect(config?.confidenceThreshold).toBe(0.8);
    });
  });

  describe("listAgentConfigs", () => {
    it("should return all agent configurations", () => {
      const configs = listAgentConfigs();

      expect(configs).toBeDefined();
      expect(Array.isArray(configs)).toBe(true);
      expect(configs.length).toBe(3);
    });

    it("should return readonly array", () => {
      const configs = listAgentConfigs();

      expect(configs).toBeDefined();
      // TypeScript ينفذ readonly في وقت التجميع
      expect(Array.isArray(configs)).toBe(true);
    });

    it("should include all task types", () => {
      const configs = listAgentConfigs();

      const ids = configs.map((c) => c.id);

      expect(ids).toContain(TaskType.ANALYSIS);
      expect(ids).toContain(TaskType.CREATIVE);
      expect(ids).toContain(TaskType.INTEGRATED);
    });

    it("should return configs with valid structure", () => {
      const configs = listAgentConfigs();

      configs.forEach((config) => {
        expect(config.id).toBeDefined();
        expect(config.name).toBeDefined();
        expect(config.description).toBeDefined();
        expect(config.capabilities).toBeDefined();
        expect(config.systemPrompt).toBeDefined();
      });
    });

    it("should not return empty array", () => {
      const configs = listAgentConfigs();

      expect(configs.length).toBeGreaterThan(0);
    });

    it("should return configs with unique IDs", () => {
      const configs = listAgentConfigs();
      const ids = configs.map((c) => c.id);
      const uniqueIds = new Set(ids);

      expect(uniqueIds.size).toBe(configs.length);
    });

    it("should return configs with different categories", () => {
      const configs = listAgentConfigs();
      const categories = configs.map((c) => c.category);

      expect(categories).toContain("core");
      expect(categories).toContain("creative");
    });
  });

  describe("Integration", () => {
    it("should allow getting config and listing all configs", () => {
      const allConfigs = listAgentConfigs();
      const firstConfig = getAgentConfig(allConfigs[0].id);

      expect(firstConfig).toBeDefined();
      expect(firstConfig?.id).toBe(allConfigs[0].id);
    });

    it("should maintain consistency between get and list", () => {
      const allConfigs = listAgentConfigs();

      allConfigs.forEach((config) => {
        const retrieved = getAgentConfig(config.id);
        expect(retrieved).toEqual(config);
      });
    });
  });

  describe("Edge Cases", () => {
    it("should handle null task type gracefully", () => {
      const config = getAgentConfig(null as any);

      expect(config).toBeUndefined();
    });

    it("should handle empty string task type", () => {
      const config = getAgentConfig("" as TaskType);

      expect(config).toBeUndefined();
    });

    it("should not mutate returned configs", () => {
      const config1 = getAgentConfig(TaskType.ANALYSIS);
      const config2 = getAgentConfig(TaskType.ANALYSIS);

      expect(config1).toEqual(config2);
    });
  });
});

import { AGENT_CONFIGS } from "@agents/index";
import { TaskType } from "@core/enums";
import { AIAgentConfig } from "@core/types";

const agentRegistry = new Map<TaskType, AIAgentConfig>(
  AGENT_CONFIGS.map(
    (config: AIAgentConfig): readonly [string, AIAgentConfig] => [
      config.id as any,
      config,
    ]
  ) as any
);

export const getAgentConfig = (task: TaskType): AIAgentConfig | undefined =>
  agentRegistry.get(task);

export const listAgentConfigs = (): readonly AIAgentConfig[] => AGENT_CONFIGS;

/**
 * نظام الذكاء الدستوري
 * Constitutional AI System
 *
 * يضمن التزام جميع الوكلاء بمجموعة من القواعد والمبادئ المحددة مسبقاً
 * Based on Anthropic's Constitutional AI research
 */

import { ConstitutionalRule } from "../core/types";
import { log } from "../services/loggerService";
import { platformGenAIService } from "../services/platformGenAIService";

interface RuleCritiqueResponse {
  hasViolation?: boolean;
  violationDescription?: string;
}

export class ConstitutionalAISystem {
  private rules: ConstitutionalRule[];

  constructor() {
    this.rules = this.initializeRules();
  }

  /**
   * تهيئة القواعد الدستورية الخمس
   * Initialize the five constitutional rules
   */
  private initializeRules(): ConstitutionalRule[] {
    return [
      {
        id: "fidelity_001",
        name: "Original Text Fidelity",
        nameAr: "الأمانة للنص الأصلي",
        description:
          "All developments must respect and build upon the original text",
        critiquePrompt: `
هل هذا التطوير يحترم النص الأصلي ولا يتناقض معه؟
قم بتحديد أي انحرافات عن النص الأصلي أو تناقضات معه.
`,
        revisionPrompt: `
قم بتعديل المخرج ليتوافق مع النص الأصلي مع الحفاظ على التطوير المقترح.
`,
        priority: 1,
      },
      {
        id: "no_positive_bias_002",
        name: "No Positive Bias",
        nameAr: "عدم الانحياز الإيجابي الزائف",
        description: "Avoid unrealistic positive feedback",
        critiquePrompt: `
هل هذا المخرج يحتوي على مديح مبالغ فيه أو انحياز إيجابي غير واقعي؟
حدد أي عبارات مبالغ فيها أو إطراء مفرط.
`,
        revisionPrompt: `
أعد صياغة المخرج ليكون موضوعياً ومتوازناً بدون مبالغة أو انحياز إيجابي.
`,
        priority: 2,
      },
      {
        id: "analysis_based_003",
        name: "Analysis-Report Based",
        nameAr: "الاعتماد على تقرير التحليل",
        description:
          "Development must be informed by the Seven Stations analysis",
        critiquePrompt: `
هل هذا التطوير مبني على نتائج تقرير التحليل (السبع محطات)؟
حدد أي جوانب لم تأخذ التحليل بعين الاعتبار.
`,
        revisionPrompt: `
أعد المخرج مع الأخذ بعين الاعتبار نتائج تقرير التحليل المرفق.
`,
        priority: 1,
      },
      {
        id: "coherence_004",
        name: "Narrative Coherence",
        nameAr: "التماسك السردي",
        description: "Ensure logical coherence in narrative development",
        critiquePrompt: `
هل المخرج متماسك منطقياً ومتسق داخلياً؟
حدد أي تناقضات أو ثغرات منطقية أو قفزات غير مبررة في السرد.
`,
        revisionPrompt: `
صحح أي تناقضات وثغرات منطقية في المخرج.
`,
        priority: 2,
      },
      {
        id: "character_consistency_005",
        name: "Character Consistency",
        nameAr: "اتساق الشخصيات",
        description: "Maintain character consistency throughout",
        critiquePrompt: `
هل الشخصيات متسقة مع تطورها وخصائصها المعرّفة؟
حدد أي سلوكيات أو حوارات غير متسقة مع طبيعة الشخصية.
`,
        revisionPrompt: `
اضبط المخرج ليحافظ على اتساق الشخصيات مع طبيعتها وتطورها.
`,
        priority: 2,
      },
    ];
  }

  /**
   * تطبيق القواعد الدستورية على مخرج
   * Apply constitutional rules to output
   */
  async applyConstitutionalRules(
    output: string,
    context: {
      originalText: string;
      analysisReport: any;
    }
  ): Promise<{
    isValid: boolean;
    violations: RuleViolation[];
    revisedOutput: string;
  }> {
    log.info("Starting constitutional validation", null, "ConstitutionalAI");

    const violations: RuleViolation[] = [];
    let currentOutput = output;

    // فرز القواعد حسب الأولوية (Priority 1 أولاً)
    const sortedRules = this.rules.sort((a, b) => a.priority - b.priority);

    for (const rule of sortedRules) {
      log.debug(
        "Checking constitutional rule",
        { ruleId: rule.id, ruleName: rule.nameAr },
        "ConstitutionalAI"
      );

      // Critique phase
      const critiqueResult = await this.critiqueWithRule(
        currentOutput,
        rule,
        context
      );

      if (critiqueResult.hasViolation) {
        log.warn(
          "Constitutional violation found",
          { ruleId: rule.id, ruleName: rule.nameAr },
          "ConstitutionalAI"
        );
        violations.push({
          ruleId: rule.id,
          ruleName: rule.name,
          description: critiqueResult.violationDescription,
        });

        // Revision phase
        currentOutput = await this.reviseWithRule(
          currentOutput,
          rule,
          context,
          critiqueResult.violationDescription
        );
      }
    }

    const isValid = violations.length === 0;
    log.info(
      "Constitutional validation complete",
      { isValid, violations: violations.length },
      "ConstitutionalAI"
    );

    return {
      isValid,
      violations,
      revisedOutput: currentOutput,
    };
  }

  /**
   * نقد المخرج بناءً على قاعدة واحدة
   * Critique output based on a single rule
   */
  private async critiqueWithRule(
    output: string,
    rule: ConstitutionalRule,
    context: any
  ): Promise<{
    hasViolation: boolean;
    violationDescription: string;
  }> {
    const critiquePrompt = `
${rule.critiquePrompt}

المخرج المراد نقده:
"""
${output}
"""

النص الأصلي (للمرجعية):
"""
${context.originalText.substring(0, 2000)}...
"""

تقرير التحليل (للمرجعية):
"""
${JSON.stringify(context.analysisReport, null, 2).substring(0, 1000)}
"""

أجب بصيغة JSON:
{
  "hasViolation": true/false,
  "violationDescription": "وصف دقيق للمخالفة إن وجدت، أو سلسلة فارغة إذا لم توجد مخالفة"
}
`;

    try {
      const parsed =
        await platformGenAIService.generateJson<RuleCritiqueResponse>(
          critiquePrompt
        );
      return {
        hasViolation: parsed.hasViolation || false,
        violationDescription: parsed.violationDescription || "",
      };
    } catch (error) {
      log.error("Error in constitutional critique", error, "ConstitutionalAI");
      return {
        hasViolation: false,
        violationDescription: "",
      };
    }
  }

  /**
   * مراجعة المخرج بناءً على قاعدة
   * Revise output based on a rule violation
   */
  private async reviseWithRule(
    output: string,
    rule: ConstitutionalRule,
    context: any,
    violationDescription: string
  ): Promise<string> {
    const revisionPrompt = `
${rule.revisionPrompt}

المخرج الحالي:
"""
${output}
"""

المخالفة المكتشفة:
${violationDescription}

النص الأصلي للمرجعية:
"""
${context.originalText.substring(0, 2000)}...
"""

تقرير التحليل للمرجعية:
"""
${JSON.stringify(context.analysisReport, null, 2).substring(0, 1000)}
"""

قم بتعديل المخرج ليتوافق مع القاعدة: ${rule.nameAr}
أعد المخرج المعدل فقط بدون شروحات أو تعليقات:
`;

    try {
      return await platformGenAIService.generateText(revisionPrompt);
    } catch (error) {
      log.error("Error in constitutional revision", error, "ConstitutionalAI");
      return output; // Return original on error
    }
  }

  /**
   * الحصول على قائمة القواعد
   * Get list of rules
   */
  getRules(): ConstitutionalRule[] {
    return this.rules;
  }

  /**
   * إضافة قاعدة مخصصة
   * Add custom rule
   */
  addCustomRule(rule: ConstitutionalRule): void {
    this.rules.push(rule);
  }
}

interface RuleViolation {
  ruleId: string;
  ruleName: string;
  description: string;
}

// Export singleton instance
export const constitutionalAI = new ConstitutionalAISystem();

