      "AnalyticsService"
    );
    return analyticsService;
  }

  analyticsService = new AnalyticsService(config);
  return analyticsService;
};

export const getAnalyticsService = () => analyticsService;

export const destroyAnalytics = () => {
  if (analyticsService) {
    analyticsService.destroy();
    analyticsService = null;
  }
};

