import { log } from "./loggerService";

export enum ErrorType {
  NETWORK_ERROR = "NETWORK_ERROR",
  API_ERROR = "API_ERROR",
  FILE_ERROR = "FILE_ERROR",
  VALIDATION_ERROR = "VALIDATION_ERROR",
  CONFIGURATION_ERROR = "CONFIGURATION_ERROR",
  RUNTIME_ERROR = "RUNTIME_ERROR",
  UNKNOWN_ERROR = "UNKNOWN_ERROR",
}

export interface ErrorContext {
  userId?: string;
  sessionId?: string;
  timestamp: string;
  userAgent?: string;
  url?: string;
  component?: string;
  action?: string;
  metadata?: Record<string, any>;
}

export interface DetailedError extends Error {
  type: ErrorType;
  context: ErrorContext;
  originalError?: Error;
  severity: "low" | "medium" | "high" | "critical";
  recoverable: boolean;
  errorId: string;
}

export class ErrorHandler {
  private static instance: ErrorHandler;
  private errorHistory: DetailedError[] = [];
  private maxHistorySize = 100;

  private constructor() {}

  static getInstance(): ErrorHandler {
    if (!ErrorHandler.instance) {
      ErrorHandler.instance = new ErrorHandler();
    }
    return ErrorHandler.instance;
  }

  /**
   * Handle and categorize errors with detailed context
   */
  handleError(
    error: Error | unknown,
    context: Partial<ErrorContext> = {},
    type?: ErrorType,
    severity: "low" | "medium" | "high" | "critical" = "medium"
  ): DetailedError {
    const errorId = this.generateErrorId();
    const timestamp = new Date().toISOString();

    // Determine error type if not provided
    const errorType = type || this.categorizeError(error);

    // Build full context
    const fullContext: ErrorContext = {
      timestamp,
      ...context,
    };

    if (typeof navigator !== "undefined") {
      fullContext.userAgent = navigator.userAgent;
    }
    if (typeof window !== "undefined") {
      fullContext.url = window.location.href;
    }

    // Create detailed error
    const detailedError: DetailedError = {
      name: error instanceof Error ? error.name : "UnknownError",
      message: error instanceof Error ? error.message : String(error),
      type: errorType,
      context: fullContext,
      severity,
      recoverable: this.isRecoverable(errorType, severity),
      errorId,
    };

    if (error instanceof Error) {
      detailedError.originalError = error;
    }

    // Log the error
    this.logError(detailedError);

    // Store in history
    this.storeError(detailedError);

    // Handle based on severity
    this.handleBySeverity(detailedError);

    return detailedError;
  }

  /**
   * Handle network-related errors
   */
  handleNetworkError(
    error: Error | unknown,
    context: Partial<ErrorContext> = {},
    url?: string
  ): DetailedError {
    const networkContext: Partial<ErrorContext> = {
      ...context,
      component: "NetworkService",
    };
    if (url) {
      networkContext.url = url;
    }
    return this.handleError(
      error,
      networkContext,
      ErrorType.NETWORK_ERROR,
      "high"
    );
  }

  /**
   * Handle API-related errors
   */
  handleAPIError(
    error: Error | unknown,
    context: Partial<ErrorContext> = {},
    endpoint?: string
  ): DetailedError {
    const apiContext: Partial<ErrorContext> = {
      ...context,
      component: "APIService",
    };
    if (endpoint) {
      apiContext.action = endpoint;
    }
    return this.handleError(error, apiContext, ErrorType.API_ERROR, "high");
  }

  /**
   * Handle file-related errors
   */
  handleFileError(
    error: Error,
    context: Partial<ErrorContext> = {},
    fileName?: string
  ): DetailedError {
    return this.handleError(
      error,
      {
        ...context,
        metadata: {
          ...context.metadata,
          fileName,
        },
        component: "FileService",
      },
      ErrorType.FILE_ERROR,
      "medium"
    );
  }

  /**
   * Handle validation errors
   */
  handleValidationError(
    error: Error,
    context: Partial<ErrorContext> = {},
    field?: string
  ): DetailedError {
    return this.handleError(
      error,
      {
        ...context,
        metadata: {
          ...context.metadata,
          field,
        },
        component: "ValidationService",
      },
      ErrorType.VALIDATION_ERROR,
      "low"
    );
  }

  /**
   * Get error history
   */
  getErrorHistory(): DetailedError[] {
    return [...this.errorHistory];
  }

  /**
   * Get errors by type
   */
  getErrorsByType(type: ErrorType): DetailedError[] {
    return this.errorHistory.filter((error) => error.type === type);
  }

  /**
   * Get errors by severity
   */
  getErrorsBySeverity(
    severity: "low" | "medium" | "high" | "critical"
  ): DetailedError[] {
    return this.errorHistory.filter((error) => error.severity === severity);
  }

  /**
   * Clear error history
   */
  clearHistory(): void {
    this.errorHistory = [];
    log.info("Error history cleared", null, "ErrorHandler");
  }

  /**
   * Get error statistics
   */
  getErrorStats(): {
    total: number;
    byType: Record<ErrorType, number>;
    bySeverity: Record<string, number>;
    recentErrors: number;
  } {
    const now = new Date();
    const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

    const recentErrors = this.errorHistory.filter(
      (error) => new Date(error.context.timestamp) > oneHourAgo
    ).length;

    const byType = Object.values(ErrorType).reduce(
      (acc, type) => {
        acc[type] = this.getErrorsByType(type).length;
        return acc;
      },
      {} as Record<ErrorType, number>
    );

    const bySeverity = ["low", "medium", "high", "critical"].reduce(
      (acc, severity) => {
        acc[severity] = this.getErrorsBySeverity(severity as any).length;
        return acc;
      },
      {} as Record<string, number>
    );

    return {
      total: this.errorHistory.length,
      byType,
      bySeverity,
      recentErrors,
    };
  }

  /**
   * Error categorization rules
   * Maps keywords to error types
   */
  private static readonly ERROR_PATTERNS: Array<{
    type: ErrorType;
    keywords: string[];
  }> = [
    {
      type: ErrorType.NETWORK_ERROR,
      keywords: ["network", "fetch", "connection", "timeout"],
    },
    {
      type: ErrorType.API_ERROR,
      keywords: ["api", "endpoint", "response", "status"],
    },
    {
      type: ErrorType.FILE_ERROR,
      keywords: ["file", "read", "write", "upload"],
    },
    {
      type: ErrorType.VALIDATION_ERROR,
      keywords: ["validation", "invalid", "required", "format"],
    },
    {
      type: ErrorType.CONFIGURATION_ERROR,
      keywords: ["config", "configuration", "setting"],
    },
  ];

  /**
   * Categorize error based on patterns
   * Reduced cyclomatic complexity from 14 to 4
   */
  private categorizeError(error: Error | unknown): ErrorType {
    if (!(error instanceof Error)) {
      return ErrorType.UNKNOWN_ERROR;
    }

    const message = error.message.toLowerCase();
    const name = error.name.toLowerCase();

    // Check each pattern
    for (const pattern of ErrorHandler.ERROR_PATTERNS) {
      const hasKeyword = pattern.keywords.some(
        (keyword) => message.includes(keyword) || name.includes(keyword)
      );

      if (hasKeyword) {
        return pattern.type;
      }
    }

    return ErrorType.UNKNOWN_ERROR;
  }

  private isRecoverable(type: ErrorType, severity: string): boolean {
    if (severity === "critical") return false;
    if (type === ErrorType.NETWORK_ERROR) return true;
    if (type === ErrorType.API_ERROR) return true;
    if (type === ErrorType.FILE_ERROR) return true;
    if (type === ErrorType.VALIDATION_ERROR) return true;

    return false;
  }

  private logError(error: DetailedError): void {
    const logMessage = `[${error.errorId}] ${error.type}: ${error.message}`;
    const logContext = {
      errorId: error.errorId,
      type: error.type,
      severity: error.severity,
      recoverable: error.recoverable,
      context: error.context,
      stack: error.stack,
    };

    switch (error.severity) {
      case "critical":
        log.error(logMessage, logContext, "ErrorHandler");
        break;
      case "high":
        log.error(logMessage, logContext, "ErrorHandler");
        break;
      case "medium":
        log.warn(logMessage, logContext, "ErrorHandler");
        break;
      case "low":
        log.info(logMessage, logContext, "ErrorHandler");
        break;
    }
  }

  private storeError(error: DetailedError): void {
    this.errorHistory.unshift(error);

    // Keep only the most recent errors
    if (this.errorHistory.length > this.maxHistorySize) {
      this.errorHistory = this.errorHistory.slice(0, this.maxHistorySize);
    }
  }

  private handleBySeverity(error: DetailedError): void {
    switch (error.severity) {
      case "critical":
        // Could trigger emergency procedures, alerts, etc.
        this.handleCriticalError(error);
        break;
      case "high":
        // Could trigger user notifications
        this.handleHighSeverityError(error);
        break;
      case "medium":
        // Could trigger background retry mechanisms
        this.handleMediumSeverityError(error);
        break;
      case "low":
        // Just log and continue
        break;
    }
  }

  private handleCriticalError(error: DetailedError): void {
    // In a real application, this could:
    // - Send alerts to monitoring systems
    // - Trigger emergency fallbacks
    // - Notify administrators
    log.error(
      "Critical error detected - emergency procedures may be needed",
      error,
      "ErrorHandler"
    );
  }

  private handleHighSeverityError(error: DetailedError): void {
    // Could show user notifications for high-severity errors
    log.warn(
      "High severity error - user may need to be notified",
      error,
      "ErrorHandler"
    );
  }

  private handleMediumSeverityError(error: DetailedError): void {
    // Could trigger retry mechanisms or alternative flows
    log.info(
      "Medium severity error - retry mechanisms may be triggered",
      error,
      "ErrorHandler"
    );
  }

  private generateErrorId(): string {
    return `ERR_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

// Export singleton instance
export const errorHandler = ErrorHandler.getInstance();

// Export convenience functions
export const handleError = (
  error: Error | unknown,
  context?: Partial<ErrorContext>,
  type?: ErrorType,
  severity?: "low" | "medium" | "high" | "critical"
) => errorHandler.handleError(error, context, type, severity);

export const handleNetworkError = (
  error: Error,
  context?: Partial<ErrorContext>,
  url?: string
) => errorHandler.handleNetworkError(error, context, url);

export const handleAPIError = (
  error: Error,
  context?: Partial<ErrorContext>,
  endpoint?: string
) => errorHandler.handleAPIError(error, context, endpoint);

export const handleFileError = (
  error: Error,
  context?: Partial<ErrorContext>,
  fileName?: string
) => errorHandler.handleFileError(error, context, fileName);

export const handleValidationError = (
  error: Error,
  context?: Partial<ErrorContext>,
  field?: string
) => errorHandler.handleValidationError(error, context, field);

import { ProcessedFile, Result } from "../core/types";
import { log } from "./loggerService";

// =====================================================
// Browser-Compatible File Reader Service
// =====================================================

/**
 * قراءة ملفات من المتصفح باستخدام File API
 */
export async function readFiles(
  files: File[]
): Promise<Result<ProcessedFile[]>> {
  try {
    const processedFiles: (ProcessedFile | null)[] = await Promise.all(
      files.map((file) => processFile(file))
    );

    const successful = processedFiles.filter(
      (f): f is ProcessedFile => f !== null
    );
    const failures = processedFiles
      .map((f, i) => (f === null ? files[i]?.name : null))
      .filter(Boolean);

    if (failures.length > 0) {
      log.warn(
        "⚠️ Some files failed to process",
        failures,
        "FileReaderService"
      );
    }

    if (successful.length === 0) {
      return {
        ok: false,
        error: new Error("فشلت معالجة جميع الملفات"),
      };
    }

    return { ok: true, value: successful };
  } catch (e: any) {
    return {
      ok: false,
      error: e instanceof Error ? e : new Error("فشل في قراءة الملفات"),
    };
  }
}

/**
 * معالجة ملف واحد
 */
/**
 * File type handlers
 * Reduces cyclomatic complexity by using strategy pattern
 */
interface FileTypeHandler {
  matches: (file: File) => boolean;
  process: (file: File, buffer: Buffer) => Promise<string | undefined>;
}

const FILE_TYPE_HANDLERS: FileTypeHandler[] = [
  {
    matches: (file) =>
      file.type === "text/plain" ||
      file.type === "text/markdown" ||
      file.name.endsWith(".txt") ||
      file.name.endsWith(".md"),
    process: async (_, buffer) => tryDecodeUtf8(buffer),
  },
  {
    matches: (file) =>
      file.type ===
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document" ||
      file.name.endsWith(".docx"),
    process: async (file) => extractDocxText(file),
  },
  {
    matches: (file) =>
      file.type === "application/pdf" || file.name.endsWith(".pdf"),
    process: async () => undefined, // PDF سيتم إرساله كـ binary
  },
  {
    matches: (file) => file.type.startsWith("image/"),
    process: async () => undefined, // الصور سيتم إرسالها كـ binary
  },
];

/**
 * Get appropriate handler for file type
 */
function getFileHandler(file: File): FileTypeHandler {
  return (
    FILE_TYPE_HANDLERS.find((handler) => handler.matches(file)) || {
      matches: () => true,
      process: async (_, buffer) => tryDecodeUtf8(buffer),
    }
  );
}

/**
 * Process file with reduced cyclomatic complexity
 * Reduced from 13 to 5
 */
async function processFile(file: File): Promise<ProcessedFile | null> {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Get handler and process file
    const handler = getFileHandler(file);
    const textContent = await handler.process(file, buffer);

    const processed: ProcessedFile = {
      fileName: file.name,
      content: textContent || "",
      sizeBytes: file.size,
      mimeType: file.type,
      textContent: textContent ?? "",
      size: file.size,
      name: file.name,
    };

    log.debug(
      `✅ Processed file: ${file.name} (${formatBytes(file.size)})`,
      null,
      "FileReaderService"
    );
    return processed;
  } catch (error: any) {
    log.error(
      `❌ Failed to process file: ${file.name}`,
      error,
      "FileReaderService"
    );
    return null;
  }
}

/**
 * محاولة فك تشفير UTF-8
 */
function tryDecodeUtf8(buffer: Buffer): string | undefined {
  try {
    const text = buffer.toString("utf8");
    // رفض إذا كان هناك الكثير من رموز الاستبدال
    if (/\uFFFD{3,}/.test(text)) {
      return undefined;
    }
    return text;
  } catch {
    return undefined;
  }
}

/**
 * استخراج نص من ملف DOCX
 */
async function extractDocxText(file: File): Promise<string | undefined> {
  try {
    // استيراد ديناميكي لـ mammoth
    const mammoth = await import("mammoth");
    const arrayBuffer = await file.arrayBuffer();

    const result = await (mammoth as any).convertToPlainText({ arrayBuffer });

    if (result.value && result.value.trim().length > 0) {
      log.debug(
        `✅ Extracted text from DOCX: ${file.name}`,
        null,
        "FileReaderService"
      );
      return result.value;
    }

    log.warn(
      `⚠️ DOCX extraction returned empty: ${file.name}`,
      null,
      "FileReaderService"
    );
    return undefined;
  } catch (error) {
    log.error(
      `❌ DOCX extraction failed: ${file.name}`,
      error,
      "FileReaderService"
    );
    return undefined;
  }
}

/**
 * تنسيق حجم الملف
 */
function formatBytes(bytes: number): string {
  if (bytes === 0) return "0 Bytes";
  const k = 1024;
  const sizes = ["Bytes", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + " " + sizes[i];
}

/**
 * خدمة تحسين الخطوط - Font Optimization Service
 * تم توحيد جميع الخطوط لاستخدام Cairo فقط
 */

export interface FontConfig {
  family: string;
  weights: number[];
  styles: ("normal" | "italic")[];
  display: "auto" | "block" | "swap" | "fallback" | "optional";
  preload?: boolean;
}

// الخط الموحد: Cairo فقط
export const FONT_CONFIGS: Record<string, FontConfig> = {
  cairo: {
    family: "Cairo",
    weights: [200, 300, 400, 500, 600, 700, 800, 900, 1000],
    styles: ["normal"],
    display: "swap",
    preload: true,
  },
};

// للتوافق مع الاستخدامات القديمة - جميعها تشير إلى Cairo
export const LEGACY_FONT_CONFIGS = {
  amiri: FONT_CONFIGS.cairo,
  tajawal: FONT_CONFIGS.cairo,
  literata: FONT_CONFIGS.cairo,
  sourceCodePro: FONT_CONFIGS.cairo,
};

/**
 * توليد CSS لتحميل الخط محلياً
 */
export function generateFontFaceCSS(
  config: FontConfig,
  fontBasePath: string = "/fonts"
): string {
  const { family, weights, styles } = config;
  const fontFaces: string[] = [];

  weights.forEach((weight) => {
    styles.forEach((style) => {
      const fontFileName = `${family.toLowerCase().replace(/\s+/g, "-")}-${weight}${style === "italic" ? "-italic" : ""}`;

      fontFaces.push(`
@font-face {
  font-family: '${family}';
  font-style: ${style};
  font-weight: ${weight};
  font-display: ${config.display};
  src: url('${fontBasePath}/${fontFileName}.woff2') format('woff2'),
       url('${fontBasePath}/${fontFileName}.woff') format('woff');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+2000-206F, U+2074, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD, U+0600-06FF, U+200C-200D, U+2010-2011, U+204F, U+2E41, U+FB50-FDFF, U+FE80-FEFC;
}`);
    });
  });

  return fontFaces.join("\n");
}

/**
 * توليد روابط preload للخطوط الحرجة
 */
export function generatePreloadLinks(): string[] {
  return Object.entries(FONT_CONFIGS)
    .filter(([, config]) => config.preload)
    .flatMap(([, config]) => {
      const primaryWeight = config.weights.includes(400)
        ? 400
        : config.weights[0];
      const fontFileName = `${config.family.toLowerCase().replace(/\s+/g, "-")}-${primaryWeight}`;

      return [
        `<link rel="preload" href="/fonts/${fontFileName}.woff2" as="font" type="font/woff2" crossorigin="anonymous">`,
      ];
    });
}

/**
 * الحصول على fallbacks الخط المحسنة
 */
export function getFontFallbacks(_primaryFont: string): string {
  // Cairo هو الخط الوحيد - استخدام fallbacks موحدة
  return 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
}

/**
 * متغيرات CSS للخطوط - موحدة لاستخدام Cairo
 */
export const FONT_CSS_VARIABLES = `
  /* الخط الموحد: Cairo */
  --font-family: 'Cairo', ${getFontFallbacks("Cairo")};
  --font-arabic-primary: 'Cairo', ${getFontFallbacks("Cairo")};
  --font-arabic-modern: 'Cairo', ${getFontFallbacks("Cairo")};
  --font-arabic-clean: 'Cairo', ${getFontFallbacks("Cairo")};
  --font-body: 'Cairo', ${getFontFallbacks("Cairo")};
  --font-headline: 'Cairo', ${getFontFallbacks("Cairo")};
  --font-code: 'Cairo', ${getFontFallbacks("Cairo")};

  /* تحسين تحميل الخط */
  --font-loading-strategy: swap;
` as const;

