import "server-only";
import { GoogleGenAI } from "@google/genai";
import { AIRequest, AIResponse } from "../core/types";
import { buildPrompt } from "../orchestration/promptBuilder";
import { config } from "../config/environment";
import { sanitization } from "./sanitizationService";
import { log } from "./loggerService";

// =====================================================
// Gemini Service Configuration
// =====================================================

interface GeminiConfig {
  apiKey: string;
  model: string;
  maxRetries: number;
  retryDelay: number;
  timeout: number;
}

interface GenerateTextOptions {
  temperature?: number;
  maxTokens?: number;
  model?: string;
}

class GeminiService {
  private config: GeminiConfig;
  private ai: GoogleGenAI | null = null;

  constructor() {
    this.config = {
      apiKey: config.api.geminiKey,
      model: config.api.geminiModel,
      maxRetries: config.api.retries,
      retryDelay: 1000,
      timeout: config.api.timeout,
    };

    if (this.config.apiKey) {
      this.initialize();
    }
  }

  private initialize(): void {
    try {
      this.ai = new GoogleGenAI({ apiKey: this.config.apiKey });
      log.info("✅ Gemini API initialized successfully", null, "GeminiService");
    } catch (error) {
      log.error("❌ Failed to initialize Gemini", error, "GeminiService");
      throw error;
    }
  }

  async generateText(
    prompt: string,
    options: GenerateTextOptions = {}
  ): Promise<string> {
    if (!this.ai) {
      throw new Error(
        "Gemini model not initialized. Please check your API key."
      );
    }

    const effectiveModel = options.model ?? this.config.model;

    log.info(
      `[Gemini Service] Generating content with model ${effectiveModel}`,
      {
        tokenLimit: options.maxTokens ?? 48192,
        temperature: options.temperature ?? 0.9,
      },
      "GeminiService"
    );

    let lastError: Error | null = null;

    for (let attempt = 1; attempt <= this.config.maxRetries; attempt++) {
      try {
        log.debug(
          `🔄 Gemini API call attempt ${attempt}/${this.config.maxRetries}`,
          null,
          "GeminiService"
        );

        const timeoutPromise = new Promise<never>((_, reject) => {
          setTimeout(
            () => reject(new Error("Request timeout")),
            this.config.timeout
          );
        });

        const generatePromise = this.ai.models.generateContent({
          model: effectiveModel,
          contents: prompt,
          config: {
            temperature: options.temperature ?? 0.9,
            maxOutputTokens: options.maxTokens ?? 48192,
          },
        });

        const result = await Promise.race([generatePromise, timeoutPromise]);
        const text = result.text;

        if (!text) {
          throw new Error("Empty response from Gemini");
        }

        log.info("✅ Gemini API call successful", null, "GeminiService");
        return text;
      } catch (error: any) {
        lastError = error;
        log.error(
          `❌ Gemini API error (attempt ${attempt})`,
          error,
          "GeminiService"
        );

        if (attempt < this.config.maxRetries) {
          const delay = this.config.retryDelay * attempt;
          log.debug(`⏳ Retrying in ${delay}ms...`, null, "GeminiService");
          await new Promise((resolve) => setTimeout(resolve, delay));
        }
      }
    }

    throw new Error(
      `Gemini API failed after ${this.config.maxRetries} attempts. Last error: ${lastError?.message}`
    );
  }

  async analyze(request: AIRequest): Promise<AIResponse> {
    try {
      log.info(
        "📝 Starting Gemini analysis",
        { agent: request.agent },
        "GeminiService"
      );

      const sanitized = sanitization.text(request.prompt);
      const sanitizedRequest = { ...request, prompt: sanitized };
      const prompt = buildPrompt(sanitizedRequest);

      const rawResponse = await this.generateText(prompt);

      log.info(
        "✅ Gemini analysis completed",
        { agent: request.agent },
        "GeminiService"
      );

      return {
        text: rawResponse,
        parsed: null,
        raw: rawResponse,
        agent: request.agent,
      };
    } catch (error) {
      log.error("❌ Gemini analysis failed", error, "GeminiService");
      throw error;
    }
  }

  isInitialized(): boolean {
    return this.ai !== null;
  }

  getModelInfo(): { model: string; maxTokens: number } {
    return {
      model: this.config.model,
      maxTokens: 48192,
    };
  }
}

// =====================================================
// Singleton Export
// =====================================================

export const geminiService = new GeminiService();

/**
 * خدمة كشف الهلوسات
 * Hallucination Detection Service
 *
 * يكتشف ويصحح المحتوى المُختَلَق غير المستند لمصادر
 */

import { HallucinationDetection, FactCheck } from "../core/types";
import { log } from "./loggerService";
import { platformGenAIService } from "./platformGenAIService";

interface FactCheckResponse {
  isSupported?: boolean;
  sources?: unknown;
  confidence?: number;
}

interface ConsistencyResponse {
  isConsistent?: boolean;
  contradictions?: unknown;
}

export class HallucinationService {
  /**
   * كشف الهلوسات في المخرج
   * Detect hallucinations in output
   */
  async detectHallucinations(
    output: string,
    sourceText: string,
    analysisReport: any
  ): Promise<HallucinationDetection> {
    log.info("Starting hallucination detection", null, "HallucinationService");

    // Extract claims from output
    const claims = await this.extractClaims(output);
    log.debug(
      "Claims extracted for verification",
      { claims: claims.length },
      "HallucinationService"
    );

    // Fact-check each claim
    const factCheckResults: FactCheck[] = [];
    const hallucinatedParts: string[] = [];

    for (const claim of claims) {
      const factCheck = await this.factCheckClaim(
        claim,
        sourceText,
        analysisReport
      );

      factCheckResults.push(factCheck);

      if (!factCheck.isSupported) {
        hallucinatedParts.push(claim);
      }
    }

    log.info(
      "Hallucination detection complete",
      { unsupportedClaims: hallucinatedParts.length },
      "HallucinationService"
    );

    // Correct hallucinations if found
    let correctedOutput = output;
    if (hallucinatedParts.length > 0) {
      correctedOutput = await this.correctHallucinations(
        output,
        hallucinatedParts,
        sourceText
      );
    }

    return {
      isHallucinated: hallucinatedParts.length > 0,
      hallucinatedParts,
      factCheckResults,
      correctedOutput,
    };
  }

  /**
   * استخراج الادعاءات من المخرج
   * Extract claims from output
   */
  private async extractClaims(output: string): Promise<string[]> {
    const extractionPrompt = `
قم باستخراج جميع الادعاءات والحقائق الرئيسية من النص التالي:

النص:
"""
${output.substring(0, 3000)}
"""

أجب بصيغة JSON كمصفوفة من السلاسل النصية (حد أقصى 10 ادعاءات):
["ادعاء 1", "ادعاء 2", ...]
`;

    try {
      const claims =
        await platformGenAIService.generateJson<unknown>(extractionPrompt);
      return Array.isArray(claims)
        ? claims
            .filter((claim): claim is string => typeof claim === "string")
            .slice(0, 10)
        : [];
    } catch (error) {
      log.error("Error extracting claims", error, "HallucinationService");
      return [];
    }
  }

  /**
   * التحقق من صحة ادعاء
   * Fact-check a claim against sources
   */
  private async factCheckClaim(
    claim: string,
    sourceText: string,
    analysisReport: any
  ): Promise<FactCheck> {
    const factCheckPrompt = `
قم بالتحقق من صحة الادعاء التالي بناءً على المصادر المتاحة:

الادعاء:
"""
${claim}
"""

النص الأصلي:
"""
${sourceText.substring(0, 2000)}...
"""

تقرير التحليل:
"""
${JSON.stringify(analysisReport, null, 2).substring(0, 1000)}
"""

هل الادعاء مدعوم بالمصادر؟ أجب بصيغة JSON:
{
  "isSupported": true/false,
  "sources": ["مصدر 1", "مصدر 2"],
  "confidence": 0.9
}
`;

    try {
      const parsed =
        await platformGenAIService.generateJson<FactCheckResponse>(
          factCheckPrompt
        );

      return {
        claim,
        isSupported: parsed.isSupported || false,
        sources: Array.isArray(parsed.sources) ? parsed.sources : [],
        confidence:
          typeof parsed.confidence === "number" ? parsed.confidence : 0.5,
      };
    } catch (error) {
      log.error("Error fact-checking claim", error, "HallucinationService");
      return {
        claim,
        isSupported: true, // Default to supported on error to avoid false positives
