// Helper function to sanitize sensitive data from logs
const sanitizeForLogging = (data: any): any => {
  if (!data || typeof data !== "object") {
    return data;
  }

  const sanitized = { ...data };
  const sensitiveKeys = [
    "dsn",
    "apiKey",
    "api_key",
    "token",
    "password",
