/**
 * Local Search Index
 * فهرس البحث المحلي في IndexedDB
 */

interface IndexedDocument {
  id: string;
  content: string;
  characters?: string[];
  scenes?: string[];
  lastIndexed: number;
}

interface SearchResult {
  docId: string;
  matches: SearchMatch[];
  score: number;
}

interface SearchMatch {
  line: number;
  text: string;
  context: string;
}

const DB_NAME = "the-copy-search-index";
const DB_VERSION = 1;
const STORE_NAME = "documents";

async function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("lastIndexed", "lastIndexed", { unique: false });
      }
    };
  });
}

export async function indexDocument(
  docId: string,
  content: string
): Promise<void> {
  const db = await openDB();
  const indexedDoc: IndexedDocument = {
    id: docId,
    content,
    characters: extractCharacters(content),
    scenes: extractScenes(content),
    lastIndexed: Date.now(),
  };
  const transaction = db.transaction(STORE_NAME, "readwrite");
  const store = transaction.objectStore(STORE_NAME);
  return new Promise((resolve, reject) => {
    const request = store.put(indexedDoc);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

export async function searchIndex(query: string): Promise<SearchResult[]> {
  const db = await openDB();
  const transaction = db.transaction(STORE_NAME, "readonly");
  const store = transaction.objectStore(STORE_NAME);
  const allDocs = await new Promise<IndexedDocument[]>((resolve, reject) => {
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
  const results: SearchResult[] = [];
  for (const doc of allDocs) {
    const matches = findMatches(doc.content, query.toLowerCase());
    if (matches.length > 0) {
      results.push({ docId: doc.id, matches, score: matches.length });
    }
  }
  return results;
}

function findMatches(content: string, query: string): SearchMatch[] {
  const lines = content.split("\n");
  const matches: SearchMatch[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? "";
    if (line.toLowerCase().includes(query)) {
      matches.push({
        line: i + 1,
        text: line,
        context: lines
          .slice(Math.max(0, i - 1), Math.min(lines.length, i + 2))
          .join("\n"),
      });
    }
  }
  return matches;
}

function extractCharacters(content: string): string[] {
  const characters = new Set<string>();
  content.split("\n").forEach((line) => {
    const match = line.match(/^([^:]+):/);
    const characterName = match?.[1]?.trim();
    if (characterName && characterName.length < 30) {
      characters.add(characterName);
    }
  });
  return Array.from(characters);
}

function extractScenes(content: string): string[] {
  return content
    .split("\n")
    .filter((line) => line.includes("مشهد") || line.match(/^(INT\.|EXT\.)/));
}

export async function clearIndex(): Promise<void> {
  const db = await openDB();
  const transaction = db.transaction(STORE_NAME, "readwrite");
  const store = transaction.objectStore(STORE_NAME);
  return new Promise((resolve, reject) => {
    const request = store.clear();
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
}

/**
 * Security Tests for HTML Sanitization
 *
 * Tests for CodeQL issue #1319 - Incomplete multi-character sanitization
 */

import { describe, it, expect } from "vitest";
import {
  stripHtmlTags,
  escapeHtml,
  createSafeStyleObject,
} from "../sanitize-html";

describe("stripHtmlTags - Security Tests", () => {
  describe("CodeQL Issue #1319 - Incomplete multi-character sanitization", () => {
    it("should prevent multi-character bypass attacks", () => {
      const malicious = "<<script>>alert(1)<</script>>";
      const result = stripHtmlTags(malicious);

      // جميع أقواس الزاوية يجب أن تُهرّب أو تُزال
      expect(result).not.toMatch(/[<>]/);
      // النص العادي (alert) يبقى — الدالة تزيل العلامات فقط وليس المحتوى النصي
      expect(result).not.toContain("<script>");
      expect(result).not.toContain("</script>");
    });

    it("should handle double-nested script tags", () => {
      const malicious = "<scr<script>ipt>alert(1)</scr</script>ipt>";
      const result = stripHtmlTags(malicious);

      // All angle brackets should be escaped, no executable script
      expect(result).not.toMatch(/[<>]/);
      expect(result).not.toContain("script");
    });

    it("should escape remaining angle brackets after tag removal", () => {
      const input = "<script>alert(1)</script><";
      const result = stripHtmlTags(input);

      // The trailing < should be escaped
      expect(result).toContain("&lt;");
      expect(result).not.toMatch(/[<>]/);
    });

    it("should handle already-encoded content safely", () => {
      const encoded = "&lt;script&gt;alert(1)&lt;/script&gt;";
      const result = stripHtmlTags(encoded);

      // Should preserve encoded entities
      expect(result).toBe(encoded);
    });

    it("should handle multiple angle brackets in sequence", () => {
      const malicious = "<<>><><>>";
      const result = stripHtmlTags(malicious);

      // All angle brackets should be escaped
      expect(result).not.toMatch(/[<>]/);
    });
  });

  describe("Standard XSS Attack Vectors", () => {
    it("should remove script tags", () => {
      const malicious = '<script>alert("xss")</script>Hello';
      const result = stripHtmlTags(malicious);

      expect(result).toBe('alert("xss")Hello');
      expect(result).not.toContain("<script>");
      expect(result).not.toContain("</script>");
    });

    it("should remove iframe tags", () => {
      const malicious = '<iframe src="javascript:alert(1)"></iframe>Content';
      const result = stripHtmlTags(malicious);

      expect(result).toBe("Content");
      expect(result).not.toContain("<iframe>");
      expect(result).not.toContain("</iframe>");
    });

    it("should remove event handlers", () => {
      const malicious = '<div onclick="alert(1)">Click me</div>';
      const result = stripHtmlTags(malicious);

      expect(result).toBe("Click me");
      expect(result).not.toContain("onclick");
    });

    it("should handle incomplete tags", () => {
      const malicious = "<script";
      const result = stripHtmlTags(malicious);

      // Incomplete tag should be removed/escaped
      expect(result).not.toMatch(/[<>]/);
    });
  });

