import { NextRequest, NextResponse } from "next/server";
import {
  withNoStoreHeaders,
  withNoStoreResponseInit,
} from "@/lib/server/no-store";

function normalizeBaseUrl(url?: string | null): string | null {
  if (!url) {
    return null;
  }

  return url.replace(/\/$/, "");
}

function normalizeAbsoluteBaseUrl(url?: string | null): string | null {
  const normalized = normalizeBaseUrl(url);
  if (!normalized) {
    return null;
  }

  return /^https?:\/\//i.test(normalized) ? normalized : null;
}

const CONFIGURED_BACKEND_BASE_URL = normalizeBaseUrl(
  process.env["NEXT_PUBLIC_API_URL"] ||
    process.env["NEXT_PUBLIC_BACKEND_URL"] ||
    process.env["BACKEND_URL"] ||
    (process.env["NODE_ENV"] !== "production" ? "http://localhost:3001" : null)
);

const EDITOR_RUNTIME_ROUTE_SUFFIXES = [
  "/api/file-extract",
  "/api/files/extract",
  "/api/text-extract",
  "/api/suspicion-review",
  "/api/final-review",
  "/api/ai/context-enhance",
  "/api/export/pdfa",
  "/api/editor-runtime/health/deep",
  "/api/editor-runtime/health",
] as const;

const DEFAULT_TIMEOUT_BY_PATH: Record<string, number> = {
  "/api/file-extract": 10 * 60 * 1_000,
  "/api/files/extract": 10 * 60 * 1_000,
  "/api/text-extract": 35_000,
  "/api/suspicion-review": 60_000,
  "/api/final-review": 60_000,
  "/api/ai/context-enhance": 60_000,
  "/api/export/pdfa": 60_000,
  "/api/editor-runtime/health": 10_000,
  "/api/editor-runtime/health/deep": 10_000,
};

class BackendProxyError extends Error {
  errorCode: string | undefined;
  statusCode: number | undefined;

  constructor(
    message: string,
    options: {
      errorCode?: string;
      statusCode?: number;
      cause?: unknown;
    } = {}
  ) {
    super(message);
    this.name = "BackendProxyError";
    this.errorCode = options.errorCode;
    this.statusCode = options.statusCode;
    if (options.cause !== undefined) {
      (this as Error & { cause?: unknown }).cause = options.cause;
    }
  }
}

function stripKnownRouteSuffix(url: string): string {
  for (const suffix of EDITOR_RUNTIME_ROUTE_SUFFIXES) {
    if (url.endsWith(suffix)) {
      return url.slice(0, -suffix.length);
    }
  }

  return url;
}

const CONFIGURED_EDITOR_RUNTIME_BASE_URL = (() => {
  const candidates = [
    process.env["EDITOR_RUNTIME_BASE_URL"],
    process.env["FILE_IMPORT_BACKEND_URL"],
    process.env["NEXT_PUBLIC_FILE_IMPORT_BACKEND_URL"],
    process.env["NEXT_PUBLIC_FINAL_REVIEW_BACKEND_URL"],
  ];

  for (const candidate of candidates) {
    const absoluteUrl = normalizeAbsoluteBaseUrl(candidate);
    if (absoluteUrl) {
      return stripKnownRouteSuffix(absoluteUrl);
    }
  }

  return null;
})();

function requireBackendBaseUrl(baseUrl?: string | null): string {
  const resolvedBaseUrl =
    normalizeBaseUrl(baseUrl) ?? CONFIGURED_BACKEND_BASE_URL;

  if (!resolvedBaseUrl) {
    throw new Error(
      "Backend base URL is not configured. Set BACKEND_URL or NEXT_PUBLIC_BACKEND_URL."
    );
  }

  return resolvedBaseUrl;
}

export interface ProxyRequestOptions {
  baseUrl?: string | null;
  body?: BodyInit | null;
  headers?: HeadersInit;
  method?: string;
  search?: URLSearchParams;
  timeoutMs?: number;
}

function copySetCookieHeaders(source: Headers, target: Headers): void {
  const sourceWithSetCookie = source as Headers & {
    getSetCookie?: () => string[];
  };

  if (typeof sourceWithSetCookie.getSetCookie === "function") {
    for (const cookie of sourceWithSetCookie.getSetCookie()) {
      target.append("set-cookie", cookie);
    }
    return;
  }

  const singleCookie = source.get("set-cookie");
  if (singleCookie) {
    target.append("set-cookie", singleCookie);
  }
}

function buildTargetUrl(
  targetPath: string,
  request: NextRequest,
  search?: URLSearchParams,
  baseUrl?: string | null
): URL {
  const resolvedBaseUrl = requireBackendBaseUrl(baseUrl);
  const normalizedPath = targetPath.startsWith("/")
    ? targetPath
    : `/${targetPath}`;
  const targetUrl = new URL(`${resolvedBaseUrl}${normalizedPath}`);
  const sourceSearch = search ?? request.nextUrl.searchParams;

  sourceSearch.forEach((value, key) => {
    targetUrl.searchParams.append(key, value);
  });

  return targetUrl;
}

function buildProxyHeaders(
  request: NextRequest,
  additionalHeaders?: HeadersInit
): Headers {
  const headers = new Headers(additionalHeaders);
  const passThroughHeaders = [
    "accept",
    "accept-language",
    "authorization",
    "content-type",
    "cookie",
    "if-none-match",
    "x-requested-with",
  ];

  for (const headerName of passThroughHeaders) {
    const headerValue = request.headers.get(headerName);
    if (headerValue && !headers.has(headerName)) {
      headers.set(headerName, headerValue);
    }
  }

  const csrfHeader =
    request.headers.get("x-xsrf-token") ??
    request.cookies.get("XSRF-TOKEN")?.value;

  if (csrfHeader && !headers.has("x-xsrf-token")) {
    headers.set("x-xsrf-token", csrfHeader);
    headers.set("X-XSRF-TOKEN", csrfHeader);
  }

  return headers;
}

async function readRequestBody(
  request: NextRequest,
  method: string
): Promise<BodyInit | null | undefined> {
  if (method === "GET" || method === "HEAD") {
    return undefined;
  }

  const buffer = await request.arrayBuffer();
  return buffer.byteLength > 0 ? buffer : null;
}

async function proxyRequest(
  request: NextRequest,
  targetPath: string,
  options: ProxyRequestOptions = {}
): Promise<NextResponse> {
  const method = (options.method ?? request.method).toUpperCase();
  const targetUrl = buildTargetUrl(
    targetPath,
    request,
    options.search,
    options.baseUrl
  );
  const requestBody =
    options.body === undefined
      ? await readRequestBody(request, method)
      : options.body;
  const headers = buildProxyHeaders(request, options.headers);
  const timeoutMs =
    options.timeoutMs ?? DEFAULT_TIMEOUT_BY_PATH[targetPath] ?? 60_000;
  const signal = AbortSignal.timeout(timeoutMs);
  const requestInit: RequestInit = {
    method,
    headers,
    cache: "no-store",
    redirect: "manual",
    signal,
  };

  if (requestBody !== undefined) {
    requestInit.body = requestBody;
  }

  let upstreamResponse: Response;
  try {
    upstreamResponse = await fetch(targetUrl, requestInit);
  } catch (error) {
    const backendError = translateProxyError(
      error,
      targetUrl.toString(),
      timeoutMs
    );
    throw backendError;
  }

  const responseHeaders = new Headers();
  const excludedHeaders = new Set([
    "content-encoding",
    "content-length",
    "transfer-encoding",
  ]);

  upstreamResponse.headers.forEach((value, key) => {
    if (
      !excludedHeaders.has(key.toLowerCase()) &&
      key.toLowerCase() !== "set-cookie"
    ) {
      responseHeaders.set(key, value);
    }
  });
  copySetCookieHeaders(upstreamResponse.headers, responseHeaders);

  return new NextResponse(upstreamResponse.body, {
    status: upstreamResponse.status,
    statusText: upstreamResponse.statusText,
    headers: withNoStoreHeaders(responseHeaders),
  });
}

function formatProxyErrorMessage(
  error: unknown,
  fallbackMessage: string
): string {
  if (error instanceof BackendProxyError) {
    return error.message || fallbackMessage;
  }

  if (!(error instanceof Error)) {
    return fallbackMessage;
  }

  const parts: string[] = [];
  if (error.message && error.message !== "fetch failed") {
    parts.push(error.message);
  }

  const errorWithCause = error as Error & {
    cause?: { code?: unknown; message?: unknown };
  };
  const causeCode =
    typeof errorWithCause.cause?.code === "string"
      ? errorWithCause.cause.code.trim()
      : "";
  const causeMessage =
    typeof errorWithCause.cause?.message === "string"
      ? errorWithCause.cause.message.trim()
      : "";

  if (causeCode || causeMessage) {
    parts.push([causeCode, causeMessage].filter(Boolean).join(": "));
  }

  const combined = parts.filter(Boolean).join(" — ");
  return combined || fallbackMessage;
}

export function buildProxyErrorResponse(
  error: unknown,
  fallbackMessage: string
): NextResponse {
  const statusCode =
    error instanceof BackendProxyError && error.statusCode
      ? error.statusCode
      : 500;
  const errorCode =
    error instanceof BackendProxyError && error.errorCode
      ? error.errorCode
      : undefined;

  return NextResponse.json(
    {
      success: false,
      error: formatProxyErrorMessage(error, fallbackMessage),
      ...(errorCode ? { errorCode } : {}),
    },
    withNoStoreResponseInit({ status: statusCode })
  );
}

export async function proxyToBackend(
  request: NextRequest,
  targetPath: string,
  options: ProxyRequestOptions = {}
): Promise<NextResponse> {
  return proxyRequest(request, targetPath, options);
}

export function getBackendBaseUrl(): string | null {
  return CONFIGURED_BACKEND_BASE_URL;
}

export function getEditorRuntimeBaseUrl(): string | null {
  return CONFIGURED_EDITOR_RUNTIME_BASE_URL ?? CONFIGURED_BACKEND_BASE_URL;
}

function translateProxyError(
  error: unknown,
  targetUrl: string,
  timeoutMs: number
): BackendProxyError {
  const errorWithCause = error as Error & {
    cause?: { code?: unknown; message?: unknown };
    code?: unknown;
  };
  const causeCode =
    typeof errorWithCause.cause?.code === "string"
      ? errorWithCause.cause.code.trim().toUpperCase()
      : typeof errorWithCause.code === "string"
        ? errorWithCause.code.trim().toUpperCase()
        : "";
  const causeMessage =
    typeof errorWithCause.cause?.message === "string"
      ? errorWithCause.cause.message.trim()
      : error instanceof Error && error.message
        ? error.message.trim()
        : "";

  if (error instanceof DOMException && error.name === "TimeoutError") {
    return new BackendProxyError(
      `انتهت مهلة الاتصال بالخادم الخلفي بعد ${Math.round(timeoutMs / 1_000)} ثانية.`,
      {
        errorCode: "BACKEND_TIMEOUT",
        statusCode: 504,
        cause: error,
      }
    );
  }

  if (causeCode === "ECONNREFUSED") {
    return new BackendProxyError(
      `الخادم الخلفي غير متاح حالياً عند ${targetUrl}.`,
      {
        errorCode: "BACKEND_CONNECTION_REFUSED",
        statusCode: 503,
        cause: error,
      }
    );
  }

  if (causeCode === "ENOTFOUND" || causeCode === "EAI_AGAIN") {
    return new BackendProxyError(
      `تعذر العثور على عنوان الخادم الخلفي عند ${targetUrl}.`,
      {
        errorCode: "BACKEND_UNRESOLVED_HOST",
        statusCode: 502,
        cause: error,
      }
    );
  }

  if (causeCode === "ECONNRESET" || causeCode === "EPIPE") {
    return new BackendProxyError(
      `انقطع الاتصال بالخادم الخلفي أثناء تنفيذ الطلب.`,
      {
        errorCode: "BACKEND_CONNECTION_RESET",
        statusCode: 502,
        cause: error,
      }
    );
  }

  if (causeCode === "ETIMEDOUT") {
    return new BackendProxyError(
      `استغرق الخادم الخلفي وقتاً أطول من المسموح.`,
      {
        errorCode: "BACKEND_TIMEOUT",
        statusCode: 504,
        cause: error,
      }
    );
  }

  return new BackendProxyError(causeMessage || "فشل الاتصال بالخادم الخلفي.", {
    errorCode: "BACKEND_PROXY_FAILED",
    statusCode: 502,
    cause: error,
  });
}

/**
 * WebSocket Client Service
 *
 * Handles real-time communication with backend for analysis progress updates
 */

import { io, Socket } from "socket.io-client";
import { logger } from "@/lib/ai/utils/logger";

// Event types matching backend
export enum RealtimeEventType {
  // Agent events
  AGENT_STARTED = "agent:started",
  AGENT_PROGRESS = "agent:progress",
  AGENT_COMPLETED = "agent:completed",
  AGENT_FAILED = "agent:failed",

  // Job events
  JOB_STARTED = "job:started",
  JOB_PROGRESS = "job:progress",
  JOB_COMPLETED = "job:completed",
  JOB_FAILED = "job:failed",

  // Step events
  STEP_PROGRESS = "step:progress",

  // Connection events
  CONNECTED = "connect",
  DISCONNECTED = "disconnect",
  UNAUTHORIZED = "unauthorized",
  ERROR = "error",
}

export interface AgentProgressPayload {
  agentId: string;
  agentName: string;
  progress: number;
  message: string;
  timestamp: string;
}

export interface JobProgressPayload {
  jobId: string;
  progress: number;
  currentStep?: string;
  message?: string;
}

export interface StepProgressPayload {
  step: string;
  status: "started" | "in_progress" | "completed" | "failed";
  message: string;
}

type EventCallback<T = unknown> = (data: T) => void;

class WebSocketClient {
  private socket: Socket | null = null;
  private listeners: Map<string, Set<EventCallback>> = new Map();
  private maxReconnectAttempts = 5;

  /**
   * Connect to WebSocket server
   */
  connect(): void {
    if (this.socket?.connected) {
      logger.warn("[WebSocket] Already connected");
      return;
    }

    const backendUrl = process.env["NEXT_PUBLIC_SOCKET_URL"];
    if (!backendUrl) {
      logger.error("[WebSocket] NEXT_PUBLIC_SOCKET_URL is not configured");
      return;
    }

    this.socket = io(backendUrl, {
      transports: ["websocket", "polling"],
      reconnection: true,
      reconnectionAttempts: this.maxReconnectAttempts,
      reconnectionDelay: 1000,
      withCredentials: true, // Needed to send cookies during handshake
    });

    this.setupEventHandlers();
  }

  /**
   * Setup event handlers
   */
  private setupEventHandlers(): void {
    if (!this.socket) return;

    this.socket.on(RealtimeEventType.CONNECTED, () => {
      logger.info("[WebSocket] Connected");
      this.notifyListeners(RealtimeEventType.CONNECTED, {});
    });

    this.socket.on(RealtimeEventType.DISCONNECTED, (reason: string) => {
      logger.info("[WebSocket] Disconnected", { reason });
      this.notifyListeners(RealtimeEventType.DISCONNECTED, { reason });
    });

    this.socket.on(RealtimeEventType.ERROR, (error: unknown) => {
      logger.error("[WebSocket] Error", { error });
      this.notifyListeners(RealtimeEventType.ERROR, error);
    });

    this.socket.on(RealtimeEventType.UNAUTHORIZED, (data: unknown) => {
      logger.warn("[WebSocket] Unauthorized", { data });
      this.notifyListeners(RealtimeEventType.UNAUTHORIZED, data);
    });
  }

  /**
   * Subscribe to agent progress updates
   */
  onAgentProgress(callback: (data: AgentProgressPayload) => void): () => void {
    return this.on(RealtimeEventType.AGENT_PROGRESS, callback);
  }

  /**
   * Subscribe to job progress updates
   */
  onJobProgress(callback: (data: JobProgressPayload) => void): () => void {
    return this.on(RealtimeEventType.JOB_PROGRESS, callback);
  }

  /**
   * Subscribe to step progress updates
   */
  onStepProgress(callback: (data: StepProgressPayload) => void): () => void {
    return this.on(RealtimeEventType.STEP_PROGRESS, callback);
  }

  /**
   * Subscribe to job completion
   */
  onJobCompleted(callback: EventCallback): () => void {
    return this.on(RealtimeEventType.JOB_COMPLETED, callback);
  }

  /**
   * Subscribe to job failure
   */
  onJobFailed(callback: EventCallback): () => void {
    return this.on(RealtimeEventType.JOB_FAILED, callback);
  }

  /**
   * Generic event subscription
   */
  on<T = unknown>(eventType: string, callback: EventCallback<T>): () => void {
    if (!this.listeners.has(eventType)) {
      this.listeners.set(eventType, new Set());
    }

    this.listeners.get(eventType)!.add(callback as EventCallback);

    // Setup socket listener if not already set
    if (this.socket && this.socket.listeners(eventType).length === 0) {
      this.socket.on(eventType, (data: unknown) => {
        this.notifyListeners(eventType, data);
      });
    }

    // Return unsubscribe function
    return () => this.off(eventType, callback);
  }

  /**
   * Unsubscribe from event
   */
  off<T = unknown>(eventType: string, callback: EventCallback<T>): void {
    const listeners = this.listeners.get(eventType);
    if (listeners) {
      listeners.delete(callback as EventCallback);
      if (listeners.size === 0) {
        this.listeners.delete(eventType);
        if (this.socket) {
          this.socket.off(eventType);
        }
      }
    }
  }

  /**
   * Notify all listeners for an event
   */
  private notifyListeners(eventType: string, data: unknown): void {
    const listeners = this.listeners.get(eventType);
    if (listeners) {
      listeners.forEach((callback) => {
        try {
          callback(data);
        } catch (error) {
          logger.error(`[WebSocket] Error in listener for ${eventType}`, {
            error,
          });
        }
      });
    }
  }

  /**
   * Join a room (e.g., for job-specific updates)
   */
  joinRoom(room: string): void {
    if (!this.socket) return;
    this.socket.emit("join", room);
  }

  /**
   * Leave a room
   */
  leaveRoom(room: string): void {
    if (!this.socket) return;
    this.socket.emit("leave", room);
  }

  /**
   * Disconnect from server
   */
  disconnect(): void {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
      this.listeners.clear();
    }
  }

  /**
   * Get connection status
   */
  isConnected(): boolean {
    return this.socket?.connected || false;
  }
}

