import { describe, expect, it } from "vitest";
import { flatten, unflatten, encodeRecord, decodeRecord } from "./kv-utils";

describe("kv-utils", () => {
  describe("flatten", () => {
    it("should flatten a simple object", () => {
      const input = { a: 1, b: "string", c: true, d: null };
      const expected = { a: "1", b: "string", c: "true", d: "null" };
      expect(flatten(input)).toEqual(expected);
    });

    it("should flatten a nested object", () => {
      const input = {
        user: {
          name: "John",
          address: {
            city: "New York",
            zip: 10001,
          },
        },
      };
      const expected = {
        "user.name": "John",
        "user.address.city": "New York",
        "user.address.zip": "10001",
      };
      expect(flatten(input)).toEqual(expected);
    });

    it("should handle arrays as primitives (stringified)", () => {
      const input = {
        tags: ["a", "b", "c"],
        nested: {
          items: [1, 2],
        },
      };
      const expected = {
        tags: "a,b,c",
        "nested.items": "1,2",
      };
      expect(flatten(input)).toEqual(expected);
    });

    it("should use a prefix when provided", () => {
      const input = { a: 1 };
      const expected = { "prefix.a": "1" };
      expect(flatten(input, "prefix")).toEqual(expected);
    });

    it("should handle deep nesting", () => {
      const input = { a: { b: { c: { d: "value" } } } };
      const expected = { "a.b.c.d": "value" };
      expect(flatten(input)).toEqual(expected);
    });
  });

  describe("unflatten", () => {
    it("should unflatten a simple flat object", () => {
      const input = { a: "1", b: "string" };
      const expected = { a: "1", b: "string" };
      expect(unflatten(input)).toEqual(expected);
    });

    it("should unflatten a dotted object", () => {
      const input = {
        "user.name": "John",
        "user.address.city": "New York",
      };
      const expected = {
        user: {
          name: "John",
          address: {
            city: "New York",
          },
        },
      };
      expect(unflatten(input)).toEqual(expected);
    });

    it("should prevent prototype pollution via __proto__", () => {
      const input = {
        "__proto__.polluted": "true",
        "user.__proto__.admin": "true",
      };
      const result = unflatten(input);
      expect(result).toEqual({});
      expect(({} as any).polluted).toBeUndefined();
    });

    it("should prevent prototype pollution via constructor", () => {
      const input = {
        "constructor.prototype.polluted": "true",
      };
      const result = unflatten(input);
      expect(result).toEqual({});
      expect(({} as any).polluted).toBeUndefined();
    });

    it("should prevent prototype pollution via prototype", () => {
      const input = {
        "prototype.polluted": "true",
      };
      const result = unflatten(input);
      expect(result).toEqual({});
      expect(({} as any).polluted).toBeUndefined();
    });

    it("should safely handle regular keys that overlap with dangerous names but aren't exactly them", () => {
      const flat = {
        my__proto__: "safe",
        constructors: "safe",
        prototypes: "safe",
      };

      expect(unflatten(flat)).toEqual({
        my__proto__: "safe",
        constructors: "safe",
        prototypes: "safe",
      });
    });
  });

  describe("encodeRecord and decodeRecord", () => {
    it("should encode a record into a string", () => {
      const input = { a: "1", b: "2" };
      const result = encodeRecord(input);
      expect(result).toContain("a=1");
      expect(result).toContain("b=2");
    });

    it("should decode a string into a record", () => {
      const input = "a=1\nb=2";
      const expected = { a: "1", b: "2" };
      expect(decodeRecord(input)).toEqual(expected);
    });

    it("should handle round-trip encoding and decoding", () => {
      const input = {
        user: {
          name: "John Doe",
          meta: {
            id: 123,
          },
        },
      };
      const encoded = encodeRecord(input);
      const decoded = decodeRecord(encoded);
      expect(decoded).toEqual(flatten(input));
    });

    it("should escape special characters during encoding", () => {
      const input = {
        "key.with.dot": "value=with=equals\nand\nnewlines\\and\\backslashes",
      };
      const encoded = encodeRecord(input);
      expect(encoded).toContain(
        "key.with.dot=value\\=with\\=equals\\nand\\nnewlines\\\\and\\\\backslashes"
      );

      const decoded = decodeRecord(encoded);
      expect(decoded).toEqual({
        "key.with.dot": "value=with=equals\nand\nnewlines\\and\\backslashes",
      });
    });

    it("should handle carriage returns", () => {
      const input = { a: "line1\rline2" };
      const encoded = encodeRecord(input);
      expect(encoded).toContain("a=line1\\rline2");
      const decoded = decodeRecord(encoded);
      expect(decoded).toEqual({ a: "line1\rline2" });
    });
  });
});

export function flatten(
  obj: Record<string, any>,
  prefix = ""
): Record<string, string> {
  const result: Record<string, string> = {};

  for (const [key, value] of Object.entries(obj)) {
    const newKey = prefix ? `${prefix}.${key}` : key;

    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      Object.assign(result, flatten(value, newKey));
    } else {
      result[newKey] = String(value);
    }
  }

  return result;
}

export function unflatten(flat: Record<string, string>): Record<string, any> {
  const result: Record<string, any> = {};

  // SECURITY: Dangerous keys that could lead to prototype pollution
  const DANGEROUS_KEYS = ["__proto__", "constructor", "prototype"];

  for (const [key, value] of Object.entries(flat)) {
    const parts = key.split(".");

    // SECURITY FIX: Validate parts to prevent prototype pollution
    if (parts.some((part) => DANGEROUS_KEYS.includes(part))) {
      // Skip potentially dangerous key silently
      continue;
    }

    let current: any = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      // SECURITY FIX: Additional check to prevent prototype pollution
      if (part && !DANGEROUS_KEYS.includes(part)) {
        if (!Object.prototype.hasOwnProperty.call(current, part)) {
          current[part] = {};
        }
        current = current[part] || Object.create(null);
      }
    }

    const lastPart = parts[parts.length - 1];
    // SECURITY FIX: Validate lastPart before assignment
    if (lastPart && !DANGEROUS_KEYS.includes(lastPart)) {
      current[lastPart] = value;
    }
  }

  return result;
}

function escapeValue(value: string): string {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/=/g, "\\=");
}

function unescapeValue(value: string): string {
  return value
    .replace(/\\=/g, "=")
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "\r")
    .replace(/\\\\/g, "\\");
}

export function encodeRecord(obj: Record<string, any>): string {
  const flat = flatten(obj);
  const lines = Object.entries(flat).map(
    ([key, value]) => `${key}=${escapeValue(value)}`
  );
  return lines.join("\n");
}

export function decodeRecord(text: string): Record<string, string> {
  const lines = text.split("\n").filter((line) => line.trim());
  const result: Record<string, string> = {};

  for (const line of lines) {
    const idx = line.indexOf("=");
    if (idx === -1) continue;
    const key = line.slice(0, idx);
    const value = unescapeValue(line.slice(idx + 1));
    result[key] = value;
  }

  return result;
}

