/**
 * @description بناء إعدادات محول OCR من سطر الأوامر ومتغيرات البيئة
 */

import process from "node:process";
import type {
  ConfigManager,
  LLMConfig,
  MistralOCRConfig,
  NormalizationOptions,
  ParsedArgs,
  PreOCRConfig,
} from "./types.js";
import { clamp, isTruthy, toNumberFloat, toNumberInt } from "./text-helpers.js";

const DEFAULT_LLM_MODEL = "kimi-k2.5";
const DEFAULT_MISTRAL_OCR_MODEL = "mistral-ocr-latest";
const DEFAULT_PRE_OCR_LANG = "ar";

const DEFAULT_MATCH_THRESHOLD = 0.88;
const DEFAULT_FULLPAGE_FALLBACK_RATIO = 0.7;
const DEFAULT_REGION_PADDING_PX = 12;
const DEFAULT_LLM_MAX_ITERATIONS = 3;
const DEFAULT_LLM_TARGET_MATCH = 100.0;
const DEFAULT_DIFF_PREVIEW_LINES = 12;

const DEFAULT_INPUT = String.raw`E:\New folder (31)\12.pdf`;

function parseArgs(argv: string[]): ParsedArgs {
  const parsed: ParsedArgs = {};

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (!token || !token.startsWith("--")) {
      continue;
    }

    const arg = token.slice(2);
    const eq = arg.indexOf("=");

    if (eq >= 0) {
      const name = arg.slice(0, eq).trim();
      const value = arg.slice(eq + 1);
      if (name) {
        parsed[name] = value;
      }
      continue;
    }

    const name = arg.trim();
    if (!name) {
      continue;
    }

    const next = argv[i + 1];
    if (typeof next === "string" && !next.startsWith("--")) {
      parsed[name] = next;
      i += 1;
    } else {
      parsed[name] = true;
    }
  }

  return parsed;
}

function argString(parsed: ParsedArgs, name: string, fallback: string): string {
  const v = parsed[name];
  if (typeof v === "string" && v.trim()) {
    return v;
  }
  return fallback;
}

function argOptionalString(
  parsed: ParsedArgs,
  name: string
): string | undefined {
  const v = parsed[name];
  if (typeof v === "string" && v.trim()) {
    return v;
  }
  return undefined;
}

function argBool(parsed: ParsedArgs, name: string, fallback = false): boolean {
  const v = parsed[name];
  if (typeof v === "boolean") {
    return v;
  }
  if (typeof v === "string") {
    return isTruthy(v);
  }
  return fallback;
}

export function buildConfig(argv: string[]): ConfigManager {
  const args = parseArgs(argv);
  const llmReferencePath = argOptionalString(args, "llm-reference");
  const llm: LLMConfig = {
    enabled: argBool(args, "use-llm"),
    model: argString(args, "llm-model", DEFAULT_LLM_MODEL),
    strict: argBool(args, "llm-strict"),
    iterative: !argBool(args, "llm-no-iterative"),
    maxIterations: Math.max(
      1,
      toNumberInt(
        argOptionalString(args, "llm-max-iterations"),
        DEFAULT_LLM_MAX_ITERATIONS
      )
    ),
    targetMatch: clamp(
      toNumberFloat(
        argOptionalString(args, "llm-target-match"),
        DEFAULT_LLM_TARGET_MATCH
      ),
      0,
      100
    ),
    diffPreviewLines: Math.max(
      1,
      toNumberInt(
        argOptionalString(args, "llm-diff-preview-lines"),
        DEFAULT_DIFF_PREVIEW_LINES
      )
    ),
    ...(llmReferencePath !== undefined
      ? { referencePath: llmReferencePath }
      : {}),
  };

  const tableRaw = (
    argOptionalString(args, "mistral-table-format") ??
    process.env["MISTRAL_OCR_TABLE_FORMAT"] ??
    ""
  )
    .trim()
    .toLowerCase();
  const tableFormat =
    tableRaw === "markdown" || tableRaw === "html"
      ? (tableRaw as "markdown" | "html")
      : undefined;
  const annotationSchemaPath =
    argOptionalString(args, "mistral-annotation-schema") ??
    (process.env["MISTRAL_ANNOTATION_SCHEMA_PATH"]?.trim() || undefined);
  const annotationPrompt =
    argOptionalString(args, "mistral-annotation-prompt") ??
    (process.env["MISTRAL_ANNOTATION_PROMPT"]?.trim() || undefined);
  const annotationOutputPath =
    argOptionalString(args, "mistral-annotation-output") ??
    (process.env["MISTRAL_ANNOTATION_OUTPUT_PATH"]?.trim() || undefined);

  const mistral: MistralOCRConfig = {
    model: argString(
      args,
      "mistral-ocr-model",
      (process.env["MISTRAL_OCR_MODEL"] ?? DEFAULT_MISTRAL_OCR_MODEL).trim() ||
        DEFAULT_MISTRAL_OCR_MODEL
    ),
    useDocumentInput: !argBool(args, "mistral-disable-document-input"),
    useBatchOCR: argBool(args, "mistral-use-batch"),
    batchTimeoutSec: Math.max(
      5,
      toNumberInt(
        argOptionalString(args, "mistral-batch-timeout-sec") ??
          process.env["MISTRAL_BATCH_TIMEOUT_SEC"],
        300
      )
    ),
    batchPollIntervalSec: Math.max(
      0.5,
      toNumberFloat(
        argOptionalString(args, "mistral-batch-poll-interval-sec") ??
          process.env["MISTRAL_BATCH_POLL_INTERVAL_SEC"],
        3
      )
    ),
    annotationStrict: !argBool(args, "mistral-annotation-non-strict"),
    extractHeader: argBool(args, "mistral-extract-header"),
    extractFooter: argBool(args, "mistral-extract-footer"),
    includeImageBase64: argBool(args, "mistral-include-image-base64"),
    ...(annotationSchemaPath !== undefined ? { annotationSchemaPath } : {}),
    ...(annotationPrompt !== undefined ? { annotationPrompt } : {}),
    ...(annotationOutputPath !== undefined ? { annotationOutputPath } : {}),
    ...(tableFormat !== undefined ? { tableFormat } : {}),
  };
  if (mistral.model !== DEFAULT_MISTRAL_OCR_MODEL) {
    throw new Error(
      `Mistral OCR model must be ${DEFAULT_MISTRAL_OCR_MODEL}. Received: ${mistral.model}`
    );
  }

  const preOcr: PreOCRConfig = {
    enabled: !argBool(args, "disable-pre-ocr-filter"),
    lang: argString(
      args,
      "pre-ocr-lang",
      (process.env["PRE_OCR_LANG"] ?? DEFAULT_PRE_OCR_LANG).trim() ||
        DEFAULT_PRE_OCR_LANG
    ),
    matchThreshold: clamp(
      toNumberFloat(
        argOptionalString(args, "pre-ocr-match-threshold"),
        DEFAULT_MATCH_THRESHOLD
      ),
      0,
      1
    ),
    fullpageFallbackRatio: clamp(
      toNumberFloat(
        argOptionalString(args, "pre-ocr-fullpage-fallback-ratio"),
        DEFAULT_FULLPAGE_FALLBACK_RATIO
      ),
      0,
      1
    ),
    regionPaddingPx: Math.max(
      0,
      toNumberInt(
        argOptionalString(args, "pre-ocr-region-padding-px"),
        DEFAULT_REGION_PADDING_PX
      )
    ),
  };

  const normalizerOptions: NormalizationOptions = {
    normalizeYa: argBool(args, "normalize-ya", false),
    normalizeTaMarbuta: argBool(args, "normalize-ta-marbuta", false),
    normalizeHamza: !argBool(args, "no-normalize-hamza"),
    normalizeDigits: (argOptionalString(args, "normalize-digits") ??
      "arabic") as "none" | "arabic" | "western",
    removeDiacritics: !argBool(args, "no-remove-diacritics"),
    fixConnectedLetters: !argBool(args, "no-fix-connected-letters"),
    fixArabicPunctuation: !argBool(args, "no-fix-arabic-punctuation"),
    scriptSpecificRules: !argBool(args, "no-script-specific-rules"),
  };

  const outputPath = argOptionalString(args, "output");
  return {
    inputPath: argString(args, "input", DEFAULT_INPUT),
    normalizeOutput: !argBool(args, "no-normalize"),
    normalizerOptions,
    saveRawMarkdown: !argBool(args, "no-raw"),
    llm,
    mistral,
    preOcr,
    ...(outputPath !== undefined ? { outputPath } : {}),
  };
}

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  ErrorCode,
  McpError,
} from "@modelcontextprotocol/sdk/types.js";
import dotenv from "dotenv";

dotenv.config();

import {
  PDFToTextConverter,
  ConfigManager,
  NormalizationOptions,
} from "./ncio_mistral_all_in_one.js";

const CANONICAL_MISTRAL_OCR_MODEL = "mistral-ocr-latest";

const server = new Server(
  {
    name: "mistral-ocr-mcp",
    version: "1.0.0",
  },
  {
    capabilities: {
      tools: {},
    },
  }
);

// Define the input schema manually as JSON Schema
const convertDocumentInputSchema = {
  type: "object" as const,
  properties: {
    inputPath: {
      type: "string",
      description: "The absolute path to the input PDF, MD, or TXT file",
    },
    outputPath: {
      type: "string",
      description:
        "Optional absolute path to save the output markdown. If not provided, it will be saved next to the input file.",
    },
    normalizeOutput: {
      type: "boolean",
      description: "Whether to normalize the output markdown",
      default: true,
    },
    saveRawMarkdown: {
      type: "boolean",
      description: "Whether to save the raw markdown before LLM refinement",
      default: true,
    },
    useLlm: {
      type: "boolean",
      description: "Whether to use an LLM for post-processing/refinement",
      default: false,
    },
    llmModel: {
      type: "string",
      description: "The Kimi chat model to use for structural refinement",
      default: "kimi-k2.5",
    },
    llmReferencePath: {
      type: "string",
      description:
        "Optional absolute path to the reference markdown used for structural diff-based refinement",
    },
    llmStrict: {
      type: "boolean",
      description: "If true, LLM refinement errors will fail the process",
      default: false,
    },
    mistralOcrModel: {
      type: "string",
      description: "The Mistral OCR model to use",
      default: "mistral-ocr-latest",
    },
    useBatchOcr: {
      type: "boolean",
      description: "Whether to use Mistral Batch OCR instead of direct OCR",
      default: false,
    },
    normalizerOptions: {
      type: "object",
      description: "Options for Arabic text normalization",
      properties: {
        normalizeYa: {
          type: "boolean",
          description: "Normalize ى → ي (default: false)",
          default: false,
        },
        normalizeTaMarbuta: {
          type: "boolean",
          description: "Normalize ة → ه (default: false, DANGEROUS!)",
          default: false,
        },
        normalizeHamza: {
          type: "boolean",
          description: "Normalize همزات إأآ → ا (default: true)",
          default: true,
        },
        normalizeDigits: {
          type: "string",
          enum: ["none", "arabic", "western"],
          description: "Normalize digits (default: arabic)",
          default: "arabic",
        },
        removeDiacritics: {
          type: "boolean",
          description: "Remove Arabic diacritics (default: true)",
          default: true,
        },
        fixConnectedLetters: {
          type: "boolean",
          description:
            "Fix Arabic Presentation Forms to standard letters (default: true)",
          default: true,
        },
        fixArabicPunctuation: {
          type: "boolean",
          description: "Fix Arabic punctuation spacing (default: true)",
          default: true,
        },
        scriptSpecificRules: {
          type: "boolean",
          description: "Enable screenplay-specific rules (default: true)",
          default: true,
        },
      },
    },
  },
  required: ["inputPath"],
};

server.setRequestHandler(ListToolsRequestSchema, async () => {
  return {
    tools: [
      {
        name: "convert_document_to_markdown",
        description:
          "Converts a PDF document to Markdown using Mistral OCR with optional LLM refinement and normalization.",
        inputSchema: convertDocumentInputSchema,
      },
    ],
  };
});

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  if (request.params.name !== "convert_document_to_markdown") {
    throw new McpError(
      ErrorCode.MethodNotFound,
      `Unknown tool: ${request.params.name}`
    );
  }

  const args = request.params.arguments as {
    inputPath: string;
    outputPath?: string;
    normalizeOutput?: boolean;
    saveRawMarkdown?: boolean;
    useLlm?: boolean;
    llmModel?: string;
    llmReferencePath?: string;
    llmStrict?: boolean;
    mistralOcrModel?: string;
    useBatchOcr?: boolean;
    normalizerOptions?: NormalizationOptions;
  };

  if (!args.inputPath) {
    throw new McpError(ErrorCode.InvalidParams, "inputPath is required");
  }

  const {
    inputPath,
    outputPath,
    normalizeOutput = true,
    saveRawMarkdown = true,
    useLlm = false,
    llmModel = "kimi-k2.5",
    llmReferencePath,
    llmStrict = false,
    mistralOcrModel = "mistral-ocr-latest",
    useBatchOcr = false,
    normalizerOptions,
  } = args;
  const llmReference = llmReferencePath?.trim();

  if (mistralOcrModel !== CANONICAL_MISTRAL_OCR_MODEL) {
    throw new McpError(
      ErrorCode.InvalidParams,
      `mistralOcrModel must be ${CANONICAL_MISTRAL_OCR_MODEL}.`
    );
  }

  const config: ConfigManager = {
    inputPath,
    normalizeOutput,
    saveRawMarkdown,
    llm: {
      enabled: useLlm,
      model: llmModel,
      strict: llmStrict,
      iterative: true,
      maxIterations: 2,
      targetMatch: 98.5,
      diffPreviewLines: 12,
      ...(llmReference ? { referencePath: llmReference } : {}),
    },
    mistral: {
      model: mistralOcrModel,
      useDocumentInput: true,
      useBatchOCR: useBatchOcr,
      batchTimeoutSec: 300,
      batchPollIntervalSec: 3,
      annotationStrict: false,
      extractHeader: false,
      extractFooter: false,
      includeImageBase64: false,
    },
    preOcr: {
      enabled: true,
      lang: "ar",
      matchThreshold: 0.88,
      fullpageFallbackRatio: 0.7,
      regionPaddingPx: 12,
    },
    ...(outputPath ? { outputPath } : {}),
    ...(normalizerOptions !== undefined ? { normalizerOptions } : {}),
  };

  try {
    const converter = new PDFToTextConverter(config);
    const { finalMarkdown } = await converter.convert();

    let successMsg = "Document converted successfully.";

    try {
      const outPath = converter.resolveOutputPath();
      const savedPath = await converter.writeNonOverwritingFile(
        outPath,
        finalMarkdown
      );
      successMsg += ` Saved to ${savedPath}`;
    } catch (fsError) {
      console.error("Failed to write to file:", fsError);
      successMsg += ` Note: Failed to write to file: ${fsError}`;
    }

    return {
      content: [
        {
          type: "text",
          text: `${successMsg}\n\nFinal Markdown Preview (first 1000 chars):\n${finalMarkdown.substring(0, 1000)}...`,
        },
      ],
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return {
      content: [
        {
          type: "text",
          text: `Conversion failed: ${errorMessage}`,
        },
      ],
      isError: true,
    };
  }
});

async function run() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("Mistral OCR MCP Server running on stdio");
}

run().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

