/**
 * @fileoverview Next.js Middleware — يضيف رؤوس الحماية الأساسية (CSP، HSTS،
 * X-Frame-Options، X-Content-Type-Options، Referrer-Policy، إلخ).
 *
 * ملاحظة بنيوية: في Next.js 16 توجد تسميتان لطبقة الإدخال هذه: `proxy.ts`
 * (الجديدة) و `middleware.ts` (التقليدية). الإصدار 16.2.3 يحوي عطلًا في خط
 * الإنتاج عند استخدام `proxy.ts` — يُولّد `middleware.js.nft.json` ثم يطلب
 * `proxy.js.nft.json` غير الموجود فيُسقط البناء بـ ENOENT. نُثبّت التسمية
 * التقليدية حتى يُصلَح العطل upstream.
 */

import { NextRequest, NextResponse } from "next/server";

interface ContentSecurityPolicyOptions {
  isDevelopment: boolean;
  allowedDevOrigin?: string;
  sentryOrigin?: string;
  cdnOrigin?: string;
  connectOrigins?: string[];
}

function getOriginFromUrl(url: string | undefined): string {
  if (!url) {
    return "";
  }

  try {
    return new URL(url).origin;
  } catch {
    return "";
  }
}

export function buildContentSecurityPolicy({
  isDevelopment,
  allowedDevOrigin,
  sentryOrigin,
  cdnOrigin,
  connectOrigins = [],
}: ContentSecurityPolicyOptions): string | null {
  if (isDevelopment) {
    return null;
  }

  const connectSrcParts = Array.from(
    new Set(
      [
        "'self'",
        "https://apis.google.com",
        "https://*.googleapis.com",
        "https://identitytoolkit.googleapis.com",
        "https://securetoken.googleapis.com",
        "https://www.googleapis.com",
        ...connectOrigins,
        sentryOrigin,
        cdnOrigin,
      ].filter(Boolean)
    )
  );

  const frameAncestors = allowedDevOrigin
    ? `frame-ancestors 'self' ${allowedDevOrigin}`
    : "frame-ancestors 'none'";

  return [
    "default-src 'self'",
    [
      "script-src",
      "'self'",
      // Preserve static prerendering while allowing Next.js bootstrap and hydration.
      "'unsafe-inline'",
      "https://apis.google.com",
      "https://www.gstatic.com",
      "https://*.googleapis.com",
      "https://*.sentry.io",
      cdnOrigin,
    ]
      .filter(Boolean)
      .join(" "),
    "worker-src 'self' blob:",
    "child-src 'self' blob:",
    [
      "style-src",
      "'self'",
      // Next.js emits inline styles during streaming and hydration.
      "'unsafe-inline'",
      "https://fonts.googleapis.com",
      cdnOrigin,
    ]
      .filter(Boolean)
      .join(" "),
    [
      "font-src",
      "'self'",
      "https://fonts.gstatic.com",
      "https://r2cdn.perplexity.ai",
      "data:",
      cdnOrigin,
    ]
      .filter(Boolean)
      .join(" "),
    [
      "img-src",
      "'self'",
      "data:",
      "blob:",
      "https:",
      "https://placehold.co",
      "https://images.unsplash.com",
      "https://picsum.photos",
      "https://www.gstatic.com",
      "https://*.googleapis.com",
      cdnOrigin,
    ]
      .filter(Boolean)
      .join(" "),
    "media-src 'self' https://cdn.pixabay.com https://*.pixabay.com blob: data:",
    `connect-src ${connectSrcParts.join(" ")}`,
    "frame-src 'self' https://apis.google.com https://*.googleapis.com",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    frameAncestors,
    "upgrade-insecure-requests",
  ].join("; ");
}

function collectAllowedConnectOrigins(
  urls: Array<string | undefined>
): string[] {
  return Array.from(
    new Set(
      urls
        .map((url) => getOriginFromUrl(url))
        .filter((origin): origin is string => Boolean(origin))
    )
  );
}

/**
 * نقطة الدخول الرسمية لطبقة Next.js middleware. تُحسب رؤوس CSP الديناميكية
 * وتُلصق بكل استجابة قبل تسليمها للمتصفح.
 *
 * @param _request - طلب Next.js الوارد (غير مستخدم حاليًا، حقوق التوسعة لاحقًا).
 * @returns NextResponse مع رؤوس الحماية.
 */
export function middleware(_request: NextRequest) {
  const response = NextResponse.next();

  // Development mode detection
  const isDevelopment = process.env["NODE_ENV"] === "development";
  const allowedDevOrigin = process.env["ALLOWED_DEV_ORIGIN"] || "";
  const sentryOrigin = getOriginFromUrl(process.env["NEXT_PUBLIC_SENTRY_DSN"]);
  const cdnOrigin = getOriginFromUrl(process.env["NEXT_PUBLIC_CDN_URL"]);
  const connectOrigins = collectAllowedConnectOrigins([
    process.env["NEXT_PUBLIC_API_URL"],
    process.env["NEXT_PUBLIC_BACKEND_URL"],
    process.env["BACKEND_URL"],
    process.env["EDITOR_RUNTIME_BASE_URL"],
    process.env["FILE_IMPORT_BACKEND_URL"],
    process.env["NEXT_PUBLIC_FILE_IMPORT_BACKEND_URL"],
    process.env["NEXT_PUBLIC_FINAL_REVIEW_BACKEND_URL"],
  ]);
  const contentSecurityPolicy = buildContentSecurityPolicy({
    isDevelopment,
    allowedDevOrigin,
    sentryOrigin,
    cdnOrigin,
    connectOrigins,
  });

  if (contentSecurityPolicy) {
    response.headers.set("Content-Security-Policy", contentSecurityPolicy);
  }

  // Additional security headers
  if (!isDevelopment) {
    response.headers.set(
      "Strict-Transport-Security",
      "max-age=31536000; includeSubDomains; preload"
    );
  }
  response.headers.set("X-Content-Type-Options", "nosniff");
  response.headers.set("X-Frame-Options", "DENY");
  response.headers.set("X-XSS-Protection", "1; mode=block");
  response.headers.set("Referrer-Policy", "strict-origin-when-cross-origin");

  return response;
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - public files (public folder)
     */
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};

// Pipeline Orchestration Executor
// Manages execution of AI analysis pipelines with proper error handling and progress tracking

import { geminiService, type GeminiConfig } from "@/ai/gemini-service";
import { cachedGeminiCall, generateGeminiCacheKey } from "@/lib/redis";
import { logger } from "@/lib/ai/utils/logger";
import { AnalysisType } from "@/types/enums";

export interface PipelineStep {
  id: string;
  name: string;
  description: string;
  type: AnalysisType;
  config: GeminiConfig;
  dependencies?: string[]; // IDs of steps this depends on
  timeout?: number; // in milliseconds
  retries?: number;
}

export interface PipelineResult {
  stepId: string;
  success: boolean;
  data?: any;
  error?: string;
  duration: number;
  cached: boolean;
}

export interface PipelineExecution {
  id: string;
  steps: PipelineStep[];
  results: Map<string, PipelineResult>;
  status: "pending" | "running" | "completed" | "failed";
  progress: number;
  startTime: Date;
  endTime?: Date;
}

// Orchestrator class
export class PipelineOrchestrator {
  private activeExecutions = new Map<string, PipelineExecution>();

  // Execute a pipeline with dependency management
  async executePipeline(
    pipelineId: string,
    steps: PipelineStep[],
    inputData: Record<string, any>
  ): Promise<PipelineExecution> {
    const execution: PipelineExecution = {
      id: pipelineId,
      steps,
      results: new Map(),
      status: "running",
      progress: 0,
      startTime: new Date(),
    };

    this.activeExecutions.set(pipelineId, execution);

    try {
      // Build dependency graph

      // Execute steps in order
      const executedSteps = new Set<string>();

      for (const step of steps) {
        if (this.canExecuteStep(step, executedSteps)) {
          const result = await this.executeStep(step, inputData);
          execution.results.set(step.id, result);
          executedSteps.add(step.id);

          // Update progress
          execution.progress = (executedSteps.size / steps.length) * 100;
        } else {
          // Wait for dependencies
          await this.waitForDependencies(step, execution);
          const result = await this.executeStep(step, inputData);
          execution.results.set(step.id, result);
          executedSteps.add(step.id);
          execution.progress = (executedSteps.size / steps.length) * 100;
        }
      }

      execution.status = "completed";
      execution.endTime = new Date();
    } catch {
      execution.status = "failed";
      execution.endTime = new Date();
      logger.error("Pipeline execution failed");
    }

    return execution;
  }

  // Execute individual step with caching and error handling
  private async executeStep(
    step: PipelineStep,
    inputData: Record<string, any>
  ): Promise<PipelineResult> {
    const startTime = Date.now();

    try {
      const cacheKey = generateGeminiCacheKey(
        `analysis:${step.id}:${step.type}`,
        "gemini-1.5-flash",
        inputData
      );

      const result = await cachedGeminiCall(
        cacheKey,
        async () => {
          // Build prompt based on step type and input data
          const prompt = this.buildStepPrompt(step, inputData);

          return geminiService.generateText(prompt, {
            model: "gemini-1.5-flash",
          });
        },
        { ttl: 1800 } // 30 minutes TTL
      );

      return {
        stepId: step.id,
        success: true,
        data: result,
        duration: Date.now() - startTime,
        cached: false, // This would need to be determined from cache layer
      };
    } catch (error) {
      return {
        stepId: step.id,
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
        duration: Date.now() - startTime,
        cached: false,
      };
    }
  }

  // Check if step can be executed
  private canExecuteStep(
    step: PipelineStep,
    executedSteps: Set<string>
  ): boolean {
    const dependencies = step.dependencies || [];
    return dependencies.every((dep) => executedSteps.has(dep));
  }

  // Wait for dependencies to complete
  private async waitForDependencies(
    step: PipelineStep,
    execution: PipelineExecution
  ): Promise<void> {
    const dependencies = step.dependencies || [];
    const checkInterval = 100; // ms
    const maxWait = 30000; // 30 seconds
    let waited = 0;

    while (waited < maxWait) {
      const allDepsCompleted = dependencies.every((dep) =>
        execution.results.has(dep)
      );

      if (allDepsCompleted) {
        return;
      }

      await new Promise((resolve) => setTimeout(resolve, checkInterval));
      waited += checkInterval;
    }

    throw new Error(`Dependencies not satisfied for step ${step.id}`);
  }

  // Build prompt for step execution
  private buildStepPrompt(
    step: PipelineStep,
    inputData: Record<string, any>
  ): string {
    const basePrompts: Record<AnalysisType, string> = {
      [AnalysisType.CHARACTERS]:
        "Analyze the characters in this screenplay. Identify main characters, their traits, relationships, and character arcs.",
      [AnalysisType.THEMES]:
        "Extract and analyze the main themes and motifs in this screenplay.",
      [AnalysisType.STRUCTURE]:
        "Analyze the dramatic structure, acts, and plot points in this screenplay.",
      [AnalysisType.SCREENPLAY]:
        "Review this screenplay for technical writing quality, formatting, and dramatic effectiveness.",
      [AnalysisType.QUICK]:
        "Provide a quick summary and initial impressions of this screenplay.",
      [AnalysisType.DETAILED]:
        "Provide a comprehensive analysis covering all aspects of this screenplay.",
      [AnalysisType.FULL]:
        "Perform complete analysis including characters, themes, structure, and recommendations.",
    };

    const prompt = basePrompts[step.type] || "Analyze this content:";

    return `${prompt}\n\nContent: ${JSON.stringify(inputData)}\n\nProvide detailed analysis in Arabic.`;
  }

  // Get execution status
  getExecution(pipelineId: string): PipelineExecution | undefined {
    return this.activeExecutions.get(pipelineId);
  }

  // Cancel execution
  cancelExecution(pipelineId: string): boolean {
    const execution = this.activeExecutions.get(pipelineId);
    if (execution && execution.status === "running") {
      execution.status = "failed";
      execution.endTime = new Date();
      return true;
    }
    return false;
  }
}

