/**
 * @file This file defines the core TypeScript types and enums used throughout the application.
 * These types ensure consistency and provide strong typing for agent configurations, tasks, and other critical data structures.
 */

/**
 * @enum {string} TaskType
 * @description Defines the unique identifiers for all available agent tasks.
 * This enum is crucial for task routing, agent selection, and configuration mapping.
 */
export const enum TaskType {
  // Core foundational agents
  ANALYSIS = "analysis",
  CREATIVE = "creative",
  INTEGRATED = "integrated",
  COMPLETION = "completion",

  // Advanced analytical agents
  RHYTHM_MAPPING = "rhythm-mapping",
  CHARACTER_NETWORK = "character-network",
  DIALOGUE_FORENSICS = "dialogue-forensics",
  THEMATIC_MINING = "thematic-mining",
  STYLE_FINGERPRINT = "style-fingerprint",
  CONFLICT_DYNAMICS = "conflict-dynamics",

  // Creative generation agents
  ADAPTIVE_REWRITING = "adaptive-rewriting",
  SCENE_GENERATOR = "scene-generator",
  CHARACTER_VOICE = "character-voice",
  WORLD_BUILDER = "world-builder",

  // Predictive & optimization agents
  PLOT_PREDICTOR = "plot-predictor",
  TENSION_OPTIMIZER = "tension-optimizer",
  AUDIENCE_RESONANCE = "audience-resonance",
  PLATFORM_ADAPTER = "platform-adapter",

  // Advanced specialized modules
  CHARACTER_DEEP_ANALYZER = "character-deep-analyzer",
  DIALOGUE_ADVANCED_ANALYZER = "dialogue-advanced-analyzer",
  VISUAL_CINEMATIC_ANALYZER = "visual-cinematic-analyzer",
  THEMES_MESSAGES_ANALYZER = "themes-messages-analyzer",
  CULTURAL_HISTORICAL_ANALYZER = "cultural-historical-analyzer",
  PRODUCIBILITY_ANALYZER = "producibility-analyzer",
  TARGET_AUDIENCE_ANALYZER = "target-audience-analyzer",
  LITERARY_QUALITY_ANALYZER = "literary-quality-analyzer",
  RECOMMENDATIONS_GENERATOR = "recommendations-generator",

  // Additional task types for compatibility
  SUMMARIZE = "summarize",
  ANALYZE_CHARACTERS = "analyze-characters",
  CREATIVE_WRITING = "creative-writing",
  PLOT_PREDICTION = "plot-prediction",
  THEMATIC_ANALYSIS = "thematic-analysis",
  STYLE_ANALYSIS = "style-analysis",
  SCENE_GENERATION = "scene-generation",
  WORLDBUILDING = "worldbuilding",
  TENSION_ANALYSIS = "tension-analysis",
  ADAPTATION = "adaptation",
  VISUAL_ANALYSIS = "visual-analysis",
  THEME_MESSAGE_ANALYSIS = "theme-message-analysis",
  RECOMMENDATION = "recommendation",

  // Additional missing task types
  AUDIENCE_ANALYSIS = "audience-analysis",
  TEXT_COMPLETION = "text-completion",
  COMPREHENSIVE_ANALYSIS = "comprehensive-analysis",
  CHARACTER_ANALYSIS = "character-analysis",
}

/**
 * @enum {string} TaskCategory
 * @description Categorizes agents into broad functional groups.
 * This helps in organizing and presenting agents to the user.
 */
export const enum TaskCategory {
  CORE = "CORE",
  ANALYSIS = "ANALYSIS",
  ANALYSES = "ANALYSES",
  AGENTS = "AGENTS",
  CREATIVE = "CREATIVE",
  PREDICTIVE = "PREDICTIVE",
  ADVANCED_MODULES = "ADVANCED_MODULES",
  EVALUATION = "EVALUATION",
  GENERATION = "GENERATION",
  INTEGRATION = "INTEGRATION",
}

/**
 * @interface CompletionEnhancementOption
 * @description Defines the structure for an option that can enhance a completion task.
 * @property {TaskType} id - The unique identifier for the enhancement task.
 * @property {string} label - The user-facing label for the enhancement option.
 */
export interface CompletionEnhancementOption {
  id: TaskType;
  label: string;
}

/**
 * @interface AIAgentConfig
 * @description Provides a comprehensive configuration for an AI agent.
 * This interface details everything from the agent's identity and capabilities to its operational parameters.
 * @property {TaskType} id - The unique identifier for the agent, linking it to a specific task.
 * @property {string} name - The user-friendly name of the agent.
 * @property {string} description - A detailed description of the agent's purpose and functionality.
 * @property {TaskCategory} category - The category the agent belongs to.
 * @property {object} capabilities - A detailed object outlining the agent's technical and cognitive abilities.
 * @property {TaskType[]} collaboratesWith - A list of other agents this agent can collaborate with.
 * @property {TaskType[]} dependsOn - A list of agents whose output is required before this agent can run.
 * @property {TaskType[]} enhances - A list of agents that this agent can enhance.
 * @property {string} systemPrompt - The base instruction or persona given to the AI model.
 * @property {any[]} fewShotExamples - Examples provided to the model to guide its responses.
 * @property {string} chainOfThoughtTemplate - A template for structured, multi-step reasoning.
 * @property {string} cacheStrategy - The caching mechanism to use for the agent's responses.
 * @property {boolean} parallelizable - Indicates if the agent can be run in parallel with others.
 * @property {boolean} batchProcessing - Indicates if the agent supports processing multiple inputs at once.
 * @property {string[]} validationRules - Rules for validating the agent's output.
 * @property {any} outputSchema - The expected schema of the agent's output.
 * @property {number} confidenceThreshold - The minimum confidence level required for the agent to return a result.
 */
export interface AIAgentConfig {
  id?: string;
  name: string;
  description: string;
  category: TaskCategory | string;
  taskType?: TaskType;
  instructions?: string;
  capabilities?: string[] | Record<string, boolean | string | number>;
  collaboratesWith?: TaskType[];
  dependsOn?: TaskType[];
  enhances?: TaskType[];
  modelConfig?: {
    temperature?: number;
    maxTokens?: number;
    topP?: number;
    frequencyPenalty?: number;
    presencePenalty?: number;
  };
  systemPrompt?: string;
  userPrompt?: string;
  expectedOutput?: string;
  processingInstructions?: string;
  qualityGates?: string[];
  fallbackBehavior?: string;
  confidenceThreshold?: number;
  fewShotExamples?: any[];
  chainOfThoughtTemplate?: string;
  cacheStrategy?: string;
  parallelizable?: boolean;
  batchProcessing?: boolean;
  validationRules?: string[];
  outputSchema?: any;
}

/**
 * Represents a single spoken or parenthetical line in the structured screenplay model.
 */
export interface DialogueLine {
  /** Unique identifier generated for tracking the dialogue line. */
  id: string;
  /** Character name associated with the line. */
  character: string;
  /** Raw text content of the line. */
  text: string;
  /** One-based index of the line within the original script. */
  lineNumber: number;
  /** Identifier of the scene that contains this line. */
  sceneId: string;
  /**
   * Type of dialogue line captured.
   * `dialogue` denotes spoken text whereas `parenthetical` stores inline directions.
   */
  type: "dialogue" | "parenthetical";
}

/**
 * Captures metadata for a screenplay character and their dialogue footprint.
 */
export interface Character {
  /** Canonical character name. */
  name: string;
  /** Total number of dialogue lines attributed to the character. */
  dialogueCount: number;
  /** Detailed list of dialogue entries spoken by the character. */
  dialogueLines: DialogueLine[];
  /** Identifier of the first scene where the character appears. */
  firstSceneId?: string;
}

/**
 * Stores action lines within a scene with their original ordering preserved.
 */
export interface SceneActionLine {
  /** Original text for the action or description line. */
  text: string;
  /** One-based index within the screenplay. */
  lineNumber: number;
}

/**
 * Represents a processed file for agent input
 */
export interface ProcessedFile {
  name: string;
  content: string;
  mimeType: string;
  isBase64: boolean;
  size: number;
}

/**
 * AI Writing Assistant interface for compatibility
 */
export interface AIWritingAssistantLike {
  generateText(
    prompt: string,
    context: string,
    options?: any
  ): Promise<{ text?: string }>;
}

/**
 * Represents a structured screenplay scene extracted from free-form text.
 */
export interface Scene {
  /** Stable identifier for the scene. */
  id: string;
  /** Normalized heading text (e.g. "مشهد 1"). */
  heading: string;
  /** Zero-based scene position within the screenplay. */
  index: number;
  /** One-based line number where the scene begins. */
  startLineNumber: number;
  /** One-based line number where the scene ends. */
  endLineNumber?: number;
  /** Ordered list of raw lines included in the scene. */
  lines: string[];
  /** Spoken and parenthetical dialogue entries contained in the scene. */
  dialogues: DialogueLine[];
  /** Descriptive or action-oriented lines associated with the scene. */
  actionLines: SceneActionLine[];
}

/**
 * Root data model describing a structured screenplay document.
 */
export interface Script {
  /** Original screenplay text provided by the user. */
  rawText: string;
  /** Total number of lines in the screenplay. */
  totalLines: number;
  /** Ordered collection of structured scenes. */
  scenes: Scene[];
  /** Aggregated character information keyed by character name. */
  characters: Record<string, Character>;
  /** Flat list of all dialogue lines for quick inspection. */
  dialogueLines: DialogueLine[];
}

/**
 * Content sanitization utilities for security
 */

import DOMPurify from "dompurify";

/**
 * Sanitize HTML content to prevent XSS attacks
 */
export function sanitizeHTML(dirty: string): string {
  return DOMPurify.sanitize(dirty, {
    ALLOWED_TAGS: ["p", "div", "span", "br", "strong", "em", "u"],
    ALLOWED_ATTR: ["class", "style", "dir"],
    KEEP_CONTENT: true,
    RETURN_DOM: false,
    RETURN_DOM_FRAGMENT: false,
  });
}

/**
 * Sanitize text content for contenteditable elements
 */
export function sanitizeContentEditable(content: string): string {
  // Remove potentially dangerous elements while preserving Arabic text
  const cleaned = DOMPurify.sanitize(content, {
    ALLOWED_TAGS: ["div", "p", "br", "span"],
    ALLOWED_ATTR: ["class", "style", "dir"],
    FORBID_TAGS: ["script", "object", "embed", "link", "style", "meta"],
    FORBID_ATTR: ["onclick", "onload", "onerror", "onmouseover"],
  });

  return cleaned;
}

/**
 * Validate and sanitize user input
 */
export function sanitizeUserInput(input: string): string {
  if (!input || typeof input !== "string") {
    return "";
  }

  // Remove null bytes and control characters except newlines and tabs
  let cleaned = input.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "");

  // Limit length to prevent DoS
  if (cleaned.length > 100000) {
    cleaned = cleaned.substring(0, 100000);
  }

  return cleaned.trim();
}

/**
 * Sanitize filename for safe file operations
 */
export function sanitizeFilename(filename: string): string {
  if (!filename) return "untitled";

  // Remove dangerous characters
  return (
    filename
      .replace(/[<>:"/\\|?*\x00-\x1f]/g, "")
      .replace(/^\.+/, "")
      .substring(0, 255)
      .trim() || "untitled"
  );
}

/**
 * Content Security Policy configuration
 */
export const CSP_CONFIG = {
  "default-src": "'self'",
  "script-src": "'self'",
  "style-src": "'self' fonts.googleapis.com",
  "font-src": "'self' fonts.gstatic.com",
  "img-src": "'self' data: blob:",
  "connect-src": "'self' generativelanguage.googleapis.com",
  "frame-src": "'none'",
  "object-src": "'none'",
  "base-uri": "'self'",
  "form-action": "'self'",
};

/**
 * Generate CSP header string
 */
export function generateCSPHeader(): string {
  return Object.entries(CSP_CONFIG)
    .map(([directive, value]) => `${directive} ${value}`)
    .join("; ");
}

/**
 * Web Worker for particle generation
 * Offloads heavy SDF calculations and particle generation from main thread
 */

interface GenerateParticlesMessage {
  type: "generate";
  config: {
    numParticles: number;
    thickness: number;
    minX: number;
    maxX: number;
    minY: number;
    maxY: number;
    maxAttempts: number;
    batchSize: number;
  };
}

interface ParticleGenerationResult {
  type: "progress" | "complete" | "error";
  positions?: Float32Array;
  colors?: Float32Array;
  count?: number;
  originalPositions?: Float32Array;
  phases?: Float32Array;
  velocities?: Float32Array;
  progress?: number;
  error?: string;
}

// Utility function
const clamp = (value: number, min: number, max: number) => {
  return Math.max(min, Math.min(max, value));
};

// ====== SDF Functions ======

const sdBox = (
  px: number,
  py: number,
  bx: number,
  by: number,
  r: number
): number => {
  const dx = Math.abs(px) - bx;
  const dy = Math.abs(py) - by;
  return (
    Math.sqrt(Math.max(dx, 0) ** 2 + Math.max(dy, 0) ** 2) +
    Math.min(Math.max(dx, dy), 0) -
    r
  );
};

const sdCircle = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number
): number => {
  return Math.hypot(px - cx, py - cy) - r;
};

const sdRing = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  thickness: number
): number => {
  return Math.abs(sdCircle(px, py, cx, cy, r)) - thickness;
};

const sdSegment = (
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number
): number => {
  const pax = px - ax;
  const pay = py - ay;
  const bax = bx - ax;
  const bay = by - ay;
  const h = clamp((pax * bax + pay * bay) / (bax * bax + bay * bay), 0, 1);
  const dx = pax - bax * h;
  const dy = pay - bay * h;
  return Math.sqrt(dx * dx + dy * dy) - r;
};

const sdArc = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  endAngle: number,
  thickness: number
): number => {
  const dx = px - cx;
  const dy = py - cy;
  const angle = Math.atan2(dy, dx);

  let normAngle = angle;
  while (normAngle < startAngle) normAngle += Math.PI * 2;
  while (normAngle > endAngle + Math.PI * 2) normAngle -= Math.PI * 2;

  const clampedAngle = clamp(normAngle, startAngle, endAngle);
  const targetX = cx + Math.cos(clampedAngle) * r;
  const targetY = cy + Math.sin(clampedAngle) * r;

  return Math.hypot(px - targetX, py - targetY) - thickness;
};

// SDF boolean operations
const opUnion = (a: number, b: number): number => Math.min(a, b);
const opSubtract = (a: number, b: number): number => Math.max(a, -b);

// Character definitions
const STROKE_WIDTH = 0.035;
const BASELINE = 0.0;
const X_HEIGHT = 0.35;
const ASCENDER_HEIGHT = 0.65;
const DESCENDER_DEPTH = -0.25;
const ARABIC_HEIGHT = 0.45;

// Letters SDF definitions
const dist_t = (px: number, py: number): number => {
  const x = -1.7;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT - 0.05,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const crossbar = sdSegment(
    px,
    py,
    x - 0.15,
    BASELINE + ASCENDER_HEIGHT,
    x + 0.15,
    BASELINE + ASCENDER_HEIGHT,
    STROKE_WIDTH
  );
  return opUnion(stem, crossbar);
};

const dist_h = (px: number, py: number): number => {
  const x = -1.25;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const shoulder = sdArc(
    px,
    py,
    x,
    BASELINE + X_HEIGHT * 0.8,
    0.22,
    -Math.PI / 2,
    0,
    STROKE_WIDTH
  );
  const rightLeg = sdSegment(
    px,
    py,
    x + 0.22,
    BASELINE + X_HEIGHT * 0.8,
    x + 0.22,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, shoulder), rightLeg);
};

const dist_e = (px: number, py: number): number => {
  const cx = -0.6;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  let ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  ring = opSubtract(ring, cutBox);
  const bar = sdSegment(px, py, cx - r, cy, cx + r * 0.7, cy, STROKE_WIDTH);
  return opUnion(ring, bar);
};

const dist_c = (px: number, py: number): number => {
  const cx = 0.0;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  let ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  return opSubtract(ring, cutBox);
};

const dist_o = (px: number, py: number): number => {
  const cx = 0.5;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  return sdRing(px, py, cx, cy, r, STROKE_WIDTH);
};

const dist_p = (px: number, py: number): number => {
  const x = 1.0;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + X_HEIGHT,
    x,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  const bowl = sdRing(px, py, x + 0.2, cy, 0.17, STROKE_WIDTH);
  return opUnion(stem, bowl);
};

const dist_y = (px: number, py: number): number => {
  const x = 1.9;
  const top = BASELINE + X_HEIGHT;
  const mid = BASELINE + X_HEIGHT * 0.2;
  const leftArm = sdSegment(px, py, x - 0.15, top, x, mid, STROKE_WIDTH);
  const rightArm = sdSegment(px, py, x + 0.15, top, x, mid, STROKE_WIDTH);
  const descender = sdSegment(
    px,
    py,
    x,
    mid,
    x + 0.05,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  return opUnion(opUnion(leftArm, rightArm), descender);
};

const dist_dash = (px: number, py: number): number => {
  const x = 2.4;
  return sdSegment(
    px,
    py,
    x - 0.1,
    BASELINE + X_HEIGHT * 0.5,
    x + 0.1,
    BASELINE + X_HEIGHT * 0.5,
    STROKE_WIDTH * 0.8
  );
};

const dist_alef = (px: number, py: number): number => {
  const x = 2.9;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE,
    STROKE_WIDTH * 1.2
  );
  const base = sdSegment(
    px,
    py,
    x - 0.03,
    BASELINE,
    x + 0.03,
    BASELINE,
    STROKE_WIDTH * 1.5
  );
  return opUnion(stem, base);
};

const dist_lam = (px: number, py: number): number => {
  const x = 3.3;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE + 0.08,
    STROKE_WIDTH * 1.2
  );
  const hook = sdArc(
    px,
    py,
    x - 0.12,
    BASELINE + 0.08,
    0.12,
    0,
    Math.PI / 2,
    STROKE_WIDTH * 1.1
  );
  const hookEnd = sdSegment(
    px,
    py,
    x - 0.24,
    BASELINE,
    x - 0.15,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, hook), hookEnd);
};

const dist_noon = (px: number, py: number): number => {
  const x = 3.75;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.18,
    -Math.PI * 0.15,
    Math.PI * 0.85,
    STROKE_WIDTH * 1.1
  );
  const connector = sdSegment(
    px,
    py,
    x - 0.17,
    cy - 0.05,
    x - 0.08,
    BASELINE + 0.02,
    STROKE_WIDTH
  );
  const base = sdSegment(
    px,
    py,
    x - 0.08,
    BASELINE + 0.02,
    x + 0.1,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);
  return opUnion(opUnion(opUnion(mainArc, connector), base), dot);
};

const dist_seen = (px: number, py: number): number => {
  const x = 4.25;
  const baseY = BASELINE + 0.02;
  const toothHeight = ARABIC_HEIGHT * 0.35;
  const baseLine = sdSegment(
    px,
    py,
    x - 0.28,
    baseY,
    x + 0.28,
    baseY,
    STROKE_WIDTH * 1.1
  );
  const tooth1 = sdArc(
    px,
    py,
    x - 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth2 = sdArc(
    px,
    py,
    x,
    baseY + toothHeight * 0.8,
    0.12,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth3 = sdArc(
    px,
    py,
    x + 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const connect1 = sdSegment(
    px,
    py,
    x - 0.18,
    baseY,
    x - 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  const connect2 = sdSegment(
    px,
    py,
    x,
    baseY,
    x,
    baseY + toothHeight * 0.7,
    STROKE_WIDTH * 0.8
  );
  const connect3 = sdSegment(
    px,
    py,
    x + 0.18,
    baseY,
    x + 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  return opUnion(
    opUnion(
      opUnion(
        opUnion(opUnion(opUnion(baseLine, tooth1), tooth2), tooth3),
        connect1
      ),
      connect2
    ),
    connect3
  );
};

const dist_khaa = (px: number, py: number): number => {
  const x = 4.75;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.2,
    Math.PI * 0.6,
    Math.PI * 2.4,
    STROKE_WIDTH * 1.1
  );
  const rightConnect = sdSegment(
    px,
    py,
    x + 0.15,
    cy - 0.12,
    x + 0.12,
    BASELINE,
    STROKE_WIDTH
  );
  const leftConnect = sdSegment(
    px,
    py,
    x - 0.15,
    cy - 0.12,
    x - 0.08,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);
  return opUnion(opUnion(opUnion(mainArc, rightConnect), leftConnect), dot);
};

const dist_taa_marbouta = (px: number, py: number): number => {
  const x = 5.2;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  let circle = sdRing(px, py, x, cy, 0.17, STROKE_WIDTH * 1.1);
  const opening = sdBox(px - x, py - (cy - 0.05), 0.08, 0.08, 0);
  circle = opSubtract(circle, opening);
  const dot1 = sdCircle(px, py, x - 0.07, cy + 0.28, 0.03);
  const dot2 = sdCircle(px, py, x + 0.07, cy + 0.28, 0.03);
  return opUnion(opUnion(circle, dot1), dot2);
};

// Combine all letters
const dist_all = (px: number, py: number): number => {
  return Math.min(
    dist_t(px, py),
    dist_h(px, py),
    dist_e(px, py),
    dist_c(px, py),
    dist_o(px, py),
    dist_p(px, py),
    dist_y(px, py),
    dist_dash(px, py),
    dist_alef(px, py),
    dist_lam(px, py),
    dist_noon(px, py),
    dist_seen(px, py),
    dist_khaa(px, py),
    dist_taa_marbouta(px, py)
  );
};

// ====== Particle Generation Logic ======

function generateParticles(config: GenerateParticlesMessage["config"]) {
  const { numParticles, thickness, minX, maxX, minY, maxY, maxAttempts } =
    config;

  const positions = new Float32Array(numParticles * 3);
  const colors = new Float32Array(numParticles * 3);

  let generatedCount = 0;
  let attempts = 0;
  let lastProgressReport = 0;

  while (generatedCount < numParticles && attempts < maxAttempts) {
    attempts++;

    const x = Math.random() * (maxX - minX) + minX;
    const y = Math.random() * (maxY - minY) + minY;
    const z = Math.random() * thickness - thickness / 2;

    const d = dist_all(x, y);
    const threshold = x > 2.5 ? 0.015 : 0.01;

    if (d <= threshold) {
      const idx = generatedCount * 3;
      positions[idx] = x;
      positions[idx + 1] = y;
      positions[idx + 2] = z;
      colors[idx] = 1;
      colors[idx + 1] = 1;
      colors[idx + 2] = 1;
      generatedCount++;

      // Report progress every 10%
      const progress = (generatedCount / numParticles) * 100;
      if (progress - lastProgressReport >= 10) {
        lastProgressReport = progress;
        self.postMessage({
          type: "progress",
          progress,
          count: generatedCount,
        } as ParticleGenerationResult);
      }
    }
  }

  // Fallback if not enough particles generated
  if (generatedCount < 200) {
    const fallbackCount = Math.min(numParticles, 3000);
    for (let j = 0; j < fallbackCount; j++) {
      const idx = j * 3;
      positions[idx] = (Math.random() - 0.5) * 6;
      positions[idx + 1] = (Math.random() - 0.5) * 3.5;
      positions[idx + 2] = (Math.random() - 0.5) * 0.3;
      colors[idx] = 1;
      colors[idx + 1] = 1;
      colors[idx + 2] = 1;
    }
    generatedCount = fallbackCount;
  }

  // Create final arrays
  const finalPositions = positions.slice(0, generatedCount * 3);
  const finalColors = colors.slice(0, generatedCount * 3);
  const originalPositions = positions.slice(0, generatedCount * 3);
  const phases = new Float32Array(generatedCount);
  const velocities = new Float32Array(generatedCount * 3);

  for (let j = 0; j < generatedCount; j++) {
    phases[j] = Math.random() * Math.PI * 2;
  }

  return {
    positions: finalPositions,
    colors: finalColors,
    count: generatedCount,
    originalPositions,
    phases,
    velocities,
  };
}

// ====== Worker Message Handler ======

function isTrustedWorkerMessage(event: MessageEvent<unknown>): boolean {
  return event.origin === "" || event.origin === self.location.origin;
}

self.addEventListener(
  "message",
  (event: MessageEvent<GenerateParticlesMessage>) => {
    if (!isTrustedWorkerMessage(event)) {
      return;
    }

    const { type, config } = event.data;

    if (type === "generate") {
      try {
        const result = generateParticles(config);

        self.postMessage(
          {
            type: "complete",
            ...result,
          } as ParticleGenerationResult,
          {
            transfer: [
              result.positions.buffer,
              result.colors.buffer,
              result.originalPositions.buffer,
              result.phases.buffer,
              result.velocities.buffer,
            ],
          }
        );
      } catch (error) {
        self.postMessage({
          type: "error",
          error: error instanceof Error ? error.message : "Unknown error",
        } as ParticleGenerationResult);
      }
    }
  }
);

export {};

/**
 * Web Worker for particle physics calculations
 * Offloads position, velocity, and color calculations from main thread
 */

interface ParticlePosition {
  px: number;
  py: number;
  pz: number;
}

interface ParticleVelocity {
  vx: number;
  vy: number;
  vz: number;
}

interface EffectConfig {
  effectRadius: number;
  repelStrength: number;
}

type Effect = "default" | "spark" | "wave" | "vortex";

interface UpdateParticlesMessage {
  type: "update";
  positions: Float32Array;
  velocities: Float32Array;
  originalPositions: Float32Array;
  colors: Float32Array;
  particleCount: number;
  config: {
    effect: Effect;
    effectRadius: number;
    repelStrength: number;
    attractStrength: number;
    damping: number;
    intersectionPoint: { x: number; y: number; z: number } | null;
    time: number;
  };
}

interface UpdateParticlesResult {
  type: "updated" | "error";
  positions?: Float32Array;
  velocities?: Float32Array;
  colors?: Float32Array;
  error?: string;
}

// ====== Physics Functions ======

function applySparkEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;

  if (distSq < config.effectRadius * config.effectRadius && distSq > 0.0001) {
    const dist = Math.sqrt(distSq);
    const force = (1 - dist / config.effectRadius) * config.repelStrength * 3;
    return {
      vx: velocity.vx + (dx / dist) * force,
      vy: velocity.vy + (dy / dist) * force,
      vz: velocity.vz + (dz / dist) * force,
    };
  }

  return velocity;
}

function applyWaveEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig,
  time: number
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;

  if (distSq < config.effectRadius * config.effectRadius) {
    const dist = Math.sqrt(distSq);
    const wavePhase = time * 8 - dist * 12;
    const waveStrength = 0.12;
    const waveForce =
      Math.sin(wavePhase) * waveStrength * (1 - dist / config.effectRadius);
    if (dist > 0.001) {
      return {
        vx: velocity.vx + (dx / dist) * waveForce,
        vy: velocity.vy + (dy / dist) * waveForce,
        vz: velocity.vz + waveForce * 0.5,
      };
    }
  }

  return velocity;
}

function applyVortexEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < config.effectRadius * config.effectRadius && dist > 0.05) {
    const vortexStrength = 0.15;
    const spiralForce = vortexStrength * (1 - dist / config.effectRadius);

    const tangentX = -dy;
    const tangentY = dx;
    const tangentLength = Math.sqrt(tangentX * tangentX + tangentY * tangentY);

    let newVx = velocity.vx;
    let newVy = velocity.vy;

    if (tangentLength > 0.001) {
      newVx += (tangentX / tangentLength) * spiralForce;
      newVy += (tangentY / tangentLength) * spiralForce;
    }

    const pullStrength = spiralForce * 0.3;
    newVx -= (dx / dist) * pullStrength;
    newVy -= (dy / dist) * pullStrength;

    return {
      vx: newVx,
      vy: newVy,
      vz: velocity.vz,
    };
  }

  return velocity;
}

function applyDefaultEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < config.effectRadius * config.effectRadius && distSq > 0.0001) {
    const force = (1 - dist / config.effectRadius) * config.repelStrength;
    return {
      vx: velocity.vx + (dx / dist) * force,
      vy: velocity.vy + (dy / dist) * force,
      vz: velocity.vz + (dz / dist) * force,
    };
  }

  return velocity;
}

function applyParticleEffect(
  effect: Effect,
  position: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig,
  time: number
): ParticleVelocity {
  switch (effect) {
    case "spark":
      return applySparkEffect(position, intersection, velocity, config);
    case "wave":
      return applyWaveEffect(position, intersection, velocity, config, time);
    case "vortex":
      return applyVortexEffect(position, intersection, velocity, config);
    case "default":
      return applyDefaultEffect(position, intersection, velocity, config);
  }
}

function applyAttraction(
  position: ParticlePosition,
  target: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  attractStrength: number
): ParticleVelocity {
  return {
    vx: velocity.vx + (target.x - position.px) * attractStrength,
    vy: velocity.vy + (target.y - position.py) * attractStrength,
    vz: velocity.vz + (target.z - position.pz) * attractStrength,
  };
}

function applyDamping(
  velocity: ParticleVelocity,
  damping: number
): ParticleVelocity {
  return {
    vx: velocity.vx * damping,
    vy: velocity.vy * damping,
    vz: velocity.vz * damping,
  };
}

function updatePosition(
  position: ParticlePosition,
  velocity: ParticleVelocity
): ParticlePosition {
  return {
    px: position.px + velocity.vx,
    py: position.py + velocity.vy,
    pz: position.pz + velocity.vz,
  };
}

// ====== Color Calculation Functions ======

function calculateWaveColor(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < effectRadius * effectRadius) {
    const wavePhase = time * 8 - dist * 15;
    const intensity =
      Math.abs(Math.sin(wavePhase)) * (1 - dist / effectRadius) + 1;
    return {
      r: intensity * 0.5 + 0.8,
      g: intensity * 0.8 + 0.6,
      b: intensity * 1.2 + 0.4,
    };
  }

  return { r: 1, g: 1, b: 1 };
}

function calculateVortexColor(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < effectRadius * effectRadius) {
    const angle = Math.atan2(dy, dx) + time * 5;
    const intensity = (1 - dist / effectRadius) * 2 + 1;
    return {
      r: (Math.sin(angle) * 0.5 + 0.5) * intensity,
      g: (Math.sin(angle + (Math.PI * 2) / 3) * 0.5 + 0.5) * intensity,
      b: (Math.sin(angle + (Math.PI * 4) / 3) * 0.5 + 0.5) * intensity,
    };
  }

  return { r: 1, g: 1, b: 1 };
}

function calculateParticleColor(
  effect: Effect,
  position: ParticlePosition,
  intersection: { x: number; y: number; z: number } | null,
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  if (!intersection) {
    return { r: 1, g: 1, b: 1 };
  }

  if (effect === "wave") {
    return calculateWaveColor(position, intersection, effectRadius, time);
  }
  if (effect === "vortex") {
    return calculateVortexColor(position, intersection, effectRadius, time);
  }

  return { r: 1, g: 1, b: 1 };
}

// ====== Main Update Function ======

function updateParticles(message: UpdateParticlesMessage) {
  const {
    positions,
    velocities,
    originalPositions,
    colors,
    particleCount,
    config,
  } = message;

  const {
    effect,
    effectRadius,
    repelStrength,
    attractStrength,
    damping,
    intersectionPoint,
    time,
  } = config;

  const effectConfig: EffectConfig = {
    effectRadius,
    repelStrength,
  };

  // Process all particles
  for (let j = 0; j < particleCount; j++) {
    const idx = j * 3;

    // Get current position
    const position: ParticlePosition = {
      px: positions[idx] ?? 0,
      py: positions[idx + 1] ?? 0,
      pz: positions[idx + 2] ?? 0,
    };

    // Get target (original) position
    const target = {
      x: originalPositions[idx] ?? 0,
      y: originalPositions[idx + 1] ?? 0,
      z: originalPositions[idx + 2] ?? 0,
    };

    // Get current velocity
    let velocity: ParticleVelocity = {
      vx: velocities[idx] ?? 0,
      vy: velocities[idx + 1] ?? 0,
      vz: velocities[idx + 2] ?? 0,
    };

    // Apply effect if mouse is hovering
    if (intersectionPoint) {
      velocity = applyParticleEffect(
        effect,
        position,
        intersectionPoint,
        velocity,
        effectConfig,
        time
      );
    }

    // Attract back to original position
    velocity = applyAttraction(position, target, velocity, attractStrength);
    velocity = applyDamping(velocity, damping);

    // Update position
    const newPos = updatePosition(position, velocity);
    positions[idx] = newPos.px;
    positions[idx + 1] = newPos.py;
    positions[idx + 2] = newPos.pz;

    // Update velocity
    velocities[idx] = velocity.vx;
    velocities[idx + 1] = velocity.vy;
    velocities[idx + 2] = velocity.vz;

    // Calculate and apply color
    const color = calculateParticleColor(
      effect,
      newPos,
      intersectionPoint,
      effectRadius,
      time
    );
    colors[idx] = color.r;
    colors[idx + 1] = color.g;
    colors[idx + 2] = color.b;
  }

  return {
    positions,
    velocities,
    colors,
  };
}

// ====== Worker Message Handler ======

function isTrustedWorkerMessage(event: MessageEvent<unknown>): boolean {
  return event.origin === "" || event.origin === self.location.origin;
}

self.addEventListener(
  "message",
  (event: MessageEvent<UpdateParticlesMessage>) => {
    if (!isTrustedWorkerMessage(event)) {
      return;
    }

    const { type } = event.data;

    if (type === "update") {
      try {
        const result = updateParticles(event.data);

        self.postMessage(
          {
            type: "updated",
            ...result,
          } as UpdateParticlesResult,
          {
            transfer: [
              result.positions.buffer,
              result.velocities.buffer,
              result.colors.buffer,
            ],
          }
        );
      } catch (error) {
        self.postMessage({
          type: "error",
          error: error instanceof Error ? error.message : "Unknown error",
        } as UpdateParticlesResult);
      }
    }
  }
);

